INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1, 'quran:1:1', 'quran', 'quran', '1:1', 1, 0, 'Al-Fatihah', 'الفاتحة', 'بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ', NULL, NULL, 'بسم الله الرحمن الرحيم', 'بسم له رحمن رحيم', 'quran', NULL, NULL, 'https://quran.com/1/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1, 'بسم الل لله الر لرح رحم حمن الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2, 'quran:1:2', 'quran', 'quran', '1:2', 2, 1, 'Al-Fatihah', 'الفاتحة', 'ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'الحمد لله رب العلمين', 'حمد لل رب علم', 'quran', NULL, NULL, 'https://quran.com/1/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2, 'الح لحم حمد لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (3, 'quran:1:3', 'quran', 'quran', '1:3', 3, 2, 'Al-Fatihah', 'الفاتحة', 'ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ', NULL, NULL, 'الرحمن الرحيم', 'رحمن رحيم', 'quran', NULL, NULL, 'https://quran.com/1/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (3, 'الر لرح رحم حمن الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (4, 'quran:1:4', 'quran', 'quran', '1:4', 4, 3, 'Al-Fatihah', 'الفاتحة', 'مَٰلِكِ يَوۡمِ ٱلدِّينِ', NULL, NULL, 'ملك يوم الدين', 'ملك يوم دين', 'quran', NULL, NULL, 'https://quran.com/1/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (4, 'ملك يوم الد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (5, 'quran:1:5', 'quran', 'quran', '1:5', 5, 4, 'Al-Fatihah', 'الفاتحة', 'إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ', NULL, NULL, 'اياك نعبد واياك نستعين', 'ايك نعبد ايك نستع', 'quran', NULL, NULL, 'https://quran.com/1/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (5, 'ايك نعب عبد ويك نست ستع تعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (6, 'quran:1:6', 'quran', 'quran', '1:6', 6, 5, 'Al-Fatihah', 'الفاتحة', 'ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ', NULL, NULL, 'اهدنا الصرط المستقيم', 'اهد صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/1/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (6, 'اهد هدن الص لصر صرط الم لمس مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (7, 'quran:1:7', 'quran', 'quran', '1:7', 7, 6, 'Al-Fatihah', 'الفاتحة', 'صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ', NULL, NULL, 'صرط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين', 'صرط ذين انعمت علي غير مغضوب علي ول ضل', 'quran', NULL, NULL, 'https://quran.com/1/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (7, 'صرط الذ لذي ذين انع نعم عمت علي ليه يهم غير الم لمغ مغض غضو ضوب علي ليه يهم ول الض لضل ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (8, 'quran:2:1', 'quran', 'quran', '2:1', 1, 7, 'Al-Baqarah', 'البقرة', 'الٓمٓ', NULL, NULL, 'الم', 'الم', 'quran', NULL, NULL, 'https://quran.com/2/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (8, 'الم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (9, 'quran:2:2', 'quran', 'quran', '2:2', 2, 8, 'Al-Baqarah', 'البقرة', 'ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ', NULL, NULL, 'ذلك الكتب لا ريب فيه هدي للمتقين', 'ذلك كتب ل ريب في هد متق', 'quran', NULL, NULL, 'https://quran.com/2/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (9, 'ذلك الك لكت كتب ل ريب فيه هدي للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (10, 'quran:2:3', 'quran', 'quran', '2:3', 3, 9, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ', NULL, NULL, 'الذين يومنون بالغيب ويقيمون الصلاه ومما رزقنهم ينفقون', 'ذين يومن غيب يقيم صل مم رزقن ينفق', 'quran', NULL, NULL, 'https://quran.com/2/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (10, 'الذ لذي ذين يوم ومن منو نون بلغ لغي غيب ويق يقي قيم يمو مون الص لصل صله ومم رزق زقن قنه نهم ينف نفق فقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (11, 'quran:2:4', 'quran', 'quran', '2:4', 4, 10, 'Al-Baqarah', 'البقرة', 'وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ', NULL, NULL, 'والذين يومنون بما انزل اليك وما انزل من قبلك وبالاخره هم يوقنون', 'ذين يومن بم انزل يك وم انزل من قبلك اخر هم يوقن', 'quran', NULL, NULL, 'https://quran.com/2/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (11, 'ولذ لذي ذين يوم ومن منو نون بم انز نزل الي ليك وم انز نزل من قبل بلك وبل بلخ لخر خره هم يوق وقن قنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (12, 'quran:2:5', 'quran', 'quran', '2:5', 5, 11, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'اوليك علي هدي من ربهم واوليك هم المفلحون', 'اوليك عل هد من رب اوليك هم مفلح', 'quran', NULL, NULL, 'https://quran.com/2/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (12, 'اول ولي ليك علي هدي من ربه بهم وول ولي ليك هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (13, 'quran:2:6', 'quran', 'quran', '2:6', 6, 12, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ', NULL, NULL, 'ان الذين كفروا سواء عليهم انذرتهم ام لم تنذرهم لا يومنون', 'ان ذين كفر سوء علي انذرت ام لم تنذر ل يومن', 'quran', NULL, NULL, 'https://quran.com/2/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (13, 'ان الذ لذي ذين كفر فرو سوء علي ليه يهم انذ نذر ذرت رته تهم ام لم تنذ نذر ذره رهم ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (14, 'quran:2:7', 'quran', 'quran', '2:7', 7, 13, 'Al-Baqarah', 'البقرة', 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ', NULL, NULL, 'ختم الله علي قلوبهم وعلي سمعهم وعلي ابصرهم غشوه ولهم عذاب عظيم', 'ختم له عل قلوب عل سمع عل ابصر غشو لهم عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/2/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (14, 'ختم الل لله علي قلو لوب وبه بهم وعل علي سمع معه عهم وعل علي ابص بصر صره رهم غشو شوه وله لهم عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (15, 'quran:2:8', 'quran', 'quran', '2:8', 8, 14, 'Al-Baqarah', 'البقرة', 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ', NULL, NULL, 'ومن الناس من يقول امنا بالله وباليوم الاخر وما هم بمومنين', 'ومن نس من يقول ام له يوم اخر وم هم بمومن', 'quran', NULL, NULL, 'https://quran.com/2/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (15, 'ومن الن لنس من يقو قول امن بلل لله وبل بلي ليو يوم الخ لخر وم هم بمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (16, 'quran:2:9', 'quran', 'quran', '2:9', 9, 15, 'Al-Baqarah', 'البقرة', 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', NULL, NULL, 'يخدعون الله والذين امنوا وما يخدعون الا انفسهم وما يشعرون', 'يخدع له ذين امن وم يخدع ال انفس وم يشعر', 'quran', NULL, NULL, 'https://quran.com/2/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (16, 'يخد خدع دعو عون الل لله ولذ لذي ذين امن منو وم يخد خدع دعو عون ال انف نفس فسه سهم وم يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (17, 'quran:2:10', 'quran', 'quran', '2:10', 10, 16, 'Al-Baqarah', 'البقرة', 'فِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ', NULL, NULL, 'في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون', 'في قلوب مرض زد له مرض لهم عذب يم بم كن يكذب', 'quran', NULL, NULL, 'https://quran.com/2/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (17, 'في قلو لوب وبه بهم مرض فزد زده دهم الل لله مرض وله لهم عذب الي ليم بم كنو يكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (18, 'quran:2:11', 'quran', 'quran', '2:11', 11, 17, 'Al-Baqarah', 'البقرة', 'وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ', NULL, NULL, 'واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون', 'اذ قيل لهم ل تفسد في ارض قل انم نحن مصلح', 'quran', NULL, NULL, 'https://quran.com/2/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (18, 'وذ قيل لهم ل تفس فسد سدو في الر لرض قلو انم نحن مصل صلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (19, 'quran:2:12', 'quran', 'quran', '2:12', 12, 18, 'Al-Baqarah', 'البقرة', 'أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ', NULL, NULL, 'الا انهم هم المفسدون ولكن لا يشعرون', 'ال ان هم مفسد لكن ل يشعر', 'quran', NULL, NULL, 'https://quran.com/2/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (19, 'ال انه نهم هم الم لمف مفس فسد سدو دون ولك لكن ل يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (20, 'quran:2:13', 'quran', 'quran', '2:13', 13, 19, 'Al-Baqarah', 'البقرة', 'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ', NULL, NULL, 'واذا قيل لهم امنوا كما امن الناس قالوا انومن كما امن السفهاء الا انهم هم السفهاء ولكن لا يعلمون', 'اذ قيل لهم امن كم امن نس قل انومن كم امن سفهء ال ان هم سفهء لكن ل يعلم', 'quran', NULL, NULL, 'https://quran.com/2/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (20, 'وذ قيل لهم امن منو كم امن الن لنس قلو انو نوم ومن كم امن الس لسف سفه فهء ال انه نهم هم الس لسف سفه فهء ولك لكن ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (21, 'quran:2:14', 'quran', 'quran', '2:14', 14, 20, 'Al-Baqarah', 'البقرة', 'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ', NULL, NULL, 'واذا لقوا الذين امنوا قالوا امنا واذا خلوا الي شيطينهم قالوا انا معكم انما نحن مستهزءون', 'اذ لق ذين امن قل ام اذ خل ال شيطين قل ان مع انم نحن مستهزء', 'quran', NULL, NULL, 'https://quran.com/2/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (21, 'وذ لقو الذ لذي ذين امن منو قلو امن وذ خلو الي شيط يطي طين ينه نهم قلو ان معك عكم انم نحن مست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (22, 'quran:2:15', 'quran', 'quran', '2:15', 15, 21, 'Al-Baqarah', 'البقرة', 'ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', NULL, NULL, 'الله يستهزي بهم ويمدهم في طغينهم يعمهون', 'له يستهز بهم يمد في طغين يعمه', 'quran', NULL, NULL, 'https://quran.com/2/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (22, 'الل لله يست سته تهز هزي بهم ويم يمد مده دهم في طغي غين ينه نهم يعم عمه مهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (23, 'quran:2:16', 'quran', 'quran', '2:16', 16, 22, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ', NULL, NULL, 'اوليك الذين اشتروا الضلله بالهدي فما ربحت تجرتهم وما كانوا مهتدين', 'اوليك ذين اشتر ضلل هد فم ربحت تجرت وم كن مهتد', 'quran', NULL, NULL, 'https://quran.com/2/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (23, 'اول ولي ليك الذ لذي ذين اشت شتر ترو الض لضل ضلل لله بله لهد هدي فم ربح بحت تجر جرت رته تهم وم كنو مهت هتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (24, 'quran:2:17', 'quran', 'quran', '2:17', 17, 23, 'Al-Baqarah', 'البقرة', 'مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ', NULL, NULL, 'مثلهم كمثل الذي استوقد نارا فلما اضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمت لا يبصرون', 'مثل كمثل ذي استوقد نر لم اضءت م حول ذهب له بنور ترك في ظلمت ل يبصر', 'quran', NULL, NULL, 'https://quran.com/2/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (24, 'مثل ثله لهم كمث مثل الذ لذي است ستو توق وقد نر فلم اضء ضءت م حول وله ذهب الل لله بنو نور وره رهم وتر ترك ركه كهم في ظلم لمت ل يبص بصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (25, 'quran:2:18', 'quran', 'quran', '2:18', 18, 24, 'Al-Baqarah', 'البقرة', 'صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ', NULL, NULL, 'صم بكم عمي فهم لا يرجعون', 'صم بكم عم فهم ل يرجع', 'quran', NULL, NULL, 'https://quran.com/2/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (25, 'صم بكم عمي فهم ل يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (26, 'quran:2:19', 'quran', 'quran', '2:19', 19, 25, 'Al-Baqarah', 'البقرة', 'أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ', NULL, NULL, 'او كصيب من السماء فيه ظلمت ورعد وبرق يجعلون اصبعهم في اذانهم من الصوعق حذر الموت والله محيط بالكفرين', 'او كصيب من سمء في ظلمت رعد برق يجعل اصبع في اذن من صوعق حذر موت له محيط كفر', 'quran', NULL, NULL, 'https://quran.com/2/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (26, 'او كصي صيب من الس لسم سمء فيه ظلم لمت ورع رعد وبر برق يجع جعل علو لون اصب صبع بعه عهم في اذن ذنه نهم من الص لصو صوع وعق حذر الم لمو موت ولل لله محي حيط بلك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (27, 'quran:2:20', 'quran', 'quran', '2:20', 20, 26, 'Al-Baqarah', 'البقرة', 'يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'يكاد البرق يخطف ابصرهم كلما اضاء لهم مشوا فيه واذا اظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وابصرهم ان الله علي كل شيء قدير', 'يكد برق يخطف ابصر كلم اضء لهم مش في اذ اظلم علي قم ولو شء له لذهب بسمع ابصر ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (27, 'يكد الب لبر برق يخط خطف ابص بصر صره رهم كلم اضء لهم مشو فيه وذ اظل ظلم علي ليه يهم قمو ولو شء الل لله لذه ذهب بسم سمع معه عهم وبص بصر صره رهم ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (28, 'quran:2:21', 'quran', 'quran', '2:21', 21, 27, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ', NULL, NULL, 'يا ايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون', 'ي اي نس اعبد رب ذي خلق ذين من قبل لعل تتق', 'quran', NULL, NULL, 'https://quran.com/2/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (28, 'ي ايه الن لنس اعب عبد بدو ربك بكم الذ لذي خلق لقك قكم ولذ لذي ذين من قبل بلك لكم لعل علك لكم تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (29, 'quran:2:22', 'quran', 'quran', '2:22', 22, 28, 'Al-Baqarah', 'البقرة', 'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'الذي جعل لكم الارض فرشا والسماء بناء وانزل من السماء ماء فاخرج به من الثمرت رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون', 'ذي جعل لكم ارض رش سمء بنء انزل من سمء مء اخرج به من ثمرت رزق لكم فل تجعل لل اندد انتم تعلم', 'quran', NULL, NULL, 'https://quran.com/2/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (29, 'الذ لذي جعل لكم الر لرض فرش ولس لسم سمء بنء ونز نزل من الس لسم سمء مء فخر خرج به من الث لثم ثمر مرت رزق لكم فل تجع جعل علو لله اند ندد ونت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (30, 'quran:2:23', 'quran', 'quran', '2:23', 23, 29, 'Al-Baqarah', 'البقرة', 'وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'وان كنتم في ريب مما نزلنا علي عبدنا فاتوا بسوره من مثله وادعوا شهداءكم من دون الله ان كنتم صدقين', 'ون كنتم في ريب مم نزل عل عبد ات بسور من مثل ادع شهدء من دون له ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/2/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (30, 'ون كنت نتم في ريب مم نزل زلن علي عبد بدن فتو بسو سور وره من مثل ثله ودع دعو شهد هدء دءك ءكم من دون الل لله ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (31, 'quran:2:24', 'quran', 'quran', '2:24', 24, 30, 'Al-Baqarah', 'البقرة', 'فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ', NULL, NULL, 'فان لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجاره اعدت للكفرين', 'فن لم تفعل ولن تفعل اتق نر تي قود نس حجر اعدت كفر', 'quran', NULL, NULL, 'https://quran.com/2/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (31, 'فن لم تفع فعل علو ولن تفع فعل علو فتق تقو الن لنر الت لتي وقو قود وده الن لنس ولح لحج حجر جره اعد عدت للك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (32, 'quran:2:25', 'quran', 'quran', '2:25', 25, 31, 'Al-Baqarah', 'البقرة', 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ رِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ وَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'وبشر الذين امنوا وعملوا الصلحت ان لهم جنت تجري من تحتها الانهر كلما رزقوا منها من ثمره رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشبها ولهم فيها ازوج مطهره وهم فيها خلدون', 'بشر ذين امن عمل صلحت ان لهم جنت تجر من تحت انهر كلم رزق من من ثمر رزق قل هذ ذي رزق من قبل ات به متشب لهم يه ازوج مطهر وهم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (32, 'وبش بشر الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت ان لهم جنت تجر جري من تحت حته الن لنه نهر كلم رزق زقو منه من ثمر مره رزق قلو هذ الذ لذي رزق زقن من قبل وتو به متش تشب شبه وله لهم فيه ازو زوج مطه طهر هره وهم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (33, 'quran:2:26', 'quran', 'quran', '2:26', 26, 32, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ', NULL, NULL, 'ان الله لا يستحي ان يضرب مثلا ما بعوضه فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفسقين', 'ان له ل يستح ان يضرب مثل م بعوض فم وق ام ذين امن يعلم ان حق من رب ام ذين كفر يقول مذ ارد له بهذ مثل يضل به كثير يهد به كثير وم يضل به ال فسق', 'quran', NULL, NULL, 'https://quran.com/2/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (33, 'ان الل لله ل يست ستح تحي ان يضر ضرب مثل م بعو عوض وضه فم فوق وقه فم الذ لذي ذين امن منو فيع يعل علم لمو مون انه الح لحق من ربه بهم وم الذ لذي ذين كفر فرو فيق يقو قول ولو لون مذ ارد الل لله بهذ مثل يضل به كثي ثير ويه يهد هدي به كثي ثير وم يضل به ال الف لفس فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (34, 'quran:2:27', 'quran', 'quran', '2:27', 27, 33, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', NULL, NULL, 'الذين ينقضون عهد الله من بعد ميثقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اوليك هم الخسرون', 'ذين ينقض عهد له من بعد ميثق يقطع م امر له به ان يوصل يفسد في ارض اوليك هم خسر', 'quran', NULL, NULL, 'https://quran.com/2/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (34, 'الذ لذي ذين ينق نقض قضو ضون عهد الل لله من بعد ميث يثق ثقه ويق يقط قطع طعو عون م امر الل لله به ان يوص وصل ويف يفس فسد سدو دون في الر لرض اول ولي ليك هم الخ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (35, 'quran:2:28', 'quran', 'quran', '2:28', 28, 34, 'Al-Baqarah', 'البقرة', 'كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ', NULL, NULL, 'كيف تكفرون بالله وكنتم اموتا فاحيكم ثم يميتكم ثم يحييكم ثم اليه ترجعون', 'كيف تكفر له كنتم اموت احي ثم يميت ثم يحيي ثم يه ترجع', 'quran', NULL, NULL, 'https://quran.com/2/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (35, 'كيف تكف كفر فرو رون بلل لله وكن كنت نتم امو موت فحي حيك يكم ثم يمي ميت يتك تكم ثم يحي حيي ييك يكم ثم الي ليه ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (36, 'quran:2:29', 'quran', 'quran', '2:29', 29, 35, 'Al-Baqarah', 'البقرة', 'هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'هو الذي خلق لكم ما في الارض جميعا ثم استوي الي السماء فسواهن سبع سموت وهو بكل شيء عليم', 'هو ذي خلق لكم م في ارض جميع ثم استو ال سمء سو سبع سموت وهو بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/2/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (36, 'هو الذ لذي خلق لكم م في الر لرض جمي ميع ثم است ستو توي الي الس لسم سمء فسو سوه وهن سبع سمو موت وهو بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (37, 'quran:2:30', 'quran', 'quran', '2:30', 30, 36, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ', NULL, NULL, 'واذ قال ربك للمليكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون', 'وذ قل ربك مليك ان جعل في ارض خليف قل اتجعل يه من يفسد يه يسفك دمء نحن نسبح بحمدك نقدس لك قل ان اعلم م ل تعلم', 'quran', NULL, NULL, 'https://quran.com/2/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (37, 'وذ قل ربك للم لمل ملي ليك يكه اني جعل في الر لرض خلي ليف يفه قلو اتج تجع جعل فيه من يفس فسد فيه ويس يسف سفك الد لدم دمء ونح نحن نسب سبح بحم حمد مدك ونق نقد قدس لك قل اني اعل علم م ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (38, 'quran:2:31', 'quran', 'quran', '2:31', 31, 37, 'Al-Baqarah', 'البقرة', 'وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'وعلم ادم الاسماء كلها ثم عرضهم علي المليكه فقال انبوني باسماء هولاء ان كنتم صدقين', 'علم ادم اسمء كل ثم عرض عل مليك قل انبون بسمء هولء ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/2/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (38, 'وعل علم ادم الس لسم سمء كله ثم عرض رضه ضهم علي الم لمل ملي ليك يكه فقل انب نبو بون وني بسم سمء هول ولء ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (39, 'quran:2:32', 'quran', 'quran', '2:32', 32, 38, 'Al-Baqarah', 'البقرة', 'قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', NULL, NULL, 'قالوا سبحنك لا علم لنا الا ما علمتنا انك انت العليم الحكيم', 'قل سبحنك ل علم لن ال م علمت انك انت عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/2/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (39, 'قلو سبح بحن حنك ل علم لن ال م علم لمت متن انك انت الع لعل علي ليم الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (40, 'quran:2:33', 'quran', 'quran', '2:33', 33, 39, 'Al-Baqarah', 'البقرة', 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ', NULL, NULL, 'قال يا ادم انبيهم باسمايهم فلما انباهم باسمايهم قال الم اقل لكم اني اعلم غيب السموت والارض واعلم ما تبدون وما كنتم تكتمون', 'قل ي ادم انبي بسمي لم انب بسمي قل الم اقل لكم ان اعلم غيب سموت ارض اعلم م تبد وم كنتم تكتم', 'quran', NULL, NULL, 'https://quran.com/2/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (40, 'قل ي ادم انب نبي بيه يهم بسم سمي ميه يهم فلم انب نبه بهم بسم سمي ميه يهم قل الم اقل لكم اني اعل علم غيب الس لسم سمو موت ولر لرض وعل علم م تبد بدو دون وم كنت نتم تكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (41, 'quran:2:34', 'quran', 'quran', '2:34', 34, 40, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'واذ قلنا للمليكه اسجدوا لادم فسجدوا الا ابليس ابي واستكبر وكان من الكفرين', 'وذ قل مليك اسجد لدم سجد ال ابليس اب استكبر كن من كفر', 'quran', NULL, NULL, 'https://quran.com/2/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (41, 'وذ قلن للم لمل ملي ليك يكه اسج سجد جدو لدم فسج سجد جدو ال ابل بلي ليس ابي وست ستك تكب كبر وكن من الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (42, 'quran:2:35', 'quran', 'quran', '2:35', 35, 41, 'Al-Baqarah', 'البقرة', 'وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'وقلنا يا ادم اسكن انت وزوجك الجنه وكلا منها رغدا حيث شيتما ولا تقربا هذه الشجره فتكونا من الظلمين', 'قل ي ادم اسكن انت زوجك جن كل من رغد حيث شيتم ول تقرب هذ شجر تكو من ظلم', 'quran', NULL, NULL, 'https://quran.com/2/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (42, 'وقل قلن ي ادم اسك سكن انت وزو زوج وجك الج لجن جنه وكل منه رغد حيث شيت يتم ول تقر قرب هذه الش لشج شجر جره فتك تكو كون من الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (43, 'quran:2:36', 'quran', 'quran', '2:36', 36, 42, 'Al-Baqarah', 'البقرة', 'فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ', NULL, NULL, 'فازلهما الشيطن عنها فاخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتع الي حين', 'ازلهم شيطن عن اخرجهم مم ك في قل اهبط بعض لبعض عدو لكم في ارض مستقر متع ال حين', 'quran', NULL, NULL, 'https://quran.com/2/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (43, 'فزل زله لهم الش لشي شيط يطن عنه فخر خرج رجه جهم مم كن فيه وقل قلن اهب هبط بطو بعض عضك ضكم لبع بعض عدو ولك لكم في الر لرض مست ستق تقر ومت متع الي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (44, 'quran:2:37', 'quran', 'quran', '2:37', 37, 43, 'Al-Baqarah', 'البقرة', 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', NULL, NULL, 'فتلقي ادم من ربه كلمت فتاب عليه انه هو التواب الرحيم', 'تلق ادم من رب كلمت تب عل ان هو توب رحيم', 'quran', NULL, NULL, 'https://quran.com/2/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (44, 'فتل تلق لقي ادم من ربه كلم لمت فتب علي ليه انه هو الت لتو توب الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (45, 'quran:2:38', 'quran', 'quran', '2:38', 38, 44, 'Al-Baqarah', 'البقرة', 'قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'قلنا اهبطوا منها جميعا فاما ياتينكم مني هدي فمن تبع هداي فلا خوف عليهم ولا هم يحزنون', 'قل اهبط من جميع ام يتين من هد فمن تبع هد فل خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (45, 'قلن اهب هبط بطو منه جمي ميع فم يتي تين ينك نكم مني هدي فمن تبع هدي فل خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (46, 'quran:2:39', 'quran', 'quran', '2:39', 39, 45, 'Al-Baqarah', 'البقرة', 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'والذين كفروا وكذبوا بايتنا اوليك اصحب النار هم فيها خلدون', 'ذين كفر كذب بيت اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (46, 'ولذ لذي ذين كفر فرو وكذ كذب ذبو بيت يتن اول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (47, 'quran:2:40', 'quran', 'quran', '2:40', 40, 46, 'Al-Baqarah', 'البقرة', 'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ', NULL, NULL, 'يا بني اسرءيل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم وايي فارهبون', 'ي بن اسرءيل اذكر نعمت تي انعمت علي اوف بعهد اوف بعهد اي ارهب', 'quran', NULL, NULL, 'https://quran.com/2/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (47, 'ي بني اسر سرء رءي ءيل اذك ذكر كرو نعم عمت متي الت لتي انع نعم عمت علي ليك يكم ووف وفو بعه عهد هدي اوف بعه عهد هدك دكم ويي فره رهب هبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (48, 'quran:2:41', 'quran', 'quran', '2:41', 41, 47, 'Al-Baqarah', 'البقرة', 'وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ', NULL, NULL, 'وامنوا بما انزلت مصدقا لما معكم ولا تكونوا اول كافر به ولا تشتروا بايتي ثمنا قليلا وايي فاتقون', 'امن بم انزلت مصدق لم مع ول تكون اول كفر به ول تشتر بيت ثم قليل اي اتق', 'quran', NULL, NULL, 'https://quran.com/2/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (48, 'ومن منو بم انز نزل زلت مصد صدق لم معك عكم ول تكو كون ونو اول كفر به ول تشت شتر ترو بيت يتي ثمن قلي ليل ويي فتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (49, 'quran:2:42', 'quran', 'quran', '2:42', 42, 48, 'Al-Baqarah', 'البقرة', 'وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'ولا تلبسوا الحق بالبطل وتكتموا الحق وانتم تعلمون', 'ول تلبس حق بطل تكتم حق انتم تعلم', 'quran', NULL, NULL, 'https://quran.com/2/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (49, 'ول تلب لبس بسو الح لحق بلب لبط بطل وتك تكت كتم تمو الح لحق ونت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (50, 'quran:2:43', 'quran', 'quran', '2:43', 43, 49, 'Al-Baqarah', 'البقرة', 'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ', NULL, NULL, 'واقيموا الصلاه واتوا الزكاه واركعوا مع الركعين', 'اقيم صل ات زك اركع مع ركع', 'quran', NULL, NULL, 'https://quran.com/2/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (50, 'وقي قيم يمو الص لصل صله وتو الز لزك زكه ورك ركع كعو مع الر لرك ركع كعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (51, 'quran:2:44', 'quran', 'quran', '2:44', 44, 50, 'Al-Baqarah', 'البقرة', 'أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتب افلا تعقلون', 'اتمر نس بر تنس انفس انتم تتل كتب افل تعقل', 'quran', NULL, NULL, 'https://quran.com/2/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (51, 'اتم تمر مرو رون الن لنس بلب لبر وتن تنس نسو سون انف نفس فسك سكم ونت نتم تتل تلو لون الك لكت كتب افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (52, 'quran:2:45', 'quran', 'quran', '2:45', 45, 51, 'Al-Baqarah', 'البقرة', 'وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ', NULL, NULL, 'واستعينوا بالصبر والصلاه وانها لكبيره الا علي الخشعين', 'استعين صبر صل ان لكبير ال عل خشع', 'quran', NULL, NULL, 'https://quran.com/2/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (52, 'وست ستع تعي عين ينو بلص لصب صبر ولص لصل صله ونه لكب كبي بير يره ال علي الخ لخش خشع شعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (53, 'quran:2:46', 'quran', 'quran', '2:46', 46, 52, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ', NULL, NULL, 'الذين يظنون انهم ملقوا ربهم وانهم اليه رجعون', 'ذين يظن ان ملق رب ان يه رجع', 'quran', NULL, NULL, 'https://quran.com/2/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (53, 'الذ لذي ذين يظن ظنو نون انه نهم ملق لقو ربه بهم ونه نهم الي ليه رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (54, 'quran:2:47', 'quran', 'quran', '2:47', 47, 53, 'Al-Baqarah', 'البقرة', 'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ', NULL, NULL, 'يا بني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين', 'ي بن اسرءيل اذكر نعمت تي انعمت علي ان ضلت عل علم', 'quran', NULL, NULL, 'https://quran.com/2/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (54, 'ي بني اسر سرء رءي ءيل اذك ذكر كرو نعم عمت متي الت لتي انع نعم عمت علي ليك يكم وني فضل ضلت لتك تكم علي الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (55, 'quran:2:48', 'quran', 'quran', '2:48', 48, 54, 'Al-Baqarah', 'البقرة', 'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ', NULL, NULL, 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها شفعه ولا يوخذ منها عدل ولا هم ينصرون', 'اتق يوم ل تجز نفس عن نفس شي ول يقبل من شفع ول يوخذ من عدل ول هم ينصر', 'quran', NULL, NULL, 'https://quran.com/2/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (55, 'وتق تقو يوم ل تجز جزي نفس عن نفس شي ول يقب قبل منه شفع فعه ول يوخ وخذ منه عدل ول هم ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (56, 'quran:2:49', 'quran', 'quran', '2:49', 49, 55, 'Al-Baqarah', 'البقرة', 'وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ', NULL, NULL, 'واذ نجينكم من ال فرعون يسومونكم سوء العذاب يذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم', 'وذ نجين من ال رع يسومون سوء عذب يذبح ابنء يستحي نسء وف ذل بلء من رب عظيم', 'quran', NULL, NULL, 'https://quran.com/2/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (56, 'وذ نجي جين ينك نكم من ال فرع رعو عون يسو سوم ومو مون ونك نكم سوء الع لعذ عذب يذب ذبح بحو حون ابن بنء نءك ءكم ويس يست ستح تحي حيو يون نسء سءك ءكم وفي ذلك لكم بلء من ربك بكم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (57, 'quran:2:50', 'quran', 'quran', '2:50', 50, 56, 'Al-Baqarah', 'البقرة', 'وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ', NULL, NULL, 'واذ فرقنا بكم البحر فانجينكم واغرقنا ال فرعون وانتم تنظرون', 'وذ رق بكم بحر انجين اغرق ال رع انتم تنظر', 'quran', NULL, NULL, 'https://quran.com/2/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (57, 'وذ فرق رقن بكم الب لبح بحر فنج نجي جين ينك نكم وغر غرق رقن ال فرع رعو عون ونت نتم تنظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (58, 'quran:2:51', 'quran', 'quran', '2:51', 51, 57, 'Al-Baqarah', 'البقرة', 'وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ', NULL, NULL, 'واذ وعدنا موسي اربعين ليله ثم اتخذتم العجل من بعده وانتم ظلمون', 'وذ عد موس اربع ليل ثم اتخذتم عجل من بعد انتم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (58, 'وذ وعد عدن موس وسي ارب ربع بعي عين ليل يله ثم اتخ تخذ خذت ذتم الع لعج عجل من بعد عده ونت نتم ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (59, 'quran:2:52', 'quran', 'quran', '2:52', 52, 58, 'Al-Baqarah', 'البقرة', 'ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون', 'ثم عفو عن من بعد ذلك لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/2/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (59, 'ثم عفو فون عنك نكم من بعد ذلك لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (60, 'quran:2:53', 'quran', 'quran', '2:53', 53, 59, 'Al-Baqarah', 'البقرة', 'وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ', NULL, NULL, 'واذ اتينا موسي الكتب والفرقان لعلكم تهتدون', 'وذ اتي موس كتب فرق لعل تهتد', 'quran', NULL, NULL, 'https://quran.com/2/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (60, 'وذ اتي تين موس وسي الك لكت كتب ولف لفر فرق رقن لعل علك لكم تهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (61, 'quran:2:54', 'quran', 'quran', '2:54', 54, 60, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', NULL, NULL, 'واذ قال موسي لقومه يا قوم انكم ظلمتم انفسكم باتخاذكم العجل فتوبوا الي باريكم فاقتلوا انفسكم ذلكم خير لكم عند باريكم فتاب عليكم انه هو التواب الرحيم', 'وذ قل موس لقوم ي قوم ان ظلمتم انفس بتخذ عجل توب ال بري اقتل انفس ذل خير لكم عند بري تب علي ان هو توب رحيم', 'quran', NULL, NULL, 'https://quran.com/2/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (61, 'وذ قل موس وسي لقو قوم ومه ي قوم انك نكم ظلم لمت متم انف نفس فسك سكم بتخ تخذ خذك ذكم الع لعج عجل فتو توب وبو الي بري ريك يكم فقت قتل تلو انف نفس فسك سكم ذلك لكم خير لكم عند بري ريك يكم فتب علي ليك يكم انه هو الت لتو توب الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (62, 'quran:2:55', 'quran', 'quran', '2:55', 55, 61, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ', NULL, NULL, 'واذ قلتم يا موسي لن نومن لك حتي نري الله جهره فاخذتكم الصعقه وانتم تنظرون', 'وذ قلتم ي موس لن نومن لك حت نر له جهر اخذت صعق انتم تنظر', 'quran', NULL, NULL, 'https://quran.com/2/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (62, 'وذ قلت لتم ي موس وسي لن نوم ومن لك حتي نري الل لله جهر هره فخذ خذت ذتك تكم الص لصع صعق عقه ونت نتم تنظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (63, 'quran:2:56', 'quran', 'quran', '2:56', 56, 62, 'Al-Baqarah', 'البقرة', 'ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'ثم بعثنكم من بعد موتكم لعلكم تشكرون', 'ثم بعثن من بعد موت لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/2/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (63, 'ثم بعث عثن ثنك نكم من بعد موت وتك تكم لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (64, 'quran:2:57', 'quran', 'quran', '2:57', 57, 63, 'Al-Baqarah', 'البقرة', 'وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', NULL, NULL, 'وظللنا عليكم الغمام وانزلنا عليكم المن والسلوي كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوا انفسهم يظلمون', 'ظلل علي غمم انزل علي من سلو كل من طيبت م رزقن وم ظلمو لكن كن انفس يظلم', 'quran', NULL, NULL, 'https://quran.com/2/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (64, 'وظل ظلل للن علي ليك يكم الغ لغم غمم ونز نزل زلن علي ليك يكم الم لمن ولس لسل سلو لوي كلو من طيب يبت م رزق زقن قنك نكم وم ظلم لمو مون ولك لكن كنو انف نفس فسه سهم يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (65, 'quran:2:58', 'quran', 'quran', '2:58', 58, 64, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'واذ قلنا ادخلوا هذه القريه فكلوا منها حيث شيتم رغدا وادخلوا الباب سجدا وقولوا حطه نغفر لكم خطيكم وسنزيد المحسنين', 'وذ قل ادخل هذ قر كل من حيث شيتم رغد ادخل بب سجد قول حط نغفر لكم خطي سنزيد محسن', 'quran', NULL, NULL, 'https://quran.com/2/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (65, 'وذ قلن ادخ دخل خلو هذه الق لقر قري ريه فكل كلو منه حيث شيت يتم رغد ودخ دخل خلو الب لبب سجد وقو قول ولو حطه نغف غفر لكم خطي طيك يكم وسن سنز نزي زيد الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (66, 'quran:2:59', 'quran', 'quran', '2:59', 59, 65, 'Al-Baqarah', 'البقرة', 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ', NULL, NULL, 'فبدل الذين ظلموا قولا غير الذي قيل لهم فانزلنا علي الذين ظلموا رجزا من السماء بما كانوا يفسقون', 'بدل ذين ظلم قول غير ذي قيل لهم انزل عل ذين ظلم رجز من سمء بم كن يفسق', 'quran', NULL, NULL, 'https://quran.com/2/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (66, 'فبد بدل الذ لذي ذين ظلم لمو قول غير الذ لذي قيل لهم فنز نزل زلن علي الذ لذي ذين ظلم لمو رجز من الس لسم سمء بم كنو يفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (67, 'quran:2:60', 'quran', 'quran', '2:60', 60, 66, 'Al-Baqarah', 'البقرة', 'وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', NULL, NULL, 'واذ استسقي موسي لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشره عينا قد علم كل اناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الارض مفسدين', 'وذ استسق موس لقوم قل اضرب بعصك حجر انفجرت من اثنت عشر عي قد علم كل انس مشرب كل اشرب من رزق له ول تعث في ارض مفسد', 'quran', NULL, NULL, 'https://quran.com/2/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (67, 'وذ است ستس تسق سقي موس وسي لقو قوم ومه فقل قلن اضر ضرب بعص عصك الح لحج حجر فنف نفج فجر جرت منه اثن ثنت عشر شره عين قد علم كل انس مشر شرب ربه بهم كلو وشر شرب ربو من رزق الل لله ول تعث عثو في الر لرض مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (68, 'quran:2:61', 'quran', 'quran', '2:61', 61, 67, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', NULL, NULL, 'واذ قلتم يا موسي لن نصبر علي طعام وحد فادع لنا ربك يخرج لنا مما تنبت الارض من بقلها وقثايها وفومها وعدسها وبصلها قال اتستبدلون الذي هو ادني بالذي هو خير اهبطوا مصرا فان لكم ما سالتم وضربت عليهم الذله والمسكنه وباءو بغضب من الله ذلك بانهم كانوا يكفرون بايت الله ويقتلون النبين بغير الحق ذلك بما عصوا وكانوا يعتدون', 'وذ قلتم ي موس لن نصبر عل طعم وحد ادع لن ربك يخرج لن مم تنبت ارض من بقل قثي فوم عدس بصل قل اتستبدل ذي هو ادن ذي هو خير اهبط مصر فن لكم م سلتم ضربت علي ذل مسكن بءو بغضب من له ذلك بن كن يكفر بيت له يقتل نب بغير حق ذلك بم عص كن يعتد', 'quran', NULL, NULL, 'https://quran.com/2/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (68, 'وذ قلت لتم ي موس وسي لن نصب صبر علي طعم وحد فدع لن ربك يخر خرج لن مم تنب نبت الر لرض من بقل قله وقث قثي ثيه وفو فوم ومه وعد عدس دسه وبص بصل صله قل اتس تست ستب تبد بدل دلو لون الذ لذي هو ادن دني بلذ لذي هو خير اهب هبط بطو مصر فن لكم م سلت لتم وضر ضرب ربت علي ليه يهم الذ لذل ذله ولم لمس مسك سكن كنه وبء بءو بغض غضب من الل لله ذلك بنه نهم كنو يكف كفر فرو رون بيت الل لله ويق يقت قتل تلو لون الن لنب نبي بين بغي غير الح لحق ذلك بم عصو وكن كنو يعت عتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (69, 'quran:2:62', 'quran', 'quran', '2:62', 62, 68, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'ان الذين امنوا والذين هادوا والنصري والصبين من امن بالله واليوم الاخر وعمل صلحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 'ان ذين امن ذين هد نصر صب من امن له يوم اخر عمل صلح لهم اجر عند رب ول خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (69, 'ان الذ لذي ذين امن منو ولذ لذي ذين هدو ولن لنص نصر صري ولص لصب صبي بين من امن بلل لله ولي ليو يوم الخ لخر وعم عمل صلح فله لهم اجر جره رهم عند ربه بهم ول خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (70, 'quran:2:63', 'quran', 'quran', '2:63', 63, 69, 'Al-Baqarah', 'البقرة', 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ', NULL, NULL, 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما اتينكم بقوه واذكروا ما فيه لعلكم تتقون', 'وذ اخذ ميثق رفع وق طور خذ م اتين بقو اذكر م في لعل تتق', 'quran', NULL, NULL, 'https://quran.com/2/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (70, 'وذ اخذ خذن ميث يثق ثقك قكم ورف رفع فعن فوق وقك قكم الط لطو طور خذو م اتي تين ينك نكم بقو قوه وذك ذكر كرو م فيه لعل علك لكم تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (71, 'quran:2:64', 'quran', 'quran', '2:64', 64, 70, 'Al-Baqarah', 'البقرة', 'ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ', NULL, NULL, 'ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخسرين', 'ثم توليتم من بعد ذلك لول فضل له علي رحمت لكنتم من خسر', 'quran', NULL, NULL, 'https://quran.com/2/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (71, 'ثم تول ولي ليت يتم من بعد ذلك فلو لول فضل الل لله علي ليك يكم ورح رحم حمت مته لكن كنت نتم من الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (72, 'quran:2:65', 'quran', 'quran', '2:65', 65, 71, 'Al-Baqarah', 'البقرة', 'وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ', NULL, NULL, 'ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قرده خسين', 'لقد علمتم ذين اعتد من في سبت قل لهم كون قرد خس', 'quran', NULL, NULL, 'https://quran.com/2/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (72, 'ولق لقد علم لمت متم الذ لذي ذين اعت عتد تدو منك نكم في الس لسب سبت فقل قلن لهم كون ونو قرد رده خسي سين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (73, 'quran:2:66', 'quran', 'quran', '2:66', 66, 72, 'Al-Baqarah', 'البقرة', 'فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ', NULL, NULL, 'فجعلنها نكلا لما بين يديها وما خلفها وموعظه للمتقين', 'جعلن نكل لم بين يدي وم خلف موعظ متق', 'quran', NULL, NULL, 'https://quran.com/2/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (73, 'فجع جعل علن لنه نكل لم بين يدي ديه وم خلف لفه ومو موع وعظ عظه للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (74, 'quran:2:67', 'quran', 'quran', '2:67', 67, 73, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ', NULL, NULL, 'واذ قال موسي لقومه ان الله يامركم ان تذبحوا بقره قالوا اتتخذنا هزوا قال اعوذ بالله ان اكون من الجهلين', 'وذ قل موس لقوم ان له يمر ان تذبح بقر قل اتتخذ هز قل اعوذ له ان اك من جهل', 'quran', NULL, NULL, 'https://quran.com/2/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (74, 'وذ قل موس وسي لقو قوم ومه ان الل لله يمر مرك ركم ان تذب ذبح بحو بقر قره قلو اتت تتخ تخذ خذن هزو قل اعو عوذ بلل لله ان اكو كون من الج لجه جهل هلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (75, 'quran:2:68', 'quran', 'quran', '2:68', 68, 74, 'Al-Baqarah', 'البقرة', 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ', NULL, NULL, 'قالوا ادع لنا ربك يبين لنا ما هي قال انه يقول انها بقره لا فارض ولا بكر عوان بين ذلك فافعلوا ما تومرون', 'قل ادع لن ربك يب لن م هي قل ان يقول ان بقر ل ارض ول بكر عو بين ذلك افعل م تومر', 'quran', NULL, NULL, 'https://quran.com/2/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (75, 'قلو ادع لن ربك يبي بين لن م هي قل انه يقو قول انه بقر قره ل فرض ول بكر عون بين ذلك ففع فعل علو م توم ومر مرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (76, 'quran:2:69', 'quran', 'quran', '2:69', 69, 75, 'Al-Baqarah', 'البقرة', 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', NULL, NULL, 'قالوا ادع لنا ربك يبين لنا ما لونها قال انه يقول انها بقره صفراء فاقع لونها تسر النظرين', 'قل ادع لن ربك يب لن م لون قل ان يقول ان بقر صفرء اقع لون تسر نظر', 'quran', NULL, NULL, 'https://quran.com/2/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (76, 'قلو ادع لن ربك يبي بين لن م لون ونه قل انه يقو قول انه بقر قره صفر فرء فقع لون ونه تسر الن لنظ نظر ظري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (77, 'quran:2:70', 'quran', 'quran', '2:70', 70, 76, 'Al-Baqarah', 'البقرة', 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ', NULL, NULL, 'قالوا ادع لنا ربك يبين لنا ما هي ان البقر تشبه علينا وانا ان شاء الله لمهتدون', 'قل ادع لن ربك يب لن م هي ان بقر تشب علي ان ان شء له لمهتد', 'quran', NULL, NULL, 'https://quran.com/2/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (77, 'قلو ادع لن ربك يبي بين لن م هي ان الب لبق بقر تشب شبه علي لين ون ان شء الل لله لمه مهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (78, 'quran:2:71', 'quran', 'quran', '2:71', 71, 77, 'Al-Baqarah', 'البقرة', 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ', NULL, NULL, 'قال انه يقول انها بقره لا ذلول تثير الارض ولا تسقي الحرث مسلمه لا شيه فيها قالوا الن جيت بالحق فذبحوها وما كادوا يفعلون', 'قل ان يقول ان بقر ل ذلول تثير ارض ول تسق حرث مسلم ل شي يه قل الن جيت حق ذبحو وم كد يفعل', 'quran', NULL, NULL, 'https://quran.com/2/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (78, 'قل انه يقو قول انه بقر قره ل ذلو لول تثي ثير الر لرض ول تسق سقي الح لحر حرث مسل سلم لمه ل شيه فيه قلو الن جيت بلح لحق فذب ذبح بحو حوه وم كدو يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (79, 'quran:2:72', 'quran', 'quran', '2:72', 72, 78, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ', NULL, NULL, 'واذ قتلتم نفسا فادرءتم فيها والله مخرج ما كنتم تكتمون', 'وذ قتلتم نفس ادرءتم يه له مخرج م كنتم تكتم', 'quran', NULL, NULL, 'https://quran.com/2/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (79, 'وذ قتل تلت لتم نفس فدر درء رءت ءتم فيه ولل لله مخر خرج م كنت نتم تكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (80, 'quran:2:73', 'quran', 'quran', '2:73', 73, 79, 'Al-Baqarah', 'البقرة', 'فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', NULL, NULL, 'فقلنا اضربوه ببعضها كذلك يحي الله الموتي ويريكم ايته لعلكم تعقلون', 'قل اضربو ببعض كذلك يح له موت يري ايت لعل تعقل', 'quran', NULL, NULL, 'https://quran.com/2/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (80, 'فقل قلن اضر ضرب ربو بوه ببع بعض عضه كذل ذلك يحي الل لله الم لمو موت وتي وير يري ريك يكم ايت يته لعل علك لكم تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (81, 'quran:2:74', 'quran', 'quran', '2:74', 74, 80, 'Al-Baqarah', 'البقرة', 'ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', NULL, NULL, 'ثم قست قلوبكم من بعد ذلك فهي كالحجاره او اشد قسوه وان من الحجاره لما يتفجر منه الانهر وان منها لما يشقق فيخرج منه الماء وان منها لما يهبط من خشيه الله وما الله بغفل عما تعملون', 'ثم قست قلوب من بعد ذلك فه حجر او اشد قسو ون من حجر لم يتفجر من انهر ون من لم يشقق يخرج من مء ون من لم يهبط من خش له وم له بغفل عم تعمل', 'quran', NULL, NULL, 'https://quran.com/2/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (81, 'ثم قست قلو لوب وبك بكم من بعد ذلك فهي كلح لحج حجر جره او اشد قسو سوه ون من الح لحج حجر جره لم يتف تفج فجر منه الن لنه نهر ون منه لم يشق شقق فيخ يخر خرج منه الم لمء ون منه لم يهب هبط من خشي شيه الل لله وم الل لله بغف غفل عم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (82, 'quran:2:75', 'quran', 'quran', '2:75', 75, 81, 'Al-Baqarah', 'البقرة', 'أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'افتطمعون ان يومنوا لكم وقد كان فريق منهم يسمعون كلم الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون', 'افتطمع ان يومن لكم وقد كن ريق من يسمع كلم له ثم يحرفون من بعد م عقلو وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/2/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (82, 'افت فتط تطم طمع معو عون ان يوم ومن منو لكم وقد كن فري ريق منه نهم يسم سمع معو عون كلم الل لله ثم يحر حرف رفو فون ونه من بعد م عقل قلو لوه وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (83, 'quran:2:76', 'quran', 'quran', '2:76', 76, 82, 'Al-Baqarah', 'البقرة', 'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'واذا لقوا الذين امنوا قالوا امنا واذا خلا بعضهم الي بعض قالوا اتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم افلا تعقلون', 'اذ لق ذين امن قل ام اذ خل بعض ال بعض قل اتحدثون بم فتح له علي ليحجو به عند رب افل تعقل', 'quran', NULL, NULL, 'https://quran.com/2/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (83, 'وذ لقو الذ لذي ذين امن منو قلو امن وذ خل بعض عضه ضهم الي بعض قلو اتح تحد حدث دثو ثون ونه نهم بم فتح الل لله علي ليك يكم ليح يحج حجو جوك وكم به عند ربك بكم افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (84, 'quran:2:77', 'quran', 'quran', '2:77', 77, 83, 'Al-Baqarah', 'البقرة', 'أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ', NULL, NULL, 'اولا يعلمون ان الله يعلم ما يسرون وما يعلنون', 'اول يعلم ان له يعلم م يسر وم يعلن', 'quran', NULL, NULL, 'https://quran.com/2/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (84, 'اول يعل علم لمو مون ان الل لله يعل علم م يسر سرو رون وم يعل علن لنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (85, 'quran:2:78', 'quran', 'quran', '2:78', 78, 84, 'Al-Baqarah', 'البقرة', 'وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ', NULL, NULL, 'ومنهم اميون لا يعلمون الكتب الا اماني وان هم الا يظنون', 'من امي ل يعلم كتب ال امن ون هم ال يظن', 'quran', NULL, NULL, 'https://quran.com/2/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (85, 'ومن منه نهم امي ميو يون ل يعل علم لمو مون الك لكت كتب ال امن مني ون هم ال يظن ظنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (86, 'quran:2:79', 'quran', 'quran', '2:79', 79, 85, 'Al-Baqarah', 'البقرة', 'فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَوَيۡلٞ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلٞ لَّهُم مِّمَّا يَكۡسِبُونَ', NULL, NULL, 'فويل للذين يكتبون الكتب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون', 'ويل ذين يكتب كتب بيدي ثم يقول هذ من عند له ليشتر به ثم قليل ويل لهم مم كتبت ايدي ويل لهم مم يكسب', 'quran', NULL, NULL, 'https://quran.com/2/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (86, 'فوي ويل للذ لذي ذين يكت كتب تبو بون الك لكت كتب بيد يدي ديه يهم ثم يقو قول ولو لون هذ من عند الل لله ليش يشت شتر ترو به ثمن قلي ليل فوي ويل لهم مم كتب تبت ايد يدي ديه يهم ووي ويل لهم مم يكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (87, 'quran:2:80', 'quran', 'quran', '2:80', 80, 86, 'Al-Baqarah', 'البقرة', 'وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', NULL, NULL, 'وقالوا لن تمسنا النار الا اياما معدوده قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون علي الله ما لا تعلمون', 'قل لن تمس نر ال ايم معدود قل اتخذتم عند له عهد فلن يخلف له عهد ام تقول عل له م ل تعلم', 'quran', NULL, NULL, 'https://quran.com/2/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (87, 'وقل قلو لن تمس مسن الن لنر ال ايم معد عدو دود وده قل اتخ تخذ خذت ذتم عند الل لله عهد فلن يخل خلف الل لله عهد هده ام تقو قول ولو لون علي الل لله م ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (88, 'quran:2:81', 'quran', 'quran', '2:81', 81, 87, 'Al-Baqarah', 'البقرة', 'بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'بلي من كسب سييه واحطت به خطيته فاوليك اصحب النار هم فيها خلدون', 'بل من كسب سي احطت به خطيت اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (88, 'بلي من كسب سيي ييه وحط حطت به خطي طيت يته فول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (89, 'quran:2:82', 'quran', 'quran', '2:82', 82, 88, 'Al-Baqarah', 'البقرة', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'والذين امنوا وعملوا الصلحت اوليك اصحب الجنه هم فيها خلدون', 'ذين امن عمل صلحت اوليك اصحب جن هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (89, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت اول ولي ليك اصح صحب الج لجن جنه هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (90, 'quran:2:83', 'quran', 'quran', '2:83', 83, 89, 'Al-Baqarah', 'البقرة', 'وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ', NULL, NULL, 'واذ اخذنا ميثق بني اسرءيل لا تعبدون الا الله وبالولدين احسانا وذي القربي واليتمي والمسكين وقولوا للناس حسنا واقيموا الصلاه واتوا الزكاه ثم توليتم الا قليلا منكم وانتم معرضون', 'وذ اخذ ميثق بن اسرءيل ل تعبد ال له ولد احس وذ قرب يتم مسك قول نس حس اقيم صل ات زك ثم توليتم ال قليل من انتم معرض', 'quran', NULL, NULL, 'https://quran.com/2/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (90, 'وذ اخذ خذن ميث يثق بني اسر سرء رءي ءيل ل تعب عبد بدو دون ال الل لله وبل بلو لول ولد لدي دين احس حسن وذي الق لقر قرب ربي ولي ليت يتم تمي ولم لمس مسك سكي كين وقو قول ولو للن لنس حسن وقي قيم يمو الص لصل صله وتو الز لزك زكه ثم تول ولي ليت يتم ال قلي ليل منك نكم ونت نتم معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (91, 'quran:2:84', 'quran', 'quran', '2:84', 84, 90, 'Al-Baqarah', 'البقرة', 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ', NULL, NULL, 'واذ اخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون انفسكم من ديركم ثم اقررتم وانتم تشهدون', 'وذ اخذ ميثق ل تسفك دمء ول تخرج انفس من دير ثم اقررتم انتم تشهد', 'quran', NULL, NULL, 'https://quran.com/2/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (91, 'وذ اخذ خذن ميث يثق ثقك قكم ل تسف سفك فكو كون دمء مءك ءكم ول تخر خرج رجو جون انف نفس فسك سكم من دير يرك ركم ثم اقر قرر ررت رتم ونت نتم تشه شهد هدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (92, 'quran:2:85', 'quran', 'quran', '2:85', 85, 91, 'Al-Baqarah', 'البقرة', 'ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', NULL, NULL, 'ثم انتم هولاء تقتلون انفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالاثم والعدون وان ياتوكم اسري تفدوهم وهو محرم عليكم اخراجهم افتومنون ببعض الكتب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحياه الدنيا ويوم القيمه يردون الي اشد العذاب وما الله بغفل عما تعملون', 'ثم انتم هولء تقتل انفس تخرج ريق من من دير تظهر علي اثم عد ون يتو اسر تفدو وهو محرم علي اخرج افتومن ببعض كتب تكفر ببعض فم جزء من يفعل ذلك من ال خز في حي دني يوم قيم يرد ال اشد عذب وم له بغفل عم تعمل', 'quran', NULL, NULL, 'https://quran.com/2/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (92, 'ثم انت نتم هول ولء تقت قتل تلو لون انف نفس فسك سكم وتخ تخر خرج رجو جون فري ريق منك نكم من دير يره رهم تظه ظهر هرو رون علي ليه يهم بلث لثم ولع لعد عدو دون ون يتو توك وكم اسر سري تفد فدو دوه وهم وهو محر حرم علي ليك يكم اخر خرج رجه جهم افت فتو توم ومن منو نون ببع بعض الك لكت كتب وتك تكف كفر فرو رون ببع بعض فم جزء من يفع فعل ذلك منك نكم ال خزي في الح لحي حيه الد لدن دني ويو يوم الق لقي قيم يمه يرد ردو دون الي اشد الع لعذ عذب وم الل لله بغف غفل عم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (93, 'quran:2:86', 'quran', 'quran', '2:86', 86, 92, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ', NULL, NULL, 'اوليك الذين اشتروا الحياه الدنيا بالاخره فلا يخفف عنهم العذاب ولا هم ينصرون', 'اوليك ذين اشتر حي دني اخر فل يخفف عن عذب ول هم ينصر', 'quran', NULL, NULL, 'https://quran.com/2/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (93, 'اول ولي ليك الذ لذي ذين اشت شتر ترو الح لحي حيه الد لدن دني بلخ لخر خره فل يخف خفف عنه نهم الع لعذ عذب ول هم ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (94, 'quran:2:87', 'quran', 'quran', '2:87', 87, 93, 'Al-Baqarah', 'البقرة', 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ', NULL, NULL, 'ولقد اتينا موسي الكتب وقفينا من بعده بالرسل واتينا عيسي ابن مريم البينت وايدنه بروح القدس افكلما جاءكم رسول بما لا تهوي انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون', 'لقد اتي موس كتب قفي من بعد رسل اتي عيس ابن مريم بينت ايدن بروح قدس افكلم جء رسول بم ل تهو انفس استكبرتم فريق كذبتم فريق تقتل', 'quran', NULL, NULL, 'https://quran.com/2/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (94, 'ولق لقد اتي تين موس وسي الك لكت كتب وقف قفي فين من بعد عده بلر لرس رسل وتي تين عيس يسي ابن مري ريم الب لبي بين ينت ويد يدن دنه برو روح الق لقد قدس افك فكل كلم جءك ءكم رسو سول بم ل تهو هوي انف نفس فسك سكم است ستك تكب كبر برت رتم ففر فري ريق كذب ذبت بتم وفر فري ريق تقت قتل تلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (95, 'quran:2:88', 'quran', 'quran', '2:88', 88, 94, 'Al-Baqarah', 'البقرة', 'وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ', NULL, NULL, 'وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يومنون', 'قل قلوب غلف بل لعن له بكفر قليل م يومن', 'quran', NULL, NULL, 'https://quran.com/2/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (95, 'وقل قلو قلو لوب وبن غلف بل لعن عنه نهم الل لله بكف كفر فره رهم فقل قلي ليل م يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (96, 'quran:2:89', 'quran', 'quran', '2:89', 89, 95, 'Al-Baqarah', 'البقرة', 'وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ', NULL, NULL, 'ولما جاءهم كتب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون علي الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنه الله علي الكفرين', 'لم جء كتب من عند له مصدق لم مع كن من قبل يستفتح عل ذين كفر لم جء م عرف كفر به لعن له عل كفر', 'quran', NULL, NULL, 'https://quran.com/2/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (96, 'ولم جءه ءهم كتب من عند الل لله مصد صدق لم معه عهم وكن كنو من قبل يست ستف تفت فتح تحو حون علي الذ لذي ذين كفر فرو فلم جءه ءهم م عرف رفو كفر فرو به فلع لعن عنه الل لله علي الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (97, 'quran:2:90', 'quran', 'quran', '2:90', 90, 96, 'Al-Baqarah', 'البقرة', 'بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ', NULL, NULL, 'بيسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله علي من يشاء من عباده فباءو بغضب علي غضب وللكفرين عذاب مهين', 'بيسم اشتر به انفس ان يكفر بم انزل له بغي ان ينزل له من ضل عل من يشء من عبد بءو بغضب عل غضب كفر عذب مه', 'quran', NULL, NULL, 'https://quran.com/2/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (97, 'بيس يسم اشت شتر ترو به انف نفس فسه سهم ان يكف كفر فرو بم انز نزل الل لله بغي ان ينز نزل الل لله من فضل ضله علي من يشء من عبد بده فبء بءو بغض غضب علي غضب ولل للك لكف كفر فري رين عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (98, 'quran:2:91', 'quran', 'quran', '2:91', 91, 97, 'Al-Baqarah', 'البقرة', 'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'واذا قيل لهم امنوا بما انزل الله قالوا نومن بما انزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون انبياء الله من قبل ان كنتم مومنين', 'اذ قيل لهم امن بم انزل له قل نومن بم انزل علي يكفر بم رء وهو حق مصدق لم مع قل فلم تقتل انبيء له من قبل ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/2/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (98, 'وذ قيل لهم امن منو بم انز نزل الل لله قلو نوم ومن بم انز نزل علي لين ويك يكف كفر فرو رون بم ورء رءه وهو الح لحق مصد صدق لم معه عهم قل فلم تقت قتل تلو لون انب نبي بيء الل لله من قبل ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (99, 'quran:2:92', 'quran', 'quran', '2:92', 92, 98, 'Al-Baqarah', 'البقرة', 'وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ', NULL, NULL, 'ولقد جاءكم موسي بالبينت ثم اتخذتم العجل من بعده وانتم ظلمون', 'لقد جء موس بينت ثم اتخذتم عجل من بعد انتم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (99, 'ولق لقد جءك ءكم موس وسي بلب لبي بين ينت ثم اتخ تخذ خذت ذتم الع لعج عجل من بعد عده ونت نتم ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (100, 'quran:2:93', 'quran', 'quran', '2:93', 93, 99, 'Al-Baqarah', 'البقرة', 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما اتينكم بقوه واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بيسما يامركم به ايمنكم ان كنتم مومنين', 'وذ اخذ ميثق رفع وق طور خذ م اتين بقو اسمع قل سمع عصي اشرب في قلوب عجل بكفر قل بيسم يمر به ايمن ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/2/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (100, 'وذ اخذ خذن ميث يثق ثقك قكم ورف رفع فعن فوق وقك قكم الط لطو طور خذو م اتي تين ينك نكم بقو قوه وسم سمع معو قلو سمع معن وعص عصي صين وشر شرب ربو في قلو لوب وبه بهم الع لعج عجل بكف كفر فره رهم قل بيس يسم يمر مرك ركم به ايم يمن منك نكم ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (101, 'quran:2:94', 'quran', 'quran', '2:94', 94, 100, 'Al-Baqarah', 'البقرة', 'قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'قل ان كانت لكم الدار الاخره عند الله خالصه من دون الناس فتمنوا الموت ان كنتم صدقين', 'قل ان كنت لكم در اخر عند له خلص من دون نس تمن موت ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/2/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (101, 'قل ان كنت لكم الد لدر الخ لخر خره عند الل لله خلص لصه من دون الن لنس فتم تمن منو الم لمو موت ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (102, 'quran:2:95', 'quran', 'quran', '2:95', 95, 101, 'Al-Baqarah', 'البقرة', 'وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ', NULL, NULL, 'ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظلمين', 'ولن يتمنو ابد بم قدمت ايدي له عليم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (102, 'ولن يتم تمن منو نوه ابد بم قدم دمت ايد يدي ديه يهم ولل لله علي ليم بلظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (103, 'quran:2:96', 'quran', 'quran', '2:96', 96, 102, 'Al-Baqarah', 'البقرة', 'وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', NULL, NULL, 'ولتجدنهم احرص الناس علي حياه ومن الذين اشركوا يود احدهم لو يعمر الف سنه وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون', 'لتجدن احرص نس عل حي ومن ذين اشرك يود احد لو يعمر الف سن وم هو بمزحزح من عذب ان يعمر له بصير بم يعمل', 'quran', NULL, NULL, 'https://quran.com/2/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (103, 'ولت لتج تجد جدن دنه نهم احر حرص الن لنس علي حيه ومن الذ لذي ذين اشر شرك ركو يود احد حده دهم لو يعم عمر الف سنه وم هو بمز مزح زحز حزح زحه من الع لعذ عذب ان يعم عمر ولل لله بصي صير بم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (104, 'quran:2:97', 'quran', 'quran', '2:97', 97, 103, 'Al-Baqarah', 'البقرة', 'قُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ', NULL, NULL, 'قل من كان عدوا لجبريل فانه نزله علي قلبك باذن الله مصدقا لما بين يديه وهدي وبشري للمومنين', 'قل من كن عد لجبريل ان نزل عل قلبك بذن له مصدق لم بين يد هد بشر مومن', 'quran', NULL, NULL, 'https://quran.com/2/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (104, 'قل من كن عدو لجب جبر بري ريل فنه نزل زله علي قلب لبك بذن الل لله مصد صدق لم بين يدي ديه وهد هدي وبش بشر شري للم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (105, 'quran:2:98', 'quran', 'quran', '2:98', 98, 104, 'Al-Baqarah', 'البقرة', 'مَن كَانَ عَدُوّٗا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوّٞ لِّلۡكَٰفِرِينَ', NULL, NULL, 'من كان عدوا لله ومليكته ورسله وجبريل وميكال فان الله عدو للكفرين', 'من كن عد لل مليكت رسل جبريل ميكل فن له عدو كفر', 'quran', NULL, NULL, 'https://quran.com/2/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (105, 'من كن عدو لله ومل ملي ليك يكت كته ورس رسل سله وجب جبر بري ريل ومي ميك يكل فن الل لله عدو للك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (106, 'quran:2:99', 'quran', 'quran', '2:99', 99, 105, 'Al-Baqarah', 'البقرة', 'وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتٖۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ', NULL, NULL, 'ولقد انزلنا اليك ايت بينت وما يكفر بها الا الفسقون', 'لقد انزل يك ايت بينت وم يكفر به ال فسق', 'quran', NULL, NULL, 'https://quran.com/2/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (106, 'ولق لقد انز نزل زلن الي ليك ايت بين ينت وم يكف كفر به ال الف لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (107, 'quran:2:100', 'quran', 'quran', '2:100', 100, 106, 'Al-Baqarah', 'البقرة', 'أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ', NULL, NULL, 'اوكلما عهدوا عهدا نبذه فريق منهم بل اكثرهم لا يومنون', 'اوكلم عهد عهد نبذ ريق من بل اكثر ل يومن', 'quran', NULL, NULL, 'https://quran.com/2/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (107, 'اوك وكل كلم عهد هدو عهد نبذ بذه فري ريق منه نهم بل اكث كثر ثره رهم ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (108, 'quran:2:101', 'quran', 'quran', '2:101', 101, 107, 'Al-Baqarah', 'البقرة', 'وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتب كتب الله وراء ظهورهم كانهم لا يعلمون', 'لم جء رسول من عند له مصدق لم مع نبذ ريق من ذين اوت كتب كتب له رء ظهور كن ل يعلم', 'quran', NULL, NULL, 'https://quran.com/2/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (108, 'ولم جءه ءهم رسو سول من عند الل لله مصد صدق لم معه عهم نبذ فري ريق من الذ لذي ذين اوت وتو الك لكت كتب كتب الل لله ورء ظهو هور وره رهم كنه نهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (109, 'quran:2:102', 'quran', 'quran', '2:102', 102, 108, 'Al-Baqarah', 'البقرة', 'وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'واتبعوا ما تتلوا الشيطين علي ملك سليمن وما كفر سليمن ولكن الشيطين كفروا يعلمون الناس السحر وما انزل علي الملكين ببابل هروت ومروت وما يعلمان من احد حتي يقولا انما نحن فتنه فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتراه ما له في الاخره من خلق ولبيس ما شروا به انفسهم لو كانوا يعلمون', 'اتبع م تتل شيط عل ملك سليمن وم كفر سليمن لكن شيط كفر يعلم نس سحر وم انزل عل ملك بببل هروت مروت وم يعلم من احد حت يقول انم نحن تن فل تكفر يتعلم منهم م يفرق به بين مرء زوج وم هم بضر به من احد ال بذن له يتعلم م يضر ول ينفع لقد علم لمن اشتر م له في اخر من خلق لبيس م شر به انفس لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/2/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (109, 'وتب تبع بعو م تتل تلو الش لشي شيط يطي طين علي ملك سلي ليم يمن وم كفر سلي ليم يمن ولك لكن الش لشي شيط يطي طين كفر فرو يعل علم لمو مون الن لنس الس لسح سحر وم انز نزل علي الم لمل ملك لكي كين ببب ببل هرو روت ومر مرو روت وم يعل علم لمن من احد حتي يقو قول انم نحن فتن تنه فل تكف كفر فيت يتع تعل علم لمو مون منه نهم م يفر فرق رقو قون به بين الم لمر مرء وزو زوج وجه وم هم بضر ضري رين به من احد ال بذن الل لله ويت يتع تعل علم لمو مون م يضر ضره رهم ول ينف نفع فعه عهم ولق لقد علم لمو لمن اشت شتر تره م له في الخ لخر خره من خلق ولب لبي بيس م شرو به انف نفس فسه سهم لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (110, 'quran:2:103', 'quran', 'quran', '2:103', 103, 109, 'Al-Baqarah', 'البقرة', 'وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'ولو انهم امنوا واتقوا لمثوبه من عند الله خير لو كانوا يعلمون', 'ولو ان امن اتق لمثوب من عند له خير لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/2/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (110, 'ولو انه نهم امن منو وتق تقو لمث مثو ثوب وبه من عند الل لله خير لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (111, 'quran:2:104', 'quran', 'quran', '2:104', 104, 110, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا لا تقولوا رعنا وقولوا انظرنا واسمعوا وللكفرين عذاب اليم', 'ي اي ذين امن ل تقول رع قول انظر اسمع كفر عذب يم', 'quran', NULL, NULL, 'https://quran.com/2/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (111, 'ي ايه الذ لذي ذين امن منو ل تقو قول ولو رعن وقو قول ولو انظ نظر ظرن وسم سمع معو ولل للك لكف كفر فري رين عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (112, 'quran:2:105', 'quran', 'quran', '2:105', 105, 111, 'Al-Baqarah', 'البقرة', 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ', NULL, NULL, 'ما يود الذين كفروا من اهل الكتب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم', 'م يود ذين كفر من اهل كتب ول مشرك ان ينزل علي من خير من رب له يختص برحمت من يشء له ذو فضل عظيم', 'quran', NULL, NULL, 'https://quran.com/2/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (112, 'م يود الذ لذي ذين كفر فرو من اهل الك لكت كتب ول الم لمش مشر شرك ركي كين ان ينز نزل علي ليك يكم من خير من ربك بكم ولل لله يخت ختص برح رحم حمت مته من يشء ولل لله ذو الف لفض فضل الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (113, 'quran:2:106', 'quran', 'quran', '2:106', 106, 112, 'Al-Baqarah', 'البقرة', 'مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', NULL, NULL, 'ما ننسخ من ايه او ننسها نات بخير منها او مثلها الم تعلم ان الله علي كل شيء قدير', 'م ننسخ من اي او ننس نت بخير من او مثل الم تعلم ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (113, 'م ننس نسخ من ايه او ننس نسه نت بخي خير منه او مثل ثله الم تعل علم ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (114, 'quran:2:107', 'quran', 'quran', '2:107', 107, 113, 'Al-Baqarah', 'البقرة', 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ', NULL, NULL, 'الم تعلم ان الله له ملك السموت والارض وما لكم من دون الله من ولي ولا نصير', 'الم تعلم ان له له ملك سموت ارض وم لكم من دون له من ول ول نصير', 'quran', NULL, NULL, 'https://quran.com/2/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (114, 'الم تعل علم ان الل لله له ملك الس لسم سمو موت ولر لرض وم لكم من دون الل لله من ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (115, 'quran:2:108', 'quran', 'quran', '2:108', 108, 114, 'Al-Baqarah', 'البقرة', 'أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', NULL, NULL, 'ام تريدون ان تسلوا رسولكم كما سيل موسي من قبل ومن يتبدل الكفر بالايمن فقد ضل سواء السبيل', 'ام تريد ان تسل رسول كم سيل موس من قبل ومن يتبدل كفر ايمن فقد ضل سوء سبيل', 'quran', NULL, NULL, 'https://quran.com/2/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (115, 'ام تري ريد يدو دون ان تسل سلو رسو سول ولك لكم كم سيل موس وسي من قبل ومن يتب تبد بدل الك لكف كفر بلي ليم يمن فقد ضل سوء الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (116, 'quran:2:109', 'quran', 'quran', '2:109', 109, 115, 'Al-Baqarah', 'البقرة', 'وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'ود كثير من اهل الكتب لو يردونكم من بعد ايمنكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتي ياتي الله بامره ان الله علي كل شيء قدير', 'ود كثير من اهل كتب لو يردون من بعد ايمن كفر حسد من عند انفس من بعد م تب لهم حق اعف اصفح حت يت له بمر ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (116, 'ود كثي ثير من اهل الك لكت كتب لو يرد ردو دون ونك نكم من بعد ايم يمن منك نكم كفر حسد من عند انف نفس فسه سهم من بعد م تبي بين لهم الح لحق فعف عفو وصف صفح فحو حتي يتي الل لله بمر مره ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (117, 'quran:2:110', 'quran', 'quran', '2:110', 110, 116, 'Al-Baqarah', 'البقرة', 'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ', NULL, NULL, 'واقيموا الصلاه واتوا الزكاه وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير', 'اقيم صل ات زك وم تقدم لنفس من خير تجدو عند له ان له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/2/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (117, 'وقي قيم يمو الص لصل صله وتو الز لزك زكه وم تقد قدم دمو لنف نفس فسك سكم من خير تجد جدو دوه عند الل لله ان الل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (118, 'quran:2:111', 'quran', 'quran', '2:111', 111, 117, 'Al-Baqarah', 'البقرة', 'وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'وقالوا لن يدخل الجنه الا من كان هودا او نصري تلك امانيهم قل هاتوا برهنكم ان كنتم صدقين', 'قل لن يدخل جن ال من كن هود او نصر تلك امني قل هت برهن ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/2/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (118, 'وقل قلو لن يدخ دخل الج لجن جنه ال من كن هود او نصر صري تلك امن مني نيه يهم قل هتو بره رهن هنك نكم ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (119, 'quran:2:112', 'quran', 'quran', '2:112', 112, 118, 'Al-Baqarah', 'البقرة', 'بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'بلي من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون', 'بل من اسلم جه لل وهو محسن فل اجر عند رب ول خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (119, 'بلي من اسل سلم وجه جهه لله وهو محس حسن فله اجر جره عند ربه ول خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (120, 'quran:2:113', 'quran', 'quran', '2:113', 113, 119, 'Al-Baqarah', 'البقرة', 'وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ', NULL, NULL, 'وقالت اليهود ليست النصري علي شيء وقالت النصري ليست اليهود علي شيء وهم يتلون الكتب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيمه فيما كانوا فيه يختلفون', 'قلت يهود ليست نصر عل شيء قلت نصر ليست يهود عل شيء وهم يتل كتب كذلك قل ذين ل يعلم مثل قول له يح بين يوم قيم يم كن في يختلف', 'quran', NULL, NULL, 'https://quran.com/2/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (120, 'وقل قلت الي ليه يهو هود ليس يست الن لنص نصر صري علي شيء وقل قلت الن لنص نصر صري ليس يست الي ليه يهو هود علي شيء وهم يتل تلو لون الك لكت كتب كذل ذلك قل الذ لذي ذين ل يعل علم لمو مون مثل قول وله لهم فلل لله يحك حكم بين ينه نهم يوم الق لقي قيم يمه فيم كنو فيه يخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (121, 'quran:2:114', 'quran', 'quran', '2:114', 114, 120, 'Al-Baqarah', 'البقرة', 'وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ', NULL, NULL, 'ومن اظلم ممن منع مسجد الله ان يذكر فيها اسمه وسعي في خرابها اوليك ما كان لهم ان يدخلوها الا خايفين لهم في الدنيا خزي ولهم في الاخره عذاب عظيم', 'ومن اظلم ممن منع مسجد له ان يذكر يه اسم سع في خرب اوليك م كن لهم ان يدخلو ال خيف لهم في دني خز لهم في اخر عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/2/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (121, 'ومن اظل ظلم ممن منع مسج سجد الل لله ان يذك ذكر فيه اسم سمه وسع سعي في خرب ربه اول ولي ليك م كن لهم ان يدخ دخل خلو لوه ال خيف يفي فين لهم في الد لدن دني خزي وله لهم في الخ لخر خره عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (122, 'quran:2:115', 'quran', 'quran', '2:115', 115, 121, 'Al-Baqarah', 'البقرة', 'وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ', NULL, NULL, 'ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم', 'لل مشرق مغرب اينم تول فثم وج له ان له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/2/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (122, 'ولل لله الم لمش مشر شرق ولم لمغ مغر غرب فين ينم تول ولو فثم وجه الل لله ان الل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (123, 'quran:2:116', 'quran', 'quran', '2:116', 116, 122, 'Al-Baqarah', 'البقرة', 'وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ', NULL, NULL, 'وقالوا اتخذ الله ولدا سبحنه بل له ما في السموت والارض كل له قنتون', 'قل اتخذ له لد سبحن بل له م في سموت ارض كل له قنت', 'quran', NULL, NULL, 'https://quran.com/2/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (123, 'وقل قلو اتخ تخذ الل لله ولد سبح بحن حنه بل له م في الس لسم سمو موت ولر لرض كل له قنت نتو تون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (124, 'quran:2:117', 'quran', 'quran', '2:117', 117, 123, 'Al-Baqarah', 'البقرة', 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', NULL, NULL, 'بديع السموت والارض واذا قضي امرا فانما يقول له كن فيكون', 'بديع سموت ارض اذ قض امر انم يقول له كن يك', 'quran', NULL, NULL, 'https://quran.com/2/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (124, 'بدي ديع الس لسم سمو موت ولر لرض وذ قضي امر فنم يقو قول له كن فيك يكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (125, 'quran:2:118', 'quran', 'quran', '2:118', 118, 124, 'Al-Baqarah', 'البقرة', 'وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ', NULL, NULL, 'وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا ايه كذلك قال الذين من قبلهم مثل قولهم تشبهت قلوبهم قد بينا الايت لقوم يوقنون', 'قل ذين ل يعلم لول يكلم له او تتي اي كذلك قل ذين من قبل مثل قول تشبهت قلوب قد بي ايت لقوم يوقن', 'quran', NULL, NULL, 'https://quran.com/2/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (125, 'وقل الذ لذي ذين ل يعل علم لمو مون لول يكل كلم لمن الل لله او تتي تين ايه كذل ذلك قل الذ لذي ذين من قبل بله لهم مثل قول وله لهم تشب شبه بهت قلو لوب وبه بهم قد بين الي ليت لقو قوم يوق وقن قنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (126, 'quran:2:119', 'quran', 'quran', '2:119', 119, 125, 'Al-Baqarah', 'البقرة', 'إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ', NULL, NULL, 'انا ارسلنك بالحق بشيرا ونذيرا ولا تسل عن اصحب الجحيم', 'ان ارسلنك حق بشير نذير ول تسل عن اصحب جحيم', 'quran', NULL, NULL, 'https://quran.com/2/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (126, 'ان ارس رسل سلن لنك بلح لحق بشي شير ونذ نذي ذير ول تسل عن اصح صحب الج لجح جحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (127, 'quran:2:120', 'quran', 'quran', '2:120', 120, 126, 'Al-Baqarah', 'البقرة', 'وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ', NULL, NULL, 'ولن ترضي عنك اليهود ولا النصري حتي تتبع ملتهم قل ان هدي الله هو الهدي ولين اتبعت اهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير', 'ولن ترض عنك يهود ول نصر حت تتبع ملت قل ان هد له هو هد لين اتبعت اهوء بعد ذي جءك من علم م لك من له من ول ول نصير', 'quran', NULL, NULL, 'https://quran.com/2/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (127, 'ولن ترض رضي عنك الي ليه يهو هود ول الن لنص نصر صري حتي تتب تبع ملت لته تهم قل ان هدي الل لله هو اله لهد هدي ولي لين اتب تبع بعت اهو هوء وءه ءهم بعد الذ لذي جءك من الع لعل علم م لك من الل لله من ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (128, 'quran:2:121', 'quran', 'quran', '2:121', 121, 127, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', NULL, NULL, 'الذين اتينهم الكتب يتلونه حق تلاوته اوليك يومنون به ومن يكفر به فاوليك هم الخسرون', 'ذين اتين كتب يتلون حق تلوت اوليك يومن به ومن يكفر به اوليك هم خسر', 'quran', NULL, NULL, 'https://quran.com/2/121');
INSERT INTO units_tri_src (id, ar_tri) VALUES (128, 'الذ لذي ذين اتي تين ينه نهم الك لكت كتب يتل تلو لون ونه حق تلو لوت وته اول ولي ليك يوم ومن منو نون به ومن يكف كفر به فول ولي ليك هم الخ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (129, 'quran:2:122', 'quran', 'quran', '2:122', 122, 128, 'Al-Baqarah', 'البقرة', 'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ', NULL, NULL, 'يا بني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين', 'ي بن اسرءيل اذكر نعمت تي انعمت علي ان ضلت عل علم', 'quran', NULL, NULL, 'https://quran.com/2/122');
INSERT INTO units_tri_src (id, ar_tri) VALUES (129, 'ي بني اسر سرء رءي ءيل اذك ذكر كرو نعم عمت متي الت لتي انع نعم عمت علي ليك يكم وني فضل ضلت لتك تكم علي الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (130, 'quran:2:123', 'quran', 'quran', '2:123', 123, 129, 'Al-Baqarah', 'البقرة', 'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمۡ يُنصَرُونَ', NULL, NULL, 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها عدل ولا تنفعها شفعه ولا هم ينصرون', 'اتق يوم ل تجز نفس عن نفس شي ول يقبل من عدل ول تنفع شفع ول هم ينصر', 'quran', NULL, NULL, 'https://quran.com/2/123');
INSERT INTO units_tri_src (id, ar_tri) VALUES (130, 'وتق تقو يوم ل تجز جزي نفس عن نفس شي ول يقب قبل منه عدل ول تنف نفع فعه شفع فعه ول هم ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (131, 'quran:2:124', 'quran', 'quran', '2:124', 124, 130, 'Al-Baqarah', 'البقرة', 'وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ', NULL, NULL, 'واذ ابتلي ابرهم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظلمين', 'وذ ابتل ابر رب بكلمت اتم قل ان جعلك نس امم قل ومن ذريت قل ل ينل عهد ظلم', 'quran', NULL, NULL, 'https://quran.com/2/124');
INSERT INTO units_tri_src (id, ar_tri) VALUES (131, 'وذ ابت بتل تلي ابر بره رهم ربه بكل كلم لمت فتم تمه مهن قل اني جعل علك للن لنس امم قل ومن ذري ريت يتي قل ل ينل عهد هدي الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (132, 'quran:2:125', 'quran', 'quran', '2:125', 125, 131, 'Al-Baqarah', 'البقرة', 'وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', NULL, NULL, 'واذ جعلنا البيت مثابه للناس وامنا واتخذوا من مقام ابرهم مصلي وعهدنا الي ابرهم واسمعيل ان طهرا بيتي للطايفين والعكفين والركع السجود', 'وذ جعل بيت مثب نس ام اتخذ من مقم ابر مصل عهد ال ابر اسمعيل ان طهر بيت طيف عكف ركع سجود', 'quran', NULL, NULL, 'https://quran.com/2/125');
INSERT INTO units_tri_src (id, ar_tri) VALUES (132, 'وذ جعل علن الب لبي بيت مثب ثبه للن لنس ومن وتخ تخذ خذو من مقم ابر بره رهم مصل صلي وعه عهد هدن الي ابر بره رهم وسم سمع معي عيل ان طهر بيت يتي للط لطي طيف يفي فين ولع لعك عكف كفي فين ولر لرك ركع الس لسج سجو جود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (133, 'quran:2:126', 'quran', 'quran', '2:126', 126, 132, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ', NULL, NULL, 'واذ قال ابرهم رب اجعل هذا بلدا امنا وارزق اهله من الثمرت من امن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الي عذاب النار وبيس المصير', 'وذ قل ابر رب اجعل هذ بلد ام ارزق اهل من ثمرت من امن من له يوم اخر قل ومن كفر امتع قليل ثم اضطر ال عذب نر بيس مصير', 'quran', NULL, NULL, 'https://quran.com/2/126');
INSERT INTO units_tri_src (id, ar_tri) VALUES (133, 'وذ قل ابر بره رهم رب اجع جعل هذ بلد امن ورز رزق اهل هله من الث لثم ثمر مرت من امن منه نهم بلل لله ولي ليو يوم الخ لخر قل ومن كفر فمت متع تعه قلي ليل ثم اضط ضطر طره الي عذب الن لنر وبي بيس الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (134, 'quran:2:127', 'quran', 'quran', '2:127', 127, 133, 'Al-Baqarah', 'البقرة', 'وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'واذ يرفع ابرهم القواعد من البيت واسمعيل ربنا تقبل منا انك انت السميع العليم', 'وذ يرفع ابر قوعد من بيت اسمعيل رب تقبل من انك انت سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/127');
INSERT INTO units_tri_src (id, ar_tri) VALUES (134, 'وذ يرف رفع ابر بره رهم الق لقو قوع وعد من الب لبي بيت وسم سمع معي عيل ربن تقب قبل من انك انت الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (135, 'quran:2:128', 'quran', 'quran', '2:128', 128, 134, 'Al-Baqarah', 'البقرة', 'رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', NULL, NULL, 'ربنا واجعلنا مسلمين لك ومن ذريتنا امه مسلمه لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم', 'رب اجعل مسلم لك ومن ذريت ام مسلم لك ار منسك وتب علي انك انت توب رحيم', 'quran', NULL, NULL, 'https://quran.com/2/128');
INSERT INTO units_tri_src (id, ar_tri) VALUES (135, 'ربن وجع جعل علن مسل سلم لمي مين لك ومن ذري ريت يتن امه مسل سلم لمه لك ورن منس نسك سكن وتب علي لين انك انت الت لتو توب الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (136, 'quran:2:129', 'quran', 'quran', '2:129', 129, 135, 'Al-Baqarah', 'البقرة', 'رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'ربنا وابعث فيهم رسولا منهم يتلوا عليهم ايتك ويعلمهم الكتب والحكمه ويزكيهم انك انت العزيز الحكيم', 'رب ابعث يهم رسول من يتل علي ايتك يعلم كتب حكم يزكي انك انت عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/129');
INSERT INTO units_tri_src (id, ar_tri) VALUES (136, 'ربن وبع بعث فيه يهم رسو سول منه نهم يتل تلو علي ليه يهم ايت يتك ويع يعل علم لمه مهم الك لكت كتب ولح لحك حكم كمه ويز يزك زكي كيه يهم انك انت الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (137, 'quran:2:130', 'quran', 'quran', '2:130', 130, 136, 'Al-Baqarah', 'البقرة', 'وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'ومن يرغب عن مله ابرهم الا من سفه نفسه ولقد اصطفينه في الدنيا وانه في الاخره لمن الصلحين', 'ومن يرغب عن مل ابر ال من سف نفس لقد اصطفين في دني ان في اخر لمن صلح', 'quran', NULL, NULL, 'https://quran.com/2/130');
INSERT INTO units_tri_src (id, ar_tri) VALUES (137, 'ومن يرغ رغب عن مله ابر بره رهم ال من سفه نفس فسه ولق لقد اصط صطف طفي فين ينه في الد لدن دني ونه في الخ لخر خره لمن الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (138, 'quran:2:131', 'quran', 'quran', '2:131', 131, 137, 'Al-Baqarah', 'البقرة', 'إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'اذ قال له ربه اسلم قال اسلمت لرب العلمين', 'اذ قل له رب اسلم قل اسلمت لرب علم', 'quran', NULL, NULL, 'https://quran.com/2/131');
INSERT INTO units_tri_src (id, ar_tri) VALUES (138, 'اذ قل له ربه اسل سلم قل اسل سلم لمت لرب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (139, 'quran:2:132', 'quran', 'quran', '2:132', 132, 138, 'Al-Baqarah', 'البقرة', 'وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ', NULL, NULL, 'ووصي بها ابرهم بنيه ويعقوب يا بني ان الله اصطفي لكم الدين فلا تموتن الا وانتم مسلمون', 'وص به ابر بن يعقوب ي بن ان له اصطف لكم دين فل تموتن ال انتم مسلم', 'quran', NULL, NULL, 'https://quran.com/2/132');
INSERT INTO units_tri_src (id, ar_tri) VALUES (139, 'ووص وصي به ابر بره رهم بني نيه ويع يعق عقو قوب ي بني ان الل لله اصط صطف طفي لكم الد لدي دين فل تمو موت وتن ال ونت نتم مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (140, 'quran:2:133', 'quran', 'quran', '2:133', 133, 139, 'Al-Baqarah', 'البقرة', 'أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', NULL, NULL, 'ام كنتم شهداء اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ابايك ابرهم واسمعيل واسحق الها وحدا ونحن له مسلمون', 'ام كنتم شهدء اذ حضر يعقوب موت اذ قل لبن م تعبد من بعد قل نعبد هك ول ابيك ابر اسمعيل اسحق ه حد نحن له مسلم', 'quran', NULL, NULL, 'https://quran.com/2/133');
INSERT INTO units_tri_src (id, ar_tri) VALUES (140, 'ام كنت نتم شهد هدء اذ حضر يعق عقو قوب الم لمو موت اذ قل لبن بني نيه م تعب عبد بدو دون من بعد عدي قلو نعب عبد اله لهك وله ابي بيك ابر بره رهم وسم سمع معي عيل وسح سحق اله وحد ونح نحن له مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (141, 'quran:2:134', 'quran', 'quran', '2:134', 134, 140, 'Al-Baqarah', 'البقرة', 'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون', 'تلك ام قد خلت له م كسبت لكم م كسبتم ول تسل عم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/2/134');
INSERT INTO units_tri_src (id, ar_tri) VALUES (141, 'تلك امه قد خلت له م كسب سبت ولك لكم م كسب سبت بتم ول تسل سلو لون عم كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (142, 'quran:2:135', 'quran', 'quran', '2:135', 135, 141, 'Al-Baqarah', 'البقرة', 'وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'وقالوا كونوا هودا او نصري تهتدوا قل بل مله ابرهم حنيفا وما كان من المشركين', 'قل كون هود او نصر تهتد قل بل مل ابر حنيف وم كن من مشرك', 'quran', NULL, NULL, 'https://quran.com/2/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (142, 'وقل قلو كون ونو هود او نصر صري تهت هتد تدو قل بل مله ابر بره رهم حني نيف وم كن من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (143, 'quran:2:136', 'quran', 'quran', '2:136', 136, 142, 'Al-Baqarah', 'البقرة', 'قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', NULL, NULL, 'قولوا امنا بالله وما انزل الينا وما انزل الي ابرهم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون', 'قول ام له وم انزل ين وم انزل ال ابر اسمعيل اسحق يعقوب اسبط وم اوت موس عيس وم اوت نبي من رب ل نفرق بين احد من نحن له مسلم', 'quran', NULL, NULL, 'https://quran.com/2/136');
INSERT INTO units_tri_src (id, ar_tri) VALUES (143, 'قول ولو امن بلل لله وم انز نزل الي لين وم انز نزل الي ابر بره رهم وسم سمع معي عيل وسح سحق ويع يعق عقو قوب ولس لسب سبط وم اوت وتي موس وسي وعي عيس يسي وم اوت وتي الن لنب نبي بيو يون من ربه بهم ل نفر فرق بين احد منه نهم ونح نحن له مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (144, 'quran:2:137', 'quran', 'quran', '2:137', 137, 143, 'Al-Baqarah', 'البقرة', 'فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'فان امنوا بمثل ما امنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم', 'فن امن بمثل م امنتم به فقد اهتد ون تول انم هم في شقق سيكفيك له وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/137');
INSERT INTO units_tri_src (id, ar_tri) VALUES (144, 'فن امن منو بمث مثل م امن منت نتم به فقد اهت هتد تدو ون تول ولو فنم هم في شقق فسي سيك يكف كفي فيك يكه كهم الل لله وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (145, 'quran:2:138', 'quran', 'quran', '2:138', 138, 144, 'Al-Baqarah', 'البقرة', 'صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ', NULL, NULL, 'صبغه الله ومن احسن من الله صبغه ونحن له عبدون', 'صبغ له ومن احسن من له صبغ نحن له عبد', 'quran', NULL, NULL, 'https://quran.com/2/138');
INSERT INTO units_tri_src (id, ar_tri) VALUES (145, 'صبغ بغه الل لله ومن احس حسن من الل لله صبغ بغه ونح نحن له عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (146, 'quran:2:139', 'quran', 'quran', '2:139', 139, 145, 'Al-Baqarah', 'البقرة', 'قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ', NULL, NULL, 'قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعملنا ولكم اعملكم ونحن له مخلصون', 'قل اتحجون في له وهو رب رب لن اعمل لكم اعمل نحن له مخلص', 'quran', NULL, NULL, 'https://quran.com/2/139');
INSERT INTO units_tri_src (id, ar_tri) VALUES (146, 'قل اتح تحج حجو جون ونن في الل لله وهو ربن ورب ربك بكم ولن اعم عمل ملن ولك لكم اعم عمل ملك لكم ونح نحن له مخل خلص لصو صون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (147, 'quran:2:140', 'quran', 'quran', '2:140', 140, 146, 'Al-Baqarah', 'البقرة', 'أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', NULL, NULL, 'ام تقولون ان ابرهم واسمعيل واسحق ويعقوب والاسباط كانوا هودا او نصري قل انتم اعلم ام الله ومن اظلم ممن كتم شهده عنده من الله وما الله بغفل عما تعملون', 'ام تقول ان ابر اسمعيل اسحق يعقوب اسبط كن هود او نصر قل انتم اعلم ام له ومن اظلم ممن كتم شهد عند من له وم له بغفل عم تعمل', 'quran', NULL, NULL, 'https://quran.com/2/140');
INSERT INTO units_tri_src (id, ar_tri) VALUES (147, 'ام تقو قول ولو لون ان ابر بره رهم وسم سمع معي عيل وسح سحق ويع يعق عقو قوب ولس لسب سبط كنو هود او نصر صري قل انت نتم اعل علم ام الل لله ومن اظل ظلم ممن كتم شهد هده عند نده من الل لله وم الل لله بغف غفل عم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (148, 'quran:2:141', 'quran', 'quran', '2:141', 141, 147, 'Al-Baqarah', 'البقرة', 'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون', 'تلك ام قد خلت له م كسبت لكم م كسبتم ول تسل عم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/2/141');
INSERT INTO units_tri_src (id, ar_tri) VALUES (148, 'تلك امه قد خلت له م كسب سبت ولك لكم م كسب سبت بتم ول تسل سلو لون عم كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (149, 'quran:2:142', 'quran', 'quran', '2:142', 142, 148, 'Al-Baqarah', 'البقرة', 'سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'سيقول السفهاء من الناس ما ولاهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء الي صرط مستقيم', 'سيقول سفهء من نس م ل عن قبلت تي كن علي قل لل مشرق مغرب يهد من يشء ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/2/142');
INSERT INTO units_tri_src (id, ar_tri) VALUES (149, 'سيق يقو قول الس لسف سفه فهء من الن لنس م وله لهم عن قبل بلت لته تهم الت لتي كنو علي ليه قل لله الم لمش مشر شرق ولم لمغ مغر غرب يهد هدي من يشء الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (150, 'quran:2:143', 'quran', 'quran', '2:143', 143, 149, 'Al-Baqarah', 'البقرة', 'وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ', NULL, NULL, 'وكذلك جعلنكم امه وسطا لتكونوا شهداء علي الناس ويكون الرسول عليكم شهيدا وما جعلنا القبله التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب علي عقبيه وان كانت لكبيره الا علي الذين هدي الله وما كان الله ليضيع ايمنكم ان الله بالناس لرءوف رحيم', 'كذلك جعلن ام سط لتكون شهدء عل نس يك رسول علي شهيد وم جعل قبل تي كنت علي ال لنعلم من يتبع رسول ممن ينقلب عل عقب ون كنت لكبير ال عل ذين هد له وم كن له ليضيع ايمن ان له نس لرءوف رحيم', 'quran', NULL, NULL, 'https://quran.com/2/143');
INSERT INTO units_tri_src (id, ar_tri) VALUES (150, 'وكذ كذل ذلك جعل علن لنك نكم امه وسط لتك تكو كون ونو شهد هدء علي الن لنس ويك يكو كون الر لرس رسو سول علي ليك يكم شهي هيد وم جعل علن الق لقب قبل بله الت لتي كنت علي ليه ال لنع نعل علم من يتب تبع الر لرس رسو سول ممن ينق نقل قلب علي عقب قبي بيه ون كنت لكب كبي بير يره ال علي الذ لذي ذين هدي الل لله وم كن الل لله ليض يضي ضيع ايم يمن منك نكم ان الل لله بلن لنس لرء رءو ءوف رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (151, 'quran:2:144', 'quran', 'quran', '2:144', 144, 150, 'Al-Baqarah', 'البقرة', 'قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ', NULL, NULL, 'قد نري تقلب وجهك في السماء فلنولينك قبله ترضاها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتب ليعلمون انه الحق من ربهم وما الله بغفل عما يعملون', 'قد نر تقلب جهك في سمء لنولينك قبل ترض فول جهك شطر مسجد حرم حيث م كنتم ول جوه شطر ون ذين اوت كتب ليعلم ان حق من رب وم له بغفل عم يعمل', 'quran', NULL, NULL, 'https://quran.com/2/144');
INSERT INTO units_tri_src (id, ar_tri) VALUES (151, 'قد نري تقل قلب وجه جهك في الس لسم سمء فلن لنو نول ولي لين ينك قبل بله ترض رضه فول وجه جهك شطر الم لمس مسج سجد الح لحر حرم وحي حيث م كنت نتم فول ولو وجو جوه وهك هكم شطر طره ون الذ لذي ذين اوت وتو الك لكت كتب ليع يعل علم لمو مون انه الح لحق من ربه بهم وم الل لله بغف غفل عم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (152, 'quran:2:145', 'quran', 'quran', '2:145', 145, 151, 'Al-Baqarah', 'البقرة', 'وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'ولين اتيت الذين اوتوا الكتب بكل ايه ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبله بعض ولين اتبعت اهواءهم من بعد ما جاءك من العلم انك اذا لمن الظلمين', 'لين اتيت ذين اوت كتب بكل اي م تبع قبلتك وم انت بتبع قبلت وم بعض بتبع قبل بعض لين اتبعت اهوء من بعد م جءك من علم انك اذ لمن ظلم', 'quran', NULL, NULL, 'https://quran.com/2/145');
INSERT INTO units_tri_src (id, ar_tri) VALUES (152, 'ولي لين اتي تيت الذ لذي ذين اوت وتو الك لكت كتب بكل ايه م تبع بعو قبل بلت لتك وم انت بتب تبع قبل بلت لته تهم وم بعض عضه ضهم بتب تبع قبل بله بعض ولي لين اتب تبع بعت اهو هوء وءه ءهم من بعد م جءك من الع لعل علم انك اذ لمن الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (153, 'quran:2:146', 'quran', 'quran', '2:146', 146, 152, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'الذين اتينهم الكتب يعرفونه كما يعرفون ابناءهم وان فريقا منهم ليكتمون الحق وهم يعلمون', 'ذين اتين كتب يعرفون كم يعرف ابنء ون ريق من ليكتم حق وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/2/146');
INSERT INTO units_tri_src (id, ar_tri) VALUES (153, 'الذ لذي ذين اتي تين ينه نهم الك لكت كتب يعر عرف رفو فون ونه كم يعر عرف رفو فون ابن بنء نءه ءهم ون فري ريق منه نهم ليك يكت كتم تمو مون الح لحق وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (154, 'quran:2:147', 'quran', 'quran', '2:147', 147, 153, 'Al-Baqarah', 'البقرة', 'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ', NULL, NULL, 'الحق من ربك فلا تكونن من الممترين', 'حق من ربك فل تكونن من ممتر', 'quran', NULL, NULL, 'https://quran.com/2/147');
INSERT INTO units_tri_src (id, ar_tri) VALUES (154, 'الح لحق من ربك فل تكو كون ونن من الم لمم ممت متر تري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (155, 'quran:2:148', 'quran', 'quran', '2:148', 148, 154, 'Al-Baqarah', 'البقرة', 'وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'ولكل وجهه هو موليها فاستبقوا الخيرت اين ما تكونوا يات بكم الله جميعا ان الله علي كل شيء قدير', 'لكل جه هو مولي استبق خيرت اين م تكون يت بكم له جميع ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/148');
INSERT INTO units_tri_src (id, ar_tri) VALUES (155, 'ولك لكل وجه جهه هو مول ولي ليه فست ستب تبق بقو الخ لخي خير يرت اين م تكو كون ونو يت بكم الل لله جمي ميع ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (156, 'quran:2:149', 'quran', 'quran', '2:149', 149, 155, 'Al-Baqarah', 'البقرة', 'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', NULL, NULL, 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغفل عما تعملون', 'ومن حيث خرجت فول جهك شطر مسجد حرم ان حق من ربك وم له بغفل عم تعمل', 'quran', NULL, NULL, 'https://quran.com/2/149');
INSERT INTO units_tri_src (id, ar_tri) VALUES (156, 'ومن حيث خرج رجت فول وجه جهك شطر الم لمس مسج سجد الح لحر حرم ونه للح لحق من ربك وم الل لله بغف غفل عم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (157, 'quran:2:150', 'quran', 'quran', '2:150', 150, 156, 'Al-Baqarah', 'البقرة', 'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ', NULL, NULL, 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره ليلا يكون للناس عليكم حجه الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون', 'ومن حيث خرجت فول جهك شطر مسجد حرم حيث م كنتم ول جوه شطر ليل يك نس علي حج ال ذين ظلم من فل تخشو اخشون لتم نعمت علي لعل تهتد', 'quran', NULL, NULL, 'https://quran.com/2/150');
INSERT INTO units_tri_src (id, ar_tri) VALUES (157, 'ومن حيث خرج رجت فول وجه جهك شطر الم لمس مسج سجد الح لحر حرم وحي حيث م كنت نتم فول ولو وجو جوه وهك هكم شطر طره ليل يكو كون للن لنس علي ليك يكم حجه ال الذ لذي ذين ظلم لمو منه نهم فل تخش خشو شوه وهم وخش خشو شون وني ولت لتم نعم عمت متي علي ليك يكم ولع لعل علك لكم تهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (158, 'quran:2:151', 'quran', 'quran', '2:151', 151, 157, 'Al-Baqarah', 'البقرة', 'كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ', NULL, NULL, 'كما ارسلنا فيكم رسولا منكم يتلوا عليكم ايتنا ويزكيكم ويعلمكم الكتب والحكمه ويعلمكم ما لم تكونوا تعلمون', 'كم ارسل يكم رسول من يتل علي ايت يزكي يعلم كتب حكم يعلم م لم تكون تعلم', 'quran', NULL, NULL, 'https://quran.com/2/151');
INSERT INTO units_tri_src (id, ar_tri) VALUES (158, 'كم ارس رسل سلن فيك يكم رسو سول منك نكم يتل تلو علي ليك يكم ايت يتن ويز يزك زكي كيك يكم ويع يعل علم لمك مكم الك لكت كتب ولح لحك حكم كمه ويع يعل علم لمك مكم م لم تكو كون ونو تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (159, 'quran:2:152', 'quran', 'quran', '2:152', 152, 158, 'Al-Baqarah', 'البقرة', 'فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ', NULL, NULL, 'فاذكروني اذكركم واشكروا لي ولا تكفرون', 'اذكرون اذكر اشكر لي ول تكفر', 'quran', NULL, NULL, 'https://quran.com/2/152');
INSERT INTO units_tri_src (id, ar_tri) VALUES (159, 'فذك ذكر كرو رون وني اذك ذكر كرك ركم وشك شكر كرو لي ول تكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (160, 'quran:2:153', 'quran', 'quran', '2:153', 153, 159, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', NULL, NULL, 'يا ايها الذين امنوا استعينوا بالصبر والصلاه ان الله مع الصبرين', 'ي اي ذين امن استعين صبر صل ان له مع صبر', 'quran', NULL, NULL, 'https://quran.com/2/153');
INSERT INTO units_tri_src (id, ar_tri) VALUES (160, 'ي ايه الذ لذي ذين امن منو است ستع تعي عين ينو بلص لصب صبر ولص لصل صله ان الل لله مع الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (161, 'quran:2:154', 'quran', 'quran', '2:154', 154, 160, 'Al-Baqarah', 'البقرة', 'وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ', NULL, NULL, 'ولا تقولوا لمن يقتل في سبيل الله اموت بل احياء ولكن لا تشعرون', 'ول تقول لمن يقتل في سبيل له اموت بل احيء لكن ل تشعر', 'quran', NULL, NULL, 'https://quran.com/2/154');
INSERT INTO units_tri_src (id, ar_tri) VALUES (161, 'ول تقو قول ولو لمن يقت قتل في سبي بيل الل لله امو موت بل احي حيء ولك لكن ل تشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (162, 'quran:2:155', 'quran', 'quran', '2:155', 155, 161, 'Al-Baqarah', 'البقرة', 'وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ', NULL, NULL, 'ولنبلونكم بشيء من الخوف والجوع ونقص من الامول والانفس والثمرت وبشر الصبرين', 'لنبلون بشيء من خوف جوع نقص من امول انفس ثمرت بشر صبر', 'quran', NULL, NULL, 'https://quran.com/2/155');
INSERT INTO units_tri_src (id, ar_tri) VALUES (162, 'ولن لنب نبل بلو لون ونك نكم بشي شيء من الخ لخو خوف ولج لجو جوع ونق نقص من الم لمو مول ولن لنف نفس ولث لثم ثمر مرت وبش بشر الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (163, 'quran:2:156', 'quran', 'quran', '2:156', 156, 162, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ', NULL, NULL, 'الذين اذا اصبتهم مصيبه قالوا انا لله وانا اليه رجعون', 'ذين اذ اصبت مصيب قل ان لل ان يه رجع', 'quran', NULL, NULL, 'https://quran.com/2/156');
INSERT INTO units_tri_src (id, ar_tri) VALUES (163, 'الذ لذي ذين اذ اصب صبت بته تهم مصي صيب يبه قلو ان لله ون الي ليه رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (164, 'quran:2:157', 'quran', 'quran', '2:157', 157, 163, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ', NULL, NULL, 'اوليك عليهم صلوت من ربهم ورحمه واوليك هم المهتدون', 'اوليك علي صلوت من رب رحم اوليك هم مهتد', 'quran', NULL, NULL, 'https://quran.com/2/157');
INSERT INTO units_tri_src (id, ar_tri) VALUES (164, 'اول ولي ليك علي ليه يهم صلو لوت من ربه بهم ورح رحم حمه وول ولي ليك هم الم لمه مهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (165, 'quran:2:158', 'quran', 'quran', '2:158', 158, 164, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', NULL, NULL, 'ان الصفا والمروه من شعاير الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم', 'ان صف مرو من شعير له فمن حج بيت او اعتمر فل جنح عل ان يطوف بهم ومن تطوع خير فن له شكر عليم', 'quran', NULL, NULL, 'https://quran.com/2/158');
INSERT INTO units_tri_src (id, ar_tri) VALUES (165, 'ان الص لصف ولم لمر مرو روه من شعي عير الل لله فمن حج الب لبي بيت او اعت عتم تمر فل جنح علي ليه ان يطو طوف بهم ومن تطو طوع خير فن الل لله شكر علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (166, 'quran:2:159', 'quran', 'quran', '2:159', 159, 165, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّٰعِنُونَ', NULL, NULL, 'ان الذين يكتمون ما انزلنا من البينت والهدي من بعد ما بينه للناس في الكتب اوليك يلعنهم الله ويلعنهم اللعنون', 'ان ذين يكتم م انزل من بينت هد من بعد م بين نس في كتب اوليك يلعن له يلعن لعن', 'quran', NULL, NULL, 'https://quran.com/2/159');
INSERT INTO units_tri_src (id, ar_tri) VALUES (166, 'ان الذ لذي ذين يكت كتم تمو مون م انز نزل زلن من الب لبي بين ينت وله لهد هدي من بعد م بين ينه للن لنس في الك لكت كتب اول ولي ليك يلع لعن عنه نهم الل لله ويل يلع لعن عنه نهم الل للع لعن عنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (167, 'quran:2:160', 'quran', 'quran', '2:160', 160, 166, 'Al-Baqarah', 'البقرة', 'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', NULL, NULL, 'الا الذين تابوا واصلحوا وبينوا فاوليك اتوب عليهم وانا التواب الرحيم', 'ال ذين تب اصلح بين اوليك اتوب علي ان توب رحيم', 'quran', NULL, NULL, 'https://quran.com/2/160');
INSERT INTO units_tri_src (id, ar_tri) VALUES (167, 'ال الذ لذي ذين تبو وصل صلح لحو وبي بين ينو فول ولي ليك اتو توب علي ليه يهم ون الت لتو توب الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (168, 'quran:2:161', 'quran', 'quran', '2:161', 161, 167, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ', NULL, NULL, 'ان الذين كفروا وماتوا وهم كفار اوليك عليهم لعنه الله والمليكه والناس اجمعين', 'ان ذين كفر مت وهم كفر اوليك علي لعن له مليك نس اجمع', 'quran', NULL, NULL, 'https://quran.com/2/161');
INSERT INTO units_tri_src (id, ar_tri) VALUES (168, 'ان الذ لذي ذين كفر فرو ومت متو وهم كفر اول ولي ليك علي ليه يهم لعن عنه الل لله ولم لمل ملي ليك يكه ولن لنس اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (169, 'quran:2:162', 'quran', 'quran', '2:162', 162, 168, 'Al-Baqarah', 'البقرة', 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ', NULL, NULL, 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون', 'خلد يه ل يخفف عن عذب ول هم ينظر', 'quran', NULL, NULL, 'https://quran.com/2/162');
INSERT INTO units_tri_src (id, ar_tri) VALUES (169, 'خلد لدي دين فيه ل يخف خفف عنه نهم الع لعذ عذب ول هم ينظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (170, 'quran:2:163', 'quran', 'quran', '2:163', 163, 169, 'Al-Baqarah', 'البقرة', 'وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ', NULL, NULL, 'والهكم اله وحد لا اله الا هو الرحمن الرحيم', 'هكم ال وحد ل ال ال هو رحمن رحيم', 'quran', NULL, NULL, 'https://quran.com/2/163');
INSERT INTO units_tri_src (id, ar_tri) VALUES (170, 'وله لهك هكم اله وحد ل اله ال هو الر لرح رحم حمن الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (171, 'quran:2:164', 'quran', 'quran', '2:164', 164, 170, 'Al-Baqarah', 'البقرة', 'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ', NULL, NULL, 'ان في خلق السموت والارض واختلف اليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السماء من ماء فاحيا به الارض بعد موتها وبث فيها من كل دابه وتصريف الريح والسحاب المسخر بين السماء والارض لايت لقوم يعقلون', 'ان في خلق سموت ارض اختلف يل نهر فلك تي تجر في بحر بم ينفع نس وم انزل له من سمء من مء احي به ارض بعد موت وبث يه من كل دب تصريف ريح سحب مسخر بين سمء ارض ليت لقوم يعقل', 'quran', NULL, NULL, 'https://quran.com/2/164');
INSERT INTO units_tri_src (id, ar_tri) VALUES (171, 'ان في خلق الس لسم سمو موت ولر لرض وخت ختل تلف الي ليل ولن لنه نهر ولف لفل فلك الت لتي تجر جري في الب لبح بحر بم ينف نفع الن لنس وم انز نزل الل لله من الس لسم سمء من مء فحي به الر لرض بعد موت وته وبث فيه من كل دبه وتص تصر صري ريف الر لري ريح ولس لسح سحب الم لمس مسخ سخر بين الس لسم سمء ولر لرض ليت لقو قوم يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (172, 'quran:2:165', 'quran', 'quran', '2:165', 165, 171, 'Al-Baqarah', 'البقرة', 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ', NULL, NULL, 'ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين امنوا اشد حبا لله ولو يري الذين ظلموا اذ يرون العذاب ان القوه لله جميعا وان الله شديد العذاب', 'ومن نس من يتخذ من دون له اندد يحبون كحب له ذين امن اشد حب لل ولو ير ذين ظلم اذ ير عذب ان قو لل جميع ون له شديد عذب', 'quran', NULL, NULL, 'https://quran.com/2/165');
INSERT INTO units_tri_src (id, ar_tri) VALUES (172, 'ومن الن لنس من يتخ تخذ من دون الل لله اند ندد يحب حبو بون ونه نهم كحب الل لله ولذ لذي ذين امن منو اشد حب لله ولو يري الذ لذي ذين ظلم لمو اذ يرو رون الع لعذ عذب ان الق لقو قوه لله جمي ميع ون الل لله شدي ديد الع لعذ عذب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (173, 'quran:2:166', 'quran', 'quran', '2:166', 166, 172, 'Al-Baqarah', 'البقرة', 'إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ', NULL, NULL, 'اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب', 'اذ تبر ذين اتبع من ذين اتبع ر عذب تقطعت بهم اسبب', 'quran', NULL, NULL, 'https://quran.com/2/166');
INSERT INTO units_tri_src (id, ar_tri) VALUES (173, 'اذ تبر الذ لذي ذين اتب تبع بعو من الذ لذي ذين اتب تبع بعو ورو الع لعذ عذب وتق تقط قطع طعت بهم الس لسب سبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (174, 'quran:2:167', 'quran', 'quran', '2:167', 167, 173, 'Al-Baqarah', 'البقرة', 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', NULL, NULL, 'وقال الذين اتبعوا لو ان لنا كره فنتبرا منهم كما تبرءوا منا كذلك يريهم الله اعملهم حسرت عليهم وما هم بخرجين من النار', 'قل ذين اتبع لو ان لن كر نتبر من كم تبرء من كذلك يري له اعمل حسرت علي وم هم بخرج من نر', 'quran', NULL, NULL, 'https://quran.com/2/167');
INSERT INTO units_tri_src (id, ar_tri) VALUES (174, 'وقل الذ لذي ذين اتب تبع بعو لو ان لن كره فنت نتب تبر منه نهم كم تبر برء رءو من كذل ذلك يري ريه يهم الل لله اعم عمل مله لهم حسر سرت علي ليه يهم وم هم بخر خرج رجي جين من الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (175, 'quran:2:168', 'quran', 'quran', '2:168', 168, 174, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ', NULL, NULL, 'يا ايها الناس كلوا مما في الارض حللا طيبا ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 'ي اي نس كل مم في ارض حلل طيب ول تتبع خطوت شيطن ان لكم عدو مب', 'quran', NULL, NULL, 'https://quran.com/2/168');
INSERT INTO units_tri_src (id, ar_tri) VALUES (175, 'ي ايه الن لنس كلو مم في الر لرض حلل طيب ول تتب تبع بعو خطو طوت الش لشي شيط يطن انه لكم عدو مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (176, 'quran:2:169', 'quran', 'quran', '2:169', 169, 175, 'Al-Baqarah', 'البقرة', 'إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', NULL, NULL, 'انما يامركم بالسوء والفحشاء وان تقولوا علي الله ما لا تعلمون', 'انم يمر سوء فحشء ون تقول عل له م ل تعلم', 'quran', NULL, NULL, 'https://quran.com/2/169');
INSERT INTO units_tri_src (id, ar_tri) VALUES (176, 'انم يمر مرك ركم بلس لسو سوء ولف لفح فحش حشء ون تقو قول ولو علي الل لله م ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (177, 'quran:2:170', 'quran', 'quran', '2:170', 170, 176, 'Al-Baqarah', 'البقرة', 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ', NULL, NULL, 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه اباءنا اولو كان اباوهم لا يعقلون شيا ولا يهتدون', 'اذ قيل لهم اتبع م انزل له قل بل نتبع م في عل ابء اولو كن ابو ل يعقل شي ول يهتد', 'quran', NULL, NULL, 'https://quran.com/2/170');
INSERT INTO units_tri_src (id, ar_tri) VALUES (177, 'وذ قيل لهم اتب تبع بعو م انز نزل الل لله قلو بل نتب تبع م الف لفي فين علي ليه ابء بءن اول ولو كن ابو بوه وهم ل يعق عقل قلو لون شي ول يهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (178, 'quran:2:171', 'quran', 'quran', '2:171', 171, 177, 'Al-Baqarah', 'البقرة', 'وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ', NULL, NULL, 'ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون', 'مثل ذين كفر كمثل ذي ينعق بم ل يسمع ال دعء ندء صم بكم عم فهم ل يعقل', 'quran', NULL, NULL, 'https://quran.com/2/171');
INSERT INTO units_tri_src (id, ar_tri) VALUES (178, 'ومث مثل الذ لذي ذين كفر فرو كمث مثل الذ لذي ينع نعق بم ل يسم سمع ال دعء وند ندء صم بكم عمي فهم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (179, 'quran:2:172', 'quran', 'quran', '2:172', 172, 178, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ', NULL, NULL, 'يا ايها الذين امنوا كلوا من طيبت ما رزقنكم واشكروا لله ان كنتم اياه تعبدون', 'ي اي ذين امن كل من طيبت م رزقن اشكر لل ان كنتم اي تعبد', 'quran', NULL, NULL, 'https://quran.com/2/172');
INSERT INTO units_tri_src (id, ar_tri) VALUES (179, 'ي ايه الذ لذي ذين امن منو كلو من طيب يبت م رزق زقن قنك نكم وشك شكر كرو لله ان كنت نتم ايه تعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (180, 'quran:2:173', 'quran', 'quran', '2:173', 173, 179, 'Al-Baqarah', 'البقرة', 'إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', NULL, NULL, 'انما حرم عليكم الميته والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم', 'انم حرم علي ميت دم لحم خنزير وم اهل به لغير له فمن اضطر غير بغ ول عد فل اثم عل ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/173');
INSERT INTO units_tri_src (id, ar_tri) VALUES (180, 'انم حرم علي ليك يكم الم لمي ميت يته ولد لدم ولح لحم الخ لخن خنز نزي زير وم اهل به لغي غير الل لله فمن اضط ضطر غير بغ ول عد فل اثم علي ليه ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (181, 'quran:2:174', 'quran', 'quran', '2:174', 174, 180, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ', NULL, NULL, 'ان الذين يكتمون ما انزل الله من الكتب ويشترون به ثمنا قليلا اوليك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيمه ولا يزكيهم ولهم عذاب اليم', 'ان ذين يكتم م انزل له من كتب يشتر به ثم قليل اوليك م يكل في بطون ال نر ول يكلم له يوم قيم ول يزكي لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/2/174');
INSERT INTO units_tri_src (id, ar_tri) VALUES (181, 'ان الذ لذي ذين يكت كتم تمو مون م انز نزل الل لله من الك لكت كتب ويش يشت شتر ترو رون به ثمن قلي ليل اول ولي ليك م يكل كلو لون في بطو طون ونه نهم ال الن لنر ول يكل كلم لمه مهم الل لله يوم الق لقي قيم يمه ول يزك زكي كيه يهم وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (182, 'quran:2:175', 'quran', 'quran', '2:175', 175, 181, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ', NULL, NULL, 'اوليك الذين اشتروا الضلله بالهدي والعذاب بالمغفره فما اصبرهم علي النار', 'اوليك ذين اشتر ضلل هد عذب مغفر فم اصبر عل نر', 'quran', NULL, NULL, 'https://quran.com/2/175');
INSERT INTO units_tri_src (id, ar_tri) VALUES (182, 'اول ولي ليك الذ لذي ذين اشت شتر ترو الض لضل ضلل لله بله لهد هدي ولع لعذ عذب بلم لمغ مغف غفر فره فم اصب صبر بره رهم علي الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (183, 'quran:2:176', 'quran', 'quran', '2:176', 176, 182, 'Al-Baqarah', 'البقرة', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ', NULL, NULL, 'ذلك بان الله نزل الكتب بالحق وان الذين اختلفوا في الكتب لفي شقاق بعيد', 'ذلك بن له نزل كتب حق ون ذين اختلف في كتب لف شقق بعيد', 'quran', NULL, NULL, 'https://quran.com/2/176');
INSERT INTO units_tri_src (id, ar_tri) VALUES (183, 'ذلك بن الل لله نزل الك لكت كتب بلح لحق ون الذ لذي ذين اخت ختل تلف لفو في الك لكت كتب لفي شقق بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (184, 'quran:2:177', 'quran', 'quran', '2:177', 177, 183, 'Al-Baqarah', 'البقرة', 'لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ', NULL, NULL, 'ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من امن بالله واليوم الاخر والمليكه والكتب والنبين واتي المال علي حبه ذوي القربي واليتمي والمسكين وابن السبيل والسايلين وفي الرقاب واقام الصلاه واتي الزكاه والموفون بعهدهم اذا عهدوا والصبرين في الباساء والضراء وحين الباس اوليك الذين صدقوا واوليك هم المتقون', 'ليس بر ان تول جوه قبل مشرق مغرب لكن بر من امن له يوم اخر مليك كتب نب ات مل عل حب ذو قرب يتم مسك ابن سبيل سيل وف رقب اقم صل ات زك موف بعهد اذ عهد صبر في بسء ضرء حين بس اوليك ذين صدق اوليك هم متق', 'quran', NULL, NULL, 'https://quran.com/2/177');
INSERT INTO units_tri_src (id, ar_tri) VALUES (184, 'ليس الب لبر ان تول ولو وجو جوه وهك هكم قبل الم لمش مشر شرق ولم لمغ مغر غرب ولك لكن الب لبر من امن بلل لله ولي ليو يوم الخ لخر ولم لمل ملي ليك يكه ولك لكت كتب ولن لنب نبي بين وتي الم لمل علي حبه ذوي الق لقر قرب ربي ولي ليت يتم تمي ولم لمس مسك سكي كين وبن الس لسب سبي بيل ولس لسي سيل يلي لين وفي الر لرق رقب وقم الص لصل صله وتي الز لزك زكه ولم لمو موف وفو فون بعه عهد هده دهم اذ عهد هدو ولص لصب صبر بري رين في الب لبس بسء ولض لضر ضرء وحي حين الب لبس اول ولي ليك الذ لذي ذين صدق دقو وول ولي ليك هم الم لمت متق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (185, 'quran:2:178', 'quran', 'quran', '2:178', 178, 184, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا كتب عليكم القصاص في القتلي الحر بالحر والعبد بالعبد والانثي بالانثي فمن عفي له من اخيه شيء فاتباع بالمعروف واداء اليه باحسن ذلك تخفيف من ربكم ورحمه فمن اعتدي بعد ذلك فله عذاب اليم', 'ي اي ذين امن كتب علي قصص في قتل حر حر عبد عبد انث انث فمن عف له من اخ شيء اتبع معروف ادء يه بحسن ذلك تخفيف من رب رحم فمن اعتد بعد ذلك فل عذب يم', 'quran', NULL, NULL, 'https://quran.com/2/178');
INSERT INTO units_tri_src (id, ar_tri) VALUES (185, 'ي ايه الذ لذي ذين امن منو كتب علي ليك يكم الق لقص قصص في الق لقت قتل تلي الح لحر بلح لحر ولع لعب عبد بلع لعب عبد ولن لنث نثي بلن لنث نثي فمن عفي له من اخي خيه شيء فتب تبع بلم لمع معر عرو روف ودء الي ليه بحس حسن ذلك تخف خفي فيف من ربك بكم ورح رحم حمه فمن اعت عتد تدي بعد ذلك فله عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (186, 'quran:2:179', 'quran', 'quran', '2:179', 179, 185, 'Al-Baqarah', 'البقرة', 'وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ', NULL, NULL, 'ولكم في القصاص حياه يا اولي الالبب لعلكم تتقون', 'لكم في قصص حي ي اول البب لعل تتق', 'quran', NULL, NULL, 'https://quran.com/2/179');
INSERT INTO units_tri_src (id, ar_tri) VALUES (186, 'ولك لكم في الق لقص قصص حيه ي اول ولي الل للب لبب لعل علك لكم تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (187, 'quran:2:180', 'quran', 'quran', '2:180', 180, 186, 'Al-Baqarah', 'البقرة', 'كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ', NULL, NULL, 'كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه للولدين والاقربين بالمعروف حقا علي المتقين', 'كتب علي اذ حضر احد موت ان ترك خير وص ولد اقرب معروف حق عل متق', 'quran', NULL, NULL, 'https://quran.com/2/180');
INSERT INTO units_tri_src (id, ar_tri) VALUES (187, 'كتب علي ليك يكم اذ حضر احد حدك دكم الم لمو موت ان ترك خير الو لوص وصي صيه للو لول ولد لدي دين ولق لقر قرب ربي بين بلم لمع معر عرو روف حق علي الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (188, 'quran:2:181', 'quran', 'quran', '2:181', 181, 187, 'Al-Baqarah', 'البقرة', 'فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', NULL, NULL, 'فمن بدله بعد ما سمعه فانما اثمه علي الذين يبدلونه ان الله سميع عليم', 'فمن بدل بعد م سمع انم اثم عل ذين يبدلون ان له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/181');
INSERT INTO units_tri_src (id, ar_tri) VALUES (188, 'فمن بدل دله بعد م سمع معه فنم اثم ثمه علي الذ لذي ذين يبد بدل دلو لون ونه ان الل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (189, 'quran:2:182', 'quran', 'quran', '2:182', 182, 188, 'Al-Baqarah', 'البقرة', 'فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم', 'فمن خف من موص جنف او اثم اصلح بين فل اثم عل ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/182');
INSERT INTO units_tri_src (id, ar_tri) VALUES (189, 'فمن خف من موص جنف او اثم فصل صلح بين ينه نهم فل اثم علي ليه ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (190, 'quran:2:183', 'quran', 'quran', '2:183', 183, 189, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ', NULL, NULL, 'يا ايها الذين امنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون', 'ي اي ذين امن كتب علي صيم كم كتب عل ذين من قبل لعل تتق', 'quran', NULL, NULL, 'https://quran.com/2/183');
INSERT INTO units_tri_src (id, ar_tri) VALUES (190, 'ي ايه الذ لذي ذين امن منو كتب علي ليك يكم الص لصي صيم كم كتب علي الذ لذي ذين من قبل بلك لكم لعل علك لكم تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (191, 'quran:2:184', 'quran', 'quran', '2:184', 184, 190, 'Al-Baqarah', 'البقرة', 'أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'اياما معدودت فمن كان منكم مريضا او علي سفر فعده من ايام اخر وعلي الذين يطيقونه فديه طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون', 'ايم معدودت فمن كن من مريض او عل سفر عد من ايم اخر عل ذين يطيقون دي طعم مسك فمن تطوع خير فهو خير له ون تصوم خير لكم ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/2/184');
INSERT INTO units_tri_src (id, ar_tri) VALUES (191, 'ايم معد عدو دود ودت فمن كن منك نكم مري ريض او علي سفر فعد عده من ايم اخر وعل علي الذ لذي ذين يطي طيق يقو قون ونه فدي ديه طعم مسك سكي كين فمن تطو طوع خير فهو خير له ون تصو صوم ومو خير لكم ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (192, 'quran:2:185', 'quran', 'quran', '2:185', 185, 191, 'Al-Baqarah', 'البقرة', 'شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'شهر رمضان الذي انزل فيه القران هدي للناس وبينت من الهدي والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او علي سفر فعده من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العده ولتكبروا الله علي ما هداكم ولعلكم تشكرون', 'شهر رمض ذي انزل في قر هد نس بينت من هد فرق فمن شهد من شهر ليصم ومن كن مريض او عل سفر عد من ايم اخر يريد له بكم يسر ول يريد بكم عسر لتكمل عد لتكبر له عل م هد لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/2/185');
INSERT INTO units_tri_src (id, ar_tri) VALUES (192, 'شهر رمض مضن الذ لذي انز نزل فيه الق لقر قرن هدي للن لنس وبي بين ينت من اله لهد هدي ولف لفر فرق رقن فمن شهد منك نكم الش لشه شهر فلي ليص يصم صمه ومن كن مري ريض او علي سفر فعد عده من ايم اخر يري ريد الل لله بكم الي ليس يسر ول يري ريد بكم الع لعس عسر ولت لتك تكم كمل ملو الع لعد عده ولت لتك تكب كبر برو الل لله علي م هدك دكم ولع لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (193, 'quran:2:186', 'quran', 'quran', '2:186', 186, 192, 'Al-Baqarah', 'البقرة', 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ', NULL, NULL, 'واذا سالك عبادي عني فاني قريب اجيب دعوه الداع اذا دعان فليستجيبوا لي وليومنوا بي لعلهم يرشدون', 'اذ سلك عبد عن ان قريب اجيب دعو دع اذ دع ليستجيب لي ليومن بي لعل يرشد', 'quran', NULL, NULL, 'https://quran.com/2/186');
INSERT INTO units_tri_src (id, ar_tri) VALUES (193, 'وذ سلك عبد بدي عني فني قري ريب اجي جيب دعو عوه الد لدع اذ دعن فلي ليس يست ستج تجي جيب يبو لي ولي ليو يوم ومن منو بي لعل عله لهم يرش رشد شدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (194, 'quran:2:187', 'quran', 'quran', '2:187', 187, 193, 'Al-Baqarah', 'البقرة', 'أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ', NULL, NULL, 'احل لكم ليله الصيام الرفث الي نسايكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالن بشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتي يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الي اليل ولا تبشروهن وانتم عكفون في المسجد تلك حدود الله فلا تقربوها كذلك يبين الله ايته للناس لعلهم يتقون', 'احل لكم ليل صيم رفث ال نسي هن لبس لكم انتم لبس لهن علم له ان كنتم تختن انفس تب علي عف عن فلن بشرو ابتغ م كتب له لكم كل اشرب حت يتب لكم خيط ابيض من خيط اسود من فجر ثم اتم صيم ال يل ول تبشرو انتم عكف في مسجد تلك حدود له فل تقربو كذلك يب له ايت نس لعل يتق', 'quran', NULL, NULL, 'https://quran.com/2/187');
INSERT INTO units_tri_src (id, ar_tri) VALUES (194, 'احل لكم ليل يله الص لصي صيم الر لرف رفث الي نسي سيك يكم هن لبس لكم ونت نتم لبس لهن علم الل لله انك نكم كنت نتم تخت ختن تنو نون انف نفس فسك سكم فتب علي ليك يكم وعف عنك نكم فلن بشر شرو روه وهن وبت بتغ تغو م كتب الل لله لكم وكل كلو وشر شرب ربو حتي يتب تبي بين لكم الخ لخي خيط الب لبي بيض من الخ لخي خيط الس لسو سود من الف لفج فجر ثم اتم تمو الص لصي صيم الي الي ليل ول تبش بشر شرو روه وهن ونت نتم عكف كفو فون في الم لمس مسج سجد تلك حدو دود الل لله فل تقر قرب ربو بوه كذل ذلك يبي بين الل لله ايت يته للن لنس لعل عله لهم يتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (195, 'quran:2:188', 'quran', 'quran', '2:188', 188, 194, 'Al-Baqarah', 'البقرة', 'وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الي الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون', 'ول تكل امول بين بطل تدل به ال حكم لتكل ريق من امول نس اثم انتم تعلم', 'quran', NULL, NULL, 'https://quran.com/2/188');
INSERT INTO units_tri_src (id, ar_tri) VALUES (195, 'ول تكل كلو امو مول ولك لكم بين ينك نكم بلب لبط بطل وتد تدل دلو به الي الح لحك حكم لتك تكل كلو فري ريق من امو مول الن لنس بلث لثم ونت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (196, 'quran:2:189', 'quran', 'quran', '2:189', 189, 195, 'Al-Baqarah', 'البقرة', 'يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يسلونك عن الاهله قل هي موقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقي واتوا البيوت من ابوبها واتقوا الله لعلكم تفلحون', 'يسلونك عن اهل قل هي موقيت نس حج ليس بر بن تت بيوت من ظهور لكن بر من اتق ات بيوت من ابوب اتق له لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/2/189');
INSERT INTO units_tri_src (id, ar_tri) VALUES (196, 'يسل سلو لون ونك عن اله لهل هله قل هي موق وقي قيت للن لنس ولح لحج ولي ليس الب لبر بن تتو الب لبي بيو يوت من ظهو هور وره ولك لكن الب لبر من اتق تقي وتو الب لبي بيو يوت من ابو بوب وبه وتق تقو الل لله لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (197, 'quran:2:190', 'quran', 'quran', '2:190', 190, 196, 'Al-Baqarah', 'البقرة', 'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ', NULL, NULL, 'وقتلوا في سبيل الله الذين يقتلونكم ولا تعتدوا ان الله لا يحب المعتدين', 'قتل في سبيل له ذين يقتلون ول تعتد ان له ل يحب معتد', 'quran', NULL, NULL, 'https://quran.com/2/190');
INSERT INTO units_tri_src (id, ar_tri) VALUES (197, 'وقت قتل تلو في سبي بيل الل لله الذ لذي ذين يقت قتل تلو لون ونك نكم ول تعت عتد تدو ان الل لله ل يحب الم لمع معت عتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (198, 'quran:2:191', 'quran', 'quran', '2:191', 191, 197, 'Al-Baqarah', 'البقرة', 'وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ', NULL, NULL, 'واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنه اشد من القتل ولا تقتلوهم عند المسجد الحرام حتي يقتلوكم فيه فان قتلوكم فاقتلوهم كذلك جزاء الكفرين', 'اقتلو حيث ثقفتمو اخرجو من حيث اخرجو فتن اشد من قتل ول تقتلو عند مسجد حرم حت يقتلو في فن قتلو اقتلو كذلك جزء كفر', 'quran', NULL, NULL, 'https://quran.com/2/191');
INSERT INTO units_tri_src (id, ar_tri) VALUES (198, 'وقت قتل تلو لوه وهم حيث ثقف قفت فتم تمو موه وهم وخر خرج رجو جوه وهم من حيث اخر خرج رجو جوك وكم ولف لفت فتن تنه اشد من الق لقت قتل ول تقت قتل تلو لوه وهم عند الم لمس مسج سجد الح لحر حرم حتي يقت قتل تلو لوك وكم فيه فن قتل تلو لوك وكم فقت قتل تلو لوه وهم كذل ذلك جزء الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (199, 'quran:2:192', 'quran', 'quran', '2:192', 192, 198, 'Al-Baqarah', 'البقرة', 'فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'فان انتهوا فان الله غفور رحيم', 'فن انته فن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/192');
INSERT INTO units_tri_src (id, ar_tri) VALUES (199, 'فن انت نته تهو فن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (200, 'quran:2:193', 'quran', 'quran', '2:193', 193, 199, 'Al-Baqarah', 'البقرة', 'وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', NULL, NULL, 'وقتلوهم حتي لا تكون فتنه ويكون الدين لله فان انتهوا فلا عدون الا علي الظلمين', 'قتلو حت ل تك تن يك دين لل فن انته فل عد ال عل ظلم', 'quran', NULL, NULL, 'https://quran.com/2/193');
INSERT INTO units_tri_src (id, ar_tri) VALUES (200, 'وقت قتل تلو لوه وهم حتي ل تكو كون فتن تنه ويك يكو كون الد لدي دين لله فن انت نته تهو فل عدو دون ال علي الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (201, 'quran:2:194', 'quran', 'quran', '2:194', 194, 200, 'Al-Baqarah', 'البقرة', 'ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ', NULL, NULL, 'الشهر الحرام بالشهر الحرام والحرمت قصاص فمن اعتدي عليكم فاعتدوا عليه بمثل ما اعتدي عليكم واتقوا الله واعلموا ان الله مع المتقين', 'شهر حرم شهر حرم حرمت قصص فمن اعتد علي اعتد عل بمثل م اعتد علي اتق له اعلم ان له مع متق', 'quran', NULL, NULL, 'https://quran.com/2/194');
INSERT INTO units_tri_src (id, ar_tri) VALUES (201, 'الش لشه شهر الح لحر حرم بلش لشه شهر الح لحر حرم ولح لحر حرم رمت قصص فمن اعت عتد تدي علي ليك يكم فعت عتد تدو علي ليه بمث مثل م اعت عتد تدي علي ليك يكم وتق تقو الل لله وعل علم لمو ان الل لله مع الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (202, 'quran:2:195', 'quran', 'quran', '2:195', 195, 201, 'Al-Baqarah', 'البقرة', 'وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'وانفقوا في سبيل الله ولا تلقوا بايديكم الي التهلكه واحسنوا ان الله يحب المحسنين', 'انفق في سبيل له ول تلق بيدي ال تهلك احسن ان له يحب محسن', 'quran', NULL, NULL, 'https://quran.com/2/195');
INSERT INTO units_tri_src (id, ar_tri) VALUES (202, 'ونف نفق فقو في سبي بيل الل لله ول تلق لقو بيد يدي ديك يكم الي الت لته تهل هلك لكه وحس حسن سنو ان الل لله يحب الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (203, 'quran:2:196', 'quran', 'quran', '2:196', 196, 202, 'Al-Baqarah', 'البقرة', 'وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'واتموا الحج والعمره لله فان احصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتي يبلغ الهدي محله فمن كان منكم مريضا او به اذي من راسه ففديه من صيام او صدقه او نسك فاذا امنتم فمن تمتع بالعمره الي الحج فما استيسر من الهدي فمن لم يجد فصيام ثلثه ايام في الحج وسبعه اذا رجعتم تلك عشره كامله ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب', 'اتم حج عمر لل فن احصرتم فم استيسر من هد ول تحلق رءوس حت يبلغ هد محل فمن كن من مريض او به اذ من رس فد من صيم او صدق او نسك اذ امنتم فمن تمتع عمر ال حج فم استيسر من هد فمن لم يجد صيم ثلث ايم في حج سبع اذ رجعتم تلك عشر كمل ذلك لمن لم يكن اهل حضر مسجد حرم اتق له اعلم ان له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/2/196');
INSERT INTO units_tri_src (id, ar_tri) VALUES (203, 'وتم تمو الح لحج ولع لعم عمر مره لله فن احص حصر صرت رتم فم است ستي تيس يسر من اله لهد هدي ول تحل حلق لقو رءو ءوس وسك سكم حتي يبل بلغ اله لهد هدي محل حله فمن كن منك نكم مري ريض او به اذي من رسه ففد فدي ديه من صيم او صدق دقه او نسك فذ امن منت نتم فمن تمت متع بلع لعم عمر مره الي الح لحج فم است ستي تيس يسر من اله لهد هدي فمن لم يجد فصي صيم ثلث لثه ايم في الح لحج وسب سبع بعه اذ رجع جعت عتم تلك عشر شره كمل مله ذلك لمن لم يكن اهل هله حضر ضري الم لمس مسج سجد الح لحر حرم وتق تقو الل لله وعل علم لمو ان الل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (204, 'quran:2:197', 'quran', 'quran', '2:197', 197, 203, 'Al-Baqarah', 'البقرة', 'ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ', NULL, NULL, 'الحج اشهر معلومت فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوي واتقون يا اولي الالبب', 'حج اشهر معلومت فمن فرض يهن حج فل رفث ول سوق ول جدل في حج وم تفعل من خير يعلم له تزود فن خير زد تقو اتق ي اول البب', 'quran', NULL, NULL, 'https://quran.com/2/197');
INSERT INTO units_tri_src (id, ar_tri) VALUES (204, 'الح لحج اشه شهر معل علو لوم ومت فمن فرض فيه يهن الح لحج فل رفث ول فسو سوق ول جدل في الح لحج وم تفع فعل علو من خير يعل علم لمه الل لله وتز تزو زود ودو فن خير الز لزد الت لتق تقو قوي وتق تقو قون ي اول ولي الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (205, 'quran:2:198', 'quran', 'quran', '2:198', 198, 204, 'Al-Baqarah', 'البقرة', 'لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ', NULL, NULL, 'ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفت فاذكروا الله عند المشعر الحرام واذكروه كما هداكم وان كنتم من قبله لمن الضالين', 'ليس علي جنح ان تبتغ ضل من رب اذ افضتم من عرفت اذكر له عند مشعر حرم اذكرو كم هد ون كنتم من قبل لمن ضل', 'quran', NULL, NULL, 'https://quran.com/2/198');
INSERT INTO units_tri_src (id, ar_tri) VALUES (205, 'ليس علي ليك يكم جنح ان تبت بتغ تغو فضل من ربك بكم فذ افض فضت ضتم من عرف رفت فذك ذكر كرو الل لله عند الم لمش مشع شعر الح لحر حرم وذك ذكر كرو روه كم هدك دكم ون كنت نتم من قبل بله لمن الض لضل ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (206, 'quran:2:199', 'quran', 'quran', '2:199', 199, 205, 'Al-Baqarah', 'البقرة', 'ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم', 'ثم افيض من حيث افض نس استغفر له ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/199');
INSERT INTO units_tri_src (id, ar_tri) VALUES (206, 'ثم افي فيض يضو من حيث افض الن لنس وست ستغ تغف غفر فرو الل لله ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (207, 'quran:2:200', 'quran', 'quran', '2:200', 200, 206, 'Al-Baqarah', 'البقرة', 'فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ', NULL, NULL, 'فاذا قضيتم منسككم فاذكروا الله كذكركم اباءكم او اشد ذكرا فمن الناس من يقول ربنا اتنا في الدنيا وما له في الاخره من خلق', 'اذ قضيتم منسك اذكر له كذكر ابء او اشد ذكر فمن نس من يقول رب ات في دني وم له في اخر من خلق', 'quran', NULL, NULL, 'https://quran.com/2/200');
INSERT INTO units_tri_src (id, ar_tri) VALUES (207, 'فذ قضي ضيت يتم منس نسك سكك ككم فذك ذكر كرو الل لله كذك ذكر كرك ركم ابء بءك ءكم او اشد ذكر فمن الن لنس من يقو قول ربن اتن في الد لدن دني وم له في الخ لخر خره من خلق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (208, 'quran:2:201', 'quran', 'quran', '2:201', 201, 207, 'Al-Baqarah', 'البقرة', 'وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ', NULL, NULL, 'ومنهم من يقول ربنا اتنا في الدنيا حسنه وفي الاخره حسنه وقنا عذاب النار', 'من من يقول رب ات في دني حسن وف اخر حسن قن عذب نر', 'quran', NULL, NULL, 'https://quran.com/2/201');
INSERT INTO units_tri_src (id, ar_tri) VALUES (208, 'ومن منه نهم من يقو قول ربن اتن في الد لدن دني حسن سنه وفي الخ لخر خره حسن سنه وقن عذب الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (209, 'quran:2:202', 'quran', 'quran', '2:202', 202, 208, 'Al-Baqarah', 'البقرة', 'أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ', NULL, NULL, 'اوليك لهم نصيب مما كسبوا والله سريع الحساب', 'اوليك لهم نصيب مم كسب له سريع حسب', 'quran', NULL, NULL, 'https://quran.com/2/202');
INSERT INTO units_tri_src (id, ar_tri) VALUES (209, 'اول ولي ليك لهم نصي صيب مم كسب سبو ولل لله سري ريع الح لحس حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (210, 'quran:2:203', 'quran', 'quran', '2:203', 203, 209, 'Al-Baqarah', 'البقرة', 'وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ', NULL, NULL, 'واذكروا الله في ايام معدودت فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقي واتقوا الله واعلموا انكم اليه تحشرون', 'اذكر له في ايم معدودت فمن تعجل في يوم فل اثم عل ومن تخر فل اثم عل لمن اتق اتق له اعلم ان يه تحشر', 'quran', NULL, NULL, 'https://quran.com/2/203');
INSERT INTO units_tri_src (id, ar_tri) VALUES (210, 'وذك ذكر كرو الل لله في ايم معد عدو دود ودت فمن تعج عجل في يوم ومي مين فل اثم علي ليه ومن تخر فل اثم علي ليه لمن اتق تقي وتق تقو الل لله وعل علم لمو انك نكم الي ليه تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (211, 'quran:2:204', 'quran', 'quran', '2:204', 204, 210, 'Al-Baqarah', 'البقرة', 'وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ', NULL, NULL, 'ومن الناس من يعجبك قوله في الحياه الدنيا ويشهد الله علي ما في قلبه وهو الد الخصام', 'ومن نس من يعجبك قول في حي دني يشهد له عل م في قلب وهو الد خصم', 'quran', NULL, NULL, 'https://quran.com/2/204');
INSERT INTO units_tri_src (id, ar_tri) VALUES (211, 'ومن الن لنس من يعج عجب جبك قول وله في الح لحي حيه الد لدن دني ويش يشه شهد الل لله علي م في قلب لبه وهو الد الخ لخص خصم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (212, 'quran:2:205', 'quran', 'quran', '2:205', 205, 211, 'Al-Baqarah', 'البقرة', 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ', NULL, NULL, 'واذا تولي سعي في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد', 'اذ تول سع في ارض ليفسد يه يهلك حرث نسل له ل يحب فسد', 'quran', NULL, NULL, 'https://quran.com/2/205');
INSERT INTO units_tri_src (id, ar_tri) VALUES (212, 'وذ تول ولي سعي في الر لرض ليف يفس فسد فيه ويه يهل هلك الح لحر حرث ولن لنس نسل ولل لله ل يحب الف لفس فسد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (213, 'quran:2:206', 'quran', 'quran', '2:206', 206, 212, 'Al-Baqarah', 'البقرة', 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ', NULL, NULL, 'واذا قيل له اتق الله اخذته العزه بالاثم فحسبه جهنم ولبيس المهاد', 'اذ قيل له اتق له اخذت عز اثم حسب جهنم لبيس مهد', 'quran', NULL, NULL, 'https://quran.com/2/206');
INSERT INTO units_tri_src (id, ar_tri) VALUES (213, 'وذ قيل له اتق الل لله اخذ خذت ذته الع لعز عزه بلث لثم فحس حسب سبه جهن هنم ولب لبي بيس الم لمه مهد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (214, 'quran:2:207', 'quran', 'quran', '2:207', 207, 213, 'Al-Baqarah', 'البقرة', 'وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ', NULL, NULL, 'ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد', 'ومن نس من يشر نفس ابتغء مرض له له رءوف عبد', 'quran', NULL, NULL, 'https://quran.com/2/207');
INSERT INTO units_tri_src (id, ar_tri) VALUES (214, 'ومن الن لنس من يشر شري نفس فسه ابت بتغ تغء مرض رضت الل لله ولل لله رءو ءوف بلع لعب عبد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (215, 'quran:2:208', 'quran', 'quran', '2:208', 208, 214, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ', NULL, NULL, 'يا ايها الذين امنوا ادخلوا في السلم كافه ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 'ي اي ذين امن ادخل في سلم كف ول تتبع خطوت شيطن ان لكم عدو مب', 'quran', NULL, NULL, 'https://quran.com/2/208');
INSERT INTO units_tri_src (id, ar_tri) VALUES (215, 'ي ايه الذ لذي ذين امن منو ادخ دخل خلو في الس لسل سلم كفه ول تتب تبع بعو خطو طوت الش لشي شيط يطن انه لكم عدو مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (216, 'quran:2:209', 'quran', 'quran', '2:209', 209, 215, 'Al-Baqarah', 'البقرة', 'فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', NULL, NULL, 'فان زللتم من بعد ما جاءتكم البينت فاعلموا ان الله عزيز حكيم', 'فن زللتم من بعد م جءت بينت اعلم ان له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/209');
INSERT INTO units_tri_src (id, ar_tri) VALUES (216, 'فن زلل للت لتم من بعد م جءت ءتك تكم الب لبي بين ينت فعل علم لمو ان الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (217, 'quran:2:210', 'quran', 'quran', '2:210', 210, 216, 'Al-Baqarah', 'البقرة', 'هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', NULL, NULL, 'هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والمليكه وقضي الامر والي الله ترجع الامور', 'هل ينظر ال ان يتي له في ظلل من غمم مليك قض امر ول له ترجع امور', 'quran', NULL, NULL, 'https://quran.com/2/210');
INSERT INTO units_tri_src (id, ar_tri) VALUES (217, 'هل ينظ نظر ظرو رون ال ان يتي تيه يهم الل لله في ظلل من الغ لغم غمم ولم لمل ملي ليك يكه وقض قضي الم لمر ولي الل لله ترج رجع الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (218, 'quran:2:211', 'quran', 'quran', '2:211', 211, 217, 'Al-Baqarah', 'البقرة', 'سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'سل بني اسرءيل كم اتينهم من ايه بينه ومن يبدل نعمه الله من بعد ما جاءته فان الله شديد العقاب', 'سل بن اسرءيل كم اتين من اي بين ومن يبدل نعم له من بعد م جءت فن له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/2/211');
INSERT INTO units_tri_src (id, ar_tri) VALUES (218, 'سل بني اسر سرء رءي ءيل كم اتي تين ينه نهم من ايه بين ينه ومن يبد بدل نعم عمه الل لله من بعد م جءت ءته فن الل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (219, 'quran:2:212', 'quran', 'quran', '2:212', 212, 218, 'Al-Baqarah', 'البقرة', 'زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ', NULL, NULL, 'زين للذين كفروا الحياه الدنيا ويسخرون من الذين امنوا والذين اتقوا فوقهم يوم القيمه والله يرزق من يشاء بغير حساب', 'زين ذين كفر حي دني يسخر من ذين امن ذين اتق وق يوم قيم له يرزق من يشء بغير حسب', 'quran', NULL, NULL, 'https://quran.com/2/212');
INSERT INTO units_tri_src (id, ar_tri) VALUES (219, 'زين للذ لذي ذين كفر فرو الح لحي حيه الد لدن دني ويس يسخ سخر خرو رون من الذ لذي ذين امن منو ولذ لذي ذين اتق تقو فوق وقه قهم يوم الق لقي قيم يمه ولل لله يرز رزق من يشء بغي غير حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (220, 'quran:2:213', 'quran', 'quran', '2:213', 213, 219, 'Al-Baqarah', 'البقرة', 'كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ', NULL, NULL, 'كان الناس امه وحده فبعث الله النبين مبشرين ومنذرين وانزل معهم الكتب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاءتهم البينت بغيا بينهم فهدي الله الذين امنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشاء الي صرط مستقيم', 'كن نس ام حد بعث له نب مبشر منذر انزل مع كتب حق ليح بين نس يم اختلف في وم اختلف في ال ذين اوتو من بعد م جءت بينت بغي بين هد له ذين امن لم اختلف في من حق بذن له يهد من يشء ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/2/213');
INSERT INTO units_tri_src (id, ar_tri) VALUES (220, 'كن الن لنس امه وحد حده فبع بعث الل لله الن لنب نبي بين مبش بشر شري رين ومن منذ نذر ذري رين ونز نزل معه عهم الك لكت كتب بلح لحق ليح يحك حكم بين الن لنس فيم اخت ختل تلف لفو فيه وم اخت ختل تلف فيه ال الذ لذي ذين اوت وتو توه من بعد م جءت ءته تهم الب لبي بين ينت بغي بين ينه نهم فهد هدي الل لله الذ لذي ذين امن منو لم اخت ختل تلف لفو فيه من الح لحق بذن ذنه ولل لله يهد هدي من يشء الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (221, 'quran:2:214', 'quran', 'quran', '2:214', 214, 220, 'Al-Baqarah', 'البقرة', 'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ', NULL, NULL, 'ام حسبتم ان تدخلوا الجنه ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباساء والضراء وزلزلوا حتي يقول الرسول والذين امنوا معه متي نصر الله الا ان نصر الله قريب', 'ام حسبتم ان تدخل جن لم يت مثل ذين خل من قبل مست بسء ضرء زلزل حت يقول رسول ذين امن مع مت نصر له ال ان نصر له قريب', 'quran', NULL, NULL, 'https://quran.com/2/214');
INSERT INTO units_tri_src (id, ar_tri) VALUES (221, 'ام حسب سبت بتم ان تدخ دخل خلو الج لجن جنه ولم يتك تكم مثل الذ لذي ذين خلو من قبل بلك لكم مست سته تهم الب لبس بسء ولض لضر ضرء وزل زلز لزل زلو حتي يقو قول الر لرس رسو سول ولذ لذي ذين امن منو معه متي نصر الل لله ال ان نصر الل لله قري ريب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (222, 'quran:2:215', 'quran', 'quran', '2:215', 215, 221, 'Al-Baqarah', 'البقرة', 'يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ', NULL, NULL, 'يسلونك ماذا ينفقون قل ما انفقتم من خير فللولدين والاقربين واليتمي والمسكين وابن السبيل وما تفعلوا من خير فان الله به عليم', 'يسلونك مذ ينفق قل م انفقتم من خير ولد اقرب يتم مسك ابن سبيل وم تفعل من خير فن له به عليم', 'quran', NULL, NULL, 'https://quran.com/2/215');
INSERT INTO units_tri_src (id, ar_tri) VALUES (222, 'يسل سلو لون ونك مذ ينف نفق فقو قون قل م انف نفق فقت قتم من خير فلل للو لول ولد لدي دين ولق لقر قرب ربي بين ولي ليت يتم تمي ولم لمس مسك سكي كين وبن الس لسب سبي بيل وم تفع فعل علو من خير فن الل لله به علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (223, 'quran:2:216', 'quran', 'quran', '2:216', 216, 222, 'Al-Baqarah', 'البقرة', 'كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', NULL, NULL, 'كتب عليكم القتال وهو كره لكم وعسي ان تكرهوا شيا وهو خير لكم وعسي ان تحبوا شيا وهو شر لكم والله يعلم وانتم لا تعلمون', 'كتب علي قتل وهو كر لكم عس ان تكره شي وهو خير لكم عس ان تحب شي وهو شر لكم له يعلم انتم ل تعلم', 'quran', NULL, NULL, 'https://quran.com/2/216');
INSERT INTO units_tri_src (id, ar_tri) VALUES (223, 'كتب علي ليك يكم الق لقت قتل وهو كره لكم وعس عسي ان تكر كره رهو شي وهو خير لكم وعس عسي ان تحب حبو شي وهو شر لكم ولل لله يعل علم ونت نتم ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (224, 'quran:2:217', 'quran', 'quran', '2:217', 217, 223, 'Al-Baqarah', 'البقرة', 'يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'يسلونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنه اكبر من القتل ولا يزالون يقتلونكم حتي يردوكم عن دينكم ان استطعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاوليك حبطت اعملهم في الدنيا والاخره واوليك اصحب النار هم فيها خلدون', 'يسلونك عن شهر حرم قتل في قل قتل في كبير وصد عن سبيل له كفر به مسجد حرم اخرج اهل من اكبر عند له فتن اكبر من قتل ول يزل يقتلون حت يردو عن دين ان استطع ومن يرتدد من عن دين يمت وهو كفر اوليك حبطت اعمل في دني اخر اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/217');
INSERT INTO units_tri_src (id, ar_tri) VALUES (224, 'يسل سلو لون ونك عن الش لشه شهر الح لحر حرم قتل فيه قل قتل فيه كبي بير وصد عن سبي بيل الل لله وكف كفر به ولم لمس مسج سجد الح لحر حرم وخر خرج اهل هله منه اكب كبر عند الل لله ولف لفت فتن تنه اكب كبر من الق لقت قتل ول يزل زلو لون يقت قتل تلو لون ونك نكم حتي يرد ردو دوك وكم عن دين ينك نكم ان است ستط تطع طعو ومن يرت رتد تدد منك نكم عن دين ينه فيم يمت وهو كفر فول ولي ليك حبط بطت اعم عمل مله لهم في الد لدن دني ولخ لخر خره وول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (225, 'quran:2:218', 'quran', 'quran', '2:218', 218, 224, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'ان الذين امنوا والذين هاجروا وجهدوا في سبيل الله اوليك يرجون رحمت الله والله غفور رحيم', 'ان ذين امن ذين هجر جهد في سبيل له اوليك يرج رحمت له له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/218');
INSERT INTO units_tri_src (id, ar_tri) VALUES (225, 'ان الذ لذي ذين امن منو ولذ لذي ذين هجر جرو وجه جهد هدو في سبي بيل الل لله اول ولي ليك يرج رجو جون رحم حمت الل لله ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (226, 'quran:2:219', 'quran', 'quran', '2:219', 219, 225, 'Al-Baqarah', 'البقرة', 'يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ', NULL, NULL, 'يسلونك عن الخمر والميسر قل فيهما اثم كبير ومنفع للناس واثمهما اكبر من نفعهما ويسلونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايت لعلكم تتفكرون', 'يسلونك عن خمر ميسر قل يهم اثم كبير منفع نس اثمهم اكبر من نفعهم يسلونك مذ ينفق قل عفو كذلك يب له لكم ايت لعل تتفكر', 'quran', NULL, NULL, 'https://quran.com/2/219');
INSERT INTO units_tri_src (id, ar_tri) VALUES (226, 'يسل سلو لون ونك عن الخ لخم خمر ولم لمي ميس يسر قل فيه يهم اثم كبي بير ومن منف نفع للن لنس وثم ثمه مهم اكب كبر من نفع فعه عهم ويس يسل سلو لون ونك مذ ينف نفق فقو قون قل الع لعف عفو كذل ذلك يبي بين الل لله لكم الي ليت لعل علك لكم تتف تفك فكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (227, 'quran:2:220', 'quran', 'quran', '2:220', 220, 226, 'Al-Baqarah', 'البقرة', 'فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', NULL, NULL, 'في الدنيا والاخره ويسلونك عن اليتمي قل اصلاح لهم خير وان تخالطوهم فاخونكم والله يعلم المفسد من المصلح ولو شاء الله لاعنتكم ان الله عزيز حكيم', 'في دني اخر يسلونك عن يتم قل اصلح لهم خير ون تخلطو اخون له يعلم مفسد من مصلح ولو شء له لعنت ان له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/220');
INSERT INTO units_tri_src (id, ar_tri) VALUES (227, 'في الد لدن دني ولخ لخر خره ويس يسل سلو لون ونك عن الي ليت يتم تمي قل اصل صلح لهم خير ون تخل خلط لطو طوه وهم فخو خون ونك نكم ولل لله يعل علم الم لمف مفس فسد من الم لمص مصل صلح ولو شء الل لله لعن عنت نتك تكم ان الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (228, 'quran:2:221', 'quran', 'quran', '2:221', 221, 227, 'Al-Baqarah', 'البقرة', 'وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ', NULL, NULL, 'ولا تنكحوا المشركت حتي يومن ولامه مومنه خير من مشركه ولو اعجبتكم ولا تنكحوا المشركين حتي يومنوا ولعبد مومن خير من مشرك ولو اعجبكم اوليك يدعون الي النار والله يدعوا الي الجنه والمغفره باذنه ويبين ايته للناس لعلهم يتذكرون', 'ول تنكح مشركت حت يومن لم مومن خير من مشرك ولو اعجبت ول تنكح مشرك حت يومن لعبد مومن خير من مشرك ولو اعجب اوليك يدع ال نر له يدع ال جن مغفر بذن يب ايت نس لعل يتذكر', 'quran', NULL, NULL, 'https://quran.com/2/221');
INSERT INTO units_tri_src (id, ar_tri) VALUES (228, 'ول تنك نكح كحو الم لمش مشر شرك ركت حتي يوم ومن ولم لمه موم ومن منه خير من مشر شرك ركه ولو اعج عجب جبت بتك تكم ول تنك نكح كحو الم لمش مشر شرك ركي كين حتي يوم ومن منو ولع لعب عبد موم ومن خير من مشر شرك ولو اعج عجب جبك بكم اول ولي ليك يدع دعو عون الي الن لنر ولل لله يدع دعو الي الج لجن جنه ولم لمغ مغف غفر فره بذن ذنه ويب يبي بين ايت يته للن لنس لعل عله لهم يتذ تذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (229, 'quran:2:222', 'quran', 'quran', '2:222', 222, 228, 'Al-Baqarah', 'البقرة', 'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ', NULL, NULL, 'ويسلونك عن المحيض قل هو اذي فاعتزلوا النساء في المحيض ولا تقربوهن حتي يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوبين ويحب المتطهرين', 'يسلونك عن محيض قل هو اذ اعتزل نسء في محيض ول تقربو حت يطهرن اذ تطهرن اتو من حيث امر له ان له يحب توب يحب متطهر', 'quran', NULL, NULL, 'https://quran.com/2/222');
INSERT INTO units_tri_src (id, ar_tri) VALUES (229, 'ويس يسل سلو لون ونك عن الم لمح محي حيض قل هو اذي فعت عتز تزل زلو الن لنس نسء في الم لمح محي حيض ول تقر قرب ربو بوه وهن حتي يطه طهر هرن فذ تطه طهر هرن فتو توه وهن من حيث امر مرك ركم الل لله ان الل لله يحب الت لتو توب وبي بين ويح يحب الم لمت متط تطه طهر هري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (230, 'quran:2:223', 'quran', 'quran', '2:223', 223, 229, 'Al-Baqarah', 'البقرة', 'نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'نساوكم حرث لكم فاتوا حرثكم اني شيتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملقوه وبشر المومنين', 'نسو حرث لكم ات حرث ان شيتم قدم لنفس اتق له اعلم ان ملقو بشر مومن', 'quran', NULL, NULL, 'https://quran.com/2/223');
INSERT INTO units_tri_src (id, ar_tri) VALUES (230, 'نسو سوك وكم حرث لكم فتو حرث رثك ثكم اني شيت يتم وقد قدم دمو لنف نفس فسك سكم وتق تقو الل لله وعل علم لمو انك نكم ملق لقو قوه وبش بشر الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (231, 'quran:2:224', 'quran', 'quran', '2:224', 224, 230, 'Al-Baqarah', 'البقرة', 'وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ', NULL, NULL, 'ولا تجعلوا الله عرضه لايمنكم ان تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم', 'ول تجعل له عرض ليمن ان تبر تتق تصلح بين نس له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/224');
INSERT INTO units_tri_src (id, ar_tri) VALUES (231, 'ول تجع جعل علو الل لله عرض رضه ليم يمن منك نكم ان تبر برو وتت تتق تقو وتص تصل صلح لحو بين الن لنس ولل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (232, 'quran:2:225', 'quran', 'quran', '2:225', 225, 231, 'Al-Baqarah', 'البقرة', 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ', NULL, NULL, 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما كسبت قلوبكم والله غفور حليم', 'ل يوخذ له لغو في ايمن لكن يوخذ بم كسبت قلوب له غفور حليم', 'quran', NULL, NULL, 'https://quran.com/2/225');
INSERT INTO units_tri_src (id, ar_tri) VALUES (232, 'ل يوخ وخذ خذك ذكم الل لله بلل للغ لغو في ايم يمن منك نكم ولك لكن يوخ وخذ خذك ذكم بم كسب سبت قلو لوب وبك بكم ولل لله غفو فور حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (233, 'quran:2:226', 'quran', 'quran', '2:226', 226, 232, 'Al-Baqarah', 'البقرة', 'لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'للذين يولون من نسايهم تربص اربعه اشهر فان فاءو فان الله غفور رحيم', 'ذين يول من نسي تربص اربع اشهر فن اءو فن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/2/226');
INSERT INTO units_tri_src (id, ar_tri) VALUES (233, 'للذ لذي ذين يول ولو لون من نسي سيه يهم ترب ربص ارب ربع بعه اشه شهر فن فءو فن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (234, 'quran:2:227', 'quran', 'quran', '2:227', 227, 233, 'Al-Baqarah', 'البقرة', 'وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', NULL, NULL, 'وان عزموا الطلق فان الله سميع عليم', 'ون عزم طلق فن له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/227');
INSERT INTO units_tri_src (id, ar_tri) VALUES (234, 'ون عزم زمو الط لطل طلق فن الل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (235, 'quran:2:228', 'quran', 'quran', '2:228', 228, 234, 'Al-Baqarah', 'البقرة', 'وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', NULL, NULL, 'والمطلقت يتربصن بانفسهن ثلثه قروء ولا يحل لهن ان يكتمن ما خلق الله في ارحامهن ان كن يومن بالله واليوم الاخر وبعولتهن احق بردهن في ذلك ان ارادوا اصلحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجه والله عزيز حكيم', 'مطلقت يتربصن بنفس ثلث قروء ول يحل لهن ان يكتمن م خلق له في ارحم ان كن يومن له يوم اخر بعولت احق برد في ذلك ان ارد اصلح لهن مثل ذي علي معروف رجل علي درج له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/228');
INSERT INTO units_tri_src (id, ar_tri) VALUES (235, 'ولم لمط مطل طلق لقت يتر ترب ربص بصن بنف نفس فسه سهن ثلث لثه قرو روء ول يحل لهن ان يكت كتم تمن م خلق الل لله في ارح رحم حمه مهن ان كن يوم ومن بلل لله ولي ليو يوم الخ لخر وبع بعو عول ولت لته تهن احق برد رده دهن في ذلك ان ارد ردو اصل صلح وله لهن مثل الذ لذي علي ليه يهن بلم لمع معر عرو روف ولل للر لرج رجل علي ليه يهن درج رجه ولل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (236, 'quran:2:229', 'quran', 'quran', '2:229', 229, 235, 'Al-Baqarah', 'البقرة', 'ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'الطلق مرتان فامساك بمعروف او تسريح باحسن ولا يحل لكم ان تاخذوا مما اتيتموهن شيا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فاوليك هم الظلمون', 'طلق مرت امسك بمعروف او تسريح بحسن ول يحل لكم ان تخذ مم اتيتمو شي ال ان يخف ال يقيم حدود له فن خفتم ال يقيم حدود له فل جنح عليهم يم افتدت به تلك حدود له فل تعتدو ومن يتعد حدود له اوليك هم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/229');
INSERT INTO units_tri_src (id, ar_tri) VALUES (236, 'الط لطل طلق مرت رتن فمس مسك بمع معر عرو روف او تسر سري ريح بحس حسن ول يحل لكم ان تخذ خذو مم اتي تيت يتم تمو موه وهن شي ال ان يخف ال يقي قيم حدو دود الل لله فن خفت فتم ال يقي قيم حدو دود الل لله فل جنح علي ليه يهم فيم افت فتد تدت به تلك حدو دود الل لله فل تعت عتد تدو دوه ومن يتع تعد حدو دود الل لله فول ولي ليك هم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (237, 'quran:2:230', 'quran', 'quran', '2:230', 230, 236, 'Al-Baqarah', 'البقرة', 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ', NULL, NULL, 'فان طلقها فلا تحل له من بعد حتي تنكح زوجا غيره فان طلقها فلا جناح عليهما ان يتراجعا ان ظنا ان يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون', 'فن طلق فل تحل له من بعد حت تنكح زوج غير فن طلق فل جنح عليهم ان يترجع ان ظن ان يقيم حدود له تلك حدود له يبين لقوم يعلم', 'quran', NULL, NULL, 'https://quran.com/2/230');
INSERT INTO units_tri_src (id, ar_tri) VALUES (237, 'فن طلق لقه فل تحل له من بعد حتي تنك نكح زوج غير يره فن طلق لقه فل جنح علي ليه يهم ان يتر ترج رجع ان ظن ان يقي قيم حدو دود الل لله وتل تلك حدو دود الل لله يبي بين ينه لقو قوم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (238, 'quran:2:231', 'quran', 'quran', '2:231', 231, 237, 'Al-Baqarah', 'البقرة', 'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'واذا طلقتم النساء فبلغن اجلهن فامسكوهن بمعروف او سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا ايت الله هزوا واذكروا نعمت الله عليكم وما انزل عليكم من الكتب والحكمه يعظكم به واتقوا الله واعلموا ان الله بكل شيء عليم', 'اذ طلقتم نسء بلغن اجل امسكو بمعروف او سرحو بمعروف ول تمسكو ضرر لتعتد ومن يفعل ذلك فقد ظلم نفس ول تتخذ ايت له هز اذكر نعمت له علي وم انزل علي من كتب حكم يعظ به اتق له اعلم ان له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/2/231');
INSERT INTO units_tri_src (id, ar_tri) VALUES (238, 'وذ طلق لقت قتم الن لنس نسء فبل بلغ لغن اجل جله لهن فمس مسك سكو كوه وهن بمع معر عرو روف او سرح رحو حوه وهن بمع معر عرو روف ول تمس مسك سكو كوه وهن ضرر لتع تعت عتد تدو ومن يفع فعل ذلك فقد ظلم نفس فسه ول تتخ تخذ خذو ايت الل لله هزو وذك ذكر كرو نعم عمت الل لله علي ليك يكم وم انز نزل علي ليك يكم من الك لكت كتب ولح لحك حكم كمه يعظ عظك ظكم به وتق تقو الل لله وعل علم لمو ان الل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (239, 'quran:2:232', 'quran', 'quran', '2:232', 232, 238, 'Al-Baqarah', 'البقرة', 'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', NULL, NULL, 'واذا طلقتم النساء فبلغن اجلهن فلا تعضلوهن ان ينكحن ازوجهن اذا ترضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يومن بالله واليوم الاخر ذلكم ازكي لكم واطهر والله يعلم وانتم لا تعلمون', 'اذ طلقتم نسء بلغن اجل فل تعضلو ان ينكحن ازوج اذ ترض بين معروف ذلك يوعظ به من كن من يومن له يوم اخر ذل ازك لكم اطهر له يعلم انتم ل تعلم', 'quran', NULL, NULL, 'https://quran.com/2/232');
INSERT INTO units_tri_src (id, ar_tri) VALUES (239, 'وذ طلق لقت قتم الن لنس نسء فبل بلغ لغن اجل جله لهن فل تعض عضل ضلو لوه وهن ان ينك نكح كحن ازو زوج وجه جهن اذ ترض رضو بين ينه نهم بلم لمع معر عرو روف ذلك يوع وعظ به من كن منك نكم يوم ومن بلل لله ولي ليو يوم الخ لخر ذلك لكم ازك زكي لكم وطه طهر ولل لله يعل علم ونت نتم ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (240, 'quran:2:233', 'quran', 'quran', '2:233', 233, 239, 'Al-Baqarah', 'البقرة', 'وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ', NULL, NULL, 'والولدت يرضعن اولدهن حولين كاملين لمن اراد ان يتم الرضاعه وعلي المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس الا وسعها لا تضار ولده بولدها ولا مولود له بولده وعلي الوارث مثل ذلك فان ارادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وان اردتم ان تسترضعوا اولدكم فلا جناح عليكم اذا سلمتم ما اتيتم بالمعروف واتقوا الله واعلموا ان الله بما تعملون بصير', 'ولدت يرضعن اولد حول كمل لمن ارد ان يتم رضع عل مولود له رزق كسوت معروف ل تكلف نفس ال سع ل تضر لد بولد ول مولود له بولد عل ورث مثل ذلك فن ارد صل عن ترض منهم تشور فل جنح عليهم ون اردتم ان تسترضع اولد فل جنح علي اذ سلمتم م اتيتم معروف اتق له اعلم ان له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/2/233');
INSERT INTO units_tri_src (id, ar_tri) VALUES (240, 'ولو لول ولد لدت يرض رضع ضعن اول ولد لده دهن حول ولي لين كمل ملي لين لمن ارد ان يتم الر لرض رضع ضعه وعل علي الم لمو مول ولو لود له رزق زقه قهن وكس كسو سوت وته تهن بلم لمع معر عرو روف ل تكل كلف نفس ال وسع سعه ل تضر ولد لده بول ولد لده ول مول ولو لود له بول ولد لده وعل علي الو لور ورث مثل ذلك فن ارد فصل عن ترض منه نهم وتش تشو شور فل جنح علي ليه يهم ون ارد ردت دتم ان تست ستر ترض رضع ضعو اول ولد لدك دكم فل جنح علي ليك يكم اذ سلم لمت متم م اتي تيت يتم بلم لمع معر عرو روف وتق تقو الل لله وعل علم لمو ان الل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (241, 'quran:2:234', 'quran', 'quran', '2:234', 234, 240, 'Al-Baqarah', 'البقرة', 'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'والذين يتوفون منكم ويذرون ازوجا يتربصن بانفسهن اربعه اشهر وعشرا فاذا بلغن اجلهن فلا جناح عليكم فيما فعلن في انفسهن بالمعروف والله بما تعملون خبير', 'ذين يتوف من يذر ازوج يتربصن بنفس اربع اشهر عشر اذ بلغن اجل فل جنح علي يم علن في انفس معروف له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/2/234');
INSERT INTO units_tri_src (id, ar_tri) VALUES (241, 'ولذ لذي ذين يتو توف وفو فون منك نكم ويذ يذر ذرو رون ازو زوج يتر ترب ربص بصن بنف نفس فسه سهن ارب ربع بعه اشه شهر وعش عشر فذ بلغ لغن اجل جله لهن فل جنح علي ليك يكم فيم فعل علن في انف نفس فسه سهن بلم لمع معر عرو روف ولل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (242, 'quran:2:235', 'quran', 'quran', '2:235', 235, 241, 'Al-Baqarah', 'البقرة', 'وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ', NULL, NULL, 'ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقده النكاح حتي يبلغ الكتب اجله واعلموا ان الله يعلم ما في انفسكم فاحذروه واعلموا ان الله غفور حليم', 'ول جنح علي يم عرضتم به من خطب نسء او اكننتم في انفس علم له ان ستذكرون لكن ل توعدو سر ال ان تقول قول معروف ول تعزم عقد نكح حت يبلغ كتب اجل اعلم ان له يعلم م في انفس احذرو اعلم ان له غفور حليم', 'quran', NULL, NULL, 'https://quran.com/2/235');
INSERT INTO units_tri_src (id, ar_tri) VALUES (242, 'ول جنح علي ليك يكم فيم عرض رضت ضتم به من خطب طبه الن لنس نسء او اكن كنن ننت نتم في انف نفس فسك سكم علم الل لله انك نكم ستذ تذك ذكر كرو رون ونه نهن ولك لكن ل توع وعد عدو دوه وهن سر ال ان تقو قول ولو قول معر عرو روف ول تعز عزم زمو عقد قده الن لنك نكح حتي يبل بلغ الك لكت كتب اجل جله وعل علم لمو ان الل لله يعل علم م في انف نفس فسك سكم فحذ حذر ذرو روه وعل علم لمو ان الل لله غفو فور حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (243, 'quran:2:236', 'quran', 'quran', '2:236', 236, 242, 'Al-Baqarah', 'البقرة', 'لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ', NULL, NULL, 'لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه ومتعوهن علي الموسع قدره وعلي المقتر قدره متعا بالمعروف حقا علي المحسنين', 'ل جنح علي ان طلقتم نسء م لم تمسو او تفرض لهن ريض متعو عل موسع قدر عل مقتر قدر متع معروف حق عل محسن', 'quran', NULL, NULL, 'https://quran.com/2/236');
INSERT INTO units_tri_src (id, ar_tri) VALUES (243, 'ل جنح علي ليك يكم ان طلق لقت قتم الن لنس نسء م لم تمس مسو سوه وهن او تفر فرض رضو لهن فري ريض يضه ومت متع تعو عوه وهن علي الم لمو موس وسع قدر دره وعل علي الم لمق مقت قتر قدر دره متع بلم لمع معر عرو روف حق علي الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (244, 'quran:2:237', 'quran', 'quran', '2:237', 237, 243, 'Al-Baqarah', 'البقرة', 'وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ', NULL, NULL, 'وان طلقتموهن من قبل ان تمسوهن وقد فرضتم لهن فريضه فنصف ما فرضتم الا ان يعفون او يعفوا الذي بيده عقده النكاح وان تعفوا اقرب للتقوي ولا تنسوا الفضل بينكم ان الله بما تعملون بصير', 'ون طلقتمو من قبل ان تمسو وقد رضتم لهن ريض نصف م رضتم ال ان يعف او يعف ذي بيد عقد نكح ون تعف اقرب تقو ول تنس فضل بين ان له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/2/237');
INSERT INTO units_tri_src (id, ar_tri) VALUES (244, 'ون طلق لقت قتم تمو موه وهن من قبل ان تمس مسو سوه وهن وقد فرض رضت ضتم لهن فري ريض يضه فنص نصف م فرض رضت ضتم ال ان يعف عفو فون او يعف عفو الذ لذي بيد يده عقد قده الن لنك نكح ون تعف عفو اقر قرب للت لتق تقو قوي ول تنس نسو الف لفض فضل بين ينك نكم ان الل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (245, 'quran:2:238', 'quran', 'quran', '2:238', 238, 244, 'Al-Baqarah', 'البقرة', 'حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ', NULL, NULL, 'حفظوا علي الصلوت والصلاه الوسطي وقوموا لله قنتين', 'حفظ عل صلوت صل وسط قوم لل قنت', 'quran', NULL, NULL, 'https://quran.com/2/238');
INSERT INTO units_tri_src (id, ar_tri) VALUES (245, 'حفظ فظو علي الص لصل صلو لوت ولص لصل صله الو لوس وسط سطي وقو قوم ومو لله قنت نتي تين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (246, 'quran:2:239', 'quran', 'quran', '2:239', 239, 245, 'Al-Baqarah', 'البقرة', 'فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ', NULL, NULL, 'فان خفتم فرجالا او ركبانا فاذا امنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون', 'فن خفتم رجل او ركب اذ امنتم اذكر له كم علم م لم تكون تعلم', 'quran', NULL, NULL, 'https://quran.com/2/239');
INSERT INTO units_tri_src (id, ar_tri) VALUES (246, 'فن خفت فتم فرج رجل او ركب كبن فذ امن منت نتم فذك ذكر كرو الل لله كم علم لمك مكم م لم تكو كون ونو تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (247, 'quran:2:240', 'quran', 'quran', '2:240', 240, 246, 'Al-Baqarah', 'البقرة', 'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ', NULL, NULL, 'والذين يتوفون منكم ويذرون ازوجا وصيه لازوجهم متعا الي الحول غير اخراج فان خرجن فلا جناح عليكم في ما فعلن في انفسهن من معروف والله عزيز حكيم', 'ذين يتوف من يذر ازوج صي لزوج متع ال حول غير اخرج فن خرجن فل جنح علي في م علن في انفس من معروف له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/240');
INSERT INTO units_tri_src (id, ar_tri) VALUES (247, 'ولذ لذي ذين يتو توف وفو فون منك نكم ويذ يذر ذرو رون ازو زوج وصي صيه لزو زوج وجه جهم متع الي الح لحو حول غير اخر خرج فن خرج رجن فل جنح علي ليك يكم في م فعل علن في انف نفس فسه سهن من معر عرو روف ولل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (248, 'quran:2:241', 'quran', 'quran', '2:241', 241, 247, 'Al-Baqarah', 'البقرة', 'وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ', NULL, NULL, 'وللمطلقت متع بالمعروف حقا علي المتقين', 'مطلقت متع معروف حق عل متق', 'quran', NULL, NULL, 'https://quran.com/2/241');
INSERT INTO units_tri_src (id, ar_tri) VALUES (248, 'ولل للم لمط مطل طلق لقت متع بلم لمع معر عرو روف حق علي الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (249, 'quran:2:242', 'quran', 'quran', '2:242', 242, 248, 'Al-Baqarah', 'البقرة', 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', NULL, NULL, 'كذلك يبين الله لكم ايته لعلكم تعقلون', 'كذلك يب له لكم ايت لعل تعقل', 'quran', NULL, NULL, 'https://quran.com/2/242');
INSERT INTO units_tri_src (id, ar_tri) VALUES (249, 'كذل ذلك يبي بين الل لله لكم ايت يته لعل علك لكم تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (250, 'quran:2:243', 'quran', 'quran', '2:243', 243, 249, 'Al-Baqarah', 'البقرة', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ', NULL, NULL, 'الم تر الي الذين خرجوا من ديرهم وهم الوف حذر الموت فقال لهم الله موتوا ثم احيهم ان الله لذو فضل علي الناس ولكن اكثر الناس لا يشكرون', 'الم تر ال ذين خرج من دير وهم وف حذر موت قل لهم له موت ثم احي ان له لذو فضل عل نس لكن اكثر نس ل يشكر', 'quran', NULL, NULL, 'https://quran.com/2/243');
INSERT INTO units_tri_src (id, ar_tri) VALUES (250, 'الم تر الي الذ لذي ذين خرج رجو من دير يره رهم وهم الو لوف حذر الم لمو موت فقل لهم الل لله موت وتو ثم احي حيه يهم ان الل لله لذو فضل علي الن لنس ولك لكن اكث كثر الن لنس ل يشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (251, 'quran:2:244', 'quran', 'quran', '2:244', 244, 250, 'Al-Baqarah', 'البقرة', 'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', NULL, NULL, 'وقتلوا في سبيل الله واعلموا ان الله سميع عليم', 'قتل في سبيل له اعلم ان له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/244');
INSERT INTO units_tri_src (id, ar_tri) VALUES (251, 'وقت قتل تلو في سبي بيل الل لله وعل علم لمو ان الل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (252, 'quran:2:245', 'quran', 'quran', '2:245', 245, 251, 'Al-Baqarah', 'البقرة', 'مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ', NULL, NULL, 'من ذا الذي يقرض الله قرضا حسنا فيضعفه له اضعافا كثيره والله يقبض ويبصط واليه ترجعون', 'من ذ ذي يقرض له قرض حس يضعف له اضعف كثير له يقبض يبصط يه ترجع', 'quran', NULL, NULL, 'https://quran.com/2/245');
INSERT INTO units_tri_src (id, ar_tri) VALUES (252, 'من ذ الذ لذي يقر قرض الل لله قرض حسن فيض يضع ضعف عفه له اضع ضعف كثي ثير يره ولل لله يقب قبض ويب يبص بصط ولي ليه ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (253, 'quran:2:246', 'quran', 'quran', '2:246', 246, 252, 'Al-Baqarah', 'البقرة', 'أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ', NULL, NULL, 'الم تر الي الملا من بني اسرءيل من بعد موسي اذ قالوا لنبي لهم ابعث لنا ملكا نقتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقتلوا قالوا وما لنا الا نقتل في سبيل الله وقد اخرجنا من ديرنا وابناينا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظلمين', 'الم تر ال مل من بن اسرءيل من بعد موس اذ قل لنب لهم ابعث لن ملك نقتل في سبيل له قل هل عسيتم ان كتب علي قتل ال تقتل قل وم لن ال نقتل في سبيل له وقد اخرج من دير ابني لم كتب علي قتل تول ال قليل من له عليم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/246');
INSERT INTO units_tri_src (id, ar_tri) VALUES (253, 'الم تر الي الم لمل من بني اسر سرء رءي ءيل من بعد موس وسي اذ قلو لنب نبي لهم ابع بعث لن ملك نقت قتل في سبي بيل الل لله قل هل عسي سيت يتم ان كتب علي ليك يكم الق لقت قتل ال تقت قتل تلو قلو وم لن ال نقت قتل في سبي بيل الل لله وقد اخر خرج رجن من دير يرن وبن بني نين فلم كتب علي ليه يهم الق لقت قتل تول ولو ال قلي ليل منه نهم ولل لله علي ليم بلظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (254, 'quran:2:247', 'quran', 'quran', '2:247', 247, 253, 'Al-Baqarah', 'البقرة', 'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', NULL, NULL, 'وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا اني يكون له الملك علينا ونحن احق بالملك منه ولم يوت سعه من المال قال ان الله اصطفاه عليكم وزاده بسطه في العلم والجسم والله يوتي ملكه من يشاء والله وسع عليم', 'قل لهم نبي ان له قد بعث لكم طلوت ملك قل ان يك له ملك علي نحن احق ملك من ولم يوت سع من مل قل ان له اصطف علي زد بسط في علم جسم له يوت ملك من يشء له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/2/247');
INSERT INTO units_tri_src (id, ar_tri) VALUES (254, 'وقل لهم نبي بيه يهم ان الل لله قد بعث لكم طلو لوت ملك قلو اني يكو كون له الم لمل ملك علي لين ونح نحن احق بلم لمل ملك منه ولم يوت سعه من الم لمل قل ان الل لله اصط صطف طفه علي ليك يكم وزد زده بسط سطه في الع لعل علم ولج لجس جسم ولل لله يوت وتي ملك لكه من يشء ولل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (255, 'quran:2:248', 'quran', 'quran', '2:248', 248, 254, 'Al-Baqarah', 'البقرة', 'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'وقال لهم نبيهم ان ايه ملكه ان ياتيكم التابوت فيه سكينه من ربكم وبقيه مما ترك ال موسي وال هرون تحمله المليكه ان في ذلك لايه لكم ان كنتم مومنين', 'قل لهم نبي ان اي ملك ان يتي تبوت في سكين من رب بق مم ترك ال موس ول هر تحمل مليك ان في ذلك ل لكم ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/2/248');
INSERT INTO units_tri_src (id, ar_tri) VALUES (255, 'وقل لهم نبي بيه يهم ان ايه ملك لكه ان يتي تيك يكم الت لتب تبو بوت فيه سكي كين ينه من ربك بكم وبق بقي قيه مم ترك ال موس وسي ول هرو رون تحم حمل مله الم لمل ملي ليك يكه ان في ذلك ليه لكم ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (256, 'quran:2:249', 'quran', 'quran', '2:249', 249, 255, 'Al-Baqarah', 'البقرة', 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', NULL, NULL, 'فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفه بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين امنوا معه قالوا لا طاقه لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملقوا الله كم من فيه قليله غلبت فيه كثيره باذن الله والله مع الصبرين', 'لم فصل طلوت جنود قل ان له مبتلي بنهر فمن شرب من ليس من ومن لم يطعم ان من ال من اغترف غرف بيد شرب من ال قليل من لم جوز هو ذين امن مع قل ل طق لن يوم بجلوت جنود قل ذين يظن ان ملق له كم من في قليل غلبت في كثير بذن له له مع صبر', 'quran', NULL, NULL, 'https://quran.com/2/249');
INSERT INTO units_tri_src (id, ar_tri) VALUES (256, 'فلم فصل طلو لوت بلج لجن جنو نود قل ان الل لله مبت بتل تلي ليك يكم بنه نهر فمن شرب منه فلي ليس مني ومن لم يطع طعم عمه فنه مني ال من اغت غتر ترف غرف رفه بيد يده فشر شرب ربو منه ال قلي ليل منه نهم فلم جوز وزه هو ولذ لذي ذين امن منو معه قلو ل طقه لن الي ليو يوم بجل جلو لوت وجن جنو نود وده قل الذ لذي ذين يظن ظنو نون انه نهم ملق لقو الل لله كم من فيه قلي ليل يله غلب لبت فيه كثي ثير يره بذن الل لله ولل لله مع الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (257, 'quran:2:250', 'quran', 'quran', '2:250', 250, 256, 'Al-Baqarah', 'البقرة', 'وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', NULL, NULL, 'ولما برزوا لجالوت وجنوده قالوا ربنا افرغ علينا صبرا وثبت اقدامنا وانصرنا علي القوم الكفرين', 'لم برز لجلوت جنود قل رب افرغ علي صبر ثبت اقدم انصر عل قوم كفر', 'quran', NULL, NULL, 'https://quran.com/2/250');
INSERT INTO units_tri_src (id, ar_tri) VALUES (257, 'ولم برز رزو لجل جلو لوت وجن جنو نود وده قلو ربن افر فرغ علي لين صبر وثب ثبت اقد قدم دمن ونص نصر صرن علي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (258, 'quran:2:251', 'quran', 'quran', '2:251', 251, 257, 'Al-Baqarah', 'البقرة', 'فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ', NULL, NULL, 'فهزموهم باذن الله وقتل داود جالوت واتاه الله الملك والحكمه وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الارض ولكن الله ذو فضل علي العلمين', 'هزمو بذن له قتل دود جلوت ات له ملك حكم علم مم يشء لول دفع له نس بعض ببعض لفسدت ارض لكن له ذو فضل عل علم', 'quran', NULL, NULL, 'https://quran.com/2/251');
INSERT INTO units_tri_src (id, ar_tri) VALUES (258, 'فهز هزم زمو موه وهم بذن الل لله وقت قتل دود جلو لوت وته الل لله الم لمل ملك ولح لحك حكم كمه وعل علم لمه مم يشء ولو لول دفع الل لله الن لنس بعض عضه ضهم ببع بعض لفس فسد سدت الر لرض ولك لكن الل لله ذو فضل علي الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (259, 'quran:2:252', 'quran', 'quran', '2:252', 252, 258, 'Al-Baqarah', 'البقرة', 'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'تلك ايت الله نتلوها عليك بالحق وانك لمن المرسلين', 'تلك ايت له نتلو عليك حق انك لمن مرسل', 'quran', NULL, NULL, 'https://quran.com/2/252');
INSERT INTO units_tri_src (id, ar_tri) VALUES (259, 'تلك ايت الل لله نتل تلو لوه علي ليك بلح لحق ونك لمن الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (260, 'quran:2:253', 'quran', 'quran', '2:253', 253, 259, 'Al-Baqarah', 'البقرة', 'تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ', NULL, NULL, 'تلك الرسل فضلنا بعضهم علي بعض منهم من كلم الله ورفع بعضهم درجت واتينا عيسي ابن مريم البينت وايدنه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينت ولكن اختلفوا فمنهم من امن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد', 'تلك رسل ضل بعض عل بعض من من كلم له رفع بعض درجت اتي عيس ابن مريم بينت ايدن بروح قدس ولو شء له م اقتتل ذين من بعد من بعد م جءت بينت لكن اختلف من من امن من من كفر ولو شء له م اقتتل لكن له يفعل م يريد', 'quran', NULL, NULL, 'https://quran.com/2/253');
INSERT INTO units_tri_src (id, ar_tri) VALUES (260, 'تلك الر لرس رسل فضل ضلن بعض عضه ضهم علي بعض منه نهم من كلم الل لله ورف رفع بعض عضه ضهم درج رجت وتي تين عيس يسي ابن مري ريم الب لبي بين ينت ويد يدن دنه برو روح الق لقد قدس ولو شء الل لله م اقت قتت تتل الذ لذي ذين من بعد عده دهم من بعد م جءت ءته تهم الب لبي بين ينت ولك لكن اخت ختل تلف لفو فمن منه نهم من امن ومن منه نهم من كفر ولو شء الل لله م اقت قتت تتل تلو ولك لكن الل لله يفع فعل م يري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (261, 'quran:2:254', 'quran', 'quran', '2:254', 254, 260, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'يا ايها الذين امنوا انفقوا مما رزقنكم من قبل ان ياتي يوم لا بيع فيه ولا خله ولا شفعه والكفرون هم الظلمون', 'ي اي ذين امن انفق مم رزقن من قبل ان يت يوم ل بيع في ول خل ول شفع كفر هم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/254');
INSERT INTO units_tri_src (id, ar_tri) VALUES (261, 'ي ايه الذ لذي ذين امن منو انف نفق فقو مم رزق زقن قنك نكم من قبل ان يتي يوم ل بيع فيه ول خله ول شفع فعه ولك لكف كفر فرو رون هم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (262, 'quran:2:255', 'quran', 'quran', '2:255', 255, 261, 'Al-Baqarah', 'البقرة', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ', NULL, NULL, 'الله لا اله الا هو الحي القيوم لا تاخذه سنه ولا نوم له ما في السموت وما في الارض من ذا الذي يشفع عنده الا باذنه يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء وسع كرسيه السموت والارض ولا يوده حفظهما وهو العلي العظيم', 'له ل ال ال هو حي قيوم ل تخذ سن ول نوم له م في سموت وم في ارض من ذ ذي يشفع عند ال بذن يعلم م بين ايدي وم خلف ول يحيط بشيء من علم ال بم شء وسع كرس سموت ارض ول يود حفظهم وهو عل عظيم', 'quran', NULL, NULL, 'https://quran.com/2/255');
INSERT INTO units_tri_src (id, ar_tri) VALUES (262, 'الل لله ل اله ال هو الح لحي الق لقي قيو يوم ل تخذ خذه سنه ول نوم له م في الس لسم سمو موت وم في الر لرض من ذ الذ لذي يشف شفع عند نده ال بذن ذنه يعل علم م بين ايد يدي ديه يهم وم خلف لفه فهم ول يحي حيط يطو طون بشي شيء من علم لمه ال بم شء وسع كرس رسي سيه الس لسم سمو موت ولر لرض ول يود وده حفظ فظه ظهم وهو الع لعل علي الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (263, 'quran:2:256', 'quran', 'quran', '2:256', 256, 262, 'Al-Baqarah', 'البقرة', 'لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', NULL, NULL, 'لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطغوت ويومن بالله فقد استمسك بالعروه الوثقي لا انفصام لها والله سميع عليم', 'ل اكر في دين قد تب رشد من غي فمن يكفر طغوت يومن له فقد استمسك عرو وثق ل انفصم له له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/2/256');
INSERT INTO units_tri_src (id, ar_tri) VALUES (263, 'ل اكر كره في الد لدي دين قد تبي بين الر لرش رشد من الغ لغي فمن يكف كفر بلط لطغ طغو غوت ويو يوم ومن بلل لله فقد است ستم تمس مسك بلع لعر عرو روه الو لوث وثق ثقي ل انف نفص فصم له ولل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (264, 'quran:2:257', 'quran', 'quran', '2:257', 257, 263, 'Al-Baqarah', 'البقرة', 'ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'الله ولي الذين امنوا يخرجهم من الظلمت الي النور والذين كفروا اولياوهم الطغوت يخرجونهم من النور الي الظلمت اوليك اصحب النار هم فيها خلدون', 'له ول ذين امن يخرج من ظلمت ال نور ذين كفر اوليو طغوت يخرجون من نور ال ظلمت اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/257');
INSERT INTO units_tri_src (id, ar_tri) VALUES (264, 'الل لله ولي الذ لذي ذين امن منو يخر خرج رجه جهم من الظ لظل ظلم لمت الي الن لنو نور ولذ لذي ذين كفر فرو اول ولي ليو يوه وهم الط لطغ طغو غوت يخر خرج رجو جون ونه نهم من الن لنو نور الي الظ لظل ظلم لمت اول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (265, 'quran:2:258', 'quran', 'quran', '2:258', 258, 264, 'Al-Baqarah', 'البقرة', 'أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ', NULL, NULL, 'الم تر الي الذي حاج ابرهم في ربه ان اتاه الله الملك اذ قال ابرهم ربي الذي يحي ويميت قال انا احي واميت قال ابرهم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظلمين', 'الم تر ال ذي حج ابر في رب ان ات له ملك اذ قل ابر رب ذي يح يميت قل ان اح اميت قل ابر فن له يت شمس من مشرق فت به من مغرب بهت ذي كفر له ل يهد قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/2/258');
INSERT INTO units_tri_src (id, ar_tri) VALUES (265, 'الم تر الي الذ لذي حج ابر بره رهم في ربه ان اته الل لله الم لمل ملك اذ قل ابر بره رهم ربي الذ لذي يحي ويم يمي ميت قل ان احي ومي ميت قل ابر بره رهم فن الل لله يتي بلش لشم شمس من الم لمش مشر شرق فت به من الم لمغ مغر غرب فبه بهت الذ لذي كفر ولل لله ل يهد هدي الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (266, 'quran:2:259', 'quran', 'quran', '2:259', 259, 265, 'Al-Baqarah', 'البقرة', 'أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'او كالذي مر علي قريه وهي خاويه علي عروشها قال اني يحي هذه الله بعد موتها فاماته الله مايه عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت مايه عام فانظر الي طعامك وشرابك لم يتسنه وانظر الي حمارك ولنجعلك ايه للناس وانظر الي العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله علي كل شيء قدير', 'او ذي مر عل قر وه خو عل عروش قل ان يح هذ له بعد موت امت له م عم ثم بعث قل كم لبثت قل لبثت يوم او بعض يوم قل بل لبثت م عم انظر ال طعمك شربك لم يتسن انظر ال حمرك لنجعلك اي نس انظر ال عظم كيف ننشز ثم نكسو لحم لم تب له قل اعلم ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/259');
INSERT INTO units_tri_src (id, ar_tri) VALUES (266, 'او كلذ لذي مر علي قري ريه وهي خوي ويه علي عرو روش وشه قل اني يحي هذه الل لله بعد موت وته فمت مته الل لله ميه عم ثم بعث عثه قل كم لبث بثت قل لبث بثت يوم او بعض يوم قل بل لبث بثت ميه عم فنظ نظر الي طعم عمك وشر شرب ربك لم يتس تسن سنه ونظ نظر الي حمر مرك ولن لنج نجع جعل علك ايه للن لنس ونظ نظر الي الع لعظ عظم كيف ننش نشز شزه ثم نكس كسو سوه لحم فلم تبي بين له قل اعل علم ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (267, 'quran:2:260', 'quran', 'quran', '2:260', 260, 266, 'Al-Baqarah', 'البقرة', 'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', NULL, NULL, 'واذ قال ابرهم رب ارني كيف تحي الموتي قال اولم تومن قال بلي ولكن ليطمين قلبي قال فخذ اربعه من الطير فصرهن اليك ثم اجعل علي كل جبل منهن جزا ثم ادعهن ياتينك سعيا واعلم ان الله عزيز حكيم', 'وذ قل ابر رب ارن كيف تح موت قل اولم تومن قل بل لكن ليطم قلب قل فخذ اربع من طير صر يك ثم اجعل عل كل جبل من جز ثم ادع يتينك سعي اعلم ان له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/2/260');
INSERT INTO units_tri_src (id, ar_tri) VALUES (267, 'وذ قل ابر بره رهم رب ارن رني كيف تحي الم لمو موت وتي قل اول ولم توم ومن قل بلي ولك لكن ليط يطم طمي مين قلب لبي قل فخذ ارب ربع بعه من الط لطي طير فصر صره رهن الي ليك ثم اجع جعل علي كل جبل منه نهن جز ثم ادع دعه عهن يتي تين ينك سعي وعل علم ان الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (268, 'quran:2:261', 'quran', 'quran', '2:261', 261, 267, 'Al-Baqarah', 'البقرة', 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', NULL, NULL, 'مثل الذين ينفقون امولهم في سبيل الله كمثل حبه انبتت سبع سنابل في كل سنبله مايه حبه والله يضعف لمن يشاء والله وسع عليم', 'مثل ذين ينفق امول في سبيل له كمثل حب انبتت سبع سنبل في كل سنبل م حب له يضعف لمن يشء له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/2/261');
INSERT INTO units_tri_src (id, ar_tri) VALUES (268, 'مثل الذ لذي ذين ينف نفق فقو قون امو مول وله لهم في سبي بيل الل لله كمث مثل حبه انب نبت بتت سبع سنب نبل في كل سنب نبل بله ميه حبه ولل لله يضع ضعف لمن يشء ولل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (269, 'quran:2:262', 'quran', 'quran', '2:262', 262, 268, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'الذين ينفقون امولهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذي لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 'ذين ينفق امول في سبيل له ثم ل يتبع م انفق من ول اذ لهم اجر عند رب ول خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/262');
INSERT INTO units_tri_src (id, ar_tri) VALUES (269, 'الذ لذي ذين ينف نفق فقو قون امو مول وله لهم في سبي بيل الل لله ثم ل يتب تبع بعو عون م انف نفق فقو من ول اذي لهم اجر جره رهم عند ربه بهم ول خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (270, 'quran:2:263', 'quran', 'quran', '2:263', 263, 269, 'Al-Baqarah', 'البقرة', 'قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ', NULL, NULL, 'قول معروف ومغفره خير من صدقه يتبعها اذي والله غني حليم', 'قول معروف مغفر خير من صدق يتبع اذ له غن حليم', 'quran', NULL, NULL, 'https://quran.com/2/263');
INSERT INTO units_tri_src (id, ar_tri) VALUES (270, 'قول معر عرو روف ومغ مغف غفر فره خير من صدق دقه يتب تبع بعه اذي ولل لله غني حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (271, 'quran:2:264', 'quran', 'quran', '2:264', 264, 270, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'يا ايها الذين امنوا لا تبطلوا صدقتكم بالمن والاذي كالذي ينفق ماله رياء الناس ولا يومن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا لا يقدرون علي شيء مما كسبوا والله لا يهدي القوم الكفرين', 'ي اي ذين امن ل تبطل صدقت من اذ ذي ينفق مل ريء نس ول يومن له يوم اخر مثل كمثل صفو عل ترب اصب ابل ترك صلد ل يقدر عل شيء مم كسب له ل يهد قوم كفر', 'quran', NULL, NULL, 'https://quran.com/2/264');
INSERT INTO units_tri_src (id, ar_tri) VALUES (271, 'ي ايه الذ لذي ذين امن منو ل تبط بطل طلو صدق دقت قتك تكم بلم لمن ولذ لذي كلذ لذي ينف نفق مله ريء الن لنس ول يوم ومن بلل لله ولي ليو يوم الخ لخر فمث مثل ثله كمث مثل صفو فون علي ليه ترب فصب صبه وبل فتر ترك ركه صلد ل يقد قدر درو رون علي شيء مم كسب سبو ولل لله ل يهد هدي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (272, 'quran:2:265', 'quran', 'quran', '2:265', 265, 271, 'Al-Baqarah', 'البقرة', 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ', NULL, NULL, 'ومثل الذين ينفقون امولهم ابتغاء مرضات الله وتثبيتا من انفسهم كمثل جنه بربوه اصابها وابل فاتت اكلها ضعفين فان لم يصبها وابل فطل والله بما تعملون بصير', 'مثل ذين ينفق امول ابتغء مرض له تثبيت من انفس كمثل جن بربو اصب ابل اتت اكل ضعف فن لم يصب ابل فطل له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/2/265');
INSERT INTO units_tri_src (id, ar_tri) VALUES (272, 'ومث مثل الذ لذي ذين ينف نفق فقو قون امو مول وله لهم ابت بتغ تغء مرض رضت الل لله وتث تثب ثبي بيت من انف نفس فسه سهم كمث مثل جنه برب ربو بوه اصب صبه وبل فتت اكل كله ضعف عفي فين فن لم يصب صبه وبل فطل ولل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (273, 'quran:2:266', 'quran', 'quran', '2:266', 266, 272, 'Al-Baqarah', 'البقرة', 'أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ', NULL, NULL, 'ايود احدكم ان تكون له جنه من نخيل واعناب تجري من تحتها الانهر له فيها من كل الثمرت واصابه الكبر وله ذريه ضعفاء فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايت لعلكم تتفكرون', 'ايود احد ان تك له جن من نخيل اعنب تجر من تحت انهر له يه من كل ثمرت اصب كبر ول ذر ضعفء اصب اعصر في نر احترقت كذلك يب له لكم ايت لعل تتفكر', 'quran', NULL, NULL, 'https://quran.com/2/266');
INSERT INTO units_tri_src (id, ar_tri) VALUES (273, 'ايو يود احد حدك دكم ان تكو كون له جنه من نخي خيل وعن عنب تجر جري من تحت حته الن لنه نهر له فيه من كل الث لثم ثمر مرت وصب صبه الك لكب كبر وله ذري ريه ضعف عفء فصب صبه اعص عصر فيه نر فحت حتر ترق رقت كذل ذلك يبي بين الل لله لكم الي ليت لعل علك لكم تتف تفك فكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (274, 'quran:2:267', 'quran', 'quran', '2:267', 267, 273, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ', NULL, NULL, 'يا ايها الذين امنوا انفقوا من طيبت ما كسبتم ومما اخرجنا لكم من الارض ولا تيمموا الخبيث منه تنفقون ولستم باخذيه الا ان تغمضوا فيه واعلموا ان الله غني حميد', 'ي اي ذين امن انفق من طيبت م كسبتم مم اخرج لكم من ارض ول تيمم خبيث من تنفق لستم بخذ ال ان تغمض في اعلم ان له غن حميد', 'quran', NULL, NULL, 'https://quran.com/2/267');
INSERT INTO units_tri_src (id, ar_tri) VALUES (274, 'ي ايه الذ لذي ذين امن منو انف نفق فقو من طيب يبت م كسب سبت بتم ومم اخر خرج رجن لكم من الر لرض ول تيم يمم ممو الخ لخب خبي بيث منه تنف نفق فقو قون ولس لست ستم بخذ خذي ذيه ال ان تغم غمض مضو فيه وعل علم لمو ان الل لله غني حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (275, 'quran:2:268', 'quran', 'quran', '2:268', 268, 274, 'Al-Baqarah', 'البقرة', 'ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', NULL, NULL, 'الشيطن يعدكم الفقر ويامركم بالفحشاء والله يعدكم مغفره منه وفضلا والله وسع عليم', 'شيطن يعد فقر يمر فحشء له يعد مغفر من فضل له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/2/268');
INSERT INTO units_tri_src (id, ar_tri) VALUES (275, 'الش لشي شيط يطن يعد عدك دكم الف لفق فقر ويم يمر مرك ركم بلف لفح فحش حشء ولل لله يعد عدك دكم مغف غفر فره منه وفض فضل ولل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (276, 'quran:2:269', 'quran', 'quran', '2:269', 269, 275, 'Al-Baqarah', 'البقرة', 'يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ', NULL, NULL, 'يوتي الحكمه من يشاء ومن يوت الحكمه فقد اوتي خيرا كثيرا وما يذكر الا اولوا الالبب', 'يوت حكم من يشء ومن يوت حكم فقد اوت خير كثير وم يذكر ال اول البب', 'quran', NULL, NULL, 'https://quran.com/2/269');
INSERT INTO units_tri_src (id, ar_tri) VALUES (276, 'يوت وتي الح لحك حكم كمه من يشء ومن يوت الح لحك حكم كمه فقد اوت وتي خير كثي ثير وم يذك ذكر ال اول ولو الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (277, 'quran:2:270', 'quran', 'quran', '2:270', 270, 276, 'Al-Baqarah', 'البقرة', 'وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ', NULL, NULL, 'وما انفقتم من نفقه او نذرتم من نذر فان الله يعلمه وما للظلمين من انصار', 'وم انفقتم من نفق او نذرتم من نذر فن له يعلم وم ظلم من انصر', 'quran', NULL, NULL, 'https://quran.com/2/270');
INSERT INTO units_tri_src (id, ar_tri) VALUES (277, 'وم انف نفق فقت قتم من نفق فقه او نذر ذرت رتم من نذر فن الل لله يعل علم لمه وم للظ لظل ظلم لمي مين من انص نصر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (278, 'quran:2:271', 'quran', 'quran', '2:271', 271, 277, 'Al-Baqarah', 'البقرة', 'إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'ان تبدوا الصدقت فنعما هي وان تخفوها وتوتوها الفقراء فهو خير لكم ويكفر عنكم من سياتكم والله بما تعملون خبير', 'ان تبد صدقت نعم هي ون تخفو توتو فقرء فهو خير لكم يكفر عن من سيت له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/2/271');
INSERT INTO units_tri_src (id, ar_tri) VALUES (278, 'ان تبد بدو الص لصد صدق دقت فنع نعم هي ون تخف خفو فوه وتو توت وتو توه الف لفق فقر قرء فهو خير لكم ويك يكف كفر عنك نكم من سيت يتك تكم ولل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (279, 'quran:2:272', 'quran', 'quran', '2:272', 272, 278, 'Al-Baqarah', 'البقرة', 'لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ', NULL, NULL, 'ليس عليك هداهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلانفسكم وما تنفقون الا ابتغاء وجه الله وما تنفقوا من خير يوف اليكم وانتم لا تظلمون', 'ليس عليك هد لكن له يهد من يشء وم تنفق من خير لنفس وم تنفق ال ابتغء وج له وم تنفق من خير يوف يكم انتم ل تظلم', 'quran', NULL, NULL, 'https://quran.com/2/272');
INSERT INTO units_tri_src (id, ar_tri) VALUES (279, 'ليس علي ليك هده دهم ولك لكن الل لله يهد هدي من يشء وم تنف نفق فقو من خير فلن لنف نفس فسك سكم وم تنف نفق فقو قون ال ابت بتغ تغء وجه الل لله وم تنف نفق فقو من خير يوف الي ليك يكم ونت نتم ل تظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (280, 'quran:2:273', 'quran', 'quran', '2:273', 273, 279, 'Al-Baqarah', 'البقرة', 'لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', NULL, NULL, 'للفقراء الذين احصروا في سبيل الله لا يستطيعون ضربا في الارض يحسبهم الجاهل اغنياء من التعفف تعرفهم بسيمهم لا يسلون الناس الحافا وما تنفقوا من خير فان الله به عليم', 'فقرء ذين احصر في سبيل له ل يستطيع ضرب في ارض يحسب جهل اغنيء من تعفف تعرف بسيم ل يسل نس حف وم تنفق من خير فن له به عليم', 'quran', NULL, NULL, 'https://quran.com/2/273');
INSERT INTO units_tri_src (id, ar_tri) VALUES (280, 'للف لفق فقر قرء الذ لذي ذين احص حصر صرو في سبي بيل الل لله ل يست ستط تطي طيع يعو عون ضرب في الر لرض يحس حسب سبه بهم الج لجه جهل اغن غني نيء من الت لتع تعف عفف تعر عرف رفه فهم بسي سيم يمه مهم ل يسل سلو لون الن لنس الح لحف وم تنف نفق فقو من خير فن الل لله به علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (281, 'quran:2:274', 'quran', 'quran', '2:274', 274, 280, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'الذين ينفقون امولهم باليل والنهار سرا وعلانيه فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 'ذين ينفق امول يل نهر سر علن لهم اجر عند رب ول خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/274');
INSERT INTO units_tri_src (id, ar_tri) VALUES (281, 'الذ لذي ذين ينف نفق فقو قون امو مول وله لهم بلي ليل ولن لنه نهر سر وعل علن لني نيه فله لهم اجر جره رهم عند ربه بهم ول خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (282, 'quran:2:275', 'quran', 'quran', '2:275', 275, 281, 'Al-Baqarah', 'البقرة', 'ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'الذين ياكلون الرباا لا يقومون الا كما يقوم الذي يتخبطه الشيطن من المس ذلك بانهم قالوا انما البيع مثل الرباا واحل الله البيع وحرم الرباا فمن جاءه موعظه من ربه فانتهي فله ما سلف وامره الي الله ومن عاد فاوليك اصحب النار هم فيها خلدون', 'ذين يكل رب ل يقوم ال كم يقوم ذي يتخبط شيطن من مس ذلك بن قل انم بيع مثل رب احل له بيع حرم رب فمن جء موعظ من رب انته فل م سلف امر ال له ومن عد اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/2/275');
INSERT INTO units_tri_src (id, ar_tri) VALUES (282, 'الذ لذي ذين يكل كلو لون الر لرب ل يقو قوم ومو مون ال كم يقو قوم الذ لذي يتخ تخب خبط بطه الش لشي شيط يطن من الم لمس ذلك بنه نهم قلو انم الب لبي بيع مثل الر لرب وحل الل لله الب لبي بيع وحر حرم الر لرب فمن جءه موع وعظ عظه من ربه فنت نته تهي فله م سلف ومر مره الي الل لله ومن عد فول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (283, 'quran:2:276', 'quran', 'quran', '2:276', 276, 282, 'Al-Baqarah', 'البقرة', 'يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', NULL, NULL, 'يمحق الله الرباا ويربي الصدقت والله لا يحب كل كفار اثيم', 'يمحق له رب يرب صدقت له ل يحب كل كفر اثيم', 'quran', NULL, NULL, 'https://quran.com/2/276');
INSERT INTO units_tri_src (id, ar_tri) VALUES (283, 'يمح محق الل لله الر لرب وير يرب ربي الص لصد صدق دقت ولل لله ل يحب كل كفر اثي ثيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (284, 'quran:2:277', 'quran', 'quran', '2:277', 277, 283, 'Al-Baqarah', 'البقرة', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'ان الذين امنوا وعملوا الصلحت واقاموا الصلاه واتوا الزكاه لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 'ان ذين امن عمل صلحت اقم صل ات زك لهم اجر عند رب ول خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/2/277');
INSERT INTO units_tri_src (id, ar_tri) VALUES (284, 'ان الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت وقم قمو الص لصل صله وتو الز لزك زكه لهم اجر جره رهم عند ربه بهم ول خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (285, 'quran:2:278', 'quran', 'quran', '2:278', 278, 284, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'يا ايها الذين امنوا اتقوا الله وذروا ما بقي من الرباا ان كنتم مومنين', 'ي اي ذين امن اتق له ذر م بق من رب ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/2/278');
INSERT INTO units_tri_src (id, ar_tri) VALUES (285, 'ي ايه الذ لذي ذين امن منو اتق تقو الل لله وذر ذرو م بقي من الر لرب ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (286, 'quran:2:279', 'quran', 'quran', '2:279', 279, 285, 'Al-Baqarah', 'البقرة', 'فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ', NULL, NULL, 'فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس امولكم لا تظلمون ولا تظلمون', 'فن لم تفعل اذن بحرب من له رسول ون تبتم لكم رءوس امول ل تظلم ول تظلم', 'quran', NULL, NULL, 'https://quran.com/2/279');
INSERT INTO units_tri_src (id, ar_tri) VALUES (286, 'فن لم تفع فعل علو فذن ذنو بحر حرب من الل لله ورس رسو سول وله ون تبت بتم فلك لكم رءو ءوس امو مول ولك لكم ل تظل ظلم لمو مون ول تظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (287, 'quran:2:280', 'quran', 'quran', '2:280', 280, 286, 'Al-Baqarah', 'البقرة', 'وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'وان كان ذو عسره فنظره الي ميسره وان تصدقوا خير لكم ان كنتم تعلمون', 'ون كن ذو عسر نظر ال ميسر ون تصدق خير لكم ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/2/280');
INSERT INTO units_tri_src (id, ar_tri) VALUES (287, 'ون كن ذو عسر سره فنظ نظر ظره الي ميس يسر سره ون تصد صدق دقو خير لكم ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (288, 'quran:2:281', 'quran', 'quran', '2:281', 281, 287, 'Al-Baqarah', 'البقرة', 'وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'واتقوا يوما ترجعون فيه الي الله ثم توفي كل نفس ما كسبت وهم لا يظلمون', 'اتق يوم ترجع في ال له ثم توف كل نفس م كسبت وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/2/281');
INSERT INTO units_tri_src (id, ar_tri) VALUES (288, 'وتق تقو يوم ترج رجع جعو عون فيه الي الل لله ثم توف وفي كل نفس م كسب سبت وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (289, 'quran:2:282', 'quran', 'quran', '2:282', 282, 288, 'Al-Baqarah', 'البقرة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه وليكتب بينكم كاتب بالعدل ولا ياب كاتب ان يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيا فان كان الذي عليه الحق سفيها او ضعيفا او لا يستطيع ان يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء ان تضل احداهما فتذكر احداهما الاخري ولا ياب الشهداء اذا ما دعوا ولا تسموا ان تكتبوه صغيرا او كبيرا الي اجله ذلكم اقسط عند الله واقوم للشهده وادني الا ترتابوا الا ان تكون تجره حاضره تديرونها بينكم فليس عليكم جناح الا تكتبوها واشهدوا اذا تبايعتم ولا يضار كاتب ولا شهيد وان تفعلوا فانه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم', 'ي اي ذين امن اذ تدينتم بد ال اجل مسم اكتبو ليكتب بين كتب عدل ول يب كتب ان يكتب كم علم له ليكتب ليملل ذي عل حق ليتق له رب ول يبخس من شي فن كن ذي عل حق سفي او ضعيف او ل يستطيع ان يمل هو ليملل لي عدل استشهد شهيد من رجل فن لم يكو رجل رجل امرت ممن ترض من شهدء ان تضل احدهم تذكر احدهم اخر ول يب شهدء اذ م دع ول تسم ان تكتبو صغير او كبير ال اجل ذل اقسط عند له اقوم شهد ادن ال ترتب ال ان تك تجر حضر تديرون بين ليس علي جنح ال تكتبو اشهد اذ تبيعتم ول يضر كتب ول شهيد ون تفعل ان سوق بكم اتق له يعلم له له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/2/282');
INSERT INTO units_tri_src (id, ar_tri) VALUES (289, 'ي ايه الذ لذي ذين امن منو اذ تدي دين ينت نتم بدي دين الي اجل مسم سمي فكت كتب تبو بوه ولي ليك يكت كتب بين ينك نكم كتب بلع لعد عدل ول يب كتب ان يكت كتب كم علم لمه الل لله فلي ليك يكت كتب ولي ليم يمل ملل الذ لذي علي ليه الح لحق ولي ليت يتق الل لله ربه ول يبخ بخس منه شي فن كن الذ لذي علي ليه الح لحق سفي فيه او ضعي عيف او ل يست ستط تطي طيع ان يمل هو فلي ليم يمل ملل ولي ليه بلع لعد عدل وست ستش تشه شهد هدو شهي هيد يدي دين من رجل جلك لكم فن لم يكو كون رجل جلي لين فرج رجل ومر مرت رتن ممن ترض رضو ضون من الش لشه شهد هدء ان تضل احد حده دهم فتذ تذك ذكر احد حده دهم الخ لخر خري ول يب الش لشه شهد هدء اذ م دعو ول تسم سمو ان تكت كتب تبو بوه صغي غير او كبي بير الي اجل جله ذلك لكم اقس قسط عند الل لله وقو قوم للش لشه شهد هده ودن دني ال ترت رتب تبو ال ان تكو كون تجر جره حضر ضره تدي دير يرو رون ونه بين ينك نكم فلي ليس علي ليك يكم جنح ال تكت كتب تبو بوه وشه شهد هدو اذ تبي بيع يعت عتم ول يضر كتب ول شهي هيد ون تفع فعل علو فنه فسو سوق بكم وتق تقو الل لله ويع يعل علم لمك مكم الل لله ولل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (290, 'quran:2:283', 'quran', 'quran', '2:283', 283, 289, 'Al-Baqarah', 'البقرة', 'وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ', NULL, NULL, 'وان كنتم علي سفر ولم تجدوا كاتبا فرهن مقبوضه فان امن بعضكم بعضا فليود الذي اوتمن امنته وليتق الله ربه ولا تكتموا الشهده ومن يكتمها فانه اثم قلبه والله بما تعملون عليم', 'ون كنتم عل سفر ولم تجد كتب رهن مقبوض فن امن بعض بعض ليود ذي اوتمن امنت ليتق له رب ول تكتم شهد ومن يكتم ان اثم قلب له بم تعمل عليم', 'quran', NULL, NULL, 'https://quran.com/2/283');
INSERT INTO units_tri_src (id, ar_tri) VALUES (290, 'ون كنت نتم علي سفر ولم تجد جدو كتب فره رهن مقب قبو بوض وضه فن امن بعض عضك ضكم بعض فلي ليو يود الذ لذي اوت وتم تمن امن منت نته ولي ليت يتق الل لله ربه ول تكت كتم تمو الش لشه شهد هده ومن يكت كتم تمه فنه اثم قلب لبه ولل لله بم تعم عمل ملو لون علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (291, 'quran:2:284', 'quran', 'quran', '2:284', 284, 290, 'Al-Baqarah', 'البقرة', 'لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', NULL, NULL, 'لله ما في السموت وما في الارض وان تبدوا ما في انفسكم او تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله علي كل شيء قدير', 'لل م في سموت وم في ارض ون تبد م في انفس او تخفو يحسب به له يغفر لمن يشء يعذب من يشء له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/2/284');
INSERT INTO units_tri_src (id, ar_tri) VALUES (291, 'لله م في الس لسم سمو موت وم في الر لرض ون تبد بدو م في انف نفس فسك سكم او تخف خفو فوه يحس حسب سبك بكم به الل لله فيغ يغف غفر لمن يشء ويع يعذ عذب من يشء ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (292, 'quran:2:285', 'quran', 'quran', '2:285', 285, 291, 'Al-Baqarah', 'البقرة', 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ', NULL, NULL, 'امن الرسول بما انزل اليه من ربه والمومنون كل امن بالله ومليكته وكتبه ورسله لا نفرق بين احد من رسله وقالوا سمعنا واطعنا غفرانك ربنا واليك المصير', 'امن رسول بم انزل يه من رب مومن كل امن له مليكت كتب رسل ل نفرق بين احد من رسل قل سمع اطع غفرنك رب يك مصير', 'quran', NULL, NULL, 'https://quran.com/2/285');
INSERT INTO units_tri_src (id, ar_tri) VALUES (292, 'امن الر لرس رسو سول بم انز نزل الي ليه من ربه ولم لمو موم ومن منو نون كل امن بلل لله ومل ملي ليك يكت كته وكت كتب تبه ورس رسل سله ل نفر فرق بين احد من رسل سله وقل قلو سمع معن وطع طعن غفر فرن رنك ربن ولي ليك الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (293, 'quran:2:286', 'quran', 'quran', '2:286', 286, 292, 'Al-Baqarah', 'البقرة', 'لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', NULL, NULL, 'لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تواخذنا ان نسينا او اخطانا ربنا ولا تحمل علينا اصرا كما حملته علي الذين من قبلنا ربنا ولا تحملنا ما لا طاقه لنا به واعف عنا واغفر لنا وارحمنا انت مولانا فانصرنا علي القوم الكفرين', 'ل يكلف له نفس ال سع له م كسبت علي م اكتسبت رب ل توخذ ان نسي او اخط رب ول تحمل علي اصر كم حملت عل ذين من قبل رب ول تحمل م ل طق لن به اعف عن اغفر لن ارحم انت مول انصر عل قوم كفر', 'quran', NULL, NULL, 'https://quran.com/2/286');
INSERT INTO units_tri_src (id, ar_tri) VALUES (293, 'ل يكل كلف الل لله نفس ال وسع سعه له م كسب سبت وعل علي ليه م اكت كتس تسب سبت ربن ل توخ وخذ خذن ان نسي سين او اخط خطن ربن ول تحم حمل علي لين اصر كم حمل ملت لته علي الذ لذي ذين من قبل بلن ربن ول تحم حمل ملن م ل طقه لن به وعف عن وغف غفر لن ورح رحم حمن انت مول ولن فنص نصر صرن علي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (294, 'quran:3:1', 'quran', 'quran', '3:1', 1, 293, 'Ali ''Imran', 'آل عمران', 'الٓمٓ', NULL, NULL, 'الم', 'الم', 'quran', NULL, NULL, 'https://quran.com/3/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (294, 'الم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (295, 'quran:3:2', 'quran', 'quran', '3:2', 2, 294, 'Ali ''Imran', 'آل عمران', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ', NULL, NULL, 'الله لا اله الا هو الحي القيوم', 'له ل ال ال هو حي قيوم', 'quran', NULL, NULL, 'https://quran.com/3/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (295, 'الل لله ل اله ال هو الح لحي الق لقي قيو يوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (296, 'quran:3:3', 'quran', 'quran', '3:3', 3, 295, 'Ali ''Imran', 'آل عمران', 'نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ', NULL, NULL, 'نزل عليك الكتب بالحق مصدقا لما بين يديه وانزل التوراه والانجيل', 'نزل عليك كتب حق مصدق لم بين يد انزل تور انجيل', 'quran', NULL, NULL, 'https://quran.com/3/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (296, 'نزل علي ليك الك لكت كتب بلح لحق مصد صدق لم بين يدي ديه ونز نزل الت لتو تور وره ولن لنج نجي جيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (297, 'quran:3:4', 'quran', 'quran', '3:4', 4, 296, 'Ali ''Imran', 'آل عمران', 'مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ', NULL, NULL, 'من قبل هدي للناس وانزل الفرقان ان الذين كفروا بايت الله لهم عذاب شديد والله عزيز ذو انتقام', 'من قبل هد نس انزل فرق ان ذين كفر بيت له لهم عذب شديد له عزيز ذو انتقم', 'quran', NULL, NULL, 'https://quran.com/3/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (297, 'من قبل هدي للن لنس ونز نزل الف لفر فرق رقن ان الذ لذي ذين كفر فرو بيت الل لله لهم عذب شدي ديد ولل لله عزي زيز ذو انت نتق تقم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (298, 'quran:3:5', 'quran', 'quran', '3:5', 5, 297, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ', NULL, NULL, 'ان الله لا يخفي عليه شيء في الارض ولا في السماء', 'ان له ل يخف عل شيء في ارض ول في سمء', 'quran', NULL, NULL, 'https://quran.com/3/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (298, 'ان الل لله ل يخف خفي علي ليه شيء في الر لرض ول في الس لسم سمء');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (299, 'quran:3:6', 'quran', 'quran', '3:6', 6, 298, 'Ali ''Imran', 'آل عمران', 'هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'هو الذي يصوركم في الارحام كيف يشاء لا اله الا هو العزيز الحكيم', 'هو ذي يصور في ارحم كيف يشء ل ال ال هو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/3/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (299, 'هو الذ لذي يصو صور ورك ركم في الر لرح رحم كيف يشء ل اله ال هو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (300, 'quran:3:7', 'quran', 'quran', '3:7', 7, 299, 'Ali ''Imran', 'آل عمران', 'هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ', NULL, NULL, 'هو الذي انزل عليك الكتب منه ايت محكمت هن ام الكتب واخر متشبهت فاما الذين في قلوبهم زيغ فيتبعون ما تشبه منه ابتغاء الفتنه وابتغاء تاويله وما يعلم تاويله الا الله والرسخون في العلم يقولون امنا به كل من عند ربنا وما يذكر الا اولوا الالبب', 'هو ذي انزل عليك كتب من ايت محكمت هن ام كتب اخر متشبهت ام ذين في قلوب زيغ يتبع م تشب من ابتغء فتن ابتغء تويل وم يعلم تويل ال له رسخ في علم يقول ام به كل من عند رب وم يذكر ال اول البب', 'quran', NULL, NULL, 'https://quran.com/3/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (300, 'هو الذ لذي انز نزل علي ليك الك لكت كتب منه ايت محك حكم كمت هن ام الك لكت كتب وخر متش تشب شبه بهت فم الذ لذي ذين في قلو لوب وبه بهم زيغ فيت يتب تبع بعو عون م تشب شبه منه ابت بتغ تغء الف لفت فتن تنه وبت بتغ تغء توي ويل يله وم يعل علم توي ويل يله ال الل لله ولر لرس رسخ سخو خون في الع لعل علم يقو قول ولو لون امن به كل من عند ربن وم يذك ذكر ال اول ولو الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (301, 'quran:3:8', 'quran', 'quran', '3:8', 8, 300, 'Ali ''Imran', 'آل عمران', 'رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ', NULL, NULL, 'ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمه انك انت الوهاب', 'رب ل تزغ قلوب بعد اذ هديت وهب لن من لدنك رحم انك انت وهب', 'quran', NULL, NULL, 'https://quran.com/3/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (301, 'ربن ل تزغ قلو لوب وبن بعد اذ هدي ديت يتن وهب لن من لدن دنك رحم حمه انك انت الو لوه وهب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (302, 'quran:3:9', 'quran', 'quran', '3:9', 9, 301, 'Ali ''Imran', 'آل عمران', 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ', NULL, NULL, 'ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد', 'رب انك جمع نس ليوم ل ريب في ان له ل يخلف ميعد', 'quran', NULL, NULL, 'https://quran.com/3/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (302, 'ربن انك جمع الن لنس ليو يوم ل ريب فيه ان الل لله ل يخل خلف الم لمي ميع يعد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (303, 'quran:3:10', 'quran', 'quran', '3:10', 10, 302, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ', NULL, NULL, 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واوليك هم وقود النار', 'ان ذين كفر لن تغن عن امول ول اولد من له شي اوليك هم قود نر', 'quran', NULL, NULL, 'https://quran.com/3/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (303, 'ان الذ لذي ذين كفر فرو لن تغن غني عنه نهم امو مول وله لهم ول اول ولد لده دهم من الل لله شي وول ولي ليك هم وقو قود الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (304, 'quran:3:11', 'quran', 'quran', '3:11', 11, 303, 'Ali ''Imran', 'آل عمران', 'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'كداب ال فرعون والذين من قبلهم كذبوا بايتنا فاخذهم الله بذنوبهم والله شديد العقاب', 'كدب ال رع ذين من قبل كذب بيت اخذ له بذنوب له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/3/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (304, 'كدب ال فرع رعو عون ولذ لذي ذين من قبل بله لهم كذب ذبو بيت يتن فخذ خذه ذهم الل لله بذن ذنو نوب وبه بهم ولل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (305, 'quran:3:12', 'quran', 'quran', '3:12', 12, 304, 'Ali ''Imran', 'آل عمران', 'قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ', NULL, NULL, 'قل للذين كفروا ستغلبون وتحشرون الي جهنم وبيس المهاد', 'قل ذين كفر ستغلب تحشر ال جهنم بيس مهد', 'quran', NULL, NULL, 'https://quran.com/3/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (305, 'قل للذ لذي ذين كفر فرو ستغ تغل غلب لبو بون وتح تحش حشر شرو رون الي جهن هنم وبي بيس الم لمه مهد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (306, 'quran:3:13', 'quran', 'quran', '3:13', 13, 305, 'Ali ''Imran', 'آل عمران', 'قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ', NULL, NULL, 'قد كان لكم ايه في فيتين التقتا فيه تقتل في سبيل الله واخري كافره يرونهم مثليهم راي العين والله يويد بنصره من يشاء ان في ذلك لعبره لاولي الابصر', 'قد كن لكم اي في يت تقت في تقتل في سبيل له اخر كفر يرون مثلي ر عين له يويد بنصر من يشء ان في ذلك لعبر لول ابصر', 'quran', NULL, NULL, 'https://quran.com/3/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (306, 'قد كن لكم ايه في فيت يتي تين الت لتق تقت فيه تقت قتل في سبي بيل الل لله وخر خري كفر فره يرو رون ونه نهم مثل ثلي ليه يهم ري الع لعي عين ولل لله يوي ويد بنص نصر صره من يشء ان في ذلك لعب عبر بره لول ولي الب لبص بصر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (307, 'quran:3:14', 'quran', 'quran', '3:14', 14, 306, 'Ali ''Imran', 'آل عمران', 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ', NULL, NULL, 'زين للناس حب الشهوت من النساء والبنين والقنطير المقنطره من الذهب والفضه والخيل المسومه والانعم والحرث ذلك متع الحياه الدنيا والله عنده حسن الماب', 'زين نس حب شهوت من نسء بن قنطير مقنطر من ذهب فض خيل مسوم انعم حرث ذلك متع حي دني له عند حسن مب', 'quran', NULL, NULL, 'https://quran.com/3/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (307, 'زين للن لنس حب الش لشه شهو هوت من الن لنس نسء ولب لبن بني نين ولق لقن قنط نطي طير الم لمق مقن قنط نطر طره من الذ لذه ذهب ولف لفض فضه ولخ لخي خيل الم لمس مسو سوم ومه ولن لنع نعم ولح لحر حرث ذلك متع الح لحي حيه الد لدن دني ولل لله عند نده حسن الم لمب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (308, 'quran:3:15', 'quran', 'quran', '3:15', 15, 307, 'Ali ''Imran', 'آل عمران', 'قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ', NULL, NULL, 'قل اونبيكم بخير من ذلكم للذين اتقوا عند ربهم جنت تجري من تحتها الانهر خلدين فيها وازوج مطهره ورضون من الله والله بصير بالعباد', 'قل اونبي بخير من ذل ذين اتق عند رب جنت تجر من تحت انهر خلد يه ازوج مطهر رض من له له بصير عبد', 'quran', NULL, NULL, 'https://quran.com/3/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (308, 'قل اون ونب نبي بيك يكم بخي خير من ذلك لكم للذ لذي ذين اتق تقو عند ربه بهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه وزو زوج مطه طهر هره ورض رضو ضون من الل لله ولل لله بصي صير بلع لعب عبد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (309, 'quran:3:16', 'quran', 'quran', '3:16', 16, 308, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', NULL, NULL, 'الذين يقولون ربنا اننا امنا فاغفر لنا ذنوبنا وقنا عذاب النار', 'ذين يقول رب ان ام اغفر لن ذنوب قن عذب نر', 'quran', NULL, NULL, 'https://quran.com/3/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (309, 'الذ لذي ذين يقو قول ولو لون ربن انن امن فغف غفر لن ذنو نوب وبن وقن عذب الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (310, 'quran:3:17', 'quran', 'quran', '3:17', 17, 309, 'Ali ''Imran', 'آل عمران', 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ', NULL, NULL, 'الصبرين والصدقين والقنتين والمنفقين والمستغفرين بالاسحار', 'صبر صدق قنت منفق مستغفر اسحر', 'quran', NULL, NULL, 'https://quran.com/3/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (310, 'الص لصب صبر بري رين ولص لصد صدق دقي قين ولق لقن قنت نتي تين ولم لمن منف نفق فقي قين ولم لمس مست ستغ تغف غفر فري رين بلس لسح سحر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (311, 'quran:3:18', 'quran', 'quran', '3:18', 18, 310, 'Ali ''Imran', 'آل عمران', 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'شهد الله انه لا اله الا هو والمليكه واولوا العلم قايما بالقسط لا اله الا هو العزيز الحكيم', 'شهد له ان ل ال ال هو مليك اول علم قيم قسط ل ال ال هو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/3/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (311, 'شهد الل لله انه ل اله ال هو ولم لمل ملي ليك يكه وول ولو الع لعل علم قيم بلق لقس قسط ل اله ال هو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (312, 'quran:3:19', 'quran', 'quran', '3:19', 19, 311, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', NULL, NULL, 'ان الدين عند الله الاسلم وما اختلف الذين اوتوا الكتب الا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بايت الله فان الله سريع الحساب', 'ان دين عند له اسلم وم اختلف ذين اوت كتب ال من بعد م جء علم بغي بين ومن يكفر بيت له فن له سريع حسب', 'quran', NULL, NULL, 'https://quran.com/3/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (312, 'ان الد لدي دين عند الل لله الس لسل سلم وم اخت ختل تلف الذ لذي ذين اوت وتو الك لكت كتب ال من بعد م جءه ءهم الع لعل علم بغي بين ينه نهم ومن يكف كفر بيت الل لله فن الل لله سري ريع الح لحس حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (313, 'quran:3:20', 'quran', 'quran', '3:20', 20, 312, 'Ali ''Imran', 'آل عمران', 'فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ', NULL, NULL, 'فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتب والامين اسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلغ والله بصير بالعباد', 'فن حجوك فقل اسلمت جه لل ومن اتبعن وقل ذين اوت كتب ام اسلمتم فن اسلم فقد اهتد ون تول انم عليك بلغ له بصير عبد', 'quran', NULL, NULL, 'https://quran.com/3/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (313, 'فن حجو جوك فقل اسل سلم لمت وجه جهي لله ومن اتب تبع بعن وقل للذ لذي ذين اوت وتو الك لكت كتب ولم لمي مين اسل سلم لمت متم فن اسل سلم لمو فقد اهت هتد تدو ون تول ولو فنم علي ليك الب لبل بلغ ولل لله بصي صير بلع لعب عبد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (314, 'quran:3:21', 'quran', 'quran', '3:21', 21, 313, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ', NULL, NULL, 'ان الذين يكفرون بايت الله ويقتلون النبين بغير حق ويقتلون الذين يامرون بالقسط من الناس فبشرهم بعذاب اليم', 'ان ذين يكفر بيت له يقتل نب بغير حق يقتل ذين يمر قسط من نس بشر بعذب يم', 'quran', NULL, NULL, 'https://quran.com/3/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (314, 'ان الذ لذي ذين يكف كفر فرو رون بيت الل لله ويق يقت قتل تلو لون الن لنب نبي بين بغي غير حق ويق يقت قتل تلو لون الذ لذي ذين يمر مرو رون بلق لقس قسط من الن لنس فبش بشر شره رهم بعذ عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (315, 'quran:3:22', 'quran', 'quran', '3:22', 22, 314, 'Ali ''Imran', 'آل عمران', 'أُوْلَٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', NULL, NULL, 'اوليك الذين حبطت اعملهم في الدنيا والاخره وما لهم من نصرين', 'اوليك ذين حبطت اعمل في دني اخر وم لهم من نصر', 'quran', NULL, NULL, 'https://quran.com/3/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (315, 'اول ولي ليك الذ لذي ذين حبط بطت اعم عمل مله لهم في الد لدن دني ولخ لخر خره وم لهم من نصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (316, 'quran:3:23', 'quran', 'quran', '3:23', 23, 315, 'Ali ''Imran', 'آل عمران', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ', NULL, NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يدعون الي كتب الله ليحكم بينهم ثم يتولي فريق منهم وهم معرضون', 'الم تر ال ذين اوت نصيب من كتب يدع ال كتب له ليح بين ثم يتول ريق من وهم معرض', 'quran', NULL, NULL, 'https://quran.com/3/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (316, 'الم تر الي الذ لذي ذين اوت وتو نصي صيب من الك لكت كتب يدع دعو عون الي كتب الل لله ليح يحك حكم بين ينه نهم ثم يتو تول ولي فري ريق منه نهم وهم معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (317, 'quran:3:24', 'quran', 'quran', '3:24', 24, 316, 'Ali ''Imran', 'آل عمران', 'ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ', NULL, NULL, 'ذلك بانهم قالوا لن تمسنا النار الا اياما معدودت وغرهم في دينهم ما كانوا يفترون', 'ذلك بن قل لن تمس نر ال ايم معدودت غر في دين م كن يفتر', 'quran', NULL, NULL, 'https://quran.com/3/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (317, 'ذلك بنه نهم قلو لن تمس مسن الن لنر ال ايم معد عدو دود ودت وغر غره رهم في دين ينه نهم م كنو يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (318, 'quran:3:25', 'quran', 'quran', '3:25', 25, 317, 'Ali ''Imran', 'آل عمران', 'فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'فكيف اذا جمعنهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون', 'كيف اذ جمعن ليوم ل ريب في وفيت كل نفس م كسبت وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/3/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (318, 'فكي كيف اذ جمع معن عنه نهم ليو يوم ل ريب فيه ووف وفي فيت كل نفس م كسب سبت وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (319, 'quran:3:26', 'quran', 'quran', '3:26', 26, 318, 'Ali ''Imran', 'آل عمران', 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'قل اللهم ملك الملك توتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير انك علي كل شيء قدير', 'قل لهم ملك ملك توت ملك من تشء تنزع ملك ممن تشء تعز من تشء تذل من تشء بيدك خير انك عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/3/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (319, 'قل الل لله لهم ملك الم لمل ملك توت وتي الم لمل ملك من تشء وتن تنز نزع الم لمل ملك ممن تشء وتع تعز من تشء وتذ تذل من تشء بيد يدك الخ لخي خير انك علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (320, 'quran:3:27', 'quran', 'quran', '3:27', 27, 319, 'Ali ''Imran', 'آل عمران', 'تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ', NULL, NULL, 'تولج اليل في النهار وتولج النهار في اليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب', 'تولج يل في نهر تولج نهر في يل تخرج حي من ميت تخرج ميت من حي ترزق من تشء بغير حسب', 'quran', NULL, NULL, 'https://quran.com/3/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (320, 'تول ولج الي ليل في الن لنه نهر وتو تول ولج الن لنه نهر في الي ليل وتخ تخر خرج الح لحي من الم لمي ميت وتخ تخر خرج الم لمي ميت من الح لحي وتر ترز رزق من تشء بغي غير حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (321, 'quran:3:28', 'quran', 'quran', '3:28', 28, 320, 'Ali ''Imran', 'آل عمران', 'لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ', NULL, NULL, 'لا يتخذ المومنون الكفرين اولياء من دون المومنين ومن يفعل ذلك فليس من الله في شيء الا ان تتقوا منهم تقاه ويحذركم الله نفسه والي الله المصير', 'ل يتخذ مومن كفر اوليء من دون مومن ومن يفعل ذلك ليس من له في شيء ال ان تتق من تق يحذر له نفس ول له مصير', 'quran', NULL, NULL, 'https://quran.com/3/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (321, 'ل يتخ تخذ الم لمو موم ومن منو نون الك لكف كفر فري رين اول ولي ليء من دون الم لمو موم ومن مني نين ومن يفع فعل ذلك فلي ليس من الل لله في شيء ال ان تتق تقو منه نهم تقه ويح يحذ حذر ذرك ركم الل لله نفس فسه ولي الل لله الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (322, 'quran:3:29', 'quran', 'quran', '3:29', 29, 321, 'Ali ''Imran', 'آل عمران', 'قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'قل ان تخفوا ما في صدوركم او تبدوه يعلمه الله ويعلم ما في السموت وما في الارض والله علي كل شيء قدير', 'قل ان تخف م في صدور او تبدو يعلم له يعلم م في سموت وم في ارض له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/3/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (322, 'قل ان تخف خفو م في صدو دور ورك ركم او تبد بدو دوه يعل علم لمه الل لله ويع يعل علم م في الس لسم سمو موت وم في الر لرض ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (323, 'quran:3:30', 'quran', 'quran', '3:30', 30, 322, 'Ali ''Imran', 'آل عمران', 'يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ', NULL, NULL, 'يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو ان بينها وبينه امدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد', 'يوم تجد كل نفس م عملت من خير محضر وم عملت من سوء تود لو ان بين بين امد بعيد يحذر له نفس له رءوف عبد', 'quran', NULL, NULL, 'https://quran.com/3/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (323, 'يوم تجد كل نفس م عمل ملت من خير محض حضر وم عمل ملت من سوء تود لو ان بين ينه وبي بين ينه امد بعي عيد ويح يحذ حذر ذرك ركم الل لله نفس فسه ولل لله رءو ءوف بلع لعب عبد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (324, 'quran:3:31', 'quran', 'quran', '3:31', 31, 323, 'Ali ''Imran', 'آل عمران', 'قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم', 'قل ان كنتم تحب له اتبعون يحبب له يغفر لكم ذنوب له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/3/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (324, 'قل ان كنت نتم تحب حبو بون الل لله فتب تبع بعو عون وني يحب حبب ببك بكم الل لله ويغ يغف غفر لكم ذنو نوب وبك بكم ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (325, 'quran:3:32', 'quran', 'quran', '3:32', 32, 324, 'Ali ''Imran', 'آل عمران', 'قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ', NULL, NULL, 'قل اطيعوا الله والرسول فان تولوا فان الله لا يحب الكفرين', 'قل اطيع له رسول فن تول فن له ل يحب كفر', 'quran', NULL, NULL, 'https://quran.com/3/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (325, 'قل اطي طيع يعو الل لله ولر لرس رسو سول فن تول ولو فن الل لله ل يحب الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (326, 'quran:3:33', 'quran', 'quran', '3:33', 33, 325, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ', NULL, NULL, 'ان الله اصطفي ادم ونوحا وال ابرهيم وال عمرن علي العلمين', 'ان له اصطف ادم نوح ول ابرهيم ول عمرن عل علم', 'quran', NULL, NULL, 'https://quran.com/3/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (326, 'ان الل لله اصط صطف طفي ادم ونو نوح ول ابر بره رهي هيم ول عمر مرن علي الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (327, 'quran:3:34', 'quran', 'quran', '3:34', 34, 326, 'Ali ''Imran', 'آل عمران', 'ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', NULL, NULL, 'ذريه بعضها من بعض والله سميع عليم', 'ذر بعض من بعض له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/3/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (327, 'ذري ريه بعض عضه من بعض ولل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (328, 'quran:3:35', 'quran', 'quran', '3:35', 35, 327, 'Ali ''Imran', 'آل عمران', 'إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'اذ قالت امرات عمرن رب اني نذرت لك ما في بطني محررا فتقبل مني انك انت السميع العليم', 'اذ قلت امر عمرن رب ان نذرت لك م في بطن محرر تقبل من انك انت سميع عليم', 'quran', NULL, NULL, 'https://quran.com/3/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (328, 'اذ قلت امر مرت عمر مرن رب اني نذر ذرت لك م في بطن طني محر حرر فتق تقب قبل مني انك انت الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (329, 'quran:3:36', 'quran', 'quran', '3:36', 36, 328, 'Ali ''Imran', 'آل عمران', 'فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ', NULL, NULL, 'فلما وضعتها قالت رب اني وضعتها انثي والله اعلم بما وضعت وليس الذكر كالانثي واني سميتها مريم واني اعيذها بك وذريتها من الشيطن الرجيم', 'لم ضعت قلت رب ان ضعت انث له اعلم بم ضعت ليس ذكر انث ان سميت مريم ان اعيذ بك ذريت من شيطن رجيم', 'quran', NULL, NULL, 'https://quran.com/3/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (329, 'فلم وضع ضعت عته قلت رب اني وضع ضعت عته انث نثي ولل لله اعل علم بم وضع ضعت ولي ليس الذ لذك ذكر كلن لنث نثي وني سمي ميت يته مري ريم وني اعي عيذ يذه بك وذر ذري ريت يته من الش لشي شيط يطن الر لرج رجي جيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (330, 'quran:3:37', 'quran', 'quran', '3:37', 37, 329, 'Ali ''Imran', 'آل عمران', 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ', NULL, NULL, 'فتقبلها ربها بقبول حسن وانبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يا مريم اني لك هذا قالت هو من عند الله ان الله يرزق من يشاء بغير حساب', 'تقبل رب بقبول حسن انبت نبت حس كفل زكري كلم دخل علي زكري محرب وجد عند رزق قل ي مريم ان لك هذ قلت هو من عند له ان له يرزق من يشء بغير حسب', 'quran', NULL, NULL, 'https://quran.com/3/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (330, 'فتق تقب قبل بله ربه بقب قبو بول حسن ونب نبت بته نبت حسن وكف كفل فله زكر كري كلم دخل علي ليه زكر كري الم لمح محر حرب وجد عند نده رزق قل ي مري ريم اني لك هذ قلت هو من عند الل لله ان الل لله يرز رزق من يشء بغي غير حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (331, 'quran:3:38', 'quran', 'quran', '3:38', 38, 330, 'Ali ''Imran', 'آل عمران', 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', NULL, NULL, 'هنالك دعا زكريا ربه قال رب هب لي من لدنك ذريه طيبه انك سميع الدعاء', 'هنلك دع زكري رب قل رب هب لي من لدنك ذر طيب انك سميع دعء', 'quran', NULL, NULL, 'https://quran.com/3/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (331, 'هنل نلك دع زكر كري ربه قل رب هب لي من لدن دنك ذري ريه طيب يبه انك سمي ميع الد لدع دعء');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (332, 'quran:3:39', 'quran', 'quran', '3:39', 39, 331, 'Ali ''Imran', 'آل عمران', 'فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'فنادته المليكه وهو قايم يصلي في المحراب ان الله يبشرك بيحيي مصدقا بكلمه من الله وسيدا وحصورا ونبيا من الصلحين', 'ندت مليك وهو قيم يصل في محرب ان له يبشرك بيحي مصدق بكلم من له سيد حصور نبي من صلح', 'quran', NULL, NULL, 'https://quran.com/3/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (332, 'فند ندت دته الم لمل ملي ليك يكه وهو قيم يصل صلي في الم لمح محر حرب ان الل لله يبش بشر شرك بيح يحي حيي مصد صدق بكل كلم لمه من الل لله وسي سيد وحص حصو صور ونب نبي من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (333, 'quran:3:40', 'quran', 'quran', '3:40', 40, 332, 'Ali ''Imran', 'آل عمران', 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ', NULL, NULL, 'قال رب اني يكون لي غلم وقد بلغني الكبر وامراتي عاقر قال كذلك الله يفعل ما يشاء', 'قل رب ان يك لي غلم وقد بلغن كبر امرت عقر قل كذلك له يفعل م يشء', 'quran', NULL, NULL, 'https://quran.com/3/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (333, 'قل رب اني يكو كون لي غلم وقد بلغ لغن غني الك لكب كبر ومر مرت رتي عقر قل كذل ذلك الل لله يفع فعل م يشء');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (334, 'quran:3:41', 'quran', 'quran', '3:41', 41, 333, 'Ali ''Imran', 'آل عمران', 'قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ', NULL, NULL, 'قال رب اجعل لي ايه قال ايتك الا تكلم الناس ثلثه ايام الا رمزا واذكر ربك كثيرا وسبح بالعشي والابكر', 'قل رب اجعل لي اي قل ايتك ال تكلم نس ثلث ايم ال رمز اذكر ربك كثير سبح عش ابكر', 'quran', NULL, NULL, 'https://quran.com/3/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (334, 'قل رب اجع جعل لي ايه قل ايت يتك ال تكل كلم الن لنس ثلث لثه ايم ال رمز وذك ذكر ربك كثي ثير وسب سبح بلع لعش عشي ولب لبك بكر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (335, 'quran:3:42', 'quran', 'quran', '3:42', 42, 334, 'Ali ''Imran', 'آل عمران', 'وَإِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ', NULL, NULL, 'واذ قالت المليكه يا مريم ان الله اصطفاك وطهرك واصطفاك علي نساء العلمين', 'وذ قلت مليك ي مريم ان له اصطفك طهرك اصطفك عل نسء علم', 'quran', NULL, NULL, 'https://quran.com/3/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (335, 'وذ قلت الم لمل ملي ليك يكه ي مري ريم ان الل لله اصط صطف طفك وطه طهر هرك وصط صطف طفك علي نسء الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (336, 'quran:3:43', 'quran', 'quran', '3:43', 43, 335, 'Ali ''Imran', 'آل عمران', 'يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ', NULL, NULL, 'يا مريم اقنتي لربك واسجدي واركعي مع الركعين', 'ي مريم اقنت لربك اسجد اركع مع ركع', 'quran', NULL, NULL, 'https://quran.com/3/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (336, 'ي مري ريم اقن قنت نتي لرب ربك وسج سجد جدي ورك ركع كعي مع الر لرك ركع كعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (337, 'quran:3:44', 'quran', 'quran', '3:44', 44, 336, 'Ali ''Imran', 'آل عمران', 'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ', NULL, NULL, 'ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ يلقون اقلمهم ايهم يكفل مريم وما كنت لديهم اذ يختصمون', 'ذلك من انبء غيب نوح يك وم كنت لدي اذ يلق اقلم اي يكفل مريم وم كنت لدي اذ يختصم', 'quran', NULL, NULL, 'https://quran.com/3/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (337, 'ذلك من انب نبء الغ لغي غيب نوح وحي حيه الي ليك وم كنت لدي ديه يهم اذ يلق لقو قون اقل قلم لمه مهم ايه يهم يكف كفل مري ريم وم كنت لدي ديه يهم اذ يخت ختص تصم صمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (338, 'quran:3:45', 'quran', 'quran', '3:45', 45, 337, 'Ali ''Imran', 'آل عمران', 'إِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ', NULL, NULL, 'اذ قالت المليكه يا مريم ان الله يبشرك بكلمه منه اسمه المسيح عيسي ابن مريم وجيها في الدنيا والاخره ومن المقربين', 'اذ قلت مليك ي مريم ان له يبشرك بكلم من اسم مسيح عيس ابن مريم جي في دني اخر ومن مقرب', 'quran', NULL, NULL, 'https://quran.com/3/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (338, 'اذ قلت الم لمل ملي ليك يكه ي مري ريم ان الل لله يبش بشر شرك بكل كلم لمه منه اسم سمه الم لمس مسي سيح عيس يسي ابن مري ريم وجي جيه في الد لدن دني ولخ لخر خره ومن الم لمق مقر قرب ربي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (339, 'quran:3:46', 'quran', 'quran', '3:46', 46, 338, 'Ali ''Imran', 'آل عمران', 'وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'ويكلم الناس في المهد وكهلا ومن الصلحين', 'يكلم نس في مهد كهل ومن صلح', 'quran', NULL, NULL, 'https://quran.com/3/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (339, 'ويك يكل كلم الن لنس في الم لمه مهد وكه كهل ومن الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (340, 'quran:3:47', 'quran', 'quran', '3:47', 47, 339, 'Ali ''Imran', 'آل عمران', 'قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', NULL, NULL, 'قالت رب اني يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء اذا قضي امرا فانما يقول له كن فيكون', 'قلت رب ان يك لي ولد ولم يمسسن بشر قل كذلك له يخلق م يشء اذ قض امر انم يقول له كن يك', 'quran', NULL, NULL, 'https://quran.com/3/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (340, 'قلت رب اني يكو كون لي ولد ولم يمس مسس سسن سني بشر قل كذل ذلك الل لله يخل خلق م يشء اذ قضي امر فنم يقو قول له كن فيك يكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (341, 'quran:3:48', 'quran', 'quran', '3:48', 48, 340, 'Ali ''Imran', 'آل عمران', 'وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ', NULL, NULL, 'ويعلمه الكتب والحكمه والتوراه والانجيل', 'يعلم كتب حكم تور انجيل', 'quran', NULL, NULL, 'https://quran.com/3/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (341, 'ويع يعل علم لمه الك لكت كتب ولح لحك حكم كمه ولت لتو تور وره ولن لنج نجي جيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (342, 'quran:3:49', 'quran', 'quran', '3:49', 49, 341, 'Ali ''Imran', 'آل عمران', 'وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'ورسولا الي بني اسرءيل اني قد جيتكم بايه من ربكم اني اخلق لكم من الطين كهيه الطير فانفخ فيه فيكون طيرا باذن الله وابري الاكمه والابرص واحي الموتي باذن الله وانبيكم بما تاكلون وما تدخرون في بيوتكم ان في ذلك لايه لكم ان كنتم مومنين', 'رسول ال بن اسرءيل ان قد جيت ب من رب ان اخلق لكم من طين كه طير انفخ في يك طير بذن له ابر اكم ابرص اح موت بذن له انبي بم تكل وم تدخر في بيوت ان في ذلك ل لكم ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/3/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (342, 'ورس رسو سول الي بني اسر سرء رءي ءيل اني قد جيت يتك تكم بيه من ربك بكم اني اخل خلق لكم من الط لطي طين كهي هيه الط لطي طير فنف نفخ فيه فيك يكو كون طير بذن الل لله وبر بري الك لكم كمه ولب لبر برص وحي الم لمو موت وتي بذن الل لله ونب نبي بيك يكم بم تكل كلو لون وم تدخ دخر خرو رون في بيو يوت وتك تكم ان في ذلك ليه لكم ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (343, 'quran:3:50', 'quran', 'quran', '3:50', 50, 342, 'Ali ''Imran', 'آل عمران', 'وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', NULL, NULL, 'ومصدقا لما بين يدي من التوراه ولاحل لكم بعض الذي حرم عليكم وجيتكم بايه من ربكم فاتقوا الله واطيعون', 'مصدق لم بين يد من تور لحل لكم بعض ذي حرم علي جيت ب من رب اتق له اطيع', 'quran', NULL, NULL, 'https://quran.com/3/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (343, 'ومص مصد صدق لم بين يدي من الت لتو تور وره ولح لحل لكم بعض الذ لذي حرم علي ليك يكم وجي جيت يتك تكم بيه من ربك بكم فتق تقو الل لله وطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (344, 'quran:3:51', 'quran', 'quran', '3:51', 51, 343, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ', NULL, NULL, 'ان الله ربي وربكم فاعبدوه هذا صرط مستقيم', 'ان له رب رب اعبدو هذ صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/3/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (344, 'ان الل لله ربي ورب ربك بكم فعب عبد بدو دوه هذ صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (345, 'quran:3:52', 'quran', 'quran', '3:52', 52, 344, 'Ali ''Imran', 'آل عمران', 'فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ', NULL, NULL, 'فلما احس عيسي منهم الكفر قال من انصاري الي الله قال الحواريون نحن انصار الله امنا بالله واشهد بانا مسلمون', 'لم احس عيس من كفر قل من انصر ال له قل حوري نحن انصر له ام له اشهد ب مسلم', 'quran', NULL, NULL, 'https://quran.com/3/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (345, 'فلم احس عيس يسي منه نهم الك لكف كفر قل من انص نصر صري الي الل لله قل الح لحو حور وري ريو يون نحن انص نصر الل لله امن بلل لله وشه شهد بن مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (346, 'quran:3:53', 'quran', 'quran', '3:53', 53, 345, 'Ali ''Imran', 'آل عمران', 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ', NULL, NULL, 'ربنا امنا بما انزلت واتبعنا الرسول فاكتبنا مع الشهدين', 'رب ام بم انزلت اتبع رسول اكتب مع شهد', 'quran', NULL, NULL, 'https://quran.com/3/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (346, 'ربن امن بم انز نزل زلت وتب تبع بعن الر لرس رسو سول فكت كتب تبن مع الش لشه شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (347, 'quran:3:54', 'quran', 'quran', '3:54', 54, 346, 'Ali ''Imran', 'آل عمران', 'وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ', NULL, NULL, 'ومكروا ومكر الله والله خير المكرين', 'مكر مكر له له خير مكر', 'quran', NULL, NULL, 'https://quran.com/3/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (347, 'ومك مكر كرو ومك مكر الل لله ولل لله خير الم لمك مكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (348, 'quran:3:55', 'quran', 'quran', '3:55', 55, 347, 'Ali ''Imran', 'آل عمران', 'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', NULL, NULL, 'اذ قال الله يا عيسي اني متوفيك ورافعك الي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا الي يوم القيمه ثم الي مرجعكم فاحكم بينكم فيما كنتم فيه تختلفون', 'اذ قل له ي عيس ان متوفيك رفعك ال مطهرك من ذين كفر جعل ذين اتبعوك فوق ذين كفر ال يوم قيم ثم ال مرجع اح بين يم كنتم في تختلف', 'quran', NULL, NULL, 'https://quran.com/3/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (348, 'اذ قل الل لله ي عيس يسي اني متو توف وفي فيك ورف رفع فعك الي ومط مطه طهر هرك من الذ لذي ذين كفر فرو وجع جعل الذ لذي ذين اتب تبع بعو عوك فوق الذ لذي ذين كفر فرو الي يوم الق لقي قيم يمه ثم الي مرج رجع جعك عكم فحك حكم بين ينك نكم فيم كنت نتم فيه تخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (349, 'quran:3:56', 'quran', 'quran', '3:56', 56, 348, 'Ali ''Imran', 'آل عمران', 'فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', NULL, NULL, 'فاما الذين كفروا فاعذبهم عذابا شديدا في الدنيا والاخره وما لهم من نصرين', 'ام ذين كفر اعذب عذب شديد في دني اخر وم لهم من نصر', 'quran', NULL, NULL, 'https://quran.com/3/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (349, 'فم الذ لذي ذين كفر فرو فعذ عذب ذبه بهم عذب شدي ديد في الد لدن دني ولخ لخر خره وم لهم من نصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (350, 'quran:3:57', 'quran', 'quran', '3:57', 57, 349, 'Ali ''Imran', 'آل عمران', 'وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', NULL, NULL, 'واما الذين امنوا وعملوا الصلحت فيوفيهم اجورهم والله لا يحب الظلمين', 'ام ذين امن عمل صلحت يوفي اجور له ل يحب ظلم', 'quran', NULL, NULL, 'https://quran.com/3/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (350, 'وم الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت فيو يوف وفي فيه يهم اجو جور وره رهم ولل لله ل يحب الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (351, 'quran:3:58', 'quran', 'quran', '3:58', 58, 350, 'Ali ''Imran', 'آل عمران', 'ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ', NULL, NULL, 'ذلك نتلوه عليك من الايت والذكر الحكيم', 'ذلك نتلو عليك من ايت ذكر حكيم', 'quran', NULL, NULL, 'https://quran.com/3/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (351, 'ذلك نتل تلو لوه علي ليك من الي ليت ولذ لذك ذكر الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (352, 'quran:3:59', 'quran', 'quran', '3:59', 59, 351, 'Ali ''Imran', 'آل عمران', 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', NULL, NULL, 'ان مثل عيسي عند الله كمثل ادم خلقه من تراب ثم قال له كن فيكون', 'ان مثل عيس عند له كمثل ادم خلق من ترب ثم قل له كن يك', 'quran', NULL, NULL, 'https://quran.com/3/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (352, 'ان مثل عيس يسي عند الل لله كمث مثل ادم خلق لقه من ترب ثم قل له كن فيك يكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (353, 'quran:3:60', 'quran', 'quran', '3:60', 60, 352, 'Ali ''Imran', 'آل عمران', 'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ', NULL, NULL, 'الحق من ربك فلا تكن من الممترين', 'حق من ربك فل تكن من ممتر', 'quran', NULL, NULL, 'https://quran.com/3/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (353, 'الح لحق من ربك فل تكن من الم لمم ممت متر تري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (354, 'quran:3:61', 'quran', 'quran', '3:61', 61, 353, 'Ali ''Imran', 'آل عمران', 'فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ', NULL, NULL, 'فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع ابناءنا وابناءكم ونساءنا ونساءكم وانفسنا وانفسكم ثم نبتهل فنجعل لعنت الله علي الكذبين', 'فمن حجك في من بعد م جءك من علم فقل تعل ندع ابنء ابنء نسء نسء انفس انفس ثم نبتهل نجعل لعنت له عل كذب', 'quran', NULL, NULL, 'https://quran.com/3/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (354, 'فمن حجك فيه من بعد م جءك من الع لعل علم فقل تعل علو ندع ابن بنء نءن وبن بنء نءك ءكم ونس نسء سءن ونس نسء سءك ءكم ونف نفس فسن ونف نفس فسك سكم ثم نبت بته تهل فنج نجع جعل لعن عنت الل لله علي الك لكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (355, 'quran:3:62', 'quran', 'quran', '3:62', 62, 354, 'Ali ''Imran', 'آل عمران', 'إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'ان هذا لهو القصص الحق وما من اله الا الله وان الله لهو العزيز الحكيم', 'ان هذ لهو قصص حق وم من ال ال له ون له لهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/3/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (355, 'ان هذ لهو الق لقص قصص الح لحق وم من اله ال الل لله ون الل لله لهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (356, 'quran:3:63', 'quran', 'quran', '3:63', 63, 355, 'Ali ''Imran', 'آل عمران', 'فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ', NULL, NULL, 'فان تولوا فان الله عليم بالمفسدين', 'فن تول فن له عليم مفسد', 'quran', NULL, NULL, 'https://quran.com/3/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (356, 'فن تول ولو فن الل لله علي ليم بلم لمف مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (357, 'quran:3:64', 'quran', 'quran', '3:64', 64, 356, 'Ali ''Imran', 'آل عمران', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ', NULL, NULL, 'قل يا اهل الكتب تعالوا الي كلمه سواء بيننا وبينكم الا نعبد الا الله ولا نشرك به شيا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون', 'قل ي اهل كتب تعل ال كلم سوء بين بين ال نعبد ال له ول نشرك به شي ول يتخذ بعض بعض اربب من دون له فن تول قول اشهد ب مسلم', 'quran', NULL, NULL, 'https://quran.com/3/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (357, 'قل ي اهل الك لكت كتب تعل علو الي كلم لمه سوء بين ينن وبي بين ينك نكم ال نعب عبد ال الل لله ول نشر شرك به شي ول يتخ تخذ بعض عضن بعض ارب ربب من دون الل لله فن تول ولو فقو قول ولو اشه شهد هدو بن مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (358, 'quran:3:65', 'quran', 'quran', '3:65', 65, 357, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'يا اهل الكتب لم تحاجون في ابرهيم وما انزلت التوراه والانجيل الا من بعده افلا تعقلون', 'ي اهل كتب لم تحج في ابرهيم وم انزلت تور انجيل ال من بعد افل تعقل', 'quran', NULL, NULL, 'https://quran.com/3/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (358, 'ي اهل الك لكت كتب لم تحج حجو جون في ابر بره رهي هيم وم انز نزل زلت الت لتو تور وره ولن لنج نجي جيل ال من بعد عده افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (359, 'quran:3:66', 'quran', 'quran', '3:66', 66, 358, 'Ali ''Imran', 'آل عمران', 'هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', NULL, NULL, 'هانتم هولاء حججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وانتم لا تعلمون', 'هنتم هولء حججتم يم لكم به علم فلم تحج يم ليس لكم به علم له يعلم انتم ل تعلم', 'quran', NULL, NULL, 'https://quran.com/3/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (359, 'هنت نتم هول ولء حجج ججت جتم فيم لكم به علم فلم تحج حجو جون فيم ليس لكم به علم ولل لله يعل علم ونت نتم ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (360, 'quran:3:67', 'quran', 'quran', '3:67', 67, 359, 'Ali ''Imran', 'آل عمران', 'مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'ما كان ابرهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين', 'م كن ابرهيم يهودي ول نصرني لكن كن حنيف مسلم وم كن من مشرك', 'quran', NULL, NULL, 'https://quran.com/3/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (360, 'م كن ابر بره رهي هيم يهو هود ودي ول نصر صرن رني ولك لكن كن حني نيف مسل سلم وم كن من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (361, 'quran:3:68', 'quran', 'quran', '3:68', 68, 360, 'Ali ''Imran', 'آل عمران', 'إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'ان اولي الناس بابرهيم للذين اتبعوه وهذا النبي والذين امنوا والله ولي المومنين', 'ان اول نس ببرهيم ذين اتبعو هذ نب ذين امن له ول مومن', 'quran', NULL, NULL, 'https://quran.com/3/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (361, 'ان اول ولي الن لنس ببر بره رهي هيم للذ لذي ذين اتب تبع بعو عوه وهذ الن لنب نبي ولذ لذي ذين امن منو ولل لله ولي الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (362, 'quran:3:69', 'quran', 'quran', '3:69', 69, 361, 'Ali ''Imran', 'آل عمران', 'وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', NULL, NULL, 'ودت طايفه من اهل الكتب لو يضلونكم وما يضلون الا انفسهم وما يشعرون', 'ودت طيف من اهل كتب لو يضلون وم يضل ال انفس وم يشعر', 'quran', NULL, NULL, 'https://quran.com/3/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (362, 'ودت طيف يفه من اهل الك لكت كتب لو يضل ضلو لون ونك نكم وم يضل ضلو لون ال انف نفس فسه سهم وم يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (363, 'quran:3:70', 'quran', 'quran', '3:70', 70, 362, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ', NULL, NULL, 'يا اهل الكتب لم تكفرون بايت الله وانتم تشهدون', 'ي اهل كتب لم تكفر بيت له انتم تشهد', 'quran', NULL, NULL, 'https://quran.com/3/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (363, 'ي اهل الك لكت كتب لم تكف كفر فرو رون بيت الل لله ونت نتم تشه شهد هدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (364, 'quran:3:71', 'quran', 'quran', '3:71', 71, 363, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'يا اهل الكتب لم تلبسون الحق بالبطل وتكتمون الحق وانتم تعلمون', 'ي اهل كتب لم تلبس حق بطل تكتم حق انتم تعلم', 'quran', NULL, NULL, 'https://quran.com/3/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (364, 'ي اهل الك لكت كتب لم تلب لبس بسو سون الح لحق بلب لبط بطل وتك تكت كتم تمو مون الح لحق ونت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (365, 'quran:3:72', 'quran', 'quran', '3:72', 72, 364, 'Ali ''Imran', 'آل عمران', 'وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ', NULL, NULL, 'وقالت طايفه من اهل الكتب امنوا بالذي انزل علي الذين امنوا وجه النهار واكفروا اخره لعلهم يرجعون', 'قلت طيف من اهل كتب امن ذي انزل عل ذين امن وج نهر اكفر اخر لعل يرجع', 'quran', NULL, NULL, 'https://quran.com/3/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (365, 'وقل قلت طيف يفه من اهل الك لكت كتب امن منو بلذ لذي انز نزل علي الذ لذي ذين امن منو وجه الن لنه نهر وكف كفر فرو اخر خره لعل عله لهم يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (366, 'quran:3:73', 'quran', 'quran', '3:73', 73, 365, 'Ali ''Imran', 'آل عمران', 'وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', NULL, NULL, 'ولا تومنوا الا لمن تبع دينكم قل ان الهدي هدي الله ان يوتي احد مثل ما اوتيتم او يحاجوكم عند ربكم قل ان الفضل بيد الله يوتيه من يشاء والله وسع عليم', 'ول تومن ال لمن تبع دين قل ان هد هد له ان يوت احد مثل م اوتيتم او يحجو عند رب قل ان فضل بيد له يوت من يشء له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/3/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (366, 'ول توم ومن منو ال لمن تبع دين ينك نكم قل ان اله لهد هدي هدي الل لله ان يوت وتي احد مثل م اوت وتي تيت يتم او يحج حجو جوك وكم عند ربك بكم قل ان الف لفض فضل بيد الل لله يوت وتي تيه من يشء ولل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (367, 'quran:3:74', 'quran', 'quran', '3:74', 74, 366, 'Ali ''Imran', 'آل عمران', 'يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ', NULL, NULL, 'يختص برحمته من يشاء والله ذو الفضل العظيم', 'يختص برحمت من يشء له ذو فضل عظيم', 'quran', NULL, NULL, 'https://quran.com/3/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (367, 'يخت ختص برح رحم حمت مته من يشء ولل لله ذو الف لفض فضل الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (368, 'quran:3:75', 'quran', 'quran', '3:75', 75, 367, 'Ali ''Imran', 'آل عمران', 'وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'ومن اهل الكتب من ان تامنه بقنطار يوده اليك ومنهم من ان تامنه بدينار لا يوده اليك الا ما دمت عليه قايما ذلك بانهم قالوا ليس علينا في الامين سبيل ويقولون علي الله الكذب وهم يعلمون', 'ومن اهل كتب من ان تمن بقنطر يود يك من من ان تمن بدينر ل يود يك ال م دمت عل قيم ذلك بن قل ليس علي في ام سبيل يقول عل له كذب وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/3/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (368, 'ومن اهل الك لكت كتب من ان تمن منه بقن قنط نطر يود وده الي ليك ومن منه نهم من ان تمن منه بدي دين ينر ل يود وده الي ليك ال م دمت علي ليه قيم ذلك بنه نهم قلو ليس علي لين في الم لمي مين سبي بيل ويق يقو قول ولو لون علي الل لله الك لكذ كذب وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (369, 'quran:3:76', 'quran', 'quran', '3:76', 76, 368, 'Ali ''Imran', 'آل عمران', 'بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ', NULL, NULL, 'بلي من اوفي بعهده واتقي فان الله يحب المتقين', 'بل من اوف بعهد اتق فن له يحب متق', 'quran', NULL, NULL, 'https://quran.com/3/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (369, 'بلي من اوف وفي بعه عهد هده وتق تقي فن الل لله يحب الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (370, 'quran:3:77', 'quran', 'quran', '3:77', 77, 369, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'ان الذين يشترون بعهد الله وايمنهم ثمنا قليلا اوليك لا خلق لهم في الاخره ولا يكلمهم الله ولا ينظر اليهم يوم القيمه ولا يزكيهم ولهم عذاب اليم', 'ان ذين يشتر بعهد له ايمن ثم قليل اوليك ل خلق لهم في اخر ول يكلم له ول ينظر يهم يوم قيم ول يزكي لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/3/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (370, 'ان الذ لذي ذين يشت شتر ترو رون بعه عهد الل لله ويم يمن منه نهم ثمن قلي ليل اول ولي ليك ل خلق لهم في الخ لخر خره ول يكل كلم لمه مهم الل لله ول ينظ نظر الي ليه يهم يوم الق لقي قيم يمه ول يزك زكي كيه يهم وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (371, 'quran:3:78', 'quran', 'quran', '3:78', 78, 370, 'Ali ''Imran', 'آل عمران', 'وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'وان منهم لفريقا يلون السنتهم بالكتب لتحسبوه من الكتب وما هو من الكتب ويقولون هو من عند الله وما هو من عند الله ويقولون علي الله الكذب وهم يعلمون', 'ون من لفريق يل سنت كتب لتحسبو من كتب وم هو من كتب يقول هو من عند له وم هو من عند له يقول عل له كذب وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/3/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (371, 'ون منه نهم لفر فري ريق يلو لون الس لسن سنت نته تهم بلك لكت كتب لتح تحس حسب سبو بوه من الك لكت كتب وم هو من الك لكت كتب ويق يقو قول ولو لون هو من عند الل لله وم هو من عند الل لله ويق يقو قول ولو لون علي الل لله الك لكذ كذب وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (372, 'quran:3:79', 'quran', 'quran', '3:79', 79, 371, 'Ali ''Imran', 'آل عمران', 'مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ', NULL, NULL, 'ما كان لبشر ان يوتيه الله الكتب والحكم والنبوه ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربنين بما كنتم تعلمون الكتب وبما كنتم تدرسون', 'م كن لبشر ان يوت له كتب حكم نبو ثم يقول نس كون عبد لي من دون له لكن كون ربن بم كنتم تعلم كتب بم كنتم تدرس', 'quran', NULL, NULL, 'https://quran.com/3/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (372, 'م كن لبش بشر ان يوت وتي تيه الل لله الك لكت كتب ولح لحك حكم ولن لنب نبو بوه ثم يقو قول للن لنس كون ونو عبد لي من دون الل لله ولك لكن كون ونو ربن بني نين بم كنت نتم تعل علم لمو مون الك لكت كتب وبم كنت نتم تدر درس رسو سون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (373, 'quran:3:80', 'quran', 'quran', '3:80', 80, 372, 'Ali ''Imran', 'آل عمران', 'وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ', NULL, NULL, 'ولا يامركم ان تتخذوا المليكه والنبين اربابا ايامركم بالكفر بعد اذ انتم مسلمون', 'ول يمر ان تتخذ مليك نب اربب ايمر كفر بعد اذ انتم مسلم', 'quran', NULL, NULL, 'https://quran.com/3/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (373, 'ول يمر مرك ركم ان تتخ تخذ خذو الم لمل ملي ليك يكه ولن لنب نبي بين ارب ربب ايم يمر مرك ركم بلك لكف كفر بعد اذ انت نتم مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (374, 'quran:3:81', 'quran', 'quran', '3:81', 81, 373, 'Ali ''Imran', 'آل عمران', 'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', NULL, NULL, 'واذ اخذ الله ميثق النبين لما اتيتكم من كتب وحكمه ثم جاءكم رسول مصدق لما معكم لتومنن به ولتنصرنه قال اقررتم واخذتم علي ذلكم اصري قالوا اقررنا قال فاشهدوا وانا معكم من الشهدين', 'وذ اخذ له ميثق نب لم اتيت من كتب حكم ثم جء رسول مصدق لم مع لتومنن به لتنصرن قل اقررتم اخذتم عل ذل اصر قل اقرر قل اشهد ان مع من شهد', 'quran', NULL, NULL, 'https://quran.com/3/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (374, 'وذ اخذ الل لله ميث يثق الن لنب نبي بين لم اتي تيت يتك تكم من كتب وحك حكم كمه ثم جءك ءكم رسو سول مصد صدق لم معك عكم لتو توم ومن منن به ولت لتن تنص نصر صرن رنه قل اقر قرر ررت رتم وخذ خذت ذتم علي ذلك لكم اصر صري قلو اقر قرر ررن قل فشه شهد هدو ون معك عكم من الش لشه شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (375, 'quran:3:82', 'quran', 'quran', '3:82', 82, 374, 'Ali ''Imran', 'آل عمران', 'فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', NULL, NULL, 'فمن تولي بعد ذلك فاوليك هم الفسقون', 'فمن تول بعد ذلك اوليك هم فسق', 'quran', NULL, NULL, 'https://quran.com/3/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (375, 'فمن تول ولي بعد ذلك فول ولي ليك هم الف لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (376, 'quran:3:83', 'quran', 'quran', '3:83', 83, 375, 'Ali ''Imran', 'آل عمران', 'أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ', NULL, NULL, 'افغير دين الله يبغون وله اسلم من في السموت والارض طوعا وكرها واليه يرجعون', 'افغير دين له يبغ ول اسلم من في سموت ارض طوع كر يه يرجع', 'quran', NULL, NULL, 'https://quran.com/3/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (376, 'افغ فغي غير دين الل لله يبغ بغو غون وله اسل سلم من في الس لسم سمو موت ولر لرض طوع وكر كره ولي ليه يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (377, 'quran:3:84', 'quran', 'quran', '3:84', 84, 376, 'Ali ''Imran', 'آل عمران', 'قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', NULL, NULL, 'قل امنا بالله وما انزل علينا وما انزل علي ابرهيم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي والنبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون', 'قل ام له وم انزل علي وم انزل عل ابرهيم اسمعيل اسحق يعقوب اسبط وم اوت موس عيس نبي من رب ل نفرق بين احد من نحن له مسلم', 'quran', NULL, NULL, 'https://quran.com/3/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (377, 'قل امن بلل لله وم انز نزل علي لين وم انز نزل علي ابر بره رهي هيم وسم سمع معي عيل وسح سحق ويع يعق عقو قوب ولس لسب سبط وم اوت وتي موس وسي وعي عيس يسي ولن لنب نبي بيو يون من ربه بهم ل نفر فرق بين احد منه نهم ونح نحن له مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (378, 'quran:3:85', 'quran', 'quran', '3:85', 85, 377, 'Ali ''Imran', 'آل عمران', 'وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ', NULL, NULL, 'ومن يبتغ غير الاسلم دينا فلن يقبل منه وهو في الاخره من الخسرين', 'ومن يبتغ غير اسلم دي فلن يقبل من وهو في اخر من خسر', 'quran', NULL, NULL, 'https://quran.com/3/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (378, 'ومن يبت بتغ غير الس لسل سلم دين فلن يقب قبل منه وهو في الخ لخر خره من الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (379, 'quran:3:86', 'quran', 'quran', '3:86', 86, 378, 'Ali ''Imran', 'آل عمران', 'كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ', NULL, NULL, 'كيف يهدي الله قوما كفروا بعد ايمنهم وشهدوا ان الرسول حق وجاءهم البينت والله لا يهدي القوم الظلمين', 'كيف يهد له قوم كفر بعد ايمن شهد ان رسول حق جء بينت له ل يهد قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/3/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (379, 'كيف يهد هدي الل لله قوم كفر فرو بعد ايم يمن منه نهم وشه شهد هدو ان الر لرس رسو سول حق وجء جءه ءهم الب لبي بين ينت ولل لله ل يهد هدي الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (380, 'quran:3:87', 'quran', 'quran', '3:87', 87, 379, 'Ali ''Imran', 'آل عمران', 'أُوْلَٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ', NULL, NULL, 'اوليك جزاوهم ان عليهم لعنه الله والمليكه والناس اجمعين', 'اوليك جزو ان علي لعن له مليك نس اجمع', 'quran', NULL, NULL, 'https://quran.com/3/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (380, 'اول ولي ليك جزو زوه وهم ان علي ليه يهم لعن عنه الل لله ولم لمل ملي ليك يكه ولن لنس اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (381, 'quran:3:88', 'quran', 'quran', '3:88', 88, 380, 'Ali ''Imran', 'آل عمران', 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ', NULL, NULL, 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون', 'خلد يه ل يخفف عن عذب ول هم ينظر', 'quran', NULL, NULL, 'https://quran.com/3/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (381, 'خلد لدي دين فيه ل يخف خفف عنه نهم الع لعذ عذب ول هم ينظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (382, 'quran:3:89', 'quran', 'quran', '3:89', 89, 381, 'Ali ''Imran', 'آل عمران', 'إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', NULL, NULL, 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم', 'ال ذين تب من بعد ذلك اصلح فن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/3/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (382, 'ال الذ لذي ذين تبو من بعد ذلك وصل صلح لحو فن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (383, 'quran:3:90', 'quran', 'quran', '3:90', 90, 382, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', NULL, NULL, 'ان الذين كفروا بعد ايمنهم ثم ازدادوا كفرا لن تقبل توبتهم واوليك هم الضالون', 'ان ذين كفر بعد ايمن ثم ازدد كفر لن تقبل توبت اوليك هم ضل', 'quran', NULL, NULL, 'https://quran.com/3/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (383, 'ان الذ لذي ذين كفر فرو بعد ايم يمن منه نهم ثم ازد زدد ددو كفر لن تقب قبل توب وبت بته تهم وول ولي ليك هم الض لضل ضلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (384, 'quran:3:91', 'quran', 'quran', '3:91', 91, 383, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّٰصِرِينَ', NULL, NULL, 'ان الذين كفروا وماتوا وهم كفار فلن يقبل من احدهم ملء الارض ذهبا ولو افتدي به اوليك لهم عذاب اليم وما لهم من نصرين', 'ان ذين كفر مت وهم كفر فلن يقبل من احد ملء ارض ذهب ولو افتد به اوليك لهم عذب يم وم لهم من نصر', 'quran', NULL, NULL, 'https://quran.com/3/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (384, 'ان الذ لذي ذين كفر فرو ومت متو وهم كفر فلن يقب قبل من احد حده دهم ملء الر لرض ذهب ولو افت فتد تدي به اول ولي ليك لهم عذب الي ليم وم لهم من نصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (385, 'quran:3:92', 'quran', 'quran', '3:92', 92, 384, 'Ali ''Imran', 'آل عمران', 'لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ', NULL, NULL, 'لن تنالوا البر حتي تنفقوا مما تحبون وما تنفقوا من شيء فان الله به عليم', 'لن تنل بر حت تنفق مم تحب وم تنفق من شيء فن له به عليم', 'quran', NULL, NULL, 'https://quran.com/3/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (385, 'لن تنل نلو الب لبر حتي تنف نفق فقو مم تحب حبو بون وم تنف نفق فقو من شيء فن الل لله به علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (386, 'quran:3:93', 'quran', 'quran', '3:93', 93, 385, 'Ali ''Imran', 'آل عمران', 'كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'كل الطعام كان حلا لبني اسرءيل الا ما حرم اسرءيل علي نفسه من قبل ان تنزل التوراه قل فاتوا بالتوراه فاتلوها ان كنتم صدقين', 'كل طعم كن حل لبن اسرءيل ال م حرم اسرءيل عل نفس من قبل ان تنزل تور قل ات تور اتلو ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/3/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (386, 'كل الط لطع طعم كن حل لبن بني اسر سرء رءي ءيل ال م حرم اسر سرء رءي ءيل علي نفس فسه من قبل ان تنز نزل الت لتو تور وره قل فتو بلت لتو تور وره فتل تلو لوه ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (387, 'quran:3:94', 'quran', 'quran', '3:94', 94, 386, 'Ali ''Imran', 'آل عمران', 'فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'فمن افتري علي الله الكذب من بعد ذلك فاوليك هم الظلمون', 'فمن افتر عل له كذب من بعد ذلك اوليك هم ظلم', 'quran', NULL, NULL, 'https://quran.com/3/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (387, 'فمن افت فتر تري علي الل لله الك لكذ كذب من بعد ذلك فول ولي ليك هم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (388, 'quran:3:95', 'quran', 'quran', '3:95', 95, 387, 'Ali ''Imran', 'آل عمران', 'قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'قل صدق الله فاتبعوا مله ابرهيم حنيفا وما كان من المشركين', 'قل صدق له اتبع مل ابرهيم حنيف وم كن من مشرك', 'quran', NULL, NULL, 'https://quran.com/3/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (388, 'قل صدق الل لله فتب تبع بعو مله ابر بره رهي هيم حني نيف وم كن من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (389, 'quran:3:96', 'quran', 'quran', '3:96', 96, 388, 'Ali ''Imran', 'آل عمران', 'إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ', NULL, NULL, 'ان اول بيت وضع للناس للذي ببكه مباركا وهدي للعلمين', 'ان اول بيت وضع نس ذي ببك مبرك هد علم', 'quran', NULL, NULL, 'https://quran.com/3/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (389, 'ان اول بيت وضع للن لنس للذ لذي ببك بكه مبر برك وهد هدي للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (390, 'quran:3:97', 'quran', 'quran', '3:97', 97, 389, 'Ali ''Imran', 'آل عمران', 'فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ', NULL, NULL, 'فيه ايت بينت مقام ابرهيم ومن دخله كان امنا ولله علي الناس حج البيت من استطاع اليه سبيلا ومن كفر فان الله غني عن العلمين', 'في ايت بينت مقم ابرهيم ومن دخل كن ام لل عل نس حج بيت من استطع يه سبيل ومن كفر فن له غن عن علم', 'quran', NULL, NULL, 'https://quran.com/3/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (390, 'فيه ايت بين ينت مقم ابر بره رهي هيم ومن دخل خله كن امن ولل لله علي الن لنس حج الب لبي بيت من است ستط تطع الي ليه سبي بيل ومن كفر فن الل لله غني عن الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (391, 'quran:3:98', 'quran', 'quran', '3:98', 98, 390, 'Ali ''Imran', 'آل عمران', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ', NULL, NULL, 'قل يا اهل الكتب لم تكفرون بايت الله والله شهيد علي ما تعملون', 'قل ي اهل كتب لم تكفر بيت له له شهيد عل م تعمل', 'quran', NULL, NULL, 'https://quran.com/3/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (391, 'قل ي اهل الك لكت كتب لم تكف كفر فرو رون بيت الل لله ولل لله شهي هيد علي م تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (392, 'quran:3:99', 'quran', 'quran', '3:99', 99, 391, 'Ali ''Imran', 'آل عمران', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجٗا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', NULL, NULL, 'قل يا اهل الكتب لم تصدون عن سبيل الله من امن تبغونها عوجا وانتم شهداء وما الله بغفل عما تعملون', 'قل ي اهل كتب لم تصد عن سبيل له من امن تبغون عوج انتم شهدء وم له بغفل عم تعمل', 'quran', NULL, NULL, 'https://quran.com/3/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (392, 'قل ي اهل الك لكت كتب لم تصد صدو دون عن سبي بيل الل لله من امن تبغ بغو غون ونه عوج ونت نتم شهد هدء وم الل لله بغف غفل عم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (393, 'quran:3:100', 'quran', 'quran', '3:100', 100, 392, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ', NULL, NULL, 'يا ايها الذين امنوا ان تطيعوا فريقا من الذين اوتوا الكتب يردوكم بعد ايمنكم كفرين', 'ي اي ذين امن ان تطيع ريق من ذين اوت كتب يردو بعد ايمن كفر', 'quran', NULL, NULL, 'https://quran.com/3/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (393, 'ي ايه الذ لذي ذين امن منو ان تطي طيع يعو فري ريق من الذ لذي ذين اوت وتو الك لكت كتب يرد ردو دوك وكم بعد ايم يمن منك نكم كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (394, 'quran:3:101', 'quran', 'quran', '3:101', 101, 393, 'Ali ''Imran', 'آل عمران', 'وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'وكيف تكفرون وانتم تتلي عليكم ايت الله وفيكم رسوله ومن يعتصم بالله فقد هدي الي صرط مستقيم', 'كيف تكفر انتم تتل علي ايت له في رسول ومن يعتصم له فقد هد ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/3/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (394, 'وكي كيف تكف كفر فرو رون ونت نتم تتل تلي علي ليك يكم ايت الل لله وفي فيك يكم رسو سول وله ومن يعت عتص تصم بلل لله فقد هدي الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (395, 'quran:3:102', 'quran', 'quran', '3:102', 102, 394, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ', NULL, NULL, 'يا ايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون', 'ي اي ذين امن اتق له حق تقت ول تموتن ال انتم مسلم', 'quran', NULL, NULL, 'https://quran.com/3/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (395, 'ي ايه الذ لذي ذين امن منو اتق تقو الل لله حق تقت قته ول تمو موت وتن ال ونت نتم مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (396, 'quran:3:103', 'quran', 'quran', '3:103', 103, 395, 'Ali ''Imran', 'آل عمران', 'وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ', NULL, NULL, 'واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمت الله عليكم اذ كنتم اعداء فالف بين قلوبكم فاصبحتم بنعمته اخونا وكنتم علي شفا حفره من النار فانقذكم منها كذلك يبين الله لكم ايته لعلكم تهتدون', 'اعتصم بحبل له جميع ول تفرق اذكر نعمت له علي اذ كنتم اعدء فلف بين قلوب اصبحتم بنعمت اخو كنتم عل شف حفر من نر انقذ من كذلك يب له لكم ايت لعل تهتد', 'quran', NULL, NULL, 'https://quran.com/3/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (396, 'وعت عتص تصم صمو بحب حبل الل لله جمي ميع ول تفر فرق رقو وذك ذكر كرو نعم عمت الل لله علي ليك يكم اذ كنت نتم اعد عدء فلف بين قلو لوب وبك بكم فصب صبح بحت حتم بنع نعم عمت مته اخو خون وكن كنت نتم علي شف حفر فره من الن لنر فنق نقذ قذك ذكم منه كذل ذلك يبي بين الل لله لكم ايت يته لعل علك لكم تهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (397, 'quran:3:104', 'quran', 'quran', '3:104', 104, 396, 'Ali ''Imran', 'آل عمران', 'وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'ولتكن منكم امه يدعون الي الخير ويامرون بالمعروف وينهون عن المنكر واوليك هم المفلحون', 'لتكن من ام يدع ال خير يمر معروف ينه عن منكر اوليك هم مفلح', 'quran', NULL, NULL, 'https://quran.com/3/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (397, 'ولت لتك تكن منك نكم امه يدع دعو عون الي الخ لخي خير ويم يمر مرو رون بلم لمع معر عرو روف وين ينه نهو هون عن الم لمن منك نكر وول ولي ليك هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (398, 'quran:3:105', 'quran', 'quran', '3:105', 105, 397, 'Ali ''Imran', 'آل عمران', 'وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ', NULL, NULL, 'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينت واوليك لهم عذاب عظيم', 'ول تكون ذين تفرق اختلف من بعد م جء بينت اوليك لهم عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/3/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (398, 'ول تكو كون ونو كلذ لذي ذين تفر فرق رقو وخت ختل تلف لفو من بعد م جءه ءهم الب لبي بين ينت وول ولي ليك لهم عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (399, 'quran:3:106', 'quran', 'quran', '3:106', 106, 398, 'Ali ''Imran', 'آل عمران', 'يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ', NULL, NULL, 'يوم تبيض وجوه وتسود وجوه فاما الذين اسودت وجوههم اكفرتم بعد ايمنكم فذوقوا العذاب بما كنتم تكفرون', 'يوم تبيض جو تسود جو ام ذين اسودت جوه اكفرتم بعد ايمن ذوق عذب بم كنتم تكفر', 'quran', NULL, NULL, 'https://quran.com/3/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (399, 'يوم تبي بيض وجو جوه وتس تسو سود وجو جوه فم الذ لذي ذين اسو سود ودت وجو جوه وهه ههم اكف كفر فرت رتم بعد ايم يمن منك نكم فذو ذوق وقو الع لعذ عذب بم كنت نتم تكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (400, 'quran:3:107', 'quran', 'quran', '3:107', 107, 399, 'Ali ''Imran', 'آل عمران', 'وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'واما الذين ابيضت وجوههم ففي رحمه الله هم فيها خلدون', 'ام ذين ابيضت جوه فف رحم له هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/3/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (400, 'وم الذ لذي ذين ابي بيض يضت وجو جوه وهه ههم ففي رحم حمه الل لله هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (401, 'quran:3:108', 'quran', 'quran', '3:108', 108, 400, 'Ali ''Imran', 'آل عمران', 'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ', NULL, NULL, 'تلك ايت الله نتلوها عليك بالحق وما الله يريد ظلما للعلمين', 'تلك ايت له نتلو عليك حق وم له يريد ظلم علم', 'quran', NULL, NULL, 'https://quran.com/3/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (401, 'تلك ايت الل لله نتل تلو لوه علي ليك بلح لحق وم الل لله يري ريد ظلم للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (402, 'quran:3:109', 'quran', 'quran', '3:109', 109, 401, 'Ali ''Imran', 'آل عمران', 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', NULL, NULL, 'ولله ما في السموت وما في الارض والي الله ترجع الامور', 'لل م في سموت وم في ارض ول له ترجع امور', 'quran', NULL, NULL, 'https://quran.com/3/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (402, 'ولل لله م في الس لسم سمو موت وم في الر لرض ولي الل لله ترج رجع الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (403, 'quran:3:110', 'quran', 'quran', '3:110', 110, 402, 'Ali ''Imran', 'آل عمران', 'كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ', NULL, NULL, 'كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله ولو امن اهل الكتب لكان خيرا لهم منهم المومنون واكثرهم الفسقون', 'كنتم خير ام اخرجت نس تمر معروف تنه عن منكر تومن له ولو امن اهل كتب لك خير لهم من مومن اكثر فسق', 'quran', NULL, NULL, 'https://quran.com/3/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (403, 'كنت نتم خير امه اخر خرج رجت للن لنس تمر مرو رون بلم لمع معر عرو روف وتن تنه نهو هون عن الم لمن منك نكر وتو توم ومن منو نون بلل لله ولو امن اهل الك لكت كتب لكن خير لهم منه نهم الم لمو موم ومن منو نون وكث كثر ثره رهم الف لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (404, 'quran:3:111', 'quran', 'quran', '3:111', 111, 403, 'Ali ''Imran', 'آل عمران', 'لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ', NULL, NULL, 'لن يضروكم الا اذي وان يقتلوكم يولوكم الادبار ثم لا ينصرون', 'لن يضرو ال اذ ون يقتلو يولو ادبر ثم ل ينصر', 'quran', NULL, NULL, 'https://quran.com/3/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (404, 'لن يضر ضرو روك وكم ال اذي ون يقت قتل تلو لوك وكم يول ولو لوك وكم الد لدب دبر ثم ل ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (405, 'quran:3:112', 'quran', 'quran', '3:112', 112, 404, 'Ali ''Imran', 'آل عمران', 'ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', NULL, NULL, 'ضربت عليهم الذله اين ما ثقفوا الا بحبل من الله وحبل من الناس وباءو بغضب من الله وضربت عليهم المسكنه ذلك بانهم كانوا يكفرون بايت الله ويقتلون الانبياء بغير حق ذلك بما عصوا وكانوا يعتدون', 'ضربت علي ذل اين م ثقف ال بحبل من له حبل من نس بءو بغضب من له ضربت علي مسكن ذلك بن كن يكفر بيت له يقتل انبيء بغير حق ذلك بم عص كن يعتد', 'quran', NULL, NULL, 'https://quran.com/3/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (405, 'ضرب ربت علي ليه يهم الذ لذل ذله اين م ثقف قفو ال بحب حبل من الل لله وحب حبل من الن لنس وبء بءو بغض غضب من الل لله وضر ضرب ربت علي ليه يهم الم لمس مسك سكن كنه ذلك بنه نهم كنو يكف كفر فرو رون بيت الل لله ويق يقت قتل تلو لون الن لنب نبي بيء بغي غير حق ذلك بم عصو وكن كنو يعت عتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (406, 'quran:3:113', 'quran', 'quran', '3:113', 113, 405, 'Ali ''Imran', 'آل عمران', 'لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ', NULL, NULL, 'ليسوا سواء من اهل الكتب امه قايمه يتلون ايت الله اناء اليل وهم يسجدون', 'ليس سوء من اهل كتب ام قيم يتل ايت له انء يل وهم يسجد', 'quran', NULL, NULL, 'https://quran.com/3/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (406, 'ليس يسو سوء من اهل الك لكت كتب امه قيم يمه يتل تلو لون ايت الل لله انء الي ليل وهم يسج سجد جدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (407, 'quran:3:114', 'quran', 'quran', '3:114', 114, 406, 'Ali ''Imran', 'آل عمران', 'يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'يومنون بالله واليوم الاخر ويامرون بالمعروف وينهون عن المنكر ويسرعون في الخيرت واوليك من الصلحين', 'يومن له يوم اخر يمر معروف ينه عن منكر يسرع في خيرت اوليك من صلح', 'quran', NULL, NULL, 'https://quran.com/3/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (407, 'يوم ومن منو نون بلل لله ولي ليو يوم الخ لخر ويم يمر مرو رون بلم لمع معر عرو روف وين ينه نهو هون عن الم لمن منك نكر ويس يسر سرع رعو عون في الخ لخي خير يرت وول ولي ليك من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (408, 'quran:3:115', 'quran', 'quran', '3:115', 115, 407, 'Ali ''Imran', 'آل عمران', 'وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ', NULL, NULL, 'وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين', 'وم يفعل من خير فلن يكفرو له عليم متق', 'quran', NULL, NULL, 'https://quran.com/3/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (408, 'وم يفع فعل علو من خير فلن يكف كفر فرو روه ولل لله علي ليم بلم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (409, 'quran:3:116', 'quran', 'quran', '3:116', 116, 408, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واوليك اصحب النار هم فيها خلدون', 'ان ذين كفر لن تغن عن امول ول اولد من له شي اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/3/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (409, 'ان الذ لذي ذين كفر فرو لن تغن غني عنه نهم امو مول وله لهم ول اول ولد لده دهم من الل لله شي وول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (410, 'quran:3:117', 'quran', 'quran', '3:117', 117, 409, 'Ali ''Imran', 'آل عمران', 'مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ', NULL, NULL, 'مثل ما ينفقون في هذه الحياه الدنيا كمثل ريح فيها صر اصابت حرث قوم ظلموا انفسهم فاهلكته وما ظلمهم الله ولكن انفسهم يظلمون', 'مثل م ينفق في هذ حي دني كمثل ريح يه صر اصبت حرث قوم ظلم انفس اهلكت وم ظلم له لكن انفس يظلم', 'quran', NULL, NULL, 'https://quran.com/3/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (410, 'مثل م ينف نفق فقو قون في هذه الح لحي حيه الد لدن دني كمث مثل ريح فيه صر اصب صبت حرث قوم ظلم لمو انف نفس فسه سهم فهل هلك لكت كته وم ظلم لمه مهم الل لله ولك لكن انف نفس فسه سهم يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (411, 'quran:3:118', 'quran', 'quran', '3:118', 118, 410, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ', NULL, NULL, 'يا ايها الذين امنوا لا تتخذوا بطانه من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افوههم وما تخفي صدورهم اكبر قد بينا لكم الايت ان كنتم تعقلون', 'ي اي ذين امن ل تتخذ بطن من دون ل يلون خبل دو م عنتم قد بدت بغضء من افوه وم تخف صدور اكبر قد بي لكم ايت ان كنتم تعقل', 'quran', NULL, NULL, 'https://quran.com/3/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (411, 'ي ايه الذ لذي ذين امن منو ل تتخ تخذ خذو بطن طنه من دون ونك نكم ل يلو لون ونك نكم خبل ودو م عنت نتم قد بدت الب لبغ بغض غضء من افو فوه وهه ههم وم تخف خفي صدو دور وره رهم اكب كبر قد بين لكم الي ليت ان كنت نتم تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (412, 'quran:3:119', 'quran', 'quran', '3:119', 119, 411, 'Ali ''Imran', 'آل عمران', 'هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'هانتم اولاء تحبونهم ولا يحبونكم وتومنون بالكتب كله واذا لقوكم قالوا امنا واذا خلوا عضوا عليكم الانامل من الغيظ قل موتوا بغيظكم ان الله عليم بذات الصدور', 'هنتم اولء تحبون ول يحبون تومن كتب كل اذ لقو قل ام اذ خل عض علي انمل من غيظ قل موت بغيظ ان له عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/3/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (412, 'هنت نتم اول ولء تحب حبو بون ونه نهم ول يحب حبو بون ونك نكم وتو توم ومن منو نون بلك لكت كتب كله وذ لقو قوك وكم قلو امن وذ خلو عضو علي ليك يكم الن لنم نمل من الغ لغي غيظ قل موت وتو بغي غيظ يظك ظكم ان الل لله علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (413, 'quran:3:120', 'quran', 'quran', '3:120', 120, 412, 'Ali ''Imran', 'آل عمران', 'إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ', NULL, NULL, 'ان تمسسكم حسنه تسوهم وان تصبكم سييه يفرحوا بها وان تصبروا وتتقوا لا يضركم كيدهم شيا ان الله بما يعملون محيط', 'ان تمسس حسن تسو ون تصب سي يفرح به ون تصبر تتق ل يضر كيد شي ان له بم يعمل محيط', 'quran', NULL, NULL, 'https://quran.com/3/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (413, 'ان تمس مسس سسك سكم حسن سنه تسو سوه وهم ون تصب صبك بكم سيي ييه يفر فرح رحو به ون تصب صبر برو وتت تتق تقو ل يضر ضرك ركم كيد يده دهم شي ان الل لله بم يعم عمل ملو لون محي حيط');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (414, 'quran:3:121', 'quran', 'quran', '3:121', 121, 413, 'Ali ''Imran', 'آل عمران', 'وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', NULL, NULL, 'واذ غدوت من اهلك تبوي المومنين مقعد للقتال والله سميع عليم', 'وذ غدوت من اهلك تبو مومن مقعد قتل له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/3/121');
INSERT INTO units_tri_src (id, ar_tri) VALUES (414, 'وذ غدو دوت من اهل هلك تبو بوي الم لمو موم ومن مني نين مقع قعد للق لقت قتل ولل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (415, 'quran:3:122', 'quran', 'quran', '3:122', 122, 414, 'Ali ''Imran', 'آل عمران', 'إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', NULL, NULL, 'اذ همت طايفتان منكم ان تفشلا والله وليهما وعلي الله فليتوكل المومنون', 'اذ همت طيفت من ان تفشل له ليهم عل له ليتوكل مومن', 'quran', NULL, NULL, 'https://quran.com/3/122');
INSERT INTO units_tri_src (id, ar_tri) VALUES (415, 'اذ همت طيف يفت فتن منك نكم ان تفش فشل ولل لله ولي ليه يهم وعل علي الل لله فلي ليت يتو توك وكل الم لمو موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (416, 'quran:3:123', 'quran', 'quran', '3:123', 123, 415, 'Ali ''Imran', 'آل عمران', 'وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'ولقد نصركم الله ببدر وانتم اذله فاتقوا الله لعلكم تشكرون', 'لقد نصر له ببدر انتم اذل اتق له لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/3/123');
INSERT INTO units_tri_src (id, ar_tri) VALUES (416, 'ولق لقد نصر صرك ركم الل لله ببد بدر ونت نتم اذل ذله فتق تقو الل لله لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (417, 'quran:3:124', 'quran', 'quran', '3:124', 124, 416, 'Ali ''Imran', 'آل عمران', 'إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُنزَلِينَ', NULL, NULL, 'اذ تقول للمومنين الن يكفيكم ان يمدكم ربكم بثلثه الف من المليكه منزلين', 'اذ تقول مومن الن يكفي ان يمد رب بثلث الف من مليك منزل', 'quran', NULL, NULL, 'https://quran.com/3/124');
INSERT INTO units_tri_src (id, ar_tri) VALUES (417, 'اذ تقو قول للم لمو موم ومن مني نين الن يكف كفي فيك يكم ان يمد مدك دكم ربك بكم بثل ثلث لثه الف من الم لمل ملي ليك يكه منز نزل زلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (418, 'quran:3:125', 'quran', 'quran', '3:125', 125, 417, 'Ali ''Imran', 'آل عمران', 'بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ', NULL, NULL, 'بلي ان تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسه الف من المليكه مسومين', 'بل ان تصبر تتق يتو من ور هذ يمدد رب بخمس الف من مليك مسوم', 'quran', NULL, NULL, 'https://quran.com/3/125');
INSERT INTO units_tri_src (id, ar_tri) VALUES (418, 'بلي ان تصب صبر برو وتت تتق تقو ويت يتو توك وكم من فور وره رهم هذ يمد مدد ددك دكم ربك بكم بخم خمس مسه الف من الم لمل ملي ليك يكه مسو سوم ومي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (419, 'quran:3:126', 'quran', 'quran', '3:126', 126, 418, 'Ali ''Imran', 'آل عمران', 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ', NULL, NULL, 'وما جعله الله الا بشري لكم ولتطمين قلوبكم به وما النصر الا من عند الله العزيز الحكيم', 'وم جعل له ال بشر لكم لتطم قلوب به وم نصر ال من عند له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/3/126');
INSERT INTO units_tri_src (id, ar_tri) VALUES (419, 'وم جعل عله الل لله ال بشر شري لكم ولت لتط تطم طمي مين قلو لوب وبك بكم به وم الن لنص نصر ال من عند الل لله الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (420, 'quran:3:127', 'quran', 'quran', '3:127', 127, 419, 'Ali ''Imran', 'آل عمران', 'لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ', NULL, NULL, 'ليقطع طرفا من الذين كفروا او يكبتهم فينقلبوا خايبين', 'ليقطع طرف من ذين كفر او يكبت ينقلب خيب', 'quran', NULL, NULL, 'https://quran.com/3/127');
INSERT INTO units_tri_src (id, ar_tri) VALUES (420, 'ليق يقط قطع طرف من الذ لذي ذين كفر فرو او يكب كبت بته تهم فين ينق نقل قلب لبو خيب يبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (421, 'quran:3:128', 'quran', 'quran', '3:128', 128, 420, 'Ali ''Imran', 'آل عمران', 'لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ', NULL, NULL, 'ليس لك من الامر شيء او يتوب عليهم او يعذبهم فانهم ظلمون', 'ليس لك من امر شيء او يتوب علي او يعذب ان ظلم', 'quran', NULL, NULL, 'https://quran.com/3/128');
INSERT INTO units_tri_src (id, ar_tri) VALUES (421, 'ليس لك من الم لمر شيء او يتو توب علي ليه يهم او يعذ عذب ذبه بهم فنه نهم ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (422, 'quran:3:129', 'quran', 'quran', '3:129', 129, 421, 'Ali ''Imran', 'آل عمران', 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'ولله ما في السموت وما في الارض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم', 'لل م في سموت وم في ارض يغفر لمن يشء يعذب من يشء له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/3/129');
INSERT INTO units_tri_src (id, ar_tri) VALUES (422, 'ولل لله م في الس لسم سمو موت وم في الر لرض يغف غفر لمن يشء ويع يعذ عذب من يشء ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (423, 'quran:3:130', 'quran', 'quran', '3:130', 130, 422, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يا ايها الذين امنوا لا تاكلوا الرباا اضعفا مضعفه واتقوا الله لعلكم تفلحون', 'ي اي ذين امن ل تكل رب اضعف مضعف اتق له لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/3/130');
INSERT INTO units_tri_src (id, ar_tri) VALUES (423, 'ي ايه الذ لذي ذين امن منو ل تكل كلو الر لرب اضع ضعف مضع ضعف عفه وتق تقو الل لله لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (424, 'quran:3:131', 'quran', 'quran', '3:131', 131, 423, 'Ali ''Imran', 'آل عمران', 'وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ', NULL, NULL, 'واتقوا النار التي اعدت للكفرين', 'اتق نر تي اعدت كفر', 'quran', NULL, NULL, 'https://quran.com/3/131');
INSERT INTO units_tri_src (id, ar_tri) VALUES (424, 'وتق تقو الن لنر الت لتي اعد عدت للك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (425, 'quran:3:132', 'quran', 'quran', '3:132', 132, 424, 'Ali ''Imran', 'آل عمران', 'وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ', NULL, NULL, 'واطيعوا الله والرسول لعلكم ترحمون', 'اطيع له رسول لعل ترحم', 'quran', NULL, NULL, 'https://quran.com/3/132');
INSERT INTO units_tri_src (id, ar_tri) VALUES (425, 'وطي طيع يعو الل لله ولر لرس رسو سول لعل علك لكم ترح رحم حمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (426, 'quran:3:133', 'quran', 'quran', '3:133', 133, 425, 'Ali ''Imran', 'آل عمران', 'وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ', NULL, NULL, 'وسارعوا الي مغفره من ربكم وجنه عرضها السموت والارض اعدت للمتقين', 'سرع ال مغفر من رب جن عرض سموت ارض اعدت متق', 'quran', NULL, NULL, 'https://quran.com/3/133');
INSERT INTO units_tri_src (id, ar_tri) VALUES (426, 'وسر سرع رعو الي مغف غفر فره من ربك بكم وجن جنه عرض رضه الس لسم سمو موت ولر لرض اعد عدت للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (427, 'quran:3:134', 'quran', 'quran', '3:134', 134, 426, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'الذين ينفقون في السراء والضراء والكظمين الغيظ والعافين عن الناس والله يحب المحسنين', 'ذين ينفق في سرء ضرء كظم غيظ عف عن نس له يحب محسن', 'quran', NULL, NULL, 'https://quran.com/3/134');
INSERT INTO units_tri_src (id, ar_tri) VALUES (427, 'الذ لذي ذين ينف نفق فقو قون في الس لسر سرء ولض لضر ضرء ولك لكظ كظم ظمي مين الغ لغي غيظ ولع لعف عفي فين عن الن لنس ولل لله يحب الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (428, 'quran:3:135', 'quran', 'quran', '3:135', 135, 427, 'Ali ''Imran', 'آل عمران', 'وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'والذين اذا فعلوا فحشه او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا علي ما فعلوا وهم يعلمون', 'ذين اذ عل حش او ظلم انفس ذكر له استغفر لذنوب ومن يغفر ذنوب ال له ولم يصر عل م عل وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/3/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (428, 'ولذ لذي ذين اذ فعل علو فحش حشه او ظلم لمو انف نفس فسه سهم ذكر كرو الل لله فست ستغ تغف غفر فرو لذن ذنو نوب وبه بهم ومن يغف غفر الذ لذن ذنو نوب ال الل لله ولم يصر صرو علي م فعل علو وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (429, 'quran:3:136', 'quran', 'quran', '3:136', 136, 428, 'Ali ''Imran', 'آل عمران', 'أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ', NULL, NULL, 'اوليك جزاوهم مغفره من ربهم وجنت تجري من تحتها الانهر خلدين فيها ونعم اجر العملين', 'اوليك جزو مغفر من رب جنت تجر من تحت انهر خلد يه نعم اجر عمل', 'quran', NULL, NULL, 'https://quran.com/3/136');
INSERT INTO units_tri_src (id, ar_tri) VALUES (429, 'اول ولي ليك جزو زوه وهم مغف غفر فره من ربه بهم وجن جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ونع نعم اجر الع لعم عمل ملي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (430, 'quran:3:137', 'quran', 'quran', '3:137', 137, 429, 'Ali ''Imran', 'آل عمران', 'قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ', NULL, NULL, 'قد خلت من قبلكم سنن فسيروا في الارض فانظروا كيف كان عقبه المكذبين', 'قد خلت من قبل سنن سير في ارض انظر كيف كن عقب مكذب', 'quran', NULL, NULL, 'https://quran.com/3/137');
INSERT INTO units_tri_src (id, ar_tri) VALUES (430, 'قد خلت من قبل بلك لكم سنن فسي سير يرو في الر لرض فنظ نظر ظرو كيف كن عقب قبه الم لمك مكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (431, 'quran:3:138', 'quran', 'quran', '3:138', 138, 430, 'Ali ''Imran', 'آل عمران', 'هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ', NULL, NULL, 'هذا بيان للناس وهدي وموعظه للمتقين', 'هذ بي نس هد موعظ متق', 'quran', NULL, NULL, 'https://quran.com/3/138');
INSERT INTO units_tri_src (id, ar_tri) VALUES (431, 'هذ بين للن لنس وهد هدي ومو موع وعظ عظه للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (432, 'quran:3:139', 'quran', 'quran', '3:139', 139, 431, 'Ali ''Imran', 'آل عمران', 'وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'ولا تهنوا ولا تحزنوا وانتم الاعلون ان كنتم مومنين', 'ول تهن ول تحزن انتم اعل ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/3/139');
INSERT INTO units_tri_src (id, ar_tri) VALUES (432, 'ول تهن هنو ول تحز حزن زنو ونت نتم الع لعل علو لون ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (433, 'quran:3:140', 'quran', 'quran', '3:140', 140, 432, 'Ali ''Imran', 'آل عمران', 'إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', NULL, NULL, 'ان يمسسكم قرح فقد مس القوم قرح مثله وتلك الايام نداولها بين الناس وليعلم الله الذين امنوا ويتخذ منكم شهداء والله لا يحب الظلمين', 'ان يمسس قرح فقد مس قوم قرح مثل تلك ايم ندول بين نس ليعلم له ذين امن يتخذ من شهدء له ل يحب ظلم', 'quran', NULL, NULL, 'https://quran.com/3/140');
INSERT INTO units_tri_src (id, ar_tri) VALUES (433, 'ان يمس مسس سسك سكم قرح فقد مس الق لقو قوم قرح مثل ثله وتل تلك الي ليم ندو دول وله بين الن لنس ولي ليع يعل علم الل لله الذ لذي ذين امن منو ويت يتخ تخذ منك نكم شهد هدء ولل لله ل يحب الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (434, 'quran:3:141', 'quran', 'quran', '3:141', 141, 433, 'Ali ''Imran', 'آل عمران', 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'وليمحص الله الذين امنوا ويمحق الكفرين', 'ليمحص له ذين امن يمحق كفر', 'quran', NULL, NULL, 'https://quran.com/3/141');
INSERT INTO units_tri_src (id, ar_tri) VALUES (434, 'ولي ليم يمح محص الل لله الذ لذي ذين امن منو ويم يمح محق الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (435, 'quran:3:142', 'quran', 'quran', '3:142', 142, 434, 'Ali ''Imran', 'آل عمران', 'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ', NULL, NULL, 'ام حسبتم ان تدخلوا الجنه ولما يعلم الله الذين جهدوا منكم ويعلم الصبرين', 'ام حسبتم ان تدخل جن لم يعلم له ذين جهد من يعلم صبر', 'quran', NULL, NULL, 'https://quran.com/3/142');
INSERT INTO units_tri_src (id, ar_tri) VALUES (435, 'ام حسب سبت بتم ان تدخ دخل خلو الج لجن جنه ولم يعل علم الل لله الذ لذي ذين جهد هدو منك نكم ويع يعل علم الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (436, 'quran:3:143', 'quran', 'quran', '3:143', 143, 435, 'Ali ''Imran', 'آل عمران', 'وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ', NULL, NULL, 'ولقد كنتم تمنون الموت من قبل ان تلقوه فقد رايتموه وانتم تنظرون', 'لقد كنتم تمن موت من قبل ان تلقو فقد ريتمو انتم تنظر', 'quran', NULL, NULL, 'https://quran.com/3/143');
INSERT INTO units_tri_src (id, ar_tri) VALUES (436, 'ولق لقد كنت نتم تمن منو نون الم لمو موت من قبل ان تلق لقو قوه فقد ريت يتم تمو موه ونت نتم تنظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (437, 'quran:3:144', 'quran', 'quran', '3:144', 144, 436, 'Ali ''Imran', 'آل عمران', 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ', NULL, NULL, 'وما محمد الا رسول قد خلت من قبله الرسل افاين مات او قتل انقلبتم علي اعقبكم ومن ينقلب علي عقبيه فلن يضر الله شيا وسيجزي الله الشكرين', 'وم محمد ال رسول قد خلت من قبل رسل اف مت او قتل انقلبتم عل اعقب ومن ينقلب عل عقب فلن يضر له شي سيجز له شكر', 'quran', NULL, NULL, 'https://quran.com/3/144');
INSERT INTO units_tri_src (id, ar_tri) VALUES (437, 'وم محم حمد ال رسو سول قد خلت من قبل بله الر لرس رسل افي فين مت او قتل انق نقل قلب لبت بتم علي اعق عقب قبك بكم ومن ينق نقل قلب علي عقب قبي بيه فلن يضر الل لله شي وسي سيج يجز جزي الل لله الش لشك شكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (438, 'quran:3:145', 'quran', 'quran', '3:145', 145, 437, 'Ali ''Imran', 'آل عمران', 'وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ', NULL, NULL, 'وما كان لنفس ان تموت الا باذن الله كتبا موجلا ومن يرد ثواب الدنيا نوته منها ومن يرد ثواب الاخره نوته منها وسنجزي الشكرين', 'وم كن لنفس ان تموت ال بذن له كتب موجل ومن يرد ثوب دني نوت من ومن يرد ثوب اخر نوت من سنجز شكر', 'quran', NULL, NULL, 'https://quran.com/3/145');
INSERT INTO units_tri_src (id, ar_tri) VALUES (438, 'وم كن لنف نفس ان تمو موت ال بذن الل لله كتب موج وجل ومن يرد ثوب الد لدن دني نوت وته منه ومن يرد ثوب الخ لخر خره نوت وته منه وسن سنج نجز جزي الش لشك شكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (439, 'quran:3:146', 'quran', 'quran', '3:146', 146, 438, 'Ali ''Imran', 'آل عمران', 'وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', NULL, NULL, 'وكاين من نبي قتل معه ربيون كثير فما وهنوا لما اصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصبرين', 'ك من نب قتل مع ربي كثير فم هن لم اصب في سبيل له وم ضعف وم استكن له يحب صبر', 'quran', NULL, NULL, 'https://quran.com/3/146');
INSERT INTO units_tri_src (id, ar_tri) VALUES (439, 'وكي كين من نبي قتل معه ربي بيو يون كثي ثير فم وهن هنو لم اصب صبه بهم في سبي بيل الل لله وم ضعف عفو وم است ستك تكن كنو ولل لله يحب الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (440, 'quran:3:147', 'quran', 'quran', '3:147', 147, 439, 'Ali ''Imran', 'آل عمران', 'وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', NULL, NULL, 'وما كان قولهم الا ان قالوا ربنا اغفر لنا ذنوبنا واسرافنا في امرنا وثبت اقدامنا وانصرنا علي القوم الكفرين', 'وم كن قول ال ان قل رب اغفر لن ذنوب اسرف في امر ثبت اقدم انصر عل قوم كفر', 'quran', NULL, NULL, 'https://quran.com/3/147');
INSERT INTO units_tri_src (id, ar_tri) VALUES (440, 'وم كن قول وله لهم ال ان قلو ربن اغف غفر لن ذنو نوب وبن وسر سرف رفن في امر مرن وثب ثبت اقد قدم دمن ونص نصر صرن علي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (441, 'quran:3:148', 'quran', 'quran', '3:148', 148, 440, 'Ali ''Imran', 'آل عمران', 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'فاتاهم الله ثواب الدنيا وحسن ثواب الاخره والله يحب المحسنين', 'ات له ثوب دني حسن ثوب اخر له يحب محسن', 'quran', NULL, NULL, 'https://quran.com/3/148');
INSERT INTO units_tri_src (id, ar_tri) VALUES (441, 'فته تهم الل لله ثوب الد لدن دني وحس حسن ثوب الخ لخر خره ولل لله يحب الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (442, 'quran:3:149', 'quran', 'quran', '3:149', 149, 441, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ', NULL, NULL, 'يا ايها الذين امنوا ان تطيعوا الذين كفروا يردوكم علي اعقبكم فتنقلبوا خسرين', 'ي اي ذين امن ان تطيع ذين كفر يردو عل اعقب تنقلب خسر', 'quran', NULL, NULL, 'https://quran.com/3/149');
INSERT INTO units_tri_src (id, ar_tri) VALUES (442, 'ي ايه الذ لذي ذين امن منو ان تطي طيع يعو الذ لذي ذين كفر فرو يرد ردو دوك وكم علي اعق عقب قبك بكم فتن تنق نقل قلب لبو خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (443, 'quran:3:150', 'quran', 'quran', '3:150', 150, 442, 'Ali ''Imran', 'آل عمران', 'بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّٰصِرِينَ', NULL, NULL, 'بل الله مولاكم وهو خير النصرين', 'بل له مول وهو خير نصر', 'quran', NULL, NULL, 'https://quran.com/3/150');
INSERT INTO units_tri_src (id, ar_tri) VALUES (443, 'بل الل لله مول ولك لكم وهو خير الن لنص نصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (444, 'quran:3:151', 'quran', 'quran', '3:151', 151, 443, 'Ali ''Imran', 'آل عمران', 'سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّٰلِمِينَ', NULL, NULL, 'سنلقي في قلوب الذين كفروا الرعب بما اشركوا بالله ما لم ينزل به سلطنا وماواهم النار وبيس مثوي الظلمين', 'سنلق في قلوب ذين كفر رعب بم اشرك له م لم ينزل به سلط مو نر بيس مثو ظلم', 'quran', NULL, NULL, 'https://quran.com/3/151');
INSERT INTO units_tri_src (id, ar_tri) VALUES (444, 'سنل نلق لقي في قلو لوب الذ لذي ذين كفر فرو الر لرع رعب بم اشر شرك ركو بلل لله م لم ينز نزل به سلط لطن ومو موه وهم الن لنر وبي بيس مثو ثوي الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (445, 'quran:3:152', 'quran', 'quran', '3:152', 152, 444, 'Ali ''Imran', 'آل عمران', 'وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'ولقد صدقكم الله وعده اذ تحسونهم باذنه حتي اذا فشلتم وتنزعتم في الامر وعصيتم من بعد ما اراكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الاخره ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل علي المومنين', 'لقد صدق له عد اذ تحسون بذن حت اذ شلتم تنزعتم في امر عصيتم من بعد م ار م تحب من من يريد دني من من يريد اخر ثم صرف عن ليبتلي لقد عف عن له ذو فضل عل مومن', 'quran', NULL, NULL, 'https://quran.com/3/152');
INSERT INTO units_tri_src (id, ar_tri) VALUES (445, 'ولق لقد صدق دقك قكم الل لله وعد عده اذ تحس حسو سون ونه نهم بذن ذنه حتي اذ فشل شلت لتم وتن تنز نزع زعت عتم في الم لمر وعص عصي صيت يتم من بعد م ارك ركم م تحب حبو بون منك نكم من يري ريد الد لدن دني ومن منك نكم من يري ريد الخ لخر خره ثم صرف رفك فكم عنه نهم ليب يبت بتل تلي ليك يكم ولق لقد عف عنك نكم ولل لله ذو فضل علي الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (446, 'quran:3:153', 'quran', 'quran', '3:153', 153, 445, 'Ali ''Imran', 'آل عمران', 'إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ', NULL, NULL, 'اذ تصعدون ولا تلون علي احد والرسول يدعوكم في اخراكم فاثبكم غما بغم لكيلا تحزنوا علي ما فاتكم ولا ما اصبكم والله خبير بما تعملون', 'اذ تصعد ول تل عل احد رسول يدعو في اخر اثب غم بغم لكيل تحزن عل م ات ول م اصب له خبير بم تعمل', 'quran', NULL, NULL, 'https://quran.com/3/153');
INSERT INTO units_tri_src (id, ar_tri) VALUES (446, 'اذ تصع صعد عدو دون ول تلو لون علي احد ولر لرس رسو سول يدع دعو عوك وكم في اخر خرك ركم فثب ثبك بكم غم بغم لكي كيل تحز حزن زنو علي م فتك تكم ول م اصب صبك بكم ولل لله خبي بير بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (447, 'quran:3:154', 'quran', 'quran', '3:154', 154, 446, 'Ali ''Imran', 'آل عمران', 'ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'ثم انزل عليكم من بعد الغم امنه نعاسا يغشي طايفه منكم وطايفه قد اهمتهم انفسهم يظنون بالله غير الحق ظن الجهليه يقولون هل لنا من الامر من شيء قل ان الامر كله لله يخفون في انفسهم ما لا يبدون لك يقولون لو كان لنا من الامر شيء ما قتلنا ههنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل الي مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور', 'ثم انزل علي من بعد غم امن نعس يغش طيف من طيف قد اهمت انفس يظن له غير حق ظن جهل يقول هل لن من امر من شيء قل ان امر كل لل يخف في انفس م ل يبد لك يقول لو كن لن من امر شيء م قتل هه قل لو كنتم في بيوت لبرز ذين كتب علي قتل ال مضجع ليبتل له م في صدور ليمحص م في قلوب له عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/3/154');
INSERT INTO units_tri_src (id, ar_tri) VALUES (447, 'ثم انز نزل علي ليك يكم من بعد الغ لغم امن منه نعس يغش غشي طيف يفه منك نكم وطي طيف يفه قد اهم همت مته تهم انف نفس فسه سهم يظن ظنو نون بلل لله غير الح لحق ظن الج لجه جهل هلي ليه يقو قول ولو لون هل لن من الم لمر من شيء قل ان الم لمر كله لله يخف خفو فون في انف نفس فسه سهم م ل يبد بدو دون لك يقو قول ولو لون لو كن لن من الم لمر شيء م قتل تلن ههن قل لو كنت نتم في بيو يوت وتك تكم لبر برز الذ لذي ذين كتب علي ليه يهم الق لقت قتل الي مضج ضجع جعه عهم ولي ليب يبت بتل تلي الل لله م في صدو دور ورك ركم ولي ليم يمح محص م في قلو لوب وبك بكم ولل لله علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (448, 'quran:3:155', 'quran', 'quran', '3:155', 155, 447, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ', NULL, NULL, 'ان الذين تولوا منكم يوم التقي الجمعان انما استزلهم الشيطن ببعض ما كسبوا ولقد عفا الله عنهم ان الله غفور حليم', 'ان ذين تول من يوم تق جمع انم استزل شيطن ببعض م كسب لقد عف له عن ان له غفور حليم', 'quran', NULL, NULL, 'https://quran.com/3/155');
INSERT INTO units_tri_src (id, ar_tri) VALUES (448, 'ان الذ لذي ذين تول ولو منك نكم يوم الت لتق تقي الج لجم جمع معن انم است ستز تزل زله لهم الش لشي شيط يطن ببع بعض م كسب سبو ولق لقد عف الل لله عنه نهم ان الل لله غفو فور حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (449, 'quran:3:156', 'quran', 'quran', '3:156', 156, 448, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ', NULL, NULL, 'يا ايها الذين امنوا لا تكونوا كالذين كفروا وقالوا لاخونهم اذا ضربوا في الارض او كانوا غزي لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسره في قلوبهم والله يحي ويميت والله بما تعملون بصير', 'ي اي ذين امن ل تكون ذين كفر قل لخون اذ ضرب في ارض او كن غز لو كن عند م مت وم قتل ليجعل له ذلك حسر في قلوب له يح يميت له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/3/156');
INSERT INTO units_tri_src (id, ar_tri) VALUES (449, 'ي ايه الذ لذي ذين امن منو ل تكو كون ونو كلذ لذي ذين كفر فرو وقل قلو لخو خون ونه نهم اذ ضرب ربو في الر لرض او كنو غزي لو كنو عند ندن م متو وم قتل تلو ليج يجع جعل الل لله ذلك حسر سره في قلو لوب وبه بهم ولل لله يحي ويم يمي ميت ولل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (450, 'quran:3:157', 'quran', 'quran', '3:157', 157, 449, 'Ali ''Imran', 'آل عمران', 'وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ', NULL, NULL, 'ولين قتلتم في سبيل الله او متم لمغفره من الله ورحمه خير مما يجمعون', 'لين قتلتم في سبيل له او متم لمغفر من له رحم خير مم يجمع', 'quran', NULL, NULL, 'https://quran.com/3/157');
INSERT INTO units_tri_src (id, ar_tri) VALUES (450, 'ولي لين قتل تلت لتم في سبي بيل الل لله او متم لمغ مغف غفر فره من الل لله ورح رحم حمه خير مم يجم جمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (451, 'quran:3:158', 'quran', 'quran', '3:158', 158, 450, 'Ali ''Imran', 'آل عمران', 'وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ', NULL, NULL, 'ولين متم او قتلتم لالي الله تحشرون', 'لين متم او قتلتم لل له تحشر', 'quran', NULL, NULL, 'https://quran.com/3/158');
INSERT INTO units_tri_src (id, ar_tri) VALUES (451, 'ولي لين متم او قتل تلت لتم للي الل لله تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (452, 'quran:3:159', 'quran', 'quran', '3:159', 159, 451, 'Ali ''Imran', 'آل عمران', 'فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ', NULL, NULL, 'فبما رحمه من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الامر فاذا عزمت فتوكل علي الله ان الله يحب المتوكلين', 'بم رحم من له لنت لهم ولو كنت فظ غليظ قلب لنفض من حولك اعف عن استغفر لهم شور في امر اذ عزمت توكل عل له ان له يحب متوكل', 'quran', NULL, NULL, 'https://quran.com/3/159');
INSERT INTO units_tri_src (id, ar_tri) VALUES (452, 'فبم رحم حمه من الل لله لنت لهم ولو كنت فظ غلي ليظ الق لقل قلب لنف نفض فضو من حول ولك فعف عنه نهم وست ستغ تغف غفر لهم وشو شور وره رهم في الم لمر فذ عزم زمت فتو توك وكل علي الل لله ان الل لله يحب الم لمت متو توك وكل كلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (453, 'quran:3:160', 'quran', 'quran', '3:160', 160, 452, 'Ali ''Imran', 'آل عمران', 'إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', NULL, NULL, 'ان ينصركم الله فلا غالب لكم وان يخذلكم فمن ذا الذي ينصركم من بعده وعلي الله فليتوكل المومنون', 'ان ينصر له فل غلب لكم ون يخذل فمن ذ ذي ينصر من بعد عل له ليتوكل مومن', 'quran', NULL, NULL, 'https://quran.com/3/160');
INSERT INTO units_tri_src (id, ar_tri) VALUES (453, 'ان ينص نصر صرك ركم الل لله فل غلب لكم ون يخذ خذل ذلك لكم فمن ذ الذ لذي ينص نصر صرك ركم من بعد عده وعل علي الل لله فلي ليت يتو توك وكل الم لمو موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (454, 'quran:3:161', 'quran', 'quran', '3:161', 161, 453, 'Ali ''Imran', 'آل عمران', 'وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'وما كان لنبي ان يغل ومن يغلل يات بما غل يوم القيمه ثم توفي كل نفس ما كسبت وهم لا يظلمون', 'وم كن لنب ان يغل ومن يغلل يت بم غل يوم قيم ثم توف كل نفس م كسبت وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/3/161');
INSERT INTO units_tri_src (id, ar_tri) VALUES (454, 'وم كن لنب نبي ان يغل ومن يغل غلل يت بم غل يوم الق لقي قيم يمه ثم توف وفي كل نفس م كسب سبت وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (455, 'quran:3:162', 'quran', 'quran', '3:162', 162, 454, 'Ali ''Imran', 'آل عمران', 'أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ', NULL, NULL, 'افمن اتبع رضون الله كمن باء بسخط من الله وماواه جهنم وبيس المصير', 'افمن اتبع رض له كمن بء بسخط من له مو جهنم بيس مصير', 'quran', NULL, NULL, 'https://quran.com/3/162');
INSERT INTO units_tri_src (id, ar_tri) VALUES (455, 'افم فمن اتب تبع رضو ضون الل لله كمن بء بسخ سخط من الل لله ومو موه جهن هنم وبي بيس الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (456, 'quran:3:163', 'quran', 'quran', '3:163', 163, 455, 'Ali ''Imran', 'آل عمران', 'هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', NULL, NULL, 'هم درجت عند الله والله بصير بما يعملون', 'هم درجت عند له له بصير بم يعمل', 'quran', NULL, NULL, 'https://quran.com/3/163');
INSERT INTO units_tri_src (id, ar_tri) VALUES (456, 'هم درج رجت عند الل لله ولل لله بصي صير بم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (457, 'quran:3:164', 'quran', 'quran', '3:164', 164, 456, 'Ali ''Imran', 'آل عمران', 'لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ', NULL, NULL, 'لقد من الله علي المومنين اذ بعث فيهم رسولا من انفسهم يتلوا عليهم ايته ويزكيهم ويعلمهم الكتب والحكمه وان كانوا من قبل لفي ضلل مبين', 'لقد من له عل مومن اذ بعث يهم رسول من انفس يتل علي ايت يزكي يعلم كتب حكم ون كن من قبل لف ضلل مب', 'quran', NULL, NULL, 'https://quran.com/3/164');
INSERT INTO units_tri_src (id, ar_tri) VALUES (457, 'لقد من الل لله علي الم لمو موم ومن مني نين اذ بعث فيه يهم رسو سول من انف نفس فسه سهم يتل تلو علي ليه يهم ايت يته ويز يزك زكي كيه يهم ويع يعل علم لمه مهم الك لكت كتب ولح لحك حكم كمه ون كنو من قبل لفي ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (458, 'quran:3:165', 'quran', 'quran', '3:165', 165, 457, 'Ali ''Imran', 'آل عمران', 'أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'اولما اصبتكم مصيبه قد اصبتم مثليها قلتم اني هذا قل هو من عند انفسكم ان الله علي كل شيء قدير', 'اولم اصبت مصيب قد اصبتم مثلي قلتم ان هذ قل هو من عند انفس ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/3/165');
INSERT INTO units_tri_src (id, ar_tri) VALUES (458, 'اول ولم اصب صبت بتك تكم مصي صيب يبه قد اصب صبت بتم مثل ثلي ليه قلت لتم اني هذ قل هو من عند انف نفس فسك سكم ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (459, 'quran:3:166', 'quran', 'quran', '3:166', 166, 458, 'Ali ''Imran', 'آل عمران', 'وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'وما اصبكم يوم التقي الجمعان فباذن الله وليعلم المومنين', 'وم اصب يوم تق جمع بذن له ليعلم مومن', 'quran', NULL, NULL, 'https://quran.com/3/166');
INSERT INTO units_tri_src (id, ar_tri) VALUES (459, 'وم اصب صبك بكم يوم الت لتق تقي الج لجم جمع معن فبذ بذن الل لله ولي ليع يعل علم الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (460, 'quran:3:167', 'quran', 'quran', '3:167', 167, 459, 'Ali ''Imran', 'آل عمران', 'وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ', NULL, NULL, 'وليعلم الذين نافقوا وقيل لهم تعالوا قتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالا لاتبعنكم هم للكفر يوميذ اقرب منهم للايمن يقولون بافوههم ما ليس في قلوبهم والله اعلم بما يكتمون', 'ليعلم ذين نفق قيل لهم تعل قتل في سبيل له او ادفع قل لو نعلم قتل لتبعن هم كفر يوميذ اقرب من ايمن يقول بفوه م ليس في قلوب له اعلم بم يكتم', 'quran', NULL, NULL, 'https://quran.com/3/167');
INSERT INTO units_tri_src (id, ar_tri) VALUES (460, 'ولي ليع يعل علم الذ لذي ذين نفق فقو وقي قيل لهم تعل علو قتل تلو في سبي بيل الل لله او ادف دفع فعو قلو لو نعل علم قتل لتب تبع بعن عنك نكم هم للك لكف كفر يوم ومي ميذ اقر قرب منه نهم للي ليم يمن يقو قول ولو لون بفو فوه وهه ههم م ليس في قلو لوب وبه بهم ولل لله اعل علم بم يكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (461, 'quran:3:168', 'quran', 'quran', '3:168', 168, 460, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'الذين قالوا لاخونهم وقعدوا لو اطاعونا ما قتلوا قل فادرءوا عن انفسكم الموت ان كنتم صدقين', 'ذين قل لخون قعد لو اطعو م قتل قل ادرء عن انفس موت ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/3/168');
INSERT INTO units_tri_src (id, ar_tri) VALUES (461, 'الذ لذي ذين قلو لخو خون ونه نهم وقع قعد عدو لو اطع طعو عون م قتل تلو قل فدر درء رءو عن انف نفس فسك سكم الم لمو موت ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (462, 'quran:3:169', 'quran', 'quran', '3:169', 169, 461, 'Ali ''Imran', 'آل عمران', 'وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ', NULL, NULL, 'ولا تحسبن الذين قتلوا في سبيل الله اموتا بل احياء عند ربهم يرزقون', 'ول تحسبن ذين قتل في سبيل له اموت بل احيء عند رب يرزق', 'quran', NULL, NULL, 'https://quran.com/3/169');
INSERT INTO units_tri_src (id, ar_tri) VALUES (462, 'ول تحس حسب سبن الذ لذي ذين قتل تلو في سبي بيل الل لله امو موت بل احي حيء عند ربه بهم يرز رزق زقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (463, 'quran:3:170', 'quran', 'quran', '3:170', 170, 462, 'Ali ''Imran', 'آل عمران', 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'فرحين بما اتاهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم الا خوف عليهم ولا هم يحزنون', 'رح بم ات له من ضل يستبشر ذين لم يلحق بهم من خلف ال خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/3/170');
INSERT INTO units_tri_src (id, ar_tri) VALUES (463, 'فرح رحي حين بم اته تهم الل لله من فضل ضله ويس يست ستب تبش بشر شرو رون بلذ لذي ذين لم يلح لحق حقو بهم من خلف لفه فهم ال خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (464, 'quran:3:171', 'quran', 'quran', '3:171', 171, 463, 'Ali ''Imran', 'آل عمران', 'يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'يستبشرون بنعمه من الله وفضل وان الله لا يضيع اجر المومنين', 'يستبشر بنعم من له فضل ون له ل يضيع اجر مومن', 'quran', NULL, NULL, 'https://quran.com/3/171');
INSERT INTO units_tri_src (id, ar_tri) VALUES (464, 'يست ستب تبش بشر شرو رون بنع نعم عمه من الل لله وفض فضل ون الل لله ل يضي ضيع اجر الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (465, 'quran:3:172', 'quran', 'quran', '3:172', 172, 464, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ', NULL, NULL, 'الذين استجابوا لله والرسول من بعد ما اصابهم القرح للذين احسنوا منهم واتقوا اجر عظيم', 'ذين استجب لل رسول من بعد م اصب قرح ذين احسن من اتق اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/3/172');
INSERT INTO units_tri_src (id, ar_tri) VALUES (465, 'الذ لذي ذين است ستج تجب جبو لله ولر لرس رسو سول من بعد م اصب صبه بهم الق لقر قرح للذ لذي ذين احس حسن سنو منه نهم وتق تقو اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (466, 'quran:3:173', 'quran', 'quran', '3:173', 173, 465, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ', NULL, NULL, 'الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمنا وقالوا حسبنا الله ونعم الوكيل', 'ذين قل لهم نس ان نس قد جمع لكم اخشو زد ايم قل حسب له نعم وكيل', 'quran', NULL, NULL, 'https://quran.com/3/173');
INSERT INTO units_tri_src (id, ar_tri) VALUES (466, 'الذ لذي ذين قل لهم الن لنس ان الن لنس قد جمع معو لكم فخش خشو شوه وهم فزد زده دهم ايم يمن وقل قلو حسب سبن الل لله ونع نعم الو لوك وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (467, 'quran:3:174', 'quran', 'quran', '3:174', 174, 466, 'Ali ''Imran', 'آل عمران', 'فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ', NULL, NULL, 'فانقلبوا بنعمه من الله وفضل لم يمسسهم سوء واتبعوا رضون الله والله ذو فضل عظيم', 'انقلب بنعم من له فضل لم يمسس سوء اتبع رض له له ذو فضل عظيم', 'quran', NULL, NULL, 'https://quran.com/3/174');
INSERT INTO units_tri_src (id, ar_tri) VALUES (467, 'فنق نقل قلب لبو بنع نعم عمه من الل لله وفض فضل لم يمس مسس سسه سهم سوء وتب تبع بعو رضو ضون الل لله ولل لله ذو فضل عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (468, 'quran:3:175', 'quran', 'quran', '3:175', 175, 467, 'Ali ''Imran', 'آل عمران', 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'انما ذلكم الشيطن يخوف اولياءه فلا تخافوهم وخافون ان كنتم مومنين', 'انم ذل شيطن يخوف اوليء فل تخفو خف ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/3/175');
INSERT INTO units_tri_src (id, ar_tri) VALUES (468, 'انم ذلك لكم الش لشي شيط يطن يخو خوف اول ولي ليء يءه فل تخف خفو فوه وهم وخف خفو فون ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (469, 'quran:3:176', 'quran', 'quran', '3:176', 176, 468, 'Ali ''Imran', 'آل عمران', 'وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ', NULL, NULL, 'ولا يحزنك الذين يسرعون في الكفر انهم لن يضروا الله شيا يريد الله الا يجعل لهم حظا في الاخره ولهم عذاب عظيم', 'ول يحزنك ذين يسرع في كفر ان لن يضر له شي يريد له ال يجعل لهم حظ في اخر لهم عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/3/176');
INSERT INTO units_tri_src (id, ar_tri) VALUES (469, 'ول يحز حزن زنك الذ لذي ذين يسر سرع رعو عون في الك لكف كفر انه نهم لن يضر ضرو الل لله شي يري ريد الل لله ال يجع جعل لهم حظ في الخ لخر خره وله لهم عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (470, 'quran:3:177', 'quran', 'quran', '3:177', 177, 469, 'Ali ''Imran', 'آل عمران', 'إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'ان الذين اشتروا الكفر بالايمن لن يضروا الله شيا ولهم عذاب اليم', 'ان ذين اشتر كفر ايمن لن يضر له شي لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/3/177');
INSERT INTO units_tri_src (id, ar_tri) VALUES (470, 'ان الذ لذي ذين اشت شتر ترو الك لكف كفر بلي ليم يمن لن يضر ضرو الل لله شي وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (471, 'quran:3:178', 'quran', 'quran', '3:178', 178, 470, 'Ali ''Imran', 'آل عمران', 'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ', NULL, NULL, 'ولا يحسبن الذين كفروا انما نملي لهم خير لانفسهم انما نملي لهم ليزدادوا اثما ولهم عذاب مهين', 'ول يحسبن ذين كفر انم نمل لهم خير لنفس انم نمل لهم ليزدد اثم لهم عذب مه', 'quran', NULL, NULL, 'https://quran.com/3/178');
INSERT INTO units_tri_src (id, ar_tri) VALUES (471, 'ول يحس حسب سبن الذ لذي ذين كفر فرو انم نمل ملي لهم خير لنف نفس فسه سهم انم نمل ملي لهم ليز يزد زدد ددو اثم وله لهم عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (472, 'quran:3:179', 'quran', 'quran', '3:179', 179, 471, 'Ali ''Imran', 'آل عمران', 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ', NULL, NULL, 'ما كان الله ليذر المومنين علي ما انتم عليه حتي يميز الخبيث من الطيب وما كان الله ليطلعكم علي الغيب ولكن الله يجتبي من رسله من يشاء فامنوا بالله ورسله وان تومنوا وتتقوا فلكم اجر عظيم', 'م كن له ليذر مومن عل م انتم عل حت يميز خبيث من طيب وم كن له ليطلع عل غيب لكن له يجتب من رسل من يشء امن له رسل ون تومن تتق لكم اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/3/179');
INSERT INTO units_tri_src (id, ar_tri) VALUES (472, 'م كن الل لله ليذ يذر الم لمو موم ومن مني نين علي م انت نتم علي ليه حتي يمي ميز الخ لخب خبي بيث من الط لطي طيب وم كن الل لله ليط يطل طلع لعك عكم علي الغ لغي غيب ولك لكن الل لله يجت جتب تبي من رسل سله من يشء فمن منو بلل لله ورس رسل سله ون توم ومن منو وتت تتق تقو فلك لكم اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (473, 'quran:3:180', 'quran', 'quran', '3:180', 180, 472, 'Ali ''Imran', 'آل عمران', 'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'ولا يحسبن الذين يبخلون بما اتاهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيمه ولله ميرث السموت والارض والله بما تعملون خبير', 'ول يحسبن ذين يبخل بم ات له من ضل هو خير لهم بل هو شر لهم سيطوق م بخل به يوم قيم لل ميرث سموت ارض له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/3/180');
INSERT INTO units_tri_src (id, ar_tri) VALUES (473, 'ول يحس حسب سبن الذ لذي ذين يبخ بخل خلو لون بم اته تهم الل لله من فضل ضله هو خير لهم بل هو شر لهم سيط يطو طوق وقو قون م بخل خلو به يوم الق لقي قيم يمه ولل لله مير يرث الس لسم سمو موت ولر لرض ولل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (474, 'quran:3:181', 'quran', 'quran', '3:181', 181, 473, 'Ali ''Imran', 'آل عمران', 'لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ', NULL, NULL, 'لقد سمع الله قول الذين قالوا ان الله فقير ونحن اغنياء سنكتب ما قالوا وقتلهم الانبياء بغير حق ونقول ذوقوا عذاب الحريق', 'لقد سمع له قول ذين قل ان له قير نحن اغنيء سنكتب م قل قتل انبيء بغير حق نقول ذوق عذب حريق', 'quran', NULL, NULL, 'https://quran.com/3/181');
INSERT INTO units_tri_src (id, ar_tri) VALUES (474, 'لقد سمع الل لله قول الذ لذي ذين قلو ان الل لله فقي قير ونح نحن اغن غني نيء سنك نكت كتب م قلو وقت قتل تله لهم الن لنب نبي بيء بغي غير حق ونق نقو قول ذوق وقو عذب الح لحر حري ريق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (475, 'quran:3:182', 'quran', 'quran', '3:182', 182, 474, 'Ali ''Imran', 'آل عمران', 'ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ', NULL, NULL, 'ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد', 'ذلك بم قدمت ايدي ون له ليس بظلم عبيد', 'quran', NULL, NULL, 'https://quran.com/3/182');
INSERT INTO units_tri_src (id, ar_tri) VALUES (475, 'ذلك بم قدم دمت ايد يدي ديك يكم ون الل لله ليس بظل ظلم للع لعب عبي بيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (476, 'quran:3:183', 'quran', 'quran', '3:183', 183, 475, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'الذين قالوا ان الله عهد الينا الا نومن لرسول حتي ياتينا بقربان تاكله النار قل قد جاءكم رسل من قبلي بالبينت وبالذي قلتم فلم قتلتموهم ان كنتم صدقين', 'ذين قل ان له عهد ين ال نومن لرسول حت يتي بقرب تكل نر قل قد جء رسل من قبل بينت ذي قلتم فلم قتلتمو ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/3/183');
INSERT INTO units_tri_src (id, ar_tri) VALUES (476, 'الذ لذي ذين قلو ان الل لله عهد الي لين ال نوم ومن لرس رسو سول حتي يتي تين بقر قرب ربن تكل كله الن لنر قل قد جءك ءكم رسل من قبل بلي بلب لبي بين ينت وبل بلذ لذي قلت لتم فلم قتل تلت لتم تمو موه وهم ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (477, 'quran:3:184', 'quran', 'quran', '3:184', 184, 476, 'Ali ''Imran', 'آل عمران', 'فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ', NULL, NULL, 'فان كذبوك فقد كذب رسل من قبلك جاءو بالبينت والزبر والكتب المنير', 'فن كذبوك فقد كذب رسل من قبلك جءو بينت زبر كتب منير', 'quran', NULL, NULL, 'https://quran.com/3/184');
INSERT INTO units_tri_src (id, ar_tri) VALUES (477, 'فن كذب ذبو بوك فقد كذب رسل من قبل بلك جءو بلب لبي بين ينت ولز لزب زبر ولك لكت كتب الم لمن مني نير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (478, 'quran:3:185', 'quran', 'quran', '3:185', 185, 477, 'Ali ''Imran', 'آل عمران', 'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ', NULL, NULL, 'كل نفس ذايقه الموت وانما توفون اجوركم يوم القيمه فمن زحزح عن النار وادخل الجنه فقد فاز وما الحياه الدنيا الا متع الغرور', 'كل نفس ذيق موت انم توف اجور يوم قيم فمن زحزح عن نر ادخل جن فقد فز وم حي دني ال متع غرور', 'quran', NULL, NULL, 'https://quran.com/3/185');
INSERT INTO units_tri_src (id, ar_tri) VALUES (478, 'كل نفس ذيق يقه الم لمو موت ونم توف وفو فون اجو جور ورك ركم يوم الق لقي قيم يمه فمن زحز حزح عن الن لنر ودخ دخل الج لجن جنه فقد فز وم الح لحي حيه الد لدن دني ال متع الغ لغر غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (479, 'quran:3:186', 'quran', 'quran', '3:186', 186, 478, 'Ali ''Imran', 'آل عمران', 'لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ', NULL, NULL, 'لتبلون في امولكم وانفسكم ولتسمعن من الذين اوتوا الكتب من قبلكم ومن الذين اشركوا اذي كثيرا وان تصبروا وتتقوا فان ذلك من عزم الامور', 'لتبل في امول انفس لتسمعن من ذين اوت كتب من قبل ومن ذين اشرك اذ كثير ون تصبر تتق فن ذلك من عزم امور', 'quran', NULL, NULL, 'https://quran.com/3/186');
INSERT INTO units_tri_src (id, ar_tri) VALUES (479, 'لتب تبل بلو لون في امو مول ولك لكم ونف نفس فسك سكم ولت لتس تسم سمع معن من الذ لذي ذين اوت وتو الك لكت كتب من قبل بلك لكم ومن الذ لذي ذين اشر شرك ركو اذي كثي ثير ون تصب صبر برو وتت تتق تقو فن ذلك من عزم الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (480, 'quran:3:187', 'quran', 'quran', '3:187', 187, 479, 'Ali ''Imran', 'آل عمران', 'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ', NULL, NULL, 'واذ اخذ الله ميثق الذين اوتوا الكتب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبيس ما يشترون', 'وذ اخذ له ميثق ذين اوت كتب لتبينن نس ول تكتمون نبذو رء ظهور اشتر به ثم قليل بيس م يشتر', 'quran', NULL, NULL, 'https://quran.com/3/187');
INSERT INTO units_tri_src (id, ar_tri) VALUES (480, 'وذ اخذ الل لله ميث يثق الذ لذي ذين اوت وتو الك لكت كتب لتب تبي بين ينن ننه للن لنس ول تكت كتم تمو مون ونه فنب نبذ بذو ذوه ورء ظهو هور وره رهم وشت شتر ترو به ثمن قلي ليل فبي بيس م يشت شتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (481, 'quran:3:188', 'quran', 'quran', '3:188', 188, 480, 'Ali ''Imran', 'آل عمران', 'لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'لا تحسبن الذين يفرحون بما اتوا ويحبون ان يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازه من العذاب ولهم عذاب اليم', 'ل تحسبن ذين يفرح بم ات يحب ان يحمد بم لم يفعل فل تحسبن بمفز من عذب لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/3/188');
INSERT INTO units_tri_src (id, ar_tri) VALUES (481, 'ل تحس حسب سبن الذ لذي ذين يفر فرح رحو حون بم اتو ويح يحب حبو بون ان يحم حمد مدو بم لم يفع فعل علو فل تحس حسب سبن بنه نهم بمف مفز فزه من الع لعذ عذب وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (482, 'quran:3:189', 'quran', 'quran', '3:189', 189, 481, 'Ali ''Imran', 'آل عمران', 'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', NULL, NULL, 'ولله ملك السموت والارض والله علي كل شيء قدير', 'لل ملك سموت ارض له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/3/189');
INSERT INTO units_tri_src (id, ar_tri) VALUES (482, 'ولل لله ملك الس لسم سمو موت ولر لرض ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (483, 'quran:3:190', 'quran', 'quran', '3:190', 190, 482, 'Ali ''Imran', 'آل عمران', 'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ', NULL, NULL, 'ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب', 'ان في خلق سموت ارض اختلف يل نهر ليت لول البب', 'quran', NULL, NULL, 'https://quran.com/3/190');
INSERT INTO units_tri_src (id, ar_tri) VALUES (483, 'ان في خلق الس لسم سمو موت ولر لرض وخت ختل تلف الي ليل ولن لنه نهر ليت لول ولي الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (484, 'quran:3:191', 'quran', 'quran', '3:191', 191, 483, 'Ali ''Imran', 'آل عمران', 'ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', NULL, NULL, 'الذين يذكرون الله قيما وقعودا وعلي جنوبهم ويتفكرون في خلق السموت والارض ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار', 'ذين يذكر له قيم قعود عل جنوب يتفكر في خلق سموت ارض رب م خلقت هذ بطل سبحنك قن عذب نر', 'quran', NULL, NULL, 'https://quran.com/3/191');
INSERT INTO units_tri_src (id, ar_tri) VALUES (484, 'الذ لذي ذين يذك ذكر كرو رون الل لله قيم وقع قعو عود وعل علي جنو نوب وبه بهم ويت يتف تفك فكر كرو رون في خلق الس لسم سمو موت ولر لرض ربن م خلق لقت هذ بطل سبح بحن حنك فقن عذب الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (485, 'quran:3:192', 'quran', 'quran', '3:192', 192, 484, 'Ali ''Imran', 'آل عمران', 'رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ', NULL, NULL, 'ربنا انك من تدخل النار فقد اخزيته وما للظلمين من انصار', 'رب انك من تدخل نر فقد اخزيت وم ظلم من انصر', 'quran', NULL, NULL, 'https://quran.com/3/192');
INSERT INTO units_tri_src (id, ar_tri) VALUES (485, 'ربن انك من تدخ دخل الن لنر فقد اخز خزي زيت يته وم للظ لظل ظلم لمي مين من انص نصر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (486, 'quran:3:193', 'quran', 'quran', '3:193', 193, 485, 'Ali ''Imran', 'آل عمران', 'رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ', NULL, NULL, 'ربنا اننا سمعنا مناديا ينادي للايمن ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سياتنا وتوفنا مع الابرار', 'رب ان سمع مندي يند ايمن ان امن برب ام رب اغفر لن ذنوب كفر عن سيت توف مع ابرر', 'quran', NULL, NULL, 'https://quran.com/3/193');
INSERT INTO units_tri_src (id, ar_tri) VALUES (486, 'ربن انن سمع معن مند ندي يند ندي للي ليم يمن ان امن منو برب ربك بكم فمن ربن فغف غفر لن ذنو نوب وبن وكف كفر عن سيت يتن وتو توف وفن مع الب لبر برر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (487, 'quran:3:194', 'quran', 'quran', '3:194', 194, 486, 'Ali ''Imran', 'آل عمران', 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ', NULL, NULL, 'ربنا واتنا ما وعدتنا علي رسلك ولا تخزنا يوم القيمه انك لا تخلف الميعاد', 'رب ات م عدت عل رسلك ول تخز يوم قيم انك ل تخلف ميعد', 'quran', NULL, NULL, 'https://quran.com/3/194');
INSERT INTO units_tri_src (id, ar_tri) VALUES (487, 'ربن وتن م وعد عدت دتن علي رسل سلك ول تخز خزن يوم الق لقي قيم يمه انك ل تخل خلف الم لمي ميع يعد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (488, 'quran:3:195', 'quran', 'quran', '3:195', 195, 487, 'Ali ''Imran', 'آل عمران', 'فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ', NULL, NULL, 'فاستجاب لهم ربهم اني لا اضيع عمل عمل منكم من ذكر او انثي بعضكم من بعض فالذين هاجروا واخرجوا من ديرهم واوذوا في سبيلي وقتلوا وقتلوا لاكفرن عنهم سياتهم ولادخلنهم جنت تجري من تحتها الانهر ثوابا من عند الله والله عنده حسن الثواب', 'استجب لهم رب ان ل اضيع عمل عمل من من ذكر او انث بعض من بعض ذين هجر اخرج من دير اوذ في سبيل قتل قتل لكفرن عن سيت لدخلن جنت تجر من تحت انهر ثوب من عند له له عند حسن ثوب', 'quran', NULL, NULL, 'https://quran.com/3/195');
INSERT INTO units_tri_src (id, ar_tri) VALUES (488, 'فست ستج تجب لهم ربه بهم اني ل اضي ضيع عمل عمل منك نكم من ذكر او انث نثي بعض عضك ضكم من بعض فلذ لذي ذين هجر جرو وخر خرج رجو من دير يره رهم ووذ وذو في سبي بيل يلي وقت قتل تلو وقت قتل تلو لكف كفر فرن عنه نهم سيت يته تهم ولد لدخ دخل خلن لنه نهم جنت تجر جري من تحت حته الن لنه نهر ثوب من عند الل لله ولل لله عند نده حسن الث لثو ثوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (489, 'quran:3:196', 'quran', 'quran', '3:196', 196, 488, 'Ali ''Imran', 'آل عمران', 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ', NULL, NULL, 'لا يغرنك تقلب الذين كفروا في البلد', 'ل يغرنك تقلب ذين كفر في بلد', 'quran', NULL, NULL, 'https://quran.com/3/196');
INSERT INTO units_tri_src (id, ar_tri) VALUES (489, 'ل يغر غرن رنك تقل قلب الذ لذي ذين كفر فرو في الب لبل بلد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (490, 'quran:3:197', 'quran', 'quran', '3:197', 197, 489, 'Ali ''Imran', 'آل عمران', 'مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ', NULL, NULL, 'متع قليل ثم ماواهم جهنم وبيس المهاد', 'متع قليل ثم مو جهنم بيس مهد', 'quran', NULL, NULL, 'https://quran.com/3/197');
INSERT INTO units_tri_src (id, ar_tri) VALUES (490, 'متع قلي ليل ثم موه وهم جهن هنم وبي بيس الم لمه مهد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (491, 'quran:3:198', 'quran', 'quran', '3:198', 198, 490, 'Ali ''Imran', 'آل عمران', 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ', NULL, NULL, 'لكن الذين اتقوا ربهم لهم جنت تجري من تحتها الانهر خلدين فيها نزلا من عند الله وما عند الله خير للابرار', 'لكن ذين اتق رب لهم جنت تجر من تحت انهر خلد يه نزل من عند له وم عند له خير ابرر', 'quran', NULL, NULL, 'https://quran.com/3/198');
INSERT INTO units_tri_src (id, ar_tri) VALUES (491, 'لكن الذ لذي ذين اتق تقو ربه بهم لهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه نزل من عند الل لله وم عند الل لله خير للب لبر برر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (492, 'quran:3:199', 'quran', 'quran', '3:199', 199, 491, 'Ali ''Imran', 'آل عمران', 'وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', NULL, NULL, 'وان من اهل الكتب لمن يومن بالله وما انزل اليكم وما انزل اليهم خشعين لله لا يشترون بايت الله ثمنا قليلا اوليك لهم اجرهم عند ربهم ان الله سريع الحساب', 'ون من اهل كتب لمن يومن له وم انزل يكم وم انزل يهم خشع لل ل يشتر بيت له ثم قليل اوليك لهم اجر عند رب ان له سريع حسب', 'quran', NULL, NULL, 'https://quran.com/3/199');
INSERT INTO units_tri_src (id, ar_tri) VALUES (492, 'ون من اهل الك لكت كتب لمن يوم ومن بلل لله وم انز نزل الي ليك يكم وم انز نزل الي ليه يهم خشع شعي عين لله ل يشت شتر ترو رون بيت الل لله ثمن قلي ليل اول ولي ليك لهم اجر جره رهم عند ربه بهم ان الل لله سري ريع الح لحس حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (493, 'quran:3:200', 'quran', 'quran', '3:200', 200, 492, 'Ali ''Imran', 'آل عمران', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يا ايها الذين امنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون', 'ي اي ذين امن اصبر صبر ربط اتق له لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/3/200');
INSERT INTO units_tri_src (id, ar_tri) VALUES (493, 'ي ايه الذ لذي ذين امن منو اصب صبر برو وصب صبر برو ورب ربط بطو وتق تقو الل لله لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (494, 'quran:4:1', 'quran', 'quran', '4:1', 1, 493, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا', NULL, NULL, 'يا ايها الناس اتقوا ربكم الذي خلقكم من نفس وحده وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا', 'ي اي نس اتق رب ذي خلق من نفس حد خلق من زوج وبث منهم رجل كثير نسء اتق له ذي تسءل به ارحم ان له كن علي رقيب', 'quran', NULL, NULL, 'https://quran.com/4/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (494, 'ي ايه الن لنس اتق تقو ربك بكم الذ لذي خلق لقك قكم من نفس وحد حده وخل خلق منه زوج وجه وبث منه نهم رجل كثي ثير ونس نسء وتق تقو الل لله الذ لذي تسء سءل ءلو لون به ولر لرح رحم ان الل لله كن علي ليك يكم رقي قيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (495, 'quran:4:2', 'quran', 'quran', '4:2', 2, 494, 'An-Nisa', 'النساء', 'وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا', NULL, NULL, 'واتوا اليتمي امولهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا امولهم الي امولكم انه كان حوبا كبيرا', 'ات يتم امول ول تتبدل خبيث طيب ول تكل امول ال امول ان كن حوب كبير', 'quran', NULL, NULL, 'https://quran.com/4/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (495, 'وتو الي ليت يتم تمي امو مول وله لهم ول تتب تبد بدل دلو الخ لخب خبي بيث بلط لطي طيب ول تكل كلو امو مول وله لهم الي امو مول ولك لكم انه كن حوب كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (496, 'quran:4:3', 'quran', 'quran', '4:3', 3, 495, 'An-Nisa', 'النساء', 'وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ', NULL, NULL, 'وان خفتم الا تقسطوا في اليتمي فانكحوا ما طاب لكم من النساء مثني وثلث وربع فان خفتم الا تعدلوا فوحده او ما ملكت ايمنكم ذلك ادني الا تعولوا', 'ون خفتم ال تقسط في يتم انكح م طب لكم من نسء مثن ثلث ربع فن خفتم ال تعدل وحد او م ملكت ايمن ذلك ادن ال تعول', 'quran', NULL, NULL, 'https://quran.com/4/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (496, 'ون خفت فتم ال تقس قسط سطو في الي ليت يتم تمي فنك نكح كحو م طب لكم من الن لنس نسء مثن ثني وثل ثلث ورب ربع فن خفت فتم ال تعد عدل دلو فوح وحد حده او م ملك لكت ايم يمن منك نكم ذلك ادن دني ال تعو عول ولو');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (497, 'quran:4:4', 'quran', 'quran', '4:4', 4, 496, 'An-Nisa', 'النساء', 'وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا', NULL, NULL, 'واتوا النساء صدقتهن نحله فان طبن لكم عن شيء منه نفسا فكلوه هنيا مريا', 'ات نسء صدقت نحل فن طبن لكم عن شيء من نفس كلو هني مري', 'quran', NULL, NULL, 'https://quran.com/4/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (497, 'وتو الن لنس نسء صدق دقت قته تهن نحل حله فن طبن لكم عن شيء منه نفس فكل كلو لوه هني مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (498, 'quran:4:5', 'quran', 'quran', '4:5', 5, 497, 'An-Nisa', 'النساء', 'وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا', NULL, NULL, 'ولا توتوا السفهاء امولكم التي جعل الله لكم قيما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا', 'ول توت سفهء امول تي جعل له لكم قيم ارزقو يه اكسو قول لهم قول معروف', 'quran', NULL, NULL, 'https://quran.com/4/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (498, 'ول توت وتو الس لسف سفه فهء امو مول ولك لكم الت لتي جعل الل لله لكم قيم ورز رزق زقو قوه وهم فيه وكس كسو سوه وهم وقو قول ولو لهم قول معر عرو روف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (499, 'quran:4:6', 'quran', 'quran', '4:6', 6, 498, 'An-Nisa', 'النساء', 'وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا', NULL, NULL, 'وابتلوا اليتمي حتي اذا بلغوا النكاح فان انستم منهم رشدا فادفعوا اليهم امولهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم امولهم فاشهدوا عليهم وكفي بالله حسيبا', 'ابتل يتم حت اذ بلغ نكح فن انستم من رشد ادفع يهم امول ول تكلو اسرف بدر ان يكبر ومن كن غني ليستعفف ومن كن قير ليكل معروف اذ دفعتم يهم امول اشهد علي كف له حسيب', 'quran', NULL, NULL, 'https://quran.com/4/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (499, 'وبت بتل تلو الي ليت يتم تمي حتي اذ بلغ لغو الن لنك نكح فن انس نست ستم منه نهم رشد فدف دفع فعو الي ليه يهم امو مول وله لهم ول تكل كلو لوه اسر سرف وبد بدر ان يكب كبر برو ومن كن غني فلي ليس يست ستع تعف عفف ومن كن فقي قير فلي ليك يكل بلم لمع معر عرو روف فذ دفع فعت عتم الي ليه يهم امو مول وله لهم فشه شهد هدو علي ليه يهم وكف كفي بلل لله حسي سيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (500, 'quran:4:7', 'quran', 'quran', '4:7', 7, 499, 'An-Nisa', 'النساء', 'لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا', NULL, NULL, 'للرجال نصيب مما ترك الولدان والاقربون وللنساء نصيب مما ترك الولدان والاقربون مما قل منه او كثر نصيبا مفروضا', 'رجل نصيب مم ترك ولد اقرب نسء نصيب مم ترك ولد اقرب مم قل من او كثر نصيب مفروض', 'quran', NULL, NULL, 'https://quran.com/4/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (500, 'للر لرج رجل نصي صيب مم ترك الو لول ولد لدن ولق لقر قرب ربو بون ولل للن لنس نسء نصي صيب مم ترك الو لول ولد لدن ولق لقر قرب ربو بون مم قل منه او كثر نصي صيب مفر فرو روض');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (501, 'quran:4:8', 'quran', 'quran', '4:8', 8, 500, 'An-Nisa', 'النساء', 'وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا', NULL, NULL, 'واذا حضر القسمه اولوا القربي واليتمي والمسكين فارزقوهم منه وقولوا لهم قولا معروفا', 'اذ حضر قسم اول قرب يتم مسك ارزقو من قول لهم قول معروف', 'quran', NULL, NULL, 'https://quran.com/4/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (501, 'وذ حضر الق لقس قسم سمه اول ولو الق لقر قرب ربي ولي ليت يتم تمي ولم لمس مسك سكي كين فرز رزق زقو قوه وهم منه وقو قول ولو لهم قول معر عرو روف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (502, 'quran:4:9', 'quran', 'quran', '4:9', 9, 501, 'An-Nisa', 'النساء', 'وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا', NULL, NULL, 'وليخش الذين لو تركوا من خلفهم ذريه ضعفا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا', 'ليخش ذين لو ترك من خلف ذر ضعف خف علي ليتق له ليقول قول سديد', 'quran', NULL, NULL, 'https://quran.com/4/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (502, 'ولي ليخ يخش الذ لذي ذين لو ترك ركو من خلف لفه فهم ذري ريه ضعف خفو علي ليه يهم فلي ليت يتق تقو الل لله ولي ليق يقو قول ولو قول سدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (503, 'quran:4:10', 'quran', 'quran', '4:10', 10, 502, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا', NULL, NULL, 'ان الذين ياكلون امول اليتمي ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا', 'ان ذين يكل امول يتم ظلم انم يكل في بطون نر سيصل سعير', 'quran', NULL, NULL, 'https://quran.com/4/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (503, 'ان الذ لذي ذين يكل كلو لون امو مول الي ليت يتم تمي ظلم انم يكل كلو لون في بطو طون ونه نهم نر وسي سيص يصل صلو لون سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (504, 'quran:4:11', 'quran', 'quran', '4:11', 11, 503, 'An-Nisa', 'النساء', 'يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا', NULL, NULL, 'يوصيكم الله في اولدكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت وحده فلها النصف ولابويه لكل وحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين اباوكم وابناوكم لا تدرون ايهم اقرب لكم نفعا فريضه من الله ان الله كان عليما حكيما', 'يوصي له في اولد ذكر مثل حظ انثي فن كن نسء فوق اثنت لهن ثلث م ترك ون كنت حد له نصف لبو لكل وحد منهم سدس مم ترك ان كن له ولد فن لم يكن له ولد ورث ابو لم ثلث فن كن له اخو لم سدس من بعد صي يوص به او دين ابو ابنو ل تدر اي اقرب لكم نفع ريض من له ان له كن عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (504, 'يوص وصي صيك يكم الل لله في اول ولد لدك دكم للذ لذك ذكر مثل حظ الن لنث نثي ثيي يين فن كن نسء فوق اثن ثنت نتي تين فله لهن ثلث م ترك ون كنت وحد حده فله الن لنص نصف ولب لبو بوي ويه لكل وحد منه نهم الس لسد سدس مم ترك ان كن له ولد فن لم يكن له ولد وور ورث رثه ابو بوه فلم لمه الث لثل ثلث فن كن له اخو خوه فلم لمه الس لسد سدس من بعد وصي صيه يوص وصي به او دين ابو بوك وكم وبن بنو نوك وكم ل تدر درو رون ايه يهم اقر قرب لكم نفع فري ريض يضه من الل لله ان الل لله كن علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (505, 'quran:4:12', 'quran', 'quran', '4:12', 12, 504, 'An-Nisa', 'النساء', 'وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ', NULL, NULL, 'ولكم نصف ما ترك ازوجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصيه يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم', 'لكم نصف م ترك ازوج ان لم يكن لهن ولد فن كن لهن ولد لكم ربع مم تركن من بعد صي يوص به او دين لهن ربع مم تركتم ان لم يكن لكم ولد فن كن لكم ولد لهن ثمن مم تركتم من بعد صي توص به او دين ون كن رجل يورث كلل او امر ول اخ او اخت لكل وحد منهم سدس فن كن اكثر من ذلك فهم شركء في ثلث من بعد صي يوص به او دين غير مضر صي من له له عليم حليم', 'quran', NULL, NULL, 'https://quran.com/4/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (505, 'ولك لكم نصف م ترك ازو زوج وجك جكم ان لم يكن لهن ولد فن كن لهن ولد فلك لكم الر لرب ربع مم ترك ركن من بعد وصي صيه يوص وصي صين به او دين وله لهن الر لرب ربع مم ترك ركت كتم ان لم يكن لكم ولد فن كن لكم ولد فله لهن الث لثم ثمن مم ترك ركت كتم من بعد وصي صيه توص وصو صون به او دين ون كن رجل يور ورث كلل لله او امر مره وله اخ او اخت فلك لكل وحد منه نهم الس لسد سدس فن كنو اكث كثر من ذلك فهم شرك ركء في الث لثل ثلث من بعد وصي صيه يوص وصي به او دين غير مضر وصي صيه من الل لله ولل لله علي ليم حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (506, 'quran:4:13', 'quran', 'quran', '4:13', 13, 505, 'An-Nisa', 'النساء', 'تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', NULL, NULL, 'تلك حدود الله ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر خلدين فيها وذلك الفوز العظيم', 'تلك حدود له ومن يطع له رسول يدخل جنت تجر من تحت انهر خلد يه ذلك فوز عظيم', 'quran', NULL, NULL, 'https://quran.com/4/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (506, 'تلك حدو دود الل لله ومن يطع الل لله ورس رسو سول وله يدخ دخل خله جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه وذل ذلك الف لفو فوز الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (507, 'quran:4:14', 'quran', 'quran', '4:14', 14, 506, 'An-Nisa', 'النساء', 'وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ', NULL, NULL, 'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خلدا فيها وله عذاب مهين', 'ومن يعص له رسول يتعد حدود يدخل نر خلد يه ول عذب مه', 'quran', NULL, NULL, 'https://quran.com/4/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (507, 'ومن يعص الل لله ورس رسو سول وله ويت يتع تعد حدو دود وده يدخ دخل خله نر خلد فيه وله عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (508, 'quran:4:15', 'quran', 'quran', '4:15', 15, 507, 'An-Nisa', 'النساء', 'وَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا', NULL, NULL, 'والتي ياتين الفحشه من نسايكم فاستشهدوا عليهن اربعه منكم فان شهدوا فامسكوهن في البيوت حتي يتوفاهن الموت او يجعل الله لهن سبيلا', 'تي يت فحش من نسي استشهد علي اربع من فن شهد امسكو في بيوت حت يتوف موت او يجعل له لهن سبيل', 'quran', NULL, NULL, 'https://quran.com/4/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (508, 'ولت لتي يتي تين الف لفح فحش حشه من نسي سيك يكم فست ستش تشه شهد هدو علي ليه يهن ارب ربع بعه منك نكم فن شهد هدو فمس مسك سكو كوه وهن في الب لبي بيو يوت حتي يتو توف وفه فهن الم لمو موت او يجع جعل الل لله لهن سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (509, 'quran:4:16', 'quran', 'quran', '4:16', 16, 508, 'An-Nisa', 'النساء', 'وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا', NULL, NULL, 'والذان ياتينها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما', 'ذن يتين من اذوهم فن تب اصلح اعرض عنهم ان له كن توب رحيم', 'quran', NULL, NULL, 'https://quran.com/4/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (509, 'ولذ لذن يتي تين ينه منك نكم فذو ذوه وهم فن تب وصل صلح فعر عرض رضو عنه نهم ان الل لله كن توب رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (510, 'quran:4:17', 'quran', 'quran', '4:17', 17, 509, 'An-Nisa', 'النساء', 'إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', NULL, NULL, 'انما التوبه علي الله للذين يعملون السوء بجهله ثم يتوبون من قريب فاوليك يتوب الله عليهم وكان الله عليما حكيما', 'انم توب عل له ذين يعمل سوء بجهل ثم يتوب من قريب اوليك يتوب له علي كن له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (510, 'انم الت لتو توب وبه علي الل لله للذ لذي ذين يعم عمل ملو لون الس لسو سوء بجه جهل هله ثم يتو توب وبو بون من قري ريب فول ولي ليك يتو توب الل لله علي ليه يهم وكن الل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (511, 'quran:4:18', 'quran', 'quran', '4:18', 18, 510, 'An-Nisa', 'النساء', 'وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا', NULL, NULL, 'وليست التوبه للذين يعملون السيات حتي اذا حضر احدهم الموت قال اني تبت الن ولا الذين يموتون وهم كفار اوليك اعتدنا لهم عذابا اليما', 'ليست توب ذين يعمل سي حت اذ حضر احد موت قل ان تبت الن ول ذين يموت وهم كفر اوليك اعتد لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/4/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (511, 'ولي ليس يست الت لتو توب وبه للذ لذي ذين يعم عمل ملو لون الس لسي سيت حتي اذ حضر احد حده دهم الم لمو موت قل اني تبت الن ول الذ لذي ذين يمو موت وتو تون وهم كفر اول ولي ليك اعت عتد تدن لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (512, 'quran:4:19', 'quran', 'quran', '4:19', 19, 511, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا', NULL, NULL, 'يا ايها الذين امنوا لا يحل لكم ان ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما اتيتموهن الا ان ياتين بفحشه مبينه وعاشروهن بالمعروف فان كرهتموهن فعسي ان تكرهوا شيا ويجعل الله فيه خيرا كثيرا', 'ي اي ذين امن ل يحل لكم ان ترث نسء كر ول تعضلو لتذهب ببعض م اتيتمو ال ان يت بفحش مبين عشرو معروف فن كرهتمو عس ان تكره شي يجعل له في خير كثير', 'quran', NULL, NULL, 'https://quran.com/4/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (512, 'ي ايه الذ لذي ذين امن منو ل يحل لكم ان ترث رثو الن لنس نسء كره ول تعض عضل ضلو لوه وهن لتذ تذه ذهب هبو ببع بعض م اتي تيت يتم تمو موه وهن ال ان يتي تين بفح فحش حشه مبي بين ينه وعش عشر شرو روه وهن بلم لمع معر عرو روف فن كره رهت هتم تمو موه وهن فعس عسي ان تكر كره رهو شي ويج يجع جعل الل لله فيه خير كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (513, 'quran:4:20', 'quran', 'quran', '4:20', 20, 512, 'An-Nisa', 'النساء', 'وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا', NULL, NULL, 'وان اردتم استبدال زوج مكان زوج واتيتم احداهن قنطارا فلا تاخذوا منه شيا اتاخذونه بهتنا واثما مبينا', 'ون اردتم استبدل زوج مك زوج اتيتم احد قنطر فل تخذ من شي اتخذون بهت اثم مبي', 'quran', NULL, NULL, 'https://quran.com/4/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (513, 'ون ارد ردت دتم است ستب تبد بدل زوج مكن زوج وتي تيت يتم احد حده دهن قنط نطر فل تخذ خذو منه شي اتخ تخذ خذو ذون ونه بهت هتن وثم مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (514, 'quran:4:21', 'quran', 'quran', '4:21', 21, 513, 'An-Nisa', 'النساء', 'وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا', NULL, NULL, 'وكيف تاخذونه وقد افضي بعضكم الي بعض واخذن منكم ميثقا غليظا', 'كيف تخذون وقد افض بعض ال بعض اخذن من ميثق غليظ', 'quran', NULL, NULL, 'https://quran.com/4/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (514, 'وكي كيف تخذ خذو ذون ونه وقد افض فضي بعض عضك ضكم الي بعض وخذ خذن منك نكم ميث يثق غلي ليظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (515, 'quran:4:22', 'quran', 'quran', '4:22', 22, 514, 'An-Nisa', 'النساء', 'وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا', NULL, NULL, 'ولا تنكحوا ما نكح اباوكم من النساء الا ما قد سلف انه كان فحشه ومقتا وساء سبيلا', 'ول تنكح م نكح ابو من نسء ال م قد سلف ان كن حش مقت سء سبيل', 'quran', NULL, NULL, 'https://quran.com/4/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (515, 'ول تنك نكح كحو م نكح ابو بوك وكم من الن لنس نسء ال م قد سلف انه كن فحش حشه ومق مقت وسء سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (516, 'quran:4:23', 'quran', 'quran', '4:23', 23, 515, 'An-Nisa', 'النساء', 'حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'حرمت عليكم امهتكم وبناتكم واخوتكم وعمتكم وخلتكم وبنات الاخ وبنات الاخت وامهتكم التي ارضعنكم واخوتكم من الرضعه وامهت نسايكم وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحليل ابنايكم الذين من اصلبكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما', 'حرمت علي امهت بنت اخوت عمت خلت بن اخ بن اخت امهت تي ارضعن اخوت من رضع امهت نسي ربيب تي في حجور من نسي تي دخلتم بهن فن لم تكون دخلتم بهن فل جنح علي حليل ابني ذين من اصلب ون تجمع بين اخت ال م قد سلف ان له كن غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (516, 'حرم رمت علي ليك يكم امه مهت هتك تكم وبن بنت نتك تكم وخو خوت وتك تكم وعم عمت متك تكم وخل خلت لتك تكم وبن بنت الخ وبن بنت الخ لخت ومه مهت هتك تكم الت لتي ارض رضع ضعن عنك نكم وخو خوت وتك تكم من الر لرض رضع ضعه ومه مهت نسي سيك يكم ورب ربي بيب يبك بكم الت لتي في حجو جور ورك ركم من نسي سيك يكم الت لتي دخل خلت لتم بهن فن لم تكو كون ونو دخل خلت لتم بهن فل جنح علي ليك يكم وحل حلي ليل ابن بني نيك يكم الذ لذي ذين من اصل صلب لبك بكم ون تجم جمع معو بين الخ لخت ختي تين ال م قد سلف ان الل لله كن غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (517, 'quran:4:24', 'quran', 'quran', '4:24', 24, 516, 'An-Nisa', 'النساء', 'وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا', NULL, NULL, 'والمحصنت من النساء الا ما ملكت ايمنكم كتب الله عليكم واحل لكم ما وراء ذلكم ان تبتغوا بامولكم محصنين غير مسفحين فما استمتعتم به منهن فاتوهن اجورهن فريضه ولا جناح عليكم فيما ترضيتم به من بعد الفريضه ان الله كان عليما حكيما', 'محصنت من نسء ال م ملكت ايمن كتب له علي احل لكم م رء ذل ان تبتغ بمول محصن غير مسفح فم استمتعتم به من اتو اجور ريض ول جنح علي يم ترضيتم به من بعد فريض ان له كن عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (517, 'ولم لمح محص حصن صنت من الن لنس نسء ال م ملك لكت ايم يمن منك نكم كتب الل لله علي ليك يكم وحل لكم م ورء ذلك لكم ان تبت بتغ تغو بمو مول ولك لكم محص حصن صني نين غير مسف سفح فحي حين فم است ستم تمت متع تعت عتم به منه نهن فتو توه وهن اجو جور وره رهن فري ريض يضه ول جنح علي ليك يكم فيم ترض رضي ضيت يتم به من بعد الف لفر فري ريض يضه ان الل لله كن علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (518, 'quran:4:25', 'quran', 'quran', '4:25', 25, 517, 'An-Nisa', 'النساء', 'وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'ومن لم يستطع منكم طولا ان ينكح المحصنت المومنت فمن ما ملكت ايمنكم من فتيتكم المومنت والله اعلم بايمنكم بعضكم من بعض فانكحوهن باذن اهلهن واتوهن اجورهن بالمعروف محصنت غير مسفحت ولا متخذت اخدان فاذا احصن فان اتين بفحشه فعليهن نصف ما علي المحصنت من العذاب ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم', 'ومن لم يستطع من طول ان ينكح محصنت مومنت فمن م ملكت ايمن من تيت مومنت له اعلم بيمن بعض من بعض انكحو بذن اهل اتو اجور معروف محصنت غير مسفحت ول متخذت اخد اذ احصن فن ات بفحش علي نصف م عل محصنت من عذب ذلك لمن خش عنت من ون تصبر خير لكم له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (518, 'ومن لم يست ستط تطع منك نكم طول ان ينك نكح الم لمح محص حصن صنت الم لمو موم ومن منت فمن م ملك لكت ايم يمن منك نكم من فتي تيت يتك تكم الم لمو موم ومن منت ولل لله اعل علم بيم يمن منك نكم بعض عضك ضكم من بعض فنك نكح كحو حوه وهن بذن اهل هله لهن وتو توه وهن اجو جور وره رهن بلم لمع معر عرو روف محص حصن صنت غير مسف سفح فحت ول متخ تخذ خذت اخد خدن فذ احص حصن فن اتي تين بفح فحش حشه فعل علي ليه يهن نصف م علي الم لمح محص حصن صنت من الع لعذ عذب ذلك لمن خشي الع لعن عنت منك نكم ون تصب صبر برو خير لكم ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (519, 'quran:4:26', 'quran', 'quran', '4:26', 26, 518, 'An-Nisa', 'النساء', 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', NULL, NULL, 'يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم', 'يريد له ليب لكم يهدي سنن ذين من قبل يتوب علي له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (519, 'يري ريد الل لله ليب يبي بين لكم ويه يهد هدي ديك يكم سنن الذ لذي ذين من قبل بلك لكم ويت يتو توب علي ليك يكم ولل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (520, 'quran:4:27', 'quran', 'quran', '4:27', 27, 519, 'An-Nisa', 'النساء', 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا', NULL, NULL, 'والله يريد ان يتوب عليكم ويريد الذين يتبعون الشهوت ان تميلوا ميلا عظيما', 'له يريد ان يتوب علي يريد ذين يتبع شهوت ان تميل ميل عظيم', 'quran', NULL, NULL, 'https://quran.com/4/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (520, 'ولل لله يري ريد ان يتو توب علي ليك يكم وير يري ريد الذ لذي ذين يتب تبع بعو عون الش لشه شهو هوت ان تمي ميل يلو ميل عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (521, 'quran:4:28', 'quran', 'quran', '4:28', 28, 520, 'An-Nisa', 'النساء', 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا', NULL, NULL, 'يريد الله ان يخفف عنكم وخلق الانسن ضعيفا', 'يريد له ان يخفف عن خلق انسن ضعيف', 'quran', NULL, NULL, 'https://quran.com/4/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (521, 'يري ريد الل لله ان يخف خفف عنك نكم وخل خلق الن لنس نسن ضعي عيف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (522, 'quran:4:29', 'quran', 'quran', '4:29', 29, 521, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا', NULL, NULL, 'يا ايها الذين امنوا لا تاكلوا امولكم بينكم بالبطل الا ان تكون تجره عن تراض منكم ولا تقتلوا انفسكم ان الله كان بكم رحيما', 'ي اي ذين امن ل تكل امول بين بطل ال ان تك تجر عن ترض من ول تقتل انفس ان له كن بكم رحيم', 'quran', NULL, NULL, 'https://quran.com/4/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (522, 'ي ايه الذ لذي ذين امن منو ل تكل كلو امو مول ولك لكم بين ينك نكم بلب لبط بطل ال ان تكو كون تجر جره عن ترض منك نكم ول تقت قتل تلو انف نفس فسك سكم ان الل لله كن بكم رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (523, 'quran:4:30', 'quran', 'quran', '4:30', 30, 522, 'An-Nisa', 'النساء', 'وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', NULL, NULL, 'ومن يفعل ذلك عدونا وظلما فسوف نصليه نارا وكان ذلك علي الله يسيرا', 'ومن يفعل ذلك عدو ظلم سوف نصل نر كن ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/4/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (523, 'ومن يفع فعل ذلك عدو دون وظل ظلم فسو سوف نصل صلي ليه نر وكن ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (524, 'quran:4:31', 'quran', 'quran', '4:31', 31, 523, 'An-Nisa', 'النساء', 'إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا', NULL, NULL, 'ان تجتنبوا كباير ما تنهون عنه نكفر عنكم سياتكم وندخلكم مدخلا كريما', 'ان تجتنب كبير م تنه عن نكفر عن سيت ندخل مدخل كريم', 'quran', NULL, NULL, 'https://quran.com/4/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (524, 'ان تجت جتن تنب نبو كبي بير م تنه نهو هون عنه نكف كفر عنك نكم سيت يتك تكم وند ندخ دخل خلك لكم مدخ دخل كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (525, 'quran:4:32', 'quran', 'quran', '4:32', 32, 524, 'An-Nisa', 'النساء', 'وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا', NULL, NULL, 'ولا تتمنوا ما فضل الله به بعضكم علي بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن وسلوا الله من فضله ان الله كان بكل شيء عليما', 'ول تتمن م فضل له به بعض عل بعض رجل نصيب مم اكتسب نسء نصيب مم اكتسبن سل له من ضل ان له كن بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/4/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (525, 'ول تتم تمن منو م فضل الل لله به بعض عضك ضكم علي بعض للر لرج رجل نصي صيب مم اكت كتس تسب سبو ولل للن لنس نسء نصي صيب مم اكت كتس تسب سبن وسل سلو الل لله من فضل ضله ان الل لله كن بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (526, 'quran:4:33', 'quran', 'quran', '4:33', 33, 525, 'An-Nisa', 'النساء', 'وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا', NULL, NULL, 'ولكل جعلنا مولي مما ترك الولدان والاقربون والذين عقدت ايمنكم فاتوهم نصيبهم ان الله كان علي كل شيء شهيدا', 'لكل جعل مول مم ترك ولد اقرب ذين عقدت ايمن اتو نصيب ان له كن عل كل شيء شهيد', 'quran', NULL, NULL, 'https://quran.com/4/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (526, 'ولك لكل جعل علن مول ولي مم ترك الو لول ولد لدن ولق لقر قرب ربو بون ولذ لذي ذين عقد قدت ايم يمن منك نكم فتو توه وهم نصي صيب يبه بهم ان الل لله كن علي كل شيء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (527, 'quran:4:34', 'quran', 'quran', '4:34', 34, 526, 'An-Nisa', 'النساء', 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا', NULL, NULL, 'الرجال قومون علي النساء بما فضل الله بعضهم علي بعض وبما انفقوا من امولهم فالصلحت قنتت حفظت للغيب بما حفظ الله والتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا', 'رجل قوم عل نسء بم فضل له بعض عل بعض بم انفق من امول صلحت قنتت حفظت غيب بم حفظ له تي تخف نشوز عظو اهجرو في مضجع اضربو فن اطعن فل تبغ علي سبيل ان له كن علي كبير', 'quran', NULL, NULL, 'https://quran.com/4/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (527, 'الر لرج رجل قوم ومو مون علي الن لنس نسء بم فضل الل لله بعض عضه ضهم علي بعض وبم انف نفق فقو من امو مول وله لهم فلص لصل صلح لحت قنت نتت حفظ فظت للغ لغي غيب بم حفظ الل لله ولت لتي تخف خفو فون نشو شوز وزه زهن فعظ عظو ظوه وهن وهج هجر جرو روه وهن في الم لمض مضج ضجع وضر ضرب ربو بوه وهن فن اطع طعن عنك نكم فل تبغ بغو علي ليه يهن سبي بيل ان الل لله كن علي كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (528, 'quran:4:35', 'quran', 'quran', '4:35', 35, 527, 'An-Nisa', 'النساء', 'وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا', NULL, NULL, 'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلحا يوفق الله بينهما ان الله كان عليما خبيرا', 'ون خفتم شقق بينهم ابعث حكم من اهل حكم من اهل ان يريد اصلح يوفق له بينهم ان له كن عليم خبير', 'quran', NULL, NULL, 'https://quran.com/4/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (528, 'ون خفت فتم شقق بين ينه نهم فبع بعث عثو حكم من اهل هله وحك حكم من اهل هله ان يري ريد اصل صلح يوف وفق الل لله بين ينه نهم ان الل لله كن علي ليم خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (529, 'quran:4:36', 'quran', 'quran', '4:36', 36, 528, 'An-Nisa', 'النساء', 'وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا', NULL, NULL, 'واعبدوا الله ولا تشركوا به شيا وبالولدين احسنا وبذي القربي واليتمي والمسكين والجار ذي القربي والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت ايمنكم ان الله لا يحب من كان مختالا فخورا', 'اعبد له ول تشرك به شي ولد احس بذ قرب يتم مسك جر ذي قرب جر جنب صحب جنب ابن سبيل وم ملكت ايمن ان له ل يحب من كن مختل خور', 'quran', NULL, NULL, 'https://quran.com/4/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (529, 'وعب عبد بدو الل لله ول تشر شرك ركو به شي وبل بلو لول ولد لدي دين احس حسن وبذ بذي الق لقر قرب ربي ولي ليت يتم تمي ولم لمس مسك سكي كين ولج لجر ذي الق لقر قرب ربي ولج لجر الج لجن جنب ولص لصح صحب بلج لجن جنب وبن الس لسب سبي بيل وم ملك لكت ايم يمن منك نكم ان الل لله ل يحب من كن مخت ختل فخو خور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (530, 'quran:4:37', 'quran', 'quran', '4:37', 37, 529, 'An-Nisa', 'النساء', 'ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', NULL, NULL, 'الذين يبخلون ويامرون الناس بالبخل ويكتمون ما اتاهم الله من فضله واعتدنا للكفرين عذابا مهينا', 'ذين يبخل يمر نس بخل يكتم م ات له من ضل اعتد كفر عذب مهي', 'quran', NULL, NULL, 'https://quran.com/4/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (530, 'الذ لذي ذين يبخ بخل خلو لون ويم يمر مرو رون الن لنس بلب لبخ بخل ويك يكت كتم تمو مون م اته تهم الل لله من فضل ضله وعت عتد تدن للك لكف كفر فري رين عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (531, 'quran:4:38', 'quran', 'quran', '4:38', 38, 530, 'An-Nisa', 'النساء', 'وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا', NULL, NULL, 'والذين ينفقون امولهم رياء الناس ولا يومنون بالله ولا باليوم الاخر ومن يكن الشيطن له قرينا فساء قرينا', 'ذين ينفق امول ريء نس ول يومن له ول يوم اخر ومن يكن شيطن له قري سء قري', 'quran', NULL, NULL, 'https://quran.com/4/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (531, 'ولذ لذي ذين ينف نفق فقو قون امو مول وله لهم ريء الن لنس ول يوم ومن منو نون بلل لله ول بلي ليو يوم الخ لخر ومن يكن الش لشي شيط يطن له قري رين فسء قري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (532, 'quran:4:39', 'quran', 'quran', '4:39', 39, 531, 'An-Nisa', 'النساء', 'وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا', NULL, NULL, 'وماذا عليهم لو امنوا بالله واليوم الاخر وانفقوا مما رزقهم الله وكان الله بهم عليما', 'مذ علي لو امن له يوم اخر انفق مم رزق له كن له بهم عليم', 'quran', NULL, NULL, 'https://quran.com/4/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (532, 'ومذ علي ليه يهم لو امن منو بلل لله ولي ليو يوم الخ لخر ونف نفق فقو مم رزق زقه قهم الل لله وكن الل لله بهم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (533, 'quran:4:40', 'quran', 'quran', '4:40', 40, 532, 'An-Nisa', 'النساء', 'إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا', NULL, NULL, 'ان الله لا يظلم مثقال ذره وان تك حسنه يضعفها ويوت من لدنه اجرا عظيما', 'ان له ل يظلم مثقل ذر ون تك حسن يضعف يوت من لدن اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (533, 'ان الل لله ل يظل ظلم مثق ثقل ذره ون تك حسن سنه يضع ضعف عفه ويو يوت من لدن دنه اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (534, 'quran:4:41', 'quran', 'quran', '4:41', 41, 533, 'An-Nisa', 'النساء', 'فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدٗا', NULL, NULL, 'فكيف اذا جينا من كل امه بشهيد وجينا بك علي هولاء شهيدا', 'كيف اذ جي من كل ام بشهيد جي بك عل هولء شهيد', 'quran', NULL, NULL, 'https://quran.com/4/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (534, 'فكي كيف اذ جين من كل امه بشه شهي هيد وجي جين بك علي هول ولء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (535, 'quran:4:42', 'quran', 'quran', '4:42', 42, 534, 'An-Nisa', 'النساء', 'يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا', NULL, NULL, 'يوميذ يود الذين كفروا وعصوا الرسول لو تسوي بهم الارض ولا يكتمون الله حديثا', 'يوميذ يود ذين كفر عص رسول لو تسو بهم ارض ول يكتم له حديث', 'quran', NULL, NULL, 'https://quran.com/4/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (535, 'يوم ومي ميذ يود الذ لذي ذين كفر فرو وعص عصو الر لرس رسو سول لو تسو سوي بهم الر لرض ول يكت كتم تمو مون الل لله حدي ديث');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (536, 'quran:4:43', 'quran', 'quran', '4:43', 43, 535, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', NULL, NULL, 'يا ايها الذين امنوا لا تقربوا الصلاه وانتم سكري حتي تعلموا ما تقولون ولا جنبا الا عابري سبيل حتي تغتسلوا وان كنتم مرضي او علي سفر او جاء احد منكم من الغايط او لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم ان الله كان عفوا غفورا', 'ي اي ذين امن ل تقرب صل انتم سكر حت تعلم م تقول ول جنب ال عبر سبيل حت تغتسل ون كنتم مرض او عل سفر او جء احد من من غيط او لمستم نسء فلم تجد مء تيمم صعيد طيب امسح بوجوه ايدي ان له كن عف غفور', 'quran', NULL, NULL, 'https://quran.com/4/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (536, 'ي ايه الذ لذي ذين امن منو ل تقر قرب ربو الص لصل صله ونت نتم سكر كري حتي تعل علم لمو م تقو قول ولو لون ول جنب ال عبر بري سبي بيل حتي تغت غتس تسل سلو ون كنت نتم مرض رضي او علي سفر او جء احد منك نكم من الغ لغي غيط او لمس مست ستم الن لنس نسء فلم تجد جدو مء فتي تيم يمم ممو صعي عيد طيب فمس مسح سحو بوج وجو جوه وهك هكم ويد يدي ديك يكم ان الل لله كن عفو غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (537, 'quran:4:44', 'quran', 'quran', '4:44', 44, 536, 'An-Nisa', 'النساء', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ', NULL, NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يشترون الضلله ويريدون ان تضلوا السبيل', 'الم تر ال ذين اوت نصيب من كتب يشتر ضلل يريد ان تضل سبيل', 'quran', NULL, NULL, 'https://quran.com/4/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (537, 'الم تر الي الذ لذي ذين اوت وتو نصي صيب من الك لكت كتب يشت شتر ترو رون الض لضل ضلل لله وير يري ريد يدو دون ان تضل ضلو الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (538, 'quran:4:45', 'quran', 'quran', '4:45', 45, 537, 'An-Nisa', 'النساء', 'وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا', NULL, NULL, 'والله اعلم باعدايكم وكفي بالله وليا وكفي بالله نصيرا', 'له اعلم بعدي كف له لي كف له نصير', 'quran', NULL, NULL, 'https://quran.com/4/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (538, 'ولل لله اعل علم بعد عدي ديك يكم وكف كفي بلل لله ولي وكف كفي بلل لله نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (539, 'quran:4:46', 'quran', 'quran', '4:46', 46, 538, 'An-Nisa', 'النساء', 'مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا', NULL, NULL, 'من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع ورعنا ليا بالسنتهم وطعنا في الدين ولو انهم قالوا سمعنا واطعنا واسمع وانظرنا لكان خيرا لهم واقوم ولكن لعنهم الله بكفرهم فلا يومنون الا قليلا', 'من ذين هد يحرف كلم عن موضع يقول سمع عصي اسمع غير مسمع رع لي سنت طع في دين ولو ان قل سمع اطع اسمع انظر لك خير لهم اقوم لكن لعن له بكفر فل يومن ال قليل', 'quran', NULL, NULL, 'https://quran.com/4/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (539, 'من الذ لذي ذين هدو يحر حرف رفو فون الك لكل كلم عن موض وضع ضعه ويق يقو قول ولو لون سمع معن وعص عصي صين وسم سمع غير مسم سمع ورع رعن لي بلس لسن سنت نته تهم وطع طعن في الد لدي دين ولو انه نهم قلو سمع معن وطع طعن وسم سمع ونظ نظر ظرن لكن خير لهم وقو قوم ولك لكن لعن عنه نهم الل لله بكف كفر فره رهم فل يوم ومن منو نون ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (540, 'quran:4:47', 'quran', 'quran', '4:47', 47, 539, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا', NULL, NULL, 'يا ايها الذين اوتوا الكتب امنوا بما نزلنا مصدقا لما معكم من قبل ان نطمس وجوها فنردها علي ادبارها او نلعنهم كما لعنا اصحب السبت وكان امر الله مفعولا', 'ي اي ذين اوت كتب امن بم نزل مصدق لم مع من قبل ان نطمس جو نرد عل ادبر او نلعن كم لع اصحب سبت كن امر له مفعول', 'quran', NULL, NULL, 'https://quran.com/4/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (540, 'ي ايه الذ لذي ذين اوت وتو الك لكت كتب امن منو بم نزل زلن مصد صدق لم معك عكم من قبل ان نطم طمس وجو جوه فنر نرد رده علي ادب دبر بره او نلع لعن عنه نهم كم لعن اصح صحب الس لسب سبت وكن امر الل لله مفع فعو عول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (541, 'quran:4:48', 'quran', 'quran', '4:48', 48, 540, 'An-Nisa', 'النساء', 'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا', NULL, NULL, 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افتري اثما عظيما', 'ان له ل يغفر ان يشرك به يغفر م دون ذلك لمن يشء ومن يشرك له فقد افتر اثم عظيم', 'quran', NULL, NULL, 'https://quran.com/4/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (541, 'ان الل لله ل يغف غفر ان يشر شرك به ويغ يغف غفر م دون ذلك لمن يشء ومن يشر شرك بلل لله فقد افت فتر تري اثم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (542, 'quran:4:49', 'quran', 'quran', '4:49', 49, 541, 'An-Nisa', 'النساء', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا', NULL, NULL, 'الم تر الي الذين يزكون انفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا', 'الم تر ال ذين يزك انفس بل له يزك من يشء ول يظلم تيل', 'quran', NULL, NULL, 'https://quran.com/4/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (542, 'الم تر الي الذ لذي ذين يزك زكو كون انف نفس فسه سهم بل الل لله يزك زكي من يشء ول يظل ظلم لمو مون فتي تيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (543, 'quran:4:50', 'quran', 'quran', '4:50', 50, 542, 'An-Nisa', 'النساء', 'ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا', NULL, NULL, 'انظر كيف يفترون علي الله الكذب وكفي به اثما مبينا', 'انظر كيف يفتر عل له كذب كف به اثم مبي', 'quran', NULL, NULL, 'https://quran.com/4/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (543, 'انظ نظر كيف يفت فتر ترو رون علي الل لله الك لكذ كذب وكف كفي به اثم مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (544, 'quran:4:51', 'quran', 'quran', '4:51', 51, 543, 'An-Nisa', 'النساء', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا', NULL, NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يومنون بالجبت والطغوت ويقولون للذين كفروا هولاء اهدي من الذين امنوا سبيلا', 'الم تر ال ذين اوت نصيب من كتب يومن جبت طغوت يقول ذين كفر هولء اهد من ذين امن سبيل', 'quran', NULL, NULL, 'https://quran.com/4/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (544, 'الم تر الي الذ لذي ذين اوت وتو نصي صيب من الك لكت كتب يوم ومن منو نون بلج لجب جبت ولط لطغ طغو غوت ويق يقو قول ولو لون للذ لذي ذين كفر فرو هول ولء اهد هدي من الذ لذي ذين امن منو سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (545, 'quran:4:52', 'quran', 'quran', '4:52', 52, 544, 'An-Nisa', 'النساء', 'أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', NULL, NULL, 'اوليك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا', 'اوليك ذين لعن له ومن يلعن له فلن تجد له نصير', 'quran', NULL, NULL, 'https://quran.com/4/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (545, 'اول ولي ليك الذ لذي ذين لعن عنه نهم الل لله ومن يلع لعن الل لله فلن تجد له نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (546, 'quran:4:53', 'quran', 'quran', '4:53', 53, 545, 'An-Nisa', 'النساء', 'أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا', NULL, NULL, 'ام لهم نصيب من الملك فاذا لا يوتون الناس نقيرا', 'ام لهم نصيب من ملك اذ ل يوت نس نقير', 'quran', NULL, NULL, 'https://quran.com/4/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (546, 'ام لهم نصي صيب من الم لمل ملك فذ ل يوت وتو تون الن لنس نقي قير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (547, 'quran:4:54', 'quran', 'quran', '4:54', 54, 546, 'An-Nisa', 'النساء', 'أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا', NULL, NULL, 'ام يحسدون الناس علي ما اتاهم الله من فضله فقد اتينا ال ابرهيم الكتب والحكمه واتينهم ملكا عظيما', 'ام يحسد نس عل م ات له من ضل فقد اتي ال ابرهيم كتب حكم اتين ملك عظيم', 'quran', NULL, NULL, 'https://quran.com/4/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (547, 'ام يحس حسد سدو دون الن لنس علي م اته تهم الل لله من فضل ضله فقد اتي تين ال ابر بره رهي هيم الك لكت كتب ولح لحك حكم كمه وتي تين ينه نهم ملك عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (548, 'quran:4:55', 'quran', 'quran', '4:55', 55, 547, 'An-Nisa', 'النساء', 'فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', NULL, NULL, 'فمنهم من امن به ومنهم من صد عنه وكفي بجهنم سعيرا', 'من من امن به من من صد عن كف بجهنم سعير', 'quran', NULL, NULL, 'https://quran.com/4/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (548, 'فمن منه نهم من امن به ومن منه نهم من صد عنه وكف كفي بجه جهن هنم سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (549, 'quran:4:56', 'quran', 'quran', '4:56', 56, 548, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا', NULL, NULL, 'ان الذين كفروا بايتنا سوف نصليهم نارا كلما نضجت جلودهم بدلنهم جلودا غيرها ليذوقوا العذاب ان الله كان عزيزا حكيما', 'ان ذين كفر بيت سوف نصلي نر كلم نضجت جلود بدلن جلود غير ليذوق عذب ان له كن عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/4/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (549, 'ان الذ لذي ذين كفر فرو بيت يتن سوف نصل صلي ليه يهم نر كلم نضج ضجت جلو لود وده دهم بدل دلن لنه نهم جلو لود غير يره ليذ يذو ذوق وقو الع لعذ عذب ان الل لله كن عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (550, 'quran:4:57', 'quran', 'quran', '4:57', 57, 549, 'An-Nisa', 'النساء', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا', NULL, NULL, 'والذين امنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا لهم فيها ازوج مطهره وندخلهم ظلا ظليلا', 'ذين امن عمل صلحت سندخل جنت تجر من تحت انهر خلد يه ابد لهم يه ازوج مطهر ندخل ظل ظليل', 'quran', NULL, NULL, 'https://quran.com/4/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (550, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت سند ندخ دخل خله لهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ابد لهم فيه ازو زوج مطه طهر هره وند ندخ دخل خله لهم ظل ظلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (551, 'quran:4:58', 'quran', 'quran', '4:58', 58, 550, 'An-Nisa', 'النساء', 'إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا', NULL, NULL, 'ان الله يامركم ان تودوا الامنت الي اهلها واذا حكمتم بين الناس ان تحكموا بالعدل ان الله نعما يعظكم به ان الله كان سميعا بصيرا', 'ان له يمر ان تود امنت ال اهل اذ حكمتم بين نس ان تحكم عدل ان له نعم يعظ به ان له كن سميع بصير', 'quran', NULL, NULL, 'https://quran.com/4/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (551, 'ان الل لله يمر مرك ركم ان تود ودو الم لمن منت الي اهل هله وذ حكم كمت متم بين الن لنس ان تحك حكم كمو بلع لعد عدل ان الل لله نعم يعظ عظك ظكم به ان الل لله كن سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (552, 'quran:4:59', 'quran', 'quran', '4:59', 59, 551, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا', NULL, NULL, 'يا ايها الذين امنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم فان تنزعتم في شيء فردوه الي الله والرسول ان كنتم تومنون بالله واليوم الاخر ذلك خير واحسن تاويلا', 'ي اي ذين امن اطيع له اطيع رسول اول امر من فن تنزعتم في شيء ردو ال له رسول ان كنتم تومن له يوم اخر ذلك خير احسن تويل', 'quran', NULL, NULL, 'https://quran.com/4/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (552, 'ي ايه الذ لذي ذين امن منو اطي طيع يعو الل لله وطي طيع يعو الر لرس رسو سول وول ولي الم لمر منك نكم فن تنز نزع زعت عتم في شيء فرد ردو دوه الي الل لله ولر لرس رسو سول ان كنت نتم توم ومن منو نون بلل لله ولي ليو يوم الخ لخر ذلك خير وحس حسن توي ويل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (553, 'quran:4:60', 'quran', 'quran', '4:60', 60, 552, 'An-Nisa', 'النساء', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا', NULL, NULL, 'الم تر الي الذين يزعمون انهم امنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الي الطغوت وقد امروا ان يكفروا به ويريد الشيطن ان يضلهم ضللا بعيدا', 'الم تر ال ذين يزعم ان امن بم انزل يك وم انزل من قبلك يريد ان يتحكم ال طغوت وقد امر ان يكفر به يريد شيطن ان يضل ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/4/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (553, 'الم تر الي الذ لذي ذين يزع زعم عمو مون انه نهم امن منو بم انز نزل الي ليك وم انز نزل من قبل بلك يري ريد يدو دون ان يتح تحك حكم كمو الي الط لطغ طغو غوت وقد امر مرو ان يكف كفر فرو به وير يري ريد الش لشي شيط يطن ان يضل ضله لهم ضلل بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (554, 'quran:4:61', 'quran', 'quran', '4:61', 61, 553, 'An-Nisa', 'النساء', 'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا', NULL, NULL, 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول رايت المنفقين يصدون عنك صدودا', 'اذ قيل لهم تعل ال م انزل له ول رسول ريت منفق يصد عنك صدود', 'quran', NULL, NULL, 'https://quran.com/4/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (554, 'وذ قيل لهم تعل علو الي م انز نزل الل لله ولي الر لرس رسو سول ريت الم لمن منف نفق فقي قين يصد صدو دون عنك صدو دود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (555, 'quran:4:62', 'quran', 'quran', '4:62', 62, 554, 'An-Nisa', 'النساء', 'فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا', NULL, NULL, 'فكيف اذا اصبتهم مصيبه بما قدمت ايديهم ثم جاءوك يحلفون بالله ان اردنا الا احسنا وتوفيقا', 'كيف اذ اصبت مصيب بم قدمت ايدي ثم جءوك يحلف له ان ارد ال احس توفيق', 'quran', NULL, NULL, 'https://quran.com/4/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (555, 'فكي كيف اذ اصب صبت بته تهم مصي صيب يبه بم قدم دمت ايد يدي ديه يهم ثم جءو ءوك يحل حلف لفو فون بلل لله ان ارد ردن ال احس حسن وتو توف وفي فيق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (556, 'quran:4:63', 'quran', 'quran', '4:63', 63, 555, 'An-Nisa', 'النساء', 'أُوْلَٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا', NULL, NULL, 'اوليك الذين يعلم الله ما في قلوبهم فاعرض عنهم وعظهم وقل لهم في انفسهم قولا بليغا', 'اوليك ذين يعلم له م في قلوب اعرض عن عظ وقل لهم في انفس قول بليغ', 'quran', NULL, NULL, 'https://quran.com/4/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (556, 'اول ولي ليك الذ لذي ذين يعل علم الل لله م في قلو لوب وبه بهم فعر عرض عنه نهم وعظ عظه ظهم وقل لهم في انف نفس فسه سهم قول بلي ليغ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (557, 'quran:4:64', 'quran', 'quran', '4:64', 64, 556, 'An-Nisa', 'النساء', 'وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا', NULL, NULL, 'وما ارسلنا من رسول الا ليطاع باذن الله ولو انهم اذ ظلموا انفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما', 'وم ارسل من رسول ال ليطع بذن له ولو ان اذ ظلم انفس جءوك استغفر له استغفر لهم رسول لوجد له توب رحيم', 'quran', NULL, NULL, 'https://quran.com/4/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (557, 'وم ارس رسل سلن من رسو سول ال ليط يطع بذن الل لله ولو انه نهم اذ ظلم لمو انف نفس فسه سهم جءو ءوك فست ستغ تغف غفر فرو الل لله وست ستغ تغف غفر لهم الر لرس رسو سول لوج وجد جدو الل لله توب رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (558, 'quran:4:65', 'quran', 'quran', '4:65', 65, 557, 'An-Nisa', 'النساء', 'فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا', NULL, NULL, 'فلا وربك لا يومنون حتي يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما', 'فل ربك ل يومن حت يحكموك يم شجر بين ثم ل يجد في انفس حرج مم قضيت يسلم تسليم', 'quran', NULL, NULL, 'https://quran.com/4/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (558, 'فل ورب ربك ل يوم ومن منو نون حتي يحك حكم كمو موك فيم شجر بين ينه نهم ثم ل يجد جدو في انف نفس فسه سهم حرج مم قضي ضيت ويس يسل سلم لمو تسل سلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (559, 'quran:4:66', 'quran', 'quran', '4:66', 66, 558, 'An-Nisa', 'النساء', 'وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا', NULL, NULL, 'ولو انا كتبنا عليهم ان اقتلوا انفسكم او اخرجوا من ديركم ما فعلوه الا قليل منهم ولو انهم فعلوا ما يوعظون به لكان خيرا لهم واشد تثبيتا', 'ولو ان كتب علي ان اقتل انفس او اخرج من دير م علو ال قليل من ولو ان عل م يوعظ به لك خير لهم اشد تثبيت', 'quran', NULL, NULL, 'https://quran.com/4/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (559, 'ولو ان كتب تبن علي ليه يهم ان اقت قتل تلو انف نفس فسك سكم او اخر خرج رجو من دير يرك ركم م فعل علو لوه ال قلي ليل منه نهم ولو انه نهم فعل علو م يوع وعظ عظو ظون به لكن خير لهم وشد تثب ثبي بيت');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (560, 'quran:4:67', 'quran', 'quran', '4:67', 67, 559, 'An-Nisa', 'النساء', 'وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا', NULL, NULL, 'واذا لاتينهم من لدنا اجرا عظيما', 'اذ لتين من لد اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (560, 'وذ لتي تين ينه نهم من لدن اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (561, 'quran:4:68', 'quran', 'quran', '4:68', 68, 560, 'An-Nisa', 'النساء', 'وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا', NULL, NULL, 'ولهدينهم صرطا مستقيما', 'لهدين صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/4/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (561, 'وله لهد هدي دين ينه نهم صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (562, 'quran:4:69', 'quran', 'quran', '4:69', 69, 561, 'An-Nisa', 'النساء', 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقٗا', NULL, NULL, 'ومن يطع الله والرسول فاوليك مع الذين انعم الله عليهم من النبين والصديقين والشهداء والصلحين وحسن اوليك رفيقا', 'ومن يطع له رسول اوليك مع ذين انعم له علي من نب صديق شهدء صلح حسن اوليك رفيق', 'quran', NULL, NULL, 'https://quran.com/4/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (562, 'ومن يطع الل لله ولر لرس رسو سول فول ولي ليك مع الذ لذي ذين انع نعم الل لله علي ليه يهم من الن لنب نبي بين ولص لصد صدي ديق يقي قين ولش لشه شهد هدء ولص لصل صلح لحي حين وحس حسن اول ولي ليك رفي فيق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (563, 'quran:4:70', 'quran', 'quran', '4:70', 70, 562, 'An-Nisa', 'النساء', 'ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا', NULL, NULL, 'ذلك الفضل من الله وكفي بالله عليما', 'ذلك فضل من له كف له عليم', 'quran', NULL, NULL, 'https://quran.com/4/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (563, 'ذلك الف لفض فضل من الل لله وكف كفي بلل لله علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (564, 'quran:4:71', 'quran', 'quran', '4:71', 71, 563, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا', NULL, NULL, 'يا ايها الذين امنوا خذوا حذركم فانفروا ثبات او انفروا جميعا', 'ي اي ذين امن خذ حذر انفر ثب او انفر جميع', 'quran', NULL, NULL, 'https://quran.com/4/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (564, 'ي ايه الذ لذي ذين امن منو خذو حذر ذرك ركم فنف نفر فرو ثبت او انف نفر فرو جمي ميع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (565, 'quran:4:72', 'quran', 'quran', '4:72', 72, 564, 'An-Nisa', 'النساء', 'وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا', NULL, NULL, 'وان منكم لمن ليبطين فان اصبتكم مصيبه قال قد انعم الله علي اذ لم اكن معهم شهيدا', 'ون من لمن ليبط فن اصبت مصيب قل قد انعم له عل اذ لم اكن مع شهيد', 'quran', NULL, NULL, 'https://quran.com/4/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (565, 'ون منك نكم لمن ليب يبط بطي طين فن اصب صبت بتك تكم مصي صيب يبه قل قد انع نعم الل لله علي اذ لم اكن معه عهم شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (566, 'quran:4:73', 'quran', 'quran', '4:73', 73, 565, 'An-Nisa', 'النساء', 'وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا', NULL, NULL, 'ولين اصبكم فضل من الله ليقولن كان لم تكن بينكم وبينه موده يا ليتني كنت معهم فافوز فوزا عظيما', 'لين اصب فضل من له ليقولن كن لم تكن بين بين مود ي ليتن كنت مع افوز وز عظيم', 'quran', NULL, NULL, 'https://quran.com/4/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (566, 'ولي لين اصب صبك بكم فضل من الل لله ليق يقو قول ولن كن لم تكن بين ينك نكم وبي بين ينه مود وده ي ليت يتن تني كنت معه عهم ففو فوز فوز عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (567, 'quran:4:74', 'quran', 'quran', '4:74', 74, 566, 'An-Nisa', 'النساء', 'فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا', NULL, NULL, 'فليقتل في سبيل الله الذين يشرون الحياه الدنيا بالاخره ومن يقتل في سبيل الله فيقتل او يغلب فسوف نوتيه اجرا عظيما', 'ليقتل في سبيل له ذين يشر حي دني اخر ومن يقتل في سبيل له يقتل او يغلب سوف نوت اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (567, 'فلي ليق يقت قتل في سبي بيل الل لله الذ لذي ذين يشر شرو رون الح لحي حيه الد لدن دني بلخ لخر خره ومن يقت قتل في سبي بيل الل لله فيق يقت قتل او يغل غلب فسو سوف نوت وتي تيه اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (568, 'quran:4:75', 'quran', 'quran', '4:75', 75, 567, 'An-Nisa', 'النساء', 'وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', NULL, NULL, 'وما لكم لا تقتلون في سبيل الله والمستضعفين من الرجال والنساء والولدن الذين يقولون ربنا اخرجنا من هذه القريه الظالم اهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا', 'وم لكم ل تقتل في سبيل له مستضعف من رجل نسء ولدن ذين يقول رب اخرج من هذ قر ظلم اهل اجعل لن من لدنك لي اجعل لن من لدنك نصير', 'quran', NULL, NULL, 'https://quran.com/4/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (568, 'وم لكم ل تقت قتل تلو لون في سبي بيل الل لله ولم لمس مست ستض تضع ضعف عفي فين من الر لرج رجل ولن لنس نسء ولو لول ولد لدن الذ لذي ذين يقو قول ولو لون ربن اخر خرج رجن من هذه الق لقر قري ريه الظ لظل ظلم اهل هله وجع جعل لن من لدن دنك ولي وجع جعل لن من لدن دنك نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (569, 'quran:4:76', 'quran', 'quran', '4:76', 76, 568, 'An-Nisa', 'النساء', 'ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا', NULL, NULL, 'الذين امنوا يقتلون في سبيل الله والذين كفروا يقتلون في سبيل الطغوت فقتلوا اولياء الشيطن ان كيد الشيطن كان ضعيفا', 'ذين امن يقتل في سبيل له ذين كفر يقتل في سبيل طغوت قتل اوليء شيطن ان كيد شيطن كن ضعيف', 'quran', NULL, NULL, 'https://quran.com/4/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (569, 'الذ لذي ذين امن منو يقت قتل تلو لون في سبي بيل الل لله ولذ لذي ذين كفر فرو يقت قتل تلو لون في سبي بيل الط لطغ طغو غوت فقت قتل تلو اول ولي ليء الش لشي شيط يطن ان كيد الش لشي شيط يطن كن ضعي عيف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (570, 'quran:4:77', 'quran', 'quran', '4:77', 77, 569, 'An-Nisa', 'النساء', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا', NULL, NULL, 'الم تر الي الذين قيل لهم كفوا ايديكم واقيموا الصلاه واتوا الزكاه فلما كتب عليهم القتال اذا فريق منهم يخشون الناس كخشيه الله او اشد خشيه وقالوا ربنا لم كتبت علينا القتال لولا اخرتنا الي اجل قريب قل متع الدنيا قليل والاخره خير لمن اتقي ولا تظلمون فتيلا', 'الم تر ال ذين قيل لهم كف ايدي اقيم صل ات زك لم كتب علي قتل اذ ريق من يخش نس كخش له او اشد خش قل رب لم كتبت علي قتل لول اخرت ال اجل قريب قل متع دني قليل اخر خير لمن اتق ول تظلم تيل', 'quran', NULL, NULL, 'https://quran.com/4/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (570, 'الم تر الي الذ لذي ذين قيل لهم كفو ايد يدي ديك يكم وقي قيم يمو الص لصل صله وتو الز لزك زكه فلم كتب علي ليه يهم الق لقت قتل اذ فري ريق منه نهم يخش خشو شون الن لنس كخش خشي شيه الل لله او اشد خشي شيه وقل قلو ربن لم كتب تبت علي لين الق لقت قتل لول اخر خرت رتن الي اجل قري ريب قل متع الد لدن دني قلي ليل ولخ لخر خره خير لمن اتق تقي ول تظل ظلم لمو مون فتي تيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (571, 'quran:4:78', 'quran', 'quran', '4:78', 78, 570, 'An-Nisa', 'النساء', 'أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا', NULL, NULL, 'اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيده وان تصبهم حسنه يقولوا هذه من عند الله وان تصبهم سييه يقولوا هذه من عندك قل كل من عند الله فمال هولاء القوم لا يكادون يفقهون حديثا', 'اينم تكون يدرك موت ولو كنتم في بروج مشيد ون تصب حسن يقول هذ من عند له ون تصب سي يقول هذ من عندك قل كل من عند له مل هولء قوم ل يكد يفقه حديث', 'quran', NULL, NULL, 'https://quran.com/4/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (571, 'اين ينم تكو كون ونو يدر درك ركك ككم الم لمو موت ولو كنت نتم في برو روج مشي شيد يده ون تصب صبه بهم حسن سنه يقو قول ولو هذه من عند الل لله ون تصب صبه بهم سيي ييه يقو قول ولو هذه من عند ندك قل كل من عند الل لله فمل هول ولء الق لقو قوم ل يكد كدو دون يفق فقه قهو هون حدي ديث');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (572, 'quran:4:79', 'quran', 'quran', '4:79', 79, 571, 'An-Nisa', 'النساء', 'مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا', NULL, NULL, 'ما اصابك من حسنه فمن الله وما اصابك من سييه فمن نفسك وارسلنك للناس رسولا وكفي بالله شهيدا', 'م اصبك من حسن فمن له وم اصبك من سي فمن نفسك ارسلنك نس رسول كف له شهيد', 'quran', NULL, NULL, 'https://quran.com/4/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (572, 'م اصب صبك من حسن سنه فمن الل لله وم اصب صبك من سيي ييه فمن نفس فسك ورس رسل سلن لنك للن لنس رسو سول وكف كفي بلل لله شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (573, 'quran:4:80', 'quran', 'quran', '4:80', 80, 572, 'An-Nisa', 'النساء', 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا', NULL, NULL, 'من يطع الرسول فقد اطاع الله ومن تولي فما ارسلنك عليهم حفيظا', 'من يطع رسول فقد اطع له ومن تول فم ارسلنك علي حفيظ', 'quran', NULL, NULL, 'https://quran.com/4/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (573, 'من يطع الر لرس رسو سول فقد اطع الل لله ومن تول ولي فم ارس رسل سلن لنك علي ليه يهم حفي فيظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (574, 'quran:4:81', 'quran', 'quran', '4:81', 81, 573, 'An-Nisa', 'النساء', 'وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', NULL, NULL, 'ويقولون طاعه فاذا برزوا من عندك بيت طايفه منهم غير الذي تقول والله يكتب ما يبيتون فاعرض عنهم وتوكل علي الله وكفي بالله وكيلا', 'يقول طع اذ برز من عندك بيت طيف من غير ذي تقول له يكتب م يبيت اعرض عن توكل عل له كف له كيل', 'quran', NULL, NULL, 'https://quran.com/4/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (574, 'ويق يقو قول ولو لون طعه فذ برز رزو من عند ندك بيت طيف يفه منه نهم غير الذ لذي تقو قول ولل لله يكت كتب م يبي بيت يتو تون فعر عرض عنه نهم وتو توك وكل علي الل لله وكف كفي بلل لله وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (575, 'quran:4:82', 'quran', 'quran', '4:82', 82, 574, 'An-Nisa', 'النساء', 'أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا', NULL, NULL, 'افلا يتدبرون القران ولو كان من عند غير الله لوجدوا فيه اختلفا كثيرا', 'افل يتدبر قر ولو كن من عند غير له لوجد في اختلف كثير', 'quran', NULL, NULL, 'https://quran.com/4/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (575, 'افل يتد تدب دبر برو رون الق لقر قرن ولو كن من عند غير الل لله لوج وجد جدو فيه اخت ختل تلف كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (576, 'quran:4:83', 'quran', 'quran', '4:83', 83, 575, 'An-Nisa', 'النساء', 'وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا', NULL, NULL, 'واذا جاءهم امر من الامن او الخوف اذاعوا به ولو ردوه الي الرسول والي اولي الامر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطن الا قليلا', 'اذ جء امر من امن او خوف اذع به ولو ردو ال رسول ول اول امر من لعلم ذين يستنبطون من لول فضل له علي رحمت لتبعتم شيطن ال قليل', 'quran', NULL, NULL, 'https://quran.com/4/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (576, 'وذ جءه ءهم امر من الم لمن او الخ لخو خوف اذع ذعو به ولو ردو دوه الي الر لرس رسو سول ولي اول ولي الم لمر منه نهم لعل علم لمه الذ لذي ذين يست ستن تنب نبط بطو طون ونه منه نهم ولو لول فضل الل لله علي ليك يكم ورح رحم حمت مته لتب تبع بعت عتم الش لشي شيط يطن ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (577, 'quran:4:84', 'quran', 'quran', '4:84', 84, 576, 'An-Nisa', 'النساء', 'فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا', NULL, NULL, 'فقتل في سبيل الله لا تكلف الا نفسك وحرض المومنين عسي الله ان يكف باس الذين كفروا والله اشد باسا واشد تنكيلا', 'قتل في سبيل له ل تكلف ال نفسك حرض مومن عس له ان يكف بس ذين كفر له اشد بس اشد تنكيل', 'quran', NULL, NULL, 'https://quran.com/4/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (577, 'فقت قتل في سبي بيل الل لله ل تكل كلف ال نفس فسك وحر حرض الم لمو موم ومن مني نين عسي الل لله ان يكف بس الذ لذي ذين كفر فرو ولل لله اشد بس وشد تنك نكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (578, 'quran:4:85', 'quran', 'quran', '4:85', 85, 577, 'An-Nisa', 'النساء', 'مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا', NULL, NULL, 'من يشفع شفعه حسنه يكن له نصيب منها ومن يشفع شفعه سييه يكن له كفل منها وكان الله علي كل شيء مقيتا', 'من يشفع شفع حسن يكن له نصيب من ومن يشفع شفع سي يكن له كفل من كن له عل كل شيء مقيت', 'quran', NULL, NULL, 'https://quran.com/4/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (578, 'من يشف شفع شفع فعه حسن سنه يكن له نصي صيب منه ومن يشف شفع شفع فعه سيي ييه يكن له كفل منه وكن الل لله علي كل شيء مقي قيت');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (579, 'quran:4:86', 'quran', 'quran', '4:86', 86, 578, 'An-Nisa', 'النساء', 'وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا', NULL, NULL, 'واذا حييتم بتحيه فحيوا باحسن منها او ردوها ان الله كان علي كل شيء حسيبا', 'اذ حييتم بتح حي بحسن من او ردو ان له كن عل كل شيء حسيب', 'quran', NULL, NULL, 'https://quran.com/4/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (579, 'وذ حيي ييت يتم بتح تحي حيه فحي حيو بحس حسن منه او ردو دوه ان الل لله كن علي كل شيء حسي سيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (580, 'quran:4:87', 'quran', 'quran', '4:87', 87, 579, 'An-Nisa', 'النساء', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا', NULL, NULL, 'الله لا اله الا هو ليجمعنكم الي يوم القيمه لا ريب فيه ومن اصدق من الله حديثا', 'له ل ال ال هو ليجمعن ال يوم قيم ل ريب في ومن اصدق من له حديث', 'quran', NULL, NULL, 'https://quran.com/4/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (580, 'الل لله ل اله ال هو ليج يجم جمع معن عنك نكم الي يوم الق لقي قيم يمه ل ريب فيه ومن اصد صدق من الل لله حدي ديث');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (581, 'quran:4:88', 'quran', 'quran', '4:88', 88, 580, 'An-Nisa', 'النساء', 'فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا', NULL, NULL, 'فما لكم في المنفقين فيتين والله اركسهم بما كسبوا اتريدون ان تهدوا من اضل الله ومن يضلل الله فلن تجد له سبيلا', 'فم لكم في منفق يت له اركس بم كسب اتريد ان تهد من اضل له ومن يضلل له فلن تجد له سبيل', 'quran', NULL, NULL, 'https://quran.com/4/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (581, 'فم لكم في الم لمن منف نفق فقي قين فيت يتي تين ولل لله ارك ركس كسه سهم بم كسب سبو اتر تري ريد يدو دون ان تهد هدو من اضل الل لله ومن يضل ضلل الل لله فلن تجد له سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (582, 'quran:4:89', 'quran', 'quran', '4:89', 89, 581, 'An-Nisa', 'النساء', 'وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا', NULL, NULL, 'ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم اولياء حتي يهاجروا في سبيل الله فان تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا', 'دو لو تكفر كم كفر تكون سوء فل تتخذ من اوليء حت يهجر في سبيل له فن تول خذو اقتلو حيث جدتمو ول تتخذ من لي ول نصير', 'quran', NULL, NULL, 'https://quran.com/4/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (582, 'ودو لو تكف كفر فرو رون كم كفر فرو فتك تكو كون ونو نون سوء فل تتخ تخذ خذو منه نهم اول ولي ليء حتي يهج هجر جرو في سبي بيل الل لله فن تول ولو فخذ خذو ذوه وهم وقت قتل تلو لوه وهم حيث وجد جدت دتم تمو موه وهم ول تتخ تخذ خذو منه نهم ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (583, 'quran:4:90', 'quran', 'quran', '4:90', 90, 582, 'An-Nisa', 'النساء', 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا', NULL, NULL, 'الا الذين يصلون الي قوم بينكم وبينهم ميثق او جاءوكم حصرت صدورهم ان يقتلوكم او يقتلوا قومهم ولو شاء الله لسلطهم عليكم فلقتلوكم فان اعتزلوكم فلم يقتلوكم والقوا اليكم السلم فما جعل الله لكم عليهم سبيلا', 'ال ذين يصل ال قوم بين بين ميثق او جءو حصرت صدور ان يقتلو او يقتل قوم ولو شء له لسلط علي لقتلو فن اعتزلو فلم يقتلو قو يكم سلم فم جعل له لكم علي سبيل', 'quran', NULL, NULL, 'https://quran.com/4/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (583, 'ال الذ لذي ذين يصل صلو لون الي قوم بين ينك نكم وبي بين ينه نهم ميث يثق او جءو ءوك وكم حصر صرت صدو دور وره رهم ان يقت قتل تلو لوك وكم او يقت قتل تلو قوم ومه مهم ولو شء الل لله لسل سلط لطه طهم علي ليك يكم فلق لقت قتل تلو لوك وكم فن اعت عتز تزل زلو لوك وكم فلم يقت قتل تلو لوك وكم ولق لقو الي ليك يكم الس لسل سلم فم جعل الل لله لكم علي ليه يهم سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (584, 'quran:4:91', 'quran', 'quran', '4:91', 91, 583, 'An-Nisa', 'النساء', 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا', NULL, NULL, 'ستجدون اخرين يريدون ان يامنوكم ويامنوا قومهم كل ما ردوا الي الفتنه اركسوا فيها فان لم يعتزلوكم ويلقوا اليكم السلم ويكفوا ايديهم فخذوهم واقتلوهم حيث ثقفتموهم واوليكم جعلنا لكم عليهم سلطنا مبينا', 'ستجد اخر يريد ان يمنو يمن قوم كل م رد ال فتن اركس يه فن لم يعتزلو يلق يكم سلم يكف ايدي خذو اقتلو حيث ثقفتمو اولي جعل لكم علي سلط مبي', 'quran', NULL, NULL, 'https://quran.com/4/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (584, 'ستج تجد جدو دون اخر خري رين يري ريد يدو دون ان يمن منو نوك وكم ويم يمن منو قوم ومه مهم كل م ردو الي الف لفت فتن تنه ارك ركس كسو فيه فن لم يعت عتز تزل زلو لوك وكم ويل يلق لقو الي ليك يكم الس لسل سلم ويك يكف كفو ايد يدي ديه يهم فخذ خذو ذوه وهم وقت قتل تلو لوه وهم حيث ثقف قفت فتم تمو موه وهم وول ولي ليك يكم جعل علن لكم علي ليه يهم سلط لطن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (585, 'quran:4:92', 'quran', 'quran', '4:92', 92, 584, 'An-Nisa', 'النساء', 'وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', NULL, NULL, 'وما كان لمومن ان يقتل مومنا الا خطا ومن قتل مومنا خطا فتحرير رقبه مومنه وديه مسلمه الي اهله الا ان يصدقوا فان كان من قوم عدو لكم وهو مومن فتحرير رقبه مومنه وان كان من قوم بينكم وبينهم ميثق فديه مسلمه الي اهله وتحرير رقبه مومنه فمن لم يجد فصيام شهرين متتابعين توبه من الله وكان الله عليما حكيما', 'وم كن لمومن ان يقتل موم ال خط ومن قتل موم خط تحرير رقب مومن دي مسلم ال اهل ال ان يصدق فن كن من قوم عدو لكم وهو مومن تحرير رقب مومن ون كن من قوم بين بين ميثق دي مسلم ال اهل تحرير رقب مومن فمن لم يجد صيم شهر متتبع توب من له كن له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (585, 'وم كن لمو موم ومن ان يقت قتل موم ومن ال خط ومن قتل موم ومن خط فتح تحر حري رير رقب قبه موم ومن منه ودي ديه مسل سلم لمه الي اهل هله ال ان يصد صدق دقو فن كن من قوم عدو لكم وهو موم ومن فتح تحر حري رير رقب قبه موم ومن منه ون كن من قوم بين ينك نكم وبي بين ينه نهم ميث يثق فدي ديه مسل سلم لمه الي اهل هله وتح تحر حري رير رقب قبه موم ومن منه فمن لم يجد فصي صيم شهر هري رين متت تتب تبع بعي عين توب وبه من الل لله وكن الل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (586, 'quran:4:93', 'quran', 'quran', '4:93', 93, 585, 'An-Nisa', 'النساء', 'وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا', NULL, NULL, 'ومن يقتل مومنا متعمدا فجزاوه جهنم خلدا فيها وغضب الله عليه ولعنه واعد له عذابا عظيما', 'ومن يقتل موم متعمد جزو جهنم خلد يه غضب له عل لعن اعد له عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/4/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (586, 'ومن يقت قتل موم ومن متع تعم عمد فجز جزو زوه جهن هنم خلد فيه وغض غضب الل لله علي ليه ولع لعن عنه وعد له عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (587, 'quran:4:94', 'quran', 'quran', '4:94', 94, 586, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', NULL, NULL, 'يا ايها الذين امنوا اذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن القي اليكم السلم لست مومنا تبتغون عرض الحياه الدنيا فعند الله مغانم كثيره كذلك كنتم من قبل فمن الله عليكم فتبينوا ان الله كان بما تعملون خبيرا', 'ي اي ذين امن اذ ضربتم في سبيل له تبين ول تقول لمن قي يكم سلم لست موم تبتغ عرض حي دني عند له مغنم كثير كذلك كنتم من قبل فمن له علي تبين ان له كن بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/4/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (587, 'ي ايه الذ لذي ذين امن منو اذ ضرب ربت بتم في سبي بيل الل لله فتب تبي بين ينو ول تقو قول ولو لمن الق لقي الي ليك يكم الس لسل سلم لست موم ومن تبت بتغ تغو غون عرض الح لحي حيه الد لدن دني فعن عند الل لله مغن غنم كثي ثير يره كذل ذلك كنت نتم من قبل فمن الل لله علي ليك يكم فتب تبي بين ينو ان الل لله كن بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (588, 'quran:4:95', 'quran', 'quran', '4:95', 95, 587, 'An-Nisa', 'النساء', 'لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا', NULL, NULL, 'لا يستوي القعدون من المومنين غير اولي الضرر والمجهدون في سبيل الله بامولهم وانفسهم فضل الله المجهدين بامولهم وانفسهم علي القعدين درجه وكلا وعد الله الحسني وفضل الله المجهدين علي القعدين اجرا عظيما', 'ل يستو قعد من مومن غير اول ضرر مجهد في سبيل له بمول انفس فضل له مجهد بمول انفس عل قعد درج كل وعد له حسن فضل له مجهد عل قعد اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (588, 'ل يست ستو توي الق لقع قعد عدو دون من الم لمو موم ومن مني نين غير اول ولي الض لضر ضرر ولم لمج مجه جهد هدو دون في سبي بيل الل لله بمو مول وله لهم ونف نفس فسه سهم فضل الل لله الم لمج مجه جهد هدي دين بمو مول وله لهم ونف نفس فسه سهم علي الق لقع قعد عدي دين درج رجه وكل وعد الل لله الح لحس حسن سني وفض فضل الل لله الم لمج مجه جهد هدي دين علي الق لقع قعد عدي دين اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (589, 'quran:4:96', 'quran', 'quran', '4:96', 96, 588, 'An-Nisa', 'النساء', 'دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا', NULL, NULL, 'درجت منه ومغفره ورحمه وكان الله غفورا رحيما', 'درجت من مغفر رحم كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (589, 'درج رجت منه ومغ مغف غفر فره ورح رحم حمه وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (590, 'quran:4:97', 'quran', 'quran', '4:97', 97, 589, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا', NULL, NULL, 'ان الذين توفاهم المليكه ظالمي انفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الارض قالوا الم تكن ارض الله وسعه فتهاجروا فيها فاوليك ماواهم جهنم وساءت مصيرا', 'ان ذين توف مليك ظلم انفس قل فيم كنتم قل كن مستضعف في ارض قل الم تكن ارض له سع تهجر يه اوليك مو جهنم سءت مصير', 'quran', NULL, NULL, 'https://quran.com/4/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (590, 'ان الذ لذي ذين توف وفه فهم الم لمل ملي ليك يكه ظلم لمي انف نفس فسه سهم قلو فيم كنت نتم قلو كن مست ستض تضع ضعف عفي فين في الر لرض قلو الم تكن ارض الل لله وسع سعه فته تهج هجر جرو فيه فول ولي ليك موه وهم جهن هنم وسء سءت مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (591, 'quran:4:98', 'quran', 'quran', '4:98', 98, 590, 'An-Nisa', 'النساء', 'إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا', NULL, NULL, 'الا المستضعفين من الرجال والنساء والولدن لا يستطيعون حيله ولا يهتدون سبيلا', 'ال مستضعف من رجل نسء ولدن ل يستطيع حيل ول يهتد سبيل', 'quran', NULL, NULL, 'https://quran.com/4/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (591, 'ال الم لمس مست ستض تضع ضعف عفي فين من الر لرج رجل ولن لنس نسء ولو لول ولد لدن ل يست ستط تطي طيع يعو عون حيل يله ول يهت هتد تدو دون سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (592, 'quran:4:99', 'quran', 'quran', '4:99', 99, 591, 'An-Nisa', 'النساء', 'فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا', NULL, NULL, 'فاوليك عسي الله ان يعفو عنهم وكان الله عفوا غفورا', 'اوليك عس له ان يعفو عن كن له عف غفور', 'quran', NULL, NULL, 'https://quran.com/4/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (592, 'فول ولي ليك عسي الل لله ان يعف عفو عنه نهم وكن الل لله عفو غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (593, 'quran:4:100', 'quran', 'quran', '4:100', 100, 592, 'An-Nisa', 'النساء', 'وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'ومن يهاجر في سبيل الله يجد في الارض مرغما كثيرا وسعه ومن يخرج من بيته مهاجرا الي الله ورسوله ثم يدركه الموت فقد وقع اجره علي الله وكان الله غفورا رحيما', 'ومن يهجر في سبيل له يجد في ارض مرغم كثير سع ومن يخرج من بيت مهجر ال له رسول ثم يدرك موت فقد وقع اجر عل له كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (593, 'ومن يهج هجر في سبي بيل الل لله يجد في الر لرض مرغ رغم كثي ثير وسع سعه ومن يخر خرج من بيت يته مهج هجر الي الل لله ورس رسو سول وله ثم يدر درك ركه الم لمو موت فقد وقع اجر جره علي الل لله وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (594, 'quran:4:101', 'quran', 'quran', '4:101', 101, 593, 'An-Nisa', 'النساء', 'وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا', NULL, NULL, 'واذا ضربتم في الارض فليس عليكم جناح ان تقصروا من الصلاه ان خفتم ان يفتنكم الذين كفروا ان الكفرين كانوا لكم عدوا مبينا', 'اذ ضربتم في ارض ليس علي جنح ان تقصر من صل ان خفتم ان يفتن ذين كفر ان كفر كن لكم عد مبي', 'quran', NULL, NULL, 'https://quran.com/4/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (594, 'وذ ضرب ربت بتم في الر لرض فلي ليس علي ليك يكم جنح ان تقص قصر صرو من الص لصل صله ان خفت فتم ان يفت فتن تنك نكم الذ لذي ذين كفر فرو ان الك لكف كفر فري رين كنو لكم عدو مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (595, 'quran:4:102', 'quran', 'quran', '4:102', 102, 594, 'An-Nisa', 'النساء', 'وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', NULL, NULL, 'واذا كنت فيهم فاقمت لهم الصلاه فلتقم طايفه منهم معك ولياخذوا اسلحتهم فاذا سجدوا فليكونوا من ورايكم ولتات طايفه اخري لم يصلوا فليصلوا معك ولياخذوا حذرهم واسلحتهم ود الذين كفروا لو تغفلون عن اسلحتكم وامتعتكم فيميلون عليكم ميله وحده ولا جناح عليكم ان كان بكم اذي من مطر او كنتم مرضي ان تضعوا اسلحتكم وخذوا حذركم ان الله اعد للكفرين عذابا مهينا', 'اذ كنت يهم اقمت لهم صل لتقم طيف من معك ليخذ اسلحت اذ سجد ليكون من ري لت طيف اخر لم يصل ليصل معك ليخذ حذر اسلحت ود ذين كفر لو تغفل عن اسلحت امتعت يميل علي ميل حد ول جنح علي ان كن بكم اذ من مطر او كنتم مرض ان تضع اسلحت خذ حذر ان له اعد كفر عذب مهي', 'quran', NULL, NULL, 'https://quran.com/4/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (595, 'وذ كنت فيه يهم فقم قمت لهم الص لصل صله فلت لتق تقم طيف يفه منه نهم معك ولي ليخ يخذ خذو اسل سلح لحت حته تهم فذ سجد جدو فلي ليك يكو كون ونو من وري ريك يكم ولت لتت طيف يفه اخر خري لم يصل صلو فلي ليص يصل صلو معك ولي ليخ يخذ خذو حذر ذره رهم وسل سلح لحت حته تهم ود الذ لذي ذين كفر فرو لو تغف غفل فلو لون عن اسل سلح لحت حتك تكم ومت متع تعت عتك تكم فيم يمي ميل يلو لون علي ليك يكم ميل يله وحد حده ول جنح علي ليك يكم ان كن بكم اذي من مطر او كنت نتم مرض رضي ان تضع ضعو اسل سلح لحت حتك تكم وخذ خذو حذر ذرك ركم ان الل لله اعد للك لكف كفر فري رين عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (596, 'quran:4:103', 'quran', 'quran', '4:103', 103, 595, 'An-Nisa', 'النساء', 'فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا', NULL, NULL, 'فاذا قضيتم الصلاه فاذكروا الله قيما وقعودا وعلي جنوبكم فاذا اطماننتم فاقيموا الصلاه ان الصلاه كانت علي المومنين كتبا موقوتا', 'اذ قضيتم صل اذكر له قيم قعود عل جنوب اذ اطمننتم اقيم صل ان صل كنت عل مومن كتب موقوت', 'quran', NULL, NULL, 'https://quran.com/4/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (596, 'فذ قضي ضيت يتم الص لصل صله فذك ذكر كرو الل لله قيم وقع قعو عود وعل علي جنو نوب وبك بكم فذ اطم طمن منن ننت نتم فقي قيم يمو الص لصل صله ان الص لصل صله كنت علي الم لمو موم ومن مني نين كتب موق وقو قوت');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (597, 'quran:4:104', 'quran', 'quran', '4:104', 104, 596, 'An-Nisa', 'النساء', 'وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', NULL, NULL, 'ولا تهنوا في ابتغاء القوم ان تكونوا تالمون فانهم يالمون كما تالمون وترجون من الله ما لا يرجون وكان الله عليما حكيما', 'ول تهن في ابتغء قوم ان تكون تلم ان يلم كم تلم ترج من له م ل يرج كن له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (597, 'ول تهن هنو في ابت بتغ تغء الق لقو قوم ان تكو كون ونو تلم لمو مون فنه نهم يلم لمو مون كم تلم لمو مون وتر ترج رجو جون من الل لله م ل يرج رجو جون وكن الل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (598, 'quran:4:105', 'quran', 'quran', '4:105', 105, 597, 'An-Nisa', 'النساء', 'إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا', NULL, NULL, 'انا انزلنا اليك الكتب بالحق لتحكم بين الناس بما اراك الله ولا تكن للخاينين خصيما', 'ان انزل يك كتب حق لتح بين نس بم ارك له ول تكن خين خصيم', 'quran', NULL, NULL, 'https://quran.com/4/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (598, 'ان انز نزل زلن الي ليك الك لكت كتب بلح لحق لتح تحك حكم بين الن لنس بم ارك الل لله ول تكن للخ لخي خين يني نين خصي صيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (599, 'quran:4:106', 'quran', 'quran', '4:106', 106, 598, 'An-Nisa', 'النساء', 'وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'واستغفر الله ان الله كان غفورا رحيما', 'استغفر له ان له كن غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (599, 'وست ستغ تغف غفر الل لله ان الل لله كن غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (600, 'quran:4:107', 'quran', 'quran', '4:107', 107, 599, 'An-Nisa', 'النساء', 'وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا', NULL, NULL, 'ولا تجدل عن الذين يختانون انفسهم ان الله لا يحب من كان خوانا اثيما', 'ول تجدل عن ذين يختن انفس ان له ل يحب من كن خو اثيم', 'quran', NULL, NULL, 'https://quran.com/4/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (600, 'ول تجد جدل عن الذ لذي ذين يخت ختن تنو نون انف نفس فسه سهم ان الل لله ل يحب من كن خون اثي ثيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (601, 'quran:4:108', 'quran', 'quran', '4:108', 108, 600, 'An-Nisa', 'النساء', 'يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا', NULL, NULL, 'يستخفون من الناس ولا يستخفون من الله وهو معهم اذ يبيتون ما لا يرضي من القول وكان الله بما يعملون محيطا', 'يستخف من نس ول يستخف من له وهو مع اذ يبيت م ل يرض من قول كن له بم يعمل محيط', 'quran', NULL, NULL, 'https://quran.com/4/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (601, 'يست ستخ تخف خفو فون من الن لنس ول يست ستخ تخف خفو فون من الل لله وهو معه عهم اذ يبي بيت يتو تون م ل يرض رضي من الق لقو قول وكن الل لله بم يعم عمل ملو لون محي حيط');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (602, 'quran:4:109', 'quran', 'quran', '4:109', 109, 601, 'An-Nisa', 'النساء', 'هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا', NULL, NULL, 'هانتم هولاء جدلتم عنهم في الحياه الدنيا فمن يجدل الله عنهم يوم القيمه ام من يكون عليهم وكيلا', 'هنتم هولء جدلتم عن في حي دني فمن يجدل له عن يوم قيم ام من يك علي كيل', 'quran', NULL, NULL, 'https://quran.com/4/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (602, 'هنت نتم هول ولء جدل دلت لتم عنه نهم في الح لحي حيه الد لدن دني فمن يجد جدل الل لله عنه نهم يوم الق لقي قيم يمه ام من يكو كون علي ليه يهم وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (603, 'quran:4:110', 'quran', 'quran', '4:110', 110, 602, 'An-Nisa', 'النساء', 'وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'ومن يعمل سوا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما', 'ومن يعمل سو او يظلم نفس ثم يستغفر له يجد له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (603, 'ومن يعم عمل سو او يظل ظلم نفس فسه ثم يست ستغ تغف غفر الل لله يجد الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (604, 'quran:4:111', 'quran', 'quran', '4:111', 111, 603, 'An-Nisa', 'النساء', 'وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', NULL, NULL, 'ومن يكسب اثما فانما يكسبه علي نفسه وكان الله عليما حكيما', 'ومن يكسب اثم انم يكسب عل نفس كن له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (604, 'ومن يكس كسب اثم فنم يكس كسب سبه علي نفس فسه وكن الل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (605, 'quran:4:112', 'quran', 'quran', '4:112', 112, 604, 'An-Nisa', 'النساء', 'وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا', NULL, NULL, 'ومن يكسب خطيه او اثما ثم يرم به بريا فقد احتمل بهتنا واثما مبينا', 'ومن يكسب خط او اثم ثم يرم به بري فقد احتمل بهت اثم مبي', 'quran', NULL, NULL, 'https://quran.com/4/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (605, 'ومن يكس كسب خطي طيه او اثم ثم يرم به بري فقد احت حتم تمل بهت هتن وثم مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (606, 'quran:4:113', 'quran', 'quran', '4:113', 113, 605, 'An-Nisa', 'النساء', 'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا', NULL, NULL, 'ولولا فضل الله عليك ورحمته لهمت طايفه منهم ان يضلوك وما يضلون الا انفسهم وما يضرونك من شيء وانزل الله عليك الكتب والحكمه وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما', 'لول فضل له عليك رحمت لهمت طيف من ان يضلوك وم يضل ال انفس وم يضرونك من شيء انزل له عليك كتب حكم علمك م لم تكن تعلم كن فضل له عليك عظيم', 'quran', NULL, NULL, 'https://quran.com/4/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (606, 'ولو لول فضل الل لله علي ليك ورح رحم حمت مته لهم همت طيف يفه منه نهم ان يضل ضلو لوك وم يضل ضلو لون ال انف نفس فسه سهم وم يضر ضرو رون ونك من شيء ونز نزل الل لله علي ليك الك لكت كتب ولح لحك حكم كمه وعل علم لمك م لم تكن تعل علم وكن فضل الل لله علي ليك عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (607, 'quran:4:114', 'quran', 'quran', '4:114', 114, 606, 'An-Nisa', 'النساء', 'لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا', NULL, NULL, 'لا خير في كثير من نجواهم الا من امر بصدقه او معروف او اصلح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نوتيه اجرا عظيما', 'ل خير في كثير من نجو ال من امر بصدق او معروف او اصلح بين نس ومن يفعل ذلك ابتغء مرض له سوف نوت اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (607, 'ل خير في كثي ثير من نجو جوه وهم ال من امر بصد صدق دقه او معر عرو روف او اصل صلح بين الن لنس ومن يفع فعل ذلك ابت بتغ تغء مرض رضت الل لله فسو سوف نوت وتي تيه اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (608, 'quran:4:115', 'quran', 'quran', '4:115', 115, 607, 'An-Nisa', 'النساء', 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا', NULL, NULL, 'ومن يشاقق الرسول من بعد ما تبين له الهدي ويتبع غير سبيل المومنين نوله ما تولي ونصله جهنم وساءت مصيرا', 'ومن يشقق رسول من بعد م تب له هد يتبع غير سبيل مومن نول م تول نصل جهنم سءت مصير', 'quran', NULL, NULL, 'https://quran.com/4/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (608, 'ومن يشق شقق الر لرس رسو سول من بعد م تبي بين له اله لهد هدي ويت يتب تبع غير سبي بيل الم لمو موم ومن مني نين نول وله م تول ولي ونص نصل صله جهن هنم وسء سءت مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (609, 'quran:4:116', 'quran', 'quran', '4:116', 116, 608, 'An-Nisa', 'النساء', 'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا', NULL, NULL, 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضللا بعيدا', 'ان له ل يغفر ان يشرك به يغفر م دون ذلك لمن يشء ومن يشرك له فقد ضل ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/4/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (609, 'ان الل لله ل يغف غفر ان يشر شرك به ويغ يغف غفر م دون ذلك لمن يشء ومن يشر شرك بلل لله فقد ضل ضلل بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (610, 'quran:4:117', 'quran', 'quran', '4:117', 117, 609, 'An-Nisa', 'النساء', 'إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا', NULL, NULL, 'ان يدعون من دونه الا انثا وان يدعون الا شيطنا مريدا', 'ان يدع من دون ال انث ون يدع ال شيط مريد', 'quran', NULL, NULL, 'https://quran.com/4/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (610, 'ان يدع دعو عون من دون ونه ال انث ون يدع دعو عون ال شيط يطن مري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (611, 'quran:4:118', 'quran', 'quran', '4:118', 118, 610, 'An-Nisa', 'النساء', 'لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا', NULL, NULL, 'لعنه الله وقال لاتخذن من عبادك نصيبا مفروضا', 'لعن له قل لتخذن من عبدك نصيب مفروض', 'quran', NULL, NULL, 'https://quran.com/4/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (611, 'لعن عنه الل لله وقل لتخ تخذ خذن من عبد بدك نصي صيب مفر فرو روض');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (612, 'quran:4:119', 'quran', 'quran', '4:119', 119, 611, 'An-Nisa', 'النساء', 'وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا', NULL, NULL, 'ولاضلنهم ولامنينهم ولامرنهم فليبتكن اذان الانعم ولامرنهم فليغيرن خلق الله ومن يتخذ الشيطن وليا من دون الله فقد خسر خسرانا مبينا', 'لضلن لمنين لمرن ليبتكن اذ انعم لمرن ليغيرن خلق له ومن يتخذ شيطن لي من دون له فقد خسر خسر مبي', 'quran', NULL, NULL, 'https://quran.com/4/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (612, 'ولض لضل ضلن لنه نهم ولم لمن مني نين ينه نهم ولم لمر مرن رنه نهم فلي ليب يبت بتك تكن اذن الن لنع نعم ولم لمر مرن رنه نهم فلي ليغ يغي غير يرن خلق الل لله ومن يتخ تخذ الش لشي شيط يطن ولي من دون الل لله فقد خسر خسر سرن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (613, 'quran:4:120', 'quran', 'quran', '4:120', 120, 612, 'An-Nisa', 'النساء', 'يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا', NULL, NULL, 'يعدهم ويمنيهم وما يعدهم الشيطن الا غرورا', 'يعد يمني وم يعد شيطن ال غرور', 'quran', NULL, NULL, 'https://quran.com/4/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (613, 'يعد عده دهم ويم يمن مني نيه يهم وم يعد عده دهم الش لشي شيط يطن ال غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (614, 'quran:4:121', 'quran', 'quran', '4:121', 121, 613, 'An-Nisa', 'النساء', 'أُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا', NULL, NULL, 'اوليك ماواهم جهنم ولا يجدون عنها محيصا', 'اوليك مو جهنم ول يجد عن محيص', 'quran', NULL, NULL, 'https://quran.com/4/121');
INSERT INTO units_tri_src (id, ar_tri) VALUES (614, 'اول ولي ليك موه وهم جهن هنم ول يجد جدو دون عنه محي حيص');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (615, 'quran:4:122', 'quran', 'quran', '4:122', 122, 614, 'An-Nisa', 'النساء', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا', NULL, NULL, 'والذين امنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا وعد الله حقا ومن اصدق من الله قيلا', 'ذين امن عمل صلحت سندخل جنت تجر من تحت انهر خلد يه ابد وعد له حق ومن اصدق من له قيل', 'quran', NULL, NULL, 'https://quran.com/4/122');
INSERT INTO units_tri_src (id, ar_tri) VALUES (615, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت سند ندخ دخل خله لهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ابد وعد الل لله حق ومن اصد صدق من الل لله قيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (616, 'quran:4:123', 'quran', 'quran', '4:123', 123, 615, 'An-Nisa', 'النساء', 'لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا', NULL, NULL, 'ليس بامانيكم ولا اماني اهل الكتب من يعمل سوا يجز به ولا يجد له من دون الله وليا ولا نصيرا', 'ليس بمني ول امن اهل كتب من يعمل سو يجز به ول يجد له من دون له لي ول نصير', 'quran', NULL, NULL, 'https://quran.com/4/123');
INSERT INTO units_tri_src (id, ar_tri) VALUES (616, 'ليس بمن مني نيك يكم ول امن مني اهل الك لكت كتب من يعم عمل سو يجز به ول يجد له من دون الل لله ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (617, 'quran:4:124', 'quran', 'quran', '4:124', 124, 616, 'An-Nisa', 'النساء', 'وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا', NULL, NULL, 'ومن يعمل من الصلحت من ذكر او انثي وهو مومن فاوليك يدخلون الجنه ولا يظلمون نقيرا', 'ومن يعمل من صلحت من ذكر او انث وهو مومن اوليك يدخل جن ول يظلم نقير', 'quran', NULL, NULL, 'https://quran.com/4/124');
INSERT INTO units_tri_src (id, ar_tri) VALUES (617, 'ومن يعم عمل من الص لصل صلح لحت من ذكر او انث نثي وهو موم ومن فول ولي ليك يدخ دخل خلو لون الج لجن جنه ول يظل ظلم لمو مون نقي قير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (618, 'quran:4:125', 'quran', 'quran', '4:125', 125, 617, 'An-Nisa', 'النساء', 'وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا', NULL, NULL, 'ومن احسن دينا ممن اسلم وجهه لله وهو محسن واتبع مله ابرهيم حنيفا واتخذ الله ابرهيم خليلا', 'ومن احسن دي ممن اسلم جه لل وهو محسن اتبع مل ابرهيم حنيف اتخذ له ابرهيم خليل', 'quran', NULL, NULL, 'https://quran.com/4/125');
INSERT INTO units_tri_src (id, ar_tri) VALUES (618, 'ومن احس حسن دين ممن اسل سلم وجه جهه لله وهو محس حسن وتب تبع مله ابر بره رهي هيم حني نيف وتخ تخذ الل لله ابر بره رهي هيم خلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (619, 'quran:4:126', 'quran', 'quran', '4:126', 126, 618, 'An-Nisa', 'النساء', 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا', NULL, NULL, 'ولله ما في السموت وما في الارض وكان الله بكل شيء محيطا', 'لل م في سموت وم في ارض كن له بكل شيء محيط', 'quran', NULL, NULL, 'https://quran.com/4/126');
INSERT INTO units_tri_src (id, ar_tri) VALUES (619, 'ولل لله م في الس لسم سمو موت وم في الر لرض وكن الل لله بكل شيء محي حيط');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (620, 'quran:4:127', 'quran', 'quran', '4:127', 127, 619, 'An-Nisa', 'النساء', 'وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا', NULL, NULL, 'ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلي عليكم في الكتب في يتمي النساء التي لا توتونهن ما كتب لهن وترغبون ان تنكحوهن والمستضعفين من الولدن وان تقوموا لليتمي بالقسط وما تفعلوا من خير فان الله كان به عليما', 'يستفتونك في نسء قل له يفتي يهن وم يتل علي في كتب في يتم نسء تي ل توتون م كتب لهن ترغب ان تنكحو مستضعف من ولدن ون تقوم يتم قسط وم تفعل من خير فن له كن به عليم', 'quran', NULL, NULL, 'https://quran.com/4/127');
INSERT INTO units_tri_src (id, ar_tri) VALUES (620, 'ويس يست ستف تفت فتو تون ونك في الن لنس نسء قل الل لله يفت فتي تيك يكم فيه يهن وم يتل تلي علي ليك يكم في الك لكت كتب في يتم تمي الن لنس نسء الت لتي ل توت وتو تون ونه نهن م كتب لهن وتر ترغ رغب غبو بون ان تنك نكح كحو حوه وهن ولم لمس مست ستض تضع ضعف عفي فين من الو لول ولد لدن ون تقو قوم ومو للي ليت يتم تمي بلق لقس قسط وم تفع فعل علو من خير فن الل لله كن به علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (621, 'quran:4:128', 'quran', 'quran', '4:128', 128, 620, 'An-Nisa', 'النساء', 'وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', NULL, NULL, 'وان امراه خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير واحضرت الانفس الشح وان تحسنوا وتتقوا فان الله كان بما تعملون خبيرا', 'ون امر خفت من بعل نشوز او اعرض فل جنح عليهم ان يصلح بينهم صلح صلح خير احضرت انفس شح ون تحسن تتق فن له كن بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/4/128');
INSERT INTO units_tri_src (id, ar_tri) VALUES (621, 'ون امر مره خفت من بعل عله نشو شوز او اعر عرض فل جنح علي ليه يهم ان يصل صلح بين ينه نهم صلح ولص لصل صلح خير وحض حضر ضرت الن لنف نفس الش لشح ون تحس حسن سنو وتت تتق تقو فن الل لله كن بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (622, 'quran:4:129', 'quran', 'quran', '4:129', 129, 621, 'An-Nisa', 'النساء', 'وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقه وان تصلحوا وتتقوا فان الله كان غفورا رحيما', 'ولن تستطيع ان تعدل بين نسء ولو حرصتم فل تميل كل ميل تذرو معلق ون تصلح تتق فن له كن غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/129');
INSERT INTO units_tri_src (id, ar_tri) VALUES (622, 'ولن تست ستط تطي طيع يعو ان تعد عدل دلو بين الن لنس نسء ولو حرص رصت صتم فل تمي ميل يلو كل الم لمي ميل فتذ تذر ذرو روه كلم لمع معل علق لقه ون تصل صلح لحو وتت تتق تقو فن الل لله كن غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (623, 'quran:4:130', 'quran', 'quran', '4:130', 130, 622, 'An-Nisa', 'النساء', 'وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا', NULL, NULL, 'وان يتفرقا يغن الله كلا من سعته وكان الله وسعا حكيما', 'ون يتفرق يغن له كل من سعت كن له سع حكيم', 'quran', NULL, NULL, 'https://quran.com/4/130');
INSERT INTO units_tri_src (id, ar_tri) VALUES (623, 'ون يتف تفر فرق يغن الل لله كل من سعت عته وكن الل لله وسع حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (624, 'quran:4:131', 'quran', 'quran', '4:131', 131, 623, 'An-Nisa', 'النساء', 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا', NULL, NULL, 'ولله ما في السموت وما في الارض ولقد وصينا الذين اوتوا الكتب من قبلكم واياكم ان اتقوا الله وان تكفروا فان لله ما في السموت وما في الارض وكان الله غنيا حميدا', 'لل م في سموت وم في ارض لقد صي ذين اوت كتب من قبل اي ان اتق له ون تكفر فن لل م في سموت وم في ارض كن له غني حميد', 'quran', NULL, NULL, 'https://quran.com/4/131');
INSERT INTO units_tri_src (id, ar_tri) VALUES (624, 'ولل لله م في الس لسم سمو موت وم في الر لرض ولق لقد وصي صين الذ لذي ذين اوت وتو الك لكت كتب من قبل بلك لكم ويك يكم ان اتق تقو الل لله ون تكف كفر فرو فن لله م في الس لسم سمو موت وم في الر لرض وكن الل لله غني حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (625, 'quran:4:132', 'quran', 'quran', '4:132', 132, 624, 'An-Nisa', 'النساء', 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', NULL, NULL, 'ولله ما في السموت وما في الارض وكفي بالله وكيلا', 'لل م في سموت وم في ارض كف له كيل', 'quran', NULL, NULL, 'https://quran.com/4/132');
INSERT INTO units_tri_src (id, ar_tri) VALUES (625, 'ولل لله م في الس لسم سمو موت وم في الر لرض وكف كفي بلل لله وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (626, 'quran:4:133', 'quran', 'quran', '4:133', 133, 625, 'An-Nisa', 'النساء', 'إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا', NULL, NULL, 'ان يشا يذهبكم ايها الناس ويات باخرين وكان الله علي ذلك قديرا', 'ان يش يذهب اي نس يت بخر كن له عل ذلك قدير', 'quran', NULL, NULL, 'https://quran.com/4/133');
INSERT INTO units_tri_src (id, ar_tri) VALUES (626, 'ان يش يذه ذهب هبك بكم ايه الن لنس ويت بخر خري رين وكن الل لله علي ذلك قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (627, 'quran:4:134', 'quran', 'quran', '4:134', 134, 626, 'An-Nisa', 'النساء', 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا', NULL, NULL, 'من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والاخره وكان الله سميعا بصيرا', 'من كن يريد ثوب دني عند له ثوب دني اخر كن له سميع بصير', 'quran', NULL, NULL, 'https://quran.com/4/134');
INSERT INTO units_tri_src (id, ar_tri) VALUES (627, 'من كن يري ريد ثوب الد لدن دني فعن عند الل لله ثوب الد لدن دني ولخ لخر خره وكن الل لله سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (628, 'quran:4:135', 'quran', 'quran', '4:135', 135, 627, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', NULL, NULL, 'يا ايها الذين امنوا كونوا قومين بالقسط شهداء لله ولو علي انفسكم او الولدين والاقربين ان يكن غنيا او فقيرا فالله اولي بهما فلا تتبعوا الهوي ان تعدلوا وان تلوا او تعرضوا فان الله كان بما تعملون خبيرا', 'ي اي ذين امن كون قوم قسط شهدء لل ولو عل انفس او ولد اقرب ان يكن غني او قير له اول بهم فل تتبع هو ان تعدل ون تل او تعرض فن له كن بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/4/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (628, 'ي ايه الذ لذي ذين امن منو كون ونو قوم ومي مين بلق لقس قسط شهد هدء لله ولو علي انف نفس فسك سكم او الو لول ولد لدي دين ولق لقر قرب ربي بين ان يكن غني او فقي قير فلل لله اول ولي بهم فل تتب تبع بعو اله لهو هوي ان تعد عدل دلو ون تلو او تعر عرض رضو فن الل لله كن بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (629, 'quran:4:136', 'quran', 'quran', '4:136', 136, 628, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا', NULL, NULL, 'يا ايها الذين امنوا امنوا بالله ورسوله والكتب الذي نزل علي رسوله والكتب الذي انزل من قبل ومن يكفر بالله ومليكته وكتبه ورسله واليوم الاخر فقد ضل ضللا بعيدا', 'ي اي ذين امن امن له رسول كتب ذي نزل عل رسول كتب ذي انزل من قبل ومن يكفر له مليكت كتب رسل يوم اخر فقد ضل ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/4/136');
INSERT INTO units_tri_src (id, ar_tri) VALUES (629, 'ي ايه الذ لذي ذين امن منو امن منو بلل لله ورس رسو سول وله ولك لكت كتب الذ لذي نزل علي رسو سول وله ولك لكت كتب الذ لذي انز نزل من قبل ومن يكف كفر بلل لله ومل ملي ليك يكت كته وكت كتب تبه ورس رسل سله ولي ليو يوم الخ لخر فقد ضل ضلل بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (630, 'quran:4:137', 'quran', 'quran', '4:137', 137, 629, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا', NULL, NULL, 'ان الذين امنوا ثم كفروا ثم امنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا', 'ان ذين امن ثم كفر ثم امن ثم كفر ثم ازدد كفر لم يكن له ليغفر لهم ول ليهدي سبيل', 'quran', NULL, NULL, 'https://quran.com/4/137');
INSERT INTO units_tri_src (id, ar_tri) VALUES (630, 'ان الذ لذي ذين امن منو ثم كفر فرو ثم امن منو ثم كفر فرو ثم ازد زدد ددو كفر لم يكن الل لله ليغ يغف غفر لهم ول ليه يهد هدي ديه يهم سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (631, 'quran:4:138', 'quran', 'quran', '4:138', 138, 630, 'An-Nisa', 'النساء', 'بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا', NULL, NULL, 'بشر المنفقين بان لهم عذابا اليما', 'بشر منفق بن لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/4/138');
INSERT INTO units_tri_src (id, ar_tri) VALUES (631, 'بشر الم لمن منف نفق فقي قين بن لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (632, 'quran:4:139', 'quran', 'quran', '4:139', 139, 631, 'An-Nisa', 'النساء', 'ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا', NULL, NULL, 'الذين يتخذون الكفرين اولياء من دون المومنين ايبتغون عندهم العزه فان العزه لله جميعا', 'ذين يتخذ كفر اوليء من دون مومن ايبتغ عند عز فن عز لل جميع', 'quran', NULL, NULL, 'https://quran.com/4/139');
INSERT INTO units_tri_src (id, ar_tri) VALUES (632, 'الذ لذي ذين يتخ تخذ خذو ذون الك لكف كفر فري رين اول ولي ليء من دون الم لمو موم ومن مني نين ايب يبت بتغ تغو غون عند نده دهم الع لعز عزه فن الع لعز عزه لله جمي ميع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (633, 'quran:4:140', 'quran', 'quran', '4:140', 140, 632, 'An-Nisa', 'النساء', 'وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا', NULL, NULL, 'وقد نزل عليكم في الكتب ان اذا سمعتم ايت الله يكفر بها ويستهزا بها فلا تقعدوا معهم حتي يخوضوا في حديث غيره انكم اذا مثلهم ان الله جامع المنفقين والكفرين في جهنم جميعا', 'وقد نزل علي في كتب ان اذ سمعتم ايت له يكفر به يستهز به فل تقعد مع حت يخوض في حديث غير ان اذ مثل ان له جمع منفق كفر في جهنم جميع', 'quran', NULL, NULL, 'https://quran.com/4/140');
INSERT INTO units_tri_src (id, ar_tri) VALUES (633, 'وقد نزل علي ليك يكم في الك لكت كتب ان اذ سمع معت عتم ايت الل لله يكف كفر به ويس يست سته تهز به فل تقع قعد عدو معه عهم حتي يخو خوض وضو في حدي ديث غير يره انك نكم اذ مثل ثله لهم ان الل لله جمع الم لمن منف نفق فقي قين ولك لكف كفر فري رين في جهن هنم جمي ميع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (634, 'quran:4:141', 'quran', 'quran', '4:141', 141, 633, 'An-Nisa', 'النساء', 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا', NULL, NULL, 'الذين يتربصون بكم فان كان لكم فتح من الله قالوا الم نكن معكم وان كان للكفرين نصيب قالوا الم نستحوذ عليكم ونمنعكم من المومنين فالله يحكم بينكم يوم القيمه ولن يجعل الله للكفرين علي المومنين سبيلا', 'ذين يتربص بكم فن كن لكم فتح من له قل الم نكن مع ون كن كفر نصيب قل الم نستحوذ علي نمنع من مومن له يح بين يوم قيم ولن يجعل له كفر عل مومن سبيل', 'quran', NULL, NULL, 'https://quran.com/4/141');
INSERT INTO units_tri_src (id, ar_tri) VALUES (634, 'الذ لذي ذين يتر ترب ربص بصو صون بكم فن كن لكم فتح من الل لله قلو الم نكن معك عكم ون كن للك لكف كفر فري رين نصي صيب قلو الم نست ستح تحو حوذ علي ليك يكم ونم نمن منع نعك عكم من الم لمو موم ومن مني نين فلل لله يحك حكم بين ينك نكم يوم الق لقي قيم يمه ولن يجع جعل الل لله للك لكف كفر فري رين علي الم لمو موم ومن مني نين سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (635, 'quran:4:142', 'quran', 'quran', '4:142', 142, 634, 'An-Nisa', 'النساء', 'إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا', NULL, NULL, 'ان المنفقين يخدعون الله وهو خدعهم واذا قاموا الي الصلاه قاموا كسالي يراءون الناس ولا يذكرون الله الا قليلا', 'ان منفق يخدع له وهو خدع اذ قم ال صل قم كسل يرء نس ول يذكر له ال قليل', 'quran', NULL, NULL, 'https://quran.com/4/142');
INSERT INTO units_tri_src (id, ar_tri) VALUES (635, 'ان الم لمن منف نفق فقي قين يخد خدع دعو عون الل لله وهو خدع دعه عهم وذ قمو الي الص لصل صله قمو كسل سلي يرء رءو ءون الن لنس ول يذك ذكر كرو رون الل لله ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (636, 'quran:4:143', 'quran', 'quran', '4:143', 143, 635, 'An-Nisa', 'النساء', 'مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا', NULL, NULL, 'مذبذبين بين ذلك لا الي هولاء ولا الي هولاء ومن يضلل الله فلن تجد له سبيلا', 'مذبذب بين ذلك ل ال هولء ول ال هولء ومن يضلل له فلن تجد له سبيل', 'quran', NULL, NULL, 'https://quran.com/4/143');
INSERT INTO units_tri_src (id, ar_tri) VALUES (636, 'مذب ذبذ بذب ذبي بين بين ذلك ل الي هول ولء ول الي هول ولء ومن يضل ضلل الل لله فلن تجد له سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (637, 'quran:4:144', 'quran', 'quran', '4:144', 144, 636, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا', NULL, NULL, 'يا ايها الذين امنوا لا تتخذوا الكفرين اولياء من دون المومنين اتريدون ان تجعلوا لله عليكم سلطنا مبينا', 'ي اي ذين امن ل تتخذ كفر اوليء من دون مومن اتريد ان تجعل لل علي سلط مبي', 'quran', NULL, NULL, 'https://quran.com/4/144');
INSERT INTO units_tri_src (id, ar_tri) VALUES (637, 'ي ايه الذ لذي ذين امن منو ل تتخ تخذ خذو الك لكف كفر فري رين اول ولي ليء من دون الم لمو موم ومن مني نين اتر تري ريد يدو دون ان تجع جعل علو لله علي ليك يكم سلط لطن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (638, 'quran:4:145', 'quran', 'quran', '4:145', 145, 637, 'An-Nisa', 'النساء', 'إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا', NULL, NULL, 'ان المنفقين في الدرك الاسفل من النار ولن تجد لهم نصيرا', 'ان منفق في درك اسفل من نر ولن تجد لهم نصير', 'quran', NULL, NULL, 'https://quran.com/4/145');
INSERT INTO units_tri_src (id, ar_tri) VALUES (638, 'ان الم لمن منف نفق فقي قين في الد لدر درك الس لسف سفل من الن لنر ولن تجد لهم نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (639, 'quran:4:146', 'quran', 'quran', '4:146', 146, 638, 'An-Nisa', 'النساء', 'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا', NULL, NULL, 'الا الذين تابوا واصلحوا واعتصموا بالله واخلصوا دينهم لله فاوليك مع المومنين وسوف يوت الله المومنين اجرا عظيما', 'ال ذين تب اصلح اعتصم له اخلص دين لل اوليك مع مومن سوف يوت له مومن اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/146');
INSERT INTO units_tri_src (id, ar_tri) VALUES (639, 'ال الذ لذي ذين تبو وصل صلح لحو وعت عتص تصم صمو بلل لله وخل خلص لصو دين ينه نهم لله فول ولي ليك مع الم لمو موم ومن مني نين وسو سوف يوت الل لله الم لمو موم ومن مني نين اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (640, 'quran:4:147', 'quran', 'quran', '4:147', 147, 639, 'An-Nisa', 'النساء', 'مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا', NULL, NULL, 'ما يفعل الله بعذابكم ان شكرتم وامنتم وكان الله شاكرا عليما', 'م يفعل له بعذب ان شكرتم امنتم كن له شكر عليم', 'quran', NULL, NULL, 'https://quran.com/4/147');
INSERT INTO units_tri_src (id, ar_tri) VALUES (640, 'م يفع فعل الل لله بعذ عذب ذبك بكم ان شكر كرت رتم ومن منت نتم وكن الل لله شكر علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (641, 'quran:4:148', 'quran', 'quran', '4:148', 148, 640, 'An-Nisa', 'النساء', 'لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', NULL, NULL, 'لا يحب الله الجهر بالسوء من القول الا من ظلم وكان الله سميعا عليما', 'ل يحب له جهر سوء من قول ال من ظلم كن له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/4/148');
INSERT INTO units_tri_src (id, ar_tri) VALUES (641, 'ل يحب الل لله الج لجه جهر بلس لسو سوء من الق لقو قول ال من ظلم وكن الل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (642, 'quran:4:149', 'quran', 'quran', '4:149', 149, 641, 'An-Nisa', 'النساء', 'إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا', NULL, NULL, 'ان تبدوا خيرا او تخفوه او تعفوا عن سوء فان الله كان عفوا قديرا', 'ان تبد خير او تخفو او تعف عن سوء فن له كن عف قدير', 'quran', NULL, NULL, 'https://quran.com/4/149');
INSERT INTO units_tri_src (id, ar_tri) VALUES (642, 'ان تبد بدو خير او تخف خفو فوه او تعف عفو عن سوء فن الل لله كن عفو قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (643, 'quran:4:150', 'quran', 'quran', '4:150', 150, 642, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا', NULL, NULL, 'ان الذين يكفرون بالله ورسله ويريدون ان يفرقوا بين الله ورسله ويقولون نومن ببعض ونكفر ببعض ويريدون ان يتخذوا بين ذلك سبيلا', 'ان ذين يكفر له رسل يريد ان يفرق بين له رسل يقول نومن ببعض نكفر ببعض يريد ان يتخذ بين ذلك سبيل', 'quran', NULL, NULL, 'https://quran.com/4/150');
INSERT INTO units_tri_src (id, ar_tri) VALUES (643, 'ان الذ لذي ذين يكف كفر فرو رون بلل لله ورس رسل سله وير يري ريد يدو دون ان يفر فرق رقو بين الل لله ورس رسل سله ويق يقو قول ولو لون نوم ومن ببع بعض ونك نكف كفر ببع بعض وير يري ريد يدو دون ان يتخ تخذ خذو بين ذلك سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (644, 'quran:4:151', 'quran', 'quran', '4:151', 151, 643, 'An-Nisa', 'النساء', 'أُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', NULL, NULL, 'اوليك هم الكفرون حقا واعتدنا للكفرين عذابا مهينا', 'اوليك هم كفر حق اعتد كفر عذب مهي', 'quran', NULL, NULL, 'https://quran.com/4/151');
INSERT INTO units_tri_src (id, ar_tri) VALUES (644, 'اول ولي ليك هم الك لكف كفر فرو رون حق وعت عتد تدن للك لكف كفر فري رين عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (645, 'quran:4:152', 'quran', 'quran', '4:152', 152, 644, 'An-Nisa', 'النساء', 'وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'والذين امنوا بالله ورسله ولم يفرقوا بين احد منهم اوليك سوف يوتيهم اجورهم وكان الله غفورا رحيما', 'ذين امن له رسل ولم يفرق بين احد من اوليك سوف يوتي اجور كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/4/152');
INSERT INTO units_tri_src (id, ar_tri) VALUES (645, 'ولذ لذي ذين امن منو بلل لله ورس رسل سله ولم يفر فرق رقو بين احد منه نهم اول ولي ليك سوف يوت وتي تيه يهم اجو جور وره رهم وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (646, 'quran:4:153', 'quran', 'quran', '4:153', 153, 645, 'An-Nisa', 'النساء', 'يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا', NULL, NULL, 'يسلك اهل الكتب ان تنزل عليهم كتبا من السماء فقد سالوا موسي اكبر من ذلك فقالوا ارنا الله جهره فاخذتهم الصعقه بظلمهم ثم اتخذوا العجل من بعد ما جاءتهم البينت فعفونا عن ذلك واتينا موسي سلطنا مبينا', 'يسلك اهل كتب ان تنزل علي كتب من سمء فقد سل موس اكبر من ذلك قل ار له جهر اخذت صعق بظلم ثم اتخذ عجل من بعد م جءت بينت عفو عن ذلك اتي موس سلط مبي', 'quran', NULL, NULL, 'https://quran.com/4/153');
INSERT INTO units_tri_src (id, ar_tri) VALUES (646, 'يسل سلك اهل الك لكت كتب ان تنز نزل علي ليه يهم كتب من الس لسم سمء فقد سلو موس وسي اكب كبر من ذلك فقل قلو ارن الل لله جهر هره فخذ خذت ذته تهم الص لصع صعق عقه بظل ظلم لمه مهم ثم اتخ تخذ خذو الع لعج عجل من بعد م جءت ءته تهم الب لبي بين ينت فعف عفو فون عن ذلك وتي تين موس وسي سلط لطن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (647, 'quran:4:154', 'quran', 'quran', '4:154', 154, 646, 'An-Nisa', 'النساء', 'وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا', NULL, NULL, 'ورفعنا فوقهم الطور بميثقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت واخذنا منهم ميثقا غليظا', 'رفع وق طور بميثق قل لهم ادخل بب سجد قل لهم ل تعد في سبت اخذ من ميثق غليظ', 'quran', NULL, NULL, 'https://quran.com/4/154');
INSERT INTO units_tri_src (id, ar_tri) VALUES (647, 'ورف رفع فعن فوق وقه قهم الط لطو طور بمي ميث يثق ثقه قهم وقل قلن لهم ادخ دخل خلو الب لبب سجد وقل قلن لهم ل تعد عدو في الس لسب سبت وخذ خذن منه نهم ميث يثق غلي ليظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (648, 'quran:4:155', 'quran', 'quran', '4:155', 155, 647, 'An-Nisa', 'النساء', 'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا', NULL, NULL, 'فبما نقضهم ميثقهم وكفرهم بايت الله وقتلهم الانبياء بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يومنون الا قليلا', 'بم نقض ميثق كفر بيت له قتل انبيء بغير حق قول قلوب غلف بل طبع له علي بكفر فل يومن ال قليل', 'quran', NULL, NULL, 'https://quran.com/4/155');
INSERT INTO units_tri_src (id, ar_tri) VALUES (648, 'فبم نقض قضه ضهم ميث يثق ثقه قهم وكف كفر فره رهم بيت الل لله وقت قتل تله لهم الن لنب نبي بيء بغي غير حق وقو قول وله لهم قلو لوب وبن غلف بل طبع الل لله علي ليه بكف كفر فره رهم فل يوم ومن منو نون ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (649, 'quran:4:156', 'quran', 'quran', '4:156', 156, 648, 'An-Nisa', 'النساء', 'وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا', NULL, NULL, 'وبكفرهم وقولهم علي مريم بهتنا عظيما', 'بكفر قول عل مريم بهت عظيم', 'quran', NULL, NULL, 'https://quran.com/4/156');
INSERT INTO units_tri_src (id, ar_tri) VALUES (649, 'وبك بكف كفر فره رهم وقو قول وله لهم علي مري ريم بهت هتن عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (650, 'quran:4:157', 'quran', 'quran', '4:157', 157, 649, 'An-Nisa', 'النساء', 'وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا', NULL, NULL, 'وقولهم انا قتلنا المسيح عيسي ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وان الذين اختلفوا فيه لفي شك منه ما لهم به من علم الا اتباع الظن وما قتلوه يقينا', 'قول ان قتل مسيح عيس ابن مريم رسول له وم قتلو وم صلبو لكن شب لهم ون ذين اختلف في لف شك من م لهم به من علم ال اتبع ظن وم قتلو يقي', 'quran', NULL, NULL, 'https://quran.com/4/157');
INSERT INTO units_tri_src (id, ar_tri) VALUES (650, 'وقو قول وله لهم ان قتل تلن الم لمس مسي سيح عيس يسي ابن مري ريم رسو سول الل لله وم قتل تلو لوه وم صلب لبو بوه ولك لكن شبه لهم ون الذ لذي ذين اخت ختل تلف لفو فيه لفي شك منه م لهم به من علم ال اتب تبع الظ لظن وم قتل تلو لوه يقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (651, 'quran:4:158', 'quran', 'quran', '4:158', 158, 650, 'An-Nisa', 'النساء', 'بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا', NULL, NULL, 'بل رفعه الله اليه وكان الله عزيزا حكيما', 'بل رفع له يه كن له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/4/158');
INSERT INTO units_tri_src (id, ar_tri) VALUES (651, 'بل رفع فعه الل لله الي ليه وكن الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (652, 'quran:4:159', 'quran', 'quran', '4:159', 159, 651, 'An-Nisa', 'النساء', 'وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا', NULL, NULL, 'وان من اهل الكتب الا ليومنن به قبل موته ويوم القيمه يكون عليهم شهيدا', 'ون من اهل كتب ال ليومنن به قبل موت يوم قيم يك علي شهيد', 'quran', NULL, NULL, 'https://quran.com/4/159');
INSERT INTO units_tri_src (id, ar_tri) VALUES (652, 'ون من اهل الك لكت كتب ال ليو يوم ومن منن به قبل موت وته ويو يوم الق لقي قيم يمه يكو كون علي ليه يهم شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (653, 'quran:4:160', 'quran', 'quran', '4:160', 160, 652, 'An-Nisa', 'النساء', 'فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا', NULL, NULL, 'فبظلم من الذين هادوا حرمنا عليهم طيبت احلت لهم وبصدهم عن سبيل الله كثيرا', 'بظلم من ذين هد حرم علي طيبت احلت لهم بصد عن سبيل له كثير', 'quran', NULL, NULL, 'https://quran.com/4/160');
INSERT INTO units_tri_src (id, ar_tri) VALUES (653, 'فبظ بظل ظلم من الذ لذي ذين هدو حرم رمن علي ليه يهم طيب يبت احل حلت لهم وبص بصد صده دهم عن سبي بيل الل لله كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (654, 'quran:4:161', 'quran', 'quran', '4:161', 161, 653, 'An-Nisa', 'النساء', 'وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا', NULL, NULL, 'واخذهم الرباا وقد نهوا عنه واكلهم امول الناس بالبطل واعتدنا للكفرين منهم عذابا اليما', 'اخذ رب وقد نه عن اكل امول نس بطل اعتد كفر من عذب يم', 'quran', NULL, NULL, 'https://quran.com/4/161');
INSERT INTO units_tri_src (id, ar_tri) VALUES (654, 'وخذ خذه ذهم الر لرب وقد نهو عنه وكل كله لهم امو مول الن لنس بلب لبط بطل وعت عتد تدن للك لكف كفر فري رين منه نهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (655, 'quran:4:162', 'quran', 'quran', '4:162', 162, 654, 'An-Nisa', 'النساء', 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا', NULL, NULL, 'لكن الرسخون في العلم منهم والمومنون يومنون بما انزل اليك وما انزل من قبلك والمقيمين الصلاه والموتون الزكاه والمومنون بالله واليوم الاخر اوليك سنوتيهم اجرا عظيما', 'لكن رسخ في علم من مومن يومن بم انزل يك وم انزل من قبلك مقيم صل موت زك مومن له يوم اخر اوليك سنوتي اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/4/162');
INSERT INTO units_tri_src (id, ar_tri) VALUES (655, 'لكن الر لرس رسخ سخو خون في الع لعل علم منه نهم ولم لمو موم ومن منو نون يوم ومن منو نون بم انز نزل الي ليك وم انز نزل من قبل بلك ولم لمق مقي قيم يمي مين الص لصل صله ولم لمو موت وتو تون الز لزك زكه ولم لمو موم ومن منو نون بلل لله ولي ليو يوم الخ لخر اول ولي ليك سنو نوت وتي تيه يهم اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (656, 'quran:4:163', 'quran', 'quran', '4:163', 163, 655, 'An-Nisa', 'النساء', 'إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا', NULL, NULL, 'انا اوحينا اليك كما اوحينا الي نوح والنبين من بعده واوحينا الي ابرهيم واسمعيل واسحق ويعقوب والاسباط وعيسي وايوب ويونس وهرون وسليمن واتينا داود زبورا', 'ان اوحي يك كم اوحي ال نوح نب من بعد اوحي ال ابرهيم اسمعيل اسحق يعقوب اسبط عيس ايوب يونس هر سليمن اتي دود زبور', 'quran', NULL, NULL, 'https://quran.com/4/163');
INSERT INTO units_tri_src (id, ar_tri) VALUES (656, 'ان اوح وحي حين الي ليك كم اوح وحي حين الي نوح ولن لنب نبي بين من بعد عده ووح وحي حين الي ابر بره رهي هيم وسم سمع معي عيل وسح سحق ويع يعق عقو قوب ولس لسب سبط وعي عيس يسي ويو يوب ويو يون ونس وهر هرو رون وسل سلي ليم يمن وتي تين دود زبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (657, 'quran:4:164', 'quran', 'quran', '4:164', 164, 656, 'An-Nisa', 'النساء', 'وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا', NULL, NULL, 'ورسلا قد قصصنهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسي تكليما', 'رسل قد قصصن عليك من قبل رسل لم نقصص عليك كلم له موس تكليم', 'quran', NULL, NULL, 'https://quran.com/4/164');
INSERT INTO units_tri_src (id, ar_tri) VALUES (657, 'ورس رسل قد قصص صصن صنه نهم علي ليك من قبل ورس رسل لم نقص قصص صصه صهم علي ليك وكل كلم الل لله موس وسي تكل كلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (658, 'quran:4:165', 'quran', 'quran', '4:165', 165, 657, 'An-Nisa', 'النساء', 'رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا', NULL, NULL, 'رسلا مبشرين ومنذرين ليلا يكون للناس علي الله حجه بعد الرسل وكان الله عزيزا حكيما', 'رسل مبشر منذر ليل يك نس عل له حج بعد رسل كن له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/4/165');
INSERT INTO units_tri_src (id, ar_tri) VALUES (658, 'رسل مبش بشر شري رين ومن منذ نذر ذري رين ليل يكو كون للن لنس علي الل لله حجه بعد الر لرس رسل وكن الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (659, 'quran:4:166', 'quran', 'quran', '4:166', 166, 658, 'An-Nisa', 'النساء', 'لَّٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', NULL, NULL, 'لكن الله يشهد بما انزل اليك انزله بعلمه والمليكه يشهدون وكفي بالله شهيدا', 'لكن له يشهد بم انزل يك انزل بعلم مليك يشهد كف له شهيد', 'quran', NULL, NULL, 'https://quran.com/4/166');
INSERT INTO units_tri_src (id, ar_tri) VALUES (659, 'لكن الل لله يشه شهد بم انز نزل الي ليك انز نزل زله بعل علم لمه ولم لمل ملي ليك يكه يشه شهد هدو دون وكف كفي بلل لله شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (660, 'quran:4:167', 'quran', 'quran', '4:167', 167, 659, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا', NULL, NULL, 'ان الذين كفروا وصدوا عن سبيل الله قد ضلوا ضللا بعيدا', 'ان ذين كفر صد عن سبيل له قد ضل ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/4/167');
INSERT INTO units_tri_src (id, ar_tri) VALUES (660, 'ان الذ لذي ذين كفر فرو وصد صدو عن سبي بيل الل لله قد ضلو ضلل بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (661, 'quran:4:168', 'quran', 'quran', '4:168', 168, 660, 'An-Nisa', 'النساء', 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا', NULL, NULL, 'ان الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا', 'ان ذين كفر ظلم لم يكن له ليغفر لهم ول ليهدي طريق', 'quran', NULL, NULL, 'https://quran.com/4/168');
INSERT INTO units_tri_src (id, ar_tri) VALUES (661, 'ان الذ لذي ذين كفر فرو وظل ظلم لمو لم يكن الل لله ليغ يغف غفر لهم ول ليه يهد هدي ديه يهم طري ريق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (662, 'quran:4:169', 'quran', 'quran', '4:169', 169, 661, 'An-Nisa', 'النساء', 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا', NULL, NULL, 'الا طريق جهنم خلدين فيها ابدا وكان ذلك علي الله يسيرا', 'ال طريق جهنم خلد يه ابد كن ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/4/169');
INSERT INTO units_tri_src (id, ar_tri) VALUES (662, 'ال طري ريق جهن هنم خلد لدي دين فيه ابد وكن ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (663, 'quran:4:170', 'quran', 'quran', '4:170', 170, 662, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', NULL, NULL, 'يا ايها الناس قد جاءكم الرسول بالحق من ربكم فامنوا خيرا لكم وان تكفروا فان لله ما في السموت والارض وكان الله عليما حكيما', 'ي اي نس قد جء رسول حق من رب امن خير لكم ون تكفر فن لل م في سموت ارض كن له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/4/170');
INSERT INTO units_tri_src (id, ar_tri) VALUES (663, 'ي ايه الن لنس قد جءك ءكم الر لرس رسو سول بلح لحق من ربك بكم فمن منو خير لكم ون تكف كفر فرو فن لله م في الس لسم سمو موت ولر لرض وكن الل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (664, 'quran:4:171', 'quran', 'quran', '4:171', 171, 663, 'An-Nisa', 'النساء', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا', NULL, NULL, 'يا اهل الكتب لا تغلوا في دينكم ولا تقولوا علي الله الا الحق انما المسيح عيسي ابن مريم رسول الله وكلمته القاها الي مريم وروح منه فامنوا بالله ورسله ولا تقولوا ثلثه انتهوا خيرا لكم انما الله اله وحد سبحنه ان يكون له ولد له ما في السموت وما في الارض وكفي بالله وكيلا', 'ي اهل كتب ل تغل في دين ول تقول عل له ال حق انم مسيح عيس ابن مريم رسول له كلمت ق ال مريم روح من امن له رسل ول تقول ثلث انته خير لكم انم له ال وحد سبحن ان يك له ولد له م في سموت وم في ارض كف له كيل', 'quran', NULL, NULL, 'https://quran.com/4/171');
INSERT INTO units_tri_src (id, ar_tri) VALUES (664, 'ي اهل الك لكت كتب ل تغل غلو في دين ينك نكم ول تقو قول ولو علي الل لله ال الح لحق انم الم لمس مسي سيح عيس يسي ابن مري ريم رسو سول الل لله وكل كلم لمت مته الق لقه الي مري ريم ورو روح منه فمن منو بلل لله ورس رسل سله ول تقو قول ولو ثلث لثه انت نته تهو خير لكم انم الل لله اله وحد سبح بحن حنه ان يكو كون له ولد له م في الس لسم سمو موت وم في الر لرض وكف كفي بلل لله وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (665, 'quran:4:172', 'quran', 'quran', '4:172', 172, 664, 'An-Nisa', 'النساء', 'لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا', NULL, NULL, 'لن يستنكف المسيح ان يكون عبدا لله ولا المليكه المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم اليه جميعا', 'لن يستنكف مسيح ان يك عبد لل ول مليك مقرب ومن يستنكف عن عبدت يستكبر سيحشر يه جميع', 'quran', NULL, NULL, 'https://quran.com/4/172');
INSERT INTO units_tri_src (id, ar_tri) VALUES (665, 'لن يست ستن تنك نكف الم لمس مسي سيح ان يكو كون عبد لله ول الم لمل ملي ليك يكه الم لمق مقر قرب ربو بون ومن يست ستن تنك نكف عن عبد بدت دته ويس يست ستك تكب كبر فسي سيح يحش حشر شره رهم الي ليه جمي ميع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (666, 'quran:4:173', 'quran', 'quran', '4:173', 173, 665, 'An-Nisa', 'النساء', 'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا', NULL, NULL, 'فاما الذين امنوا وعملوا الصلحت فيوفيهم اجورهم ويزيدهم من فضله واما الذين استنكفوا واستكبروا فيعذبهم عذابا اليما ولا يجدون لهم من دون الله وليا ولا نصيرا', 'ام ذين امن عمل صلحت يوفي اجور يزيد من ضل ام ذين استنكف استكبر يعذب عذب يم ول يجد لهم من دون له لي ول نصير', 'quran', NULL, NULL, 'https://quran.com/4/173');
INSERT INTO units_tri_src (id, ar_tri) VALUES (666, 'فم الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت فيو يوف وفي فيه يهم اجو جور وره رهم ويز يزي زيد يده دهم من فضل ضله وم الذ لذي ذين است ستن تنك نكف كفو وست ستك تكب كبر برو فيع يعذ عذب ذبه بهم عذب الي ليم ول يجد جدو دون لهم من دون الل لله ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (667, 'quran:4:174', 'quran', 'quran', '4:174', 174, 666, 'An-Nisa', 'النساء', 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا', NULL, NULL, 'يا ايها الناس قد جاءكم برهن من ربكم وانزلنا اليكم نورا مبينا', 'ي اي نس قد جء بر من رب انزل يكم نور مبي', 'quran', NULL, NULL, 'https://quran.com/4/174');
INSERT INTO units_tri_src (id, ar_tri) VALUES (667, 'ي ايه الن لنس قد جءك ءكم بره رهن من ربك بكم ونز نزل زلن الي ليك يكم نور مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (668, 'quran:4:175', 'quran', 'quran', '4:175', 175, 667, 'An-Nisa', 'النساء', 'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا', NULL, NULL, 'فاما الذين امنوا بالله واعتصموا به فسيدخلهم في رحمه منه وفضل ويهديهم اليه صرطا مستقيما', 'ام ذين امن له اعتصم به سيدخل في رحم من فضل يهدي يه صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/4/175');
INSERT INTO units_tri_src (id, ar_tri) VALUES (668, 'فم الذ لذي ذين امن منو بلل لله وعت عتص تصم صمو به فسي سيد يدخ دخل خله لهم في رحم حمه منه وفض فضل ويه يهد هدي ديه يهم الي ليه صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (669, 'quran:4:176', 'quran', 'quran', '4:176', 176, 668, 'An-Nisa', 'النساء', 'يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ', NULL, NULL, 'يستفتونك قل الله يفتيكم في الكلله ان امروا هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد فان كانتا اثنتين فلهما الثلثان مما ترك وان كانوا اخوه رجالا ونساء فللذكر مثل حظ الانثيين يبين الله لكم ان تضلوا والله بكل شيء عليم', 'يستفتونك قل له يفتي في كلل ان امر هلك ليس له ولد ول اخت له نصف م ترك وهو يرث ان لم يكن له ولد فن كنت اثنت لهم ثلث مم ترك ون كن اخو رجل نسء ذكر مثل حظ انثي يب له لكم ان تضل له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/4/176');
INSERT INTO units_tri_src (id, ar_tri) VALUES (669, 'يست ستف تفت فتو تون ونك قل الل لله يفت فتي تيك يكم في الك لكل كلل لله ان امر مرو هلك ليس له ولد وله اخت فله نصف م ترك وهو يرث رثه ان لم يكن له ولد فن كنت اثن ثنت نتي تين فله لهم الث لثل ثلث لثن مم ترك ون كنو اخو خوه رجل ونس نسء فلل للذ لذك ذكر مثل حظ الن لنث نثي ثيي يين يبي بين الل لله لكم ان تضل ضلو ولل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (670, 'quran:5:1', 'quran', 'quran', '5:1', 1, 669, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ', NULL, NULL, 'يا ايها الذين امنوا اوفوا بالعقود احلت لكم بهيمه الانعم الا ما يتلي عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد', 'ي اي ذين امن اوف عقود احلت لكم بهيم انعم ال م يتل علي غير محل صيد انتم حرم ان له يح م يريد', 'quran', NULL, NULL, 'https://quran.com/5/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (670, 'ي ايه الذ لذي ذين امن منو اوف وفو بلع لعق عقو قود احل حلت لكم بهي هيم يمه الن لنع نعم ال م يتل تلي علي ليك يكم غير محل حلي الص لصي صيد ونت نتم حرم ان الل لله يحك حكم م يري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (671, 'quran:5:2', 'quran', 'quran', '5:2', 2, 670, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'يا ايها الذين امنوا لا تحلوا شعير الله ولا الشهر الحرام ولا الهدي ولا القليد ولا امين البيت الحرام يبتغون فضلا من ربهم ورضونا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا علي البر والتقوي ولا تعاونوا علي الاثم والعدون واتقوا الله ان الله شديد العقاب', 'ي اي ذين امن ل تحل شعير له ول شهر حرم ول هد ول قليد ول ام بيت حرم يبتغ ضل من رب رضو اذ حللتم اصطد ول يجرمن شن قوم ان صدو عن مسجد حرم ان تعتد تعون عل بر تقو ول تعون عل اثم عد اتق له ان له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/5/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (671, 'ي ايه الذ لذي ذين امن منو ل تحل حلو شعي عير الل لله ول الش لشه شهر الح لحر حرم ول اله لهد هدي ول الق لقل قلي ليد ول امي مين الب لبي بيت الح لحر حرم يبت بتغ تغو غون فضل من ربه بهم ورض رضو ضون وذ حلل للت لتم فصط صطد طدو ول يجر جرم رمن منك نكم شنن قوم ان صدو دوك وكم عن الم لمس مسج سجد الح لحر حرم ان تعت عتد تدو وتع تعو عون ونو علي الب لبر ولت لتق تقو قوي ول تعو عون ونو علي الث لثم ولع لعد عدو دون وتق تقو الل لله ان الل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (672, 'quran:5:3', 'quran', 'quran', '5:3', 3, 671, 'Al-Ma''idah', 'المائدة', 'حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'حرمت عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به والمنخنقه والموقوذه والمترديه والنطيحه وما اكل السبع الا ما ذكيتم وما ذبح علي النصب وان تستقسموا بالازلم ذلكم فسق اليوم ييس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلم دينا فمن اضطر في مخمصه غير متجانف لاثم فان الله غفور رحيم', 'حرمت علي ميت دم لحم خنزير وم اهل لغير له به منخنق موقوذ مترد نطيح وم اكل سبع ال م ذكيتم وم ذبح عل نصب ون تستقسم ازلم ذل فسق يوم ييس ذين كفر من دين فل تخشو اخش يوم اكملت لكم دين اتممت علي نعمت رضيت لكم اسلم دي فمن اضطر في مخمص غير متجنف لثم فن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/5/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (672, 'حرم رمت علي ليك يكم الم لمي ميت يته ولد لدم ولح لحم الخ لخن خنز نزي زير وم اهل لغي غير الل لله به ولم لمن منخ نخن خنق نقه ولم لمو موق وقو قوذ وذه ولم لمت متر ترد ردي ديه ولن لنط نطي طيح يحه وم اكل الس لسب سبع ال م ذكي كيت يتم وم ذبح علي الن لنص نصب ون تست ستق تقس قسم سمو بلز لزل زلم ذلك لكم فسق الي ليو يوم ييس الذ لذي ذين كفر فرو من دين ينك نكم فل تخش خشو شوه وهم وخش خشو شون الي ليو يوم اكم كمل ملت لكم دين ينك نكم وتم تمم ممت علي ليك يكم نعم عمت متي ورض رضي ضيت لكم الس لسل سلم دين فمن اضط ضطر في مخم خمص مصه غير متج تجن جنف لثم فن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (673, 'quran:5:4', 'quran', 'quran', '5:4', 4, 672, 'Al-Ma''idah', 'المائدة', 'يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', NULL, NULL, 'يسلونك ماذا احل لهم قل احل لكم الطيبت وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب', 'يسلونك مذ احل لهم قل احل لكم طيبت وم علمتم من جورح مكلب تعلمون مم علم له كل مم امسكن علي اذكر اسم له عل اتق له ان له سريع حسب', 'quran', NULL, NULL, 'https://quran.com/5/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (673, 'يسل سلو لون ونك مذ احل لهم قل احل لكم الط لطي طيب يبت وم علم لمت متم من الج لجو جور ورح مكل كلب لبي بين تعل علم لمو مون ونه نهن مم علم لمك مكم الل لله فكل كلو مم امس مسك سكن علي ليك يكم وذك ذكر كرو اسم الل لله علي ليه وتق تقو الل لله ان الل لله سري ريع الح لحس حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (674, 'quran:5:5', 'quran', 'quran', '5:5', 5, 673, 'Al-Ma''idah', 'المائدة', 'ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ', NULL, NULL, 'اليوم احل لكم الطيبت وطعام الذين اوتوا الكتب حل لكم وطعامكم حل لهم والمحصنت من المومنت والمحصنت من الذين اوتوا الكتب من قبلكم اذا اتيتموهن اجورهن محصنين غير مسفحين ولا متخذي اخدان ومن يكفر بالايمن فقد حبط عمله وهو في الاخره من الخسرين', 'يوم احل لكم طيبت طعم ذين اوت كتب حل لكم طعم حل لهم محصنت من مومنت محصنت من ذين اوت كتب من قبل اذ اتيتمو اجور محصن غير مسفح ول متخذ اخد ومن يكفر ايمن فقد حبط عمل وهو في اخر من خسر', 'quran', NULL, NULL, 'https://quran.com/5/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (674, 'الي ليو يوم احل لكم الط لطي طيب يبت وطع طعم الذ لذي ذين اوت وتو الك لكت كتب حل لكم وطع طعم عمك مكم حل لهم ولم لمح محص حصن صنت من الم لمو موم ومن منت ولم لمح محص حصن صنت من الذ لذي ذين اوت وتو الك لكت كتب من قبل بلك لكم اذ اتي تيت يتم تمو موه وهن اجو جور وره رهن محص حصن صني نين غير مسف سفح فحي حين ول متخ تخذ خذي اخد خدن ومن يكف كفر بلي ليم يمن فقد حبط عمل مله وهو في الخ لخر خره من الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (675, 'quran:5:6', 'quran', 'quran', '5:6', 6, 674, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'يا ايها الذين امنوا اذا قمتم الي الصلاه فاغسلوا وجوهكم وايديكم الي المرافق وامسحوا برءوسكم وارجلكم الي الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضي او علي سفر او جاء احد منكم من الغايط او لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون', 'ي اي ذين امن اذ قمتم ال صل اغسل جوه ايدي ال مرفق امسح برءوس ارجل ال كعب ون كنتم جنب اطهر ون كنتم مرض او عل سفر او جء احد من من غيط او لمستم نسء فلم تجد مء تيمم صعيد طيب امسح بوجوه ايدي من م يريد له ليجعل علي من حرج لكن يريد ليطهر ليتم نعمت علي لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/5/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (675, 'ي ايه الذ لذي ذين امن منو اذ قمت متم الي الص لصل صله فغس غسل سلو وجو جوه وهك هكم ويد يدي ديك يكم الي الم لمر مرف رفق ومس مسح سحو برء رءو ءوس وسك سكم ورج رجل جلك لكم الي الك لكع كعب عبي بين ون كنت نتم جنب فطه طهر هرو ون كنت نتم مرض رضي او علي سفر او جء احد منك نكم من الغ لغي غيط او لمس مست ستم الن لنس نسء فلم تجد جدو مء فتي تيم يمم ممو صعي عيد طيب فمس مسح سحو بوج وجو جوه وهك هكم ويد يدي ديك يكم منه م يري ريد الل لله ليج يجع جعل علي ليك يكم من حرج ولك لكن يري ريد ليط يطه طهر هرك ركم ولي ليت يتم نعم عمت مته علي ليك يكم لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (676, 'quran:5:7', 'quran', 'quran', '5:7', 7, 675, 'Al-Ma''idah', 'المائدة', 'وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'واذكروا نعمه الله عليكم وميثقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور', 'اذكر نعم له علي ميثق ذي اثق به اذ قلتم سمع اطع اتق له ان له عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/5/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (676, 'وذك ذكر كرو نعم عمه الل لله علي ليك يكم ومي ميث يثق ثقه الذ لذي وثق ثقك قكم به اذ قلت لتم سمع معن وطع طعن وتق تقو الل لله ان الل لله علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (677, 'quran:5:8', 'quran', 'quran', '5:8', 8, 676, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ', NULL, NULL, 'يا ايها الذين امنوا كونوا قومين لله شهداء بالقسط ولا يجرمنكم شنان قوم علي الا تعدلوا اعدلوا هو اقرب للتقوي واتقوا الله ان الله خبير بما تعملون', 'ي اي ذين امن كون قوم لل شهدء قسط ول يجرمن شن قوم عل ال تعدل اعدل هو اقرب تقو اتق له ان له خبير بم تعمل', 'quran', NULL, NULL, 'https://quran.com/5/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (677, 'ي ايه الذ لذي ذين امن منو كون ونو قوم ومي مين لله شهد هدء بلق لقس قسط ول يجر جرم رمن منك نكم شنن قوم علي ال تعد عدل دلو اعد عدل دلو هو اقر قرب للت لتق تقو قوي وتق تقو الل لله ان الل لله خبي بير بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (678, 'quran:5:9', 'quran', 'quran', '5:9', 9, 677, 'Al-Ma''idah', 'المائدة', 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ', NULL, NULL, 'وعد الله الذين امنوا وعملوا الصلحت لهم مغفره واجر عظيم', 'وعد له ذين امن عمل صلحت لهم مغفر اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/5/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (678, 'وعد الل لله الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لهم مغف غفر فره وجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (679, 'quran:5:10', 'quran', 'quran', '5:10', 10, 678, 'Al-Ma''idah', 'المائدة', 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', NULL, NULL, 'والذين كفروا وكذبوا بايتنا اوليك اصحب الجحيم', 'ذين كفر كذب بيت اوليك اصحب جحيم', 'quran', NULL, NULL, 'https://quran.com/5/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (679, 'ولذ لذي ذين كفر فرو وكذ كذب ذبو بيت يتن اول ولي ليك اصح صحب الج لجح جحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (680, 'quran:5:11', 'quran', 'quran', '5:11', 11, 679, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', NULL, NULL, 'يا ايها الذين امنوا اذكروا نعمت الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلي الله فليتوكل المومنون', 'ي اي ذين امن اذكر نعمت له علي اذ هم قوم ان يبسط يكم ايدي فكف ايدي عن اتق له عل له ليتوكل مومن', 'quran', NULL, NULL, 'https://quran.com/5/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (680, 'ي ايه الذ لذي ذين امن منو اذك ذكر كرو نعم عمت الل لله علي ليك يكم اذ هم قوم ان يبس بسط سطو الي ليك يكم ايد يدي ديه يهم فكف ايد يدي ديه يهم عنك نكم وتق تقو الل لله وعل علي الل لله فلي ليت يتو توك وكل الم لمو موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (681, 'quran:5:12', 'quran', 'quran', '5:12', 12, 680, 'Al-Ma''idah', 'المائدة', 'وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', NULL, NULL, 'ولقد اخذ الله ميثق بني اسرءيل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لين اقمتم الصلاه واتيتم الزكاه وامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سياتكم ولادخلنكم جنت تجري من تحتها الانهر فمن كفر بعد ذلك منكم فقد ضل سواء السبيل', 'لقد اخذ له ميثق بن اسرءيل بعث من اثن عشر نقيب قل له ان مع لين اقمتم صل اتيتم زك امنتم برسل عزرتمو اقرضتم له قرض حس لكفرن عن سيت لدخلن جنت تجر من تحت انهر فمن كفر بعد ذلك من فقد ضل سوء سبيل', 'quran', NULL, NULL, 'https://quran.com/5/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (681, 'ولق لقد اخذ الل لله ميث يثق بني اسر سرء رءي ءيل وبع بعث عثن منه نهم اثن ثني عشر نقي قيب وقل الل لله اني معك عكم لين اقم قمت متم الص لصل صله وتي تيت يتم الز لزك زكه ومن منت نتم برس رسل سلي وعز عزر زرت رتم تمو موه وهم وقر قرض رضت ضتم الل لله قرض حسن لكف كفر فرن عنك نكم سيت يتك تكم ولد لدخ دخل خلن لنك نكم جنت تجر جري من تحت حته الن لنه نهر فمن كفر بعد ذلك منك نكم فقد ضل سوء الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (682, 'quran:5:13', 'quran', 'quran', '5:13', 13, 681, 'Al-Ma''idah', 'المائدة', 'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'فبما نقضهم ميثقهم لعنهم وجعلنا قلوبهم قسيه يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع علي خاينه منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين', 'بم نقض ميثق لعن جعل قلوب قس يحرف كلم عن موضع نس حظ مم ذكر به ول تزل تطلع عل خين من ال قليل من اعف عن اصفح ان له يحب محسن', 'quran', NULL, NULL, 'https://quran.com/5/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (682, 'فبم نقض قضه ضهم ميث يثق ثقه قهم لعن عنه نهم وجع جعل علن قلو لوب وبه بهم قسي سيه يحر حرف رفو فون الك لكل كلم عن موض وضع ضعه ونس نسو حظ مم ذكر كرو به ول تزل تطل طلع علي خين ينه منه نهم ال قلي ليل منه نهم فعف عنه نهم وصف صفح ان الل لله يحب الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (683, 'quran:5:14', 'quran', 'quran', '5:14', 14, 682, 'Al-Ma''idah', 'المائدة', 'وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ', NULL, NULL, 'ومن الذين قالوا انا نصري اخذنا ميثقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوه والبغضاء الي يوم القيمه وسوف ينبيهم الله بما كانوا يصنعون', 'ومن ذين قل ان نصر اخذ ميثق نس حظ مم ذكر به اغري بين عدو بغضء ال يوم قيم سوف ينبي له بم كن يصنع', 'quran', NULL, NULL, 'https://quran.com/5/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (683, 'ومن الذ لذي ذين قلو ان نصر صري اخذ خذن ميث يثق ثقه قهم فنس نسو حظ مم ذكر كرو به فغر غري رين بين ينه نهم الع لعد عدو دوه ولب لبغ بغض غضء الي يوم الق لقي قيم يمه وسو سوف ينب نبي بيه يهم الل لله بم كنو يصن صنع نعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (684, 'quran:5:15', 'quran', 'quran', '5:15', 15, 683, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ', NULL, NULL, 'يا اهل الكتب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتب ويعفوا عن كثير قد جاءكم من الله نور وكتب مبين', 'ي اهل كتب قد جء رسول يب لكم كثير مم كنتم تخف من كتب يعف عن كثير قد جء من له نور كتب مب', 'quran', NULL, NULL, 'https://quran.com/5/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (684, 'ي اهل الك لكت كتب قد جءك ءكم رسو سول ولن يبي بين لكم كثي ثير مم كنت نتم تخف خفو فون من الك لكت كتب ويع يعف عفو عن كثي ثير قد جءك ءكم من الل لله نور وكت كتب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (685, 'quran:5:16', 'quran', 'quran', '5:16', 16, 684, 'Al-Ma''idah', 'المائدة', 'يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'يهدي به الله من اتبع رضونه سبل السلم ويخرجهم من الظلمت الي النور باذنه ويهديهم الي صرط مستقيم', 'يهد به له من اتبع رضون سبل سلم يخرج من ظلمت ال نور بذن يهدي ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/5/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (685, 'يهد هدي به الل لله من اتب تبع رضو ضون ونه سبل الس لسل سلم ويخ يخر خرج رجه جهم من الظ لظل ظلم لمت الي الن لنو نور بذن ذنه ويه يهد هدي ديه يهم الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (686, 'quran:5:17', 'quran', 'quran', '5:17', 17, 685, 'Al-Ma''idah', 'المائدة', 'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السموت والارض وما بينهما يخلق ما يشاء والله علي كل شيء قدير', 'لقد كفر ذين قل ان له هو مسيح ابن مريم قل فمن يملك من له شي ان ارد ان يهلك مسيح ابن مريم ام ومن في ارض جميع لل ملك سموت ارض وم بينهم يخلق م يشء له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/5/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (686, 'لقد كفر الذ لذي ذين قلو ان الل لله هو الم لمس مسي سيح ابن مري ريم قل فمن يمل ملك من الل لله شي ان ارد ان يهل هلك الم لمس مسي سيح ابن مري ريم ومه ومن في الر لرض جمي ميع ولل لله ملك الس لسم سمو موت ولر لرض وم بين ينه نهم يخل خلق م يشء ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (687, 'quran:5:18', 'quran', 'quran', '5:18', 18, 686, 'Al-Ma''idah', 'المائدة', 'وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ', NULL, NULL, 'وقالت اليهود والنصري نحن ابنوا الله واحبوه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السموت والارض وما بينهما واليه المصير', 'قلت يهود نصر نحن ابن له احبو قل فلم يعذب بذنوب بل انتم بشر ممن خلق يغفر لمن يشء يعذب من يشء لل ملك سموت ارض وم بينهم يه مصير', 'quran', NULL, NULL, 'https://quran.com/5/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (687, 'وقل قلت الي ليه يهو هود ولن لنص نصر صري نحن ابن بنو الل لله وحب حبو بوه قل فلم يعذ عذب ذبك بكم بذن ذنو نوب وبك بكم بل انت نتم بشر ممن خلق يغف غفر لمن يشء ويع يعذ عذب من يشء ولل لله ملك الس لسم سمو موت ولر لرض وم بين ينه نهم ولي ليه الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (688, 'quran:5:19', 'quran', 'quran', '5:19', 19, 687, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'يا اهل الكتب قد جاءكم رسولنا يبين لكم علي فتره من الرسل ان تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله علي كل شيء قدير', 'ي اهل كتب قد جء رسول يب لكم عل تر من رسل ان تقول م جء من بشير ول نذير فقد جء بشير نذير له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/5/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (688, 'ي اهل الك لكت كتب قد جءك ءكم رسو سول ولن يبي بين لكم علي فتر تره من الر لرس رسل ان تقو قول ولو م جءن من بشي شير ول نذي ذير فقد جءك ءكم بشي شير ونذ نذي ذير ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (689, 'quran:5:20', 'quran', 'quran', '5:20', 20, 688, 'Al-Ma''idah', 'المائدة', 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ', NULL, NULL, 'واذ قال موسي لقومه يا قوم اذكروا نعمه الله عليكم اذ جعل فيكم انبياء وجعلكم ملوكا واتاكم ما لم يوت احدا من العلمين', 'وذ قل موس لقوم ي قوم اذكر نعم له علي اذ جعل يكم انبيء جعل ملوك ات م لم يوت احد من علم', 'quran', NULL, NULL, 'https://quran.com/5/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (689, 'وذ قل موس وسي لقو قوم ومه ي قوم اذك ذكر كرو نعم عمه الل لله علي ليك يكم اذ جعل فيك يكم انب نبي بيء وجع جعل علك لكم ملو لوك وتك تكم م لم يوت احد من الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (690, 'quran:5:21', 'quran', 'quran', '5:21', 21, 689, 'Al-Ma''idah', 'المائدة', 'يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ', NULL, NULL, 'يا قوم ادخلوا الارض المقدسه التي كتب الله لكم ولا ترتدوا علي ادباركم فتنقلبوا خسرين', 'ي قوم ادخل ارض مقدس تي كتب له لكم ول ترتد عل ادبر تنقلب خسر', 'quran', NULL, NULL, 'https://quran.com/5/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (690, 'ي قوم ادخ دخل خلو الر لرض الم لمق مقد قدس دسه الت لتي كتب الل لله لكم ول ترت رتد تدو علي ادب دبر برك ركم فتن تنق نقل قلب لبو خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (691, 'quran:5:22', 'quran', 'quran', '5:22', 22, 690, 'Al-Ma''idah', 'المائدة', 'قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ', NULL, NULL, 'قالوا يا موسي ان فيها قوما جبارين وانا لن ندخلها حتي يخرجوا منها فان يخرجوا منها فانا دخلون', 'قل ي موس ان يه قوم جبر ان لن ندخل حت يخرج من فن يخرج من ان دخل', 'quran', NULL, NULL, 'https://quran.com/5/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (691, 'قلو ي موس وسي ان فيه قوم جبر بري رين ون لن ندخ دخل خله حتي يخر خرج رجو منه فن يخر خرج رجو منه فن دخل خلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (692, 'quran:5:23', 'quran', 'quran', '5:23', 23, 691, 'Al-Ma''idah', 'المائدة', 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'قال رجلان من الذين يخافون انعم الله عليهما ادخلوا عليهم الباب فاذا دخلتموه فانكم غلبون وعلي الله فتوكلوا ان كنتم مومنين', 'قل رجل من ذين يخف انعم له عليهم ادخل علي بب اذ دخلتمو ان غلب عل له توكل ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/5/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (692, 'قل رجل جلن من الذ لذي ذين يخف خفو فون انع نعم الل لله علي ليه يهم ادخ دخل خلو علي ليه يهم الب لبب فذ دخل خلت لتم تمو موه فنك نكم غلب لبو بون وعل علي الل لله فتو توك وكل كلو ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (693, 'quran:5:24', 'quran', 'quran', '5:24', 24, 692, 'Al-Ma''idah', 'المائدة', 'قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', NULL, NULL, 'قالوا يا موسي انا لن ندخلها ابدا ما داموا فيها فاذهب انت وربك فقتلا انا ههنا قعدون', 'قل ي موس ان لن ندخل ابد م دم يه اذهب انت ربك قتل ان هه قعد', 'quran', NULL, NULL, 'https://quran.com/5/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (693, 'قلو ي موس وسي ان لن ندخ دخل خله ابد م دمو فيه فذه ذهب انت ورب ربك فقت قتل ان ههن قعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (694, 'quran:5:25', 'quran', 'quran', '5:25', 25, 693, 'Al-Ma''idah', 'المائدة', 'قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ', NULL, NULL, 'قال رب اني لا املك الا نفسي واخي فافرق بيننا وبين القوم الفسقين', 'قل رب ان ل املك ال نفس اخ افرق بين بين قوم فسق', 'quran', NULL, NULL, 'https://quran.com/5/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (694, 'قل رب اني ل امل ملك ال نفس فسي وخي ففر فرق بين ينن وبي بين الق لقو قوم الف لفس فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (695, 'quran:5:26', 'quran', 'quran', '5:26', 26, 694, 'Al-Ma''idah', 'المائدة', 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ', NULL, NULL, 'قال فانها محرمه عليهم اربعين سنه يتيهون في الارض فلا تاس علي القوم الفسقين', 'قل ان محرم علي اربع سن يتيه في ارض فل تس عل قوم فسق', 'quran', NULL, NULL, 'https://quran.com/5/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (695, 'قل فنه محر حرم رمه علي ليه يهم ارب ربع بعي عين سنه يتي تيه يهو هون في الر لرض فل تس علي الق لقو قوم الف لفس فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (696, 'quran:5:27', 'quran', 'quran', '5:27', 27, 695, 'Al-Ma''idah', 'المائدة', 'وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ', NULL, NULL, 'واتل عليهم نبا ابني ادم بالحق اذ قربا قربانا فتقبل من احدهما ولم يتقبل من الاخر قال لاقتلنك قال انما يتقبل الله من المتقين', 'اتل علي نب ابن ادم حق اذ قرب قرب تقبل من احدهم ولم يتقبل من اخر قل لقتلنك قل انم يتقبل له من متق', 'quran', NULL, NULL, 'https://quran.com/5/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (696, 'وتل علي ليه يهم نب ابن بني ادم بلح لحق اذ قرب قرب ربن فتق تقب قبل من احد حده دهم ولم يتق تقب قبل من الخ لخر قل لقت قتل تلن لنك قل انم يتق تقب قبل الل لله من الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (697, 'quran:5:28', 'quran', 'quran', '5:28', 28, 696, 'Al-Ma''idah', 'المائدة', 'لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'لين بسطت الي يدك لتقتلني ما انا بباسط يدي اليك لاقتلك اني اخاف الله رب العلمين', 'لين بسطت ال يدك لتقتلن م ان ببسط يد يك لقتلك ان اخف له رب علم', 'quran', NULL, NULL, 'https://quran.com/5/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (697, 'لين بسط سطت الي يدك لتق تقت قتل تلن لني م ان ببس بسط يدي الي ليك لقت قتل تلك اني اخف الل لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (698, 'quran:5:29', 'quran', 'quran', '5:29', 29, 697, 'Al-Ma''idah', 'المائدة', 'إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ', NULL, NULL, 'اني اريد ان تبوا باثمي واثمك فتكون من اصحب النار وذلك جزوا الظلمين', 'ان اريد ان تب بثم اثمك تك من اصحب نر ذلك جز ظلم', 'quran', NULL, NULL, 'https://quran.com/5/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (698, 'اني اري ريد ان تبو بثم ثمي وثم ثمك فتك تكو كون من اصح صحب الن لنر وذل ذلك جزو الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (699, 'quran:5:30', 'quran', 'quran', '5:30', 30, 698, 'Al-Ma''idah', 'المائدة', 'فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ', NULL, NULL, 'فطوعت له نفسه قتل اخيه فقتله فاصبح من الخسرين', 'طوعت له نفس قتل اخ قتل اصبح من خسر', 'quran', NULL, NULL, 'https://quran.com/5/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (699, 'فطو طوع وعت له نفس فسه قتل اخي خيه فقت قتل تله فصب صبح من الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (700, 'quran:5:31', 'quran', 'quran', '5:31', 31, 699, 'Al-Ma''idah', 'المائدة', 'فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّٰدِمِينَ', NULL, NULL, 'فبعث الله غرابا يبحث في الارض ليريه كيف يوري سوءه اخيه قال يا ويلتي اعجزت ان اكون مثل هذا الغراب فاوري سوءه اخي فاصبح من الندمين', 'بعث له غرب يبحث في ارض لير كيف يور سوء اخ قل ي يلت اعجزت ان اك مثل هذ غرب اور سوء اخ اصبح من ندم', 'quran', NULL, NULL, 'https://quran.com/5/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (700, 'فبع بعث الل لله غرب يبح بحث في الر لرض لير يري ريه كيف يور وري سوء وءه اخي خيه قل ي ويل يلت لتي اعج عجز جزت ان اكو كون مثل هذ الغ لغر غرب فور وري سوء وءه اخي فصب صبح من الن لند ندم دمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (701, 'quran:5:32', 'quran', 'quran', '5:32', 32, 700, 'Al-Ma''idah', 'المائدة', 'مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ', NULL, NULL, 'من اجل ذلك كتبنا علي بني اسرءيل انه من قتل نفسا بغير نفس او فساد في الارض فكانما قتل الناس جميعا ومن احياها فكانما احيا الناس جميعا ولقد جاءتهم رسلنا بالبينت ثم ان كثيرا منهم بعد ذلك في الارض لمسرفون', 'من اجل ذلك كتب عل بن اسرءيل ان من قتل نفس بغير نفس او سد في ارض كنم قتل نس جميع ومن احي كنم احي نس جميع لقد جءت رسل بينت ثم ان كثير من بعد ذلك في ارض لمسرف', 'quran', NULL, NULL, 'https://quran.com/5/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (701, 'من اجل ذلك كتب تبن علي بني اسر سرء رءي ءيل انه من قتل نفس بغي غير نفس او فسد في الر لرض فكن كنم قتل الن لنس جمي ميع ومن احي حيه فكن كنم احي الن لنس جمي ميع ولق لقد جءت ءته تهم رسل سلن بلب لبي بين ينت ثم ان كثي ثير منه نهم بعد ذلك في الر لرض لمس مسر سرف رفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (702, 'quran:5:33', 'quran', 'quran', '5:33', 33, 701, 'Al-Ma''idah', 'المائدة', 'إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ', NULL, NULL, 'انما جزوا الذين يحاربون الله ورسوله ويسعون في الارض فسادا ان يقتلوا او يصلبوا او تقطع ايديهم وارجلهم من خلف او ينفوا من الارض ذلك لهم خزي في الدنيا ولهم في الاخره عذاب عظيم', 'انم جز ذين يحرب له رسول يسع في ارض سد ان يقتل او يصلب او تقطع ايدي ارجل من خلف او ينف من ارض ذلك لهم خز في دني لهم في اخر عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/5/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (702, 'انم جزو الذ لذي ذين يحر حرب ربو بون الل لله ورس رسو سول وله ويس يسع سعو عون في الر لرض فسد ان يقت قتل تلو او يصل صلب لبو او تقط قطع ايد يدي ديه يهم ورج رجل جله لهم من خلف او ينف نفو من الر لرض ذلك لهم خزي في الد لدن دني وله لهم في الخ لخر خره عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (703, 'quran:5:34', 'quran', 'quran', '5:34', 34, 702, 'Al-Ma''idah', 'المائدة', 'إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'الا الذين تابوا من قبل ان تقدروا عليهم فاعلموا ان الله غفور رحيم', 'ال ذين تب من قبل ان تقدر علي اعلم ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/5/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (703, 'ال الذ لذي ذين تبو من قبل ان تقد قدر درو علي ليه يهم فعل علم لمو ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (704, 'quran:5:35', 'quran', 'quran', '5:35', 35, 703, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يا ايها الذين امنوا اتقوا الله وابتغوا اليه الوسيله وجهدوا في سبيله لعلكم تفلحون', 'ي اي ذين امن اتق له ابتغ يه وسيل جهد في سبيل لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/5/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (704, 'ي ايه الذ لذي ذين امن منو اتق تقو الل لله وبت بتغ تغو الي ليه الو لوس وسي سيل يله وجه جهد هدو في سبي بيل يله لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (705, 'quran:5:36', 'quran', 'quran', '5:36', 36, 704, 'Al-Ma''idah', 'المائدة', 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'ان الذين كفروا لو ان لهم ما في الارض جميعا ومثله معه ليفتدوا به من عذاب يوم القيمه ما تقبل منهم ولهم عذاب اليم', 'ان ذين كفر لو ان لهم م في ارض جميع مثل مع ليفتد به من عذب يوم قيم م تقبل من لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/5/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (705, 'ان الذ لذي ذين كفر فرو لو ان لهم م في الر لرض جمي ميع ومث مثل ثله معه ليف يفت فتد تدو به من عذب يوم الق لقي قيم يمه م تقب قبل منه نهم وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (706, 'quran:5:37', 'quran', 'quran', '5:37', 37, 705, 'Al-Ma''idah', 'المائدة', 'يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ', NULL, NULL, 'يريدون ان يخرجوا من النار وما هم بخرجين منها ولهم عذاب مقيم', 'يريد ان يخرج من نر وم هم بخرج من لهم عذب مقيم', 'quran', NULL, NULL, 'https://quran.com/5/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (706, 'يري ريد يدو دون ان يخر خرج رجو من الن لنر وم هم بخر خرج رجي جين منه وله لهم عذب مقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (707, 'quran:5:38', 'quran', 'quran', '5:38', 38, 706, 'Al-Ma''idah', 'المائدة', 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ', NULL, NULL, 'والسارق والسارقه فاقطعوا ايديهما جزاء بما كسبا نكلا من الله والله عزيز حكيم', 'سرق سرق اقطع ايديهم جزء بم كسب نكل من له له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/5/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (707, 'ولس لسر سرق ولس لسر سرق رقه فقط قطع طعو ايد يدي ديه يهم جزء بم كسب نكل من الل لله ولل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (708, 'quran:5:39', 'quran', 'quran', '5:39', 39, 707, 'Al-Ma''idah', 'المائدة', 'فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', NULL, NULL, 'فمن تاب من بعد ظلمه واصلح فان الله يتوب عليه ان الله غفور رحيم', 'فمن تب من بعد ظلم اصلح فن له يتوب عل ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/5/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (708, 'فمن تب من بعد ظلم لمه وصل صلح فن الل لله يتو توب علي ليه ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (709, 'quran:5:40', 'quran', 'quran', '5:40', 40, 708, 'Al-Ma''idah', 'المائدة', 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'الم تعلم ان الله له ملك السموت والارض يعذب من يشاء ويغفر لمن يشاء والله علي كل شيء قدير', 'الم تعلم ان له له ملك سموت ارض يعذب من يشء يغفر لمن يشء له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/5/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (709, 'الم تعل علم ان الل لله له ملك الس لسم سمو موت ولر لرض يعذ عذب من يشء ويغ يغف غفر لمن يشء ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (710, 'quran:5:41', 'quran', 'quran', '5:41', 41, 709, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّٰعُونَ لِلۡكَذِبِ سَمَّٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ', NULL, NULL, 'يا ايها الرسول لا يحزنك الذين يسرعون في الكفر من الذين قالوا امنا بافوههم ولم تومن قلوبهم ومن الذين هادوا سمعون للكذب سمعون لقوم اخرين لم ياتوك يحرفون الكلم من بعد مواضعه يقولون ان اوتيتم هذا فخذوه وان لم توتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيا اوليك الذين لم يرد الله ان يطهر قلوبهم لهم في الدنيا خزي ولهم في الاخره عذاب عظيم', 'ي اي رسول ل يحزنك ذين يسرع في كفر من ذين قل ام بفوه ولم تومن قلوب ومن ذين هد سمع كذب سمع لقوم اخر لم يتوك يحرف كلم من بعد موضع يقول ان اوتيتم هذ خذو ون لم توتو احذر ومن يرد له تنت فلن تملك له من له شي اوليك ذين لم يرد له ان يطهر قلوب لهم في دني خز لهم في اخر عذب عظيم', 'quran', NULL, NULL, 'https://quran.com/5/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (710, 'ي ايه الر لرس رسو سول ل يحز حزن زنك الذ لذي ذين يسر سرع رعو عون في الك لكف كفر من الذ لذي ذين قلو امن بفو فوه وهه ههم ولم توم ومن قلو لوب وبه بهم ومن الذ لذي ذين هدو سمع معو عون للك لكذ كذب سمع معو عون لقو قوم اخر خري رين لم يتو توك يحر حرف رفو فون الك لكل كلم من بعد موض وضع ضعه يقو قول ولو لون ان اوت وتي تيت يتم هذ فخذ خذو ذوه ون لم توت وتو توه فحذ حذر ذرو ومن يرد الل لله فتن تنت نته فلن تمل ملك له من الل لله شي اول ولي ليك الذ لذي ذين لم يرد الل لله ان يطه طهر قلو لوب وبه بهم لهم في الد لدن دني خزي وله لهم في الخ لخر خره عذب عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (711, 'quran:5:42', 'quran', 'quran', '5:42', 42, 710, 'Al-Ma''idah', 'المائدة', 'سَمَّٰعُونَ لِلۡكَذِبِ أَكَّٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ', NULL, NULL, 'سمعون للكذب اكلون للسحت فان جاءوك فاحكم بينهم او اعرض عنهم وان تعرض عنهم فلن يضروك شيا وان حكمت فاحكم بينهم بالقسط ان الله يحب المقسطين', 'سمع كذب اكل سحت فن جءوك اح بين او اعرض عن ون تعرض عن فلن يضروك شي ون حكمت اح بين قسط ان له يحب مقسط', 'quran', NULL, NULL, 'https://quran.com/5/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (711, 'سمع معو عون للك لكذ كذب اكل كلو لون للس لسح سحت فن جءو ءوك فحك حكم بين ينه نهم او اعر عرض عنه نهم ون تعر عرض عنه نهم فلن يضر ضرو روك شي ون حكم كمت فحك حكم بين ينه نهم بلق لقس قسط ان الل لله يحب الم لمق مقس قسط سطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (712, 'quran:5:43', 'quran', 'quran', '5:43', 43, 711, 'Al-Ma''idah', 'المائدة', 'وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ', NULL, NULL, 'وكيف يحكمونك وعندهم التوراه فيها حكم الله ثم يتولون من بعد ذلك وما اوليك بالمومنين', 'كيف يحكمونك عند تور يه حكم له ثم يتول من بعد ذلك وم اوليك مومن', 'quran', NULL, NULL, 'https://quran.com/5/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (712, 'وكي كيف يحك حكم كمو مون ونك وعن عند نده دهم الت لتو تور وره فيه حكم الل لله ثم يتو تول ولو لون من بعد ذلك وم اول ولي ليك بلم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (713, 'quran:5:44', 'quran', 'quran', '5:44', 44, 712, 'Al-Ma''idah', 'المائدة', 'إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ', NULL, NULL, 'انا انزلنا التوراه فيها هدي ونور يحكم بها النبيون الذين اسلموا للذين هادوا والربنيون والاحبار بما استحفظوا من كتب الله وكانوا عليه شهداء فلا تخشوا الناس واخشون ولا تشتروا بايتي ثمنا قليلا ومن لم يحكم بما انزل الله فاوليك هم الكفرون', 'ان انزل تور يه هد نور يح به نبي ذين اسلم ذين هد ربني احبر بم استحفظ من كتب له كن عل شهدء فل تخش نس اخش ول تشتر بيت ثم قليل ومن لم يح بم انزل له اوليك هم كفر', 'quran', NULL, NULL, 'https://quran.com/5/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (713, 'ان انز نزل زلن الت لتو تور وره فيه هدي ونو نور يحك حكم به الن لنب نبي بيو يون الذ لذي ذين اسل سلم لمو للذ لذي ذين هدو ولر لرب ربن بني نيو يون ولح لحب حبر بم است ستح تحف حفظ فظو من كتب الل لله وكن كنو علي ليه شهد هدء فل تخش خشو الن لنس وخش خشو شون ول تشت شتر ترو بيت يتي ثمن قلي ليل ومن لم يحك حكم بم انز نزل الل لله فول ولي ليك هم الك لكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (714, 'quran:5:45', 'quran', 'quran', '5:45', 45, 713, 'Al-Ma''idah', 'المائدة', 'وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'وكتبنا عليهم فيها ان النفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفاره له ومن لم يحكم بما انزل الله فاوليك هم الظلمون', 'كتب علي يه ان نفس نفس عين عين انف انف اذن اذن سن سن جروح قصص فمن تصدق به فهو كفر له ومن لم يح بم انزل له اوليك هم ظلم', 'quran', NULL, NULL, 'https://quran.com/5/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (714, 'وكت كتب تبن علي ليه يهم فيه ان الن لنف نفس بلن لنف نفس ولع لعي عين بلع لعي عين ولن لنف بلن لنف ولذ لذن بلذ لذن ولس لسن بلس لسن ولج لجر جرو روح قصص فمن تصد صدق به فهو كفر فره له ومن لم يحك حكم بم انز نزل الل لله فول ولي ليك هم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (715, 'quran:5:46', 'quran', 'quran', '5:46', 46, 714, 'Al-Ma''idah', 'المائدة', 'وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ', NULL, NULL, 'وقفينا علي اثرهم بعيسي ابن مريم مصدقا لما بين يديه من التوراه واتينه الانجيل فيه هدي ونور ومصدقا لما بين يديه من التوراه وهدي وموعظه للمتقين', 'قفي عل اثر بعيس ابن مريم مصدق لم بين يد من تور اتين انجيل في هد نور مصدق لم بين يد من تور هد موعظ متق', 'quran', NULL, NULL, 'https://quran.com/5/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (715, 'وقف قفي فين علي اثر ثره رهم بعي عيس يسي ابن مري ريم مصد صدق لم بين يدي ديه من الت لتو تور وره وتي تين ينه الن لنج نجي جيل فيه هدي ونو نور ومص مصد صدق لم بين يدي ديه من الت لتو تور وره وهد هدي ومو موع وعظ عظه للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (716, 'quran:5:47', 'quran', 'quran', '5:47', 47, 715, 'Al-Ma''idah', 'المائدة', 'وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', NULL, NULL, 'وليحكم اهل الانجيل بما انزل الله فيه ومن لم يحكم بما انزل الله فاوليك هم الفسقون', 'ليح اهل انجيل بم انزل له في ومن لم يح بم انزل له اوليك هم فسق', 'quran', NULL, NULL, 'https://quran.com/5/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (716, 'ولي ليح يحك حكم اهل الن لنج نجي جيل بم انز نزل الل لله فيه ومن لم يحك حكم بم انز نزل الل لله فول ولي ليك هم الف لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (717, 'quran:5:48', 'quran', 'quran', '5:48', 48, 716, 'Al-Ma''idah', 'المائدة', 'وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', NULL, NULL, 'وانزلنا اليك الكتب بالحق مصدقا لما بين يديه من الكتب ومهيمنا عليه فاحكم بينهم بما انزل الله ولا تتبع اهواءهم عما جاءك من الحق لكل جعلنا منكم شرعه ومنهاجا ولو شاء الله لجعلكم امه وحده ولكن ليبلوكم في ما اتاكم فاستبقوا الخيرت الي الله مرجعكم جميعا فينبيكم بما كنتم فيه تختلفون', 'انزل يك كتب حق مصدق لم بين يد من كتب مهيم عل اح بين بم انزل له ول تتبع اهوء عم جءك من حق لكل جعل من شرع منهج ولو شء له لجعل ام حد لكن ليبلو في م ات استبق خيرت ال له مرجع جميع ينبي بم كنتم في تختلف', 'quran', NULL, NULL, 'https://quran.com/5/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (717, 'ونز نزل زلن الي ليك الك لكت كتب بلح لحق مصد صدق لم بين يدي ديه من الك لكت كتب ومه مهي هيم يمن علي ليه فحك حكم بين ينه نهم بم انز نزل الل لله ول تتب تبع اهو هوء وءه ءهم عم جءك من الح لحق لكل جعل علن منك نكم شرع رعه ومن منه نهج ولو شء الل لله لجع جعل علك لكم امه وحد حده ولك لكن ليب يبل بلو لوك وكم في م اتك تكم فست ستب تبق بقو الخ لخي خير يرت الي الل لله مرج رجع جعك عكم جمي ميع فين ينب نبي بيك يكم بم كنت نتم فيه تخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (718, 'quran:5:49', 'quran', 'quran', '5:49', 49, 717, 'Al-Ma''idah', 'المائدة', 'وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', NULL, NULL, 'وان احكم بينهم بما انزل الله ولا تتبع اهواءهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك فان تولوا فاعلم انما يريد الله ان يصيبهم ببعض ذنوبهم وان كثيرا من الناس لفسقون', 'ون اح بين بم انزل له ول تتبع اهوء احذر ان يفتنوك عن بعض م انزل له يك فن تول اعلم انم يريد له ان يصيب ببعض ذنوب ون كثير من نس لفسق', 'quran', NULL, NULL, 'https://quran.com/5/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (718, 'ون احك حكم بين ينه نهم بم انز نزل الل لله ول تتب تبع اهو هوء وءه ءهم وحذ حذر ذره رهم ان يفت فتن تنو نوك عن بعض م انز نزل الل لله الي ليك فن تول ولو فعل علم انم يري ريد الل لله ان يصي صيب يبه بهم ببع بعض ذنو نوب وبه بهم ون كثي ثير من الن لنس لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (719, 'quran:5:50', 'quran', 'quran', '5:50', 50, 718, 'Al-Ma''idah', 'المائدة', 'أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ', NULL, NULL, 'افحكم الجهليه يبغون ومن احسن من الله حكما لقوم يوقنون', 'افح جهل يبغ ومن احسن من له حكم لقوم يوقن', 'quran', NULL, NULL, 'https://quran.com/5/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (719, 'افح فحك حكم الج لجه جهل هلي ليه يبغ بغو غون ومن احس حسن من الل لله حكم لقو قوم يوق وقن قنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (720, 'quran:5:51', 'quran', 'quran', '5:51', 51, 719, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ', NULL, NULL, 'يا ايها الذين امنوا لا تتخذوا اليهود والنصري اولياء بعضهم اولياء بعض ومن يتولهم منكم فانه منهم ان الله لا يهدي القوم الظلمين', 'ي اي ذين امن ل تتخذ يهود نصر اوليء بعض اوليء بعض ومن يتول من ان من ان له ل يهد قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/5/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (720, 'ي ايه الذ لذي ذين امن منو ل تتخ تخذ خذو الي ليه يهو هود ولن لنص نصر صري اول ولي ليء بعض عضه ضهم اول ولي ليء بعض ومن يتو تول وله لهم منك نكم فنه منه نهم ان الل لله ل يهد هدي الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (721, 'quran:5:52', 'quran', 'quran', '5:52', 52, 720, 'Al-Ma''idah', 'المائدة', 'فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ', NULL, NULL, 'فتري الذين في قلوبهم مرض يسرعون فيهم يقولون نخشي ان تصيبنا دايره فعسي الله ان ياتي بالفتح او امر من عنده فيصبحوا علي ما اسروا في انفسهم ندمين', 'تر ذين في قلوب مرض يسرع يهم يقول نخش ان تصيب دير عس له ان يت فتح او امر من عند يصبح عل م اسر في انفس ندم', 'quran', NULL, NULL, 'https://quran.com/5/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (721, 'فتر تري الذ لذي ذين في قلو لوب وبه بهم مرض يسر سرع رعو عون فيه يهم يقو قول ولو لون نخش خشي ان تصي صيب يبن دير يره فعس عسي الل لله ان يتي بلف لفت فتح او امر من عند نده فيص يصب صبح بحو علي م اسر سرو في انف نفس فسه سهم ندم دمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (722, 'quran:5:53', 'quran', 'quran', '5:53', 53, 721, 'Al-Ma''idah', 'المائدة', 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ', NULL, NULL, 'ويقول الذين امنوا اهولاء الذين اقسموا بالله جهد ايمنهم انهم لمعكم حبطت اعملهم فاصبحوا خسرين', 'يقول ذين امن اهولء ذين اقسم له جهد ايمن ان لمع حبطت اعمل اصبح خسر', 'quran', NULL, NULL, 'https://quran.com/5/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (722, 'ويق يقو قول الذ لذي ذين امن منو اهو هول ولء الذ لذي ذين اقس قسم سمو بلل لله جهد ايم يمن منه نهم انه نهم لمع معك عكم حبط بطت اعم عمل مله لهم فصب صبح بحو خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (723, 'quran:5:54', 'quran', 'quran', '5:54', 54, 722, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', NULL, NULL, 'يا ايها الذين امنوا من يرتد منكم عن دينه فسوف ياتي الله بقوم يحبهم ويحبونه اذله علي المومنين اعزه علي الكفرين يجهدون في سبيل الله ولا يخافون لومه لايم ذلك فضل الله يوتيه من يشاء والله وسع عليم', 'ي اي ذين امن من يرتد من عن دين سوف يت له بقوم يحب يحبون اذل عل مومن اعز عل كفر يجهد في سبيل له ول يخف لوم ليم ذلك فضل له يوت من يشء له وسع عليم', 'quran', NULL, NULL, 'https://quran.com/5/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (723, 'ي ايه الذ لذي ذين امن منو من يرت رتد منك نكم عن دين ينه فسو سوف يتي الل لله بقو قوم يحب حبه بهم ويح يحب حبو بون ونه اذل ذله علي الم لمو موم ومن مني نين اعز عزه علي الك لكف كفر فري رين يجه جهد هدو دون في سبي بيل الل لله ول يخف خفو فون لوم ومه ليم ذلك فضل الل لله يوت وتي تيه من يشء ولل لله وسع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (724, 'quran:5:55', 'quran', 'quran', '5:55', 55, 723, 'Al-Ma''idah', 'المائدة', 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ', NULL, NULL, 'انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلاه ويوتون الزكاه وهم ركعون', 'انم لي له رسول ذين امن ذين يقيم صل يوت زك وهم ركع', 'quran', NULL, NULL, 'https://quran.com/5/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (724, 'انم ولي ليك يكم الل لله ورس رسو سول وله ولذ لذي ذين امن منو الذ لذي ذين يقي قيم يمو مون الص لصل صله ويو يوت وتو تون الز لزك زكه وهم ركع كعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (725, 'quran:5:56', 'quran', 'quran', '5:56', 56, 724, 'Al-Ma''idah', 'المائدة', 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ', NULL, NULL, 'ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغلبون', 'ومن يتول له رسول ذين امن فن حزب له هم غلب', 'quran', NULL, NULL, 'https://quran.com/5/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (725, 'ومن يتو تول الل لله ورس رسو سول وله ولذ لذي ذين امن منو فن حزب الل لله هم الغ لغل غلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (726, 'quran:5:57', 'quran', 'quran', '5:57', 57, 725, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'يا ايها الذين امنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين اوتوا الكتب من قبلكم والكفار اولياء واتقوا الله ان كنتم مومنين', 'ي اي ذين امن ل تتخذ ذين اتخذ دين هز لعب من ذين اوت كتب من قبل كفر اوليء اتق له ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/5/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (726, 'ي ايه الذ لذي ذين امن منو ل تتخ تخذ خذو الذ لذي ذين اتخ تخذ خذو دين ينك نكم هزو ولع لعب من الذ لذي ذين اوت وتو الك لكت كتب من قبل بلك لكم ولك لكف كفر اول ولي ليء وتق تقو الل لله ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (727, 'quran:5:58', 'quran', 'quran', '5:58', 58, 726, 'Al-Ma''idah', 'المائدة', 'وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ', NULL, NULL, 'واذا ناديتم الي الصلاه اتخذوها هزوا ولعبا ذلك بانهم قوم لا يعقلون', 'اذ نديتم ال صل اتخذو هز لعب ذلك بن قوم ل يعقل', 'quran', NULL, NULL, 'https://quran.com/5/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (727, 'وذ ندي ديت يتم الي الص لصل صله اتخ تخذ خذو ذوه هزو ولع لعب ذلك بنه نهم قوم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (728, 'quran:5:59', 'quran', 'quran', '5:59', 59, 727, 'Al-Ma''idah', 'المائدة', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ', NULL, NULL, 'قل يا اهل الكتب هل تنقمون منا الا ان امنا بالله وما انزل الينا وما انزل من قبل وان اكثركم فسقون', 'قل ي اهل كتب هل تنقم من ال ان ام له وم انزل ين وم انزل من قبل ون اكثر سق', 'quran', NULL, NULL, 'https://quran.com/5/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (728, 'قل ي اهل الك لكت كتب هل تنق نقم قمو مون من ال ان امن بلل لله وم انز نزل الي لين وم انز نزل من قبل ون اكث كثر ثرك ركم فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (729, 'quran:5:60', 'quran', 'quran', '5:60', 60, 728, 'Al-Ma''idah', 'المائدة', 'قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', NULL, NULL, 'قل هل انبيكم بشر من ذلك مثوبه عند الله من لعنه الله وغضب عليه وجعل منهم القرده والخنازير وعبد الطغوت اوليك شر مكانا واضل عن سواء السبيل', 'قل هل انبي بشر من ذلك مثوب عند له من لعن له غضب عل جعل من قرد خنزير عبد طغوت اوليك شر مك اضل عن سوء سبيل', 'quran', NULL, NULL, 'https://quran.com/5/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (729, 'قل هل انب نبي بيك يكم بشر من ذلك مثو ثوب وبه عند الل لله من لعن عنه الل لله وغض غضب علي ليه وجع جعل منه نهم الق لقر قرد رده ولخ لخن خنز نزي زير وعب عبد الط لطغ طغو غوت اول ولي ليك شر مكن وضل عن سوء الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (730, 'quran:5:61', 'quran', 'quran', '5:61', 61, 729, 'Al-Ma''idah', 'المائدة', 'وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ', NULL, NULL, 'واذا جاءوكم قالوا امنا وقد دخلوا بالكفر وهم قد خرجوا به والله اعلم بما كانوا يكتمون', 'اذ جءو قل ام وقد دخل كفر وهم قد خرج به له اعلم بم كن يكتم', 'quran', NULL, NULL, 'https://quran.com/5/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (730, 'وذ جءو ءوك وكم قلو امن وقد دخل خلو بلك لكف كفر وهم قد خرج رجو به ولل لله اعل علم بم كنو يكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (731, 'quran:5:62', 'quran', 'quran', '5:62', 62, 730, 'Al-Ma''idah', 'المائدة', 'وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'وتري كثيرا منهم يسرعون في الاثم والعدون واكلهم السحت لبيس ما كانوا يعملون', 'تر كثير من يسرع في اثم عد اكل سحت لبيس م كن يعمل', 'quran', NULL, NULL, 'https://quran.com/5/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (731, 'وتر تري كثي ثير منه نهم يسر سرع رعو عون في الث لثم ولع لعد عدو دون وكل كله لهم الس لسح سحت لبي بيس م كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (732, 'quran:5:63', 'quran', 'quran', '5:63', 63, 731, 'Al-Ma''idah', 'المائدة', 'لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ', NULL, NULL, 'لولا ينهاهم الربنيون والاحبار عن قولهم الاثم واكلهم السحت لبيس ما كانوا يصنعون', 'لول ينه ربني احبر عن قول اثم اكل سحت لبيس م كن يصنع', 'quran', NULL, NULL, 'https://quran.com/5/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (732, 'لول ينه نهه ههم الر لرب ربن بني نيو يون ولح لحب حبر عن قول وله لهم الث لثم وكل كله لهم الس لسح سحت لبي بيس م كنو يصن صنع نعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (733, 'quran:5:64', 'quran', 'quran', '5:64', 64, 732, 'Al-Ma''idah', 'المائدة', 'وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ', NULL, NULL, 'وقالت اليهود يد الله مغلوله غلت ايديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا والقينا بينهم العدوه والبغضاء الي يوم القيمه كلما اوقدوا نارا للحرب اطفاها الله ويسعون في الارض فسادا والله لا يحب المفسدين', 'قلت يهود يد له مغلول غلت ايدي لعن بم قل بل يد مبسوطت ينفق كيف يشء ليزيدن كثير من م انزل يك من ربك طغي كفر قي بين عدو بغضء ال يوم قيم كلم اوقد نر حرب اطف له يسع في ارض سد له ل يحب مفسد', 'quran', NULL, NULL, 'https://quran.com/5/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (733, 'وقل قلت الي ليه يهو هود يد الل لله مغل غلو لول وله غلت ايد يدي ديه يهم ولع لعن عنو بم قلو بل يده مبس بسو سوط وطت طتن ينف نفق كيف يشء ولي ليز يزي زيد يدن كثي ثير منه نهم م انز نزل الي ليك من ربك طغي غين وكف كفر ولق لقي قين بين ينه نهم الع لعد عدو دوه ولب لبغ بغض غضء الي يوم الق لقي قيم يمه كلم اوق وقد قدو نر للح لحر حرب اطف طفه الل لله ويس يسع سعو عون في الر لرض فسد ولل لله ل يحب الم لمف مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (734, 'quran:5:65', 'quran', 'quran', '5:65', 65, 733, 'Al-Ma''idah', 'المائدة', 'وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّٰتِ ٱلنَّعِيمِ', NULL, NULL, 'ولو ان اهل الكتب امنوا واتقوا لكفرنا عنهم سياتهم ولادخلنهم جنت النعيم', 'ولو ان اهل كتب امن اتق لكفر عن سيت لدخلن جنت نعيم', 'quran', NULL, NULL, 'https://quran.com/5/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (734, 'ولو ان اهل الك لكت كتب امن منو وتق تقو لكف كفر فرن عنه نهم سيت يته تهم ولد لدخ دخل خلن لنه نهم جنت الن لنع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (735, 'quran:5:66', 'quran', 'quran', '5:66', 66, 734, 'Al-Ma''idah', 'المائدة', 'وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ', NULL, NULL, 'ولو انهم اقاموا التوراه والانجيل وما انزل اليهم من ربهم لاكلوا من فوقهم ومن تحت ارجلهم منهم امه مقتصده وكثير منهم ساء ما يعملون', 'ولو ان اقم تور انجيل وم انزل يهم من رب لكل من وق ومن تحت ارجل من ام مقتصد كثير من سء م يعمل', 'quran', NULL, NULL, 'https://quran.com/5/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (735, 'ولو انه نهم اقم قمو الت لتو تور وره ولن لنج نجي جيل وم انز نزل الي ليه يهم من ربه بهم لكل كلو من فوق وقه قهم ومن تحت ارج رجل جله لهم منه نهم امه مقت قتص تصد صده وكث كثي ثير منه نهم سء م يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (736, 'quran:5:67', 'quran', 'quran', '5:67', 67, 735, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'يا ايها الرسول بلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته والله يعصمك من الناس ان الله لا يهدي القوم الكفرين', 'ي اي رسول بلغ م انزل يك من ربك ون لم تفعل فم بلغت رسلت له يعصمك من نس ان له ل يهد قوم كفر', 'quran', NULL, NULL, 'https://quran.com/5/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (736, 'ي ايه الر لرس رسو سول بلغ م انز نزل الي ليك من ربك ون لم تفع فعل فم بلغ لغت رسل سلت لته ولل لله يعص عصم صمك من الن لنس ان الل لله ل يهد هدي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (737, 'quran:5:68', 'quran', 'quran', '5:68', 68, 736, 'Al-Ma''idah', 'المائدة', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', NULL, NULL, 'قل يا اهل الكتب لستم علي شيء حتي تقيموا التوراه والانجيل وما انزل اليكم من ربكم وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا فلا تاس علي القوم الكفرين', 'قل ي اهل كتب لستم عل شيء حت تقيم تور انجيل وم انزل يكم من رب ليزيدن كثير من م انزل يك من ربك طغي كفر فل تس عل قوم كفر', 'quran', NULL, NULL, 'https://quran.com/5/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (737, 'قل ي اهل الك لكت كتب لست ستم علي شيء حتي تقي قيم يمو الت لتو تور وره ولن لنج نجي جيل وم انز نزل الي ليك يكم من ربك بكم ولي ليز يزي زيد يدن كثي ثير منه نهم م انز نزل الي ليك من ربك طغي غين وكف كفر فل تس علي الق لقو قوم الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (738, 'quran:5:69', 'quran', 'quran', '5:69', 69, 737, 'Al-Ma''idah', 'المائدة', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'ان الذين امنوا والذين هادوا والصبون والنصري من امن بالله واليوم الاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون', 'ان ذين امن ذين هد صب نصر من امن له يوم اخر عمل صلح فل خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/5/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (738, 'ان الذ لذي ذين امن منو ولذ لذي ذين هدو ولص لصب صبو بون ولن لنص نصر صري من امن بلل لله ولي ليو يوم الخ لخر وعم عمل صلح فل خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (739, 'quran:5:70', 'quran', 'quran', '5:70', 70, 738, 'Al-Ma''idah', 'المائدة', 'لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ', NULL, NULL, 'لقد اخذنا ميثق بني اسرءيل وارسلنا اليهم رسلا كلما جاءهم رسول بما لا تهوي انفسهم فريقا كذبوا وفريقا يقتلون', 'لقد اخذ ميثق بن اسرءيل ارسل يهم رسل كلم جء رسول بم ل تهو انفس ريق كذب فريق يقتل', 'quran', NULL, NULL, 'https://quran.com/5/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (739, 'لقد اخذ خذن ميث يثق بني اسر سرء رءي ءيل ورس رسل سلن الي ليه يهم رسل كلم جءه ءهم رسو سول بم ل تهو هوي انف نفس فسه سهم فري ريق كذب ذبو وفر فري ريق يقت قتل تلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (740, 'quran:5:71', 'quran', 'quran', '5:71', 71, 739, 'Al-Ma''idah', 'المائدة', 'وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', NULL, NULL, 'وحسبوا الا تكون فتنه فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون', 'حسب ال تك تن عم صم ثم تب له علي ثم عم صم كثير من له بصير بم يعمل', 'quran', NULL, NULL, 'https://quran.com/5/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (740, 'وحس حسب سبو ال تكو كون فتن تنه فعم عمو وصم صمو ثم تب الل لله علي ليه يهم ثم عمو وصم صمو كثي ثير منه نهم ولل لله بصي صير بم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (741, 'quran:5:72', 'quran', 'quran', '5:72', 72, 740, 'Al-Ma''idah', 'المائدة', 'لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ', NULL, NULL, 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم وقال المسيح يا بني اسرءيل اعبدوا الله ربي وربكم انه من يشرك بالله فقد حرم الله عليه الجنه وماواه النار وما للظلمين من انصار', 'لقد كفر ذين قل ان له هو مسيح ابن مريم قل مسيح ي بن اسرءيل اعبد له رب رب ان من يشرك له فقد حرم له عل جن مو نر وم ظلم من انصر', 'quran', NULL, NULL, 'https://quran.com/5/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (741, 'لقد كفر الذ لذي ذين قلو ان الل لله هو الم لمس مسي سيح ابن مري ريم وقل الم لمس مسي سيح ي بني اسر سرء رءي ءيل اعب عبد بدو الل لله ربي ورب ربك بكم انه من يشر شرك بلل لله فقد حرم الل لله علي ليه الج لجن جنه ومو موه الن لنر وم للظ لظل ظلم لمي مين من انص نصر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (742, 'quran:5:73', 'quran', 'quran', '5:73', 73, 741, 'Al-Ma''idah', 'المائدة', 'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ', NULL, NULL, 'لقد كفر الذين قالوا ان الله ثالث ثلثه وما من اله الا اله وحد وان لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب اليم', 'لقد كفر ذين قل ان له ثلث ثلث وم من ال ال ال وحد ون لم ينته عم يقول ليمسن ذين كفر من عذب يم', 'quran', NULL, NULL, 'https://quran.com/5/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (742, 'لقد كفر الذ لذي ذين قلو ان الل لله ثلث ثلث لثه وم من اله ال اله وحد ون لم ينت نته تهو عم يقو قول ولو لون ليم يمس مسن الذ لذي ذين كفر فرو منه نهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (743, 'quran:5:74', 'quran', 'quran', '5:74', 74, 742, 'Al-Ma''idah', 'المائدة', 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'افلا يتوبون الي الله ويستغفرونه والله غفور رحيم', 'افل يتوب ال له يستغفرون له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/5/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (743, 'افل يتو توب وبو بون الي الل لله ويس يست ستغ تغف غفر فرو رون ونه ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (744, 'quran:5:75', 'quran', 'quran', '5:75', 75, 743, 'Al-Ma''idah', 'المائدة', 'مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ', NULL, NULL, 'ما المسيح ابن مريم الا رسول قد خلت من قبله الرسل وامه صديقه كانا ياكلان الطعام انظر كيف نبين لهم الايت ثم انظر اني يوفكون', 'م مسيح ابن مريم ال رسول قد خلت من قبل رسل ام صديق ك يكل طعم انظر كيف نب لهم ايت ثم انظر ان يوفك', 'quran', NULL, NULL, 'https://quran.com/5/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (744, 'م الم لمس مسي سيح ابن مري ريم ال رسو سول قد خلت من قبل بله الر لرس رسل ومه صدي ديق يقه كن يكل كلن الط لطع طعم انظ نظر كيف نبي بين لهم الي ليت ثم انظ نظر اني يوف وفك فكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (745, 'quran:5:76', 'quran', 'quran', '5:76', 76, 744, 'Al-Ma''idah', 'المائدة', 'قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'قل اتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم', 'قل اتعبد من دون له م ل يملك لكم ضر ول نفع له هو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/5/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (745, 'قل اتع تعب عبد بدو دون من دون الل لله م ل يمل ملك لكم ضر ول نفع ولل لله هو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (746, 'quran:5:77', 'quran', 'quran', '5:77', 77, 745, 'Al-Ma''idah', 'المائدة', 'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ', NULL, NULL, 'قل يا اهل الكتب لا تغلوا في دينكم غير الحق ولا تتبعوا اهواء قوم قد ضلوا من قبل واضلوا كثيرا وضلوا عن سواء السبيل', 'قل ي اهل كتب ل تغل في دين غير حق ول تتبع اهوء قوم قد ضل من قبل اضل كثير ضل عن سوء سبيل', 'quran', NULL, NULL, 'https://quran.com/5/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (746, 'قل ي اهل الك لكت كتب ل تغل غلو في دين ينك نكم غير الح لحق ول تتب تبع بعو اهو هوء قوم قد ضلو من قبل وضل ضلو كثي ثير وضل ضلو عن سوء الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (747, 'quran:5:78', 'quran', 'quran', '5:78', 78, 746, 'Al-Ma''idah', 'المائدة', 'لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', NULL, NULL, 'لعن الذين كفروا من بني اسرءيل علي لسان داود وعيسي ابن مريم ذلك بما عصوا وكانوا يعتدون', 'لعن ذين كفر من بن اسرءيل عل لس دود عيس ابن مريم ذلك بم عص كن يعتد', 'quran', NULL, NULL, 'https://quran.com/5/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (747, 'لعن الذ لذي ذين كفر فرو من بني اسر سرء رءي ءيل علي لسن دود وعي عيس يسي ابن مري ريم ذلك بم عصو وكن كنو يعت عتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (748, 'quran:5:79', 'quran', 'quran', '5:79', 79, 747, 'Al-Ma''idah', 'المائدة', 'كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ', NULL, NULL, 'كانوا لا يتناهون عن منكر فعلوه لبيس ما كانوا يفعلون', 'كن ل يتنه عن منكر علو لبيس م كن يفعل', 'quran', NULL, NULL, 'https://quran.com/5/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (748, 'كنو ل يتن تنه نهو هون عن منك نكر فعل علو لوه لبي بيس م كنو يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (749, 'quran:5:80', 'quran', 'quran', '5:80', 80, 748, 'Al-Ma''idah', 'المائدة', 'تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ', NULL, NULL, 'تري كثيرا منهم يتولون الذين كفروا لبيس ما قدمت لهم انفسهم ان سخط الله عليهم وفي العذاب هم خلدون', 'تر كثير من يتول ذين كفر لبيس م قدمت لهم انفس ان سخط له علي وف عذب هم خلد', 'quran', NULL, NULL, 'https://quran.com/5/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (749, 'تري كثي ثير منه نهم يتو تول ولو لون الذ لذي ذين كفر فرو لبي بيس م قدم دمت لهم انف نفس فسه سهم ان سخط الل لله علي ليه يهم وفي الع لعذ عذب هم خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (750, 'quran:5:81', 'quran', 'quran', '5:81', 81, 749, 'Al-Ma''idah', 'المائدة', 'وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ', NULL, NULL, 'ولو كانوا يومنون بالله والنبي وما انزل اليه ما اتخذوهم اولياء ولكن كثيرا منهم فسقون', 'ولو كن يومن له نب وم انزل يه م اتخذو اوليء لكن كثير من سق', 'quran', NULL, NULL, 'https://quran.com/5/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (750, 'ولو كنو يوم ومن منو نون بلل لله ولن لنب نبي وم انز نزل الي ليه م اتخ تخذ خذو ذوه وهم اول ولي ليء ولك لكن كثي ثير منه نهم فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (751, 'quran:5:82', 'quran', 'quran', '5:82', 82, 750, 'Al-Ma''idah', 'المائدة', 'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ', NULL, NULL, 'لتجدن اشد الناس عدوه للذين امنوا اليهود والذين اشركوا ولتجدن اقربهم موده للذين امنوا الذين قالوا انا نصري ذلك بان منهم قسيسين ورهبانا وانهم لا يستكبرون', 'لتجدن اشد نس عدو ذين امن يهود ذين اشرك لتجدن اقرب مود ذين امن ذين قل ان نصر ذلك بن من قسيس رهب ان ل يستكبر', 'quran', NULL, NULL, 'https://quran.com/5/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (751, 'لتج تجد جدن اشد الن لنس عدو دوه للذ لذي ذين امن منو الي ليه يهو هود ولذ لذي ذين اشر شرك ركو ولت لتج تجد جدن اقر قرب ربه بهم مود وده للذ لذي ذين امن منو الذ لذي ذين قلو ان نصر صري ذلك بن منه نهم قسي سيس يسي سين وره رهب هبن ونه نهم ل يست ستك تكب كبر برو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (752, 'quran:5:83', 'quran', 'quran', '5:83', 83, 751, 'Al-Ma''idah', 'المائدة', 'وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ', NULL, NULL, 'واذا سمعوا ما انزل الي الرسول تري اعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا امنا فاكتبنا مع الشهدين', 'اذ سمع م انزل ال رسول تر اعين تفيض من دمع مم عرف من حق يقول رب ام اكتب مع شهد', 'quran', NULL, NULL, 'https://quran.com/5/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (752, 'وذ سمع معو م انز نزل الي الر لرس رسو سول تري اعي عين ينه نهم تفي فيض من الد لدم دمع مم عرف رفو من الح لحق يقو قول ولو لون ربن امن فكت كتب تبن مع الش لشه شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (753, 'quran:5:84', 'quran', 'quran', '5:84', 84, 752, 'Al-Ma''idah', 'المائدة', 'وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّٰلِحِينَ', NULL, NULL, 'وما لنا لا نومن بالله وما جاءنا من الحق ونطمع ان يدخلنا ربنا مع القوم الصلحين', 'وم لن ل نومن له وم جء من حق نطمع ان يدخل رب مع قوم صلح', 'quran', NULL, NULL, 'https://quran.com/5/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (753, 'وم لن ل نوم ومن بلل لله وم جءن من الح لحق ونط نطم طمع ان يدخ دخل خلن ربن مع الق لقو قوم الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (754, 'quran:5:85', 'quran', 'quran', '5:85', 85, 753, 'Al-Ma''idah', 'المائدة', 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'فاثبهم الله بما قالوا جنت تجري من تحتها الانهر خلدين فيها وذلك جزاء المحسنين', 'اثب له بم قل جنت تجر من تحت انهر خلد يه ذلك جزء محسن', 'quran', NULL, NULL, 'https://quran.com/5/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (754, 'فثب ثبه بهم الل لله بم قلو جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه وذل ذلك جزء الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (755, 'quran:5:86', 'quran', 'quran', '5:86', 86, 754, 'Al-Ma''idah', 'المائدة', 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', NULL, NULL, 'والذين كفروا وكذبوا بايتنا اوليك اصحب الجحيم', 'ذين كفر كذب بيت اوليك اصحب جحيم', 'quran', NULL, NULL, 'https://quran.com/5/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (755, 'ولذ لذي ذين كفر فرو وكذ كذب ذبو بيت يتن اول ولي ليك اصح صحب الج لجح جحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (756, 'quran:5:87', 'quran', 'quran', '5:87', 87, 755, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ', NULL, NULL, 'يا ايها الذين امنوا لا تحرموا طيبت ما احل الله لكم ولا تعتدوا ان الله لا يحب المعتدين', 'ي اي ذين امن ل تحرم طيبت م احل له لكم ول تعتد ان له ل يحب معتد', 'quran', NULL, NULL, 'https://quran.com/5/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (756, 'ي ايه الذ لذي ذين امن منو ل تحر حرم رمو طيب يبت م احل الل لله لكم ول تعت عتد تدو ان الل لله ل يحب الم لمع معت عتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (757, 'quran:5:88', 'quran', 'quran', '5:88', 88, 756, 'Al-Ma''idah', 'المائدة', 'وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ', NULL, NULL, 'وكلوا مما رزقكم الله حللا طيبا واتقوا الله الذي انتم به مومنون', 'كل مم رزق له حلل طيب اتق له ذي انتم به مومن', 'quran', NULL, NULL, 'https://quran.com/5/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (757, 'وكل كلو مم رزق زقك قكم الل لله حلل طيب وتق تقو الل لله الذ لذي انت نتم به موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (758, 'quran:5:89', 'quran', 'quran', '5:89', 89, 757, 'Al-Ma''idah', 'المائدة', 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه فمن لم يجد فصيام ثلثه ايام ذلك كفره ايمنكم اذا حلفتم واحفظوا ايمنكم كذلك يبين الله لكم ايته لعلكم تشكرون', 'ل يوخذ له لغو في ايمن لكن يوخذ بم عقدتم ايمن كفرت اطعم عشر مسك من اوسط م تطعم اهلي او كسوت او تحرير رقب فمن لم يجد صيم ثلث ايم ذلك كفر ايمن اذ حلفتم احفظ ايمن كذلك يب له لكم ايت لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/5/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (758, 'ل يوخ وخذ خذك ذكم الل لله بلل للغ لغو في ايم يمن منك نكم ولك لكن يوخ وخذ خذك ذكم بم عقد قدت دتم الي ليم يمن فكف كفر فرت رته اطع طعم عشر شره مسك سكي كين من اوس وسط م تطع طعم عمو مون اهل هلي ليك يكم او كسو سوت وته تهم او تحر حري رير رقب قبه فمن لم يجد فصي صيم ثلث لثه ايم ذلك كفر فره ايم يمن منك نكم اذ حلف لفت فتم وحف حفظ فظو ايم يمن منك نكم كذل ذلك يبي بين الل لله لكم ايت يته لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (759, 'quran:5:90', 'quran', 'quran', '5:90', 90, 758, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يا ايها الذين امنوا انما الخمر والميسر والانصاب والازلم رجس من عمل الشيطن فاجتنبوه لعلكم تفلحون', 'ي اي ذين امن انم خمر ميسر انصب ازلم رجس من عمل شيطن اجتنبو لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/5/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (759, 'ي ايه الذ لذي ذين امن منو انم الخ لخم خمر ولم لمي ميس يسر ولن لنص نصب ولز لزل زلم رجس من عمل الش لشي شيط يطن فجت جتن تنب نبو بوه لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (760, 'quran:5:91', 'quran', 'quran', '5:91', 91, 759, 'Al-Ma''idah', 'المائدة', 'إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ', NULL, NULL, 'انما يريد الشيطن ان يوقع بينكم العدوه والبغضاء في الخمر والميسر ويصدكم عن ذكر الله وعن الصلاه فهل انتم منتهون', 'انم يريد شيطن ان يوقع بين عدو بغضء في خمر ميسر يصد عن ذكر له وعن صل فهل انتم منته', 'quran', NULL, NULL, 'https://quran.com/5/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (760, 'انم يري ريد الش لشي شيط يطن ان يوق وقع بين ينك نكم الع لعد عدو دوه ولب لبغ بغض غضء في الخ لخم خمر ولم لمي ميس يسر ويص يصد صدك دكم عن ذكر الل لله وعن الص لصل صله فهل انت نتم منت نته تهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (761, 'quran:5:92', 'quran', 'quran', '5:92', 92, 760, 'Al-Ma''idah', 'المائدة', 'وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ', NULL, NULL, 'واطيعوا الله واطيعوا الرسول واحذروا فان توليتم فاعلموا انما علي رسولنا البلغ المبين', 'اطيع له اطيع رسول احذر فن توليتم اعلم انم عل رسول بلغ مب', 'quran', NULL, NULL, 'https://quran.com/5/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (761, 'وطي طيع يعو الل لله وطي طيع يعو الر لرس رسو سول وحذ حذر ذرو فن تول ولي ليت يتم فعل علم لمو انم علي رسو سول ولن الب لبل بلغ الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (762, 'quran:5:93', 'quran', 'quran', '5:93', 93, 761, 'Al-Ma''idah', 'المائدة', 'لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'ليس علي الذين امنوا وعملوا الصلحت جناح فيما طعموا اذا ما اتقوا وامنوا وعملوا الصلحت ثم اتقوا وامنوا ثم اتقوا واحسنوا والله يحب المحسنين', 'ليس عل ذين امن عمل صلحت جنح يم طعم اذ م اتق امن عمل صلحت ثم اتق امن ثم اتق احسن له يحب محسن', 'quran', NULL, NULL, 'https://quran.com/5/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (762, 'ليس علي الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت جنح فيم طعم عمو اذ م اتق تقو ومن منو وعم عمل ملو الص لصل صلح لحت ثم اتق تقو ومن منو ثم اتق تقو وحس حسن سنو ولل لله يحب الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (763, 'quran:5:94', 'quran', 'quran', '5:94', 94, 762, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا ليبلونكم الله بشيء من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدي بعد ذلك فله عذاب اليم', 'ي اي ذين امن ليبلون له بشيء من صيد تنل ايدي رمح ليعلم له من يخف غيب فمن اعتد بعد ذلك فل عذب يم', 'quran', NULL, NULL, 'https://quran.com/5/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (763, 'ي ايه الذ لذي ذين امن منو ليب يبل بلو لون ونك نكم الل لله بشي شيء من الص لصي صيد تنل نله ايد يدي ديك يكم ورم رمح محك حكم ليع يعل علم الل لله من يخف خفه بلغ لغي غيب فمن اعت عتد تدي بعد ذلك فله عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (764, 'quran:5:95', 'quran', 'quran', '5:95', 95, 763, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ', NULL, NULL, 'يا ايها الذين امنوا لا تقتلوا الصيد وانتم حرم ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بلغ الكعبه او كفره طعام مسكين او عدل ذلك صياما ليذوق وبال امره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام', 'ي اي ذين امن ل تقتل صيد انتم حرم ومن قتل من متعمد جزء مثل م قتل من نعم يح به ذو عدل من هدي بلغ كعب او كفر طعم مسك او عدل ذلك صيم ليذوق بل امر عف له عم سلف ومن عد ينتقم له من له عزيز ذو انتقم', 'quran', NULL, NULL, 'https://quran.com/5/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (764, 'ي ايه الذ لذي ذين امن منو ل تقت قتل تلو الص لصي صيد ونت نتم حرم ومن قتل تله منك نكم متع تعم عمد فجز جزء مثل م قتل من الن لنع نعم يحك حكم به ذو عدل منك نكم هدي بلغ الك لكع كعب عبه او كفر فره طعم مسك سكي كين او عدل ذلك صيم ليذ يذو ذوق وبل امر مره عف الل لله عم سلف ومن عد فين ينت نتق تقم الل لله منه ولل لله عزي زيز ذو انت نتق تقم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (765, 'quran:5:96', 'quran', 'quran', '5:96', 96, 764, 'Al-Ma''idah', 'المائدة', 'أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ', NULL, NULL, 'احل لكم صيد البحر وطعامه متعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي اليه تحشرون', 'احل لكم صيد بحر طعم متع لكم سير حرم علي صيد بر م دمتم حرم اتق له ذي يه تحشر', 'quran', NULL, NULL, 'https://quran.com/5/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (765, 'احل لكم صيد الب لبح بحر وطع طعم عمه متع لكم ولل للس لسي سير يره وحر حرم علي ليك يكم صيد الب لبر م دمت متم حرم وتق تقو الل لله الذ لذي الي ليه تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (766, 'quran:5:97', 'quran', 'quran', '5:97', 97, 765, 'Al-Ma''idah', 'المائدة', 'جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ', NULL, NULL, 'جعل الله الكعبه البيت الحرام قيما للناس والشهر الحرام والهدي والقليد ذلك لتعلموا ان الله يعلم ما في السموت وما في الارض وان الله بكل شيء عليم', 'جعل له كعب بيت حرم قيم نس شهر حرم هد قليد ذلك لتعلم ان له يعلم م في سموت وم في ارض ون له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/5/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (766, 'جعل الل لله الك لكع كعب عبه الب لبي بيت الح لحر حرم قيم للن لنس ولش لشه شهر الح لحر حرم وله لهد هدي ولق لقل قلي ليد ذلك لتع تعل علم لمو ان الل لله يعل علم م في الس لسم سمو موت وم في الر لرض ون الل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (767, 'quran:5:98', 'quran', 'quran', '5:98', 98, 766, 'Al-Ma''idah', 'المائدة', 'ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'اعلموا ان الله شديد العقاب وان الله غفور رحيم', 'اعلم ان له شديد عقب ون له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/5/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (767, 'اعل علم لمو ان الل لله شدي ديد الع لعق عقب ون الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (768, 'quran:5:99', 'quran', 'quran', '5:99', 99, 767, 'Al-Ma''idah', 'المائدة', 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ', NULL, NULL, 'ما علي الرسول الا البلغ والله يعلم ما تبدون وما تكتمون', 'م عل رسول ال بلغ له يعلم م تبد وم تكتم', 'quran', NULL, NULL, 'https://quran.com/5/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (768, 'م علي الر لرس رسو سول ال الب لبل بلغ ولل لله يعل علم م تبد بدو دون وم تكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (769, 'quran:5:100', 'quran', 'quran', '5:100', 100, 768, 'Al-Ma''idah', 'المائدة', 'قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'قل لا يستوي الخبيث والطيب ولو اعجبك كثره الخبيث فاتقوا الله يا اولي الالبب لعلكم تفلحون', 'قل ل يستو خبيث طيب ولو اعجبك كثر خبيث اتق له ي اول البب لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/5/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (769, 'قل ل يست ستو توي الخ لخب خبي بيث ولط لطي طيب ولو اعج عجب جبك كثر ثره الخ لخب خبي بيث فتق تقو الل لله ي اول ولي الل للب لبب لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (770, 'quran:5:101', 'quran', 'quran', '5:101', 101, 769, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا لا تسلوا عن اشياء ان تبد لكم تسوكم وان تسلوا عنها حين ينزل القران تبد لكم عفا الله عنها والله غفور حليم', 'ي اي ذين امن ل تسل عن اشيء ان تبد لكم تسو ون تسل عن حين ينزل قر تبد لكم عف له عن له غفور حليم', 'quran', NULL, NULL, 'https://quran.com/5/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (770, 'ي ايه الذ لذي ذين امن منو ل تسل سلو عن اشي شيء ان تبد لكم تسو سوك وكم ون تسل سلو عنه حين ينز نزل الق لقر قرن تبد لكم عف الل لله عنه ولل لله غفو فور حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (771, 'quran:5:102', 'quran', 'quran', '5:102', 102, 770, 'Al-Ma''idah', 'المائدة', 'قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ', NULL, NULL, 'قد سالها قوم من قبلكم ثم اصبحوا بها كفرين', 'قد سل قوم من قبل ثم اصبح به كفر', 'quran', NULL, NULL, 'https://quran.com/5/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (771, 'قد سله قوم من قبل بلك لكم ثم اصب صبح بحو به كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (772, 'quran:5:103', 'quran', 'quran', '5:103', 103, 771, 'Al-Ma''idah', 'المائدة', 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ', NULL, NULL, 'ما جعل الله من بحيره ولا سايبه ولا وصيله ولا حام ولكن الذين كفروا يفترون علي الله الكذب واكثرهم لا يعقلون', 'م جعل له من بحير ول سيب ول صيل ول حم لكن ذين كفر يفتر عل له كذب اكثر ل يعقل', 'quran', NULL, NULL, 'https://quran.com/5/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (772, 'م جعل الل لله من بحي حير يره ول سيب يبه ول وصي صيل يله ول حم ولك لكن الذ لذي ذين كفر فرو يفت فتر ترو رون علي الل لله الك لكذ كذب وكث كثر ثره رهم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (773, 'quran:5:104', 'quran', 'quran', '5:104', 104, 772, 'Al-Ma''idah', 'المائدة', 'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ', NULL, NULL, 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول قالوا حسبنا ما وجدنا عليه اباءنا اولو كان اباوهم لا يعلمون شيا ولا يهتدون', 'اذ قيل لهم تعل ال م انزل له ول رسول قل حسب م جد عل ابء اولو كن ابو ل يعلم شي ول يهتد', 'quran', NULL, NULL, 'https://quran.com/5/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (773, 'وذ قيل لهم تعل علو الي م انز نزل الل لله ولي الر لرس رسو سول قلو حسب سبن م وجد جدن علي ليه ابء بءن اول ولو كن ابو بوه وهم ل يعل علم لمو مون شي ول يهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (774, 'quran:5:105', 'quran', 'quran', '5:105', 105, 773, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'يا ايها الذين امنوا عليكم انفسكم لا يضركم من ضل اذا اهتديتم الي الله مرجعكم جميعا فينبيكم بما كنتم تعملون', 'ي اي ذين امن علي انفس ل يضر من ضل اذ اهتديتم ال له مرجع جميع ينبي بم كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/5/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (774, 'ي ايه الذ لذي ذين امن منو علي ليك يكم انف نفس فسك سكم ل يضر ضرك ركم من ضل اذ اهت هتد تدي ديت يتم الي الل لله مرج رجع جعك عكم جمي ميع فين ينب نبي بيك يكم بم كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (775, 'quran:5:106', 'quran', 'quran', '5:106', 106, 774, 'Al-Ma''idah', 'المائدة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ', NULL, NULL, 'يا ايها الذين امنوا شهده بينكم اذا حضر احدكم الموت حين الوصيه اثنان ذوا عدل منكم او اخران من غيركم ان انتم ضربتم في الارض فاصبتكم مصيبه الموت تحبسونهما من بعد الصلاه فيقسمان بالله ان ارتبتم لا نشتري به ثمنا ولو كان ذا قربي ولا نكتم شهده الله انا اذا لمن الاثمين', 'ي اي ذين امن شهد بين اذ حضر احد موت حين وص اثن ذو عدل من او اخر من غير ان انتم ضربتم في ارض اصبت مصيب موت تحبسونهم من بعد صل يقسم له ان ارتبتم ل نشتر به ثم ولو كن ذ قرب ول نكتم شهد له ان اذ لمن اثم', 'quran', NULL, NULL, 'https://quran.com/5/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (775, 'ي ايه الذ لذي ذين امن منو شهد هده بين ينك نكم اذ حضر احد حدك دكم الم لمو موت حين الو لوص وصي صيه اثن ثنن ذو عدل منك نكم او اخر خرن من غير يرك ركم ان انت نتم ضرب ربت بتم في الر لرض فصب صبت بتك تكم مصي صيب يبه الم لمو موت تحب حبس بسو سون ونه نهم من بعد الص لصل صله فيق يقس قسم سمن بلل لله ان ارت رتب تبت بتم ل نشت شتر تري به ثمن ولو كن ذ قرب ربي ول نكت كتم شهد هده الل لله ان اذ لمن الث لثم ثمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (776, 'quran:5:107', 'quran', 'quran', '5:107', 107, 775, 'Al-Ma''idah', 'المائدة', 'فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'فان عثر علي انهما استحقا اثما فاخران يقومان مقامهما من الذين استحق عليهم الاولين فيقسمان بالله لشهدتنا احق من شهدتهما وما اعتدينا انا اذا لمن الظلمين', 'فن عثر عل انهم استحق اثم اخر يقوم مقمهم من ذين استحق علي اول يقسم له لشهدت احق من شهدتهم وم اعتدي ان اذ لمن ظلم', 'quran', NULL, NULL, 'https://quran.com/5/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (776, 'فن عثر علي انه نهم است ستح تحق اثم فخر خرن يقو قوم ومن مقم قمه مهم من الذ لذي ذين است ستح تحق علي ليه يهم الو لول ولي لين فيق يقس قسم سمن بلل لله لشه شهد هدت دتن احق من شهد هدت دته تهم وم اعت عتد تدي دين ان اذ لمن الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (777, 'quran:5:108', 'quran', 'quran', '5:108', 108, 776, 'Al-Ma''idah', 'المائدة', 'ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ', NULL, NULL, 'ذلك ادني ان ياتوا بالشهده علي وجهها او يخافوا ان ترد ايمن بعد ايمنهم واتقوا الله واسمعوا والله لا يهدي القوم الفسقين', 'ذلك ادن ان يت شهد عل جه او يخف ان ترد ايمن بعد ايمن اتق له اسمع له ل يهد قوم فسق', 'quran', NULL, NULL, 'https://quran.com/5/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (777, 'ذلك ادن دني ان يتو بلش لشه شهد هده علي وجه جهه او يخف خفو ان ترد ايم يمن بعد ايم يمن منه نهم وتق تقو الل لله وسم سمع معو ولل لله ل يهد هدي الق لقو قوم الف لفس فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (778, 'quran:5:109', 'quran', 'quran', '5:109', 109, 777, 'Al-Ma''idah', 'المائدة', 'يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ', NULL, NULL, 'يوم يجمع الله الرسل فيقول ماذا اجبتم قالوا لا علم لنا انك انت علم الغيوب', 'يوم يجمع له رسل يقول مذ اجبتم قل ل علم لن انك انت علم غيوب', 'quran', NULL, NULL, 'https://quran.com/5/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (778, 'يوم يجم جمع الل لله الر لرس رسل فيق يقو قول مذ اجب جبت بتم قلو ل علم لن انك انت علم الغ لغي غيو يوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (779, 'quran:5:110', 'quran', 'quran', '5:110', 110, 778, 'Al-Ma''idah', 'المائدة', 'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ', NULL, NULL, 'اذ قال الله يا عيسي ابن مريم اذكر نعمتي عليك وعلي ولدتك اذ ايدتك بروح القدس تكلم الناس في المهد وكهلا واذ علمتك الكتب والحكمه والتوراه والانجيل واذ تخلق من الطين كهيه الطير باذني فتنفخ فيها فتكون طيرا باذني وتبري الاكمه والابرص باذني واذ تخرج الموتي باذني واذ كففت بني اسرءيل عنك اذ جيتهم بالبينت فقال الذين كفروا منهم ان هذا الا سحر مبين', 'اذ قل له ي عيس ابن مريم اذكر نعمت عليك عل لدتك اذ ايدتك بروح قدس تكلم نس في مهد كهل وذ علمتك كتب حكم تور انجيل وذ تخلق من طين كه طير بذن تنفخ يه تك طير بذن تبر اكم ابرص بذن وذ تخرج موت بذن وذ كففت بن اسرءيل عنك اذ جيت بينت قل ذين كفر من ان هذ ال سحر مب', 'quran', NULL, NULL, 'https://quran.com/5/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (779, 'اذ قل الل لله ي عيس يسي ابن مري ريم اذك ذكر نعم عمت متي علي ليك وعل علي ولد لدت دتك اذ ايد يدت دتك برو روح الق لقد قدس تكل كلم الن لنس في الم لمه مهد وكه كهل وذ علم لمت متك الك لكت كتب ولح لحك حكم كمه ولت لتو تور وره ولن لنج نجي جيل وذ تخل خلق من الط لطي طين كهي هيه الط لطي طير بذن ذني فتن تنف نفخ فيه فتك تكو كون طير بذن ذني وتب تبر بري الك لكم كمه ولب لبر برص بذن ذني وذ تخر خرج الم لمو موت وتي بذن ذني وذ كفف ففت بني اسر سرء رءي ءيل عنك اذ جيت يته تهم بلب لبي بين ينت فقل الذ لذي ذين كفر فرو منه نهم ان هذ ال سحر مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (780, 'quran:5:111', 'quran', 'quran', '5:111', 111, 779, 'Al-Ma''idah', 'المائدة', 'وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ', NULL, NULL, 'واذ اوحيت الي الحوارين ان امنوا بي وبرسولي قالوا امنا واشهد باننا مسلمون', 'وذ اوحيت ال حور ان امن بي برسول قل ام اشهد بن مسلم', 'quran', NULL, NULL, 'https://quran.com/5/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (780, 'وذ اوح وحي حيت الي الح لحو حور وري رين ان امن منو بي وبر برس رسو سول ولي قلو امن وشه شهد بنن مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (781, 'quran:5:112', 'quran', 'quran', '5:112', 112, 780, 'Al-Ma''idah', 'المائدة', 'إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ', NULL, NULL, 'اذ قال الحواريون يا عيسي ابن مريم هل يستطيع ربك ان ينزل علينا مايده من السماء قال اتقوا الله ان كنتم مومنين', 'اذ قل حوري ي عيس ابن مريم هل يستطيع ربك ان ينزل علي ميد من سمء قل اتق له ان كنتم مومن', 'quran', NULL, NULL, 'https://quran.com/5/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (781, 'اذ قل الح لحو حور وري ريو يون ي عيس يسي ابن مري ريم هل يست ستط تطي طيع ربك ان ينز نزل علي لين ميد يده من الس لسم سمء قل اتق تقو الل لله ان كنت نتم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (782, 'quran:5:113', 'quran', 'quran', '5:113', 113, 781, 'Al-Ma''idah', 'المائدة', 'قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّٰهِدِينَ', NULL, NULL, 'قالوا نريد ان ناكل منها وتطمين قلوبنا ونعلم ان قد صدقتنا ونكون عليها من الشهدين', 'قل نريد ان نكل من تطم قلوب نعلم ان قد صدقت نك علي من شهد', 'quran', NULL, NULL, 'https://quran.com/5/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (782, 'قلو نري ريد ان نكل منه وتط تطم طمي مين قلو لوب وبن ونع نعل علم ان قد صدق دقت قتن ونك نكو كون علي ليه من الش لشه شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (783, 'quran:5:114', 'quran', 'quran', '5:114', 114, 782, 'Al-Ma''idah', 'المائدة', 'قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ', NULL, NULL, 'قال عيسي ابن مريم اللهم ربنا انزل علينا مايده من السماء تكون لنا عيدا لاولنا واخرنا وايه منك وارزقنا وانت خير الرزقين', 'قل عيس ابن مريم لهم رب انزل علي ميد من سمء تك لن عيد لول اخر اي منك ارزق انت خير رزق', 'quran', NULL, NULL, 'https://quran.com/5/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (783, 'قل عيس يسي ابن مري ريم الل لله لهم ربن انز نزل علي لين ميد يده من الس لسم سمء تكو كون لن عيد لول ولن وخر خرن ويه منك ورز رزق زقن ونت خير الر لرز رزق زقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (784, 'quran:5:115', 'quran', 'quran', '5:115', 115, 783, 'Al-Ma''idah', 'المائدة', 'قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قال الله اني منزلها عليكم فمن يكفر بعد منكم فاني اعذبه عذابا لا اعذبه احدا من العلمين', 'قل له ان منزل علي فمن يكفر بعد من ان اعذب عذب ل اعذب احد من علم', 'quran', NULL, NULL, 'https://quran.com/5/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (784, 'قل الل لله اني منز نزل زله علي ليك يكم فمن يكف كفر بعد منك نكم فني اعذ عذب ذبه عذب ل اعذ عذب ذبه احد من الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (785, 'quran:5:116', 'quran', 'quran', '5:116', 116, 784, 'Al-Ma''idah', 'المائدة', 'وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ', NULL, NULL, 'واذ قال الله يا عيسي ابن مريم انت قلت للناس اتخذوني وامي الهين من دون الله قال سبحنك ما يكون لي ان اقول ما ليس لي بحق ان كنت قلته فقد علمته تعلم ما في نفسي ولا اعلم ما في نفسك انك انت علم الغيوب', 'وذ قل له ي عيس ابن مريم انت قلت نس اتخذون ام هين من دون له قل سبحنك م يك لي ان اقول م ليس لي بحق ان كنت قلت فقد علمت تعلم م في نفس ول اعلم م في نفسك انك انت علم غيوب', 'quran', NULL, NULL, 'https://quran.com/5/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (785, 'وذ قل الل لله ي عيس يسي ابن مري ريم انت قلت للن لنس اتخ تخذ خذو ذون وني ومي اله لهي هين من دون الل لله قل سبح بحن حنك م يكو كون لي ان اقو قول م ليس لي بحق ان كنت قلت لته فقد علم لمت مته تعل علم م في نفس فسي ول اعل علم م في نفس فسك انك انت علم الغ لغي غيو يوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (786, 'quran:5:117', 'quran', 'quran', '5:117', 117, 785, 'Al-Ma''idah', 'المائدة', 'مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ', NULL, NULL, 'ما قلت لهم الا ما امرتني به ان اعبدوا الله ربي وربكم وكنت عليهم شهيدا ما دمت فيهم فلما توفيتني كنت انت الرقيب عليهم وانت علي كل شيء شهيد', 'م قلت لهم ال م امرتن به ان اعبد له رب رب كنت علي شهيد م دمت يهم لم توفيتن كنت انت رقيب علي انت عل كل شيء شهيد', 'quran', NULL, NULL, 'https://quran.com/5/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (786, 'م قلت لهم ال م امر مرت رتن تني به ان اعب عبد بدو الل لله ربي ورب ربك بكم وكن كنت علي ليه يهم شهي هيد م دمت فيه يهم فلم توف وفي فيت يتن تني كنت انت الر لرق رقي قيب علي ليه يهم ونت علي كل شيء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (787, 'quran:5:118', 'quran', 'quran', '5:118', 118, 786, 'Al-Ma''idah', 'المائدة', 'إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'ان تعذبهم فانهم عبادك وان تغفر لهم فانك انت العزيز الحكيم', 'ان تعذب ان عبدك ون تغفر لهم انك انت عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/5/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (787, 'ان تعذ عذب ذبه بهم فنه نهم عبد بدك ون تغف غفر لهم فنك انت الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (788, 'quran:5:119', 'quran', 'quran', '5:119', 119, 787, 'Al-Ma''idah', 'المائدة', 'قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', NULL, NULL, 'قال الله هذا يوم ينفع الصدقين صدقهم لهم جنت تجري من تحتها الانهر خلدين فيها ابدا ورضوا عنه ذلك الفوز العظيم', 'قل له هذ يوم ينفع صدق صدق لهم جنت تجر من تحت انهر خلد يه ابد رض عن ذلك فوز عظيم', 'quran', NULL, NULL, 'https://quran.com/5/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (788, 'قل الل لله هذ يوم ينف نفع الص لصد صدق دقي قين صدق دقه قهم لهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ابد ورض رضو عنه ذلك الف لفو فوز الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (789, 'quran:5:120', 'quran', 'quran', '5:120', 120, 788, 'Al-Ma''idah', 'المائدة', 'لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ', NULL, NULL, 'لله ملك السموت والارض وما فيهن وهو علي كل شيء قدير', 'لل ملك سموت ارض وم يهن وهو عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/5/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (789, 'لله ملك الس لسم سمو موت ولر لرض وم فيه يهن وهو علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (790, 'quran:6:1', 'quran', 'quran', '6:1', 1, 789, 'Al-An''am', 'الأنعام', 'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ', NULL, NULL, 'الحمد لله الذي خلق السموت والارض وجعل الظلمت والنور ثم الذين كفروا بربهم يعدلون', 'حمد لل ذي خلق سموت ارض جعل ظلمت نور ثم ذين كفر برب يعدل', 'quran', NULL, NULL, 'https://quran.com/6/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (790, 'الح لحم حمد لله الذ لذي خلق الس لسم سمو موت ولر لرض وجع جعل الظ لظل ظلم لمت ولن لنو نور ثم الذ لذي ذين كفر فرو برب ربه بهم يعد عدل دلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (791, 'quran:6:2', 'quran', 'quran', '6:2', 2, 790, 'Al-An''am', 'الأنعام', 'هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ', NULL, NULL, 'هو الذي خلقكم من طين ثم قضي اجلا واجل مسمي عنده ثم انتم تمترون', 'هو ذي خلق من طين ثم قض اجل اجل مسم عند ثم انتم تمتر', 'quran', NULL, NULL, 'https://quran.com/6/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (791, 'هو الذ لذي خلق لقك قكم من طين ثم قضي اجل وجل مسم سمي عند نده ثم انت نتم تمت متر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (792, 'quran:6:3', 'quran', 'quran', '6:3', 3, 791, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ', NULL, NULL, 'وهو الله في السموت وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون', 'وهو له في سموت وف ارض يعلم سر جهر يعلم م تكسب', 'quran', NULL, NULL, 'https://quran.com/6/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (792, 'وهو الل لله في الس لسم سمو موت وفي الر لرض يعل علم سرك ركم وجه جهر هرك ركم ويع يعل علم م تكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (793, 'quran:6:4', 'quran', 'quran', '6:4', 4, 792, 'Al-An''am', 'الأنعام', 'وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ', NULL, NULL, 'وما تاتيهم من ايه من ايت ربهم الا كانوا عنها معرضين', 'وم تتي من اي من ايت رب ال كن عن معرض', 'quran', NULL, NULL, 'https://quran.com/6/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (793, 'وم تتي تيه يهم من ايه من ايت ربه بهم ال كنو عنه معر عرض رضي ضين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (794, 'quran:6:5', 'quran', 'quran', '6:5', 5, 793, 'Al-An''am', 'الأنعام', 'فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'فقد كذبوا بالحق لما جاءهم فسوف ياتيهم انبوا ما كانوا به يستهزءون', 'فقد كذب حق لم جء سوف يتي انب م كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/6/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (794, 'فقد كذب ذبو بلح لحق لم جءه ءهم فسو سوف يتي تيه يهم انب نبو م كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (795, 'quran:6:6', 'quran', 'quran', '6:6', 6, 794, 'Al-An''am', 'الأنعام', 'أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ', NULL, NULL, 'الم يروا كم اهلكنا من قبلهم من قرن مكنهم في الارض ما لم نمكن لكم وارسلنا السماء عليهم مدرارا وجعلنا الانهر تجري من تحتهم فاهلكنهم بذنوبهم وانشانا من بعدهم قرنا اخرين', 'الم ير كم اهلك من قبل من قرن مكن في ارض م لم نمكن لكم ارسل سمء علي مدرر جعل انهر تجر من تحت اهلكن بذنوب انش من بعد قر اخر', 'quran', NULL, NULL, 'https://quran.com/6/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (795, 'الم يرو كم اهل هلك لكن من قبل بله لهم من قرن مكن كنه نهم في الر لرض م لم نمك مكن لكم ورس رسل سلن الس لسم سمء علي ليه يهم مدر درر وجع جعل علن الن لنه نهر تجر جري من تحت حته تهم فهل هلك لكن كنه نهم بذن ذنو نوب وبه بهم ونش نشن من بعد عده دهم قرن اخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (796, 'quran:6:7', 'quran', 'quran', '6:7', 7, 795, 'Al-An''am', 'الأنعام', 'وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ', NULL, NULL, 'ولو نزلنا عليك كتبا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين', 'ولو نزل عليك كتب في قرطس لمسو بيدي لقل ذين كفر ان هذ ال سحر مب', 'quran', NULL, NULL, 'https://quran.com/6/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (796, 'ولو نزل زلن علي ليك كتب في قرط رطس فلم لمس مسو سوه بيد يدي ديه يهم لقل الذ لذي ذين كفر فرو ان هذ ال سحر مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (797, 'quran:6:8', 'quran', 'quran', '6:8', 8, 796, 'Al-An''am', 'الأنعام', 'وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ', NULL, NULL, 'وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون', 'قل لول انزل عل ملك ولو انزل ملك لقض امر ثم ل ينظر', 'quran', NULL, NULL, 'https://quran.com/6/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (797, 'وقل قلو لول انز نزل علي ليه ملك ولو انز نزل زلن ملك لقض قضي الم لمر ثم ل ينظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (798, 'quran:6:9', 'quran', 'quran', '6:9', 9, 797, 'Al-An''am', 'الأنعام', 'وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ', NULL, NULL, 'ولو جعلنه ملكا لجعلنه رجلا وللبسنا عليهم ما يلبسون', 'ولو جعلن ملك لجعلن رجل بس علي م يلبس', 'quran', NULL, NULL, 'https://quran.com/6/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (798, 'ولو جعل علن لنه ملك لجع جعل علن لنه رجل ولل للب لبس بسن علي ليه يهم م يلب لبس بسو سون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (799, 'quran:6:10', 'quran', 'quran', '6:10', 10, 798, 'Al-An''am', 'الأنعام', 'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'ولقد استهزي برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', 'لقد استهز برسل من قبلك حق ذين سخر من م كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/6/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (799, 'ولق لقد است سته تهز هزي برس رسل من قبل بلك فحق بلذ لذي ذين سخر خرو منه نهم م كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (800, 'quran:6:11', 'quran', 'quran', '6:11', 11, 799, 'Al-An''am', 'الأنعام', 'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ', NULL, NULL, 'قل سيروا في الارض ثم انظروا كيف كان عقبه المكذبين', 'قل سير في ارض ثم انظر كيف كن عقب مكذب', 'quran', NULL, NULL, 'https://quran.com/6/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (800, 'قل سير يرو في الر لرض ثم انظ نظر ظرو كيف كن عقب قبه الم لمك مكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (801, 'quran:6:12', 'quran', 'quran', '6:12', 12, 800, 'Al-An''am', 'الأنعام', 'قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ', NULL, NULL, 'قل لمن ما في السموت والارض قل لله كتب علي نفسه الرحمه ليجمعنكم الي يوم القيمه لا ريب فيه الذين خسروا انفسهم فهم لا يومنون', 'قل لمن م في سموت ارض قل لل كتب عل نفس رحم ليجمعن ال يوم قيم ل ريب في ذين خسر انفس فهم ل يومن', 'quran', NULL, NULL, 'https://quran.com/6/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (801, 'قل لمن م في الس لسم سمو موت ولر لرض قل لله كتب علي نفس فسه الر لرح رحم حمه ليج يجم جمع معن عنك نكم الي يوم الق لقي قيم يمه ل ريب فيه الذ لذي ذين خسر سرو انف نفس فسه سهم فهم ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (802, 'quran:6:13', 'quran', 'quran', '6:13', 13, 801, 'Al-An''am', 'الأنعام', 'وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'وله ما سكن في اليل والنهار وهو السميع العليم', 'ول م سكن في يل نهر وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/6/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (802, 'وله م سكن في الي ليل ولن لنه نهر وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (803, 'quran:6:14', 'quran', 'quran', '6:14', 14, 802, 'Al-An''am', 'الأنعام', 'قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'قل اغير الله اتخذ وليا فاطر السموت والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين', 'قل اغير له اتخذ لي اطر سموت ارض وهو يطعم ول يطعم قل ان امرت ان اك اول من اسلم ول تكونن من مشرك', 'quran', NULL, NULL, 'https://quran.com/6/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (803, 'قل اغي غير الل لله اتخ تخذ ولي فطر الس لسم سمو موت ولر لرض وهو يطع طعم ول يطع طعم قل اني امر مرت ان اكو كون اول من اسل سلم ول تكو كون ونن من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (804, 'quran:6:15', 'quran', 'quran', '6:15', 15, 803, 'Al-An''am', 'الأنعام', 'قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ', NULL, NULL, 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', 'قل ان اخف ان عصيت رب عذب يوم عظيم', 'quran', NULL, NULL, 'https://quran.com/6/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (804, 'قل اني اخف ان عصي صيت ربي عذب يوم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (805, 'quran:6:16', 'quran', 'quran', '6:16', 16, 804, 'Al-An''am', 'الأنعام', 'مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ', NULL, NULL, 'من يصرف عنه يوميذ فقد رحمه وذلك الفوز المبين', 'من يصرف عن يوميذ فقد رحم ذلك فوز مب', 'quran', NULL, NULL, 'https://quran.com/6/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (805, 'من يصر صرف عنه يوم ومي ميذ فقد رحم حمه وذل ذلك الف لفو فوز الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (806, 'quran:6:17', 'quran', 'quran', '6:17', 17, 805, 'Al-An''am', 'الأنعام', 'وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو علي كل شيء قدير', 'ون يمسسك له بضر فل كشف له ال هو ون يمسسك بخير فهو عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/6/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (806, 'ون يمس مسس سسك الل لله بضر فل كشف له ال هو ون يمس مسس سسك بخي خير فهو علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (807, 'quran:6:18', 'quran', 'quran', '6:18', 18, 806, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ', NULL, NULL, 'وهو القاهر فوق عباده وهو الحكيم الخبير', 'وهو قهر فوق عبد وهو حكيم خبير', 'quran', NULL, NULL, 'https://quran.com/6/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (807, 'وهو الق لقه قهر فوق عبد بده وهو الح لحك حكي كيم الخ لخب خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (808, 'quran:6:19', 'quran', 'quran', '6:19', 19, 807, 'Al-An''am', 'الأنعام', 'قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ', NULL, NULL, 'قل اي شيء اكبر شهده قل الله شهيد بيني وبينكم واوحي الي هذا القران لانذركم به ومن بلغ اينكم لتشهدون ان مع الله الهه اخري قل لا اشهد قل انما هو اله وحد وانني بريء مما تشركون', 'قل اي شيء اكبر شهد قل له شهيد بين بين اوح ال هذ قر لنذر به ومن بلغ اين لتشهد ان مع له هه اخر قل ل اشهد قل انم هو ال وحد انن بريء مم تشرك', 'quran', NULL, NULL, 'https://quran.com/6/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (808, 'قل اي شيء اكب كبر شهد هده قل الل لله شهي هيد بين يني وبي بين ينك نكم ووح وحي الي هذ الق لقر قرن لنذ نذر ذرك ركم به ومن بلغ اين ينك نكم لتش تشه شهد هدو دون ان مع الل لله اله لهه اخر خري قل ل اشه شهد قل انم هو اله وحد ونن نني بري ريء مم تشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (809, 'quran:6:20', 'quran', 'quran', '6:20', 20, 808, 'Al-An''am', 'الأنعام', 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ', NULL, NULL, 'الذين اتينهم الكتب يعرفونه كما يعرفون ابناءهم الذين خسروا انفسهم فهم لا يومنون', 'ذين اتين كتب يعرفون كم يعرف ابنء ذين خسر انفس فهم ل يومن', 'quran', NULL, NULL, 'https://quran.com/6/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (809, 'الذ لذي ذين اتي تين ينه نهم الك لكت كتب يعر عرف رفو فون ونه كم يعر عرف رفو فون ابن بنء نءه ءهم الذ لذي ذين خسر سرو انف نفس فسه سهم فهم ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (810, 'quran:6:21', 'quran', 'quran', '6:21', 21, 809, 'Al-An''am', 'الأنعام', 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ', NULL, NULL, 'ومن اظلم ممن افتري علي الله كذبا او كذب بايته انه لا يفلح الظلمون', 'ومن اظلم ممن افتر عل له كذب او كذب بيت ان ل يفلح ظلم', 'quran', NULL, NULL, 'https://quran.com/6/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (810, 'ومن اظل ظلم ممن افت فتر تري علي الل لله كذب او كذب بيت يته انه ل يفل فلح الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (811, 'quran:6:22', 'quran', 'quran', '6:22', 22, 810, 'Al-An''am', 'الأنعام', 'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ', NULL, NULL, 'ويوم نحشرهم جميعا ثم نقول للذين اشركوا اين شركاوكم الذين كنتم تزعمون', 'يوم نحشر جميع ثم نقول ذين اشرك اين شركو ذين كنتم تزعم', 'quran', NULL, NULL, 'https://quran.com/6/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (811, 'ويو يوم نحش حشر شره رهم جمي ميع ثم نقو قول للذ لذي ذين اشر شرك ركو اين شرك ركو كوك وكم الذ لذي ذين كنت نتم تزع زعم عمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (812, 'quran:6:23', 'quran', 'quran', '6:23', 23, 811, 'Al-An''am', 'الأنعام', 'ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ', NULL, NULL, 'ثم لم تكن فتنتهم الا ان قالوا والله ربنا ما كنا مشركين', 'ثم لم تكن تنت ال ان قل له رب م كن مشرك', 'quran', NULL, NULL, 'https://quran.com/6/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (812, 'ثم لم تكن فتن تنت نته تهم ال ان قلو ولل لله ربن م كن مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (813, 'quran:6:24', 'quran', 'quran', '6:24', 24, 812, 'Al-An''am', 'الأنعام', 'ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', NULL, NULL, 'انظر كيف كذبوا علي انفسهم وضل عنهم ما كانوا يفترون', 'انظر كيف كذب عل انفس وضل عن م كن يفتر', 'quran', NULL, NULL, 'https://quran.com/6/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (813, 'انظ نظر كيف كذب ذبو علي انف نفس فسه سهم وضل عنه نهم م كنو يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (814, 'quran:6:25', 'quran', 'quran', '6:25', 25, 813, 'Al-An''am', 'الأنعام', 'وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', NULL, NULL, 'ومنهم من يستمع اليك وجعلنا علي قلوبهم اكنه ان يفقهوه وفي اذانهم وقرا وان يروا كل ايه لا يومنوا بها حتي اذا جاءوك يجدلونك يقول الذين كفروا ان هذا الا اسطير الاولين', 'من من يستمع يك جعل عل قلوب اكن ان يفقهو وف اذن قر ون ير كل اي ل يومن به حت اذ جءوك يجدلونك يقول ذين كفر ان هذ ال اسطير اول', 'quran', NULL, NULL, 'https://quran.com/6/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (814, 'ومن منه نهم من يست ستم تمع الي ليك وجع جعل علن علي قلو لوب وبه بهم اكن كنه ان يفق فقه قهو هوه وفي اذن ذنه نهم وقر ون يرو كل ايه ل يوم ومن منو به حتي اذ جءو ءوك يجد جدل دلو لون ونك يقو قول الذ لذي ذين كفر فرو ان هذ ال اسط سطي طير الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (815, 'quran:6:26', 'quran', 'quran', '6:26', 26, 814, 'Al-An''am', 'الأنعام', 'وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', NULL, NULL, 'وهم ينهون عنه وينون عنه وان يهلكون الا انفسهم وما يشعرون', 'وهم ينه عن ين عن ون يهلك ال انفس وم يشعر', 'quran', NULL, NULL, 'https://quran.com/6/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (815, 'وهم ينه نهو هون عنه وين ينو نون عنه ون يهل هلك لكو كون ال انف نفس فسه سهم وم يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (816, 'quran:6:27', 'quran', 'quran', '6:27', 27, 815, 'Al-An''am', 'الأنعام', 'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'ولو تري اذ وقفوا علي النار فقالوا يا ليتنا نرد ولا نكذب بايت ربنا ونكون من المومنين', 'ولو تر اذ قف عل نر قل ي ليت نرد ول نكذب بيت رب نك من مومن', 'quran', NULL, NULL, 'https://quran.com/6/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (816, 'ولو تري اذ وقف قفو علي الن لنر فقل قلو ي ليت يتن نرد ول نكذ كذب بيت ربن ونك نكو كون من الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (817, 'quran:6:28', 'quran', 'quran', '6:28', 28, 816, 'Al-An''am', 'الأنعام', 'بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ', NULL, NULL, 'بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وانهم لكذبون', 'بل بد لهم م كن يخف من قبل ولو رد لعد لم نه عن ان لكذب', 'quran', NULL, NULL, 'https://quran.com/6/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (817, 'بل بد لهم م كنو يخف خفو فون من قبل ولو ردو لعد عدو لم نهو عنه ونه نهم لكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (818, 'quran:6:29', 'quran', 'quran', '6:29', 29, 817, 'Al-An''am', 'الأنعام', 'وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ', NULL, NULL, 'وقالوا ان هي الا حياتنا الدنيا وما نحن بمبعوثين', 'قل ان هي ال حيت دني وم نحن بمبعوث', 'quran', NULL, NULL, 'https://quran.com/6/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (818, 'وقل قلو ان هي ال حيت يتن الد لدن دني وم نحن بمب مبع بعو عوث وثي ثين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (819, 'quran:6:30', 'quran', 'quran', '6:30', 30, 818, 'Al-An''am', 'الأنعام', 'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ', NULL, NULL, 'ولو تري اذ وقفوا علي ربهم قال اليس هذا بالحق قالوا بلي وربنا قال فذوقوا العذاب بما كنتم تكفرون', 'ولو تر اذ قف عل رب قل يس هذ حق قل بل رب قل ذوق عذب بم كنتم تكفر', 'quran', NULL, NULL, 'https://quran.com/6/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (819, 'ولو تري اذ وقف قفو علي ربه بهم قل الي ليس هذ بلح لحق قلو بلي ورب ربن قل فذو ذوق وقو الع لعذ عذب بم كنت نتم تكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (820, 'quran:6:31', 'quran', 'quran', '6:31', 31, 819, 'Al-An''am', 'الأنعام', 'قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ', NULL, NULL, 'قد خسر الذين كذبوا بلقاء الله حتي اذا جاءتهم الساعه بغته قالوا يا حسرتنا علي ما فرطنا فيها وهم يحملون اوزارهم علي ظهورهم الا ساء ما يزرون', 'قد خسر ذين كذب بلقء له حت اذ جءت سع بغت قل ي حسرت عل م رط يه وهم يحمل اوزر عل ظهور ال سء م يزر', 'quran', NULL, NULL, 'https://quran.com/6/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (820, 'قد خسر الذ لذي ذين كذب ذبو بلق لقء الل لله حتي اذ جءت ءته تهم الس لسع سعه بغت غته قلو ي حسر سرت رتن علي م فرط رطن فيه وهم يحم حمل ملو لون اوز وزر زره رهم علي ظهو هور وره رهم ال سء م يزر زرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (821, 'quran:6:32', 'quran', 'quran', '6:32', 32, 820, 'Al-An''am', 'الأنعام', 'وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'وما الحياه الدنيا الا لعب ولهو وللدار الاخره خير للذين يتقون افلا تعقلون', 'وم حي دني ال لعب لهو در اخر خير ذين يتق افل تعقل', 'quran', NULL, NULL, 'https://quran.com/6/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (821, 'وم الح لحي حيه الد لدن دني ال لعب وله لهو ولل للد لدر الخ لخر خره خير للذ لذي ذين يتق تقو قون افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (822, 'quran:6:33', 'quran', 'quran', '6:33', 33, 821, 'Al-An''am', 'الأنعام', 'قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ', NULL, NULL, 'قد نعلم انه ليحزنك الذي يقولون فانهم لا يكذبونك ولكن الظلمين بايت الله يجحدون', 'قد نعلم ان ليحزنك ذي يقول ان ل يكذبونك لكن ظلم بيت له يجحد', 'quran', NULL, NULL, 'https://quran.com/6/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (822, 'قد نعل علم انه ليح يحز حزن زنك الذ لذي يقو قول ولو لون فنه نهم ل يكذ كذب ذبو بون ونك ولك لكن الظ لظل ظلم لمي مين بيت الل لله يجح جحد حدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (823, 'quran:6:34', 'quran', 'quran', '6:34', 34, 822, 'Al-An''am', 'الأنعام', 'وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'ولقد كذبت رسل من قبلك فصبروا علي ما كذبوا واوذوا حتي اتاهم نصرنا ولا مبدل لكلمت الله ولقد جاءك من نباي المرسلين', 'لقد كذبت رسل من قبلك صبر عل م كذب اوذ حت ات نصر ول مبدل لكلمت له لقد جءك من نب مرسل', 'quran', NULL, NULL, 'https://quran.com/6/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (823, 'ولق لقد كذب ذبت رسل من قبل بلك فصب صبر برو علي م كذب ذبو ووذ وذو حتي اته تهم نصر صرن ول مبد بدل لكل كلم لمت الل لله ولق لقد جءك من نبي الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (824, 'quran:6:35', 'quran', 'quran', '6:35', 35, 823, 'Al-An''am', 'الأنعام', 'وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ', NULL, NULL, 'وان كان كبر عليك اعراضهم فان استطعت ان تبتغي نفقا في الارض او سلما في السماء فتاتيهم بايه ولو شاء الله لجمعهم علي الهدي فلا تكونن من الجهلين', 'ون كن كبر عليك اعرض فن استطعت ان تبتغ نفق في ارض او سلم في سمء تتي ب ولو شء له لجمع عل هد فل تكونن من جهل', 'quran', NULL, NULL, 'https://quran.com/6/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (824, 'ون كن كبر علي ليك اعر عرض رضه ضهم فن است ستط تطع طعت ان تبت بتغ تغي نفق في الر لرض او سلم في الس لسم سمء فتت تتي تيه يهم بيه ولو شء الل لله لجم جمع معه عهم علي اله لهد هدي فل تكو كون ونن من الج لجه جهل هلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (825, 'quran:6:36', 'quran', 'quran', '6:36', 36, 824, 'Al-An''am', 'الأنعام', 'إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ', NULL, NULL, 'انما يستجيب الذين يسمعون والموتي يبعثهم الله ثم اليه يرجعون', 'انم يستجيب ذين يسمع موت يبعث له ثم يه يرجع', 'quran', NULL, NULL, 'https://quran.com/6/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (825, 'انم يست ستج تجي جيب الذ لذي ذين يسم سمع معو عون ولم لمو موت وتي يبع بعث عثه ثهم الل لله ثم الي ليه يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (826, 'quran:6:37', 'quran', 'quran', '6:37', 37, 825, 'Al-An''am', 'الأنعام', 'وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'وقالوا لولا نزل عليه ايه من ربه قل ان الله قادر علي ان ينزل ايه ولكن اكثرهم لا يعلمون', 'قل لول نزل عل اي من رب قل ان له قدر عل ان ينزل اي لكن اكثر ل يعلم', 'quran', NULL, NULL, 'https://quran.com/6/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (826, 'وقل قلو لول نزل علي ليه ايه من ربه قل ان الل لله قدر علي ان ينز نزل ايه ولك لكن اكث كثر ثره رهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (827, 'quran:6:38', 'quran', 'quran', '6:38', 38, 826, 'Al-An''am', 'الأنعام', 'وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ', NULL, NULL, 'وما من دابه في الارض ولا طير يطير بجناحيه الا امم امثالكم ما فرطنا في الكتب من شيء ثم الي ربهم يحشرون', 'وم من دب في ارض ول طير يطير بجنح ال امم امثل م رط في كتب من شيء ثم ال رب يحشر', 'quran', NULL, NULL, 'https://quran.com/6/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (827, 'وم من دبه في الر لرض ول طير يطي طير بجن جنح نحي حيه ال امم امث مثل ثلك لكم م فرط رطن في الك لكت كتب من شيء ثم الي ربه بهم يحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (828, 'quran:6:39', 'quran', 'quran', '6:39', 39, 827, 'Al-An''am', 'الأنعام', 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'والذين كذبوا بايتنا صم وبكم في الظلمت من يشا الله يضلله ومن يشا يجعله علي صرط مستقيم', 'ذين كذب بيت صم بكم في ظلمت من يش له يضلل ومن يش يجعل عل صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/6/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (828, 'ولذ لذي ذين كذب ذبو بيت يتن صم وبك بكم في الظ لظل ظلم لمت من يش الل لله يضل ضلل لله ومن يش يجع جعل عله علي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (829, 'quran:6:40', 'quran', 'quran', '6:40', 40, 828, 'Al-An''am', 'الأنعام', 'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'قل ارءيتكم ان اتاكم عذاب الله او اتتكم الساعه اغير الله تدعون ان كنتم صدقين', 'قل ارءيت ان ات عذب له او اتت سع اغير له تدع ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/6/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (829, 'قل ارء رءي ءيت يتك تكم ان اتك تكم عذب الل لله او اتت تتك تكم الس لسع سعه اغي غير الل لله تدع دعو عون ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (830, 'quran:6:41', 'quran', 'quran', '6:41', 41, 829, 'Al-An''am', 'الأنعام', 'بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ', NULL, NULL, 'بل اياه تدعون فيكشف ما تدعون اليه ان شاء وتنسون ما تشركون', 'بل اي تدع يكشف م تدع يه ان شء تنس م تشرك', 'quran', NULL, NULL, 'https://quran.com/6/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (830, 'بل ايه تدع دعو عون فيك يكش كشف م تدع دعو عون الي ليه ان شء وتن تنس نسو سون م تشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (831, 'quran:6:42', 'quran', 'quran', '6:42', 42, 830, 'Al-An''am', 'الأنعام', 'وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ', NULL, NULL, 'ولقد ارسلنا الي امم من قبلك فاخذنهم بالباساء والضراء لعلهم يتضرعون', 'لقد ارسل ال امم من قبلك اخذن بسء ضرء لعل يتضرع', 'quran', NULL, NULL, 'https://quran.com/6/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (831, 'ولق لقد ارس رسل سلن الي امم من قبل بلك فخذ خذن ذنه نهم بلب لبس بسء ولض لضر ضرء لعل عله لهم يتض تضر ضرع رعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (832, 'quran:6:43', 'quran', 'quran', '6:43', 43, 831, 'Al-An''am', 'الأنعام', 'فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'فلولا اذ جاءهم باسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطن ما كانوا يعملون', 'لول اذ جء بس تضرع لكن قست قلوب زين لهم شيطن م كن يعمل', 'quran', NULL, NULL, 'https://quran.com/6/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (832, 'فلو لول اذ جءه ءهم بسن تضر ضرع رعو ولك لكن قست قلو لوب وبه بهم وزي زين لهم الش لشي شيط يطن م كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (833, 'quran:6:44', 'quran', 'quran', '6:44', 44, 832, 'Al-An''am', 'الأنعام', 'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ', NULL, NULL, 'فلما نسوا ما ذكروا به فتحنا عليهم ابوب كل شيء حتي اذا فرحوا بما اوتوا اخذنهم بغته فاذا هم مبلسون', 'لم نس م ذكر به تح علي ابوب كل شيء حت اذ رح بم اوت اخذن بغت اذ هم مبلس', 'quran', NULL, NULL, 'https://quran.com/6/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (833, 'فلم نسو م ذكر كرو به فتح تحن علي ليه يهم ابو بوب كل شيء حتي اذ فرح رحو بم اوت وتو اخذ خذن ذنه نهم بغت غته فذ هم مبل بلس لسو سون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (834, 'quran:6:45', 'quran', 'quran', '6:45', 45, 833, 'Al-An''am', 'الأنعام', 'فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'فقطع دابر القوم الذين ظلموا والحمد لله رب العلمين', 'قطع دبر قوم ذين ظلم حمد لل رب علم', 'quran', NULL, NULL, 'https://quran.com/6/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (834, 'فقط قطع دبر الق لقو قوم الذ لذي ذين ظلم لمو ولح لحم حمد لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (835, 'quran:6:46', 'quran', 'quran', '6:46', 46, 834, 'Al-An''am', 'الأنعام', 'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ', NULL, NULL, 'قل ارءيتم ان اخذ الله سمعكم وابصركم وختم علي قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايت ثم هم يصدفون', 'قل ارءيتم ان اخذ له سمع ابصر ختم عل قلوب من ال غير له يتي به انظر كيف نصرف ايت ثم هم يصدف', 'quran', NULL, NULL, 'https://quran.com/6/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (835, 'قل ارء رءي ءيت يتم ان اخذ الل لله سمع معك عكم وبص بصر صرك ركم وخت ختم علي قلو لوب وبك بكم من اله غير الل لله يتي تيك يكم به انظ نظر كيف نصر صرف الي ليت ثم هم يصد صدف دفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (836, 'quran:6:47', 'quran', 'quran', '6:47', 47, 835, 'Al-An''am', 'الأنعام', 'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'قل ارءيتكم ان اتاكم عذاب الله بغته او جهره هل يهلك الا القوم الظلمون', 'قل ارءيت ان ات عذب له بغت او جهر هل يهلك ال قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/6/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (836, 'قل ارء رءي ءيت يتك تكم ان اتك تكم عذب الل لله بغت غته او جهر هره هل يهل هلك ال الق لقو قوم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (837, 'quran:6:48', 'quran', 'quran', '6:48', 48, 836, 'Al-An''am', 'الأنعام', 'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'وما نرسل المرسلين الا مبشرين ومنذرين فمن امن واصلح فلا خوف عليهم ولا هم يحزنون', 'وم نرسل مرسل ال مبشر منذر فمن امن اصلح فل خوف علي ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/6/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (837, 'وم نرس رسل الم لمر مرس رسل سلي لين ال مبش بشر شري رين ومن منذ نذر ذري رين فمن امن وصل صلح فل خوف علي ليه يهم ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (838, 'quran:6:49', 'quran', 'quran', '6:49', 49, 837, 'Al-An''am', 'الأنعام', 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ', NULL, NULL, 'والذين كذبوا بايتنا يمسهم العذاب بما كانوا يفسقون', 'ذين كذب بيت يمس عذب بم كن يفسق', 'quran', NULL, NULL, 'https://quran.com/6/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (838, 'ولذ لذي ذين كذب ذبو بيت يتن يمس مسه سهم الع لعذ عذب بم كنو يفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (839, 'quran:6:50', 'quran', 'quran', '6:50', 50, 838, 'Al-An''am', 'الأنعام', 'قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ', NULL, NULL, 'قل لا اقول لكم عندي خزاين الله ولا اعلم الغيب ولا اقول لكم اني ملك ان اتبع الا ما يوحي الي قل هل يستوي الاعمي والبصير افلا تتفكرون', 'قل ل اقول لكم عند خز له ول اعلم غيب ول اقول لكم ان ملك ان اتبع ال م يوح ال قل هل يستو اعم بصير افل تتفكر', 'quran', NULL, NULL, 'https://quran.com/6/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (839, 'قل ل اقو قول لكم عند ندي خزي زين الل لله ول اعل علم الغ لغي غيب ول اقو قول لكم اني ملك ان اتب تبع ال م يوح وحي الي قل هل يست ستو توي الع لعم عمي ولب لبص بصي صير افل تتف تفك فكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (840, 'quran:6:51', 'quran', 'quran', '6:51', 51, 839, 'Al-An''am', 'الأنعام', 'وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ', NULL, NULL, 'وانذر به الذين يخافون ان يحشروا الي ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون', 'انذر به ذين يخف ان يحشر ال رب ليس لهم من دون ول ول شفيع لعل يتق', 'quran', NULL, NULL, 'https://quran.com/6/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (840, 'ونذ نذر به الذ لذي ذين يخف خفو فون ان يحش حشر شرو الي ربه بهم ليس لهم من دون ونه ولي ول شفي فيع لعل عله لهم يتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (841, 'quran:6:52', 'quran', 'quran', '6:52', 52, 840, 'Al-An''am', 'الأنعام', 'وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'ولا تطرد الذين يدعون ربهم بالغداه والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظلمين', 'ول تطرد ذين يدع رب غد عش يريد جه م عليك من حسب من شيء وم من حسبك علي من شيء تطرد تك من ظلم', 'quran', NULL, NULL, 'https://quran.com/6/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (841, 'ول تطر طرد الذ لذي ذين يدع دعو عون ربه بهم بلغ لغد غده ولع لعش عشي يري ريد يدو دون وجه جهه م علي ليك من حسب سبه بهم من شيء وم من حسب سبك علي ليه يهم من شيء فتط تطر طرد رده دهم فتك تكو كون من الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (842, 'quran:6:53', 'quran', 'quran', '6:53', 53, 841, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ', NULL, NULL, 'وكذلك فتنا بعضهم ببعض ليقولوا اهولاء من الله عليهم من بيننا اليس الله باعلم بالشكرين', 'كذلك تن بعض ببعض ليقول اهولء من له علي من بين يس له بعلم شكر', 'quran', NULL, NULL, 'https://quran.com/6/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (842, 'وكذ كذل ذلك فتن بعض عضه ضهم ببع بعض ليق يقو قول ولو اهو هول ولء من الل لله علي ليه يهم من بين ينن الي ليس الل لله بعل علم بلش لشك شكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (843, 'quran:6:54', 'quran', 'quran', '6:54', 54, 842, 'Al-An''am', 'الأنعام', 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'واذا جاءك الذين يومنون بايتنا فقل سلم عليكم كتب ربكم علي نفسه الرحمه انه من عمل منكم سوا بجهله ثم تاب من بعده واصلح فانه غفور رحيم', 'اذ جءك ذين يومن بيت فقل سلم علي كتب رب عل نفس رحم ان من عمل من سو بجهل ثم تب من بعد اصلح ان غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/6/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (843, 'وذ جءك الذ لذي ذين يوم ومن منو نون بيت يتن فقل سلم علي ليك يكم كتب ربك بكم علي نفس فسه الر لرح رحم حمه انه من عمل منك نكم سو بجه جهل هله ثم تب من بعد عده وصل صلح فنه غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (844, 'quran:6:55', 'quran', 'quran', '6:55', 55, 843, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ', NULL, NULL, 'وكذلك نفصل الايت ولتستبين سبيل المجرمين', 'كذلك نفصل ايت لتستب سبيل مجرم', 'quran', NULL, NULL, 'https://quran.com/6/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (844, 'وكذ كذل ذلك نفص فصل الي ليت ولت لتس تست ستب تبي بين سبي بيل الم لمج مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (845, 'quran:6:56', 'quran', 'quran', '6:56', 56, 844, 'Al-An''am', 'الأنعام', 'قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ', NULL, NULL, 'قل اني نهيت ان اعبد الذين تدعون من دون الله قل لا اتبع اهواءكم قد ضللت اذا وما انا من المهتدين', 'قل ان نهيت ان اعبد ذين تدع من دون له قل ل اتبع اهوء قد ضللت اذ وم ان من مهتد', 'quran', NULL, NULL, 'https://quran.com/6/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (845, 'قل اني نهي هيت ان اعب عبد الذ لذي ذين تدع دعو عون من دون الل لله قل ل اتب تبع اهو هوء وءك ءكم قد ضلل للت اذ وم ان من الم لمه مهت هتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (846, 'quran:6:57', 'quran', 'quran', '6:57', 57, 845, 'Al-An''am', 'الأنعام', 'قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ', NULL, NULL, 'قل اني علي بينه من ربي وكذبتم به ما عندي ما تستعجلون به ان الحكم الا لله يقص الحق وهو خير الفصلين', 'قل ان عل بين من رب كذبتم به م عند م تستعجل به ان حكم ال لل يقص حق وهو خير فصل', 'quran', NULL, NULL, 'https://quran.com/6/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (846, 'قل اني علي بين ينه من ربي وكذ كذب ذبت بتم به م عند ندي م تست ستع تعج عجل جلو لون به ان الح لحك حكم ال لله يقص الح لحق وهو خير الف لفص فصل صلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (847, 'quran:6:58', 'quran', 'quran', '6:58', 58, 846, 'Al-An''am', 'الأنعام', 'قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّٰلِمِينَ', NULL, NULL, 'قل لو ان عندي ما تستعجلون به لقضي الامر بيني وبينكم والله اعلم بالظلمين', 'قل لو ان عند م تستعجل به لقض امر بين بين له اعلم ظلم', 'quran', NULL, NULL, 'https://quran.com/6/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (847, 'قل لو ان عند ندي م تست ستع تعج عجل جلو لون به لقض قضي الم لمر بين يني وبي بين ينك نكم ولل لله اعل علم بلظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (848, 'quran:6:59', 'quran', 'quran', '6:59', 59, 847, 'Al-An''am', 'الأنعام', 'وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ', NULL, NULL, 'وعنده مفاتح الغيب لا يعلمها الا هو ويعلم ما في البر والبحر وما تسقط من ورقه الا يعلمها ولا حبه في ظلمت الارض ولا رطب ولا يابس الا في كتب مبين', 'عند مفتح غيب ل يعلم ال هو يعلم م في بر بحر وم تسقط من رق ال يعلم ول حب في ظلمت ارض ول رطب ول يبس ال في كتب مب', 'quran', NULL, NULL, 'https://quran.com/6/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (848, 'وعن عند نده مفت فتح الغ لغي غيب ل يعل علم لمه ال هو ويع يعل علم م في الب لبر ولب لبح بحر وم تسق سقط من ورق رقه ال يعل علم لمه ول حبه في ظلم لمت الر لرض ول رطب ول يبس ال في كتب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (849, 'quran:6:60', 'quran', 'quran', '6:60', 60, 848, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'وهو الذي يتوفاكم باليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضي اجل مسمي ثم اليه مرجعكم ثم ينبيكم بما كنتم تعملون', 'وهو ذي يتوف يل يعلم م جرحتم نهر ثم يبعث في ليقض اجل مسم ثم يه مرجع ثم ينبي بم كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/6/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (849, 'وهو الذ لذي يتو توف وفك فكم بلي ليل ويع يعل علم م جرح رحت حتم بلن لنه نهر ثم يبع بعث عثك ثكم فيه ليق يقض قضي اجل مسم سمي ثم الي ليه مرج رجع جعك عكم ثم ينب نبي بيك يكم بم كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (850, 'quran:6:61', 'quran', 'quran', '6:61', 61, 849, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ', NULL, NULL, 'وهو القاهر فوق عباده ويرسل عليكم حفظه حتي اذا جاء احدكم الموت توفته رسلنا وهم لا يفرطون', 'وهو قهر فوق عبد يرسل علي حفظ حت اذ جء احد موت توفت رسل وهم ل يفرط', 'quran', NULL, NULL, 'https://quran.com/6/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (850, 'وهو الق لقه قهر فوق عبد بده وير يرس رسل علي ليك يكم حفظ فظه حتي اذ جء احد حدك دكم الم لمو موت توف وفت فته رسل سلن وهم ل يفر فرط رطو طون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (851, 'quran:6:62', 'quran', 'quran', '6:62', 62, 850, 'Al-An''am', 'الأنعام', 'ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ', NULL, NULL, 'ثم ردوا الي الله مولاهم الحق الا له الحكم وهو اسرع الحسبين', 'ثم رد ال له مول حق ال له حكم وهو اسرع حسب', 'quran', NULL, NULL, 'https://quran.com/6/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (851, 'ثم ردو الي الل لله مول وله لهم الح لحق ال له الح لحك حكم وهو اسر سرع الح لحس حسب سبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (852, 'quran:6:63', 'quran', 'quran', '6:63', 63, 851, 'Al-An''am', 'الأنعام', 'قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', NULL, NULL, 'قل من ينجيكم من ظلمت البر والبحر تدعونه تضرعا وخفيه لين انجانا من هذه لنكونن من الشكرين', 'قل من ينجي من ظلمت بر بحر تدعون تضرع خف لين انج من هذ لنكونن من شكر', 'quran', NULL, NULL, 'https://quran.com/6/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (852, 'قل من ينج نجي جيك يكم من ظلم لمت الب لبر ولب لبح بحر تدع دعو عون ونه تضر ضرع وخف خفي فيه لين انج نجن من هذه لنك نكو كون ونن من الش لشك شكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (853, 'quran:6:64', 'quran', 'quran', '6:64', 64, 852, 'Al-An''am', 'الأنعام', 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ', NULL, NULL, 'قل الله ينجيكم منها ومن كل كرب ثم انتم تشركون', 'قل له ينجي من ومن كل كرب ثم انتم تشرك', 'quran', NULL, NULL, 'https://quran.com/6/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (853, 'قل الل لله ينج نجي جيك يكم منه ومن كل كرب ثم انت نتم تشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (854, 'quran:6:65', 'quran', 'quran', '6:65', 65, 853, 'Al-An''am', 'الأنعام', 'قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ', NULL, NULL, 'قل هو القادر علي ان يبعث عليكم عذابا من فوقكم او من تحت ارجلكم او يلبسكم شيعا ويذيق بعضكم باس بعض انظر كيف نصرف الايت لعلهم يفقهون', 'قل هو قدر عل ان يبعث علي عذب من وق او من تحت ارجل او يلبس شيع يذيق بعض بس بعض انظر كيف نصرف ايت لعل يفقه', 'quran', NULL, NULL, 'https://quran.com/6/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (854, 'قل هو الق لقد قدر علي ان يبع بعث علي ليك يكم عذب من فوق وقك قكم او من تحت ارج رجل جلك لكم او يلب لبس بسك سكم شيع ويذ يذي ذيق بعض عضك ضكم بس بعض انظ نظر كيف نصر صرف الي ليت لعل عله لهم يفق فقه قهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (855, 'quran:6:66', 'quran', 'quran', '6:66', 66, 854, 'Al-An''am', 'الأنعام', 'وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ', NULL, NULL, 'وكذب به قومك وهو الحق قل لست عليكم بوكيل', 'كذب به قومك وهو حق قل لست علي بوكيل', 'quran', NULL, NULL, 'https://quran.com/6/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (855, 'وكذ كذب به قوم ومك وهو الح لحق قل لست علي ليك يكم بوك وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (856, 'quran:6:67', 'quran', 'quran', '6:67', 67, 855, 'Al-An''am', 'الأنعام', 'لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ', NULL, NULL, 'لكل نبا مستقر وسوف تعلمون', 'لكل نب مستقر سوف تعلم', 'quran', NULL, NULL, 'https://quran.com/6/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (856, 'لكل نب مست ستق تقر وسو سوف تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (857, 'quran:6:68', 'quran', 'quran', '6:68', 68, 856, 'Al-An''am', 'الأنعام', 'وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ', NULL, NULL, 'واذا رايت الذين يخوضون في ايتنا فاعرض عنهم حتي يخوضوا في حديث غيره واما ينسينك الشيطن فلا تقعد بعد الذكري مع القوم الظلمين', 'اذ ريت ذين يخوض في ايت اعرض عن حت يخوض في حديث غير ام ينسينك شيطن فل تقعد بعد ذكر مع قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/6/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (857, 'وذ ريت الذ لذي ذين يخو خوض وضو ضون في ايت يتن فعر عرض عنه نهم حتي يخو خوض وضو في حدي ديث غير يره وم ينس نسي سين ينك الش لشي شيط يطن فل تقع قعد بعد الذ لذك ذكر كري مع الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (858, 'quran:6:69', 'quran', 'quran', '6:69', 69, 857, 'Al-An''am', 'الأنعام', 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ', NULL, NULL, 'وما علي الذين يتقون من حسابهم من شيء ولكن ذكري لعلهم يتقون', 'وم عل ذين يتق من حسب من شيء لكن ذكر لعل يتق', 'quran', NULL, NULL, 'https://quran.com/6/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (858, 'وم علي الذ لذي ذين يتق تقو قون من حسب سبه بهم من شيء ولك لكن ذكر كري لعل عله لهم يتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (859, 'quran:6:70', 'quran', 'quran', '6:70', 70, 858, 'Al-An''am', 'الأنعام', 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ', NULL, NULL, 'وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياه الدنيا وذكر به ان تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وان تعدل كل عدل لا يوخذ منها اوليك الذين ابسلوا بما كسبوا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون', 'وذر ذين اتخذ دين لعب له غرت حي دني ذكر به ان تبسل نفس بم كسبت ليس له من دون له ول ول شفيع ون تعدل كل عدل ل يوخذ من اوليك ذين ابسل بم كسب لهم شرب من حميم عذب يم بم كن يكفر', 'quran', NULL, NULL, 'https://quran.com/6/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (859, 'وذر الذ لذي ذين اتخ تخذ خذو دين ينه نهم لعب وله لهو وغر غرت رته تهم الح لحي حيه الد لدن دني وذك ذكر به ان تبس بسل نفس بم كسب سبت ليس له من دون الل لله ولي ول شفي فيع ون تعد عدل كل عدل ل يوخ وخذ منه اول ولي ليك الذ لذي ذين ابس بسل سلو بم كسب سبو لهم شرب من حمي ميم وعذ عذب الي ليم بم كنو يكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (860, 'quran:6:71', 'quran', 'quran', '6:71', 71, 859, 'Al-An''am', 'الأنعام', 'قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قل اندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد علي اعقابنا بعد اذ هدانا الله كالذي استهوته الشيطين في الارض حيران له اصحب يدعونه الي الهدي ايتنا قل ان هدي الله هو الهدي وامرنا لنسلم لرب العلمين', 'قل اندع من دون له م ل ينفع ول يضر نرد عل اعقب بعد اذ هد له ذي استهوت شيط في ارض حير له اصحب يدعون ال هد ايت قل ان هد له هو هد امر لنسلم لرب علم', 'quran', NULL, NULL, 'https://quran.com/6/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (860, 'قل اند ندع دعو من دون الل لله م ل ينف نفع فعن ول يضر ضرن ونر نرد علي اعق عقب قبن بعد اذ هدن الل لله كلذ لذي است سته تهو هوت وته الش لشي شيط يطي طين في الر لرض حير يرن له اصح صحب يدع دعو عون ونه الي اله لهد هدي ايت يتن قل ان هدي الل لله هو اله لهد هدي ومر مرن لنس نسل سلم لرب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (861, 'quran:6:72', 'quran', 'quran', '6:72', 72, 860, 'Al-An''am', 'الأنعام', 'وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ', NULL, NULL, 'وان اقيموا الصلاه واتقوه وهو الذي اليه تحشرون', 'ون اقيم صل اتقو وهو ذي يه تحشر', 'quran', NULL, NULL, 'https://quran.com/6/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (861, 'ون اقي قيم يمو الص لصل صله وتق تقو قوه وهو الذ لذي الي ليه تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (862, 'quran:6:73', 'quran', 'quran', '6:73', 73, 861, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ', NULL, NULL, 'وهو الذي خلق السموت والارض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور علم الغيب والشهده وهو الحكيم الخبير', 'وهو ذي خلق سموت ارض حق يوم يقول كن يك قول حق ول ملك يوم ينفخ في صور علم غيب شهد وهو حكيم خبير', 'quran', NULL, NULL, 'https://quran.com/6/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (862, 'وهو الذ لذي خلق الس لسم سمو موت ولر لرض بلح لحق ويو يوم يقو قول كن فيك يكو كون قول وله الح لحق وله الم لمل ملك يوم ينف نفخ في الص لصو صور علم الغ لغي غيب ولش لشه شهد هده وهو الح لحك حكي كيم الخ لخب خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (863, 'quran:6:74', 'quran', 'quran', '6:74', 74, 862, 'Al-An''am', 'الأنعام', 'وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ', NULL, NULL, 'واذ قال ابرهيم لابيه ازر اتتخذ اصناما الهه اني اراك وقومك في ضلل مبين', 'وذ قل ابرهيم لب ازر اتتخذ اصنم هه ان ارك قومك في ضلل مب', 'quran', NULL, NULL, 'https://quran.com/6/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (863, 'وذ قل ابر بره رهي هيم لبي بيه ازر اتت تتخ تخذ اصن صنم اله لهه اني ارك وقو قوم ومك في ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (864, 'quran:6:75', 'quran', 'quran', '6:75', 75, 863, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ', NULL, NULL, 'وكذلك نري ابرهيم ملكوت السموت والارض وليكون من الموقنين', 'كذلك نر ابرهيم ملكوت سموت ارض ليك من موقن', 'quran', NULL, NULL, 'https://quran.com/6/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (864, 'وكذ كذل ذلك نري ابر بره رهي هيم ملك لكو كوت الس لسم سمو موت ولر لرض ولي ليك يكو كون من الم لمو موق وقن قني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (865, 'quran:6:76', 'quran', 'quran', '6:76', 76, 864, 'Al-An''am', 'الأنعام', 'فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ', NULL, NULL, 'فلما جن عليه اليل را كوكبا قال هذا ربي فلما افل قال لا احب الافلين', 'لم جن عل يل ر كوكب قل هذ رب لم افل قل ل احب افل', 'quran', NULL, NULL, 'https://quran.com/6/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (865, 'فلم جن علي ليه الي ليل ر كوك وكب قل هذ ربي فلم افل قل ل احب الف لفل فلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (866, 'quran:6:77', 'quran', 'quran', '6:77', 77, 865, 'Al-An''am', 'الأنعام', 'فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ', NULL, NULL, 'فلما را القمر بازغا قال هذا ربي فلما افل قال لين لم يهدني ربي لاكونن من القوم الضالين', 'لم ر قمر بزغ قل هذ رب لم افل قل لين لم يهدن رب لكونن من قوم ضل', 'quran', NULL, NULL, 'https://quran.com/6/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (866, 'فلم ر الق لقم قمر بزغ قل هذ ربي فلم افل قل لين لم يهد هدن دني ربي لكو كون ونن من الق لقو قوم الض لضل ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (867, 'quran:6:78', 'quran', 'quran', '6:78', 78, 866, 'Al-An''am', 'الأنعام', 'فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ', NULL, NULL, 'فلما را الشمس بازغه قال هذا ربي هذا اكبر فلما افلت قال يا قوم اني بريء مما تشركون', 'لم ر شمس بزغ قل هذ رب هذ اكبر لم افلت قل ي قوم ان بريء مم تشرك', 'quran', NULL, NULL, 'https://quran.com/6/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (867, 'فلم ر الش لشم شمس بزغ زغه قل هذ ربي هذ اكب كبر فلم افل فلت قل ي قوم اني بري ريء مم تشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (868, 'quran:6:79', 'quran', 'quran', '6:79', 79, 867, 'Al-An''am', 'الأنعام', 'إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'اني وجهت وجهي للذي فطر السموت والارض حنيفا وما انا من المشركين', 'ان جهت جه ذي فطر سموت ارض حنيف وم ان من مشرك', 'quran', NULL, NULL, 'https://quran.com/6/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (868, 'اني وجه جهت وجه جهي للذ لذي فطر الس لسم سمو موت ولر لرض حني نيف وم ان من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (869, 'quran:6:80', 'quran', 'quran', '6:80', 80, 868, 'Al-An''am', 'الأنعام', 'وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ', NULL, NULL, 'وحاجه قومه قال اتحجوني في الله وقد هدان ولا اخاف ما تشركون به الا ان يشاء ربي شيا وسع ربي كل شيء علما افلا تتذكرون', 'حج قوم قل اتحجون في له وقد هد ول اخف م تشرك به ال ان يشء رب شي وسع رب كل شيء علم افل تتذكر', 'quran', NULL, NULL, 'https://quran.com/6/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (869, 'وحج حجه قوم ومه قل اتح تحج حجو جون وني في الل لله وقد هدن ول اخف م تشر شرك ركو كون به ال ان يشء ربي شي وسع ربي كل شيء علم افل تتذ تذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (870, 'quran:6:81', 'quran', 'quran', '6:81', 81, 869, 'Al-An''am', 'الأنعام', 'وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'وكيف اخاف ما اشركتم ولا تخافون انكم اشركتم بالله ما لم ينزل به عليكم سلطنا فاي الفريقين احق بالامن ان كنتم تعلمون', 'كيف اخف م اشركتم ول تخف ان اشركتم له م لم ينزل به علي سلط ف فريق احق امن ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/6/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (870, 'وكي كيف اخف م اشر شرك ركت كتم ول تخف خفو فون انك نكم اشر شرك ركت كتم بلل لله م لم ينز نزل به علي ليك يكم سلط لطن في الف لفر فري ريق يقي قين احق بلم لمن ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (871, 'quran:6:82', 'quran', 'quran', '6:82', 82, 870, 'Al-An''am', 'الأنعام', 'ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ', NULL, NULL, 'الذين امنوا ولم يلبسوا ايمنهم بظلم اوليك لهم الامن وهم مهتدون', 'ذين امن ولم يلبس ايمن بظلم اوليك لهم امن وهم مهتد', 'quran', NULL, NULL, 'https://quran.com/6/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (871, 'الذ لذي ذين امن منو ولم يلب لبس بسو ايم يمن منه نهم بظل ظلم اول ولي ليك لهم الم لمن وهم مهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (872, 'quran:6:83', 'quran', 'quran', '6:83', 83, 871, 'Al-An''am', 'الأنعام', 'وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ', NULL, NULL, 'وتلك حجتنا اتينها ابرهيم علي قومه نرفع درجت من نشاء ان ربك حكيم عليم', 'تلك حجت اتين ابرهيم عل قوم نرفع درجت من نشء ان ربك حكيم عليم', 'quran', NULL, NULL, 'https://quran.com/6/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (872, 'وتل تلك حجت جتن اتي تين ينه ابر بره رهي هيم علي قوم ومه نرف رفع درج رجت من نشء ان ربك حكي كيم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (873, 'quran:6:84', 'quran', 'quran', '6:84', 84, 872, 'Al-An''am', 'الأنعام', 'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ', NULL, NULL, 'ووهبنا له اسحق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمن وايوب ويوسف وموسي وهرون وكذلك نجزي المحسنين', 'وهب له اسحق يعقوب كل هدي نوح هدي من قبل ومن ذريت دود سليمن ايوب يوسف موس هر كذلك نجز محسن', 'quran', NULL, NULL, 'https://quran.com/6/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (873, 'ووه وهب هبن له اسح سحق ويع يعق عقو قوب كل هدي دين ونو نوح هدي دين من قبل ومن ذري ريت يته دود وسل سلي ليم يمن ويو يوب ويو يوس وسف ومو موس وسي وهر هرو رون وكذ كذل ذلك نجز جزي الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (874, 'quran:6:85', 'quran', 'quran', '6:85', 85, 873, 'Al-An''am', 'الأنعام', 'وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'وزكريا ويحيي وعيسي والياس كل من الصلحين', 'زكري يحي عيس يس كل من صلح', 'quran', NULL, NULL, 'https://quran.com/6/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (874, 'وزك زكر كري ويح يحي حيي وعي عيس يسي ولي ليس كل من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (875, 'quran:6:86', 'quran', 'quran', '6:86', 86, 874, 'Al-An''am', 'الأنعام', 'وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ', NULL, NULL, 'واسمعيل واليسع ويونس ولوطا وكلا فضلنا علي العلمين', 'اسمعيل يسع يونس لوط كل ضل عل علم', 'quran', NULL, NULL, 'https://quran.com/6/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (875, 'وسم سمع معي عيل ولي ليس يسع ويو يون ونس ولو لوط وكل فضل ضلن علي الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (876, 'quran:6:87', 'quran', 'quran', '6:87', 87, 875, 'Al-An''am', 'الأنعام', 'وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'ومن ابايهم وذريتهم واخونهم واجتبينهم وهدينهم الي صرط مستقيم', 'ومن ابي ذريت اخون اجتبين هدين ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/6/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (876, 'ومن ابي بيه يهم وذر ذري ريت يته تهم وخو خون ونه نهم وجت جتب تبي بين ينه نهم وهد هدي دين ينه نهم الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (877, 'quran:6:88', 'quran', 'quran', '6:88', 88, 876, 'Al-An''am', 'الأنعام', 'ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'ذلك هدي الله يهدي به من يشاء من عباده ولو اشركوا لحبط عنهم ما كانوا يعملون', 'ذلك هد له يهد به من يشء من عبد ولو اشرك لحبط عن م كن يعمل', 'quran', NULL, NULL, 'https://quran.com/6/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (877, 'ذلك هدي الل لله يهد هدي به من يشء من عبد بده ولو اشر شرك ركو لحب حبط عنه نهم م كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (878, 'quran:6:89', 'quran', 'quran', '6:89', 89, 877, 'Al-An''am', 'الأنعام', 'أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ', NULL, NULL, 'اوليك الذين اتينهم الكتب والحكم والنبوه فان يكفر بها هولاء فقد وكلنا بها قوما ليسوا بها بكفرين', 'اوليك ذين اتين كتب حكم نبو فن يكفر به هولء فقد كل به قوم ليس به بكفر', 'quran', NULL, NULL, 'https://quran.com/6/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (878, 'اول ولي ليك الذ لذي ذين اتي تين ينه نهم الك لكت كتب ولح لحك حكم ولن لنب نبو بوه فن يكف كفر به هول ولء فقد وكل كلن به قوم ليس يسو به بكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (879, 'quran:6:90', 'quran', 'quran', '6:90', 90, 878, 'Al-An''am', 'الأنعام', 'أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ', NULL, NULL, 'اوليك الذين هدي الله فبهداهم اقتده قل لا اسلكم عليه اجرا ان هو الا ذكري للعلمين', 'اوليك ذين هد له بهد اقتد قل ل اسل عل اجر ان هو ال ذكر علم', 'quran', NULL, NULL, 'https://quran.com/6/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (879, 'اول ولي ليك الذ لذي ذين هدي الل لله فبه بهد هده دهم اقت قتد تده قل ل اسل سلك لكم علي ليه اجر ان هو ال ذكر كري للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (880, 'quran:6:91', 'quran', 'quran', '6:91', 91, 879, 'Al-An''am', 'الأنعام', 'وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ', NULL, NULL, 'وما قدروا الله حق قدره اذ قالوا ما انزل الله علي بشر من شيء قل من انزل الكتب الذي جاء به موسي نورا وهدي للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا انتم ولا اباوكم قل الله ثم ذرهم في خوضهم يلعبون', 'وم قدر له حق قدر اذ قل م انزل له عل بشر من شيء قل من انزل كتب ذي جء به موس نور هد نس تجعلون قرطيس تبدون تخف كثير علمتم م لم تعلم انتم ول ابو قل له ثم ذر في خوض يلعب', 'quran', NULL, NULL, 'https://quran.com/6/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (880, 'وم قدر درو الل لله حق قدر دره اذ قلو م انز نزل الل لله علي بشر من شيء قل من انز نزل الك لكت كتب الذ لذي جء به موس وسي نور وهد هدي للن لنس تجع جعل علو لون ونه قرط رطي طيس تبد بدو دون ونه وتخ تخف خفو فون كثي ثير وعل علم لمت متم م لم تعل علم لمو انت نتم ول ابو بوك وكم قل الل لله ثم ذره رهم في خوض وضه ضهم يلع لعب عبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (881, 'quran:6:92', 'quran', 'quran', '6:92', 92, 880, 'Al-An''am', 'الأنعام', 'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ', NULL, NULL, 'وهذا كتب انزلنه مبارك مصدق الذي بين يديه ولتنذر ام القري ومن حولها والذين يومنون بالاخره يومنون به وهم علي صلاتهم يحافظون', 'هذ كتب انزلن مبرك مصدق ذي بين يد لتنذر ام قر ومن حول ذين يومن اخر يومن به وهم عل صلت يحفظ', 'quran', NULL, NULL, 'https://quran.com/6/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (881, 'وهذ كتب انز نزل زلن لنه مبر برك مصد صدق الذ لذي بين يدي ديه ولت لتن تنذ نذر ام الق لقر قري ومن حول وله ولذ لذي ذين يوم ومن منو نون بلخ لخر خره يوم ومن منو نون به وهم علي صلت لته تهم يحف حفظ فظو ظون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (882, 'quran:6:93', 'quran', 'quran', '6:93', 93, 881, 'Al-An''am', 'الأنعام', 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ', NULL, NULL, 'ومن اظلم ممن افتري علي الله كذبا او قال اوحي الي ولم يوح اليه شيء ومن قال سانزل مثل ما انزل الله ولو تري اذ الظلمون في غمرت الموت والمليكه باسطوا ايديهم اخرجوا انفسكم اليوم تجزون عذاب الهون بما كنتم تقولون علي الله غير الحق وكنتم عن ايته تستكبرون', 'ومن اظلم ممن افتر عل له كذب او قل اوح ال ولم يوح يه شيء ومن قل سنزل مثل م انزل له ولو تر اذ ظلم في غمرت موت مليك بسط ايدي اخرج انفس يوم تجز عذب هون بم كنتم تقول عل له غير حق كنتم عن ايت تستكبر', 'quran', NULL, NULL, 'https://quran.com/6/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (882, 'ومن اظل ظلم ممن افت فتر تري علي الل لله كذب او قل اوح وحي الي ولم يوح الي ليه شيء ومن قل سنز نزل مثل م انز نزل الل لله ولو تري اذ الظ لظل ظلم لمو مون في غمر مرت الم لمو موت ولم لمل ملي ليك يكه بسط سطو ايد يدي ديه يهم اخر خرج رجو انف نفس فسك سكم الي ليو يوم تجز جزو زون عذب اله لهو هون بم كنت نتم تقو قول ولو لون علي الل لله غير الح لحق وكن كنت نتم عن ايت يته تست ستك تكب كبر برو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (883, 'quran:6:94', 'quran', 'quran', '6:94', 94, 882, 'Al-An''am', 'الأنعام', 'وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ', NULL, NULL, 'ولقد جيتمونا فردي كما خلقنكم اول مره وتركتم ما خولنكم وراء ظهوركم وما نري معكم شفعاءكم الذين زعمتم انهم فيكم شركوا لقد تقطع بينكم وضل عنكم ما كنتم تزعمون', 'لقد جيتمو رد كم خلقن اول مر تركتم م خولن رء ظهور وم نر مع شفعء ذين زعمتم ان يكم شرك لقد تقطع بين وضل عن م كنتم تزعم', 'quran', NULL, NULL, 'https://quran.com/6/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (883, 'ولق لقد جيت يتم تمو مون فرد ردي كم خلق لقن قنك نكم اول مره وتر ترك ركت كتم م خول ولن لنك نكم ورء ظهو هور ورك ركم وم نري معك عكم شفع فعء عءك ءكم الذ لذي ذين زعم عمت متم انه نهم فيك يكم شرك ركو لقد تقط قطع بين ينك نكم وضل عنك نكم م كنت نتم تزع زعم عمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (884, 'quran:6:95', 'quran', 'quran', '6:95', 95, 883, 'Al-An''am', 'الأنعام', 'إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ', NULL, NULL, 'ان الله فالق الحب والنوي يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فاني توفكون', 'ان له فلق حب نو يخرج حي من ميت مخرج ميت من حي ذل له ان توفك', 'quran', NULL, NULL, 'https://quran.com/6/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (884, 'ان الل لله فلق الح لحب ولن لنو نوي يخر خرج الح لحي من الم لمي ميت ومخ مخر خرج الم لمي ميت من الح لحي ذلك لكم الل لله فني توف وفك فكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (885, 'quran:6:96', 'quran', 'quran', '6:96', 96, 884, 'Al-An''am', 'الأنعام', 'فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ', NULL, NULL, 'فالق الاصباح وجعل اليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم', 'فلق اصبح جعل يل سك شمس قمر حسب ذلك تقدير عزيز عليم', 'quran', NULL, NULL, 'https://quran.com/6/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (885, 'فلق الص لصب صبح وجع جعل الي ليل سكن ولش لشم شمس ولق لقم قمر حسب سبن ذلك تقد قدي دير الع لعز عزي زيز الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (886, 'quran:6:97', 'quran', 'quran', '6:97', 97, 885, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ', NULL, NULL, 'وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمت البر والبحر قد فصلنا الايت لقوم يعلمون', 'وهو ذي جعل لكم نجوم لتهتد به في ظلمت بر بحر قد صل ايت لقوم يعلم', 'quran', NULL, NULL, 'https://quran.com/6/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (886, 'وهو الذ لذي جعل لكم الن لنج نجو جوم لته تهت هتد تدو به في ظلم لمت الب لبر ولب لبح بحر قد فصل صلن الي ليت لقو قوم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (887, 'quran:6:98', 'quran', 'quran', '6:98', 98, 886, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ', NULL, NULL, 'وهو الذي انشاكم من نفس وحده فمستقر ومستودع قد فصلنا الايت لقوم يفقهون', 'وهو ذي انش من نفس حد مستقر مستودع قد صل ايت لقوم يفقه', 'quran', NULL, NULL, 'https://quran.com/6/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (887, 'وهو الذ لذي انش نشك شكم من نفس وحد حده فمس مست ستق تقر ومس مست ستو تود ودع قد فصل صلن الي ليت لقو قوم يفق فقه قهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (888, 'quran:6:99', 'quran', 'quran', '6:99', 99, 887, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ', NULL, NULL, 'وهو الذي انزل من السماء ماء فاخرجنا به نبات كل شيء فاخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانيه وجنت من اعناب والزيتون والرمان مشتبها وغير متشبه انظروا الي ثمره اذا اثمر وينعه ان في ذلكم لايت لقوم يومنون', 'وهو ذي انزل من سمء مء اخرج به نب كل شيء اخرج من خضر نخرج من حب متركب ومن نخل من طلع قنو دن جنت من اعنب زيت رم مشتب غير متشب انظر ال ثمر اذ اثمر ينع ان في ذل ليت لقوم يومن', 'quran', NULL, NULL, 'https://quran.com/6/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (888, 'وهو الذ لذي انز نزل من الس لسم سمء مء فخر خرج رجن به نبت كل شيء فخر خرج رجن منه خضر نخر خرج منه حب متر ترك ركب ومن الن لنخ نخل من طلع لعه قنو نون دني نيه وجن جنت من اعن عنب ولز لزي زيت يتو تون ولر لرم رمن مشت شتب تبه وغي غير متش تشب شبه انظ نظر ظرو الي ثمر مره اذ اثم ثمر وين ينع نعه ان في ذلك لكم ليت لقو قوم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (889, 'quran:6:100', 'quran', 'quran', '6:100', 100, 888, 'Al-An''am', 'الأنعام', 'وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', NULL, NULL, 'وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنت بغير علم سبحنه وتعلي عما يصفون', 'جعل لل شركء جن خلق خرق له بن بنت بغير علم سبحن تعل عم يصف', 'quran', NULL, NULL, 'https://quran.com/6/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (889, 'وجع جعل علو لله شرك ركء الج لجن وخل خلق لقه قهم وخر خرق رقو له بني نين وبن بنت بغي غير علم سبح بحن حنه وتع تعل علي عم يصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (890, 'quran:6:101', 'quran', 'quran', '6:101', 101, 889, 'Al-An''am', 'الأنعام', 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'بديع السموت والارض اني يكون له ولد ولم تكن له صحبه وخلق كل شيء وهو بكل شيء عليم', 'بديع سموت ارض ان يك له ولد ولم تكن له صحب خلق كل شيء وهو بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/6/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (890, 'بدي ديع الس لسم سمو موت ولر لرض اني يكو كون له ولد ولم تكن له صحب حبه وخل خلق كل شيء وهو بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (891, 'quran:6:102', 'quran', 'quran', '6:102', 102, 890, 'Al-An''am', 'الأنعام', 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ', NULL, NULL, 'ذلكم الله ربكم لا اله الا هو خلق كل شيء فاعبدوه وهو علي كل شيء وكيل', 'ذل له رب ل ال ال هو خلق كل شيء اعبدو وهو عل كل شيء كيل', 'quran', NULL, NULL, 'https://quran.com/6/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (891, 'ذلك لكم الل لله ربك بكم ل اله ال هو خلق كل شيء فعب عبد بدو دوه وهو علي كل شيء وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (892, 'quran:6:103', 'quran', 'quran', '6:103', 103, 891, 'Al-An''am', 'الأنعام', 'لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ', NULL, NULL, 'لا تدركه الابصر وهو يدرك الابصر وهو اللطيف الخبير', 'ل تدرك ابصر وهو يدرك ابصر وهو لطيف خبير', 'quran', NULL, NULL, 'https://quran.com/6/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (892, 'ل تدر درك ركه الب لبص بصر وهو يدر درك الب لبص بصر وهو الل للط لطي طيف الخ لخب خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (893, 'quran:6:104', 'quran', 'quran', '6:104', 104, 892, 'Al-An''am', 'الأنعام', 'قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ', NULL, NULL, 'قد جاءكم بصاير من ربكم فمن ابصر فلنفسه ومن عمي فعليها وما انا عليكم بحفيظ', 'قد جء بصير من رب فمن ابصر لنفس ومن عم علي وم ان علي بحفيظ', 'quran', NULL, NULL, 'https://quran.com/6/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (893, 'قد جءك ءكم بصي صير من ربك بكم فمن ابص بصر فلن لنف نفس فسه ومن عمي فعل علي ليه وم ان علي ليك يكم بحف حفي فيظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (894, 'quran:6:105', 'quran', 'quran', '6:105', 105, 893, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ', NULL, NULL, 'وكذلك نصرف الايت وليقولوا درست ولنبينه لقوم يعلمون', 'كذلك نصرف ايت ليقول درست لنبين لقوم يعلم', 'quran', NULL, NULL, 'https://quran.com/6/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (894, 'وكذ كذل ذلك نصر صرف الي ليت ولي ليق يقو قول ولو درس رست ولن لنب نبي بين ينه لقو قوم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (895, 'quran:6:106', 'quran', 'quran', '6:106', 106, 894, 'Al-An''am', 'الأنعام', 'ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'اتبع ما اوحي اليك من ربك لا اله الا هو واعرض عن المشركين', 'اتبع م اوح يك من ربك ل ال ال هو اعرض عن مشرك', 'quran', NULL, NULL, 'https://quran.com/6/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (895, 'اتب تبع م اوح وحي الي ليك من ربك ل اله ال هو وعر عرض عن الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (896, 'quran:6:107', 'quran', 'quran', '6:107', 107, 895, 'Al-An''am', 'الأنعام', 'وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ', NULL, NULL, 'ولو شاء الله ما اشركوا وما جعلنك عليهم حفيظا وما انت عليهم بوكيل', 'ولو شء له م اشرك وم جعلنك علي حفيظ وم انت علي بوكيل', 'quran', NULL, NULL, 'https://quran.com/6/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (896, 'ولو شء الل لله م اشر شرك ركو وم جعل علن لنك علي ليه يهم حفي فيظ وم انت علي ليه يهم بوك وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (897, 'quran:6:108', 'quran', 'quran', '6:108', 108, 896, 'Al-An''am', 'الأنعام', 'وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل امه عملهم ثم الي ربهم مرجعهم فينبيهم بما كانوا يعملون', 'ول تسب ذين يدع من دون له يسب له عد بغير علم كذلك زي لكل ام عمل ثم ال رب مرجع ينبي بم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/6/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (897, 'ول تسب سبو الذ لذي ذين يدع دعو عون من دون الل لله فيس يسب سبو الل لله عدو بغي غير علم كذل ذلك زين لكل امه عمل مله لهم ثم الي ربه بهم مرج رجع جعه عهم فين ينب نبي بيه يهم بم كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (898, 'quran:6:109', 'quran', 'quran', '6:109', 109, 897, 'Al-An''am', 'الأنعام', 'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ', NULL, NULL, 'واقسموا بالله جهد ايمنهم لين جاءتهم ايه ليومنن بها قل انما الايت عند الله وما يشعركم انها اذا جاءت لا يومنون', 'اقسم له جهد ايمن لين جءت اي ليومنن به قل انم ايت عند له وم يشعر ان اذ جءت ل يومن', 'quran', NULL, NULL, 'https://quran.com/6/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (898, 'وقس قسم سمو بلل لله جهد ايم يمن منه نهم لين جءت ءته تهم ايه ليو يوم ومن منن به قل انم الي ليت عند الل لله وم يشع شعر عرك ركم انه اذ جءت ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (899, 'quran:6:110', 'quran', 'quran', '6:110', 110, 898, 'Al-An''am', 'الأنعام', 'وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', NULL, NULL, 'ونقلب افدتهم وابصرهم كما لم يومنوا به اول مره ونذرهم في طغينهم يعمهون', 'نقلب افدت ابصر كم لم يومن به اول مر نذر في طغين يعمه', 'quran', NULL, NULL, 'https://quran.com/6/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (899, 'ونق نقل قلب افد فدت دته تهم وبص بصر صره رهم كم لم يوم ومن منو به اول مره ونذ نذر ذره رهم في طغي غين ينه نهم يعم عمه مهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (900, 'quran:6:111', 'quran', 'quran', '6:111', 111, 899, 'Al-An''am', 'الأنعام', 'وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ', NULL, NULL, 'ولو اننا نزلنا اليهم المليكه وكلمهم الموتي وحشرنا عليهم كل شيء قبلا ما كانوا ليومنوا الا ان يشاء الله ولكن اكثرهم يجهلون', 'ولو ان نزل يهم مليك كلم موت حشر علي كل شيء قبل م كن ليومن ال ان يشء له لكن اكثر يجهل', 'quran', NULL, NULL, 'https://quran.com/6/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (900, 'ولو انن نزل زلن الي ليه يهم الم لمل ملي ليك يكه وكل كلم لمه مهم الم لمو موت وتي وحش حشر شرن علي ليه يهم كل شيء قبل م كنو ليو يوم ومن منو ال ان يشء الل لله ولك لكن اكث كثر ثره رهم يجه جهل هلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (901, 'quran:6:112', 'quran', 'quran', '6:112', 112, 900, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ', NULL, NULL, 'وكذلك جعلنا لكل نبي عدوا شيطين الانس والجن يوحي بعضهم الي بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون', 'كذلك جعل لكل نب عد شيط انس جن يوح بعض ال بعض زخرف قول غرور ولو شء ربك م علو ذر وم يفتر', 'quran', NULL, NULL, 'https://quran.com/6/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (901, 'وكذ كذل ذلك جعل علن لكل نبي عدو شيط يطي طين الن لنس ولج لجن يوح وحي بعض عضه ضهم الي بعض زخر خرف الق لقو قول غرو رور ولو شء ربك م فعل علو لوه فذر ذره رهم وم يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (902, 'quran:6:113', 'quran', 'quran', '6:113', 113, 901, 'Al-An''am', 'الأنعام', 'وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ', NULL, NULL, 'ولتصغي اليه افده الذين لا يومنون بالاخره وليرضوه وليقترفوا ما هم مقترفون', 'لتصغ يه افد ذين ل يومن اخر ليرضو ليقترف م هم مقترف', 'quran', NULL, NULL, 'https://quran.com/6/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (902, 'ولت لتص تصغ صغي الي ليه افد فده الذ لذي ذين ل يوم ومن منو نون بلخ لخر خره ولي لير يرض رضو ضوه ولي ليق يقت قتر ترف رفو م هم مقت قتر ترف رفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (903, 'quran:6:114', 'quran', 'quran', '6:114', 114, 902, 'Al-An''am', 'الأنعام', 'أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ', NULL, NULL, 'افغير الله ابتغي حكما وهو الذي انزل اليكم الكتب مفصلا والذين اتينهم الكتب يعلمون انه منزل من ربك بالحق فلا تكونن من الممترين', 'افغير له ابتغ حكم وهو ذي انزل يكم كتب مفصل ذين اتين كتب يعلم ان منزل من ربك حق فل تكونن من ممتر', 'quran', NULL, NULL, 'https://quran.com/6/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (903, 'افغ فغي غير الل لله ابت بتغ تغي حكم وهو الذ لذي انز نزل الي ليك يكم الك لكت كتب مفص فصل ولذ لذي ذين اتي تين ينه نهم الك لكت كتب يعل علم لمو مون انه منز نزل من ربك بلح لحق فل تكو كون ونن من الم لمم ممت متر تري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (904, 'quran:6:115', 'quran', 'quran', '6:115', 115, 903, 'Al-An''am', 'الأنعام', 'وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'وتمت كلمت ربك صدقا وعدلا لا مبدل لكلمته وهو السميع العليم', 'تمت كلمت ربك صدق عدل ل مبدل لكلمت وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/6/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (904, 'وتم تمت كلم لمت ربك صدق وعد عدل ل مبد بدل لكل كلم لمت مته وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (905, 'quran:6:116', 'quran', 'quran', '6:116', 116, 904, 'Al-An''am', 'الأنعام', 'وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ', NULL, NULL, 'وان تطع اكثر من في الارض يضلوك عن سبيل الله ان يتبعون الا الظن وان هم الا يخرصون', 'ون تطع اكثر من في ارض يضلوك عن سبيل له ان يتبع ال ظن ون هم ال يخرص', 'quran', NULL, NULL, 'https://quran.com/6/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (905, 'ون تطع اكث كثر من في الر لرض يضل ضلو لوك عن سبي بيل الل لله ان يتب تبع بعو عون ال الظ لظن ون هم ال يخر خرص رصو صون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (906, 'quran:6:117', 'quran', 'quran', '6:117', 117, 905, 'Al-An''am', 'الأنعام', 'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ', NULL, NULL, 'ان ربك هو اعلم من يضل عن سبيله وهو اعلم بالمهتدين', 'ان ربك هو اعلم من يضل عن سبيل وهو اعلم مهتد', 'quran', NULL, NULL, 'https://quran.com/6/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (906, 'ان ربك هو اعل علم من يضل عن سبي بيل يله وهو اعل علم بلم لمه مهت هتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (907, 'quran:6:118', 'quran', 'quran', '6:118', 118, 906, 'Al-An''am', 'الأنعام', 'فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ', NULL, NULL, 'فكلوا مما ذكر اسم الله عليه ان كنتم بايته مومنين', 'كل مم ذكر اسم له عل ان كنتم بيت مومن', 'quran', NULL, NULL, 'https://quran.com/6/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (907, 'فكل كلو مم ذكر اسم الل لله علي ليه ان كنت نتم بيت يته موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (908, 'quran:6:119', 'quran', 'quran', '6:119', 119, 907, 'Al-An''am', 'الأنعام', 'وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ', NULL, NULL, 'وما لكم الا تاكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم الا ما اضطررتم اليه وان كثيرا ليضلون باهوايهم بغير علم ان ربك هو اعلم بالمعتدين', 'وم لكم ال تكل مم ذكر اسم له عل وقد فصل لكم م حرم علي ال م اضطررتم يه ون كثير ليضل بهوي بغير علم ان ربك هو اعلم معتد', 'quran', NULL, NULL, 'https://quran.com/6/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (908, 'وم لكم ال تكل كلو مم ذكر اسم الل لله علي ليه وقد فصل لكم م حرم علي ليك يكم ال م اضط ضطر طرر ررت رتم الي ليه ون كثي ثير ليض يضل ضلو لون بهو هوي ويه يهم بغي غير علم ان ربك هو اعل علم بلم لمع معت عتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (909, 'quran:6:120', 'quran', 'quran', '6:120', 120, 908, 'Al-An''am', 'الأنعام', 'وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ', NULL, NULL, 'وذروا ظهر الاثم وباطنه ان الذين يكسبون الاثم سيجزون بما كانوا يقترفون', 'ذر ظهر اثم بطن ان ذين يكسب اثم سيجز بم كن يقترف', 'quran', NULL, NULL, 'https://quran.com/6/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (909, 'وذر ذرو ظهر الث لثم وبط بطن طنه ان الذ لذي ذين يكس كسب سبو بون الث لثم سيج يجز جزو زون بم كنو يقت قتر ترف رفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (910, 'quran:6:121', 'quran', 'quran', '6:121', 121, 909, 'Al-An''am', 'الأنعام', 'وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ', NULL, NULL, 'ولا تاكلوا مما لم يذكر اسم الله عليه وانه لفسق وان الشيطين ليوحون الي اوليايهم ليجدلوكم وان اطعتموهم انكم لمشركون', 'ول تكل مم لم يذكر اسم له عل ان لفسق ون شيط ليوح ال اوليي ليجدلو ون اطعتمو ان لمشرك', 'quran', NULL, NULL, 'https://quran.com/6/121');
INSERT INTO units_tri_src (id, ar_tri) VALUES (910, 'ول تكل كلو مم لم يذك ذكر اسم الل لله علي ليه ونه لفس فسق ون الش لشي شيط يطي طين ليو يوح وحو حون الي اول ولي ليي ييه يهم ليج يجد جدل دلو لوك وكم ون اطع طعت عتم تمو موه وهم انك نكم لمش مشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (911, 'quran:6:122', 'quran', 'quran', '6:122', 122, 910, 'Al-An''am', 'الأنعام', 'أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'اومن كان ميتا فاحيينه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمت ليس بخارج منها كذلك زين للكفرين ما كانوا يعملون', 'اومن كن ميت احيين جعل له نور يمش به في نس كمن مثل في ظلمت ليس بخرج من كذلك زين كفر م كن يعمل', 'quran', NULL, NULL, 'https://quran.com/6/122');
INSERT INTO units_tri_src (id, ar_tri) VALUES (911, 'اوم ومن كن ميت فحي حيي يين ينه وجع جعل علن له نور يمش مشي به في الن لنس كمن مثل ثله في الظ لظل ظلم لمت ليس بخر خرج منه كذل ذلك زين للك لكف كفر فري رين م كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (912, 'quran:6:123', 'quran', 'quran', '6:123', 123, 911, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ', NULL, NULL, 'وكذلك جعلنا في كل قريه اكبر مجرميها ليمكروا فيها وما يمكرون الا بانفسهم وما يشعرون', 'كذلك جعل في كل قر اكبر مجرمي ليمكر يه وم يمكر ال بنفس وم يشعر', 'quran', NULL, NULL, 'https://quran.com/6/123');
INSERT INTO units_tri_src (id, ar_tri) VALUES (912, 'وكذ كذل ذلك جعل علن في كل قري ريه اكب كبر مجر جرم رمي ميه ليم يمك مكر كرو فيه وم يمك مكر كرو رون ال بنف نفس فسه سهم وم يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (913, 'quran:6:124', 'quran', 'quran', '6:124', 124, 912, 'Al-An''am', 'الأنعام', 'وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ', NULL, NULL, 'واذا جاءتهم ايه قالوا لن نومن حتي نوتي مثل ما اوتي رسل الله الله اعلم حيث يجعل رسالته سيصيب الذين اجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون', 'اذ جءت اي قل لن نومن حت نوت مثل م اوت رسل له له اعلم حيث يجعل رسلت سيصيب ذين اجرم صغر عند له عذب شديد بم كن يمكر', 'quran', NULL, NULL, 'https://quran.com/6/124');
INSERT INTO units_tri_src (id, ar_tri) VALUES (913, 'وذ جءت ءته تهم ايه قلو لن نوم ومن حتي نوت وتي مثل م اوت وتي رسل الل لله الل لله اعل علم حيث يجع جعل رسل سلت لته سيص يصي صيب الذ لذي ذين اجر جرم رمو صغر عند الل لله وعذ عذب شدي ديد بم كنو يمك مكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (914, 'quran:6:125', 'quran', 'quran', '6:125', 125, 913, 'Al-An''am', 'الأنعام', 'فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ', NULL, NULL, 'فمن يرد الله ان يهديه يشرح صدره للاسلم ومن يرد ان يضله يجعل صدره ضيقا حرجا كانما يصعد في السماء كذلك يجعل الله الرجس علي الذين لا يومنون', 'فمن يرد له ان يهد يشرح صدر اسلم ومن يرد ان يضل يجعل صدر ضيق حرج كنم يصعد في سمء كذلك يجعل له رجس عل ذين ل يومن', 'quran', NULL, NULL, 'https://quran.com/6/125');
INSERT INTO units_tri_src (id, ar_tri) VALUES (914, 'فمن يرد الل لله ان يهد هدي ديه يشر شرح صدر دره للس لسل سلم ومن يرد ان يضل ضله يجع جعل صدر دره ضيق حرج كنم يصع صعد في الس لسم سمء كذل ذلك يجع جعل الل لله الر لرج رجس علي الذ لذي ذين ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (915, 'quran:6:126', 'quran', 'quran', '6:126', 126, 914, 'Al-An''am', 'الأنعام', 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ', NULL, NULL, 'وهذا صرط ربك مستقيما قد فصلنا الايت لقوم يذكرون', 'هذ صرط ربك مستقيم قد صل ايت لقوم يذكر', 'quran', NULL, NULL, 'https://quran.com/6/126');
INSERT INTO units_tri_src (id, ar_tri) VALUES (915, 'وهذ صرط ربك مست ستق تقي قيم قد فصل صلن الي ليت لقو قوم يذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (916, 'quran:6:127', 'quran', 'quran', '6:127', 127, 915, 'Al-An''am', 'الأنعام', 'لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'لهم دار السلم عند ربهم وهو وليهم بما كانوا يعملون', 'لهم در سلم عند رب وهو لي بم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/6/127');
INSERT INTO units_tri_src (id, ar_tri) VALUES (916, 'لهم در الس لسل سلم عند ربه بهم وهو ولي ليه يهم بم كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (917, 'quran:6:128', 'quran', 'quran', '6:128', 128, 916, 'Al-An''am', 'الأنعام', 'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ', NULL, NULL, 'ويوم يحشرهم جميعا يا معشر الجن قد استكثرتم من الانس وقال اولياوهم من الانس ربنا استمتع بعضنا ببعض وبلغنا اجلنا الذي اجلت لنا قال النار مثواكم خلدين فيها الا ما شاء الله ان ربك حكيم عليم', 'يوم يحشر جميع ي معشر جن قد استكثرتم من انس قل اوليو من انس رب استمتع بعض ببعض بلغ اجل ذي اجلت لن قل نر مثو خلد يه ال م شء له ان ربك حكيم عليم', 'quran', NULL, NULL, 'https://quran.com/6/128');
INSERT INTO units_tri_src (id, ar_tri) VALUES (917, 'ويو يوم يحش حشر شره رهم جمي ميع ي معش عشر الج لجن قد است ستك تكث كثر ثرت رتم من الن لنس وقل اول ولي ليو يوه وهم من الن لنس ربن است ستم تمت متع بعض عضن ببع بعض وبل بلغ لغن اجل جلن الذ لذي اجل جلت لن قل الن لنر مثو ثوك وكم خلد لدي دين فيه ال م شء الل لله ان ربك حكي كيم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (918, 'quran:6:129', 'quran', 'quran', '6:129', 129, 917, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ', NULL, NULL, 'وكذلك نولي بعض الظلمين بعضا بما كانوا يكسبون', 'كذلك نول بعض ظلم بعض بم كن يكسب', 'quran', NULL, NULL, 'https://quran.com/6/129');
INSERT INTO units_tri_src (id, ar_tri) VALUES (918, 'وكذ كذل ذلك نول ولي بعض الظ لظل ظلم لمي مين بعض بم كنو يكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (919, 'quran:6:130', 'quran', 'quran', '6:130', 130, 918, 'Al-An''am', 'الأنعام', 'يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ', NULL, NULL, 'يا معشر الجن والانس الم ياتكم رسل منكم يقصون عليكم ايتي وينذرونكم لقاء يومكم هذا قالوا شهدنا علي انفسنا وغرتهم الحياه الدنيا وشهدوا علي انفسهم انهم كانوا كفرين', 'ي معشر جن انس الم يت رسل من يقص علي ايت ينذرون لقء يوم هذ قل شهد عل انفس غرت حي دني شهد عل انفس ان كن كفر', 'quran', NULL, NULL, 'https://quran.com/6/130');
INSERT INTO units_tri_src (id, ar_tri) VALUES (919, 'ي معش عشر الج لجن ولن لنس الم يتك تكم رسل منك نكم يقص قصو صون علي ليك يكم ايت يتي وين ينذ نذر ذرو رون ونك نكم لقء يوم ومك مكم هذ قلو شهد هدن علي انف نفس فسن وغر غرت رته تهم الح لحي حيه الد لدن دني وشه شهد هدو علي انف نفس فسه سهم انه نهم كنو كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (920, 'quran:6:131', 'quran', 'quran', '6:131', 131, 919, 'Al-An''am', 'الأنعام', 'ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ', NULL, NULL, 'ذلك ان لم يكن ربك مهلك القري بظلم واهلها غفلون', 'ذلك ان لم يكن ربك مهلك قر بظلم اهل غفل', 'quran', NULL, NULL, 'https://quran.com/6/131');
INSERT INTO units_tri_src (id, ar_tri) VALUES (920, 'ذلك ان لم يكن ربك مهل هلك الق لقر قري بظل ظلم وهل هله غفل فلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (921, 'quran:6:132', 'quran', 'quran', '6:132', 132, 920, 'Al-An''am', 'الأنعام', 'وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ', NULL, NULL, 'ولكل درجت مما عملوا وما ربك بغفل عما يعملون', 'لكل درجت مم عمل وم ربك بغفل عم يعمل', 'quran', NULL, NULL, 'https://quran.com/6/132');
INSERT INTO units_tri_src (id, ar_tri) VALUES (921, 'ولك لكل درج رجت مم عمل ملو وم ربك بغف غفل عم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (922, 'quran:6:133', 'quran', 'quran', '6:133', 133, 921, 'Al-An''am', 'الأنعام', 'وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ', NULL, NULL, 'وربك الغني ذو الرحمه ان يشا يذهبكم ويستخلف من بعدكم ما يشاء كما انشاكم من ذريه قوم اخرين', 'ربك غن ذو رحم ان يش يذهب يستخلف من بعد م يشء كم انش من ذر قوم اخر', 'quran', NULL, NULL, 'https://quran.com/6/133');
INSERT INTO units_tri_src (id, ar_tri) VALUES (922, 'ورب ربك الغ لغن غني ذو الر لرح رحم حمه ان يش يذه ذهب هبك بكم ويس يست ستخ تخل خلف من بعد عدك دكم م يشء كم انش نشك شكم من ذري ريه قوم اخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (923, 'quran:6:134', 'quran', 'quran', '6:134', 134, 922, 'Al-An''am', 'الأنعام', 'إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ', NULL, NULL, 'ان ما توعدون لات وما انتم بمعجزين', 'ان م توعد لت وم انتم بمعجز', 'quran', NULL, NULL, 'https://quran.com/6/134');
INSERT INTO units_tri_src (id, ar_tri) VALUES (923, 'ان م توع وعد عدو دون لت وم انت نتم بمع معج عجز جزي زين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (924, 'quran:6:135', 'quran', 'quran', '6:135', 135, 923, 'Al-An''am', 'الأنعام', 'قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ', NULL, NULL, 'قل يا قوم اعملوا علي مكانتكم اني عامل فسوف تعلمون من تكون له عقبه الدار انه لا يفلح الظلمون', 'قل ي قوم اعمل عل مكنت ان عمل سوف تعلم من تك له عقب در ان ل يفلح ظلم', 'quran', NULL, NULL, 'https://quran.com/6/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (924, 'قل ي قوم اعم عمل ملو علي مكن كنت نتك تكم اني عمل فسو سوف تعل علم لمو مون من تكو كون له عقب قبه الد لدر انه ل يفل فلح الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (925, 'quran:6:136', 'quran', 'quran', '6:136', 136, 924, 'Al-An''am', 'الأنعام', 'وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ', NULL, NULL, 'وجعلوا لله مما ذرا من الحرث والانعم نصيبا فقالوا هذا لله بزعمهم وهذا لشركاينا فما كان لشركايهم فلا يصل الي الله وما كان لله فهو يصل الي شركايهم ساء ما يحكمون', 'جعل لل مم ذر من حرث انعم نصيب قل هذ لل بزعم هذ لشركي فم كن لشركي فل يصل ال له وم كن لل فهو يصل ال شركي سء م يحكم', 'quran', NULL, NULL, 'https://quran.com/6/136');
INSERT INTO units_tri_src (id, ar_tri) VALUES (925, 'وجع جعل علو لله مم ذر من الح لحر حرث ولن لنع نعم نصي صيب فقل قلو هذ لله بزع زعم عمه مهم وهذ لشر شرك ركي كين فم كن لشر شرك ركي كيه يهم فل يصل الي الل لله وم كن لله فهو يصل الي شرك ركي كيه يهم سء م يحك حكم كمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (926, 'quran:6:137', 'quran', 'quran', '6:137', 137, 925, 'Al-An''am', 'الأنعام', 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ', NULL, NULL, 'وكذلك زين لكثير من المشركين قتل اولدهم شركاوهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون', 'كذلك زين لكثير من مشرك قتل اولد شركو ليردو ليلبس علي دين ولو شء له م علو ذر وم يفتر', 'quran', NULL, NULL, 'https://quran.com/6/137');
INSERT INTO units_tri_src (id, ar_tri) VALUES (926, 'وكذ كذل ذلك زين لكث كثي ثير من الم لمش مشر شرك ركي كين قتل اول ولد لده دهم شرك ركو كوه وهم لير يرد ردو دوه وهم ولي ليل يلب لبس بسو علي ليه يهم دين ينه نهم ولو شء الل لله م فعل علو لوه فذر ذره رهم وم يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (927, 'quran:6:138', 'quran', 'quran', '6:138', 138, 926, 'Al-An''am', 'الأنعام', 'وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ', NULL, NULL, 'وقالوا هذه انعم وحرث حجر لا يطعمها الا من نشاء بزعمهم وانعم حرمت ظهورها وانعم لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون', 'قل هذ انعم حرث حجر ل يطعم ال من نشء بزعم انعم حرمت ظهور انعم ل يذكر اسم له علي افترء عل سيجزي بم كن يفتر', 'quran', NULL, NULL, 'https://quran.com/6/138');
INSERT INTO units_tri_src (id, ar_tri) VALUES (927, 'وقل قلو هذه انع نعم وحر حرث حجر ل يطع طعم عمه ال من نشء بزع زعم عمه مهم ونع نعم حرم رمت ظهو هور وره ونع نعم ل يذك ذكر كرو رون اسم الل لله علي ليه افت فتر ترء علي ليه سيج يجز جزي زيه يهم بم كنو يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (928, 'quran:6:139', 'quran', 'quran', '6:139', 139, 927, 'Al-An''am', 'الأنعام', 'وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ', NULL, NULL, 'وقالوا ما في بطون هذه الانعم خالصه لذكورنا ومحرم علي ازوجنا وان يكن ميته فهم فيه شركاء سيجزيهم وصفهم انه حكيم عليم', 'قل م في بط هذ انعم خلص لذكور محرم عل ازوج ون يكن ميت فهم في شركء سيجزي صف ان حكيم عليم', 'quran', NULL, NULL, 'https://quran.com/6/139');
INSERT INTO units_tri_src (id, ar_tri) VALUES (928, 'وقل قلو م في بطو طون هذه الن لنع نعم خلص لصه لذك ذكو كور ورن ومح محر حرم علي ازو زوج وجن ون يكن ميت يته فهم فيه شرك ركء سيج يجز جزي زيه يهم وصف صفه فهم انه حكي كيم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (929, 'quran:6:140', 'quran', 'quran', '6:140', 140, 928, 'Al-An''am', 'الأنعام', 'قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ', NULL, NULL, 'قد خسر الذين قتلوا اولدهم سفها بغير علم وحرموا ما رزقهم الله افتراء علي الله قد ضلوا وما كانوا مهتدين', 'قد خسر ذين قتل اولد سف بغير علم حرم م رزق له افترء عل له قد ضل وم كن مهتد', 'quran', NULL, NULL, 'https://quran.com/6/140');
INSERT INTO units_tri_src (id, ar_tri) VALUES (929, 'قد خسر الذ لذي ذين قتل تلو اول ولد لده دهم سفه بغي غير علم وحر حرم رمو م رزق زقه قهم الل لله افت فتر ترء علي الل لله قد ضلو وم كنو مهت هتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (930, 'quran:6:141', 'quran', 'quran', '6:141', 141, 929, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ', NULL, NULL, 'وهو الذي انشا جنت معروشت وغير معروشت والنخل والزرع مختلفا اكله والزيتون والرمان متشبها وغير متشبه كلوا من ثمره اذا اثمر واتوا حقه يوم حصاده ولا تسرفوا انه لا يحب المسرفين', 'وهو ذي انش جنت معروشت غير معروشت نخل زرع مختلف اكل زيت رم متشب غير متشب كل من ثمر اذ اثمر ات حق يوم حصد ول تسرف ان ل يحب مسرف', 'quran', NULL, NULL, 'https://quran.com/6/141');
INSERT INTO units_tri_src (id, ar_tri) VALUES (930, 'وهو الذ لذي انش جنت معر عرو روش وشت وغي غير معر عرو روش وشت ولن لنخ نخل ولز لزر زرع مخت ختل تلف اكل كله ولز لزي زيت يتو تون ولر لرم رمن متش تشب شبه وغي غير متش تشب شبه كلو من ثمر مره اذ اثم ثمر وتو حقه يوم حصد صده ول تسر سرف رفو انه ل يحب الم لمس مسر سرف رفي فين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (931, 'quran:6:142', 'quran', 'quran', '6:142', 142, 930, 'Al-An''am', 'الأنعام', 'وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ', NULL, NULL, 'ومن الانعم حموله وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 'ومن انعم حمول فرش كل مم رزق له ول تتبع خطوت شيطن ان لكم عدو مب', 'quran', NULL, NULL, 'https://quran.com/6/142');
INSERT INTO units_tri_src (id, ar_tri) VALUES (931, 'ومن الن لنع نعم حمو مول وله وفر فرش كلو مم رزق زقك قكم الل لله ول تتب تبع بعو خطو طوت الش لشي شيط يطن انه لكم عدو مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (932, 'quran:6:143', 'quran', 'quran', '6:143', 143, 931, 'Al-An''am', 'الأنعام', 'ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'ثمنيه ازوج من الضان اثنين ومن المعز اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين نبوني بعلم ان كنتم صدقين', 'ثمن ازوج من ضن اثن ومن معز اثن قل ذكر حرم ام انثي ام اشتملت عل ارحم انثي نبون بعلم ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/6/143');
INSERT INTO units_tri_src (id, ar_tri) VALUES (932, 'ثمن مني نيه ازو زوج من الض لضن اثن ثني نين ومن الم لمع معز اثن ثني نين قل الذ لذك ذكر كري رين حرم ام الن لنث نثي ثيي يين ام اشت شتم تمل ملت علي ليه ارح رحم الن لنث نثي ثيي يين نبو بون وني بعل علم ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (933, 'quran:6:144', 'quran', 'quran', '6:144', 144, 932, 'Al-An''am', 'الأنعام', 'وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ', NULL, NULL, 'ومن الابل اثنين ومن البقر اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين ام كنتم شهداء اذ وصاكم الله بهذا فمن اظلم ممن افتري علي الله كذبا ليضل الناس بغير علم ان الله لا يهدي القوم الظلمين', 'ومن ابل اثن ومن بقر اثن قل ذكر حرم ام انثي ام اشتملت عل ارحم انثي ام كنتم شهدء اذ ص له بهذ فمن اظلم ممن افتر عل له كذب ليضل نس بغير علم ان له ل يهد قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/6/144');
INSERT INTO units_tri_src (id, ar_tri) VALUES (933, 'ومن الب لبل اثن ثني نين ومن الب لبق بقر اثن ثني نين قل الذ لذك ذكر كري رين حرم ام الن لنث نثي ثيي يين ام اشت شتم تمل ملت علي ليه ارح رحم الن لنث نثي ثيي يين ام كنت نتم شهد هدء اذ وصك صكم الل لله بهذ فمن اظل ظلم ممن افت فتر تري علي الل لله كذب ليض يضل الن لنس بغي غير علم ان الل لله ل يهد هدي الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (934, 'quran:6:145', 'quran', 'quran', '6:145', 145, 933, 'Al-An''am', 'الأنعام', 'قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'قل لا اجد في ما اوحي الي محرما علي طاعم يطعمه الا ان يكون ميته او دما مسفوحا او لحم خنزير فانه رجس او فسقا اهل لغير الله به فمن اضطر غير باغ ولا عاد فان ربك غفور رحيم', 'قل ل اجد في م اوح ال محرم عل طعم يطعم ال ان يك ميت او دم مسفوح او لحم خنزير ان رجس او سق اهل لغير له به فمن اضطر غير بغ ول عد فن ربك غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/6/145');
INSERT INTO units_tri_src (id, ar_tri) VALUES (934, 'قل ل اجد في م اوح وحي الي محر حرم علي طعم يطع طعم عمه ال ان يكو كون ميت يته او دم مسف سفو فوح او لحم خنز نزي زير فنه رجس او فسق اهل لغي غير الل لله به فمن اضط ضطر غير بغ ول عد فن ربك غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (935, 'quran:6:146', 'quran', 'quran', '6:146', 146, 934, 'Al-An''am', 'الأنعام', 'وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ', NULL, NULL, 'وعلي الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما الا ما حملت ظهورهما او الحوايا او ما اختلط بعظم ذلك جزينهم ببغيهم وانا لصدقون', 'عل ذين هد حرم كل ذي ظفر ومن بقر غنم حرم علي شحومهم ال م حملت ظهورهم او حوي او م اختلط بعظم ذلك جزين ببغي ان لصدق', 'quran', NULL, NULL, 'https://quran.com/6/146');
INSERT INTO units_tri_src (id, ar_tri) VALUES (935, 'وعل علي الذ لذي ذين هدو حرم رمن كل ذي ظفر ومن الب لبق بقر ولغ لغن غنم حرم رمن علي ليه يهم شحو حوم ومه مهم ال م حمل ملت ظهو هور وره رهم او الح لحو حوي او م اخت ختل تلط بعظ عظم ذلك جزي زين ينه نهم ببغ بغي غيه يهم ون لصد صدق دقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (936, 'quran:6:147', 'quran', 'quran', '6:147', 147, 935, 'Al-An''am', 'الأنعام', 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ', NULL, NULL, 'فان كذبوك فقل ربكم ذو رحمه وسعه ولا يرد باسه عن القوم المجرمين', 'فن كذبوك فقل رب ذو رحم سع ول يرد بس عن قوم مجرم', 'quran', NULL, NULL, 'https://quran.com/6/147');
INSERT INTO units_tri_src (id, ar_tri) VALUES (936, 'فن كذب ذبو بوك فقل ربك بكم ذو رحم حمه وسع سعه ول يرد بسه عن الق لقو قوم الم لمج مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (937, 'quran:6:148', 'quran', 'quran', '6:148', 148, 936, 'Al-An''am', 'الأنعام', 'سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ', NULL, NULL, 'سيقول الذين اشركوا لو شاء الله ما اشركنا ولا اباونا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتي ذاقوا باسنا قل هل عندكم من علم فتخرجوه لنا ان تتبعون الا الظن وان انتم الا تخرصون', 'سيقول ذين اشرك لو شء له م اشرك ول ابو ول حرم من شيء كذلك كذب ذين من قبل حت ذق بس قل هل عند من علم تخرجو لن ان تتبع ال ظن ون انتم ال تخرص', 'quran', NULL, NULL, 'https://quran.com/6/148');
INSERT INTO units_tri_src (id, ar_tri) VALUES (937, 'سيق يقو قول الذ لذي ذين اشر شرك ركو لو شء الل لله م اشر شرك ركن ول ابو بون ول حرم رمن من شيء كذل ذلك كذب الذ لذي ذين من قبل بله لهم حتي ذقو بسن قل هل عند ندك دكم من علم فتخ تخر خرج رجو جوه لن ان تتب تبع بعو عون ال الظ لظن ون انت نتم ال تخر خرص رصو صون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (938, 'quran:6:149', 'quran', 'quran', '6:149', 149, 937, 'Al-An''am', 'الأنعام', 'قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ', NULL, NULL, 'قل فلله الحجه البلغه فلو شاء لهداكم اجمعين', 'قل لل حج بلغ فلو شء لهد اجمع', 'quran', NULL, NULL, 'https://quran.com/6/149');
INSERT INTO units_tri_src (id, ar_tri) VALUES (938, 'قل فلل لله الح لحج حجه الب لبل بلغ لغه فلو شء لهد هدك دكم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (939, 'quran:6:150', 'quran', 'quran', '6:150', 150, 938, 'Al-An''am', 'الأنعام', 'قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ', NULL, NULL, 'قل هلم شهداءكم الذين يشهدون ان الله حرم هذا فان شهدوا فلا تشهد معهم ولا تتبع اهواء الذين كذبوا بايتنا والذين لا يومنون بالاخره وهم بربهم يعدلون', 'قل هلم شهدء ذين يشهد ان له حرم هذ فن شهد فل تشهد مع ول تتبع اهوء ذين كذب بيت ذين ل يومن اخر وهم برب يعدل', 'quran', NULL, NULL, 'https://quran.com/6/150');
INSERT INTO units_tri_src (id, ar_tri) VALUES (939, 'قل هلم شهد هدء دءك ءكم الذ لذي ذين يشه شهد هدو دون ان الل لله حرم هذ فن شهد هدو فل تشه شهد معه عهم ول تتب تبع اهو هوء الذ لذي ذين كذب ذبو بيت يتن ولذ لذي ذين ل يوم ومن منو نون بلخ لخر خره وهم برب ربه بهم يعد عدل دلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (940, 'quran:6:151', 'quran', 'quran', '6:151', 151, 939, 'Al-An''am', 'الأنعام', 'قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', NULL, NULL, 'قل تعالوا اتل ما حرم ربكم عليكم الا تشركوا به شيا وبالولدين احسنا ولا تقتلوا اولدكم من املق نحن نرزقكم واياهم ولا تقربوا الفوحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله الا بالحق ذلكم وصاكم به لعلكم تعقلون', 'قل تعل اتل م حرم رب علي ال تشرك به شي ولد احس ول تقتل اولد من املق نحن نرزق اي ول تقرب فوحش م ظهر من وم بطن ول تقتل نفس تي حرم له ال حق ذل ص به لعل تعقل', 'quran', NULL, NULL, 'https://quran.com/6/151');
INSERT INTO units_tri_src (id, ar_tri) VALUES (940, 'قل تعل علو اتل م حرم ربك بكم علي ليك يكم ال تشر شرك ركو به شي وبل بلو لول ولد لدي دين احس حسن ول تقت قتل تلو اول ولد لدك دكم من امل ملق نحن نرز رزق زقك قكم ويه يهم ول تقر قرب ربو الف لفو فوح وحش م ظهر منه وم بطن ول تقت قتل تلو الن لنف نفس الت لتي حرم الل لله ال بلح لحق ذلك لكم وصك صكم به لعل علك لكم تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (941, 'quran:6:152', 'quran', 'quran', '6:152', 152, 940, 'Al-An''am', 'الأنعام', 'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ', NULL, NULL, 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا الكيل والميزان بالقسط لا نكلف نفسا الا وسعها واذا قلتم فاعدلوا ولو كان ذا قربي وبعهد الله اوفوا ذلكم وصاكم به لعلكم تذكرون', 'ول تقرب مل يتيم ال تي هي احسن حت يبلغ اشد اوف كيل ميز قسط ل نكلف نفس ال سع اذ قلتم اعدل ولو كن ذ قرب بعهد له اوف ذل ص به لعل تذكر', 'quran', NULL, NULL, 'https://quran.com/6/152');
INSERT INTO units_tri_src (id, ar_tri) VALUES (941, 'ول تقر قرب ربو مل الي ليت يتي تيم ال بلت لتي هي احس حسن حتي يبل بلغ اشد شده ووف وفو الك لكي كيل ولم لمي ميز يزن بلق لقس قسط ل نكل كلف نفس ال وسع سعه وذ قلت لتم فعد عدل دلو ولو كن ذ قرب ربي وبع بعه عهد الل لله اوف وفو ذلك لكم وصك صكم به لعل علك لكم تذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (942, 'quran:6:153', 'quran', 'quran', '6:153', 153, 941, 'Al-An''am', 'الأنعام', 'وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ', NULL, NULL, 'وان هذا صرطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون', 'ون هذ صرط مستقيم اتبعو ول تتبع سبل تفرق بكم عن سبيل ذل ص به لعل تتق', 'quran', NULL, NULL, 'https://quran.com/6/153');
INSERT INTO units_tri_src (id, ar_tri) VALUES (942, 'ون هذ صرط رطي مست ستق تقي قيم فتب تبع بعو عوه ول تتب تبع بعو الس لسب سبل فتف تفر فرق بكم عن سبي بيل يله ذلك لكم وصك صكم به لعل علك لكم تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (943, 'quran:6:154', 'quran', 'quran', '6:154', 154, 942, 'Al-An''am', 'الأنعام', 'ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ', NULL, NULL, 'ثم اتينا موسي الكتب تماما علي الذي احسن وتفصيلا لكل شيء وهدي ورحمه لعلهم بلقاء ربهم يومنون', 'ثم اتي موس كتب تمم عل ذي احسن تفصيل لكل شيء هد رحم لعل بلقء رب يومن', 'quran', NULL, NULL, 'https://quran.com/6/154');
INSERT INTO units_tri_src (id, ar_tri) VALUES (943, 'ثم اتي تين موس وسي الك لكت كتب تمم علي الذ لذي احس حسن وتف تفص فصي صيل لكل شيء وهد هدي ورح رحم حمه لعل عله لهم بلق لقء ربه بهم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (944, 'quran:6:155', 'quran', 'quran', '6:155', 155, 943, 'Al-An''am', 'الأنعام', 'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ', NULL, NULL, 'وهذا كتب انزلنه مبارك فاتبعوه واتقوا لعلكم ترحمون', 'هذ كتب انزلن مبرك اتبعو اتق لعل ترحم', 'quran', NULL, NULL, 'https://quran.com/6/155');
INSERT INTO units_tri_src (id, ar_tri) VALUES (944, 'وهذ كتب انز نزل زلن لنه مبر برك فتب تبع بعو عوه وتق تقو لعل علك لكم ترح رحم حمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (945, 'quran:6:156', 'quran', 'quran', '6:156', 156, 944, 'Al-An''am', 'الأنعام', 'أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ', NULL, NULL, 'ان تقولوا انما انزل الكتب علي طايفتين من قبلنا وان كنا عن دراستهم لغفلين', 'ان تقول انم انزل كتب عل طيفت من قبل ون كن عن درست لغفل', 'quran', NULL, NULL, 'https://quran.com/6/156');
INSERT INTO units_tri_src (id, ar_tri) VALUES (945, 'ان تقو قول ولو انم انز نزل الك لكت كتب علي طيف يفت فتي تين من قبل بلن ون كن عن درس رست سته تهم لغف غفل فلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (946, 'quran:6:157', 'quran', 'quran', '6:157', 157, 945, 'Al-An''am', 'الأنعام', 'أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ', NULL, NULL, 'او تقولوا لو انا انزل علينا الكتب لكنا اهدي منهم فقد جاءكم بينه من ربكم وهدي ورحمه فمن اظلم ممن كذب بايت الله وصدف عنها سنجزي الذين يصدفون عن ايتنا سوء العذاب بما كانوا يصدفون', 'او تقول لو ان انزل علي كتب لك اهد من فقد جء بين من رب هد رحم فمن اظلم ممن كذب بيت له صدف عن سنجز ذين يصدف عن ايت سوء عذب بم كن يصدف', 'quran', NULL, NULL, 'https://quran.com/6/157');
INSERT INTO units_tri_src (id, ar_tri) VALUES (946, 'او تقو قول ولو لو ان انز نزل علي لين الك لكت كتب لكن اهد هدي منه نهم فقد جءك ءكم بين ينه من ربك بكم وهد هدي ورح رحم حمه فمن اظل ظلم ممن كذب بيت الل لله وصد صدف عنه سنج نجز جزي الذ لذي ذين يصد صدف دفو فون عن ايت يتن سوء الع لعذ عذب بم كنو يصد صدف دفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (947, 'quran:6:158', 'quran', 'quran', '6:158', 158, 946, 'Al-An''am', 'الأنعام', 'هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ', NULL, NULL, 'هل ينظرون الا ان تاتيهم المليكه او ياتي ربك او ياتي بعض ايت ربك يوم ياتي بعض ايت ربك لا ينفع نفسا ايمنها لم تكن امنت من قبل او كسبت في ايمنها خيرا قل انتظروا انا منتظرون', 'هل ينظر ال ان تتي مليك او يت ربك او يت بعض ايت ربك يوم يت بعض ايت ربك ل ينفع نفس ايمن لم تكن امنت من قبل او كسبت في ايمن خير قل انتظر ان منتظر', 'quran', NULL, NULL, 'https://quran.com/6/158');
INSERT INTO units_tri_src (id, ar_tri) VALUES (947, 'هل ينظ نظر ظرو رون ال ان تتي تيه يهم الم لمل ملي ليك يكه او يتي ربك او يتي بعض ايت ربك يوم يتي بعض ايت ربك ل ينف نفع نفس ايم يمن منه لم تكن امن منت من قبل او كسب سبت في ايم يمن منه خير قل انت نتظ تظر ظرو ان منت نتظ تظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (948, 'quran:6:159', 'quran', 'quran', '6:159', 159, 947, 'Al-An''am', 'الأنعام', 'إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ', NULL, NULL, 'ان الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء انما امرهم الي الله ثم ينبيهم بما كانوا يفعلون', 'ان ذين رق دين كن شيع لست من في شيء انم امر ال له ثم ينبي بم كن يفعل', 'quran', NULL, NULL, 'https://quran.com/6/159');
INSERT INTO units_tri_src (id, ar_tri) VALUES (948, 'ان الذ لذي ذين فرق رقو دين ينه نهم وكن كنو شيع لست منه نهم في شيء انم امر مره رهم الي الل لله ثم ينب نبي بيه يهم بم كنو يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (949, 'quran:6:160', 'quran', 'quran', '6:160', 160, 948, 'Al-An''am', 'الأنعام', 'مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'من جاء بالحسنه فله عشر امثالها ومن جاء بالسييه فلا يجزي الا مثلها وهم لا يظلمون', 'من جء حسن فل عشر امثل ومن جء سي فل يجز ال مثل وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/6/160');
INSERT INTO units_tri_src (id, ar_tri) VALUES (949, 'من جء بلح لحس حسن سنه فله عشر امث مثل ثله ومن جء بلس لسي سيي ييه فل يجز جزي ال مثل ثله وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (950, 'quran:6:161', 'quran', 'quran', '6:161', 161, 949, 'Al-An''am', 'الأنعام', 'قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'قل انني هداني ربي الي صرط مستقيم دينا قيما مله ابرهيم حنيفا وما كان من المشركين', 'قل انن هدن رب ال صرط مستقيم دي قيم مل ابرهيم حنيف وم كن من مشرك', 'quran', NULL, NULL, 'https://quran.com/6/161');
INSERT INTO units_tri_src (id, ar_tri) VALUES (950, 'قل انن نني هدن دني ربي الي صرط مست ستق تقي قيم دين قيم مله ابر بره رهي هيم حني نيف وم كن من الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (951, 'quran:6:162', 'quran', 'quran', '6:162', 162, 950, 'Al-An''am', 'الأنعام', 'قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قل ان صلاتي ونسكي ومحياي ومماتي لله رب العلمين', 'قل ان صلت نسك محي ممت لل رب علم', 'quran', NULL, NULL, 'https://quran.com/6/162');
INSERT INTO units_tri_src (id, ar_tri) VALUES (951, 'قل ان صلت لتي ونس نسك سكي ومح محي حيي ومم ممت متي لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (952, 'quran:6:163', 'quran', 'quran', '6:163', 163, 951, 'Al-An''am', 'الأنعام', 'لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ', NULL, NULL, 'لا شريك له وبذلك امرت وانا اول المسلمين', 'ل شريك له بذلك امرت ان اول مسلم', 'quran', NULL, NULL, 'https://quran.com/6/163');
INSERT INTO units_tri_src (id, ar_tri) VALUES (952, 'ل شري ريك له وبذ بذل ذلك امر مرت ون اول الم لمس مسل سلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (953, 'quran:6:164', 'quran', 'quran', '6:164', 164, 952, 'Al-An''am', 'الأنعام', 'قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', NULL, NULL, 'قل اغير الله ابغي ربا وهو رب كل شيء ولا تكسب كل نفس الا عليها ولا تزر وازره وزر اخري ثم الي ربكم مرجعكم فينبيكم بما كنتم فيه تختلفون', 'قل اغير له ابغ رب وهو رب كل شيء ول تكسب كل نفس ال علي ول تزر ازر وزر اخر ثم ال رب مرجع ينبي بم كنتم في تختلف', 'quran', NULL, NULL, 'https://quran.com/6/164');
INSERT INTO units_tri_src (id, ar_tri) VALUES (953, 'قل اغي غير الل لله ابغ بغي رب وهو رب كل شيء ول تكس كسب كل نفس ال علي ليه ول تزر وزر زره وزر اخر خري ثم الي ربك بكم مرج رجع جعك عكم فين ينب نبي بيك يكم بم كنت نتم فيه تخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (954, 'quran:6:165', 'quran', 'quran', '6:165', 165, 953, 'Al-An''am', 'الأنعام', 'وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ', NULL, NULL, 'وهو الذي جعلكم خليف الارض ورفع بعضكم فوق بعض درجت ليبلوكم في ما اتاكم ان ربك سريع العقاب وانه لغفور رحيم', 'وهو ذي جعل خليف ارض رفع بعض فوق بعض درجت ليبلو في م ات ان ربك سريع عقب ان لغفور رحيم', 'quran', NULL, NULL, 'https://quran.com/6/165');
INSERT INTO units_tri_src (id, ar_tri) VALUES (954, 'وهو الذ لذي جعل علك لكم خلي ليف الر لرض ورف رفع بعض عضك ضكم فوق بعض درج رجت ليب يبل بلو لوك وكم في م اتك تكم ان ربك سري ريع الع لعق عقب ونه لغف غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (955, 'quran:15:1', 'quran', 'quran', '15:1', 1, 954, 'Al-Hijr', 'الحجر', 'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانٖ مُّبِينٖ', NULL, NULL, 'الر تلك ايت الكتب وقران مبين', 'الر تلك ايت كتب قر مب', 'quran', NULL, NULL, 'https://quran.com/15/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (955, 'الر تلك ايت الك لكت كتب وقر قرن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (956, 'quran:15:2', 'quran', 'quran', '15:2', 2, 955, 'Al-Hijr', 'الحجر', 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ', NULL, NULL, 'ربما يود الذين كفروا لو كانوا مسلمين', 'ربم يود ذين كفر لو كن مسلم', 'quran', NULL, NULL, 'https://quran.com/15/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (956, 'ربم يود الذ لذي ذين كفر فرو لو كنو مسل سلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (957, 'quran:15:3', 'quran', 'quran', '15:3', 3, 956, 'Al-Hijr', 'الحجر', 'ذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ', NULL, NULL, 'ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون', 'ذر يكل يتمتع يله امل سوف يعلم', 'quran', NULL, NULL, 'https://quran.com/15/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (957, 'ذره رهم يكل كلو ويت يتم تمت متع تعو ويل يله لهه ههم الم لمل فسو سوف يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (958, 'quran:15:4', 'quran', 'quran', '15:4', 4, 957, 'Al-Hijr', 'الحجر', 'وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ', NULL, NULL, 'وما اهلكنا من قريه الا ولها كتاب معلوم', 'وم اهلك من قر ال له كتب معلوم', 'quran', NULL, NULL, 'https://quran.com/15/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (958, 'وم اهل هلك لكن من قري ريه ال وله كتب معل علو لوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (959, 'quran:15:5', 'quran', 'quran', '15:5', 5, 958, 'Al-Hijr', 'الحجر', 'مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ', NULL, NULL, 'ما تسبق من امه اجلها وما يستخرون', 'م تسبق من ام اجل وم يستخر', 'quran', NULL, NULL, 'https://quran.com/15/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (959, 'م تسب سبق من امه اجل جله وم يست ستخ تخر خرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (960, 'quran:15:6', 'quran', 'quran', '15:6', 6, 959, 'Al-Hijr', 'الحجر', 'وَقَالُواْ يَٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونٞ', NULL, NULL, 'وقالوا يا ايها الذي نزل عليه الذكر انك لمجنون', 'قل ي اي ذي نزل عل ذكر انك لمجن', 'quran', NULL, NULL, 'https://quran.com/15/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (960, 'وقل قلو ي ايه الذ لذي نزل علي ليه الذ لذك ذكر انك لمج مجن جنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (961, 'quran:15:7', 'quran', 'quran', '15:7', 7, 960, 'Al-Hijr', 'الحجر', 'لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', NULL, NULL, 'لوما تاتينا بالمليكه ان كنت من الصدقين', 'لوم تتي مليك ان كنت من صدق', 'quran', NULL, NULL, 'https://quran.com/15/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (961, 'لوم تتي تين بلم لمل ملي ليك يكه ان كنت من الص لصد صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (962, 'quran:15:8', 'quran', 'quran', '15:8', 8, 961, 'Al-Hijr', 'الحجر', 'مَا نُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ', NULL, NULL, 'ما ننزل المليكه الا بالحق وما كانوا اذا منظرين', 'م ننزل مليك ال حق وم كن اذ منظر', 'quran', NULL, NULL, 'https://quran.com/15/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (962, 'م ننز نزل الم لمل ملي ليك يكه ال بلح لحق وم كنو اذ منظ نظر ظري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (963, 'quran:15:9', 'quran', 'quran', '15:9', 9, 962, 'Al-Hijr', 'الحجر', 'إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', NULL, NULL, 'انا نحن نزلنا الذكر وانا له لحفظون', 'ان نحن نزل ذكر ان له لحفظ', 'quran', NULL, NULL, 'https://quran.com/15/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (963, 'ان نحن نزل زلن الذ لذك ذكر ون له لحف حفظ فظو ظون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (964, 'quran:15:10', 'quran', 'quran', '15:10', 10, 963, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ', NULL, NULL, 'ولقد ارسلنا من قبلك في شيع الاولين', 'لقد ارسل من قبلك في شيع اول', 'quran', NULL, NULL, 'https://quran.com/15/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (964, 'ولق لقد ارس رسل سلن من قبل بلك في شيع الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (965, 'quran:15:11', 'quran', 'quran', '15:11', 11, 964, 'Al-Hijr', 'الحجر', 'وَمَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'وما ياتيهم من رسول الا كانوا به يستهزءون', 'وم يتي من رسول ال كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/15/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (965, 'وم يتي تيه يهم من رسو سول ال كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (966, 'quran:15:12', 'quran', 'quran', '15:12', 12, 965, 'Al-Hijr', 'الحجر', 'كَذَٰلِكَ نَسۡلُكُهُۥ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ', NULL, NULL, 'كذلك نسلكه في قلوب المجرمين', 'كذلك نسلك في قلوب مجرم', 'quran', NULL, NULL, 'https://quran.com/15/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (966, 'كذل ذلك نسل سلك لكه في قلو لوب الم لمج مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (967, 'quran:15:13', 'quran', 'quran', '15:13', 13, 966, 'Al-Hijr', 'الحجر', 'لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ', NULL, NULL, 'لا يومنون به وقد خلت سنه الاولين', 'ل يومن به وقد خلت سن اول', 'quran', NULL, NULL, 'https://quran.com/15/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (967, 'ل يوم ومن منو نون به وقد خلت سنه الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (968, 'quran:15:14', 'quran', 'quran', '15:14', 14, 967, 'Al-Hijr', 'الحجر', 'وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابٗا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ', NULL, NULL, 'ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون', 'ولو تح علي بب من سمء ظل في يعرج', 'quran', NULL, NULL, 'https://quran.com/15/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (968, 'ولو فتح تحن علي ليه يهم بب من الس لسم سمء فظل ظلو فيه يعر عرج رجو جون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (969, 'quran:15:15', 'quran', 'quran', '15:15', 15, 968, 'Al-Hijr', 'الحجر', 'لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمٞ مَّسۡحُورُونَ', NULL, NULL, 'لقالوا انما سكرت ابصرنا بل نحن قوم مسحورون', 'لقل انم سكرت ابصر بل نحن قوم مسحور', 'quran', NULL, NULL, 'https://quran.com/15/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (969, 'لقل قلو انم سكر كرت ابص بصر صرن بل نحن قوم مسح سحو حور ورو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (970, 'quran:15:16', 'quran', 'quran', '15:16', 16, 969, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', NULL, NULL, 'ولقد جعلنا في السماء بروجا وزينها للنظرين', 'لقد جعل في سمء بروج زين نظر', 'quran', NULL, NULL, 'https://quran.com/15/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (970, 'ولق لقد جعل علن في الس لسم سمء برو روج وزي زين ينه للن لنظ نظر ظري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (971, 'quran:15:17', 'quran', 'quran', '15:17', 17, 970, 'Al-Hijr', 'الحجر', 'وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنٖ رَّجِيمٍ', NULL, NULL, 'وحفظنها من كل شيطن رجيم', 'حفظن من كل شيطن رجيم', 'quran', NULL, NULL, 'https://quran.com/15/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (971, 'وحف حفظ فظن ظنه من كل شيط يطن رجي جيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (972, 'quran:15:18', 'quran', 'quran', '15:18', 18, 971, 'Al-Hijr', 'الحجر', 'إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابٞ مُّبِينٞ', NULL, NULL, 'الا من استرق السمع فاتبعه شهاب مبين', 'ال من استرق سمع اتبع شهب مب', 'quran', NULL, NULL, 'https://quran.com/15/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (972, 'ال من است ستر ترق الس لسم سمع فتب تبع بعه شهب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (973, 'quran:15:19', 'quran', 'quran', '15:19', 19, 972, 'Al-Hijr', 'الحجر', 'وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ', NULL, NULL, 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل شيء موزون', 'ارض مددن قي يه روس انبت يه من كل شيء موز', 'quran', NULL, NULL, 'https://quran.com/15/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (973, 'ولر لرض مدد ددن دنه ولق لقي قين فيه روس وسي ونب نبت بتن فيه من كل شيء موز وزو زون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (974, 'quran:15:20', 'quran', 'quran', '15:20', 20, 973, 'Al-Hijr', 'الحجر', 'وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ', NULL, NULL, 'وجعلنا لكم فيها معيش ومن لستم له برزقين', 'جعل لكم يه معيش ومن لستم له برزق', 'quran', NULL, NULL, 'https://quran.com/15/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (974, 'وجع جعل علن لكم فيه معي عيش ومن لست ستم له برز رزق زقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (975, 'quran:15:21', 'quran', 'quran', '15:21', 21, 974, 'Al-Hijr', 'الحجر', 'وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ', NULL, NULL, 'وان من شيء الا عندنا خزاينه وما ننزله الا بقدر معلوم', 'ون من شيء ال عند خزين وم ننزل ال بقدر معلوم', 'quran', NULL, NULL, 'https://quran.com/15/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (975, 'ون من شيء ال عند ندن خزي زين ينه وم ننز نزل زله ال بقد قدر معل علو لوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (976, 'quran:15:22', 'quran', 'quran', '15:22', 22, 975, 'Al-Hijr', 'الحجر', 'وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ', NULL, NULL, 'وارسلنا الريح لوقح فانزلنا من السماء ماء فاسقينكموه وما انتم له بخزنين', 'ارسل ريح لوقح انزل من سمء مء اسقينكمو وم انتم له بخزن', 'quran', NULL, NULL, 'https://quran.com/15/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (976, 'ورس رسل سلن الر لري ريح لوق وقح فنز نزل زلن من الس لسم سمء مء فسق سقي قين ينك نكم كمو موه وم انت نتم له بخز خزن زني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (977, 'quran:15:23', 'quran', 'quran', '15:23', 23, 976, 'Al-Hijr', 'الحجر', 'وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ', NULL, NULL, 'وانا لنحن نحي ونميت ونحن الورثون', 'ان لنحن نح نميت نحن ورث', 'quran', NULL, NULL, 'https://quran.com/15/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (977, 'ون لنح نحن نحي ونم نمي ميت ونح نحن الو لور ورث رثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (978, 'quran:15:24', 'quran', 'quran', '15:24', 24, 977, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ', NULL, NULL, 'ولقد علمنا المستقدمين منكم ولقد علمنا المستخرين', 'لقد علم مستقدم من لقد علم مستخر', 'quran', NULL, NULL, 'https://quran.com/15/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (978, 'ولق لقد علم لمن الم لمس مست ستق تقد قدم دمي مين منك نكم ولق لقد علم لمن الم لمس مست ستخ تخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (979, 'quran:15:25', 'quran', 'quran', '15:25', 25, 978, 'Al-Hijr', 'الحجر', 'وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ', NULL, NULL, 'وان ربك هو يحشرهم انه حكيم عليم', 'ون ربك هو يحشر ان حكيم عليم', 'quran', NULL, NULL, 'https://quran.com/15/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (979, 'ون ربك هو يحش حشر شره رهم انه حكي كيم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (980, 'quran:15:26', 'quran', 'quran', '15:26', 26, 979, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', NULL, NULL, 'ولقد خلقنا الانسن من صلصل من حما مسنون', 'لقد خلق انسن من صلصل من حم مسن', 'quran', NULL, NULL, 'https://quran.com/15/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (980, 'ولق لقد خلق لقن الن لنس نسن من صلص لصل من حم مسن سنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (981, 'quran:15:27', 'quran', 'quran', '15:27', 27, 980, 'Al-Hijr', 'الحجر', 'وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ', NULL, NULL, 'والجان خلقنه من قبل من نار السموم', 'جن خلقن من قبل من نر سموم', 'quran', NULL, NULL, 'https://quran.com/15/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (981, 'ولج لجن خلق لقن قنه من قبل من نر الس لسم سمو موم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (982, 'quran:15:28', 'quran', 'quran', '15:28', 28, 981, 'Al-Hijr', 'الحجر', 'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', NULL, NULL, 'واذ قال ربك للمليكه اني خلق بشرا من صلصل من حما مسنون', 'وذ قل ربك مليك ان خلق بشر من صلصل من حم مسن', 'quran', NULL, NULL, 'https://quran.com/15/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (982, 'وذ قل ربك للم لمل ملي ليك يكه اني خلق بشر من صلص لصل من حم مسن سنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (983, 'quran:15:29', 'quran', 'quran', '15:29', 29, 982, 'Al-Hijr', 'الحجر', 'فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ', NULL, NULL, 'فاذا سويته ونفخت فيه من روحي فقعوا له سجدين', 'اذ سويت نفخت في من روح قع له سجد', 'quran', NULL, NULL, 'https://quran.com/15/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (983, 'فذ سوي ويت يته ونف نفخ فخت فيه من روح وحي فقع قعو له سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (984, 'quran:15:30', 'quran', 'quran', '15:30', 30, 983, 'Al-Hijr', 'الحجر', 'فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ', NULL, NULL, 'فسجد المليكه كلهم اجمعون', 'سجد مليك كل اجمع', 'quran', NULL, NULL, 'https://quran.com/15/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (984, 'فسج سجد الم لمل ملي ليك يكه كله لهم اجم جمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (985, 'quran:15:31', 'quran', 'quran', '15:31', 31, 984, 'Al-Hijr', 'الحجر', 'إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', NULL, NULL, 'الا ابليس ابي ان يكون مع السجدين', 'ال ابليس اب ان يك مع سجد', 'quran', NULL, NULL, 'https://quran.com/15/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (985, 'ال ابل بلي ليس ابي ان يكو كون مع الس لسج سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (986, 'quran:15:32', 'quran', 'quran', '15:32', 32, 985, 'Al-Hijr', 'الحجر', 'قَالَ يَٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', NULL, NULL, 'قال يا ابليس ما لك الا تكون مع السجدين', 'قل ي ابليس م لك ال تك مع سجد', 'quran', NULL, NULL, 'https://quran.com/15/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (986, 'قل ي ابل بلي ليس م لك ال تكو كون مع الس لسج سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (987, 'quran:15:33', 'quran', 'quran', '15:33', 33, 986, 'Al-Hijr', 'الحجر', 'قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', NULL, NULL, 'قال لم اكن لاسجد لبشر خلقته من صلصل من حما مسنون', 'قل لم اكن لسجد لبشر خلقت من صلصل من حم مسن', 'quran', NULL, NULL, 'https://quran.com/15/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (987, 'قل لم اكن لسج سجد لبش بشر خلق لقت قته من صلص لصل من حم مسن سنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (988, 'quran:15:34', 'quran', 'quran', '15:34', 34, 987, 'Al-Hijr', 'الحجر', 'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ', NULL, NULL, 'قال فاخرج منها فانك رجيم', 'قل اخرج من انك رجيم', 'quran', NULL, NULL, 'https://quran.com/15/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (988, 'قل فخر خرج منه فنك رجي جيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (989, 'quran:15:35', 'quran', 'quran', '15:35', 35, 988, 'Al-Hijr', 'الحجر', 'وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ', NULL, NULL, 'وان عليك اللعنه الي يوم الدين', 'ون عليك لعن ال يوم دين', 'quran', NULL, NULL, 'https://quran.com/15/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (989, 'ون علي ليك الل للع لعن عنه الي يوم الد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (990, 'quran:15:36', 'quran', 'quran', '15:36', 36, 989, 'Al-Hijr', 'الحجر', 'قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ', NULL, NULL, 'قال رب فانظرني الي يوم يبعثون', 'قل رب انظرن ال يوم يبعث', 'quran', NULL, NULL, 'https://quran.com/15/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (990, 'قل رب فنظ نظر ظرن رني الي يوم يبع بعث عثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (991, 'quran:15:37', 'quran', 'quran', '15:37', 37, 990, 'Al-Hijr', 'الحجر', 'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ', NULL, NULL, 'قال فانك من المنظرين', 'قل انك من منظر', 'quran', NULL, NULL, 'https://quran.com/15/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (991, 'قل فنك من الم لمن منظ نظر ظري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (992, 'quran:15:38', 'quran', 'quran', '15:38', 38, 991, 'Al-Hijr', 'الحجر', 'إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ', NULL, NULL, 'الي يوم الوقت المعلوم', 'ال يوم وقت معلوم', 'quran', NULL, NULL, 'https://quran.com/15/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (992, 'الي يوم الو لوق وقت الم لمع معل علو لوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (993, 'quran:15:39', 'quran', 'quran', '15:39', 39, 992, 'Al-Hijr', 'الحجر', 'قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ', NULL, NULL, 'قال رب بما اغويتني لازينن لهم في الارض ولاغوينهم اجمعين', 'قل رب بم اغويتن لزينن لهم في ارض لغوين اجمع', 'quran', NULL, NULL, 'https://quran.com/15/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (993, 'قل رب بم اغو غوي ويت يتن تني لزي زين ينن لهم في الر لرض ولغ لغو غوي وين ينه نهم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (994, 'quran:15:40', 'quran', 'quran', '15:40', 40, 993, 'Al-Hijr', 'الحجر', 'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ', NULL, NULL, 'الا عبادك منهم المخلصين', 'ال عبدك من مخلص', 'quran', NULL, NULL, 'https://quran.com/15/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (994, 'ال عبد بدك منه نهم الم لمخ مخل خلص لصي صين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (995, 'quran:15:41', 'quran', 'quran', '15:41', 41, 994, 'Al-Hijr', 'الحجر', 'قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ', NULL, NULL, 'قال هذا صرط علي مستقيم', 'قل هذ صرط عل مستقيم', 'quran', NULL, NULL, 'https://quran.com/15/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (995, 'قل هذ صرط علي مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (996, 'quran:15:42', 'quran', 'quran', '15:42', 42, 995, 'Al-Hijr', 'الحجر', 'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ', NULL, NULL, 'ان عبادي ليس لك عليهم سلطن الا من اتبعك من الغاوين', 'ان عبد ليس لك علي سلطن ال من اتبعك من غو', 'quran', NULL, NULL, 'https://quran.com/15/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (996, 'ان عبد بدي ليس لك علي ليه يهم سلط لطن ال من اتب تبع بعك من الغ لغو غوي وين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (997, 'quran:15:43', 'quran', 'quran', '15:43', 43, 996, 'Al-Hijr', 'الحجر', 'وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ', NULL, NULL, 'وان جهنم لموعدهم اجمعين', 'ون جهنم لموعد اجمع', 'quran', NULL, NULL, 'https://quran.com/15/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (997, 'ون جهن هنم لمو موع وعد عده دهم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (998, 'quran:15:44', 'quran', 'quran', '15:44', 44, 997, 'Al-Hijr', 'الحجر', 'لَهَا سَبۡعَةُ أَبۡوَٰبٖ لِّكُلِّ بَابٖ مِّنۡهُمۡ جُزۡءٞ مَّقۡسُومٌ', NULL, NULL, 'لها سبعه ابوب لكل باب منهم جزء مقسوم', 'له سبع ابوب لكل بب من جزء مقسوم', 'quran', NULL, NULL, 'https://quran.com/15/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (998, 'له سبع بعه ابو بوب لكل بب منه نهم جزء مقس قسو سوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (999, 'quran:15:45', 'quran', 'quran', '15:45', 45, 998, 'Al-Hijr', 'الحجر', 'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ', NULL, NULL, 'ان المتقين في جنت وعيون', 'ان متق في جنت عي', 'quran', NULL, NULL, 'https://quran.com/15/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (999, 'ان الم لمت متق تقي قين في جنت وعي عيو يون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1000, 'quran:15:46', 'quran', 'quran', '15:46', 46, 999, 'Al-Hijr', 'الحجر', 'ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', NULL, NULL, 'ادخلوها بسلم امنين', 'ادخلو بسلم امن', 'quran', NULL, NULL, 'https://quran.com/15/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1000, 'ادخ دخل خلو لوه بسل سلم امن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1001, 'quran:15:47', 'quran', 'quran', '15:47', 47, 1000, 'Al-Hijr', 'الحجر', 'وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ', NULL, NULL, 'ونزعنا ما في صدورهم من غل اخونا علي سرر متقبلين', 'نزع م في صدور من غل اخو عل سرر متقبل', 'quran', NULL, NULL, 'https://quran.com/15/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1001, 'ونز نزع زعن م في صدو دور وره رهم من غل اخو خون علي سرر متق تقب قبل بلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1002, 'quran:15:48', 'quran', 'quran', '15:48', 48, 1001, 'Al-Hijr', 'الحجر', 'لَا يَمَسُّهُمۡ فِيهَا نَصَبٞ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ', NULL, NULL, 'لا يمسهم فيها نصب وما هم منها بمخرجين', 'ل يمس يه نصب وم هم من بمخرج', 'quran', NULL, NULL, 'https://quran.com/15/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1002, 'ل يمس مسه سهم فيه نصب وم هم منه بمخ مخر خرج رجي جين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1003, 'quran:15:49', 'quran', 'quran', '15:49', 49, 1002, 'Al-Hijr', 'الحجر', 'نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ', NULL, NULL, 'نبي عبادي اني انا الغفور الرحيم', 'نب عبد ان ان غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/15/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1003, 'نبي عبد بدي اني ان الغ لغف غفو فور الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1004, 'quran:15:50', 'quran', 'quran', '15:50', 50, 1003, 'Al-Hijr', 'الحجر', 'وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ', NULL, NULL, 'وان عذابي هو العذاب الاليم', 'ون عذب هو عذب اليم', 'quran', NULL, NULL, 'https://quran.com/15/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1004, 'ون عذب ذبي هو الع لعذ عذب الل للي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1005, 'quran:15:51', 'quran', 'quran', '15:51', 51, 1004, 'Al-Hijr', 'الحجر', 'وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ', NULL, NULL, 'ونبيهم عن ضيف ابرهيم', 'نبي عن ضيف ابرهيم', 'quran', NULL, NULL, 'https://quran.com/15/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1005, 'ونب نبي بيه يهم عن ضيف ابر بره رهي هيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1006, 'quran:15:52', 'quran', 'quran', '15:52', 52, 1005, 'Al-Hijr', 'الحجر', 'إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ', NULL, NULL, 'اذ دخلوا عليه فقالوا سلما قال انا منكم وجلون', 'اذ دخل عل قل سلم قل ان من جل', 'quran', NULL, NULL, 'https://quran.com/15/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1006, 'اذ دخل خلو علي ليه فقل قلو سلم قل ان منك نكم وجل جلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1007, 'quran:15:53', 'quran', 'quran', '15:53', 53, 1006, 'Al-Hijr', 'الحجر', 'قَالُواْ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٖ', NULL, NULL, 'قالوا لا توجل انا نبشرك بغلم عليم', 'قل ل توجل ان نبشرك بغلم عليم', 'quran', NULL, NULL, 'https://quran.com/15/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1007, 'قلو ل توج وجل ان نبش بشر شرك بغل غلم علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1008, 'quran:15:54', 'quran', 'quran', '15:54', 54, 1007, 'Al-Hijr', 'الحجر', 'قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ', NULL, NULL, 'قال ابشرتموني علي ان مسني الكبر فبم تبشرون', 'قل ابشرتمون عل ان مسن كبر فبم تبشر', 'quran', NULL, NULL, 'https://quran.com/15/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1008, 'قل ابش بشر شرت رتم تمو مون وني علي ان مسن سني الك لكب كبر فبم تبش بشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1009, 'quran:15:55', 'quran', 'quran', '15:55', 55, 1008, 'Al-Hijr', 'الحجر', 'قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ', NULL, NULL, 'قالوا بشرنك بالحق فلا تكن من القنطين', 'قل بشرنك حق فل تكن من قنط', 'quran', NULL, NULL, 'https://quran.com/15/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1009, 'قلو بشر شرن رنك بلح لحق فل تكن من الق لقن قنط نطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1010, 'quran:15:56', 'quran', 'quran', '15:56', 56, 1009, 'Al-Hijr', 'الحجر', 'قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', NULL, NULL, 'قال ومن يقنط من رحمه ربه الا الضالون', 'قل ومن يقنط من رحم رب ال ضل', 'quran', NULL, NULL, 'https://quran.com/15/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1010, 'قل ومن يقن قنط من رحم حمه ربه ال الض لضل ضلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1011, 'quran:15:57', 'quran', 'quran', '15:57', 57, 1010, 'Al-Hijr', 'الحجر', 'قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ', NULL, NULL, 'قال فما خطبكم ايها المرسلون', 'قل فم خطب اي مرسل', 'quran', NULL, NULL, 'https://quran.com/15/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1011, 'قل فم خطب طبك بكم ايه الم لمر مرس رسل سلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1012, 'quran:15:58', 'quran', 'quran', '15:58', 58, 1011, 'Al-Hijr', 'الحجر', 'قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ', NULL, NULL, 'قالوا انا ارسلنا الي قوم مجرمين', 'قل ان ارسل ال قوم مجرم', 'quran', NULL, NULL, 'https://quran.com/15/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1012, 'قلو ان ارس رسل سلن الي قوم مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1013, 'quran:15:59', 'quran', 'quran', '15:59', 59, 1012, 'Al-Hijr', 'الحجر', 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ', NULL, NULL, 'الا ال لوط انا لمنجوهم اجمعين', 'ال ال لوط ان لمنجو اجمع', 'quran', NULL, NULL, 'https://quran.com/15/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1013, 'ال ال لوط ان لمن منج نجو جوه وهم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1014, 'quran:15:60', 'quran', 'quran', '15:60', 60, 1013, 'Al-Hijr', 'الحجر', 'إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ', NULL, NULL, 'الا امراته قدرنا انها لمن الغبرين', 'ال امرت قدر ان لمن غبر', 'quran', NULL, NULL, 'https://quran.com/15/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1014, 'ال امر مرت رته قدر درن انه لمن الغ لغب غبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1015, 'quran:15:61', 'quran', 'quran', '15:61', 61, 1014, 'Al-Hijr', 'الحجر', 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ', NULL, NULL, 'فلما جاء ال لوط المرسلون', 'لم جء ال لوط مرسل', 'quran', NULL, NULL, 'https://quran.com/15/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1015, 'فلم جء ال لوط الم لمر مرس رسل سلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1016, 'quran:15:62', 'quran', 'quran', '15:62', 62, 1015, 'Al-Hijr', 'الحجر', 'قَالَ إِنَّكُمۡ قَوۡمٞ مُّنكَرُونَ', NULL, NULL, 'قال انكم قوم منكرون', 'قل ان قوم منكر', 'quran', NULL, NULL, 'https://quran.com/15/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1016, 'قل انك نكم قوم منك نكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1017, 'quran:15:63', 'quran', 'quran', '15:63', 63, 1016, 'Al-Hijr', 'الحجر', 'قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ يَمۡتَرُونَ', NULL, NULL, 'قالوا بل جينك بما كانوا فيه يمترون', 'قل بل جينك بم كن في يمتر', 'quran', NULL, NULL, 'https://quran.com/15/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1017, 'قلو بل جين ينك بم كنو فيه يمت متر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1018, 'quran:15:64', 'quran', 'quran', '15:64', 64, 1017, 'Al-Hijr', 'الحجر', 'وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ', NULL, NULL, 'واتينك بالحق وانا لصدقون', 'اتينك حق ان لصدق', 'quran', NULL, NULL, 'https://quran.com/15/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1018, 'وتي تين ينك بلح لحق ون لصد صدق دقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1019, 'quran:15:65', 'quran', 'quran', '15:65', 65, 1018, 'Al-Hijr', 'الحجر', 'فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ', NULL, NULL, 'فاسر باهلك بقطع من اليل واتبع ادبرهم ولا يلتفت منكم احد وامضوا حيث تومرون', 'اسر بهلك بقطع من يل اتبع ادبر ول يلتفت من احد امض حيث تومر', 'quran', NULL, NULL, 'https://quran.com/15/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1019, 'فسر بهل هلك بقط قطع من الي ليل وتب تبع ادب دبر بره رهم ول يلت لتف تفت منك نكم احد ومض مضو حيث توم ومر مرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1020, 'quran:15:66', 'quran', 'quran', '15:66', 66, 1019, 'Al-Hijr', 'الحجر', 'وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقۡطُوعٞ مُّصۡبِحِينَ', NULL, NULL, 'وقضينا اليه ذلك الامر ان دابر هولاء مقطوع مصبحين', 'قضي يه ذلك امر ان دبر هولء مقطوع مصبح', 'quran', NULL, NULL, 'https://quran.com/15/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1020, 'وقض قضي ضين الي ليه ذلك الم لمر ان دبر هول ولء مقط قطو طوع مصب صبح بحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1021, 'quran:15:67', 'quran', 'quran', '15:67', 67, 1020, 'Al-Hijr', 'الحجر', 'وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ', NULL, NULL, 'وجاء اهل المدينه يستبشرون', 'جء اهل مدين يستبشر', 'quran', NULL, NULL, 'https://quran.com/15/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1021, 'وجء اهل الم لمد مدي دين ينه يست ستب تبش بشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1022, 'quran:15:68', 'quran', 'quran', '15:68', 68, 1021, 'Al-Hijr', 'الحجر', 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ', NULL, NULL, 'قال ان هولاء ضيفي فلا تفضحون', 'قل ان هولء ضيف فل تفضح', 'quran', NULL, NULL, 'https://quran.com/15/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1022, 'قل ان هول ولء ضيف يفي فل تفض فضح ضحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1023, 'quran:15:69', 'quran', 'quran', '15:69', 69, 1022, 'Al-Hijr', 'الحجر', 'وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ', NULL, NULL, 'واتقوا الله ولا تخزون', 'اتق له ول تخز', 'quran', NULL, NULL, 'https://quran.com/15/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1023, 'وتق تقو الل لله ول تخز خزو زون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1024, 'quran:15:70', 'quran', 'quran', '15:70', 70, 1023, 'Al-Hijr', 'الحجر', 'قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قالوا اولم ننهك عن العلمين', 'قل اولم ننهك عن علم', 'quran', NULL, NULL, 'https://quran.com/15/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1024, 'قلو اول ولم ننه نهك عن الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1025, 'quran:15:71', 'quran', 'quran', '15:71', 71, 1024, 'Al-Hijr', 'الحجر', 'قَالَ هَٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ', NULL, NULL, 'قال هولاء بناتي ان كنتم فعلين', 'قل هولء بنت ان كنتم عل', 'quran', NULL, NULL, 'https://quran.com/15/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1025, 'قل هول ولء بنت نتي ان كنت نتم فعل علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1026, 'quran:15:72', 'quran', 'quran', '15:72', 72, 1025, 'Al-Hijr', 'الحجر', 'لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ يَعۡمَهُونَ', NULL, NULL, 'لعمرك انهم لفي سكرتهم يعمهون', 'لعمرك ان لف سكرت يعمه', 'quran', NULL, NULL, 'https://quran.com/15/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1026, 'لعم عمر مرك انه نهم لفي سكر كرت رته تهم يعم عمه مهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1027, 'quran:15:73', 'quran', 'quran', '15:73', 73, 1026, 'Al-Hijr', 'الحجر', 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ', NULL, NULL, 'فاخذتهم الصيحه مشرقين', 'اخذت صيح مشرق', 'quran', NULL, NULL, 'https://quran.com/15/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1027, 'فخذ خذت ذته تهم الص لصي صيح يحه مشر شرق رقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1028, 'quran:15:74', 'quran', 'quran', '15:74', 74, 1027, 'Al-Hijr', 'الحجر', 'فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ', NULL, NULL, 'فجعلنا عليها سافلها وامطرنا عليهم حجاره من سجيل', 'جعل علي سفل امطر علي حجر من سجيل', 'quran', NULL, NULL, 'https://quran.com/15/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1028, 'فجع جعل علن علي ليه سفل فله ومط مطر طرن علي ليه يهم حجر جره من سجي جيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1029, 'quran:15:75', 'quran', 'quran', '15:75', 75, 1028, 'Al-Hijr', 'الحجر', 'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ', NULL, NULL, 'ان في ذلك لايت للمتوسمين', 'ان في ذلك ليت متوسم', 'quran', NULL, NULL, 'https://quran.com/15/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1029, 'ان في ذلك ليت للم لمت متو توس وسم سمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1030, 'quran:15:76', 'quran', 'quran', '15:76', 76, 1029, 'Al-Hijr', 'الحجر', 'وَإِنَّهَا لَبِسَبِيلٖ مُّقِيمٍ', NULL, NULL, 'وانها لبسبيل مقيم', 'ان لبسبيل مقيم', 'quran', NULL, NULL, 'https://quran.com/15/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1030, 'ونه لبس بسب سبي بيل مقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1031, 'quran:15:77', 'quran', 'quran', '15:77', 77, 1030, 'Al-Hijr', 'الحجر', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه للمومنين', 'ان في ذلك ل مومن', 'quran', NULL, NULL, 'https://quran.com/15/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1031, 'ان في ذلك ليه للم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1032, 'quran:15:78', 'quran', 'quran', '15:78', 78, 1031, 'Al-Hijr', 'الحجر', 'وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ', NULL, NULL, 'وان كان اصحب الايكه لظلمين', 'ون كن اصحب ايك لظلم', 'quran', NULL, NULL, 'https://quran.com/15/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1032, 'ون كن اصح صحب الي ليك يكه لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1033, 'quran:15:79', 'quran', 'quran', '15:79', 79, 1032, 'Al-Hijr', 'الحجر', 'فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ', NULL, NULL, 'فانتقمنا منهم وانهما لبامام مبين', 'انتقم من انهم لبمم مب', 'quran', NULL, NULL, 'https://quran.com/15/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1033, 'فنت نتق تقم قمن منه نهم ونه نهم لبم بمم مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1034, 'quran:15:80', 'quran', 'quran', '15:80', 80, 1033, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'ولقد كذب اصحب الحجر المرسلين', 'لقد كذب اصحب حجر مرسل', 'quran', NULL, NULL, 'https://quran.com/15/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1034, 'ولق لقد كذب اصح صحب الح لحج حجر الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1035, 'quran:15:81', 'quran', 'quran', '15:81', 81, 1034, 'Al-Hijr', 'الحجر', 'وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ', NULL, NULL, 'واتينهم ايتنا فكانوا عنها معرضين', 'اتين ايت كن عن معرض', 'quran', NULL, NULL, 'https://quran.com/15/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1035, 'وتي تين ينه نهم ايت يتن فكن كنو عنه معر عرض رضي ضين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1036, 'quran:15:82', 'quran', 'quran', '15:82', 82, 1035, 'Al-Hijr', 'الحجر', 'وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ', NULL, NULL, 'وكانوا ينحتون من الجبال بيوتا امنين', 'كن ينحت من جبل بيوت امن', 'quran', NULL, NULL, 'https://quran.com/15/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1036, 'وكن كنو ينح نحت حتو تون من الج لجب جبل بيو يوت امن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1037, 'quran:15:83', 'quran', 'quran', '15:83', 83, 1036, 'Al-Hijr', 'الحجر', 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ', NULL, NULL, 'فاخذتهم الصيحه مصبحين', 'اخذت صيح مصبح', 'quran', NULL, NULL, 'https://quran.com/15/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1037, 'فخذ خذت ذته تهم الص لصي صيح يحه مصب صبح بحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1038, 'quran:15:84', 'quran', 'quran', '15:84', 84, 1037, 'Al-Hijr', 'الحجر', 'فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ', NULL, NULL, 'فما اغني عنهم ما كانوا يكسبون', 'فم اغن عن م كن يكسب', 'quran', NULL, NULL, 'https://quran.com/15/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1038, 'فم اغن غني عنه نهم م كنو يكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1039, 'quran:15:85', 'quran', 'quran', '15:85', 85, 1038, 'Al-Hijr', 'الحجر', 'وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ', NULL, NULL, 'وما خلقنا السموت والارض وما بينهما الا بالحق وان الساعه لاتيه فاصفح الصفح الجميل', 'وم خلق سموت ارض وم بينهم ال حق ون سع لت اصفح صفح جميل', 'quran', NULL, NULL, 'https://quran.com/15/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1039, 'وم خلق لقن الس لسم سمو موت ولر لرض وم بين ينه نهم ال بلح لحق ون الس لسع سعه لتي تيه فصف صفح الص لصف صفح الج لجم جمي ميل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1040, 'quran:15:86', 'quran', 'quran', '15:86', 86, 1039, 'Al-Hijr', 'الحجر', 'إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ', NULL, NULL, 'ان ربك هو الخلق العليم', 'ان ربك هو خلق عليم', 'quran', NULL, NULL, 'https://quran.com/15/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1040, 'ان ربك هو الخ لخل خلق الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1041, 'quran:15:87', 'quran', 'quran', '15:87', 87, 1040, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ', NULL, NULL, 'ولقد اتينك سبعا من المثاني والقران العظيم', 'لقد اتينك سبع من مثن قر عظيم', 'quran', NULL, NULL, 'https://quran.com/15/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1041, 'ولق لقد اتي تين ينك سبع من الم لمث مثن ثني ولق لقر قرن الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1042, 'quran:15:88', 'quran', 'quran', '15:88', 88, 1041, 'Al-Hijr', 'الحجر', 'لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ', NULL, NULL, 'لا تمدن عينيك الي ما متعنا به ازوجا منهم ولا تحزن عليهم واخفض جناحك للمومنين', 'ل تمدن عينيك ال م متع به ازوج من ول تحزن علي اخفض جنحك مومن', 'quran', NULL, NULL, 'https://quran.com/15/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1042, 'ل تمد مدن عين يني نيك الي م متع تعن به ازو زوج منه نهم ول تحز حزن علي ليه يهم وخف خفض جنح نحك للم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1043, 'quran:15:89', 'quran', 'quran', '15:89', 89, 1042, 'Al-Hijr', 'الحجر', 'وَقُلۡ إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ', NULL, NULL, 'وقل اني انا النذير المبين', 'وقل ان ان نذير مب', 'quran', NULL, NULL, 'https://quran.com/15/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1043, 'وقل اني ان الن لنذ نذي ذير الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1044, 'quran:15:90', 'quran', 'quran', '15:90', 90, 1043, 'Al-Hijr', 'الحجر', 'كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ', NULL, NULL, 'كما انزلنا علي المقتسمين', 'كم انزل عل مقتسم', 'quran', NULL, NULL, 'https://quran.com/15/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1044, 'كم انز نزل زلن علي الم لمق مقت قتس تسم سمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1045, 'quran:15:91', 'quran', 'quran', '15:91', 91, 1044, 'Al-Hijr', 'الحجر', 'ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ', NULL, NULL, 'الذين جعلوا القران عضين', 'ذين جعل قر عض', 'quran', NULL, NULL, 'https://quran.com/15/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1045, 'الذ لذي ذين جعل علو الق لقر قرن عضي ضين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1046, 'quran:15:92', 'quran', 'quran', '15:92', 92, 1045, 'Al-Hijr', 'الحجر', 'فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ', NULL, NULL, 'فوربك لنسلنهم اجمعين', 'وربك لنسلن اجمع', 'quran', NULL, NULL, 'https://quran.com/15/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1046, 'فور ورب ربك لنس نسل سلن لنه نهم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1047, 'quran:15:93', 'quran', 'quran', '15:93', 93, 1046, 'Al-Hijr', 'الحجر', 'عَمَّا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'عما كانوا يعملون', 'عم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/15/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1047, 'عم كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1048, 'quran:15:94', 'quran', 'quran', '15:94', 94, 1047, 'Al-Hijr', 'الحجر', 'فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ', NULL, NULL, 'فاصدع بما تومر واعرض عن المشركين', 'اصدع بم تومر اعرض عن مشرك', 'quran', NULL, NULL, 'https://quran.com/15/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1048, 'فصد صدع بم توم ومر وعر عرض عن الم لمش مشر شرك ركي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1049, 'quran:15:95', 'quran', 'quran', '15:95', 95, 1048, 'Al-Hijr', 'الحجر', 'إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ', NULL, NULL, 'انا كفينك المستهزءين', 'ان كفينك مستهزء', 'quran', NULL, NULL, 'https://quran.com/15/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1049, 'ان كفي فين ينك الم لمس مست سته تهز هزء زءي ءين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1050, 'quran:15:96', 'quran', 'quran', '15:96', 96, 1049, 'Al-Hijr', 'الحجر', 'ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ', NULL, NULL, 'الذين يجعلون مع الله الها اخر فسوف يعلمون', 'ذين يجعل مع له ه اخر سوف يعلم', 'quran', NULL, NULL, 'https://quran.com/15/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1050, 'الذ لذي ذين يجع جعل علو لون مع الل لله اله اخر فسو سوف يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1051, 'quran:15:97', 'quran', 'quran', '15:97', 97, 1050, 'Al-Hijr', 'الحجر', 'وَلَقَدۡ نَعۡلَمُ أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ', NULL, NULL, 'ولقد نعلم انك يضيق صدرك بما يقولون', 'لقد نعلم انك يضيق صدرك بم يقول', 'quran', NULL, NULL, 'https://quran.com/15/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1051, 'ولق لقد نعل علم انك يضي ضيق صدر درك بم يقو قول ولو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1052, 'quran:15:98', 'quran', 'quran', '15:98', 98, 1051, 'Al-Hijr', 'الحجر', 'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', NULL, NULL, 'فسبح بحمد ربك وكن من السجدين', 'سبح بحمد ربك وكن من سجد', 'quran', NULL, NULL, 'https://quran.com/15/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1052, 'فسب سبح بحم حمد ربك وكن من الس لسج سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1053, 'quran:15:99', 'quran', 'quran', '15:99', 99, 1052, 'Al-Hijr', 'الحجر', 'وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ', NULL, NULL, 'واعبد ربك حتي ياتيك اليقين', 'اعبد ربك حت يتيك يق', 'quran', NULL, NULL, 'https://quran.com/15/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1053, 'وعب عبد ربك حتي يتي تيك الي ليق يقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1054, 'quran:17:1', 'quran', 'quran', '17:1', 1, 1053, 'Al-Isra', 'الإسراء', 'سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ', NULL, NULL, 'سبحن الذي اسري بعبده ليلا من المسجد الحرام الي المسجد الاقصا الذي بركنا حوله لنريه من ايتنا انه هو السميع البصير', 'سبحن ذي اسر بعبد ليل من مسجد حرم ال مسجد اقص ذي برك حول لنر من ايت ان هو سميع بصير', 'quran', NULL, NULL, 'https://quran.com/17/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1054, 'سبح بحن الذ لذي اسر سري بعب عبد بده ليل من الم لمس مسج سجد الح لحر حرم الي الم لمس مسج سجد الق لقص الذ لذي برك ركن حول وله لنر نري ريه من ايت يتن انه هو الس لسم سمي ميع الب لبص بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1055, 'quran:17:2', 'quran', 'quran', '17:2', 2, 1054, 'Al-Isra', 'الإسراء', 'وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا', NULL, NULL, 'واتينا موسي الكتب وجعلنه هدي لبني اسرءيل الا تتخذوا من دوني وكيلا', 'اتي موس كتب جعلن هد لبن اسرءيل ال تتخذ من دون كيل', 'quran', NULL, NULL, 'https://quran.com/17/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1055, 'وتي تين موس وسي الك لكت كتب وجع جعل علن لنه هدي لبن بني اسر سرء رءي ءيل ال تتخ تخذ خذو من دون وني وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1056, 'quran:17:3', 'quran', 'quran', '17:3', 3, 1055, 'Al-Isra', 'الإسراء', 'ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا', NULL, NULL, 'ذريه من حملنا مع نوح انه كان عبدا شكورا', 'ذر من حمل مع نوح ان كن عبد شكور', 'quran', NULL, NULL, 'https://quran.com/17/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1056, 'ذري ريه من حمل ملن مع نوح انه كن عبد شكو كور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1057, 'quran:17:4', 'quran', 'quran', '17:4', 4, 1056, 'Al-Isra', 'الإسراء', 'وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا', NULL, NULL, 'وقضينا الي بني اسرءيل في الكتب لتفسدن في الارض مرتين ولتعلن علوا كبيرا', 'قضي ال بن اسرءيل في كتب لتفسدن في ارض مرت لتعلن عل كبير', 'quran', NULL, NULL, 'https://quran.com/17/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1057, 'وقض قضي ضين الي بني اسر سرء رءي ءيل في الك لكت كتب لتف تفس فسد سدن في الر لرض مرت رتي تين ولت لتع تعل علن علو كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1058, 'quran:17:5', 'quran', 'quran', '17:5', 5, 1057, 'Al-Isra', 'الإسراء', 'فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا', NULL, NULL, 'فاذا جاء وعد اولاهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلل الديار وكان وعدا مفعولا', 'اذ جء وعد اولهم بعث علي عبد لن اول بس شديد جس خلل دير كن عد مفعول', 'quran', NULL, NULL, 'https://quran.com/17/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1058, 'فذ جء وعد اول وله لهم بعث عثن علي ليك يكم عبد لن اول ولي بس شدي ديد فجس جسو خلل الد لدي دير وكن وعد مفع فعو عول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1059, 'quran:17:6', 'quran', 'quran', '17:6', 6, 1058, 'Al-Isra', 'الإسراء', 'ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا', NULL, NULL, 'ثم رددنا لكم الكره عليهم وامددنكم بامول وبنين وجعلنكم اكثر نفيرا', 'ثم ردد لكم كر علي امددن بمول بن جعلن اكثر نفير', 'quran', NULL, NULL, 'https://quran.com/17/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1059, 'ثم ردد ددن لكم الك لكر كره علي ليه يهم ومد مدد ددن دنك نكم بمو مول وبن بني نين وجع جعل علن لنك نكم اكث كثر نفي فير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1060, 'quran:17:7', 'quran', 'quran', '17:7', 7, 1059, 'Al-Isra', 'الإسراء', 'إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا', NULL, NULL, 'ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جاء وعد الاخره ليسوا وجوهكم وليدخلوا المسجد كما دخلوه اول مره وليتبروا ما علوا تتبيرا', 'ان احسنتم احسنتم لنفس ون استم له اذ جء وعد اخر ليس جوه ليدخل مسجد كم دخلو اول مر ليتبر م عل تتبير', 'quran', NULL, NULL, 'https://quran.com/17/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1060, 'ان احس حسن سنت نتم احس حسن سنت نتم لنف نفس فسك سكم ون است ستم فله فذ جء وعد الخ لخر خره ليس يسو وجو جوه وهك هكم ولي ليد يدخ دخل خلو الم لمس مسج سجد كم دخل خلو لوه اول مره ولي ليت يتب تبر برو م علو تتب تبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1061, 'quran:17:8', 'quran', 'quran', '17:8', 8, 1060, 'Al-Isra', 'الإسراء', 'عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا', NULL, NULL, 'عسي ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكفرين حصيرا', 'عس رب ان يرحم ون عدتم عد جعل جهنم كفر حصير', 'quran', NULL, NULL, 'https://quran.com/17/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1061, 'عسي ربك بكم ان يرح رحم حمك مكم ون عدت دتم عدن وجع جعل علن جهن هنم للك لكف كفر فري رين حصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1062, 'quran:17:9', 'quran', 'quran', '17:9', 9, 1061, 'Al-Isra', 'الإسراء', 'إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا', NULL, NULL, 'ان هذا القران يهدي للتي هي اقوم ويبشر المومنين الذين يعملون الصلحت ان لهم اجرا كبيرا', 'ان هذ قر يهد تي هي اقوم يبشر مومن ذين يعمل صلحت ان لهم اجر كبير', 'quran', NULL, NULL, 'https://quran.com/17/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1062, 'ان هذ الق لقر قرن يهد هدي للت لتي هي اقو قوم ويب يبش بشر الم لمو موم ومن مني نين الذ لذي ذين يعم عمل ملو لون الص لصل صلح لحت ان لهم اجر كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1063, 'quran:17:10', 'quran', 'quran', '17:10', 10, 1062, 'Al-Isra', 'الإسراء', 'وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا', NULL, NULL, 'وان الذين لا يومنون بالاخره اعتدنا لهم عذابا اليما', 'ون ذين ل يومن اخر اعتد لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/17/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1063, 'ون الذ لذي ذين ل يوم ومن منو نون بلخ لخر خره اعت عتد تدن لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1064, 'quran:17:11', 'quran', 'quran', '17:11', 11, 1063, 'Al-Isra', 'الإسراء', 'وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا', NULL, NULL, 'ويدع الانسن بالشر دعاءه بالخير وكان الانسن عجولا', 'يدع انسن شر دعء خير كن انسن عجول', 'quran', NULL, NULL, 'https://quran.com/17/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1064, 'ويد يدع الن لنس نسن بلش لشر دعء عءه بلخ لخي خير وكن الن لنس نسن عجو جول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1065, 'quran:17:12', 'quran', 'quran', '17:12', 12, 1064, 'Al-Isra', 'الإسراء', 'وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا', NULL, NULL, 'وجعلنا اليل والنهار ايتين فمحونا ايه اليل وجعلنا ايه النهار مبصره لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلنه تفصيلا', 'جعل يل نهر ايت محو اي يل جعل اي نهر مبصر لتبتغ ضل من رب لتعلم عدد سن حسب وكل شيء صلن تفصيل', 'quran', NULL, NULL, 'https://quran.com/17/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1065, 'وجع جعل علن الي ليل ولن لنه نهر ايت يتي تين فمح محو حون ايه الي ليل وجع جعل علن ايه الن لنه نهر مبص بصر صره لتب تبت بتغ تغو فضل من ربك بكم ولت لتع تعل علم لمو عدد الس لسن سني نين ولح لحس حسب وكل شيء فصل صلن لنه تفص فصي صيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1066, 'quran:17:13', 'quran', 'quran', '17:13', 13, 1065, 'Al-Isra', 'الإسراء', 'وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا', NULL, NULL, 'وكل انسن الزمنه طيره في عنقه ونخرج له يوم القيمه كتبا يلقاه منشورا', 'وكل انسن زمن طير في عنق نخرج له يوم قيم كتب يلق منشور', 'quran', NULL, NULL, 'https://quran.com/17/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1066, 'وكل انس نسن الز لزم زمن منه طير يره في عنق نقه ونخ نخر خرج له يوم الق لقي قيم يمه كتب يلق لقه منش نشو شور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1067, 'quran:17:14', 'quran', 'quran', '17:14', 14, 1066, 'Al-Isra', 'الإسراء', 'ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا', NULL, NULL, 'اقرا كتبك كفي بنفسك اليوم عليك حسيبا', 'اقر كتبك كف بنفسك يوم عليك حسيب', 'quran', NULL, NULL, 'https://quran.com/17/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1067, 'اقر كتب تبك كفي بنف نفس فسك الي ليو يوم علي ليك حسي سيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1068, 'quran:17:15', 'quran', 'quran', '17:15', 15, 1067, 'Al-Isra', 'الإسراء', 'مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا', NULL, NULL, 'من اهتدي فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازره وزر اخري وما كنا معذبين حتي نبعث رسولا', 'من اهتد انم يهتد لنفس ومن ضل انم يضل علي ول تزر ازر وزر اخر وم كن معذب حت نبعث رسول', 'quran', NULL, NULL, 'https://quran.com/17/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1068, 'من اهت هتد تدي فنم يهت هتد تدي لنف نفس فسه ومن ضل فنم يضل علي ليه ول تزر وزر زره وزر اخر خري وم كن معذ عذب ذبي بين حتي نبع بعث رسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1069, 'quran:17:16', 'quran', 'quran', '17:16', 16, 1068, 'Al-Isra', 'الإسراء', 'وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا', NULL, NULL, 'واذا اردنا ان نهلك قريه امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرنها تدميرا', 'اذ ارد ان نهلك قر امر مترفي فسق يه فحق علي قول دمرن تدمير', 'quran', NULL, NULL, 'https://quran.com/17/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1069, 'وذ ارد ردن ان نهل هلك قري ريه امر مرن متر ترف رفي فيه ففس فسق سقو فيه فحق علي ليه الق لقو قول فدم دمر مرن رنه تدم دمي مير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1070, 'quran:17:17', 'quran', 'quran', '17:17', 17, 1069, 'Al-Isra', 'الإسراء', 'وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', NULL, NULL, 'وكم اهلكنا من القرون من بعد نوح وكفي بربك بذنوب عباده خبيرا بصيرا', 'وكم اهلك من قر من بعد نوح كف بربك بذنوب عبد خبير بصير', 'quran', NULL, NULL, 'https://quran.com/17/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1070, 'وكم اهل هلك لكن من الق لقر قرو رون من بعد نوح وكف كفي برب ربك بذن ذنو نوب عبد بده خبي بير بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1071, 'quran:17:18', 'quran', 'quran', '17:18', 18, 1070, 'Al-Isra', 'الإسراء', 'مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا', NULL, NULL, 'من كان يريد العاجله عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا', 'من كن يريد عجل عجل له يه م نشء لمن نريد ثم جعل له جهنم يصل مذموم مدحور', 'quran', NULL, NULL, 'https://quran.com/17/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1071, 'من كن يري ريد الع لعج عجل جله عجل جلن له فيه م نشء لمن نري ريد ثم جعل علن له جهن هنم يصل صله مذم ذمو موم مدح دحو حور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1072, 'quran:17:19', 'quran', 'quran', '17:19', 19, 1071, 'Al-Isra', 'الإسراء', 'وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا', NULL, NULL, 'ومن اراد الاخره وسعي لها سعيها وهو مومن فاوليك كان سعيهم مشكورا', 'ومن ارد اخر سع له سعي وهو مومن اوليك كن سعي مشكور', 'quran', NULL, NULL, 'https://quran.com/17/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1072, 'ومن ارد الخ لخر خره وسع سعي له سعي عيه وهو موم ومن فول ولي ليك كن سعي عيه يهم مشك شكو كور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1073, 'quran:17:20', 'quran', 'quran', '17:20', 20, 1072, 'Al-Isra', 'الإسراء', 'كُلّٗا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا', NULL, NULL, 'كلا نمد هولاء وهولاء من عطاء ربك وما كان عطاء ربك محظورا', 'كل نمد هولء هولء من عطء ربك وم كن عطء ربك محظور', 'quran', NULL, NULL, 'https://quran.com/17/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1073, 'كل نمد هول ولء وهو هول ولء من عطء ربك وم كن عطء ربك محظ حظو ظور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1074, 'quran:17:21', 'quran', 'quran', '17:21', 21, 1073, 'Al-Isra', 'الإسراء', 'ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا', NULL, NULL, 'انظر كيف فضلنا بعضهم علي بعض وللاخره اكبر درجت واكبر تفضيلا', 'انظر كيف ضل بعض عل بعض اخر اكبر درجت اكبر تفضيل', 'quran', NULL, NULL, 'https://quran.com/17/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1074, 'انظ نظر كيف فضل ضلن بعض عضه ضهم علي بعض ولل للخ لخر خره اكب كبر درج رجت وكب كبر تفض فضي ضيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1075, 'quran:17:22', 'quran', 'quran', '17:22', 22, 1074, 'Al-Isra', 'الإسراء', 'لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا', NULL, NULL, 'لا تجعل مع الله الها اخر فتقعد مذموما مخذولا', 'ل تجعل مع له ه اخر تقعد مذموم مخذول', 'quran', NULL, NULL, 'https://quran.com/17/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1075, 'ل تجع جعل مع الل لله اله اخر فتق تقع قعد مذم ذمو موم مخذ خذو ذول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1076, 'quran:17:23', 'quran', 'quran', '17:23', 23, 1075, 'Al-Isra', 'الإسراء', 'وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا', NULL, NULL, 'وقضي ربك الا تعبدوا الا اياه وبالولدين احسنا اما يبلغن عندك الكبر احدهما او كلاهما فلا تقل لهما اف ولا تنهرهما وقل لهما قولا كريما', 'قض ربك ال تعبد ال اي ولد احس ام يبلغن عندك كبر احدهم او كلهم فل تقل لهم اف ول تنهرهم وقل لهم قول كريم', 'quran', NULL, NULL, 'https://quran.com/17/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1076, 'وقض قضي ربك ال تعب عبد بدو ال ايه وبل بلو لول ولد لدي دين احس حسن ام يبل بلغ لغن عند ندك الك لكب كبر احد حده دهم او كله لهم فل تقل لهم اف ول تنه نهر هره رهم وقل لهم قول كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1077, 'quran:17:24', 'quran', 'quran', '17:24', 24, 1076, 'Al-Isra', 'الإسراء', 'وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا', NULL, NULL, 'واخفض لهما جناح الذل من الرحمه وقل رب ارحمهما كما ربياني صغيرا', 'اخفض لهم جنح ذل من رحم وقل رب ارحمهم كم ربين صغير', 'quran', NULL, NULL, 'https://quran.com/17/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1077, 'وخف خفض لهم جنح الذ لذل من الر لرح رحم حمه وقل رب ارح رحم حمه مهم كم ربي بين يني صغي غير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1078, 'quran:17:25', 'quran', 'quran', '17:25', 25, 1077, 'Al-Isra', 'الإسراء', 'رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورٗا', NULL, NULL, 'ربكم اعلم بما في نفوسكم ان تكونوا صلحين فانه كان للاوبين غفورا', 'رب اعلم بم في نفوس ان تكون صلح ان كن اوب غفور', 'quran', NULL, NULL, 'https://quran.com/17/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1078, 'ربك بكم اعل علم بم في نفو فوس وسك سكم ان تكو كون ونو صلح لحي حين فنه كن للو لوب وبي بين غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1079, 'quran:17:26', 'quran', 'quran', '17:26', 26, 1078, 'Al-Isra', 'الإسراء', 'وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا', NULL, NULL, 'وات ذا القربي حقه والمسكين وابن السبيل ولا تبذر تبذيرا', 'وت ذ قرب حق مسك ابن سبيل ول تبذر تبذير', 'quran', NULL, NULL, 'https://quran.com/17/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1079, 'وت ذ الق لقر قرب ربي حقه ولم لمس مسك سكي كين وبن الس لسب سبي بيل ول تبذ بذر تبذ بذي ذير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1080, 'quran:17:27', 'quran', 'quran', '17:27', 27, 1079, 'Al-Isra', 'الإسراء', 'إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا', NULL, NULL, 'ان المبذرين كانوا اخون الشيطين وكان الشيطن لربه كفورا', 'ان مبذر كن اخ شيط كن شيطن لرب كفور', 'quran', NULL, NULL, 'https://quran.com/17/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1080, 'ان الم لمب مبذ بذر ذري رين كنو اخو خون الش لشي شيط يطي طين وكن الش لشي شيط يطن لرب ربه كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1081, 'quran:17:28', 'quran', 'quran', '17:28', 28, 1080, 'Al-Isra', 'الإسراء', 'وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا', NULL, NULL, 'واما تعرضن عنهم ابتغاء رحمه من ربك ترجوها فقل لهم قولا ميسورا', 'ام تعرضن عن ابتغء رحم من ربك ترجو فقل لهم قول ميسور', 'quran', NULL, NULL, 'https://quran.com/17/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1081, 'وم تعر عرض رضن عنه نهم ابت بتغ تغء رحم حمه من ربك ترج رجو جوه فقل لهم قول ميس يسو سور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1082, 'quran:17:29', 'quran', 'quran', '17:29', 29, 1081, 'Al-Isra', 'الإسراء', 'وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا', NULL, NULL, 'ولا تجعل يدك مغلوله الي عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا', 'ول تجعل يدك مغلول ال عنقك ول تبسط كل بسط تقعد ملوم محسور', 'quran', NULL, NULL, 'https://quran.com/17/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1082, 'ول تجع جعل يدك مغل غلو لول وله الي عنق نقك ول تبس بسط سطه كل الب لبس بسط فتق تقع قعد ملو لوم محس حسو سور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1083, 'quran:17:30', 'quran', 'quran', '17:30', 30, 1082, 'Al-Isra', 'الإسراء', 'إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', NULL, NULL, 'ان ربك يبسط الرزق لمن يشاء ويقدر انه كان بعباده خبيرا بصيرا', 'ان ربك يبسط رزق لمن يشء يقدر ان كن بعبد خبير بصير', 'quran', NULL, NULL, 'https://quran.com/17/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1083, 'ان ربك يبس بسط الر لرز رزق لمن يشء ويق يقد قدر انه كن بعب عبد بده خبي بير بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1084, 'quran:17:31', 'quran', 'quran', '17:31', 31, 1083, 'Al-Isra', 'الإسراء', 'وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا', NULL, NULL, 'ولا تقتلوا اولدكم خشيه املق نحن نرزقهم واياكم ان قتلهم كان خطا كبيرا', 'ول تقتل اولد خش املق نحن نرزق اي ان قتل كن خط كبير', 'quran', NULL, NULL, 'https://quran.com/17/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1084, 'ول تقت قتل تلو اول ولد لدك دكم خشي شيه امل ملق نحن نرز رزق زقه قهم ويك يكم ان قتل تله لهم كن خط كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1085, 'quran:17:32', 'quran', 'quran', '17:32', 32, 1084, 'Al-Isra', 'الإسراء', 'وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا', NULL, NULL, 'ولا تقربوا الزني انه كان فحشه وساء سبيلا', 'ول تقرب زن ان كن حش سء سبيل', 'quran', NULL, NULL, 'https://quran.com/17/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1085, 'ول تقر قرب ربو الز لزن زني انه كن فحش حشه وسء سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1086, 'quran:17:33', 'quran', 'quran', '17:33', 33, 1085, 'Al-Isra', 'الإسراء', 'وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا', NULL, NULL, 'ولا تقتلوا النفس التي حرم الله الا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطنا فلا يسرف في القتل انه كان منصورا', 'ول تقتل نفس تي حرم له ال حق ومن قتل مظلوم فقد جعل لول سلط فل يسرف في قتل ان كن منصور', 'quran', NULL, NULL, 'https://quran.com/17/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1086, 'ول تقت قتل تلو الن لنف نفس الت لتي حرم الل لله ال بلح لحق ومن قتل مظل ظلو لوم فقد جعل علن لول ولي ليه سلط لطن فل يسر سرف في الق لقت قتل انه كن منص نصو صور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1087, 'quran:17:34', 'quran', 'quran', '17:34', 34, 1086, 'Al-Isra', 'الإسراء', 'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا', NULL, NULL, 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا بالعهد ان العهد كان مسولا', 'ول تقرب مل يتيم ال تي هي احسن حت يبلغ اشد اوف عهد ان عهد كن مسول', 'quran', NULL, NULL, 'https://quran.com/17/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1087, 'ول تقر قرب ربو مل الي ليت يتي تيم ال بلت لتي هي احس حسن حتي يبل بلغ اشد شده ووف وفو بلع لعه عهد ان الع لعه عهد كن مسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1088, 'quran:17:35', 'quran', 'quran', '17:35', 35, 1087, 'Al-Isra', 'الإسراء', 'وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا', NULL, NULL, 'واوفوا الكيل اذا كلتم وزنوا بالقسطاس المستقيم ذلك خير واحسن تاويلا', 'اوف كيل اذ كلتم زن قسطس مستقيم ذلك خير احسن تويل', 'quran', NULL, NULL, 'https://quran.com/17/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1088, 'ووف وفو الك لكي كيل اذ كلت لتم وزن زنو بلق لقس قسط سطس الم لمس مست ستق تقي قيم ذلك خير وحس حسن توي ويل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1089, 'quran:17:36', 'quran', 'quran', '17:36', 36, 1088, 'Al-Isra', 'الإسراء', 'وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا', NULL, NULL, 'ولا تقف ما ليس لك به علم ان السمع والبصر والفواد كل اوليك كان عنه مسولا', 'ول تقف م ليس لك به علم ان سمع بصر فود كل اوليك كن عن مسول', 'quran', NULL, NULL, 'https://quran.com/17/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1089, 'ول تقف م ليس لك به علم ان الس لسم سمع ولب لبص بصر ولف لفو فود كل اول ولي ليك كن عنه مسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1090, 'quran:17:37', 'quran', 'quran', '17:37', 37, 1089, 'Al-Isra', 'الإسراء', 'وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا', NULL, NULL, 'ولا تمش في الارض مرحا انك لن تخرق الارض ولن تبلغ الجبال طولا', 'ول تمش في ارض مرح انك لن تخرق ارض ولن تبلغ جبل طول', 'quran', NULL, NULL, 'https://quran.com/17/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1090, 'ول تمش في الر لرض مرح انك لن تخر خرق الر لرض ولن تبل بلغ الج لجب جبل طول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1091, 'quran:17:38', 'quran', 'quran', '17:38', 38, 1090, 'Al-Isra', 'الإسراء', 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا', NULL, NULL, 'كل ذلك كان سييه عند ربك مكروها', 'كل ذلك كن سي عند ربك مكرو', 'quran', NULL, NULL, 'https://quran.com/17/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1091, 'كل ذلك كن سيي ييه عند ربك مكر كرو روه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1092, 'quran:17:39', 'quran', 'quran', '17:39', 39, 1091, 'Al-Isra', 'الإسراء', 'ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا', NULL, NULL, 'ذلك مما اوحي اليك ربك من الحكمه ولا تجعل مع الله الها اخر فتلقي في جهنم ملوما مدحورا', 'ذلك مم اوح يك ربك من حكم ول تجعل مع له ه اخر تلق في جهنم ملوم مدحور', 'quran', NULL, NULL, 'https://quran.com/17/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1092, 'ذلك مم اوح وحي الي ليك ربك من الح لحك حكم كمه ول تجع جعل مع الل لله اله اخر فتل تلق لقي في جهن هنم ملو لوم مدح دحو حور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1093, 'quran:17:40', 'quran', 'quran', '17:40', 40, 1092, 'Al-Isra', 'الإسراء', 'أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا', NULL, NULL, 'افاصفاكم ربكم بالبنين واتخذ من المليكه انثا انكم لتقولون قولا عظيما', 'افصف رب بن اتخذ من مليك انث ان لتقول قول عظيم', 'quran', NULL, NULL, 'https://quran.com/17/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1093, 'افص فصف صفك فكم ربك بكم بلب لبن بني نين وتخ تخذ من الم لمل ملي ليك يكه انث انك نكم لتق تقو قول ولو لون قول عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1094, 'quran:17:41', 'quran', 'quran', '17:41', 41, 1093, 'Al-Isra', 'الإسراء', 'وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا', NULL, NULL, 'ولقد صرفنا في هذا القران ليذكروا وما يزيدهم الا نفورا', 'لقد صرف في هذ قر ليذكر وم يزيد ال نفور', 'quran', NULL, NULL, 'https://quran.com/17/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1094, 'ولق لقد صرف رفن في هذ الق لقر قرن ليذ يذك ذكر كرو وم يزي زيد يده دهم ال نفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1095, 'quran:17:42', 'quran', 'quran', '17:42', 42, 1094, 'Al-Isra', 'الإسراء', 'قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا', NULL, NULL, 'قل لو كان معه الهه كما يقولون اذا لابتغوا الي ذي العرش سبيلا', 'قل لو كن مع هه كم يقول اذ لبتغ ال ذي عرش سبيل', 'quran', NULL, NULL, 'https://quran.com/17/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1095, 'قل لو كن معه اله لهه كم يقو قول ولو لون اذ لبت بتغ تغو الي ذي الع لعر عرش سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1096, 'quran:17:43', 'quran', 'quran', '17:43', 43, 1095, 'Al-Isra', 'الإسراء', 'سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا', NULL, NULL, 'سبحنه وتعلي عما يقولون علوا كبيرا', 'سبحن تعل عم يقول عل كبير', 'quran', NULL, NULL, 'https://quran.com/17/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1096, 'سبح بحن حنه وتع تعل علي عم يقو قول ولو لون علو كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1097, 'quran:17:44', 'quran', 'quran', '17:44', 44, 1096, 'Al-Isra', 'الإسراء', 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا', NULL, NULL, 'تسبح له السموت السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا', 'تسبح له سموت سبع ارض ومن يهن ون من شيء ال يسبح بحمد لكن ل تفقه تسبيح ان كن حليم غفور', 'quran', NULL, NULL, 'https://quran.com/17/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1097, 'تسب سبح له الس لسم سمو موت الس لسب سبع ولر لرض ومن فيه يهن ون من شيء ال يسب سبح بحم حمد مده ولك لكن ل تفق فقه قهو هون تسب سبي بيح يحه حهم انه كن حلي ليم غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1098, 'quran:17:45', 'quran', 'quran', '17:45', 45, 1097, 'Al-Isra', 'الإسراء', 'وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا', NULL, NULL, 'واذا قرات القران جعلنا بينك وبين الذين لا يومنون بالاخره حجابا مستورا', 'اذ قر قر جعل بينك بين ذين ل يومن اخر حجب مستور', 'quran', NULL, NULL, 'https://quran.com/17/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1098, 'وذ قرت الق لقر قرن جعل علن بين ينك وبي بين الذ لذي ذين ل يوم ومن منو نون بلخ لخر خره حجب مست ستو تور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1099, 'quran:17:46', 'quran', 'quran', '17:46', 46, 1098, 'Al-Isra', 'الإسراء', 'وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا', NULL, NULL, 'وجعلنا علي قلوبهم اكنه ان يفقهوه وفي اذانهم وقرا واذا ذكرت ربك في القران وحده ولوا علي ادبرهم نفورا', 'جعل عل قلوب اكن ان يفقهو وف اذن قر اذ ذكرت ربك في قر حد لو عل ادبر نفور', 'quran', NULL, NULL, 'https://quran.com/17/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1099, 'وجع جعل علن علي قلو لوب وبه بهم اكن كنه ان يفق فقه قهو هوه وفي اذن ذنه نهم وقر وذ ذكر كرت ربك في الق لقر قرن وحد حده ولو علي ادب دبر بره رهم نفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1100, 'quran:17:47', 'quran', 'quran', '17:47', 47, 1099, 'Al-Isra', 'الإسراء', 'نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا', NULL, NULL, 'نحن اعلم بما يستمعون به اذ يستمعون اليك واذ هم نجوي اذ يقول الظلمون ان تتبعون الا رجلا مسحورا', 'نحن اعلم بم يستمع به اذ يستمع يك وذ هم نجو اذ يقول ظلم ان تتبع ال رجل مسحور', 'quran', NULL, NULL, 'https://quran.com/17/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1100, 'نحن اعل علم بم يست ستم تمع معو عون به اذ يست ستم تمع معو عون الي ليك وذ هم نجو جوي اذ يقو قول الظ لظل ظلم لمو مون ان تتب تبع بعو عون ال رجل مسح سحو حور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1101, 'quran:17:48', 'quran', 'quran', '17:48', 48, 1100, 'Al-Isra', 'الإسراء', 'ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا', NULL, NULL, 'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا', 'انظر كيف ضرب لك امثل ضل فل يستطيع سبيل', 'quran', NULL, NULL, 'https://quran.com/17/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1101, 'انظ نظر كيف ضرب ربو لك الم لمث مثل فضل ضلو فل يست ستط تطي طيع يعو عون سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1102, 'quran:17:49', 'quran', 'quran', '17:49', 49, 1101, 'Al-Isra', 'الإسراء', 'وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا', NULL, NULL, 'وقالوا اءذا كنا عظما ورفتا اءنا لمبعوثون خلقا جديدا', 'قل اءذ كن عظم رفت اء لمبعوث خلق جديد', 'quran', NULL, NULL, 'https://quran.com/17/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1102, 'وقل قلو اءذ كن عظم ورف رفت اءن لمب مبع بعو عوث وثو ثون خلق جدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1103, 'quran:17:50', 'quran', 'quran', '17:50', 50, 1102, 'Al-Isra', 'الإسراء', 'قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا', NULL, NULL, 'قل كونوا حجاره او حديدا', 'قل كون حجر او حديد', 'quran', NULL, NULL, 'https://quran.com/17/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1103, 'قل كون ونو حجر جره او حدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1104, 'quran:17:51', 'quran', 'quran', '17:51', 51, 1103, 'Al-Isra', 'الإسراء', 'أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا', NULL, NULL, 'او خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم اول مره فسينغضون اليك رءوسهم ويقولون متي هو قل عسي ان يكون قريبا', 'او خلق مم يكبر في صدور سيقول من يعيد قل ذي طر اول مر سينغض يك رءوس يقول مت هو قل عس ان يك قريب', 'quran', NULL, NULL, 'https://quran.com/17/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1104, 'او خلق مم يكب كبر في صدو دور ورك ركم فسي سيق يقو قول ولو لون من يعي عيد يدن قل الذ لذي فطر طرك ركم اول مره فسي سين ينغ نغض غضو ضون الي ليك رءو ءوس وسه سهم ويق يقو قول ولو لون متي هو قل عسي ان يكو كون قري ريب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1105, 'quran:17:52', 'quran', 'quran', '17:52', 52, 1104, 'Al-Isra', 'الإسراء', 'يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا', NULL, NULL, 'يوم يدعوكم فتستجيبون بحمده وتظنون ان لبثتم الا قليلا', 'يوم يدعو تستجيب بحمد تظن ان لبثتم ال قليل', 'quran', NULL, NULL, 'https://quran.com/17/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1105, 'يوم يدع دعو عوك وكم فتس تست ستج تجي جيب يبو بون بحم حمد مده وتظ تظن ظنو نون ان لبث بثت ثتم ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1106, 'quran:17:53', 'quran', 'quran', '17:53', 53, 1105, 'Al-Isra', 'الإسراء', 'وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا', NULL, NULL, 'وقل لعبادي يقولوا التي هي احسن ان الشيطن ينزغ بينهم ان الشيطن كان للانسن عدوا مبينا', 'وقل لعبد يقول تي هي احسن ان شيطن ينزغ بين ان شيطن كن انسن عد مبي', 'quran', NULL, NULL, 'https://quran.com/17/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1106, 'وقل لعب عبد بدي يقو قول ولو الت لتي هي احس حسن ان الش لشي شيط يطن ينز نزغ بين ينه نهم ان الش لشي شيط يطن كن للن لنس نسن عدو مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1107, 'quran:17:54', 'quran', 'quran', '17:54', 54, 1106, 'Al-Isra', 'الإسراء', 'رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا', NULL, NULL, 'ربكم اعلم بكم ان يشا يرحمكم او ان يشا يعذبكم وما ارسلنك عليهم وكيلا', 'رب اعلم بكم ان يش يرحم او ان يش يعذب وم ارسلنك علي كيل', 'quran', NULL, NULL, 'https://quran.com/17/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1107, 'ربك بكم اعل علم بكم ان يش يرح رحم حمك مكم او ان يش يعذ عذب ذبك بكم وم ارس رسل سلن لنك علي ليه يهم وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1108, 'quran:17:55', 'quran', 'quran', '17:55', 55, 1107, 'Al-Isra', 'الإسراء', 'وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا', NULL, NULL, 'وربك اعلم بمن في السموت والارض ولقد فضلنا بعض النبين علي بعض واتينا داود زبورا', 'ربك اعلم بمن في سموت ارض لقد ضل بعض نب عل بعض اتي دود زبور', 'quran', NULL, NULL, 'https://quran.com/17/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1108, 'ورب ربك اعل علم بمن في الس لسم سمو موت ولر لرض ولق لقد فضل ضلن بعض الن لنب نبي بين علي بعض وتي تين دود زبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1109, 'quran:17:56', 'quran', 'quran', '17:56', 56, 1108, 'Al-Isra', 'الإسراء', 'قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا', NULL, NULL, 'قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا', 'قل ادع ذين زعمتم من دون فل يملك كشف ضر عن ول تحويل', 'quran', NULL, NULL, 'https://quran.com/17/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1109, 'قل ادع دعو الذ لذي ذين زعم عمت متم من دون ونه فل يمل ملك لكو كون كشف الض لضر عنك نكم ول تحو حوي ويل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1110, 'quran:17:57', 'quran', 'quran', '17:57', 57, 1109, 'Al-Isra', 'الإسراء', 'أُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا', NULL, NULL, 'اوليك الذين يدعون يبتغون الي ربهم الوسيله ايهم اقرب ويرجون رحمته ويخافون عذابه ان عذاب ربك كان محذورا', 'اوليك ذين يدع يبتغ ال رب وسيل اي اقرب يرج رحمت يخف عذب ان عذب ربك كن محذور', 'quran', NULL, NULL, 'https://quran.com/17/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1110, 'اول ولي ليك الذ لذي ذين يدع دعو عون يبت بتغ تغو غون الي ربه بهم الو لوس وسي سيل يله ايه يهم اقر قرب وير يرج رجو جون رحم حمت مته ويخ يخف خفو فون عذب ذبه ان عذب ربك كن محذ حذو ذور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1111, 'quran:17:58', 'quran', 'quran', '17:58', 58, 1110, 'Al-Isra', 'الإسراء', 'وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا', NULL, NULL, 'وان من قريه الا نحن مهلكوها قبل يوم القيمه او معذبوها عذابا شديدا كان ذلك في الكتب مسطورا', 'ون من قر ال نحن مهلكو قبل يوم قيم او معذبو عذب شديد كن ذلك في كتب مسطور', 'quran', NULL, NULL, 'https://quran.com/17/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1111, 'ون من قري ريه ال نحن مهل هلك لكو كوه قبل يوم الق لقي قيم يمه او معذ عذب ذبو بوه عذب شدي ديد كن ذلك في الك لكت كتب مسط سطو طور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1112, 'quran:17:59', 'quran', 'quran', '17:59', 59, 1111, 'Al-Isra', 'الإسراء', 'وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا', NULL, NULL, 'وما منعنا ان نرسل بالايت الا ان كذب بها الاولون واتينا ثمود الناقه مبصره فظلموا بها وما نرسل بالايت الا تخويفا', 'وم منع ان نرسل ايت ال ان كذب به اول اتي ثمود نق مبصر ظلم به وم نرسل ايت ال تخويف', 'quran', NULL, NULL, 'https://quran.com/17/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1112, 'وم منع نعن ان نرس رسل بلي ليت ال ان كذب به الو لول ولو لون وتي تين ثمو مود الن لنق نقه مبص بصر صره فظل ظلم لمو به وم نرس رسل بلي ليت ال تخو خوي ويف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1113, 'quran:17:60', 'quran', 'quran', '17:60', 60, 1112, 'Al-Isra', 'الإسراء', 'وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا', NULL, NULL, 'واذ قلنا لك ان ربك احاط بالناس وما جعلنا الرءيا التي ارينك الا فتنه للناس والشجره الملعونه في القران ونخوفهم فما يزيدهم الا طغينا كبيرا', 'وذ قل لك ان ربك احط نس وم جعل رءي تي ارينك ال تن نس شجر ملعون في قر نخوف فم يزيد ال طغي كبير', 'quran', NULL, NULL, 'https://quran.com/17/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1113, 'وذ قلن لك ان ربك احط بلن لنس وم جعل علن الر لرء رءي الت لتي اري رين ينك ال فتن تنه للن لنس ولش لشج شجر جره الم لمل ملع لعو عون ونه في الق لقر قرن ونخ نخو خوف وفه فهم فم يزي زيد يده دهم ال طغي غين كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1114, 'quran:17:61', 'quran', 'quran', '17:61', 61, 1113, 'Al-Isra', 'الإسراء', 'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا', NULL, NULL, 'واذ قلنا للمليكه اسجدوا لادم فسجدوا الا ابليس قال اسجد لمن خلقت طينا', 'وذ قل مليك اسجد لدم سجد ال ابليس قل اسجد لمن خلقت طي', 'quran', NULL, NULL, 'https://quran.com/17/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1114, 'وذ قلن للم لمل ملي ليك يكه اسج سجد جدو لدم فسج سجد جدو ال ابل بلي ليس قل اسج سجد لمن خلق لقت طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1115, 'quran:17:62', 'quran', 'quran', '17:62', 62, 1114, 'Al-Isra', 'الإسراء', 'قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا', NULL, NULL, 'قال ارءيتك هذا الذي كرمت علي لين اخرتن الي يوم القيمه لاحتنكن ذريته الا قليلا', 'قل ارءيتك هذ ذي كرمت عل لين اخرتن ال يوم قيم لحتنكن ذريت ال قليل', 'quran', NULL, NULL, 'https://quran.com/17/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1115, 'قل ارء رءي ءيت يتك هذ الذ لذي كرم رمت علي لين اخر خرت رتن الي يوم الق لقي قيم يمه لحت حتن تنك نكن ذري ريت يته ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1116, 'quran:17:63', 'quran', 'quran', '17:63', 63, 1115, 'Al-Isra', 'الإسراء', 'قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا', NULL, NULL, 'قال اذهب فمن تبعك منهم فان جهنم جزاوكم جزاء موفورا', 'قل اذهب فمن تبعك من فن جهنم جزو جزء موفور', 'quran', NULL, NULL, 'https://quran.com/17/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1116, 'قل اذه ذهب فمن تبع بعك منه نهم فن جهن هنم جزو زوك وكم جزء موف وفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1117, 'quran:17:64', 'quran', 'quran', '17:64', 64, 1116, 'Al-Isra', 'الإسراء', 'وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا', NULL, NULL, 'واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الامول والاولد وعدهم وما يعدهم الشيطن الا غرورا', 'استفزز من استطعت من بصوتك اجلب علي بخيلك رجلك شرك في امول اولد عد وم يعد شيطن ال غرور', 'quran', NULL, NULL, 'https://quran.com/17/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1117, 'وست ستف تفز فزز من است ستط تطع طعت منه نهم بصو صوت وتك وجل جلب علي ليه يهم بخي خيل يلك ورج رجل جلك وشر شرك ركه كهم في الم لمو مول ولو لول ولد وعد عده دهم وم يعد عده دهم الش لشي شيط يطن ال غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1118, 'quran:17:65', 'quran', 'quran', '17:65', 65, 1117, 'Al-Isra', 'الإسراء', 'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا', NULL, NULL, 'ان عبادي ليس لك عليهم سلطن وكفي بربك وكيلا', 'ان عبد ليس لك علي سلطن كف بربك كيل', 'quran', NULL, NULL, 'https://quran.com/17/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1118, 'ان عبد بدي ليس لك علي ليه يهم سلط لطن وكف كفي برب ربك وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1119, 'quran:17:66', 'quran', 'quran', '17:66', 66, 1118, 'Al-Isra', 'الإسراء', 'رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا', NULL, NULL, 'ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله انه كان بكم رحيما', 'رب ذي يزج لكم فلك في بحر لتبتغ من ضل ان كن بكم رحيم', 'quran', NULL, NULL, 'https://quran.com/17/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1119, 'ربك بكم الذ لذي يزج زجي لكم الف لفل فلك في الب لبح بحر لتب تبت بتغ تغو من فضل ضله انه كن بكم رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1120, 'quran:17:67', 'quran', 'quran', '17:67', 67, 1119, 'Al-Isra', 'الإسراء', 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا', NULL, NULL, 'واذا مسكم الضر في البحر ضل من تدعون الا اياه فلما نجاكم الي البر اعرضتم وكان الانسن كفورا', 'اذ مس ضر في بحر ضل من تدع ال اي لم نج ال بر اعرضتم كن انسن كفور', 'quran', NULL, NULL, 'https://quran.com/17/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1120, 'وذ مسك سكم الض لضر في الب لبح بحر ضل من تدع دعو عون ال ايه فلم نجك جكم الي الب لبر اعر عرض رضت ضتم وكن الن لنس نسن كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1121, 'quran:17:68', 'quran', 'quran', '17:68', 68, 1120, 'Al-Isra', 'الإسراء', 'أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا', NULL, NULL, 'افامنتم ان يخسف بكم جانب البر او يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا', 'افمنتم ان يخسف بكم جنب بر او يرسل علي حصب ثم ل تجد لكم كيل', 'quran', NULL, NULL, 'https://quran.com/17/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1121, 'افم فمن منت نتم ان يخس خسف بكم جنب الب لبر او يرس رسل علي ليك يكم حصب ثم ل تجد جدو لكم وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1122, 'quran:17:69', 'quran', 'quran', '17:69', 69, 1121, 'Al-Isra', 'الإسراء', 'أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا', NULL, NULL, 'ام امنتم ان يعيدكم فيه تاره اخري فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا', 'ام امنتم ان يعيد في تر اخر يرسل علي قصف من ريح يغرق بم كفرتم ثم ل تجد لكم علي به تبيع', 'quran', NULL, NULL, 'https://quran.com/17/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1122, 'ام امن منت نتم ان يعي عيد يدك دكم فيه تره اخر خري فير يرس رسل علي ليك يكم قصف من الر لري ريح فيغ يغر غرق رقك قكم بم كفر فرت رتم ثم ل تجد جدو لكم علي لين به تبي بيع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1123, 'quran:17:70', 'quran', 'quran', '17:70', 70, 1122, 'Al-Isra', 'الإسراء', 'وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا', NULL, NULL, 'ولقد كرمنا بني ادم وحملنهم في البر والبحر ورزقنهم من الطيبت وفضلنهم علي كثير ممن خلقنا تفضيلا', 'لقد كرم بن ادم حملن في بر بحر رزقن من طيبت فضلن عل كثير ممن خلق تفضيل', 'quran', NULL, NULL, 'https://quran.com/17/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1123, 'ولق لقد كرم رمن بني ادم وحم حمل ملن لنه نهم في الب لبر ولب لبح بحر ورز رزق زقن قنه نهم من الط لطي طيب يبت وفض فضل ضلن لنه نهم علي كثي ثير ممن خلق لقن تفض فضي ضيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1124, 'quran:17:71', 'quran', 'quran', '17:71', 71, 1123, 'Al-Isra', 'الإسراء', 'يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا', NULL, NULL, 'يوم ندعوا كل اناس باممهم فمن اوتي كتبه بيمينه فاوليك يقرءون كتبهم ولا يظلمون فتيلا', 'يوم ندع كل انس بمم فمن اوت كتب بيمين اوليك يقرء كتب ول يظلم تيل', 'quran', NULL, NULL, 'https://quran.com/17/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1124, 'يوم ندع دعو كل انس بمم ممه مهم فمن اوت وتي كتب تبه بيم يمي مين ينه فول ولي ليك يقر قرء رءو ءون كتب تبه بهم ول يظل ظلم لمو مون فتي تيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1125, 'quran:17:72', 'quran', 'quran', '17:72', 72, 1124, 'Al-Isra', 'الإسراء', 'وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا', NULL, NULL, 'ومن كان في هذه اعمي فهو في الاخره اعمي واضل سبيلا', 'ومن كن في هذ اعم فهو في اخر اعم اضل سبيل', 'quran', NULL, NULL, 'https://quran.com/17/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1125, 'ومن كن في هذه اعم عمي فهو في الخ لخر خره اعم عمي وضل سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1126, 'quran:17:73', 'quran', 'quran', '17:73', 73, 1125, 'Al-Isra', 'الإسراء', 'وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا', NULL, NULL, 'وان كادوا ليفتنونك عن الذي اوحينا اليك لتفتري علينا غيره واذا لاتخذوك خليلا', 'ون كد ليفتنونك عن ذي اوحي يك لتفتر علي غير اذ لتخذوك خليل', 'quran', NULL, NULL, 'https://quran.com/17/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1126, 'ون كدو ليف يفت فتن تنو نون ونك عن الذ لذي اوح وحي حين الي ليك لتف تفت فتر تري علي لين غير يره وذ لتخ تخذ خذو ذوك خلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1127, 'quran:17:74', 'quran', 'quran', '17:74', 74, 1126, 'Al-Isra', 'الإسراء', 'وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا', NULL, NULL, 'ولولا ان ثبتنك لقد كدت تركن اليهم شيا قليلا', 'لول ان ثبتنك لقد كدت تركن يهم شي قليل', 'quran', NULL, NULL, 'https://quran.com/17/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1127, 'ولو لول ان ثبت بتن تنك لقد كدت ترك ركن الي ليه يهم شي قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1128, 'quran:17:75', 'quran', 'quran', '17:75', 75, 1127, 'Al-Isra', 'الإسراء', 'إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا', NULL, NULL, 'اذا لاذقنك ضعف الحياه وضعف الممات ثم لا تجد لك علينا نصيرا', 'اذ لذقنك ضعف حي ضعف مم ثم ل تجد لك علي نصير', 'quran', NULL, NULL, 'https://quran.com/17/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1128, 'اذ لذق ذقن قنك ضعف الح لحي حيه وضع ضعف الم لمم ممت ثم ل تجد لك علي لين نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1129, 'quran:17:76', 'quran', 'quran', '17:76', 76, 1128, 'Al-Isra', 'الإسراء', 'وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا', NULL, NULL, 'وان كادوا ليستفزونك من الارض ليخرجوك منها واذا لا يلبثون خلفك الا قليلا', 'ون كد ليستفزونك من ارض ليخرجوك من اذ ل يلبث خلفك ال قليل', 'quran', NULL, NULL, 'https://quran.com/17/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1129, 'ون كدو ليس يست ستف تفز فزو زون ونك من الر لرض ليخ يخر خرج رجو جوك منه وذ ل يلب لبث بثو ثون خلف لفك ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1130, 'quran:17:77', 'quran', 'quran', '17:77', 77, 1129, 'Al-Isra', 'الإسراء', 'سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا', NULL, NULL, 'سنه من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا', 'سن من قد ارسل قبلك من رسل ول تجد لسنت تحويل', 'quran', NULL, NULL, 'https://quran.com/17/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1130, 'سنه من قد ارس رسل سلن قبل بلك من رسل سلن ول تجد لسن سنت نتن تحو حوي ويل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1131, 'quran:17:78', 'quran', 'quran', '17:78', 78, 1130, 'Al-Isra', 'الإسراء', 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا', NULL, NULL, 'اقم الصلاه لدلوك الشمس الي غسق اليل وقران الفجر ان قران الفجر كان مشهودا', 'اقم صل لدلوك شمس ال غسق يل قر فجر ان قر فجر كن مشهود', 'quran', NULL, NULL, 'https://quran.com/17/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1131, 'اقم الص لصل صله لدل دلو لوك الش لشم شمس الي غسق الي ليل وقر قرن الف لفج فجر ان قرن الف لفج فجر كن مشه شهو هود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1132, 'quran:17:79', 'quran', 'quran', '17:79', 79, 1131, 'Al-Isra', 'الإسراء', 'وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا', NULL, NULL, 'ومن اليل فتهجد به نافله لك عسي ان يبعثك ربك مقاما محمودا', 'ومن يل تهجد به نفل لك عس ان يبعثك ربك مقم محمود', 'quran', NULL, NULL, 'https://quran.com/17/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1132, 'ومن الي ليل فته تهج هجد به نفل فله لك عسي ان يبع بعث عثك ربك مقم محم حمو مود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1133, 'quran:17:80', 'quran', 'quran', '17:80', 80, 1132, 'Al-Isra', 'الإسراء', 'وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا', NULL, NULL, 'وقل رب ادخلني مدخل صدق واخرجني مخرج صدق واجعل لي من لدنك سلطنا نصيرا', 'وقل رب ادخلن مدخل صدق اخرجن مخرج صدق اجعل لي من لدنك سلط نصير', 'quran', NULL, NULL, 'https://quran.com/17/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1133, 'وقل رب ادخ دخل خلن لني مدخ دخل صدق وخر خرج رجن جني مخر خرج صدق وجع جعل لي من لدن دنك سلط لطن نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1134, 'quran:17:81', 'quran', 'quran', '17:81', 81, 1133, 'Al-Isra', 'الإسراء', 'وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا', NULL, NULL, 'وقل جاء الحق وزهق البطل ان البطل كان زهوقا', 'وقل جء حق زهق بطل ان بطل كن زهوق', 'quran', NULL, NULL, 'https://quran.com/17/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1134, 'وقل جء الح لحق وزه زهق الب لبط بطل ان الب لبط بطل كن زهو هوق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1135, 'quran:17:82', 'quran', 'quran', '17:82', 82, 1134, 'Al-Isra', 'الإسراء', 'وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا', NULL, NULL, 'وننزل من القران ما هو شفاء ورحمه للمومنين ولا يزيد الظلمين الا خسارا', 'ننزل من قر م هو شفء رحم مومن ول يزيد ظلم ال خسر', 'quran', NULL, NULL, 'https://quran.com/17/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1135, 'ونن ننز نزل من الق لقر قرن م هو شفء ورح رحم حمه للم لمو موم ومن مني نين ول يزي زيد الظ لظل ظلم لمي مين ال خسر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1136, 'quran:17:83', 'quran', 'quran', '17:83', 83, 1135, 'Al-Isra', 'الإسراء', 'وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا', NULL, NULL, 'واذا انعمنا علي الانسن اعرض ونا بجانبه واذا مسه الشر كان يوسا', 'اذ انعم عل انسن اعرض ون بجنب اذ مس شر كن يوس', 'quran', NULL, NULL, 'https://quran.com/17/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1136, 'وذ انع نعم عمن علي الن لنس نسن اعر عرض ون بجن جنب نبه وذ مسه الش لشر كن يوس');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1137, 'quran:17:84', 'quran', 'quran', '17:84', 84, 1136, 'Al-Isra', 'الإسراء', 'قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا', NULL, NULL, 'قل كل يعمل علي شاكلته فربكم اعلم بمن هو اهدي سبيلا', 'قل كل يعمل عل شكلت رب اعلم بمن هو اهد سبيل', 'quran', NULL, NULL, 'https://quran.com/17/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1137, 'قل كل يعم عمل علي شكل كلت لته فرب ربك بكم اعل علم بمن هو اهد هدي سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1138, 'quran:17:85', 'quran', 'quran', '17:85', 85, 1137, 'Al-Isra', 'الإسراء', 'وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا', NULL, NULL, 'ويسلونك عن الروح قل الروح من امر ربي وما اوتيتم من العلم الا قليلا', 'يسلونك عن روح قل روح من امر رب وم اوتيتم من علم ال قليل', 'quran', NULL, NULL, 'https://quran.com/17/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1138, 'ويس يسل سلو لون ونك عن الر لرو روح قل الر لرو روح من امر ربي وم اوت وتي تيت يتم من الع لعل علم ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1139, 'quran:17:86', 'quran', 'quran', '17:86', 86, 1138, 'Al-Isra', 'الإسراء', 'وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا', NULL, NULL, 'ولين شينا لنذهبن بالذي اوحينا اليك ثم لا تجد لك به علينا وكيلا', 'لين شي لنذهبن ذي اوحي يك ثم ل تجد لك به علي كيل', 'quran', NULL, NULL, 'https://quran.com/17/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1139, 'ولي لين شين لنذ نذه ذهب هبن بلذ لذي اوح وحي حين الي ليك ثم ل تجد لك به علي لين وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1140, 'quran:17:87', 'quran', 'quran', '17:87', 87, 1139, 'Al-Isra', 'الإسراء', 'إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا', NULL, NULL, 'الا رحمه من ربك ان فضله كان عليك كبيرا', 'ال رحم من ربك ان ضل كن عليك كبير', 'quran', NULL, NULL, 'https://quran.com/17/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1140, 'ال رحم حمه من ربك ان فضل ضله كن علي ليك كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1141, 'quran:17:88', 'quran', 'quran', '17:88', 88, 1140, 'Al-Isra', 'الإسراء', 'قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا', NULL, NULL, 'قل لين اجتمعت الانس والجن علي ان ياتوا بمثل هذا القران لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا', 'قل لين اجتمعت انس جن عل ان يت بمثل هذ قر ل يت بمثل ولو كن بعض لبعض ظهير', 'quran', NULL, NULL, 'https://quran.com/17/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1141, 'قل لين اجت جتم تمع معت الن لنس ولج لجن علي ان يتو بمث مثل هذ الق لقر قرن ل يتو تون بمث مثل ثله ولو كن بعض عضه ضهم لبع بعض ظهي هير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1142, 'quran:17:89', 'quran', 'quran', '17:89', 89, 1141, 'Al-Isra', 'الإسراء', 'وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا', NULL, NULL, 'ولقد صرفنا للناس في هذا القران من كل مثل فابي اكثر الناس الا كفورا', 'لقد صرف نس في هذ قر من كل مثل اب اكثر نس ال كفور', 'quran', NULL, NULL, 'https://quran.com/17/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1142, 'ولق لقد صرف رفن للن لنس في هذ الق لقر قرن من كل مثل فبي اكث كثر الن لنس ال كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1143, 'quran:17:90', 'quran', 'quran', '17:90', 90, 1142, 'Al-Isra', 'الإسراء', 'وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا', NULL, NULL, 'وقالوا لن نومن لك حتي تفجر لنا من الارض ينبوعا', 'قل لن نومن لك حت تفجر لن من ارض ينبوع', 'quran', NULL, NULL, 'https://quran.com/17/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1143, 'وقل قلو لن نوم ومن لك حتي تفج فجر لن من الر لرض ينب نبو بوع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1144, 'quran:17:91', 'quran', 'quran', '17:91', 91, 1143, 'Al-Isra', 'الإسراء', 'أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا', NULL, NULL, 'او تكون لك جنه من نخيل وعنب فتفجر الانهر خللها تفجيرا', 'او تك لك جن من نخيل عنب تفجر انهر خلل تفجير', 'quran', NULL, NULL, 'https://quran.com/17/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1144, 'او تكو كون لك جنه من نخي خيل وعن عنب فتف تفج فجر الن لنه نهر خلل لله تفج فجي جير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1145, 'quran:17:92', 'quran', 'quran', '17:92', 92, 1144, 'Al-Isra', 'الإسراء', 'أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ قَبِيلًا', NULL, NULL, 'او تسقط السماء كما زعمت علينا كسفا او تاتي بالله والمليكه قبيلا', 'او تسقط سمء كم زعمت علي كسف او تت له مليك قبيل', 'quran', NULL, NULL, 'https://quran.com/17/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1145, 'او تسق سقط الس لسم سمء كم زعم عمت علي لين كسف او تتي بلل لله ولم لمل ملي ليك يكه قبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1146, 'quran:17:93', 'quran', 'quran', '17:93', 93, 1145, 'Al-Isra', 'الإسراء', 'أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا', NULL, NULL, 'او يكون لك بيت من زخرف او ترقي في السماء ولن نومن لرقيك حتي تنزل علينا كتبا نقروه قل سبحان ربي هل كنت الا بشرا رسولا', 'او يك لك بيت من زخرف او ترق في سمء ولن نومن لرقيك حت تنزل علي كتب نقرو قل سبح رب هل كنت ال بشر رسول', 'quran', NULL, NULL, 'https://quran.com/17/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1146, 'او يكو كون لك بيت من زخر خرف او ترق رقي في الس لسم سمء ولن نوم ومن لرق رقي قيك حتي تنز نزل علي لين كتب نقر قرو روه قل سبح بحن ربي هل كنت ال بشر رسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1147, 'quran:17:94', 'quran', 'quran', '17:94', 94, 1146, 'Al-Isra', 'الإسراء', 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا', NULL, NULL, 'وما منع الناس ان يومنوا اذ جاءهم الهدي الا ان قالوا ابعث الله بشرا رسولا', 'وم منع نس ان يومن اذ جء هد ال ان قل ابعث له بشر رسول', 'quran', NULL, NULL, 'https://quran.com/17/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1147, 'وم منع الن لنس ان يوم ومن منو اذ جءه ءهم اله لهد هدي ال ان قلو ابع بعث الل لله بشر رسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1148, 'quran:17:95', 'quran', 'quran', '17:95', 95, 1147, 'Al-Isra', 'الإسراء', 'قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا', NULL, NULL, 'قل لو كان في الارض مليكه يمشون مطمينين لنزلنا عليهم من السماء ملكا رسولا', 'قل لو كن في ارض مليك يمش مطمين لنزل علي من سمء ملك رسول', 'quran', NULL, NULL, 'https://quran.com/17/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1148, 'قل لو كن في الر لرض ملي ليك يكه يمش مشو شون مطم طمي مين يني نين لنز نزل زلن علي ليه يهم من الس لسم سمء ملك رسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1149, 'quran:17:96', 'quran', 'quran', '17:96', 96, 1148, 'Al-Isra', 'الإسراء', 'قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', NULL, NULL, 'قل كفي بالله شهيدا بيني وبينكم انه كان بعباده خبيرا بصيرا', 'قل كف له شهيد بين بين ان كن بعبد خبير بصير', 'quran', NULL, NULL, 'https://quran.com/17/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1149, 'قل كفي بلل لله شهي هيد بين يني وبي بين ينك نكم انه كن بعب عبد بده خبي بير بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1150, 'quran:17:97', 'quran', 'quran', '17:97', 97, 1149, 'Al-Isra', 'الإسراء', 'وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا', NULL, NULL, 'ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم اولياء من دونه ونحشرهم يوم القيمه علي وجوههم عميا وبكما وصما ماواهم جهنم كلما خبت زدنهم سعيرا', 'ومن يهد له فهو مهتد ومن يضلل فلن تجد لهم اوليء من دون نحشر يوم قيم عل جوه عمي بكم صم مو جهنم كلم خبت زدن سعير', 'quran', NULL, NULL, 'https://quran.com/17/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1150, 'ومن يهد الل لله فهو الم لمه مهت هتد ومن يضل ضلل فلن تجد لهم اول ولي ليء من دون ونه ونح نحش حشر شره رهم يوم الق لقي قيم يمه علي وجو جوه وهه ههم عمي وبك بكم وصم موه وهم جهن هنم كلم خبت زدن دنه نهم سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1151, 'quran:17:98', 'quran', 'quran', '17:98', 98, 1150, 'Al-Isra', 'الإسراء', 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا', NULL, NULL, 'ذلك جزاوهم بانهم كفروا بايتنا وقالوا اءذا كنا عظما ورفتا اءنا لمبعوثون خلقا جديدا', 'ذلك جزو بن كفر بيت قل اءذ كن عظم رفت اء لمبعوث خلق جديد', 'quran', NULL, NULL, 'https://quran.com/17/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1151, 'ذلك جزو زوه وهم بنه نهم كفر فرو بيت يتن وقل قلو اءذ كن عظم ورف رفت اءن لمب مبع بعو عوث وثو ثون خلق جدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1152, 'quran:17:99', 'quran', 'quran', '17:99', 99, 1151, 'Al-Isra', 'الإسراء', 'أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورٗا', NULL, NULL, 'اولم يروا ان الله الذي خلق السموت والارض قادر علي ان يخلق مثلهم وجعل لهم اجلا لا ريب فيه فابي الظلمون الا كفورا', 'اولم ير ان له ذي خلق سموت ارض قدر عل ان يخلق مثل جعل لهم اجل ل ريب في اب ظلم ال كفور', 'quran', NULL, NULL, 'https://quran.com/17/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1152, 'اول ولم يرو ان الل لله الذ لذي خلق الس لسم سمو موت ولر لرض قدر علي ان يخل خلق مثل ثله لهم وجع جعل لهم اجل ل ريب فيه فبي الظ لظل ظلم لمو مون ال كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1153, 'quran:17:100', 'quran', 'quran', '17:100', 100, 1152, 'Al-Isra', 'الإسراء', 'قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا', NULL, NULL, 'قل لو انتم تملكون خزاين رحمه ربي اذا لامسكتم خشيه الانفاق وكان الانسن قتورا', 'قل لو انتم تملك خز رحم رب اذ لمسكتم خش انفق كن انسن قتور', 'quran', NULL, NULL, 'https://quran.com/17/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1153, 'قل لو انت نتم تمل ملك لكو كون خزي زين رحم حمه ربي اذ لمس مسك سكت كتم خشي شيه الن لنف نفق وكن الن لنس نسن قتو تور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1154, 'quran:17:101', 'quran', 'quran', '17:101', 101, 1153, 'Al-Isra', 'الإسراء', 'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا', NULL, NULL, 'ولقد اتينا موسي تسع ايت بينت فسل بني اسرءيل اذ جاءهم فقال له فرعون اني لاظنك يا موسي مسحورا', 'لقد اتي موس تسع ايت بينت فسل بن اسرءيل اذ جء قل له رع ان لظنك ي موس مسحور', 'quran', NULL, NULL, 'https://quran.com/17/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1154, 'ولق لقد اتي تين موس وسي تسع ايت بين ينت فسل بني اسر سرء رءي ءيل اذ جءه ءهم فقل له فرع رعو عون اني لظن ظنك ي موس وسي مسح سحو حور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1155, 'quran:17:102', 'quran', 'quran', '17:102', 102, 1154, 'Al-Isra', 'الإسراء', 'قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا', NULL, NULL, 'قال لقد علمت ما انزل هولاء الا رب السموت والارض بصاير واني لاظنك يا فرعون مثبورا', 'قل لقد علمت م انزل هولء ال رب سموت ارض بصير ان لظنك ي رع مثبور', 'quran', NULL, NULL, 'https://quran.com/17/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1155, 'قل لقد علم لمت م انز نزل هول ولء ال رب الس لسم سمو موت ولر لرض بصي صير وني لظن ظنك ي فرع رعو عون مثب ثبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1156, 'quran:17:103', 'quran', 'quran', '17:103', 103, 1155, 'Al-Isra', 'الإسراء', 'فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا', NULL, NULL, 'فاراد ان يستفزهم من الارض فاغرقنه ومن معه جميعا', 'ارد ان يستفز من ارض اغرقن ومن مع جميع', 'quran', NULL, NULL, 'https://quran.com/17/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1156, 'فرد ان يست ستف تفز فزه زهم من الر لرض فغر غرق رقن قنه ومن معه جمي ميع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1157, 'quran:17:104', 'quran', 'quran', '17:104', 104, 1156, 'Al-Isra', 'الإسراء', 'وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا', NULL, NULL, 'وقلنا من بعده لبني اسرءيل اسكنوا الارض فاذا جاء وعد الاخره جينا بكم لفيفا', 'قل من بعد لبن اسرءيل اسكن ارض اذ جء وعد اخر جي بكم لفيف', 'quran', NULL, NULL, 'https://quran.com/17/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1157, 'وقل قلن من بعد عده لبن بني اسر سرء رءي ءيل اسك سكن كنو الر لرض فذ جء وعد الخ لخر خره جين بكم لفي فيف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1158, 'quran:17:105', 'quran', 'quran', '17:105', 105, 1157, 'Al-Isra', 'الإسراء', 'وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا', NULL, NULL, 'وبالحق انزلنه وبالحق نزل وما ارسلنك الا مبشرا ونذيرا', 'حق انزلن حق نزل وم ارسلنك ال مبشر نذير', 'quran', NULL, NULL, 'https://quran.com/17/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1158, 'وبل بلح لحق انز نزل زلن لنه وبل بلح لحق نزل وم ارس رسل سلن لنك ال مبش بشر ونذ نذي ذير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1159, 'quran:17:106', 'quran', 'quran', '17:106', 106, 1158, 'Al-Isra', 'الإسراء', 'وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا', NULL, NULL, 'وقرانا فرقنه لتقراه علي الناس علي مكث ونزلنه تنزيلا', 'قر رقن لتقر عل نس عل مكث نزلن تنزيل', 'quran', NULL, NULL, 'https://quran.com/17/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1159, 'وقر قرن فرق رقن قنه لتق تقر قره علي الن لنس علي مكث ونز نزل زلن لنه تنز نزي زيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1160, 'quran:17:107', 'quran', 'quran', '17:107', 107, 1159, 'Al-Isra', 'الإسراء', 'قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ', NULL, NULL, 'قل امنوا به او لا تومنوا ان الذين اوتوا العلم من قبله اذا يتلي عليهم يخرون للاذقان سجدا', 'قل امن به او ل تومن ان ذين اوت علم من قبل اذ يتل علي يخر اذق سجد', 'quran', NULL, NULL, 'https://quran.com/17/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1160, 'قل امن منو به او ل توم ومن منو ان الذ لذي ذين اوت وتو الع لعل علم من قبل بله اذ يتل تلي علي ليه يهم يخر خرو رون للذ لذق ذقن سجد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1161, 'quran:17:108', 'quran', 'quran', '17:108', 108, 1160, 'Al-Isra', 'الإسراء', 'وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا', NULL, NULL, 'ويقولون سبحن ربنا ان كان وعد ربنا لمفعولا', 'يقول سبحن رب ان كن وعد رب لمفعول', 'quran', NULL, NULL, 'https://quran.com/17/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1161, 'ويق يقو قول ولو لون سبح بحن ربن ان كن وعد ربن لمف مفع فعو عول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1162, 'quran:17:109', 'quran', 'quran', '17:109', 109, 1161, 'Al-Isra', 'الإسراء', 'وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا', NULL, NULL, 'ويخرون للاذقان يبكون ويزيدهم خشوعا', 'يخر اذق يبك يزيد خشوع', 'quran', NULL, NULL, 'https://quran.com/17/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1162, 'ويخ يخر خرو رون للذ لذق ذقن يبك بكو كون ويز يزي زيد يده دهم خشو شوع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1163, 'quran:17:110', 'quran', 'quran', '17:110', 110, 1162, 'Al-Isra', 'الإسراء', 'قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا', NULL, NULL, 'قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسماء الحسني ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا', 'قل ادع له او ادع رحمن اي م تدع فل اسمء حسن ول تجهر بصلتك ول تخفت به ابتغ بين ذلك سبيل', 'quran', NULL, NULL, 'https://quran.com/17/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1163, 'قل ادع دعو الل لله او ادع دعو الر لرح رحم حمن اي م تدع دعو فله الس لسم سمء الح لحس حسن سني ول تجه جهر بصل صلت لتك ول تخف خفت به وبت بتغ بين ذلك سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1164, 'quran:17:111', 'quran', 'quran', '17:111', 111, 1163, 'Al-Isra', 'الإسراء', 'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا', NULL, NULL, 'وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا', 'وقل حمد لل ذي لم يتخذ لد ولم يكن له شريك في ملك ولم يكن له ول من ذل كبر تكبير', 'quran', NULL, NULL, 'https://quran.com/17/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1164, 'وقل الح لحم حمد لله الذ لذي لم يتخ تخذ ولد ولم يكن له شري ريك في الم لمل ملك ولم يكن له ولي من الذ لذل وكب كبر بره تكب كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1165, 'quran:20:1', 'quran', 'quran', '20:1', 1, 1164, 'Taha', 'طه', 'طه', NULL, NULL, 'طه', 'طه', 'quran', NULL, NULL, 'https://quran.com/20/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1165, 'طه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1166, 'quran:20:2', 'quran', 'quran', '20:2', 2, 1165, 'Taha', 'طه', 'مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ', NULL, NULL, 'ما انزلنا عليك القران لتشقي', 'م انزل عليك قر لتشق', 'quran', NULL, NULL, 'https://quran.com/20/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1166, 'م انز نزل زلن علي ليك الق لقر قرن لتش تشق شقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1167, 'quran:20:3', 'quran', 'quran', '20:3', 3, 1166, 'Taha', 'طه', 'إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ', NULL, NULL, 'الا تذكره لمن يخشي', 'ال تذكر لمن يخش', 'quran', NULL, NULL, 'https://quran.com/20/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1167, 'ال تذك ذكر كره لمن يخش خشي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1168, 'quran:20:4', 'quran', 'quran', '20:4', 4, 1167, 'Taha', 'طه', 'تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى', NULL, NULL, 'تنزيلا ممن خلق الارض والسموت العلي', 'تنزيل ممن خلق ارض سموت عل', 'quran', NULL, NULL, 'https://quran.com/20/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1168, 'تنز نزي زيل ممن خلق الر لرض ولس لسم سمو موت الع لعل علي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1169, 'quran:20:5', 'quran', 'quran', '20:5', 5, 1168, 'Taha', 'طه', 'ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ', NULL, NULL, 'الرحمن علي العرش استوي', 'رحمن عل عرش استو', 'quran', NULL, NULL, 'https://quran.com/20/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1169, 'الر لرح رحم حمن علي الع لعر عرش است ستو توي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1170, 'quran:20:6', 'quran', 'quran', '20:6', 6, 1169, 'Taha', 'طه', 'لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ', NULL, NULL, 'له ما في السموت وما في الارض وما بينهما وما تحت الثري', 'له م في سموت وم في ارض وم بينهم وم تحت ثر', 'quran', NULL, NULL, 'https://quran.com/20/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1170, 'له م في الس لسم سمو موت وم في الر لرض وم بين ينه نهم وم تحت الث لثر ثري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1171, 'quran:20:7', 'quran', 'quran', '20:7', 7, 1170, 'Taha', 'طه', 'وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى', NULL, NULL, 'وان تجهر بالقول فانه يعلم السر واخفي', 'ون تجهر قول ان يعلم سر اخف', 'quran', NULL, NULL, 'https://quran.com/20/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1171, 'ون تجه جهر بلق لقو قول فنه يعل علم الس لسر وخف خفي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1172, 'quran:20:8', 'quran', 'quran', '20:8', 8, 1171, 'Taha', 'طه', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ', NULL, NULL, 'الله لا اله الا هو له الاسماء الحسني', 'له ل ال ال هو له اسمء حسن', 'quran', NULL, NULL, 'https://quran.com/20/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1172, 'الل لله ل اله ال هو له الس لسم سمء الح لحس حسن سني');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1173, 'quran:20:9', 'quran', 'quran', '20:9', 9, 1172, 'Taha', 'طه', 'وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', NULL, NULL, 'وهل اتاك حديث موسي', 'وهل اتك حديث موس', 'quran', NULL, NULL, 'https://quran.com/20/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1173, 'وهل اتك حدي ديث موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1174, 'quran:20:10', 'quran', 'quran', '20:10', 10, 1173, 'Taha', 'طه', 'إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى', NULL, NULL, 'اذ را نارا فقال لاهله امكثوا اني انست نارا لعلي اتيكم منها بقبس او اجد علي النار هدي', 'اذ ر نر قل لهل امكث ان انست نر لعل اتي من بقبس او اجد عل نر هد', 'quran', NULL, NULL, 'https://quran.com/20/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1174, 'اذ ر نر فقل لهل هله امك مكث كثو اني انس نست نر لعل علي اتي تيك يكم منه بقب قبس او اجد علي الن لنر هدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1175, 'quran:20:11', 'quran', 'quran', '20:11', 11, 1174, 'Taha', 'طه', 'فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ', NULL, NULL, 'فلما اتاها نودي يا موسي', 'لم ات نود ي موس', 'quran', NULL, NULL, 'https://quran.com/20/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1175, 'فلم اته نود ودي ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1176, 'quran:20:12', 'quran', 'quran', '20:12', 12, 1175, 'Taha', 'طه', 'إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى', NULL, NULL, 'اني انا ربك فاخلع نعليك انك بالواد المقدس طوي', 'ان ان ربك اخلع نعليك انك ود مقدس طو', 'quran', NULL, NULL, 'https://quran.com/20/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1176, 'اني ان ربك فخل خلع نعل علي ليك انك بلو لود الم لمق مقد قدس طوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1177, 'quran:20:13', 'quran', 'quran', '20:13', 13, 1176, 'Taha', 'طه', 'وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ', NULL, NULL, 'وانا اخترتك فاستمع لما يوحي', 'ان اخترتك استمع لم يوح', 'quran', NULL, NULL, 'https://quran.com/20/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1177, 'ون اخت ختر ترت رتك فست ستم تمع لم يوح وحي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1178, 'quran:20:14', 'quran', 'quran', '20:14', 14, 1177, 'Taha', 'طه', 'إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ', NULL, NULL, 'انني انا الله لا اله الا انا فاعبدني واقم الصلاه لذكري', 'انن ان له ل ال ال ان اعبدن اقم صل لذكر', 'quran', NULL, NULL, 'https://quran.com/20/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1178, 'انن نني ان الل لله ل اله ال ان فعب عبد بدن دني وقم الص لصل صله لذك ذكر كري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1179, 'quran:20:15', 'quran', 'quran', '20:15', 15, 1178, 'Taha', 'طه', 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ', NULL, NULL, 'ان الساعه اتيه اكاد اخفيها لتجزي كل نفس بما تسعي', 'ان سع ات اكد اخفي لتجز كل نفس بم تسع', 'quran', NULL, NULL, 'https://quran.com/20/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1179, 'ان الس لسع سعه اتي تيه اكد اخف خفي فيه لتج تجز جزي كل نفس بم تسع سعي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1180, 'quran:20:16', 'quran', 'quran', '20:16', 16, 1179, 'Taha', 'طه', 'فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ', NULL, NULL, 'فلا يصدنك عنها من لا يومن بها واتبع هواه فتردي', 'فل يصدنك عن من ل يومن به اتبع هو ترد', 'quran', NULL, NULL, 'https://quran.com/20/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1180, 'فل يصد صدن دنك عنه من ل يوم ومن به وتب تبع هوه فتر ترد ردي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1181, 'quran:20:17', 'quran', 'quran', '20:17', 17, 1180, 'Taha', 'طه', 'وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ', NULL, NULL, 'وما تلك بيمينك يا موسي', 'وم تلك بيمينك ي موس', 'quran', NULL, NULL, 'https://quran.com/20/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1181, 'وم تلك بيم يمي مين ينك ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1182, 'quran:20:18', 'quran', 'quran', '20:18', 18, 1181, 'Taha', 'طه', 'قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ', NULL, NULL, 'قال هي عصاي اتوكوا عليها واهش بها علي غنمي ولي فيها مارب اخري', 'قل هي عص اتوك علي اهش به عل غنم ول يه مرب اخر', 'quran', NULL, NULL, 'https://quran.com/20/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1182, 'قل هي عصي اتو توك وكو علي ليه وهش به علي غنم نمي ولي فيه مرب اخر خري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1183, 'quran:20:19', 'quran', 'quran', '20:19', 19, 1182, 'Taha', 'طه', 'قَالَ أَلۡقِهَا يَٰمُوسَىٰ', NULL, NULL, 'قال القها يا موسي', 'قل قه ي موس', 'quran', NULL, NULL, 'https://quran.com/20/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1183, 'قل الق لقه ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1184, 'quran:20:20', 'quran', 'quran', '20:20', 20, 1183, 'Taha', 'طه', 'فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ', NULL, NULL, 'فالقاها فاذا هي حيه تسعي', 'ق اذ هي حي تسع', 'quran', NULL, NULL, 'https://quran.com/20/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1184, 'فلق لقه فذ هي حيه تسع سعي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1185, 'quran:20:21', 'quran', 'quran', '20:21', 21, 1184, 'Taha', 'طه', 'قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ', NULL, NULL, 'قال خذها ولا تخف سنعيدها سيرتها الاولي', 'قل خذ ول تخف سنعيد سيرت اول', 'quran', NULL, NULL, 'https://quran.com/20/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1185, 'قل خذه ول تخف سنع نعي عيد يده سير يرت رته الو لول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1186, 'quran:20:22', 'quran', 'quran', '20:22', 22, 1185, 'Taha', 'طه', 'وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ', NULL, NULL, 'واضمم يدك الي جناحك تخرج بيضاء من غير سوء ايه اخري', 'اضمم يدك ال جنحك تخرج بيضء من غير سوء اي اخر', 'quran', NULL, NULL, 'https://quran.com/20/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1186, 'وضم ضمم يدك الي جنح نحك تخر خرج بيض يضء من غير سوء ايه اخر خري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1187, 'quran:20:23', 'quran', 'quran', '20:23', 23, 1186, 'Taha', 'طه', 'لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى', NULL, NULL, 'لنريك من ايتنا الكبري', 'لنريك من ايت كبر', 'quran', NULL, NULL, 'https://quran.com/20/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1187, 'لنر نري ريك من ايت يتن الك لكب كبر بري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1188, 'quran:20:24', 'quran', 'quran', '20:24', 24, 1187, 'Taha', 'طه', 'ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ', NULL, NULL, 'اذهب الي فرعون انه طغي', 'اذهب ال رع ان طغ', 'quran', NULL, NULL, 'https://quran.com/20/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1188, 'اذه ذهب الي فرع رعو عون انه طغي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1189, 'quran:20:25', 'quran', 'quran', '20:25', 25, 1188, 'Taha', 'طه', 'قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي', NULL, NULL, 'قال رب اشرح لي صدري', 'قل رب اشرح لي صدر', 'quran', NULL, NULL, 'https://quran.com/20/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1189, 'قل رب اشر شرح لي صدر دري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1190, 'quran:20:26', 'quran', 'quran', '20:26', 26, 1189, 'Taha', 'طه', 'وَيَسِّرۡ لِيٓ أَمۡرِي', NULL, NULL, 'ويسر لي امري', 'يسر لي امر', 'quran', NULL, NULL, 'https://quran.com/20/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1190, 'ويس يسر لي امر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1191, 'quran:20:27', 'quran', 'quran', '20:27', 27, 1190, 'Taha', 'طه', 'وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي', NULL, NULL, 'واحلل عقده من لساني', 'احلل عقد من لسن', 'quran', NULL, NULL, 'https://quran.com/20/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1191, 'وحل حلل عقد قده من لسن سني');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1192, 'quran:20:28', 'quran', 'quran', '20:28', 28, 1191, 'Taha', 'طه', 'يَفۡقَهُواْ قَوۡلِي', NULL, NULL, 'يفقهوا قولي', 'يفقه قول', 'quran', NULL, NULL, 'https://quran.com/20/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1192, 'يفق فقه قهو قول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1193, 'quran:20:29', 'quran', 'quran', '20:29', 29, 1192, 'Taha', 'طه', 'وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي', NULL, NULL, 'واجعل لي وزيرا من اهلي', 'اجعل لي زير من اهل', 'quran', NULL, NULL, 'https://quran.com/20/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1193, 'وجع جعل لي وزي زير من اهل هلي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1194, 'quran:20:30', 'quran', 'quran', '20:30', 30, 1193, 'Taha', 'طه', 'هَٰرُونَ أَخِي', NULL, NULL, 'هرون اخي', 'هر اخ', 'quran', NULL, NULL, 'https://quran.com/20/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1194, 'هرو رون اخي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1195, 'quran:20:31', 'quran', 'quran', '20:31', 31, 1194, 'Taha', 'طه', 'ٱشۡدُدۡ بِهِۦٓ أَزۡرِي', NULL, NULL, 'اشدد به ازري', 'اشدد به ازر', 'quran', NULL, NULL, 'https://quran.com/20/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1195, 'اشد شدد به ازر زري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1196, 'quran:20:32', 'quran', 'quran', '20:32', 32, 1195, 'Taha', 'طه', 'وَأَشۡرِكۡهُ فِيٓ أَمۡرِي', NULL, NULL, 'واشركه في امري', 'اشرك في امر', 'quran', NULL, NULL, 'https://quran.com/20/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1196, 'وشر شرك ركه في امر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1197, 'quran:20:33', 'quran', 'quran', '20:33', 33, 1196, 'Taha', 'طه', 'كَيۡ نُسَبِّحَكَ كَثِيرٗا', NULL, NULL, 'كي نسبحك كثيرا', 'كي نسبحك كثير', 'quran', NULL, NULL, 'https://quran.com/20/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1197, 'كي نسب سبح بحك كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1198, 'quran:20:34', 'quran', 'quran', '20:34', 34, 1197, 'Taha', 'طه', 'وَنَذۡكُرَكَ كَثِيرًا', NULL, NULL, 'ونذكرك كثيرا', 'نذكرك كثير', 'quran', NULL, NULL, 'https://quran.com/20/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1198, 'ونذ نذك ذكر كرك كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1199, 'quran:20:35', 'quran', 'quran', '20:35', 35, 1198, 'Taha', 'طه', 'إِنَّكَ كُنتَ بِنَا بَصِيرٗا', NULL, NULL, 'انك كنت بنا بصيرا', 'انك كنت بن بصير', 'quran', NULL, NULL, 'https://quran.com/20/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1199, 'انك كنت بن بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1200, 'quran:20:36', 'quran', 'quran', '20:36', 36, 1199, 'Taha', 'طه', 'قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ', NULL, NULL, 'قال قد اوتيت سولك يا موسي', 'قل قد اوتيت سولك ي موس', 'quran', NULL, NULL, 'https://quran.com/20/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1200, 'قل قد اوت وتي تيت سول ولك ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1201, 'quran:20:37', 'quran', 'quran', '20:37', 37, 1200, 'Taha', 'طه', 'وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ', NULL, NULL, 'ولقد مننا عليك مره اخري', 'لقد من عليك مر اخر', 'quran', NULL, NULL, 'https://quran.com/20/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1201, 'ولق لقد منن علي ليك مره اخر خري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1202, 'quran:20:38', 'quran', 'quran', '20:38', 38, 1201, 'Taha', 'طه', 'إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', NULL, NULL, 'اذ اوحينا الي امك ما يوحي', 'اذ اوحي ال امك م يوح', 'quran', NULL, NULL, 'https://quran.com/20/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1202, 'اذ اوح وحي حين الي امك م يوح وحي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1203, 'quran:20:39', 'quran', 'quran', '20:39', 39, 1202, 'Taha', 'طه', 'أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ', NULL, NULL, 'ان اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل ياخذه عدو لي وعدو له والقيت عليك محبه مني ولتصنع علي عيني', 'ان اقذف في تبوت اقذف في يم ليلق يم سحل يخذ عدو لي عدو له قيت عليك محب من لتصنع عل عين', 'quran', NULL, NULL, 'https://quran.com/20/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1203, 'ان اقذ قذف ذفي فيه في الت لتب تبو بوت فقذ قذف ذفي فيه في الي ليم فلي ليل يلق لقه الي ليم بلس لسح سحل يخذ خذه عدو لي وعد عدو له ولق لقي قيت علي ليك محب حبه مني ولت لتص تصن صنع علي عين يني');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1204, 'quran:20:40', 'quran', 'quran', '20:40', 40, 1203, 'Taha', 'طه', 'إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ', NULL, NULL, 'اذ تمشي اختك فتقول هل ادلكم علي من يكفله فرجعنك الي امك كي تقر عينها ولا تحزن وقتلت نفسا فنجينك من الغم وفتنك فتونا فلبثت سنين في اهل مدين ثم جيت علي قدر يا موسي', 'اذ تمش اختك تقول هل ادل عل من يكفل رجعنك ال امك كي تقر عين ول تحزن قتلت نفس نجينك من غم فتنك تو لبثت سن في اهل مد ثم جيت عل قدر ي موس', 'quran', NULL, NULL, 'https://quran.com/20/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1204, 'اذ تمش مشي اخت ختك فتق تقو قول هل ادل دلك لكم علي من يكف كفل فله فرج رجع جعن عنك الي امك كي تقر عين ينه ول تحز حزن وقت قتل تلت نفس فنج نجي جين ينك من الغ لغم وفت فتن تنك فتو تون فلب لبث بثت سني نين في اهل مدي دين ثم جيت علي قدر ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1205, 'quran:20:41', 'quran', 'quran', '20:41', 41, 1204, 'Taha', 'طه', 'وَٱصۡطَنَعۡتُكَ لِنَفۡسِي', NULL, NULL, 'واصطنعتك لنفسي', 'اصطنعتك لنفس', 'quran', NULL, NULL, 'https://quran.com/20/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1205, 'وصط صطن طنع نعت عتك لنف نفس فسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1206, 'quran:20:42', 'quran', 'quran', '20:42', 42, 1205, 'Taha', 'طه', 'ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي', NULL, NULL, 'اذهب انت واخوك بايتي ولا تنيا في ذكري', 'اذهب انت اخوك بيت ول تني في ذكر', 'quran', NULL, NULL, 'https://quran.com/20/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1206, 'اذه ذهب انت وخو خوك بيت يتي ول تني في ذكر كري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1207, 'quran:20:43', 'quran', 'quran', '20:43', 43, 1206, 'Taha', 'طه', 'ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ', NULL, NULL, 'اذهبا الي فرعون انه طغي', 'اذهب ال رع ان طغ', 'quran', NULL, NULL, 'https://quran.com/20/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1207, 'اذه ذهب الي فرع رعو عون انه طغي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1208, 'quran:20:44', 'quran', 'quran', '20:44', 44, 1207, 'Taha', 'طه', 'فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ', NULL, NULL, 'فقولا له قولا لينا لعله يتذكر او يخشي', 'قول له قول لي لعل يتذكر او يخش', 'quran', NULL, NULL, 'https://quran.com/20/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1208, 'فقو قول له قول لين لعل عله يتذ تذك ذكر او يخش خشي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1209, 'quran:20:45', 'quran', 'quran', '20:45', 45, 1208, 'Taha', 'طه', 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ', NULL, NULL, 'قالا ربنا اننا نخاف ان يفرط علينا او ان يطغي', 'قل رب ان نخف ان يفرط علي او ان يطغ', 'quran', NULL, NULL, 'https://quran.com/20/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1209, 'قل ربن انن نخف ان يفر فرط علي لين او ان يطغ طغي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1210, 'quran:20:46', 'quran', 'quran', '20:46', 46, 1209, 'Taha', 'طه', 'قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ', NULL, NULL, 'قال لا تخافا انني معكما اسمع واري', 'قل ل تخف انن معكم اسمع ار', 'quran', NULL, NULL, 'https://quran.com/20/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1210, 'قل ل تخف انن نني معك عكم اسم سمع وري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1211, 'quran:20:47', 'quran', 'quran', '20:47', 47, 1210, 'Taha', 'طه', 'فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ', NULL, NULL, 'فاتياه فقولا انا رسولا ربك فارسل معنا بني اسرءيل ولا تعذبهم قد جينك بايه من ربك والسلم علي من اتبع الهدي', 'اتي قول ان رسول ربك ارسل مع بن اسرءيل ول تعذب قد جينك ب من ربك سلم عل من اتبع هد', 'quran', NULL, NULL, 'https://quran.com/20/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1211, 'فتي تيه فقو قول ان رسو سول ربك فرس رسل معن بني اسر سرء رءي ءيل ول تعذ عذب ذبه بهم قد جين ينك بيه من ربك ولس لسل سلم علي من اتب تبع اله لهد هدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1212, 'quran:20:48', 'quran', 'quran', '20:48', 48, 1211, 'Taha', 'طه', 'إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', NULL, NULL, 'انا قد اوحي الينا ان العذاب علي من كذب وتولي', 'ان قد اوح ين ان عذب عل من كذب تول', 'quran', NULL, NULL, 'https://quran.com/20/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1212, 'ان قد اوح وحي الي لين ان الع لعذ عذب علي من كذب وتو تول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1213, 'quran:20:49', 'quran', 'quran', '20:49', 49, 1212, 'Taha', 'طه', 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', NULL, NULL, 'قال فمن ربكما يا موسي', 'قل فمن ربكم ي موس', 'quran', NULL, NULL, 'https://quran.com/20/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1213, 'قل فمن ربك بكم ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1214, 'quran:20:50', 'quran', 'quran', '20:50', 50, 1213, 'Taha', 'طه', 'قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ', NULL, NULL, 'قال ربنا الذي اعطي كل شيء خلقه ثم هدي', 'قل رب ذي اعط كل شيء خلق ثم هد', 'quran', NULL, NULL, 'https://quran.com/20/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1214, 'قل ربن الذ لذي اعط عطي كل شيء خلق لقه ثم هدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1215, 'quran:20:51', 'quran', 'quran', '20:51', 51, 1214, 'Taha', 'طه', 'قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ', NULL, NULL, 'قال فما بال القرون الاولي', 'قل فم بل قر اول', 'quran', NULL, NULL, 'https://quran.com/20/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1215, 'قل فم بل الق لقر قرو رون الو لول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1216, 'quran:20:52', 'quran', 'quran', '20:52', 52, 1215, 'Taha', 'طه', 'قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى', NULL, NULL, 'قال علمها عند ربي في كتب لا يضل ربي ولا ينسي', 'قل علم عند رب في كتب ل يضل رب ول ينس', 'quran', NULL, NULL, 'https://quran.com/20/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1216, 'قل علم لمه عند ربي في كتب ل يضل ربي ول ينس نسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1217, 'quran:20:53', 'quran', 'quran', '20:53', 53, 1216, 'Taha', 'طه', 'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ', NULL, NULL, 'الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا به ازوجا من نبات شتي', 'ذي جعل لكم ارض مهد سلك لكم يه سبل انزل من سمء مء اخرج به ازوج من نب شت', 'quran', NULL, NULL, 'https://quran.com/20/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1217, 'الذ لذي جعل لكم الر لرض مهد وسل سلك لكم فيه سبل ونز نزل من الس لسم سمء مء فخر خرج رجن به ازو زوج من نبت شتي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1218, 'quran:20:54', 'quran', 'quran', '20:54', 54, 1217, 'Taha', 'طه', 'كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ', NULL, NULL, 'كلوا وارعوا انعمكم ان في ذلك لايت لاولي النهي', 'كل ارع انعم ان في ذلك ليت لول نه', 'quran', NULL, NULL, 'https://quran.com/20/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1218, 'كلو ورع رعو انع نعم عمك مكم ان في ذلك ليت لول ولي الن لنه نهي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1219, 'quran:20:55', 'quran', 'quran', '20:55', 55, 1218, 'Taha', 'طه', 'مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ', NULL, NULL, 'منها خلقنكم وفيها نعيدكم ومنها نخرجكم تاره اخري', 'من خلقن في نعيد من نخرج تر اخر', 'quran', NULL, NULL, 'https://quran.com/20/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1219, 'منه خلق لقن قنك نكم وفي فيه نعي عيد يدك دكم ومن منه نخر خرج رجك جكم تره اخر خري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1220, 'quran:20:56', 'quran', 'quran', '20:56', 56, 1219, 'Taha', 'طه', 'وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', NULL, NULL, 'ولقد ارينه ايتنا كلها فكذب وابي', 'لقد ارين ايت كل كذب اب', 'quran', NULL, NULL, 'https://quran.com/20/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1220, 'ولق لقد اري رين ينه ايت يتن كله فكذ كذب وبي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1221, 'quran:20:57', 'quran', 'quran', '20:57', 57, 1220, 'Taha', 'طه', 'قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ', NULL, NULL, 'قال اجيتنا لتخرجنا من ارضنا بسحرك يا موسي', 'قل اجيت لتخرج من ارض بسحرك ي موس', 'quran', NULL, NULL, 'https://quran.com/20/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1221, 'قل اجي جيت يتن لتخ تخر خرج رجن من ارض رضن بسح سحر حرك ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1222, 'quran:20:58', 'quran', 'quran', '20:58', 58, 1221, 'Taha', 'طه', 'فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى', NULL, NULL, 'فلناتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا انت مكانا سوي', 'لنتينك بسحر مثل اجعل بين بينك موعد ل نخلف نحن ول انت مك سو', 'quran', NULL, NULL, 'https://quran.com/20/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1222, 'فلن لنت نتي تين ينك بسح سحر مثل ثله فجع جعل بين ينن وبي بين ينك موع وعد ل نخل خلف لفه نحن ول انت مكن سوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1223, 'quran:20:59', 'quran', 'quran', '20:59', 59, 1222, 'Taha', 'طه', 'قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى', NULL, NULL, 'قال موعدكم يوم الزينه وان يحشر الناس ضحي', 'قل موعد يوم زين ون يحشر نس ضح', 'quran', NULL, NULL, 'https://quran.com/20/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1223, 'قل موع وعد عدك دكم يوم الز لزي زين ينه ون يحش حشر الن لنس ضحي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1224, 'quran:20:60', 'quran', 'quran', '20:60', 60, 1223, 'Taha', 'طه', 'فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ', NULL, NULL, 'فتولي فرعون فجمع كيده ثم اتي', 'تول رع جمع كيد ثم ات', 'quran', NULL, NULL, 'https://quran.com/20/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1224, 'فتو تول ولي فرع رعو عون فجم جمع كيد يده ثم اتي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1225, 'quran:20:61', 'quran', 'quran', '20:61', 61, 1224, 'Taha', 'طه', 'قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ', NULL, NULL, 'قال لهم موسي ويلكم لا تفتروا علي الله كذبا فيسحتكم بعذاب وقد خاب من افتري', 'قل لهم موس يل ل تفتر عل له كذب يسحت بعذب وقد خب من افتر', 'quran', NULL, NULL, 'https://quran.com/20/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1225, 'قل لهم موس وسي ويل يلك لكم ل تفت فتر ترو علي الل لله كذب فيس يسح سحت حتك تكم بعذ عذب وقد خب من افت فتر تري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1226, 'quran:20:62', 'quran', 'quran', '20:62', 62, 1225, 'Taha', 'طه', 'فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ', NULL, NULL, 'فتنزعوا امرهم بينهم واسروا النجوي', 'تنزع امر بين اسر نجو', 'quran', NULL, NULL, 'https://quran.com/20/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1226, 'فتن تنز نزع زعو امر مره رهم بين ينه نهم وسر سرو الن لنج نجو جوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1227, 'quran:20:63', 'quran', 'quran', '20:63', 63, 1226, 'Taha', 'طه', 'قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ', NULL, NULL, 'قالوا ان هذن لسحرن يريدان ان يخرجاكم من ارضكم بسحرهما ويذهبا بطريقتكم المثلي', 'قل ان هذن لسحرن يريد ان يخرج من ارض بسحرهم يذهب بطريقت مثل', 'quran', NULL, NULL, 'https://quran.com/20/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1227, 'قلو ان هذن لسح سحر حرن يري ريد يدن ان يخر خرج رجك جكم من ارض رضك ضكم بسح سحر حره رهم ويذ يذه ذهب بطر طري ريق يقت قتك تكم الم لمث مثل ثلي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1228, 'quran:20:64', 'quran', 'quran', '20:64', 64, 1227, 'Taha', 'طه', 'فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ', NULL, NULL, 'فاجمعوا كيدكم ثم ايتوا صفا وقد افلح اليوم من استعلي', 'اجمع كيد ثم ايت صف وقد افلح يوم من استعل', 'quran', NULL, NULL, 'https://quran.com/20/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1228, 'فجم جمع معو كيد يدك دكم ثم ايت يتو صف وقد افل فلح الي ليو يوم من است ستع تعل علي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1229, 'quran:20:65', 'quran', 'quran', '20:65', 65, 1228, 'Taha', 'طه', 'قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ', NULL, NULL, 'قالوا يا موسي اما ان تلقي واما ان نكون اول من القي', 'قل ي موس ام ان تلق ام ان نك اول من قي', 'quran', NULL, NULL, 'https://quran.com/20/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1229, 'قلو ي موس وسي ام ان تلق لقي وم ان نكو كون اول من الق لقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1230, 'quran:20:66', 'quran', 'quran', '20:66', 66, 1229, 'Taha', 'طه', 'قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ', NULL, NULL, 'قال بل القوا فاذا حبالهم وعصيهم يخيل اليه من سحرهم انها تسعي', 'قل بل قو اذ حبل عصي يخيل يه من سحر ان تسع', 'quran', NULL, NULL, 'https://quran.com/20/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1230, 'قل بل الق لقو فذ حبل بله لهم وعص عصي صيه يهم يخي خيل الي ليه من سحر حره رهم انه تسع سعي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1231, 'quran:20:67', 'quran', 'quran', '20:67', 67, 1230, 'Taha', 'طه', 'فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ', NULL, NULL, 'فاوجس في نفسه خيفه موسي', 'اوجس في نفس خيف موس', 'quran', NULL, NULL, 'https://quran.com/20/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1231, 'فوج وجس في نفس فسه خيف يفه موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1232, 'quran:20:68', 'quran', 'quran', '20:68', 68, 1231, 'Taha', 'طه', 'قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ', NULL, NULL, 'قلنا لا تخف انك انت الاعلي', 'قل ل تخف انك انت اعل', 'quran', NULL, NULL, 'https://quran.com/20/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1232, 'قلن ل تخف انك انت الع لعل علي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1233, 'quran:20:69', 'quran', 'quran', '20:69', 69, 1232, 'Taha', 'طه', 'وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ', NULL, NULL, 'والق ما في يمينك تلقف ما صنعوا انما صنعوا كيد سحر ولا يفلح الساحر حيث اتي', 'ولق م في يمينك تلقف م صنع انم صنع كيد سحر ول يفلح سحر حيث ات', 'quran', NULL, NULL, 'https://quran.com/20/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1233, 'ولق م في يمي مين ينك تلق لقف م صنع نعو انم صنع نعو كيد سحر ول يفل فلح الس لسح سحر حيث اتي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1234, 'quran:20:70', 'quran', 'quran', '20:70', 70, 1233, 'Taha', 'طه', 'فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', NULL, NULL, 'فالقي السحره سجدا قالوا امنا برب هرون وموسي', 'قي سحر سجد قل ام برب هر موس', 'quran', NULL, NULL, 'https://quran.com/20/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1234, 'فلق لقي الس لسح سحر حره سجد قلو امن برب هرو رون ومو موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1235, 'quran:20:71', 'quran', 'quran', '20:71', 71, 1234, 'Taha', 'طه', 'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ', NULL, NULL, 'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلاقطعن ايديكم وارجلكم من خلف ولاصلبنكم في جذوع النخل ولتعلمن اينا اشد عذابا وابقي', 'قل امنتم له قبل ان اذن لكم ان لكبير ذي علم سحر لقطعن ايدي ارجل من خلف لصلبن في جذوع نخل لتعلمن اي اشد عذب ابق', 'quran', NULL, NULL, 'https://quran.com/20/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1235, 'قل امن منت نتم له قبل ان اذن لكم انه لكب كبي بير يرك ركم الذ لذي علم لمك مكم الس لسح سحر فلق لقط قطع طعن ايد يدي ديك يكم ورج رجل جلك لكم من خلف ولص لصل صلب لبن بنك نكم في جذو ذوع الن لنخ نخل ولت لتع تعل علم لمن اين اشد عذب وبق بقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1236, 'quran:20:72', 'quran', 'quran', '20:72', 72, 1235, 'Taha', 'طه', 'قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ', NULL, NULL, 'قالوا لن نوثرك علي ما جاءنا من البينت والذي فطرنا فاقض ما انت قاض انما تقضي هذه الحياه الدنيا', 'قل لن نوثرك عل م جء من بينت ذي طر اقض م انت قض انم تقض هذ حي دني', 'quran', NULL, NULL, 'https://quran.com/20/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1236, 'قلو لن نوث وثر ثرك علي م جءن من الب لبي بين ينت ولذ لذي فطر طرن فقض م انت قض انم تقض قضي هذه الح لحي حيه الد لدن دني');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1237, 'quran:20:73', 'quran', 'quran', '20:73', 73, 1236, 'Taha', 'طه', 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ', NULL, NULL, 'انا امنا بربنا ليغفر لنا خطينا وما اكرهتنا عليه من السحر والله خير وابقي', 'ان ام برب ليغفر لن خطي وم اكرهت عل من سحر له خير ابق', 'quran', NULL, NULL, 'https://quran.com/20/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1237, 'ان امن برب ربن ليغ يغف غفر لن خطي طين وم اكر كره رهت هتن علي ليه من الس لسح سحر ولل لله خير وبق بقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1238, 'quran:20:74', 'quran', 'quran', '20:74', 74, 1237, 'Taha', 'طه', 'إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ', NULL, NULL, 'انه من يات ربه مجرما فان له جهنم لا يموت فيها ولا يحيي', 'ان من يت رب مجرم فن له جهنم ل يموت يه ول يحي', 'quran', NULL, NULL, 'https://quran.com/20/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1238, 'انه من يت ربه مجر جرم فن له جهن هنم ل يمو موت فيه ول يحي حيي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1239, 'quran:20:75', 'quran', 'quran', '20:75', 75, 1238, 'Taha', 'طه', 'وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ', NULL, NULL, 'ومن ياته مومنا قد عمل الصلحت فاوليك لهم الدرجت العلي', 'ومن يت موم قد عمل صلحت اوليك لهم درجت عل', 'quran', NULL, NULL, 'https://quran.com/20/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1239, 'ومن يته موم ومن قد عمل الص لصل صلح لحت فول ولي ليك لهم الد لدر درج رجت الع لعل علي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1240, 'quran:20:76', 'quran', 'quran', '20:76', 76, 1239, 'Taha', 'طه', 'جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', NULL, NULL, 'جنت عدن تجري من تحتها الانهر خلدين فيها وذلك جزاء من تزكي', 'جنت عدن تجر من تحت انهر خلد يه ذلك جزء من تزك', 'quran', NULL, NULL, 'https://quran.com/20/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1240, 'جنت عدن تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه وذل ذلك جزء من تزك زكي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1241, 'quran:20:77', 'quran', 'quran', '20:77', 77, 1240, 'Taha', 'طه', 'وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ', NULL, NULL, 'ولقد اوحينا الي موسي ان اسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخف دركا ولا تخشي', 'لقد اوحي ال موس ان اسر بعبد اضرب لهم طريق في بحر يبس ل تخف درك ول تخش', 'quran', NULL, NULL, 'https://quran.com/20/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1241, 'ولق لقد اوح وحي حين الي موس وسي ان اسر بعب عبد بدي فضر ضرب لهم طري ريق في الب لبح بحر يبس ل تخف درك ول تخش خشي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1242, 'quran:20:78', 'quran', 'quran', '20:78', 78, 1241, 'Taha', 'طه', 'فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ', NULL, NULL, 'فاتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم', 'اتبع رع بجنود غشي من يم م غشي', 'quran', NULL, NULL, 'https://quran.com/20/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1242, 'فتب تبع بعه عهم فرع رعو عون بجن جنو نود وده فغش غشي شيه يهم من الي ليم م غشي شيه يهم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1243, 'quran:20:79', 'quran', 'quran', '20:79', 79, 1242, 'Taha', 'طه', 'وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ', NULL, NULL, 'واضل فرعون قومه وما هدي', 'اضل رع قوم وم هد', 'quran', NULL, NULL, 'https://quran.com/20/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1243, 'وضل فرع رعو عون قوم ومه وم هدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1244, 'quran:20:80', 'quran', 'quran', '20:80', 80, 1243, 'Taha', 'طه', 'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ', NULL, NULL, 'يا بني اسرءيل قد انجينكم من عدوكم ووعدنكم جانب الطور الايمن ونزلنا عليكم المن والسلوي', 'ي بن اسرءيل قد انجين من عدو وعدن جنب طور ايمن نزل علي من سلو', 'quran', NULL, NULL, 'https://quran.com/20/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1244, 'ي بني اسر سرء رءي ءيل قد انج نجي جين ينك نكم من عدو دوك وكم ووع وعد عدن دنك نكم جنب الط لطو طور الي ليم يمن ونز نزل زلن علي ليك يكم الم لمن ولس لسل سلو لوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1245, 'quran:20:81', 'quran', 'quran', '20:81', 81, 1244, 'Taha', 'طه', 'كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ', NULL, NULL, 'كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوي', 'كل من طيبت م رزقن ول تطغ في يحل علي غضب ومن يحلل عل غضب فقد هو', 'quran', NULL, NULL, 'https://quran.com/20/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1245, 'كلو من طيب يبت م رزق زقن قنك نكم ول تطغ طغو فيه فيح يحل علي ليك يكم غضب ضبي ومن يحل حلل علي ليه غضب ضبي فقد هوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1246, 'quran:20:82', 'quran', 'quran', '20:82', 82, 1245, 'Taha', 'طه', 'وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ', NULL, NULL, 'واني لغفار لمن تاب وامن وعمل صلحا ثم اهتدي', 'ان لغفر لمن تب امن عمل صلح ثم اهتد', 'quran', NULL, NULL, 'https://quran.com/20/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1246, 'وني لغف غفر لمن تب ومن وعم عمل صلح ثم اهت هتد تدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1247, 'quran:20:83', 'quran', 'quran', '20:83', 83, 1246, 'Taha', 'طه', 'وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ', NULL, NULL, 'وما اعجلك عن قومك يا موسي', 'وم اعجلك عن قومك ي موس', 'quran', NULL, NULL, 'https://quran.com/20/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1247, 'وم اعج عجل جلك عن قوم ومك ي موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1248, 'quran:20:84', 'quran', 'quran', '20:84', 84, 1247, 'Taha', 'طه', 'قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ', NULL, NULL, 'قال هم اولاء علي اثري وعجلت اليك رب لترضي', 'قل هم اولء عل اثر عجلت يك رب لترض', 'quran', NULL, NULL, 'https://quran.com/20/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1248, 'قل هم اول ولء علي اثر ثري وعج عجل جلت الي ليك رب لتر ترض رضي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1249, 'quran:20:85', 'quran', 'quran', '20:85', 85, 1248, 'Taha', 'طه', 'قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ', NULL, NULL, 'قال فانا قد فتنا قومك من بعدك واضلهم السامري', 'قل ان قد تن قومك من بعدك اضل سمر', 'quran', NULL, NULL, 'https://quran.com/20/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1249, 'قل فن قد فتن قوم ومك من بعد عدك وضل ضله لهم الس لسم سمر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1250, 'quran:20:86', 'quran', 'quran', '20:86', 86, 1249, 'Taha', 'طه', 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي', NULL, NULL, 'فرجع موسي الي قومه غضبن اسفا قال يا قوم الم يعدكم ربكم وعدا حسنا افطال عليكم العهد ام اردتم ان يحل عليكم غضب من ربكم فاخلفتم موعدي', 'رجع موس ال قوم غضبن اسف قل ي قوم الم يعد رب عد حس افطل علي عهد ام اردتم ان يحل علي غضب من رب اخلفتم موعد', 'quran', NULL, NULL, 'https://quran.com/20/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1250, 'فرج رجع موس وسي الي قوم ومه غضب ضبن اسف قل ي قوم الم يعد عدك دكم ربك بكم وعد حسن افط فطل علي ليك يكم الع لعه عهد ام ارد ردت دتم ان يحل علي ليك يكم غضب من ربك بكم فخل خلف لفت فتم موع وعد عدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1251, 'quran:20:87', 'quran', 'quran', '20:87', 87, 1250, 'Taha', 'طه', 'قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ', NULL, NULL, 'قالوا ما اخلفنا موعدك بملكنا ولكنا حملنا اوزارا من زينه القوم فقذفنها فكذلك القي السامري', 'قل م اخلف موعدك بملك لك حمل اوزر من زين قوم قذفن كذلك قي سمر', 'quran', NULL, NULL, 'https://quran.com/20/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1251, 'قلو م اخل خلف لفن موع وعد عدك بمل ملك لكن ولك لكن حمل ملن اوز وزر من زين ينه الق لقو قوم فقذ قذف ذفن فنه فكذ كذل ذلك الق لقي الس لسم سمر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1252, 'quran:20:88', 'quran', 'quran', '20:88', 88, 1251, 'Taha', 'طه', 'فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ', NULL, NULL, 'فاخرج لهم عجلا جسدا له خوار فقالوا هذا الهكم واله موسي فنسي', 'اخرج لهم عجل جسد له خور قل هذ هكم ول موس نس', 'quran', NULL, NULL, 'https://quran.com/20/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1252, 'فخر خرج لهم عجل جسد له خور فقل قلو هذ اله لهك هكم وله موس وسي فنس نسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1253, 'quran:20:89', 'quran', 'quran', '20:89', 89, 1252, 'Taha', 'طه', 'أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا', NULL, NULL, 'افلا يرون الا يرجع اليهم قولا ولا يملك لهم ضرا ولا نفعا', 'افل ير ال يرجع يهم قول ول يملك لهم ضر ول نفع', 'quran', NULL, NULL, 'https://quran.com/20/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1253, 'افل يرو رون ال يرج رجع الي ليه يهم قول ول يمل ملك لهم ضر ول نفع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1254, 'quran:20:90', 'quran', 'quran', '20:90', 90, 1253, 'Taha', 'طه', 'وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي', NULL, NULL, 'ولقد قال لهم هرون من قبل يا قوم انما فتنتم به وان ربكم الرحمن فاتبعوني واطيعوا امري', 'لقد قل لهم هر من قبل ي قوم انم تنتم به ون رب رحمن اتبعون اطيع امر', 'quran', NULL, NULL, 'https://quran.com/20/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1254, 'ولق لقد قل لهم هرو رون من قبل ي قوم انم فتن تنت نتم به ون ربك بكم الر لرح رحم حمن فتب تبع بعو عون وني وطي طيع يعو امر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1255, 'quran:20:91', 'quran', 'quran', '20:91', 91, 1254, 'Taha', 'طه', 'قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ', NULL, NULL, 'قالوا لن نبرح عليه عكفين حتي يرجع الينا موسي', 'قل لن نبرح عل عكف حت يرجع ين موس', 'quran', NULL, NULL, 'https://quran.com/20/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1255, 'قلو لن نبر برح علي ليه عكف كفي فين حتي يرج رجع الي لين موس وسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1256, 'quran:20:92', 'quran', 'quran', '20:92', 92, 1255, 'Taha', 'طه', 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ', NULL, NULL, 'قال يا هرون ما منعك اذ رايتهم ضلوا', 'قل ي هر م منعك اذ ريت ضل', 'quran', NULL, NULL, 'https://quran.com/20/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1256, 'قل ي هرو رون م منع نعك اذ ريت يته تهم ضلو');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1257, 'quran:20:93', 'quran', 'quran', '20:93', 93, 1256, 'Taha', 'طه', 'أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي', NULL, NULL, 'الا تتبعن افعصيت امري', 'ال تتبعن افعصيت امر', 'quran', NULL, NULL, 'https://quran.com/20/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1257, 'ال تتب تبع بعن افع فعص عصي صيت امر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1258, 'quran:20:94', 'quran', 'quran', '20:94', 94, 1257, 'Taha', 'طه', 'قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي', NULL, NULL, 'قال يبنوم لا تاخذ بلحيتي ولا براسي اني خشيت ان تقول فرقت بين بني اسرءيل ولم ترقب قولي', 'قل يبنوم ل تخذ بلحيت ول برس ان خشيت ان تقول رقت بين بن اسرءيل ولم ترقب قول', 'quran', NULL, NULL, 'https://quran.com/20/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1258, 'قل يبن بنو نوم ل تخذ بلح لحي حيت يتي ول برس رسي اني خشي شيت ان تقو قول فرق رقت بين بني اسر سرء رءي ءيل ولم ترق رقب قول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1259, 'quran:20:95', 'quran', 'quran', '20:95', 95, 1258, 'Taha', 'طه', 'قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ', NULL, NULL, 'قال فما خطبك يا سمري', 'قل فم خطبك ي سمر', 'quran', NULL, NULL, 'https://quran.com/20/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1259, 'قل فم خطب طبك ي سمر مري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1260, 'quran:20:96', 'quran', 'quran', '20:96', 96, 1259, 'Taha', 'طه', 'قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي', NULL, NULL, 'قال بصرت بما لم يبصروا به فقبضت قبضه من اثر الرسول فنبذتها وكذلك سولت لي نفسي', 'قل بصرت بم لم يبصر به قبضت قبض من اثر رسول نبذت كذلك سولت لي نفس', 'quran', NULL, NULL, 'https://quran.com/20/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1260, 'قل بصر صرت بم لم يبص بصر صرو به فقب قبض بضت قبض بضه من اثر الر لرس رسو سول فنب نبذ بذت ذته وكذ كذل ذلك سول ولت لي نفس فسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1261, 'quran:20:97', 'quran', 'quran', '20:97', 97, 1260, 'Taha', 'طه', 'قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا', NULL, NULL, 'قال فاذهب فان لك في الحياه ان تقول لا مساس وان لك موعدا لن تخلفه وانظر الي الهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا', 'قل اذهب فن لك في حي ان تقول ل مسس ون لك موعد لن تخلف انظر ال هك ذي ظلت عل عكف لنحرقن ثم لننسفن في يم نسف', 'quran', NULL, NULL, 'https://quran.com/20/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1261, 'قل فذه ذهب فن لك في الح لحي حيه ان تقو قول ل مسس ون لك موع وعد لن تخل خلف لفه ونظ نظر الي اله لهك الذ لذي ظلت علي ليه عكف لنح نحر حرق رقن قنه ثم لنن ننس نسف سفن فنه في الي ليم نسف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1262, 'quran:20:98', 'quran', 'quran', '20:98', 98, 1261, 'Taha', 'طه', 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا', NULL, NULL, 'انما الهكم الله الذي لا اله الا هو وسع كل شيء علما', 'انم هكم له ذي ل ال ال هو وسع كل شيء علم', 'quran', NULL, NULL, 'https://quran.com/20/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1262, 'انم اله لهك هكم الل لله الذ لذي ل اله ال هو وسع كل شيء علم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1263, 'quran:20:99', 'quran', 'quran', '20:99', 99, 1262, 'Taha', 'طه', 'كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا', NULL, NULL, 'كذلك نقص عليك من انباء ما قد سبق وقد اتينك من لدنا ذكرا', 'كذلك نقص عليك من انبء م قد سبق وقد اتينك من لد ذكر', 'quran', NULL, NULL, 'https://quran.com/20/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1263, 'كذل ذلك نقص علي ليك من انب نبء م قد سبق وقد اتي تين ينك من لدن ذكر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1264, 'quran:20:100', 'quran', 'quran', '20:100', 100, 1263, 'Taha', 'طه', 'مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا', NULL, NULL, 'من اعرض عنه فانه يحمل يوم القيمه وزرا', 'من اعرض عن ان يحمل يوم قيم زر', 'quran', NULL, NULL, 'https://quran.com/20/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1264, 'من اعر عرض عنه فنه يحم حمل يوم الق لقي قيم يمه وزر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1265, 'quran:20:101', 'quran', 'quran', '20:101', 101, 1264, 'Taha', 'طه', 'خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا', NULL, NULL, 'خلدين فيه وساء لهم يوم القيمه حملا', 'خلد في سء لهم يوم قيم حمل', 'quran', NULL, NULL, 'https://quran.com/20/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1265, 'خلد لدي دين فيه وسء لهم يوم الق لقي قيم يمه حمل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1266, 'quran:20:102', 'quran', 'quran', '20:102', 102, 1265, 'Taha', 'طه', 'يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا', NULL, NULL, 'يوم ينفخ في الصور ونحشر المجرمين يوميذ زرقا', 'يوم ينفخ في صور نحشر مجرم يوميذ زرق', 'quran', NULL, NULL, 'https://quran.com/20/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1266, 'يوم ينف نفخ في الص لصو صور ونح نحش حشر الم لمج مجر جرم رمي مين يوم ومي ميذ زرق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1267, 'quran:20:103', 'quran', 'quran', '20:103', 103, 1266, 'Taha', 'طه', 'يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا', NULL, NULL, 'يتخفتون بينهم ان لبثتم الا عشرا', 'يتخفت بين ان لبثتم ال عشر', 'quran', NULL, NULL, 'https://quran.com/20/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1267, 'يتخ تخف خفت فتو تون بين ينه نهم ان لبث بثت ثتم ال عشر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1268, 'quran:20:104', 'quran', 'quran', '20:104', 104, 1267, 'Taha', 'طه', 'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا', NULL, NULL, 'نحن اعلم بما يقولون اذ يقول امثلهم طريقه ان لبثتم الا يوما', 'نحن اعلم بم يقول اذ يقول امثل طريق ان لبثتم ال يوم', 'quran', NULL, NULL, 'https://quran.com/20/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1268, 'نحن اعل علم بم يقو قول ولو لون اذ يقو قول امث مثل ثله لهم طري ريق يقه ان لبث بثت ثتم ال يوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1269, 'quran:20:105', 'quran', 'quran', '20:105', 105, 1268, 'Taha', 'طه', 'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا', NULL, NULL, 'ويسلونك عن الجبال فقل ينسفها ربي نسفا', 'يسلونك عن جبل فقل ينسف رب نسف', 'quran', NULL, NULL, 'https://quran.com/20/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1269, 'ويس يسل سلو لون ونك عن الج لجب جبل فقل ينس نسف سفه ربي نسف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1270, 'quran:20:106', 'quran', 'quran', '20:106', 106, 1269, 'Taha', 'طه', 'فَيَذَرُهَا قَاعٗا صَفۡصَفٗا', NULL, NULL, 'فيذرها قاعا صفصفا', 'يذر قع صفصف', 'quran', NULL, NULL, 'https://quran.com/20/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1270, 'فيذ يذر ذره قع صفص فصف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1271, 'quran:20:107', 'quran', 'quran', '20:107', 107, 1270, 'Taha', 'طه', 'لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا', NULL, NULL, 'لا تري فيها عوجا ولا امتا', 'ل تر يه عوج ول امت', 'quran', NULL, NULL, 'https://quran.com/20/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1271, 'ل تري فيه عوج ول امت');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1272, 'quran:20:108', 'quran', 'quran', '20:108', 108, 1271, 'Taha', 'طه', 'يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا', NULL, NULL, 'يوميذ يتبعون الداعي لا عوج له وخشعت الاصوات للرحمن فلا تسمع الا همسا', 'يوميذ يتبع دع ل عوج له خشعت اصو رحمن فل تسمع ال همس', 'quran', NULL, NULL, 'https://quran.com/20/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1272, 'يوم ومي ميذ يتب تبع بعو عون الد لدع دعي ل عوج له وخش خشع شعت الص لصو صوت للر لرح رحم حمن فل تسم سمع ال همس');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1273, 'quran:20:109', 'quran', 'quran', '20:109', 109, 1272, 'Taha', 'طه', 'يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا', NULL, NULL, 'يوميذ لا تنفع الشفعه الا من اذن له الرحمن ورضي له قولا', 'يوميذ ل تنفع شفع ال من اذن له رحمن رض له قول', 'quran', NULL, NULL, 'https://quran.com/20/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1273, 'يوم ومي ميذ ل تنف نفع الش لشف شفع فعه ال من اذن له الر لرح رحم حمن ورض رضي له قول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1274, 'quran:20:110', 'quran', 'quran', '20:110', 110, 1273, 'Taha', 'طه', 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا', NULL, NULL, 'يعلم ما بين ايديهم وما خلفهم ولا يحيطون به علما', 'يعلم م بين ايدي وم خلف ول يحيط به علم', 'quran', NULL, NULL, 'https://quran.com/20/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1274, 'يعل علم م بين ايد يدي ديه يهم وم خلف لفه فهم ول يحي حيط يطو طون به علم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1275, 'quran:20:111', 'quran', 'quran', '20:111', 111, 1274, 'Taha', 'طه', 'وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا', NULL, NULL, 'وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما', 'عنت وجو حي قيوم وقد خب من حمل ظلم', 'quran', NULL, NULL, 'https://quran.com/20/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1275, 'وعن عنت الو لوج وجو جوه للح لحي الق لقي قيو يوم وقد خب من حمل ظلم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1276, 'quran:20:112', 'quran', 'quran', '20:112', 112, 1275, 'Taha', 'طه', 'وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا', NULL, NULL, 'ومن يعمل من الصلحت وهو مومن فلا يخاف ظلما ولا هضما', 'ومن يعمل من صلحت وهو مومن فل يخف ظلم ول هضم', 'quran', NULL, NULL, 'https://quran.com/20/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1276, 'ومن يعم عمل من الص لصل صلح لحت وهو موم ومن فل يخف ظلم ول هضم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1277, 'quran:20:113', 'quran', 'quran', '20:113', 113, 1276, 'Taha', 'طه', 'وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا', NULL, NULL, 'وكذلك انزلنه قرانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون او يحدث لهم ذكرا', 'كذلك انزلن قر عربي صرف في من وعيد لعل يتق او يحدث لهم ذكر', 'quran', NULL, NULL, 'https://quran.com/20/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1277, 'وكذ كذل ذلك انز نزل زلن لنه قرن عرب ربي وصر صرف رفن فيه من الو لوع وعي عيد لعل عله لهم يتق تقو قون او يحد حدث لهم ذكر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1278, 'quran:20:114', 'quran', 'quran', '20:114', 114, 1277, 'Taha', 'طه', 'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا', NULL, NULL, 'فتعلي الله الملك الحق ولا تعجل بالقران من قبل ان يقضي اليك وحيه وقل رب زدني علما', 'تعل له ملك حق ول تعجل قر من قبل ان يقض يك حي وقل رب زدن علم', 'quran', NULL, NULL, 'https://quran.com/20/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1278, 'فتع تعل علي الل لله الم لمل ملك الح لحق ول تعج عجل بلق لقر قرن من قبل ان يقض قضي الي ليك وحي حيه وقل رب زدن دني علم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1279, 'quran:20:115', 'quran', 'quran', '20:115', 115, 1278, 'Taha', 'طه', 'وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا', NULL, NULL, 'ولقد عهدنا الي ادم من قبل فنسي ولم نجد له عزما', 'لقد عهد ال ادم من قبل نس ولم نجد له عزم', 'quran', NULL, NULL, 'https://quran.com/20/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1279, 'ولق لقد عهد هدن الي ادم من قبل فنس نسي ولم نجد له عزم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1280, 'quran:20:116', 'quran', 'quran', '20:116', 116, 1279, 'Taha', 'طه', 'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ', NULL, NULL, 'واذ قلنا للمليكه اسجدوا لادم فسجدوا الا ابليس ابي', 'وذ قل مليك اسجد لدم سجد ال ابليس اب', 'quran', NULL, NULL, 'https://quran.com/20/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1280, 'وذ قلن للم لمل ملي ليك يكه اسج سجد جدو لدم فسج سجد جدو ال ابل بلي ليس ابي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1281, 'quran:20:117', 'quran', 'quran', '20:117', 117, 1280, 'Taha', 'طه', 'فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ', NULL, NULL, 'فقلنا يا ادم ان هذا عدو لك ولزوجك فلا يخرجنكما من الجنه فتشقي', 'قل ي ادم ان هذ عدو لك لزوجك فل يخرجنكم من جن تشق', 'quran', NULL, NULL, 'https://quran.com/20/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1281, 'فقل قلن ي ادم ان هذ عدو لك ولز لزو زوج وجك فل يخر خرج رجن جنك نكم من الج لجن جنه فتش تشق شقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1282, 'quran:20:118', 'quran', 'quran', '20:118', 118, 1281, 'Taha', 'طه', 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ', NULL, NULL, 'ان لك الا تجوع فيها ولا تعري', 'ان لك ال تجوع يه ول تعر', 'quran', NULL, NULL, 'https://quran.com/20/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1282, 'ان لك ال تجو جوع فيه ول تعر عري');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1283, 'quran:20:119', 'quran', 'quran', '20:119', 119, 1282, 'Taha', 'طه', 'وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ', NULL, NULL, 'وانك لا تظموا فيها ولا تضحي', 'انك ل تظم يه ول تضح', 'quran', NULL, NULL, 'https://quran.com/20/119');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1283, 'ونك ل تظم ظمو فيه ول تضح ضحي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1284, 'quran:20:120', 'quran', 'quran', '20:120', 120, 1283, 'Taha', 'طه', 'فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ', NULL, NULL, 'فوسوس اليه الشيطن قال يا ادم هل ادلك علي شجره الخلد وملك لا يبلي', 'وسوس يه شيطن قل ي ادم هل ادلك عل شجر خلد ملك ل يبل', 'quran', NULL, NULL, 'https://quran.com/20/120');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1284, 'فوس وسو سوس الي ليه الش لشي شيط يطن قل ي ادم هل ادل دلك علي شجر جره الخ لخل خلد ومل ملك ل يبل بلي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1285, 'quran:20:121', 'quran', 'quran', '20:121', 121, 1284, 'Taha', 'طه', 'فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', NULL, NULL, 'فاكلا منها فبدت لهما سوءتهما وطفقا يخصفان عليهما من ورق الجنه وعصي ادم ربه فغوي', 'اكل من بدت لهم سوءتهم طفق يخصف عليهم من ورق جن عص ادم رب غو', 'quran', NULL, NULL, 'https://quran.com/20/121');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1285, 'فكل منه فبد بدت لهم سوء وءت ءته تهم وطف طفق يخص خصف صفن علي ليه يهم من ورق الج لجن جنه وعص عصي ادم ربه فغو غوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1286, 'quran:20:122', 'quran', 'quran', '20:122', 122, 1285, 'Taha', 'طه', 'ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ', NULL, NULL, 'ثم اجتبه ربه فتاب عليه وهدي', 'ثم اجتب رب تب عل هد', 'quran', NULL, NULL, 'https://quran.com/20/122');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1286, 'ثم اجت جتب تبه ربه فتب علي ليه وهد هدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1287, 'quran:20:123', 'quran', 'quran', '20:123', 123, 1286, 'Taha', 'طه', 'قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ', NULL, NULL, 'قال اهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم مني هدي فمن اتبع هداي فلا يضل ولا يشقي', 'قل اهبط من جميع بعض لبعض عدو ام يتين من هد فمن اتبع هد فل يضل ول يشق', 'quran', NULL, NULL, 'https://quran.com/20/123');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1287, 'قل اهب هبط منه جمي ميع بعض عضك ضكم لبع بعض عدو فم يتي تين ينك نكم مني هدي فمن اتب تبع هدي فل يضل ول يشق شقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1288, 'quran:20:124', 'quran', 'quran', '20:124', 124, 1287, 'Taha', 'طه', 'وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ', NULL, NULL, 'ومن اعرض عن ذكري فان له معيشه ضنكا ونحشره يوم القيمه اعمي', 'ومن اعرض عن ذكر فن له معيش ضنك نحشر يوم قيم اعم', 'quran', NULL, NULL, 'https://quran.com/20/124');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1288, 'ومن اعر عرض عن ذكر كري فن له معي عيش يشه ضنك ونح نحش حشر شره يوم الق لقي قيم يمه اعم عمي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1289, 'quran:20:125', 'quran', 'quran', '20:125', 125, 1288, 'Taha', 'طه', 'قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا', NULL, NULL, 'قال رب لم حشرتني اعمي وقد كنت بصيرا', 'قل رب لم حشرتن اعم وقد كنت بصير', 'quran', NULL, NULL, 'https://quran.com/20/125');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1289, 'قل رب لم حشر شرت رتن تني اعم عمي وقد كنت بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1290, 'quran:20:126', 'quran', 'quran', '20:126', 126, 1289, 'Taha', 'طه', 'قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ', NULL, NULL, 'قال كذلك اتتك ايتنا فنسيتها وكذلك اليوم تنسي', 'قل كذلك اتتك ايت نسيت كذلك يوم تنس', 'quran', NULL, NULL, 'https://quran.com/20/126');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1290, 'قل كذل ذلك اتت تتك ايت يتن فنس نسي سيت يته وكذ كذل ذلك الي ليو يوم تنس نسي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1291, 'quran:20:127', 'quran', 'quran', '20:127', 127, 1290, 'Taha', 'طه', 'وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ', NULL, NULL, 'وكذلك نجزي من اسرف ولم يومن بايت ربه ولعذاب الاخره اشد وابقي', 'كذلك نجز من اسرف ولم يومن بيت رب لعذب اخر اشد ابق', 'quran', NULL, NULL, 'https://quran.com/20/127');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1291, 'وكذ كذل ذلك نجز جزي من اسر سرف ولم يوم ومن بيت ربه ولع لعذ عذب الخ لخر خره اشد وبق بقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1292, 'quran:20:128', 'quran', 'quran', '20:128', 128, 1291, 'Taha', 'طه', 'أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ', NULL, NULL, 'افلم يهد لهم كم اهلكنا قبلهم من القرون يمشون في مسكنهم ان في ذلك لايت لاولي النهي', 'افلم يهد لهم كم اهلك قبل من قر يمش في مسكن ان في ذلك ليت لول نه', 'quran', NULL, NULL, 'https://quran.com/20/128');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1292, 'افل فلم يهد لهم كم اهل هلك لكن قبل بله لهم من الق لقر قرو رون يمش مشو شون في مسك سكن كنه نهم ان في ذلك ليت لول ولي الن لنه نهي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1293, 'quran:20:129', 'quran', 'quran', '20:129', 129, 1292, 'Taha', 'طه', 'وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى', NULL, NULL, 'ولولا كلمه سبقت من ربك لكان لزاما واجل مسمي', 'لول كلم سبقت من ربك لك لزم اجل مسم', 'quran', NULL, NULL, 'https://quran.com/20/129');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1293, 'ولو لول كلم لمه سبق بقت من ربك لكن لزم وجل مسم سمي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1294, 'quran:20:130', 'quran', 'quran', '20:130', 130, 1293, 'Taha', 'طه', 'فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ', NULL, NULL, 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن اناي اليل فسبح واطراف النهار لعلك ترضي', 'اصبر عل م يقول سبح بحمد ربك قبل طلوع شمس قبل غروب ومن ان يل سبح اطرف نهر لعلك ترض', 'quran', NULL, NULL, 'https://quran.com/20/130');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1294, 'فصب صبر علي م يقو قول ولو لون وسب سبح بحم حمد ربك قبل طلو لوع الش لشم شمس وقب قبل غرو روب وبه ومن اني الي ليل فسب سبح وطر طرف الن لنه نهر لعل علك ترض رضي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1295, 'quran:20:131', 'quran', 'quran', '20:131', 131, 1294, 'Taha', 'طه', 'وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ', NULL, NULL, 'ولا تمدن عينيك الي ما متعنا به ازوجا منهم زهره الحياه الدنيا لنفتنهم فيه ورزق ربك خير وابقي', 'ول تمدن عينيك ال م متع به ازوج من زهر حي دني لنفتن في رزق ربك خير ابق', 'quran', NULL, NULL, 'https://quran.com/20/131');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1295, 'ول تمد مدن عين يني نيك الي م متع تعن به ازو زوج منه نهم زهر هره الح لحي حيه الد لدن دني لنف نفت فتن تنه نهم فيه ورز رزق ربك خير وبق بقي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1296, 'quran:20:132', 'quran', 'quran', '20:132', 132, 1295, 'Taha', 'طه', 'وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ', NULL, NULL, 'وامر اهلك بالصلاه واصطبر عليها لا نسلك رزقا نحن نرزقك والعقبه للتقوي', 'امر اهلك صل اصطبر علي ل نسلك رزق نحن نرزقك عقب تقو', 'quran', NULL, NULL, 'https://quran.com/20/132');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1296, 'ومر اهل هلك بلص لصل صله وصط صطب طبر علي ليه ل نسل سلك رزق نحن نرز رزق زقك ولع لعق عقب قبه للت لتق تقو قوي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1297, 'quran:20:133', 'quran', 'quran', '20:133', 133, 1296, 'Taha', 'طه', 'وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ', NULL, NULL, 'وقالوا لولا ياتينا بايه من ربه اولم تاتهم بينه ما في الصحف الاولي', 'قل لول يتي ب من رب اولم تت بين م في صحف اول', 'quran', NULL, NULL, 'https://quran.com/20/133');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1297, 'وقل قلو لول يتي تين بيه من ربه اول ولم تته تهم بين ينه م في الص لصح صحف الو لول ولي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1298, 'quran:20:134', 'quran', 'quran', '20:134', 134, 1297, 'Taha', 'طه', 'وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ', NULL, NULL, 'ولو انا اهلكنهم بعذاب من قبله لقالوا ربنا لولا ارسلت الينا رسولا فنتبع ايتك من قبل ان نذل ونخزي', 'ولو ان اهلكن بعذب من قبل لقل رب لول ارسلت ين رسول نتبع ايتك من قبل ان نذل نخز', 'quran', NULL, NULL, 'https://quran.com/20/134');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1298, 'ولو ان اهل هلك لكن كنه نهم بعذ عذب من قبل بله لقل قلو ربن لول ارس رسل سلت الي لين رسو سول فنت نتب تبع ايت يتك من قبل ان نذل ونخ نخز خزي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1299, 'quran:20:135', 'quran', 'quran', '20:135', 135, 1298, 'Taha', 'طه', 'قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ', NULL, NULL, 'قل كل متربص فتربصوا فستعلمون من اصحب الصرط السوي ومن اهتدي', 'قل كل متربص تربص ستعلم من اصحب صرط سو ومن اهتد', 'quran', NULL, NULL, 'https://quran.com/20/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1299, 'قل كل متر ترب ربص فتر ترب ربص بصو فست ستع تعل علم لمو مون من اصح صحب الص لصر صرط الس لسو سوي ومن اهت هتد تدي');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1300, 'quran:21:1', 'quran', 'quran', '21:1', 1, 1299, 'Al-Anbya', 'الأنبياء', 'ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ', NULL, NULL, 'اقترب للناس حسابهم وهم في غفله معرضون', 'اقترب نس حسب وهم في غفل معرض', 'quran', NULL, NULL, 'https://quran.com/21/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1300, 'اقت قتر ترب للن لنس حسب سبه بهم وهم في غفل فله معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1301, 'quran:21:2', 'quran', 'quran', '21:2', 2, 1300, 'Al-Anbya', 'الأنبياء', 'مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ', NULL, NULL, 'ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون', 'م يتي من ذكر من رب محدث ال استمعو وهم يلعب', 'quran', NULL, NULL, 'https://quran.com/21/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1301, 'م يتي تيه يهم من ذكر من ربه بهم محد حدث ال است ستم تمع معو عوه وهم يلع لعب عبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1302, 'quran:21:3', 'quran', 'quran', '21:3', 3, 1301, 'Al-Anbya', 'الأنبياء', 'لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ', NULL, NULL, 'لاهيه قلوبهم واسروا النجوي الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون', 'له قلوب اسر نجو ذين ظلم هل هذ ال بشر مثل افتت سحر انتم تبصر', 'quran', NULL, NULL, 'https://quran.com/21/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1302, 'لهي هيه قلو لوب وبه بهم وسر سرو الن لنج نجو جوي الذ لذي ذين ظلم لمو هل هذ ال بشر مثل ثلك لكم افت فتت تتو تون الس لسح سحر ونت نتم تبص بصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1303, 'quran:21:4', 'quran', 'quran', '21:4', 4, 1302, 'Al-Anbya', 'الأنبياء', 'قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'قال ربي يعلم القول في السماء والارض وهو السميع العليم', 'قل رب يعلم قول في سمء ارض وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/21/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1303, 'قل ربي يعل علم الق لقو قول في الس لسم سمء ولر لرض وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1304, 'quran:21:5', 'quran', 'quran', '21:5', 5, 1303, 'Al-Anbya', 'الأنبياء', 'بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ', NULL, NULL, 'بل قالوا اضغث احلم بل افتراه بل هو شاعر فلياتنا بايه كما ارسل الاولون', 'بل قل اضغث احلم بل افتر بل هو شعر ليت ب كم ارسل اول', 'quran', NULL, NULL, 'https://quran.com/21/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1304, 'بل قلو اضغ ضغث احل حلم بل افت فتر تره بل هو شعر فلي ليت يتن بيه كم ارس رسل الو لول ولو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1305, 'quran:21:6', 'quran', 'quran', '21:6', 6, 1304, 'Al-Anbya', 'الأنبياء', 'مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ', NULL, NULL, 'ما امنت قبلهم من قريه اهلكنها افهم يومنون', 'م امنت قبل من قر اهلكن اف يومن', 'quran', NULL, NULL, 'https://quran.com/21/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1305, 'م امن منت قبل بله لهم من قري ريه اهل هلك لكن كنه افه فهم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1306, 'quran:21:7', 'quran', 'quran', '21:7', 7, 1305, 'Al-Anbya', 'الأنبياء', 'وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ', NULL, NULL, 'وما ارسلنا قبلك الا رجالا نوحي اليهم فسلوا اهل الذكر ان كنتم لا تعلمون', 'وم ارسل قبلك ال رجل نوح يهم سل اهل ذكر ان كنتم ل تعلم', 'quran', NULL, NULL, 'https://quran.com/21/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1306, 'وم ارس رسل سلن قبل بلك ال رجل نوح وحي الي ليه يهم فسل سلو اهل الذ لذك ذكر ان كنت نتم ل تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1307, 'quran:21:8', 'quran', 'quran', '21:8', 8, 1306, 'Al-Anbya', 'الأنبياء', 'وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ', NULL, NULL, 'وما جعلنهم جسدا لا ياكلون الطعام وما كانوا خلدين', 'وم جعلن جسد ل يكل طعم وم كن خلد', 'quran', NULL, NULL, 'https://quran.com/21/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1307, 'وم جعل علن لنه نهم جسد ل يكل كلو لون الط لطع طعم وم كنو خلد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1308, 'quran:21:9', 'quran', 'quran', '21:9', 9, 1307, 'Al-Anbya', 'الأنبياء', 'ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ', NULL, NULL, 'ثم صدقنهم الوعد فانجينهم ومن نشاء واهلكنا المسرفين', 'ثم صدقن وعد انجين ومن نشء اهلك مسرف', 'quran', NULL, NULL, 'https://quran.com/21/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1308, 'ثم صدق دقن قنه نهم الو لوع وعد فنج نجي جين ينه نهم ومن نشء وهل هلك لكن الم لمس مسر سرف رفي فين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1309, 'quran:21:10', 'quran', 'quran', '21:10', 10, 1308, 'Al-Anbya', 'الأنبياء', 'لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'لقد انزلنا اليكم كتبا فيه ذكركم افلا تعقلون', 'لقد انزل يكم كتب في ذكر افل تعقل', 'quran', NULL, NULL, 'https://quran.com/21/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1309, 'لقد انز نزل زلن الي ليك يكم كتب فيه ذكر كرك ركم افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1310, 'quran:21:11', 'quran', 'quran', '21:11', 11, 1309, 'Al-Anbya', 'الأنبياء', 'وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ', NULL, NULL, 'وكم قصمنا من قريه كانت ظالمه وانشانا بعدها قوما اخرين', 'وكم قصم من قر كنت ظلم انش بعد قوم اخر', 'quran', NULL, NULL, 'https://quran.com/21/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1310, 'وكم قصم صمن من قري ريه كنت ظلم لمه ونش نشن بعد عده قوم اخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1311, 'quran:21:12', 'quran', 'quran', '21:12', 12, 1310, 'Al-Anbya', 'الأنبياء', 'فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ', NULL, NULL, 'فلما احسوا باسنا اذا هم منها يركضون', 'لم احس بس اذ هم من يركض', 'quran', NULL, NULL, 'https://quran.com/21/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1311, 'فلم احس حسو بسن اذ هم منه يرك ركض كضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1312, 'quran:21:13', 'quran', 'quran', '21:13', 13, 1311, 'Al-Anbya', 'الأنبياء', 'لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ', NULL, NULL, 'لا تركضوا وارجعوا الي ما اترفتم فيه ومسكنكم لعلكم تسلون', 'ل تركض ارجع ال م اترفتم في مسكن لعل تسل', 'quran', NULL, NULL, 'https://quran.com/21/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1312, 'ل ترك ركض كضو ورج رجع جعو الي م اتر ترف رفت فتم فيه ومس مسك سكن كنك نكم لعل علك لكم تسل سلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1313, 'quran:21:14', 'quran', 'quran', '21:14', 14, 1312, 'Al-Anbya', 'الأنبياء', 'قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', NULL, NULL, 'قالوا يا ويلنا انا كنا ظلمين', 'قل ي يل ان كن ظلم', 'quran', NULL, NULL, 'https://quran.com/21/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1313, 'قلو ي ويل يلن ان كن ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1314, 'quran:21:15', 'quran', 'quran', '21:15', 15, 1313, 'Al-Anbya', 'الأنبياء', 'فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ', NULL, NULL, 'فما زالت تلك دعواهم حتي جعلنهم حصيدا خمدين', 'فم زلت تلك دعو حت جعلن حصيد خمد', 'quran', NULL, NULL, 'https://quran.com/21/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1314, 'فم زلت تلك دعو عوه وهم حتي جعل علن لنه نهم حصي صيد خمد مدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1315, 'quran:21:16', 'quran', 'quran', '21:16', 16, 1314, 'Al-Anbya', 'الأنبياء', 'وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ', NULL, NULL, 'وما خلقنا السماء والارض وما بينهما لعبين', 'وم خلق سمء ارض وم بينهم لعب', 'quran', NULL, NULL, 'https://quran.com/21/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1315, 'وم خلق لقن الس لسم سمء ولر لرض وم بين ينه نهم لعب عبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1316, 'quran:21:17', 'quran', 'quran', '21:17', 17, 1315, 'Al-Anbya', 'الأنبياء', 'لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', NULL, NULL, 'لو اردنا ان نتخذ لهوا لاتخذنه من لدنا ان كنا فعلين', 'لو ارد ان نتخذ له لتخذن من لد ان كن عل', 'quran', NULL, NULL, 'https://quran.com/21/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1316, 'لو ارد ردن ان نتخ تخذ لهو لتخ تخذ خذن ذنه من لدن ان كن فعل علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1317, 'quran:21:18', 'quran', 'quran', '21:18', 18, 1316, 'Al-Anbya', 'الأنبياء', 'بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ', NULL, NULL, 'بل نقذف بالحق علي البطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون', 'بل نقذف حق عل بطل يدمغ اذ هو زهق لكم ويل مم تصف', 'quran', NULL, NULL, 'https://quran.com/21/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1317, 'بل نقذ قذف بلح لحق علي الب لبط بطل فيد يدم دمغ مغه فذ هو زهق ولك لكم الو لوي ويل مم تصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1318, 'quran:21:19', 'quran', 'quran', '21:19', 19, 1317, 'Al-Anbya', 'الأنبياء', 'وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ', NULL, NULL, 'وله من في السموت والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون', 'ول من في سموت ارض ومن عند ل يستكبر عن عبدت ول يستحسر', 'quran', NULL, NULL, 'https://quran.com/21/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1318, 'وله من في الس لسم سمو موت ولر لرض ومن عند نده ل يست ستك تكب كبر برو رون عن عبد بدت دته ول يست ستح تحس حسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1319, 'quran:21:20', 'quran', 'quran', '21:20', 20, 1318, 'Al-Anbya', 'الأنبياء', 'يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ', NULL, NULL, 'يسبحون اليل والنهار لا يفترون', 'يسبح يل نهر ل يفتر', 'quran', NULL, NULL, 'https://quran.com/21/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1319, 'يسب سبح بحو حون الي ليل ولن لنه نهر ل يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1320, 'quran:21:21', 'quran', 'quran', '21:21', 21, 1319, 'Al-Anbya', 'الأنبياء', 'أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ', NULL, NULL, 'ام اتخذوا الهه من الارض هم ينشرون', 'ام اتخذ هه من ارض هم ينشر', 'quran', NULL, NULL, 'https://quran.com/21/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1320, 'ام اتخ تخذ خذو اله لهه من الر لرض هم ينش نشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1321, 'quran:21:22', 'quran', 'quran', '21:22', 22, 1320, 'Al-Anbya', 'الأنبياء', 'لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ', NULL, NULL, 'لو كان فيهما الهه الا الله لفسدتا فسبحن الله رب العرش عما يصفون', 'لو كن يهم هه ال له لفسدت سبحن له رب عرش عم يصف', 'quran', NULL, NULL, 'https://quran.com/21/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1321, 'لو كن فيه يهم اله لهه ال الل لله لفس فسد سدت فسب سبح بحن الل لله رب الع لعر عرش عم يصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1322, 'quran:21:23', 'quran', 'quran', '21:23', 23, 1321, 'Al-Anbya', 'الأنبياء', 'لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ', NULL, NULL, 'لا يسل عما يفعل وهم يسلون', 'ل يسل عم يفعل وهم يسل', 'quran', NULL, NULL, 'https://quran.com/21/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1322, 'ل يسل عم يفع فعل وهم يسل سلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1323, 'quran:21:24', 'quran', 'quran', '21:24', 24, 1322, 'Al-Anbya', 'الأنبياء', 'أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ', NULL, NULL, 'ام اتخذوا من دونه الهه قل هاتوا برهنكم هذا ذكر من معي وذكر من قبلي بل اكثرهم لا يعلمون الحق فهم معرضون', 'ام اتخذ من دون هه قل هت برهن هذ ذكر من مع ذكر من قبل بل اكثر ل يعلم حق فهم معرض', 'quran', NULL, NULL, 'https://quran.com/21/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1323, 'ام اتخ تخذ خذو من دون ونه اله لهه قل هتو بره رهن هنك نكم هذ ذكر من معي وذك ذكر من قبل بلي بل اكث كثر ثره رهم ل يعل علم لمو مون الح لحق فهم معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1324, 'quran:21:25', 'quran', 'quran', '21:25', 25, 1323, 'Al-Anbya', 'الأنبياء', 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ', NULL, NULL, 'وما ارسلنا من قبلك من رسول الا نوحي اليه انه لا اله الا انا فاعبدون', 'وم ارسل من قبلك من رسول ال نوح يه ان ل ال ال ان اعبد', 'quran', NULL, NULL, 'https://quran.com/21/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1324, 'وم ارس رسل سلن من قبل بلك من رسو سول ال نوح وحي الي ليه انه ل اله ال ان فعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1325, 'quran:21:26', 'quran', 'quran', '21:26', 26, 1324, 'Al-Anbya', 'الأنبياء', 'وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ', NULL, NULL, 'وقالوا اتخذ الرحمن ولدا سبحنه بل عباد مكرمون', 'قل اتخذ رحمن لد سبحن بل عبد مكرم', 'quran', NULL, NULL, 'https://quran.com/21/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1325, 'وقل قلو اتخ تخذ الر لرح رحم حمن ولد سبح بحن حنه بل عبد مكر كرم رمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1326, 'quran:21:27', 'quran', 'quran', '21:27', 27, 1325, 'Al-Anbya', 'الأنبياء', 'لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ', NULL, NULL, 'لا يسبقونه بالقول وهم بامره يعملون', 'ل يسبقون قول وهم بمر يعمل', 'quran', NULL, NULL, 'https://quran.com/21/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1326, 'ل يسب سبق بقو قون ونه بلق لقو قول وهم بمر مره يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1327, 'quran:21:28', 'quran', 'quran', '21:28', 28, 1326, 'Al-Anbya', 'الأنبياء', 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ', NULL, NULL, 'يعلم ما بين ايديهم وما خلفهم ولا يشفعون الا لمن ارتضي وهم من خشيته مشفقون', 'يعلم م بين ايدي وم خلف ول يشفع ال لمن ارتض وهم من خشيت مشفق', 'quran', NULL, NULL, 'https://quran.com/21/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1327, 'يعل علم م بين ايد يدي ديه يهم وم خلف لفه فهم ول يشف شفع فعو عون ال لمن ارت رتض تضي وهم من خشي شيت يته مشف شفق فقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1328, 'quran:21:29', 'quran', 'quran', '21:29', 29, 1327, 'Al-Anbya', 'الأنبياء', 'وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ', NULL, NULL, 'ومن يقل منهم اني اله من دونه فذلك نجزيه جهنم كذلك نجزي الظلمين', 'ومن يقل من ان ال من دون ذلك نجز جهنم كذلك نجز ظلم', 'quran', NULL, NULL, 'https://quran.com/21/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1328, 'ومن يقل منه نهم اني اله من دون ونه فذل ذلك نجز جزي زيه جهن هنم كذل ذلك نجز جزي الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1329, 'quran:21:30', 'quran', 'quran', '21:30', 30, 1328, 'Al-Anbya', 'الأنبياء', 'أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ', NULL, NULL, 'اولم ير الذين كفروا ان السموت والارض كانتا رتقا ففتقنهما وجعلنا من الماء كل شيء حي افلا يومنون', 'اولم ير ذين كفر ان سموت ارض كنت رتق فتقنهم جعل من مء كل شيء حي افل يومن', 'quran', NULL, NULL, 'https://quran.com/21/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1329, 'اول ولم ير الذ لذي ذين كفر فرو ان الس لسم سمو موت ولر لرض كنت رتق ففت فتق تقن قنه نهم وجع جعل علن من الم لمء كل شيء حي افل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1330, 'quran:21:31', 'quran', 'quran', '21:31', 31, 1329, 'Al-Anbya', 'الأنبياء', 'وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ', NULL, NULL, 'وجعلنا في الارض روسي ان تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون', 'جعل في ارض روس ان تميد بهم جعل يه جج سبل لعل يهتد', 'quran', NULL, NULL, 'https://quran.com/21/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1330, 'وجع جعل علن في الر لرض روس وسي ان تمي ميد بهم وجع جعل علن فيه فجج سبل لعل عله لهم يهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1331, 'quran:21:32', 'quran', 'quran', '21:32', 32, 1330, 'Al-Anbya', 'الأنبياء', 'وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ', NULL, NULL, 'وجعلنا السماء سقفا محفوظا وهم عن ايتها معرضون', 'جعل سمء سقف محفوظ وهم عن ايت معرض', 'quran', NULL, NULL, 'https://quran.com/21/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1331, 'وجع جعل علن الس لسم سمء سقف محف حفو فوظ وهم عن ايت يته معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1332, 'quran:21:33', 'quran', 'quran', '21:33', 33, 1331, 'Al-Anbya', 'الأنبياء', 'وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ', NULL, NULL, 'وهو الذي خلق اليل والنهار والشمس والقمر كل في فلك يسبحون', 'وهو ذي خلق يل نهر شمس قمر كل في فلك يسبح', 'quran', NULL, NULL, 'https://quran.com/21/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1332, 'وهو الذ لذي خلق الي ليل ولن لنه نهر ولش لشم شمس ولق لقم قمر كل في فلك يسب سبح بحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1333, 'quran:21:34', 'quran', 'quran', '21:34', 34, 1332, 'Al-Anbya', 'الأنبياء', 'وَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ', NULL, NULL, 'وما جعلنا لبشر من قبلك الخلد افاين مت فهم الخلدون', 'وم جعل لبشر من قبلك خلد اف مت فهم خلد', 'quran', NULL, NULL, 'https://quran.com/21/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1333, 'وم جعل علن لبش بشر من قبل بلك الخ لخل خلد افي فين مت فهم الخ لخل خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1334, 'quran:21:35', 'quran', 'quran', '21:35', 35, 1333, 'Al-Anbya', 'الأنبياء', 'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ', NULL, NULL, 'كل نفس ذايقه الموت ونبلوكم بالشر والخير فتنه والينا ترجعون', 'كل نفس ذيق موت نبلو شر خير تن ين ترجع', 'quran', NULL, NULL, 'https://quran.com/21/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1334, 'كل نفس ذيق يقه الم لمو موت ونب نبل بلو لوك وكم بلش لشر ولخ لخي خير فتن تنه ولي لين ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1335, 'quran:21:36', 'quran', 'quran', '21:36', 36, 1334, 'Al-Anbya', 'الأنبياء', 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ', NULL, NULL, 'واذا راك الذين كفروا ان يتخذونك الا هزوا اهذا الذي يذكر الهتكم وهم بذكر الرحمن هم كفرون', 'اذ رك ذين كفر ان يتخذونك ال هز اهذ ذي يذكر هت وهم بذكر رحمن هم كفر', 'quran', NULL, NULL, 'https://quran.com/21/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1335, 'وذ رك الذ لذي ذين كفر فرو ان يتخ تخذ خذو ذون ونك ال هزو اهذ الذ لذي يذك ذكر اله لهت هتك تكم وهم بذك ذكر الر لرح رحم حمن هم كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1336, 'quran:21:37', 'quran', 'quran', '21:37', 37, 1335, 'Al-Anbya', 'الأنبياء', 'خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ', NULL, NULL, 'خلق الانسن من عجل ساوريكم ايتي فلا تستعجلون', 'خلق انسن من عجل سوري ايت فل تستعجل', 'quran', NULL, NULL, 'https://quran.com/21/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1336, 'خلق الن لنس نسن من عجل سور وري ريك يكم ايت يتي فل تست ستع تعج عجل جلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1337, 'quran:21:38', 'quran', 'quran', '21:38', 38, 1336, 'Al-Anbya', 'الأنبياء', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 'يقول مت هذ وعد ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/21/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1337, 'ويق يقو قول ولو لون متي هذ الو لوع وعد ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1338, 'quran:21:39', 'quran', 'quran', '21:39', 39, 1337, 'Al-Anbya', 'الأنبياء', 'لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ', NULL, NULL, 'لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون', 'لو يعلم ذين كفر حين ل يكف عن جوه نر ول عن ظهور ول هم ينصر', 'quran', NULL, NULL, 'https://quran.com/21/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1338, 'لو يعل علم الذ لذي ذين كفر فرو حين ل يكف كفو فون عن وجو جوه وهه ههم الن لنر ول عن ظهو هور وره رهم ول هم ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1339, 'quran:21:40', 'quran', 'quran', '21:40', 40, 1338, 'Al-Anbya', 'الأنبياء', 'بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ', NULL, NULL, 'بل تاتيهم بغته فتبهتهم فلا يستطيعون ردها ولا هم ينظرون', 'بل تتي بغت تبهت فل يستطيع رد ول هم ينظر', 'quran', NULL, NULL, 'https://quran.com/21/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1339, 'بل تتي تيه يهم بغت غته فتب تبه بهت هته تهم فل يست ستط تطي طيع يعو عون رده ول هم ينظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1340, 'quran:21:41', 'quran', 'quran', '21:41', 41, 1339, 'Al-Anbya', 'الأنبياء', 'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'ولقد استهزي برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', 'لقد استهز برسل من قبلك حق ذين سخر من م كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/21/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1340, 'ولق لقد است سته تهز هزي برس رسل من قبل بلك فحق بلذ لذي ذين سخر خرو منه نهم م كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1341, 'quran:21:42', 'quran', 'quran', '21:42', 42, 1340, 'Al-Anbya', 'الأنبياء', 'قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ', NULL, NULL, 'قل من يكلوكم باليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون', 'قل من يكلو يل نهر من رحمن بل هم عن ذكر رب معرض', 'quran', NULL, NULL, 'https://quran.com/21/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1341, 'قل من يكل كلو لوك وكم بلي ليل ولن لنه نهر من الر لرح رحم حمن بل هم عن ذكر ربه بهم معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1342, 'quran:21:43', 'quran', 'quran', '21:43', 43, 1341, 'Al-Anbya', 'الأنبياء', 'أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ', NULL, NULL, 'ام لهم الهه تمنعهم من دوننا لا يستطيعون نصر انفسهم ولا هم منا يصحبون', 'ام لهم هه تمنع من دون ل يستطيع نصر انفس ول هم من يصحب', 'quran', NULL, NULL, 'https://quran.com/21/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1342, 'ام لهم اله لهه تمن منع نعه عهم من دون ونن ل يست ستط تطي طيع يعو عون نصر انف نفس فسه سهم ول هم من يصح صحب حبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1343, 'quran:21:44', 'quran', 'quran', '21:44', 44, 1342, 'Al-Anbya', 'الأنبياء', 'بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ', NULL, NULL, 'بل متعنا هولاء واباءهم حتي طال عليهم العمر افلا يرون انا ناتي الارض ننقصها من اطرافها افهم الغلبون', 'بل متع هولء ابء حت طل علي عمر افل ير ان نت ارض ننقص من اطرف اف غلب', 'quran', NULL, NULL, 'https://quran.com/21/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1343, 'بل متع تعن هول ولء وبء بءه ءهم حتي طل علي ليه يهم الع لعم عمر افل يرو رون ان نتي الر لرض ننق نقص قصه من اطر طرف رفه افه فهم الغ لغل غلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1344, 'quran:21:45', 'quran', 'quran', '21:45', 45, 1343, 'Al-Anbya', 'الأنبياء', 'قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', NULL, NULL, 'قل انما انذركم بالوحي ولا يسمع الصم الدعاء اذا ما ينذرون', 'قل انم انذر وح ول يسمع صم دعء اذ م ينذر', 'quran', NULL, NULL, 'https://quran.com/21/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1344, 'قل انم انذ نذر ذرك ركم بلو لوح وحي ول يسم سمع الص لصم الد لدع دعء اذ م ينذ نذر ذرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1345, 'quran:21:46', 'quran', 'quran', '21:46', 46, 1344, 'Al-Anbya', 'الأنبياء', 'وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', NULL, NULL, 'ولين مستهم نفحه من عذاب ربك ليقولن يا ويلنا انا كنا ظلمين', 'لين مست نفح من عذب ربك ليقولن ي يل ان كن ظلم', 'quran', NULL, NULL, 'https://quran.com/21/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1345, 'ولي لين مست سته تهم نفح فحه من عذب ربك ليق يقو قول ولن ي ويل يلن ان كن ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1346, 'quran:21:47', 'quran', 'quran', '21:47', 47, 1345, 'Al-Anbya', 'الأنبياء', 'وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ', NULL, NULL, 'ونضع الموزين القسط ليوم القيمه فلا تظلم نفس شيا وان كان مثقال حبه من خردل اتينا بها وكفي بنا حسبين', 'نضع موز قسط ليوم قيم فل تظلم نفس شي ون كن مثقل حب من خردل اتي به كف بن حسب', 'quran', NULL, NULL, 'https://quran.com/21/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1346, 'ونض نضع الم لمو موز وزي زين الق لقس قسط ليو يوم الق لقي قيم يمه فل تظل ظلم نفس شي ون كن مثق ثقل حبه من خرد ردل اتي تين به وكف كفي بن حسب سبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1347, 'quran:21:48', 'quran', 'quran', '21:48', 48, 1346, 'Al-Anbya', 'الأنبياء', 'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ', NULL, NULL, 'ولقد اتينا موسي وهرون الفرقان وضياء وذكرا للمتقين', 'لقد اتي موس هر فرق ضيء ذكر متق', 'quran', NULL, NULL, 'https://quran.com/21/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1347, 'ولق لقد اتي تين موس وسي وهر هرو رون الف لفر فرق رقن وضي ضيء وذك ذكر للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1348, 'quran:21:49', 'quran', 'quran', '21:49', 49, 1347, 'Al-Anbya', 'الأنبياء', 'ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ', NULL, NULL, 'الذين يخشون ربهم بالغيب وهم من الساعه مشفقون', 'ذين يخش رب غيب وهم من سع مشفق', 'quran', NULL, NULL, 'https://quran.com/21/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1348, 'الذ لذي ذين يخش خشو شون ربه بهم بلغ لغي غيب وهم من الس لسع سعه مشف شفق فقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1349, 'quran:21:50', 'quran', 'quran', '21:50', 50, 1348, 'Al-Anbya', 'الأنبياء', 'وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ', NULL, NULL, 'وهذا ذكر مبارك انزلنه افانتم له منكرون', 'هذ ذكر مبرك انزلن افنتم له منكر', 'quran', NULL, NULL, 'https://quran.com/21/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1349, 'وهذ ذكر مبر برك انز نزل زلن لنه افن فنت نتم له منك نكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1350, 'quran:21:51', 'quran', 'quran', '21:51', 51, 1349, 'Al-Anbya', 'الأنبياء', 'وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', NULL, NULL, 'ولقد اتينا ابرهيم رشده من قبل وكنا به علمين', 'لقد اتي ابرهيم رشد من قبل كن به علم', 'quran', NULL, NULL, 'https://quran.com/21/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1350, 'ولق لقد اتي تين ابر بره رهي هيم رشد شده من قبل وكن به علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1351, 'quran:21:52', 'quran', 'quran', '21:52', 52, 1350, 'Al-Anbya', 'الأنبياء', 'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ', NULL, NULL, 'اذ قال لابيه وقومه ما هذه التماثيل التي انتم لها عكفون', 'اذ قل لب قوم م هذ تمثيل تي انتم له عكف', 'quran', NULL, NULL, 'https://quran.com/21/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1351, 'اذ قل لبي بيه وقو قوم ومه م هذه الت لتم تمث مثي ثيل الت لتي انت نتم له عكف كفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1352, 'quran:21:53', 'quran', 'quran', '21:53', 53, 1351, 'Al-Anbya', 'الأنبياء', 'قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', NULL, NULL, 'قالوا وجدنا اباءنا لها عبدين', 'قل جد ابء له عبد', 'quran', NULL, NULL, 'https://quran.com/21/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1352, 'قلو وجد جدن ابء بءن له عبد بدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1353, 'quran:21:54', 'quran', 'quran', '21:54', 54, 1352, 'Al-Anbya', 'الأنبياء', 'قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ', NULL, NULL, 'قال لقد كنتم انتم واباوكم في ضلل مبين', 'قل لقد كنتم انتم ابو في ضلل مب', 'quran', NULL, NULL, 'https://quran.com/21/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1353, 'قل لقد كنت نتم انت نتم وبو بوك وكم في ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1354, 'quran:21:55', 'quran', 'quran', '21:55', 55, 1353, 'Al-Anbya', 'الأنبياء', 'قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ', NULL, NULL, 'قالوا اجيتنا بالحق ام انت من اللعبين', 'قل اجيت حق ام انت من لعب', 'quran', NULL, NULL, 'https://quran.com/21/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1354, 'قلو اجي جيت يتن بلح لحق ام انت من الل للع لعب عبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1355, 'quran:21:56', 'quran', 'quran', '21:56', 56, 1354, 'Al-Anbya', 'الأنبياء', 'قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', NULL, NULL, 'قال بل ربكم رب السموت والارض الذي فطرهن وانا علي ذلكم من الشهدين', 'قل بل رب رب سموت ارض ذي طر ان عل ذل من شهد', 'quran', NULL, NULL, 'https://quran.com/21/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1355, 'قل بل ربك بكم رب الس لسم سمو موت ولر لرض الذ لذي فطر طره رهن ون علي ذلك لكم من الش لشه شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1356, 'quran:21:57', 'quran', 'quran', '21:57', 57, 1355, 'Al-Anbya', 'الأنبياء', 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ', NULL, NULL, 'وتالله لاكيدن اصنمكم بعد ان تولوا مدبرين', 'تلل لكيدن اصنم بعد ان تول مدبر', 'quran', NULL, NULL, 'https://quran.com/21/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1356, 'وتل تلل لله لكي كيد يدن اصن صنم نمك مكم بعد ان تول ولو مدب دبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1357, 'quran:21:58', 'quran', 'quran', '21:58', 58, 1356, 'Al-Anbya', 'الأنبياء', 'فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ', NULL, NULL, 'فجعلهم جذذا الا كبيرا لهم لعلهم اليه يرجعون', 'جعل جذذ ال كبير لهم لعل يه يرجع', 'quran', NULL, NULL, 'https://quran.com/21/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1357, 'فجع جعل عله لهم جذذ ال كبي بير لهم لعل عله لهم الي ليه يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1358, 'quran:21:59', 'quran', 'quran', '21:59', 59, 1357, 'Al-Anbya', 'الأنبياء', 'قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'قالوا من فعل هذا بالهتنا انه لمن الظلمين', 'قل من فعل هذ هت ان لمن ظلم', 'quran', NULL, NULL, 'https://quran.com/21/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1358, 'قلو من فعل هذ بله لهت هتن انه لمن الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1359, 'quran:21:60', 'quran', 'quran', '21:60', 60, 1358, 'Al-Anbya', 'الأنبياء', 'قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ', NULL, NULL, 'قالوا سمعنا فتي يذكرهم يقال له ابرهيم', 'قل سمع فت يذكر يقل له ابرهيم', 'quran', NULL, NULL, 'https://quran.com/21/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1359, 'قلو سمع معن فتي يذك ذكر كره رهم يقل له ابر بره رهي هيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1360, 'quran:21:61', 'quran', 'quran', '21:61', 61, 1359, 'Al-Anbya', 'الأنبياء', 'قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ', NULL, NULL, 'قالوا فاتوا به علي اعين الناس لعلهم يشهدون', 'قل ات به عل اع نس لعل يشهد', 'quran', NULL, NULL, 'https://quran.com/21/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1360, 'قلو فتو به علي اعي عين الن لنس لعل عله لهم يشه شهد هدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1361, 'quran:21:62', 'quran', 'quran', '21:62', 62, 1360, 'Al-Anbya', 'الأنبياء', 'قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ', NULL, NULL, 'قالوا انت فعلت هذا بالهتنا يا ابرهيم', 'قل انت علت هذ هت ي ابرهيم', 'quran', NULL, NULL, 'https://quran.com/21/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1361, 'قلو انت فعل علت هذ بله لهت هتن ي ابر بره رهي هيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1362, 'quran:21:63', 'quran', 'quran', '21:63', 63, 1361, 'Al-Anbya', 'الأنبياء', 'قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ', NULL, NULL, 'قال بل فعله كبيرهم هذا فسلوهم ان كانوا ينطقون', 'قل بل عل كبير هذ سلو ان كن ينطق', 'quran', NULL, NULL, 'https://quran.com/21/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1362, 'قل بل فعل عله كبي بير يره رهم هذ فسل سلو لوه وهم ان كنو ينط نطق طقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1363, 'quran:21:64', 'quran', 'quran', '21:64', 64, 1362, 'Al-Anbya', 'الأنبياء', 'فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'فرجعوا الي انفسهم فقالوا انكم انتم الظلمون', 'رجع ال انفس قل ان انتم ظلم', 'quran', NULL, NULL, 'https://quran.com/21/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1363, 'فرج رجع جعو الي انف نفس فسه سهم فقل قلو انك نكم انت نتم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1364, 'quran:21:65', 'quran', 'quran', '21:65', 65, 1363, 'Al-Anbya', 'الأنبياء', 'ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', NULL, NULL, 'ثم نكسوا علي رءوسهم لقد علمت ما هولاء ينطقون', 'ثم نكس عل رءوس لقد علمت م هولء ينطق', 'quran', NULL, NULL, 'https://quran.com/21/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1364, 'ثم نكس كسو علي رءو ءوس وسه سهم لقد علم لمت م هول ولء ينط نطق طقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1365, 'quran:21:66', 'quran', 'quran', '21:66', 66, 1364, 'Al-Anbya', 'الأنبياء', 'قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ', NULL, NULL, 'قال افتعبدون من دون الله ما لا ينفعكم شيا ولا يضركم', 'قل افتعبد من دون له م ل ينفع شي ول يضر', 'quran', NULL, NULL, 'https://quran.com/21/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1365, 'قل افت فتع تعب عبد بدو دون من دون الل لله م ل ينف نفع فعك عكم شي ول يضر ضرك ركم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1366, 'quran:21:67', 'quran', 'quran', '21:67', 67, 1365, 'Al-Anbya', 'الأنبياء', 'أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'اف لكم ولما تعبدون من دون الله افلا تعقلون', 'اف لكم لم تعبد من دون له افل تعقل', 'quran', NULL, NULL, 'https://quran.com/21/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1366, 'اف لكم ولم تعب عبد بدو دون من دون الل لله افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1367, 'quran:21:68', 'quran', 'quran', '21:68', 68, 1366, 'Al-Anbya', 'الأنبياء', 'قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ', NULL, NULL, 'قالوا حرقوه وانصروا الهتكم ان كنتم فعلين', 'قل حرقو انصر هت ان كنتم عل', 'quran', NULL, NULL, 'https://quran.com/21/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1367, 'قلو حرق رقو قوه ونص نصر صرو اله لهت هتك تكم ان كنت نتم فعل علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1368, 'quran:21:69', 'quran', 'quran', '21:69', 69, 1367, 'Al-Anbya', 'الأنبياء', 'قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ', NULL, NULL, 'قلنا يا نار كوني بردا وسلما علي ابرهيم', 'قل ي نر كون برد سلم عل ابرهيم', 'quran', NULL, NULL, 'https://quran.com/21/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1368, 'قلن ي نر كون وني برد وسل سلم علي ابر بره رهي هيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1369, 'quran:21:70', 'quran', 'quran', '21:70', 70, 1368, 'Al-Anbya', 'الأنبياء', 'وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ', NULL, NULL, 'وارادوا به كيدا فجعلنهم الاخسرين', 'ارد به كيد جعلن اخسر', 'quran', NULL, NULL, 'https://quran.com/21/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1369, 'ورد ردو به كيد فجع جعل علن لنه نهم الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1370, 'quran:21:71', 'quran', 'quran', '21:71', 71, 1369, 'Al-Anbya', 'الأنبياء', 'وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ', NULL, NULL, 'ونجينه ولوطا الي الارض التي بركنا فيها للعلمين', 'نجين لوط ال ارض تي برك يه علم', 'quran', NULL, NULL, 'https://quran.com/21/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1370, 'ونج نجي جين ينه ولو لوط الي الر لرض الت لتي برك ركن فيه للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1371, 'quran:21:72', 'quran', 'quran', '21:72', 72, 1370, 'Al-Anbya', 'الأنبياء', 'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ', NULL, NULL, 'ووهبنا له اسحق ويعقوب نافله وكلا جعلنا صلحين', 'وهب له اسحق يعقوب نفل كل جعل صلح', 'quran', NULL, NULL, 'https://quran.com/21/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1371, 'ووه وهب هبن له اسح سحق ويع يعق عقو قوب نفل فله وكل جعل علن صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1372, 'quran:21:73', 'quran', 'quran', '21:73', 73, 1371, 'Al-Anbya', 'الأنبياء', 'وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ', NULL, NULL, 'وجعلنهم ايمه يهدون بامرنا واوحينا اليهم فعل الخيرت واقام الصلاه وايتاء الزكاه وكانوا لنا عبدين', 'جعلن ايم يهد بمر اوحي يهم فعل خيرت اقم صل ايتء زك كن لن عبد', 'quran', NULL, NULL, 'https://quran.com/21/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1372, 'وجع جعل علن لنه نهم ايم يمه يهد هدو دون بمر مرن ووح وحي حين الي ليه يهم فعل الخ لخي خير يرت وقم الص لصل صله ويت يتء الز لزك زكه وكن كنو لن عبد بدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1373, 'quran:21:74', 'quran', 'quran', '21:74', 74, 1372, 'Al-Anbya', 'الأنبياء', 'وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ', NULL, NULL, 'ولوطا اتينه حكما وعلما ونجينه من القريه التي كانت تعمل الخبيث انهم كانوا قوم سوء فسقين', 'لوط اتين حكم علم نجين من قر تي كنت تعمل خبيث ان كن قوم سوء سق', 'quran', NULL, NULL, 'https://quran.com/21/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1373, 'ولو لوط اتي تين ينه حكم وعل علم ونج نجي جين ينه من الق لقر قري ريه الت لتي كنت تعم عمل الخ لخب خبي بيث انه نهم كنو قوم سوء فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1374, 'quran:21:75', 'quran', 'quran', '21:75', 75, 1373, 'Al-Anbya', 'الأنبياء', 'وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'وادخلنه في رحمتنا انه من الصلحين', 'ادخلن في رحمت ان من صلح', 'quran', NULL, NULL, 'https://quran.com/21/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1374, 'ودخ دخل خلن لنه في رحم حمت متن انه من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1375, 'quran:21:76', 'quran', 'quran', '21:76', 76, 1374, 'Al-Anbya', 'الأنبياء', 'وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ', NULL, NULL, 'ونوحا اذ نادي من قبل فاستجبنا له فنجينه واهله من الكرب العظيم', 'نوح اذ ند من قبل استجب له نجين اهل من كرب عظيم', 'quran', NULL, NULL, 'https://quran.com/21/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1375, 'ونو نوح اذ ندي من قبل فست ستج تجب جبن له فنج نجي جين ينه وهل هله من الك لكر كرب الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1376, 'quran:21:77', 'quran', 'quran', '21:77', 77, 1375, 'Al-Anbya', 'الأنبياء', 'وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ', NULL, NULL, 'ونصرنه من القوم الذين كذبوا بايتنا انهم كانوا قوم سوء فاغرقنهم اجمعين', 'نصرن من قوم ذين كذب بيت ان كن قوم سوء اغرقن اجمع', 'quran', NULL, NULL, 'https://quran.com/21/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1376, 'ونص نصر صرن رنه من الق لقو قوم الذ لذي ذين كذب ذبو بيت يتن انه نهم كنو قوم سوء فغر غرق رقن قنه نهم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1377, 'quran:21:78', 'quran', 'quran', '21:78', 78, 1376, 'Al-Anbya', 'الأنبياء', 'وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ', NULL, NULL, 'وداود وسليمن اذ يحكمان في الحرث اذ نفشت فيه غنم القوم وكنا لحكمهم شهدين', 'دود سليمن اذ يحكم في حرث اذ نفشت في غنم قوم كن لحكم شهد', 'quran', NULL, NULL, 'https://quran.com/21/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1377, 'ودو دود وسل سلي ليم يمن اذ يحك حكم كمن في الح لحر حرث اذ نفش فشت فيه غنم الق لقو قوم وكن لحك حكم كمه مهم شهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1378, 'quran:21:79', 'quran', 'quran', '21:79', 79, 1377, 'Al-Anbya', 'الأنبياء', 'فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ', NULL, NULL, 'ففهمنها سليمن وكلا اتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فعلين', 'فهمن سليمن كل اتي حكم علم سخر مع دود جبل يسبحن طير كن عل', 'quran', NULL, NULL, 'https://quran.com/21/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1378, 'ففه فهم همن منه سلي ليم يمن وكل اتي تين حكم وعل علم وسخ سخر خرن مع دود الج لجب جبل يسب سبح بحن ولط لطي طير وكن فعل علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1379, 'quran:21:80', 'quran', 'quran', '21:80', 80, 1378, 'Al-Anbya', 'الأنبياء', 'وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ', NULL, NULL, 'وعلمنه صنعه لبوس لكم لتحصنكم من باسكم فهل انتم شكرون', 'علمن صنع لبوس لكم لتحصن من بس فهل انتم شكر', 'quran', NULL, NULL, 'https://quran.com/21/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1379, 'وعل علم لمن منه صنع نعه لبو بوس لكم لتح تحص حصن صنك نكم من بسك سكم فهل انت نتم شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1380, 'quran:21:81', 'quran', 'quran', '21:81', 81, 1379, 'Al-Anbya', 'الأنبياء', 'وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ', NULL, NULL, 'ولسليمن الريح عاصفه تجري بامره الي الارض التي بركنا فيها وكنا بكل شيء علمين', 'لسليمن ريح عصف تجر بمر ال ارض تي برك يه كن بكل شيء علم', 'quran', NULL, NULL, 'https://quran.com/21/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1380, 'ولس لسل سلي ليم يمن الر لري ريح عصف صفه تجر جري بمر مره الي الر لرض الت لتي برك ركن فيه وكن بكل شيء علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1381, 'quran:21:82', 'quran', 'quran', '21:82', 82, 1380, 'Al-Anbya', 'الأنبياء', 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ', NULL, NULL, 'ومن الشيطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حفظين', 'ومن شيط من يغوص له يعمل عمل دون ذلك كن لهم حفظ', 'quran', NULL, NULL, 'https://quran.com/21/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1381, 'ومن الش لشي شيط يطي طين من يغو غوص وصو صون له ويع يعم عمل ملو لون عمل دون ذلك وكن لهم حفظ فظي ظين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1382, 'quran:21:83', 'quran', 'quran', '21:83', 83, 1381, 'Al-Anbya', 'الأنبياء', 'وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ', NULL, NULL, 'وايوب اذ نادي ربه اني مسني الضر وانت ارحم الرحمين', 'ايوب اذ ند رب ان مسن ضر انت ارحم رحم', 'quran', NULL, NULL, 'https://quran.com/21/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1382, 'ويو يوب اذ ندي ربه اني مسن سني الض لضر ونت ارح رحم الر لرح رحم حمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1383, 'quran:21:84', 'quran', 'quran', '21:84', 84, 1382, 'Al-Anbya', 'الأنبياء', 'فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ', NULL, NULL, 'فاستجبنا له فكشفنا ما به من ضر واتينه اهله ومثلهم معهم رحمه من عندنا وذكري للعبدين', 'استجب له كشف م به من ضر اتين اهل مثل مع رحم من عند ذكر عبد', 'quran', NULL, NULL, 'https://quran.com/21/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1383, 'فست ستج تجب جبن له فكش كشف شفن م به من ضر وتي تين ينه اهل هله ومث مثل ثله لهم معه عهم رحم حمه من عند ندن وذك ذكر كري للع لعب عبد بدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1384, 'quran:21:85', 'quran', 'quran', '21:85', 85, 1383, 'Al-Anbya', 'الأنبياء', 'وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ', NULL, NULL, 'واسمعيل وادريس وذا الكفل كل من الصبرين', 'اسمعيل ادريس وذ كفل كل من صبر', 'quran', NULL, NULL, 'https://quran.com/21/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1384, 'وسم سمع معي عيل ودر دري ريس وذ الك لكف كفل كل من الص لصب صبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1385, 'quran:21:86', 'quran', 'quran', '21:86', 86, 1384, 'Al-Anbya', 'الأنبياء', 'وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'وادخلنهم في رحمتنا انهم من الصلحين', 'ادخلن في رحمت ان من صلح', 'quran', NULL, NULL, 'https://quran.com/21/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1385, 'ودخ دخل خلن لنه نهم في رحم حمت متن انه نهم من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1386, 'quran:21:87', 'quran', 'quran', '21:87', 87, 1385, 'Al-Anbya', 'الأنبياء', 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ', NULL, NULL, 'وذا النون اذ ذهب مغضبا فظن ان لن نقدر عليه فنادي في الظلمت ان لا اله الا انت سبحنك اني كنت من الظلمين', 'وذ نون اذ ذهب مغضب فظن ان لن نقدر عل ند في ظلمت ان ل ال ال انت سبحنك ان كنت من ظلم', 'quran', NULL, NULL, 'https://quran.com/21/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1386, 'وذ الن لنو نون اذ ذهب مغض غضب فظن ان لن نقد قدر علي ليه فند ندي في الظ لظل ظلم لمت ان ل اله ال انت سبح بحن حنك اني كنت من الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1387, 'quran:21:88', 'quran', 'quran', '21:88', 88, 1386, 'Al-Anbya', 'الأنبياء', 'فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'فاستجبنا له ونجينه من الغم وكذلك نجي المومنين', 'استجب له نجين من غم كذلك نج مومن', 'quran', NULL, NULL, 'https://quran.com/21/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1387, 'فست ستج تجب جبن له ونج نجي جين ينه من الغ لغم وكذ كذل ذلك نجي الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1388, 'quran:21:89', 'quran', 'quran', '21:89', 89, 1387, 'Al-Anbya', 'الأنبياء', 'وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ', NULL, NULL, 'وزكريا اذ نادي ربه رب لا تذرني فردا وانت خير الورثين', 'زكري اذ ند رب رب ل تذرن رد انت خير ورث', 'quran', NULL, NULL, 'https://quran.com/21/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1388, 'وزك زكر كري اذ ندي ربه رب ل تذر ذرن رني فرد ونت خير الو لور ورث رثي ثين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1389, 'quran:21:90', 'quran', 'quran', '21:90', 90, 1388, 'Al-Anbya', 'الأنبياء', 'فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ', NULL, NULL, 'فاستجبنا له ووهبنا له يحيي واصلحنا له زوجه انهم كانوا يسرعون في الخيرت ويدعوننا رغبا ورهبا وكانوا لنا خشعين', 'استجب له وهب له يحي اصلح له زوج ان كن يسرع في خيرت يدعون رغب رهب كن لن خشع', 'quran', NULL, NULL, 'https://quran.com/21/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1389, 'فست ستج تجب جبن له ووه وهب هبن له يحي حيي وصل صلح لحن له زوج وجه انه نهم كنو يسر سرع رعو عون في الخ لخي خير يرت ويد يدع دعو عون ونن رغب وره رهب وكن كنو لن خشع شعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1390, 'quran:21:91', 'quran', 'quran', '21:91', 91, 1389, 'Al-Anbya', 'الأنبياء', 'وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ', NULL, NULL, 'والتي احصنت فرجها فنفخنا فيها من روحنا وجعلنها وابنها ايه للعلمين', 'تي احصنت رج نفخ يه من روح جعلن ابن اي علم', 'quran', NULL, NULL, 'https://quran.com/21/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1390, 'ولت لتي احص حصن صنت فرج رجه فنف نفخ فخن فيه من روح وحن وجع جعل علن لنه وبن بنه ايه للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1391, 'quran:21:92', 'quran', 'quran', '21:92', 92, 1390, 'Al-Anbya', 'الأنبياء', 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ', NULL, NULL, 'ان هذه امتكم امه وحده وانا ربكم فاعبدون', 'ان هذ امت ام حد ان رب اعبد', 'quran', NULL, NULL, 'https://quran.com/21/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1391, 'ان هذه امت متك تكم امه وحد حده ون ربك بكم فعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1392, 'quran:21:93', 'quran', 'quran', '21:93', 93, 1391, 'Al-Anbya', 'الأنبياء', 'وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ', NULL, NULL, 'وتقطعوا امرهم بينهم كل الينا رجعون', 'تقطع امر بين كل ين رجع', 'quran', NULL, NULL, 'https://quran.com/21/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1392, 'وتق تقط قطع طعو امر مره رهم بين ينه نهم كل الي لين رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1393, 'quran:21:94', 'quran', 'quran', '21:94', 94, 1392, 'Al-Anbya', 'الأنبياء', 'فَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', NULL, NULL, 'فمن يعمل من الصلحت وهو مومن فلا كفران لسعيه وانا له كتبون', 'فمن يعمل من صلحت وهو مومن فل كفر لسع ان له كتب', 'quran', NULL, NULL, 'https://quran.com/21/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1393, 'فمن يعم عمل من الص لصل صلح لحت وهو موم ومن فل كفر فرن لسع سعي عيه ون له كتب تبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1394, 'quran:21:95', 'quran', 'quran', '21:95', 95, 1393, 'Al-Anbya', 'الأنبياء', 'وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ', NULL, NULL, 'وحرم علي قريه اهلكنها انهم لا يرجعون', 'حرم عل قر اهلكن ان ل يرجع', 'quran', NULL, NULL, 'https://quran.com/21/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1394, 'وحر حرم علي قري ريه اهل هلك لكن كنه انه نهم ل يرج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1395, 'quran:21:96', 'quran', 'quran', '21:96', 96, 1394, 'Al-Anbya', 'الأنبياء', 'حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ', NULL, NULL, 'حتي اذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون', 'حت اذ تحت يجوج مجوج وهم من كل حدب ينسل', 'quran', NULL, NULL, 'https://quran.com/21/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1395, 'حتي اذ فتح تحت يجو جوج ومج مجو جوج وهم من كل حدب ينس نسل سلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1396, 'quran:21:97', 'quran', 'quran', '21:97', 97, 1395, 'Al-Anbya', 'الأنبياء', 'وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ', NULL, NULL, 'واقترب الوعد الحق فاذا هي شخصه ابصر الذين كفروا يا ويلنا قد كنا في غفله من هذا بل كنا ظلمين', 'اقترب وعد حق اذ هي شخص ابصر ذين كفر ي يل قد كن في غفل من هذ بل كن ظلم', 'quran', NULL, NULL, 'https://quran.com/21/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1396, 'وقت قتر ترب الو لوع وعد الح لحق فذ هي شخص خصه ابص بصر الذ لذي ذين كفر فرو ي ويل يلن قد كن في غفل فله من هذ بل كن ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1397, 'quran:21:98', 'quran', 'quran', '21:98', 98, 1396, 'Al-Anbya', 'الأنبياء', 'إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ', NULL, NULL, 'انكم وما تعبدون من دون الله حصب جهنم انتم لها وردون', 'ان وم تعبد من دون له حصب جهنم انتم له رد', 'quran', NULL, NULL, 'https://quran.com/21/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1397, 'انك نكم وم تعب عبد بدو دون من دون الل لله حصب جهن هنم انت نتم له ورد ردو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1398, 'quran:21:99', 'quran', 'quran', '21:99', 99, 1397, 'Al-Anbya', 'الأنبياء', 'لَوۡ كَانَ هَٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ', NULL, NULL, 'لو كان هولاء الهه ما وردوها وكل فيها خلدون', 'لو كن هولء هه م ردو وكل يه خلد', 'quran', NULL, NULL, 'https://quran.com/21/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1398, 'لو كن هول ولء اله لهه م ورد ردو دوه وكل فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1399, 'quran:21:100', 'quran', 'quran', '21:100', 100, 1398, 'Al-Anbya', 'الأنبياء', 'لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ', NULL, NULL, 'لهم فيها زفير وهم فيها لا يسمعون', 'لهم يه زفير وهم يه ل يسمع', 'quran', NULL, NULL, 'https://quran.com/21/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1399, 'لهم فيه زفي فير وهم فيه ل يسم سمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1400, 'quran:21:101', 'quran', 'quran', '21:101', 101, 1399, 'Al-Anbya', 'الأنبياء', 'إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَٰٓئِكَ عَنۡهَا مُبۡعَدُونَ', NULL, NULL, 'ان الذين سبقت لهم منا الحسني اوليك عنها مبعدون', 'ان ذين سبقت لهم من حسن اوليك عن مبعد', 'quran', NULL, NULL, 'https://quran.com/21/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1400, 'ان الذ لذي ذين سبق بقت لهم من الح لحس حسن سني اول ولي ليك عنه مبع بعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1401, 'quran:21:102', 'quran', 'quran', '21:102', 102, 1400, 'Al-Anbya', 'الأنبياء', 'لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ', NULL, NULL, 'لا يسمعون حسيسها وهم في ما اشتهت انفسهم خلدون', 'ل يسمع حسيس وهم في م اشتهت انفس خلد', 'quran', NULL, NULL, 'https://quran.com/21/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1401, 'ل يسم سمع معو عون حسي سيس يسه وهم في م اشت شته تهت انف نفس فسه سهم خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1402, 'quran:21:103', 'quran', 'quran', '21:103', 103, 1401, 'Al-Anbya', 'الأنبياء', 'لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ', NULL, NULL, 'لا يحزنهم الفزع الاكبر وتتلقاهم المليكه هذا يومكم الذي كنتم توعدون', 'ل يحزن فزع اكبر تتلق مليك هذ يوم ذي كنتم توعد', 'quran', NULL, NULL, 'https://quran.com/21/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1402, 'ل يحز حزن زنه نهم الف لفز فزع الك لكب كبر وتت تتل تلق لقه قهم الم لمل ملي ليك يكه هذ يوم ومك مكم الذ لذي كنت نتم توع وعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1403, 'quran:21:104', 'quran', 'quran', '21:104', 104, 1402, 'Al-Anbya', 'الأنبياء', 'يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ', NULL, NULL, 'يوم نطوي السماء كطي السجل للكتب كما بدانا اول خلق نعيده وعدا علينا انا كنا فعلين', 'يوم نطو سمء كط سجل كتب كم بد اول خلق نعيد عد علي ان كن عل', 'quran', NULL, NULL, 'https://quran.com/21/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1403, 'يوم نطو طوي الس لسم سمء كطي الس لسج سجل للك لكت كتب كم بدن اول خلق نعي عيد يده وعد علي لين ان كن فعل علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1404, 'quran:21:105', 'quran', 'quran', '21:105', 105, 1403, 'Al-Anbya', 'الأنبياء', 'وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ', NULL, NULL, 'ولقد كتبنا في الزبور من بعد الذكر ان الارض يرثها عبادي الصلحون', 'لقد كتب في زبور من بعد ذكر ان ارض يرث عبد صلح', 'quran', NULL, NULL, 'https://quran.com/21/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1404, 'ولق لقد كتب تبن في الز لزب زبو بور من بعد الذ لذك ذكر ان الر لرض يرث رثه عبد بدي الص لصل صلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1405, 'quran:21:106', 'quran', 'quran', '21:106', 106, 1404, 'Al-Anbya', 'الأنبياء', 'إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ', NULL, NULL, 'ان في هذا لبلغا لقوم عبدين', 'ان في هذ لبلغ لقوم عبد', 'quran', NULL, NULL, 'https://quran.com/21/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1405, 'ان في هذ لبل بلغ لقو قوم عبد بدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1406, 'quran:21:107', 'quran', 'quran', '21:107', 107, 1405, 'Al-Anbya', 'الأنبياء', 'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ', NULL, NULL, 'وما ارسلنك الا رحمه للعلمين', 'وم ارسلنك ال رحم علم', 'quran', NULL, NULL, 'https://quran.com/21/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1406, 'وم ارس رسل سلن لنك ال رحم حمه للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1407, 'quran:21:108', 'quran', 'quran', '21:108', 108, 1406, 'Al-Anbya', 'الأنبياء', 'قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ', NULL, NULL, 'قل انما يوحي الي انما الهكم اله وحد فهل انتم مسلمون', 'قل انم يوح ال انم هكم ال وحد فهل انتم مسلم', 'quran', NULL, NULL, 'https://quran.com/21/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1407, 'قل انم يوح وحي الي انم اله لهك هكم اله وحد فهل انت نتم مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1408, 'quran:21:109', 'quran', 'quran', '21:109', 109, 1407, 'Al-Anbya', 'الأنبياء', 'فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ', NULL, NULL, 'فان تولوا فقل اذنتكم علي سواء وان ادري اقريب ام بعيد ما توعدون', 'فن تول فقل اذنت عل سوء ون ادر اقريب ام بعيد م توعد', 'quran', NULL, NULL, 'https://quran.com/21/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1408, 'فن تول ولو فقل اذن ذنت نتك تكم علي سوء ون ادر دري اقر قري ريب ام بعي عيد م توع وعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1409, 'quran:21:110', 'quran', 'quran', '21:110', 110, 1408, 'Al-Anbya', 'الأنبياء', 'إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ', NULL, NULL, 'انه يعلم الجهر من القول ويعلم ما تكتمون', 'ان يعلم جهر من قول يعلم م تكتم', 'quran', NULL, NULL, 'https://quran.com/21/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1409, 'انه يعل علم الج لجه جهر من الق لقو قول ويع يعل علم م تكت كتم تمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1410, 'quran:21:111', 'quran', 'quran', '21:111', 111, 1409, 'Al-Anbya', 'الأنبياء', 'وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ', NULL, NULL, 'وان ادري لعله فتنه لكم ومتع الي حين', 'ون ادر لعل تن لكم متع ال حين', 'quran', NULL, NULL, 'https://quran.com/21/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1410, 'ون ادر دري لعل عله فتن تنه لكم ومت متع الي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1411, 'quran:21:112', 'quran', 'quran', '21:112', 112, 1410, 'Al-Anbya', 'الأنبياء', 'قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ', NULL, NULL, 'قل رب احكم بالحق وربنا الرحمن المستعان علي ما تصفون', 'قل رب اح حق رب رحمن مستع عل م تصف', 'quran', NULL, NULL, 'https://quran.com/21/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1411, 'قل رب احك حكم بلح لحق ورب ربن الر لرح رحم حمن الم لمس مست ستع تعن علي م تصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1412, 'quran:22:1', 'quran', 'quran', '22:1', 1, 1411, 'Al-Hajj', 'الحج', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ', NULL, NULL, 'يا ايها الناس اتقوا ربكم ان زلزله الساعه شيء عظيم', 'ي اي نس اتق رب ان زلزل سع شيء عظيم', 'quran', NULL, NULL, 'https://quran.com/22/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1412, 'ي ايه الن لنس اتق تقو ربك بكم ان زلز لزل زله الس لسع سعه شيء عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1413, 'quran:22:2', 'quran', 'quran', '22:2', 2, 1412, 'Al-Hajj', 'الحج', 'يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ', NULL, NULL, 'يوم ترونها تذهل كل مرضعه عما ارضعت وتضع كل ذات حمل حملها وتري الناس سكري وما هم بسكري ولكن عذاب الله شديد', 'يوم ترون تذهل كل مرضع عم ارضعت تضع كل ذت حمل حمل تر نس سكر وم هم بسكر لكن عذب له شديد', 'quran', NULL, NULL, 'https://quran.com/22/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1413, 'يوم ترو رون ونه تذه ذهل كل مرض رضع ضعه عم ارض رضع ضعت وتض تضع كل ذت حمل حمل مله وتر تري الن لنس سكر كري وم هم بسك سكر كري ولك لكن عذب الل لله شدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1414, 'quran:22:3', 'quran', 'quran', '22:3', 3, 1413, 'Al-Hajj', 'الحج', 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ', NULL, NULL, 'ومن الناس من يجدل في الله بغير علم ويتبع كل شيطن مريد', 'ومن نس من يجدل في له بغير علم يتبع كل شيطن مريد', 'quran', NULL, NULL, 'https://quran.com/22/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1414, 'ومن الن لنس من يجد جدل في الل لله بغي غير علم ويت يتب تبع كل شيط يطن مري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1415, 'quran:22:4', 'quran', 'quran', '22:4', 4, 1414, 'Al-Hajj', 'الحج', 'كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', NULL, NULL, 'كتب عليه انه من تولاه فانه يضله ويهديه الي عذاب السعير', 'كتب عل ان من تول ان يضل يهد ال عذب سعير', 'quran', NULL, NULL, 'https://quran.com/22/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1415, 'كتب علي ليه انه من تول وله فنه يضل ضله ويه يهد هدي ديه الي عذب الس لسع سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1416, 'quran:22:5', 'quran', 'quran', '22:5', 5, 1415, 'Al-Hajj', 'الحج', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ', NULL, NULL, 'يا ايها الناس ان كنتم في ريب من البعث فانا خلقنكم من تراب ثم من نطفه ثم من علقه ثم من مضغه مخلقه وغير مخلقه لنبين لكم ونقر في الارحام ما نشاء الي اجل مسمي ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفي ومنكم من يرد الي ارذل العمر لكيلا يعلم من بعد علم شيا وتري الارض هامده فاذا انزلنا عليها الماء اهتزت وربت وانبتت من كل زوج بهيج', 'ي اي نس ان كنتم في ريب من بعث ان خلقن من ترب ثم من نطف ثم من علق ثم من مضغ مخلق غير مخلق لنب لكم نقر في ارحم م نشء ال اجل مسم ثم نخرج طفل ثم لتبلغ اشد من من يتوف من من يرد ال ارذل عمر لكيل يعلم من بعد علم شي تر ارض همد اذ انزل علي مء اهتزت ربت انبتت من كل زوج بهيج', 'quran', NULL, NULL, 'https://quran.com/22/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1416, 'ي ايه الن لنس ان كنت نتم في ريب من الب لبع بعث فن خلق لقن قنك نكم من ترب ثم من نطف طفه ثم من علق لقه ثم من مضغ ضغه مخل خلق لقه وغي غير مخل خلق لقه لنب نبي بين لكم ونق نقر في الر لرح رحم م نشء الي اجل مسم سمي ثم نخر خرج رجك جكم طفل ثم لتب تبل بلغ لغو اشد شدك دكم ومن منك نكم من يتو توف وفي ومن منك نكم من يرد الي ارذ رذل الع لعم عمر لكي كيل يعل علم من بعد علم شي وتر تري الر لرض همد مده فذ انز نزل زلن علي ليه الم لمء اهت هتز تزت ورب ربت ونب نبت بتت من كل زوج بهي هيج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1417, 'quran:22:6', 'quran', 'quran', '22:6', 6, 1416, 'Al-Hajj', 'الحج', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'ذلك بان الله هو الحق وانه يحي الموتي وانه علي كل شيء قدير', 'ذلك بن له هو حق ان يح موت ان عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/22/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1417, 'ذلك بن الل لله هو الح لحق ونه يحي الم لمو موت وتي ونه علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1418, 'quran:22:7', 'quran', 'quran', '22:7', 7, 1417, 'Al-Hajj', 'الحج', 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ', NULL, NULL, 'وان الساعه اتيه لا ريب فيها وان الله يبعث من في القبور', 'ون سع ات ل ريب يه ون له يبعث من في قبور', 'quran', NULL, NULL, 'https://quran.com/22/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1418, 'ون الس لسع سعه اتي تيه ل ريب فيه ون الل لله يبع بعث من في الق لقب قبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1419, 'quran:22:8', 'quran', 'quran', '22:8', 8, 1418, 'Al-Hajj', 'الحج', 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ', NULL, NULL, 'ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير', 'ومن نس من يجدل في له بغير علم ول هد ول كتب منير', 'quran', NULL, NULL, 'https://quran.com/22/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1419, 'ومن الن لنس من يجد جدل في الل لله بغي غير علم ول هدي ول كتب مني نير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1420, 'quran:22:9', 'quran', 'quran', '22:9', 9, 1419, 'Al-Hajj', 'الحج', 'ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ', NULL, NULL, 'ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيمه عذاب الحريق', 'ثن عطف ليضل عن سبيل له له في دني خز نذيق يوم قيم عذب حريق', 'quran', NULL, NULL, 'https://quran.com/22/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1420, 'ثني عطف طفه ليض يضل عن سبي بيل الل لله له في الد لدن دني خزي ونذ نذي ذيق يقه يوم الق لقي قيم يمه عذب الح لحر حري ريق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1421, 'quran:22:10', 'quran', 'quran', '22:10', 10, 1420, 'Al-Hajj', 'الحج', 'ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمٖ لِّلۡعَبِيدِ', NULL, NULL, 'ذلك بما قدمت يداك وان الله ليس بظلم للعبيد', 'ذلك بم قدمت يدك ون له ليس بظلم عبيد', 'quran', NULL, NULL, 'https://quran.com/22/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1421, 'ذلك بم قدم دمت يدك ون الل لله ليس بظل ظلم للع لعب عبي بيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1422, 'quran:22:11', 'quran', 'quran', '22:11', 11, 1421, 'Al-Hajj', 'الحج', 'وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ', NULL, NULL, 'ومن الناس من يعبد الله علي حرف فان اصابه خير اطمان به وان اصابته فتنه انقلب علي وجهه خسر الدنيا والاخره ذلك هو الخسران المبين', 'ومن نس من يعبد له عل حرف فن اصب خير اطم به ون اصبت تن انقلب عل جه خسر دني اخر ذلك هو خسر مب', 'quran', NULL, NULL, 'https://quran.com/22/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1422, 'ومن الن لنس من يعب عبد الل لله علي حرف فن اصب صبه خير اطم طمن به ون اصب صبت بته فتن تنه انق نقل قلب علي وجه جهه خسر الد لدن دني ولخ لخر خره ذلك هو الخ لخس خسر سرن الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1423, 'quran:22:12', 'quran', 'quran', '22:12', 12, 1422, 'Al-Hajj', 'الحج', 'يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ', NULL, NULL, 'يدعوا من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلل البعيد', 'يدع من دون له م ل يضر وم ل ينفع ذلك هو ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/22/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1423, 'يدع دعو من دون الل لله م ل يضر ضره وم ل ينف نفع فعه ذلك هو الض لضل ضلل الب لبع بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1424, 'quran:22:13', 'quran', 'quran', '22:13', 13, 1423, 'Al-Hajj', 'الحج', 'يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ', NULL, NULL, 'يدعوا لمن ضره اقرب من نفعه لبيس المولي ولبيس العشير', 'يدع لمن ضر اقرب من نفع لبيس مول لبيس عشير', 'quran', NULL, NULL, 'https://quran.com/22/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1424, 'يدع دعو لمن ضره اقر قرب من نفع فعه لبي بيس الم لمو مول ولي ولب لبي بيس الع لعش عشي شير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1425, 'quran:22:14', 'quran', 'quran', '22:14', 14, 1424, 'Al-Hajj', 'الحج', 'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ', NULL, NULL, 'ان الله يدخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر ان الله يفعل ما يريد', 'ان له يدخل ذين امن عمل صلحت جنت تجر من تحت انهر ان له يفعل م يريد', 'quran', NULL, NULL, 'https://quran.com/22/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1425, 'ان الل لله يدخ دخل الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت جنت تجر جري من تحت حته الن لنه نهر ان الل لله يفع فعل م يري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1426, 'quran:22:15', 'quran', 'quran', '22:15', 15, 1425, 'Al-Hajj', 'الحج', 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ', NULL, NULL, 'من كان يظن ان لن ينصره الله في الدنيا والاخره فليمدد بسبب الي السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ', 'من كن يظن ان لن ينصر له في دني اخر ليمدد بسبب ال سمء ثم ليقطع لينظر هل يذهبن كيد م يغيظ', 'quran', NULL, NULL, 'https://quran.com/22/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1426, 'من كن يظن ان لن ينص نصر صره الل لله في الد لدن دني ولخ لخر خره فلي ليم يمد مدد بسب سبب الي الس لسم سمء ثم ليق يقط قطع فلي لين ينظ نظر هل يذه ذهب هبن كيد يده م يغي غيظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1427, 'quran:22:16', 'quran', 'quran', '22:16', 16, 1426, 'Al-Hajj', 'الحج', 'وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ', NULL, NULL, 'وكذلك انزلنه ايت بينت وان الله يهدي من يريد', 'كذلك انزلن ايت بينت ون له يهد من يريد', 'quran', NULL, NULL, 'https://quran.com/22/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1427, 'وكذ كذل ذلك انز نزل زلن لنه ايت بين ينت ون الل لله يهد هدي من يري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1428, 'quran:22:17', 'quran', 'quran', '22:17', 17, 1427, 'Al-Hajj', 'الحج', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ', NULL, NULL, 'ان الذين امنوا والذين هادوا والصبين والنصري والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيمه ان الله علي كل شيء شهيد', 'ان ذين امن ذين هد صب نصر مجوس ذين اشرك ان له يفصل بين يوم قيم ان له عل كل شيء شهيد', 'quran', NULL, NULL, 'https://quran.com/22/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1428, 'ان الذ لذي ذين امن منو ولذ لذي ذين هدو ولص لصب صبي بين ولن لنص نصر صري ولم لمج مجو جوس ولذ لذي ذين اشر شرك ركو ان الل لله يفص فصل بين ينه نهم يوم الق لقي قيم يمه ان الل لله علي كل شيء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1429, 'quran:22:18', 'quran', 'quran', '22:18', 18, 1428, 'Al-Hajj', 'الحج', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ', NULL, NULL, 'الم تر ان الله يسجد له من في السموت ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشاء', 'الم تر ان له يسجد له من في سموت ومن في ارض شمس قمر نجوم جبل شجر دوب كثير من نس كثير حق عل عذب ومن يهن له فم له من مكرم ان له يفعل م يشء', 'quran', NULL, NULL, 'https://quran.com/22/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1429, 'الم تر ان الل لله يسج سجد له من في الس لسم سمو موت ومن في الر لرض ولش لشم شمس ولق لقم قمر ولن لنج نجو جوم ولج لجب جبل ولش لشج شجر ولد لدو دوب وكث كثي ثير من الن لنس وكث كثي ثير حق علي ليه الع لعذ عذب ومن يهن الل لله فم له من مكر كرم ان الل لله يفع فعل م يشء');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1430, 'quran:22:19', 'quran', 'quran', '22:19', 19, 1429, 'Al-Hajj', 'الحج', 'هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ', NULL, NULL, 'هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم', 'هذ خصم اختصم في رب ذين كفر قطعت لهم ثيب من نر يصب من فوق رءوس حميم', 'quran', NULL, NULL, 'https://quran.com/22/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1430, 'هذن خصم صمن اخت ختص تصم صمو في ربه بهم فلذ لذي ذين كفر فرو قطع طعت لهم ثيب من نر يصب من فوق رءو ءوس وسه سهم الح لحم حمي ميم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1431, 'quran:22:20', 'quran', 'quran', '22:20', 20, 1430, 'Al-Hajj', 'الحج', 'يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ', NULL, NULL, 'يصهر به ما في بطونهم والجلود', 'يصهر به م في بطون جلود', 'quran', NULL, NULL, 'https://quran.com/22/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1431, 'يصه صهر به م في بطو طون ونه نهم ولج لجل جلو لود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1432, 'quran:22:21', 'quran', 'quran', '22:21', 21, 1431, 'Al-Hajj', 'الحج', 'وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ', NULL, NULL, 'ولهم مقمع من حديد', 'لهم مقمع من حديد', 'quran', NULL, NULL, 'https://quran.com/22/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1432, 'وله لهم مقم قمع من حدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1433, 'quran:22:22', 'quran', 'quran', '22:22', 22, 1432, 'Al-Hajj', 'الحج', 'كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ', NULL, NULL, 'كلما ارادوا ان يخرجوا منها من غم اعيدوا فيها وذوقوا عذاب الحريق', 'كلم ارد ان يخرج من من غم اعيد يه ذوق عذب حريق', 'quran', NULL, NULL, 'https://quran.com/22/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1433, 'كلم ارد ردو ان يخر خرج رجو منه من غم اعي عيد يدو فيه وذو ذوق وقو عذب الح لحر حري ريق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1434, 'quran:22:23', 'quran', 'quran', '22:23', 23, 1433, 'Al-Hajj', 'الحج', 'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ', NULL, NULL, 'ان الله يدخل الذين امنوا وعملوا الصلحت جنت تجري من تحتها الانهر يحلون فيها من اساور من ذهب ولولوا ولباسهم فيها حرير', 'ان له يدخل ذين امن عمل صلحت جنت تجر من تحت انهر يحل يه من اسور من ذهب لول لبس يه حرير', 'quran', NULL, NULL, 'https://quran.com/22/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1434, 'ان الل لله يدخ دخل الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت جنت تجر جري من تحت حته الن لنه نهر يحل حلو لون فيه من اسو سور من ذهب ولو لول ولو ولب لبس بسه سهم فيه حري رير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1435, 'quran:22:24', 'quran', 'quran', '22:24', 24, 1434, 'Al-Hajj', 'الحج', 'وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ', NULL, NULL, 'وهدوا الي الطيب من القول وهدوا الي صرط الحميد', 'هد ال طيب من قول هد ال صرط حميد', 'quran', NULL, NULL, 'https://quran.com/22/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1435, 'وهد هدو الي الط لطي طيب من الق لقو قول وهد هدو الي صرط الح لحم حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1436, 'quran:22:25', 'quran', 'quran', '22:25', 25, 1435, 'Al-Hajj', 'الحج', 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ', NULL, NULL, 'ان الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلنه للناس سواء العكف فيه والباد ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم', 'ان ذين كفر يصد عن سبيل له مسجد حرم ذي جعلن نس سوء عكف في بد ومن يرد في حد بظلم نذق من عذب يم', 'quran', NULL, NULL, 'https://quran.com/22/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1436, 'ان الذ لذي ذين كفر فرو ويص يصد صدو دون عن سبي بيل الل لله ولم لمس مسج سجد الح لحر حرم الذ لذي جعل علن لنه للن لنس سوء الع لعك عكف فيه ولب لبد ومن يرد فيه بلح لحد بظل ظلم نذق ذقه من عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1437, 'quran:22:26', 'quran', 'quran', '22:26', 26, 1436, 'Al-Hajj', 'الحج', 'وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', NULL, NULL, 'واذ بوانا لابرهيم مكان البيت ان لا تشرك بي شيا وطهر بيتي للطايفين والقايمين والركع السجود', 'وذ بو لبرهيم مك بيت ان ل تشرك بي شي طهر بيت طيف قيم ركع سجود', 'quran', NULL, NULL, 'https://quran.com/22/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1437, 'وذ بون لبر بره رهي هيم مكن الب لبي بيت ان ل تشر شرك بي شي وطه طهر بيت يتي للط لطي طيف يفي فين ولق لقي قيم يمي مين ولر لرك ركع الس لسج سجو جود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1438, 'quran:22:27', 'quran', 'quran', '22:27', 27, 1437, 'Al-Hajj', 'الحج', 'وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ', NULL, NULL, 'واذن في الناس بالحج ياتوك رجالا وعلي كل ضامر ياتين من كل فج عميق', 'اذن في نس حج يتوك رجل عل كل ضمر يت من كل فج عميق', 'quran', NULL, NULL, 'https://quran.com/22/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1438, 'وذن في الن لنس بلح لحج يتو توك رجل وعل علي كل ضمر يتي تين من كل فج عمي ميق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1439, 'quran:22:28', 'quran', 'quran', '22:28', 28, 1438, 'Al-Hajj', 'الحج', 'لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ', NULL, NULL, 'ليشهدوا منفع لهم ويذكروا اسم الله في ايام معلومت علي ما رزقهم من بهيمه الانعم فكلوا منها واطعموا البايس الفقير', 'ليشهد منفع لهم يذكر اسم له في ايم معلومت عل م رزق من بهيم انعم كل من اطعم بيس فقير', 'quran', NULL, NULL, 'https://quran.com/22/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1439, 'ليش يشه شهد هدو منف نفع لهم ويذ يذك ذكر كرو اسم الل لله في ايم معل علو لوم ومت علي م رزق زقه قهم من بهي هيم يمه الن لنع نعم فكل كلو منه وطع طعم عمو الب لبي بيس الف لفق فقي قير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1440, 'quran:22:29', 'quran', 'quran', '22:29', 29, 1439, 'Al-Hajj', 'الحج', 'ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ', NULL, NULL, 'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق', 'ثم ليقض تفث ليوف نذور ليطوف بيت عتيق', 'quran', NULL, NULL, 'https://quran.com/22/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1440, 'ثم ليق يقض قضو تفث فثه ثهم ولي ليو يوف وفو نذو ذور وره رهم ولي ليط يطو طوف وفو بلب لبي بيت الع لعت عتي تيق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1441, 'quran:22:30', 'quran', 'quran', '22:30', 30, 1440, 'Al-Hajj', 'الحج', 'ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ', NULL, NULL, 'ذلك ومن يعظم حرمت الله فهو خير له عند ربه واحلت لكم الانعم الا ما يتلي عليكم فاجتنبوا الرجس من الاوثن واجتنبوا قول الزور', 'ذلك ومن يعظم حرمت له فهو خير له عند رب احلت لكم انعم ال م يتل علي اجتنب رجس من اوثن اجتنب قول زور', 'quran', NULL, NULL, 'https://quran.com/22/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1441, 'ذلك ومن يعظ عظم حرم رمت الل لله فهو خير له عند ربه وحل حلت لكم الن لنع نعم ال م يتل تلي علي ليك يكم فجت جتن تنب نبو الر لرج رجس من الو لوث وثن وجت جتن تنب نبو قول الز لزو زور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1442, 'quran:22:31', 'quran', 'quran', '22:31', 31, 1441, 'Al-Hajj', 'الحج', 'حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ', NULL, NULL, 'حنفاء لله غير مشركين به ومن يشرك بالله فكانما خر من السماء فتخطفه الطير او تهوي به الريح في مكان سحيق', 'حنفء لل غير مشرك به ومن يشرك له كنم خر من سمء تخطف طير او تهو به ريح في مك سحيق', 'quran', NULL, NULL, 'https://quran.com/22/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1442, 'حنف نفء لله غير مشر شرك ركي كين به ومن يشر شرك بلل لله فكن كنم خر من الس لسم سمء فتخ تخط خطف طفه الط لطي طير او تهو هوي به الر لري ريح في مكن سحي حيق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1443, 'quran:22:32', 'quran', 'quran', '22:32', 32, 1442, 'Al-Hajj', 'الحج', 'ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ', NULL, NULL, 'ذلك ومن يعظم شعير الله فانها من تقوي القلوب', 'ذلك ومن يعظم شعير له ان من تقو قلوب', 'quran', NULL, NULL, 'https://quran.com/22/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1443, 'ذلك ومن يعظ عظم شعي عير الل لله فنه من تقو قوي الق لقل قلو لوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1444, 'quran:22:33', 'quran', 'quran', '22:33', 33, 1443, 'Al-Hajj', 'الحج', 'لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ', NULL, NULL, 'لكم فيها منفع الي اجل مسمي ثم محلها الي البيت العتيق', 'لكم يه منفع ال اجل مسم ثم محل ال بيت عتيق', 'quran', NULL, NULL, 'https://quran.com/22/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1444, 'لكم فيه منف نفع الي اجل مسم سمي ثم محل حله الي الب لبي بيت الع لعت عتي تيق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1445, 'quran:22:34', 'quran', 'quran', '22:34', 34, 1444, 'Al-Hajj', 'الحج', 'وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ', NULL, NULL, 'ولكل امه جعلنا منسكا ليذكروا اسم الله علي ما رزقهم من بهيمه الانعم فالهكم اله وحد فله اسلموا وبشر المخبتين', 'لكل ام جعل منسك ليذكر اسم له عل م رزق من بهيم انعم هكم ال وحد فل اسلم بشر مخبت', 'quran', NULL, NULL, 'https://quran.com/22/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1445, 'ولك لكل امه جعل علن منس نسك ليذ يذك ذكر كرو اسم الل لله علي م رزق زقه قهم من بهي هيم يمه الن لنع نعم فله لهك هكم اله وحد فله اسل سلم لمو وبش بشر الم لمخ مخب خبت بتي تين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1446, 'quran:22:35', 'quran', 'quran', '22:35', 35, 1445, 'Al-Hajj', 'الحج', 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ', NULL, NULL, 'الذين اذا ذكر الله وجلت قلوبهم والصبرين علي ما اصابهم والمقيمي الصلاه ومما رزقنهم ينفقون', 'ذين اذ ذكر له جلت قلوب صبر عل م اصب مقيم صل مم رزقن ينفق', 'quran', NULL, NULL, 'https://quran.com/22/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1446, 'الذ لذي ذين اذ ذكر الل لله وجل جلت قلو لوب وبه بهم ولص لصب صبر بري رين علي م اصب صبه بهم ولم لمق مقي قيم يمي الص لصل صله ومم رزق زقن قنه نهم ينف نفق فقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1447, 'quran:22:36', 'quran', 'quran', '22:36', 36, 1446, 'Al-Hajj', 'الحج', 'وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'والبدن جعلنها لكم من شعير الله لكم فيها خير فاذكروا اسم الله عليها صواف فاذا وجبت جنوبها فكلوا منها واطعموا القانع والمعتر كذلك سخرنها لكم لعلكم تشكرون', 'بدن جعلن لكم من شعير له لكم يه خير اذكر اسم له علي صوف اذ جبت جنوب كل من اطعم قنع معتر كذلك سخرن لكم لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/22/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1447, 'ولب لبد بدن جعل علن لنه لكم من شعي عير الل لله لكم فيه خير فذك ذكر كرو اسم الل لله علي ليه صوف فذ وجب جبت جنو نوب وبه فكل كلو منه وطع طعم عمو الق لقن قنع ولم لمع معت عتر كذل ذلك سخر خرن رنه لكم لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1448, 'quran:22:37', 'quran', 'quran', '22:37', 37, 1447, 'Al-Hajj', 'الحج', 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'لن ينال الله لحومها ولا دماوها ولكن يناله التقوي منكم كذلك سخرها لكم لتكبروا الله علي ما هداكم وبشر المحسنين', 'لن ينل له لحوم ول دمو لكن ينل تقو من كذلك سخر لكم لتكبر له عل م هد بشر محسن', 'quran', NULL, NULL, 'https://quran.com/22/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1448, 'لن ينل الل لله لحو حوم ومه ول دمو موه ولك لكن ينل نله الت لتق تقو قوي منك نكم كذل ذلك سخر خره لكم لتك تكب كبر برو الل لله علي م هدك دكم وبش بشر الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1449, 'quran:22:38', 'quran', 'quran', '22:38', 38, 1448, 'Al-Hajj', 'الحج', 'إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ', NULL, NULL, 'ان الله يدفع عن الذين امنوا ان الله لا يحب كل خوان كفور', 'ان له يدفع عن ذين امن ان له ل يحب كل خو كفور', 'quran', NULL, NULL, 'https://quran.com/22/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1449, 'ان الل لله يدف دفع عن الذ لذي ذين امن منو ان الل لله ل يحب كل خون كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1450, 'quran:22:39', 'quran', 'quran', '22:39', 39, 1449, 'Al-Hajj', 'الحج', 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ', NULL, NULL, 'اذن للذين يقتلون بانهم ظلموا وان الله علي نصرهم لقدير', 'اذن ذين يقتل بن ظلم ون له عل نصر لقدير', 'quran', NULL, NULL, 'https://quran.com/22/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1450, 'اذن للذ لذي ذين يقت قتل تلو لون بنه نهم ظلم لمو ون الل لله علي نصر صره رهم لقد قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1451, 'quran:22:40', 'quran', 'quran', '22:40', 40, 1450, 'Al-Hajj', 'الحج', 'ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ', NULL, NULL, 'الذين اخرجوا من ديرهم بغير حق الا ان يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صومع وبيع وصلوت ومسجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره ان الله لقوي عزيز', 'ذين اخرج من دير بغير حق ال ان يقول رب له لول دفع له نس بعض ببعض لهدمت صومع بيع صلوت مسجد يذكر يه اسم له كثير لينصرن له من ينصر ان له لقو عزيز', 'quran', NULL, NULL, 'https://quran.com/22/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1451, 'الذ لذي ذين اخر خرج رجو من دير يره رهم بغي غير حق ال ان يقو قول ولو ربن الل لله ولو لول دفع الل لله الن لنس بعض عضه ضهم ببع بعض لهد هدم دمت صوم ومع وبي بيع وصل صلو لوت ومس مسج سجد يذك ذكر فيه اسم الل لله كثي ثير ولي لين ينص نصر صرن الل لله من ينص نصر صره ان الل لله لقو قوي عزي زيز');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1452, 'quran:22:41', 'quran', 'quran', '22:41', 41, 1451, 'Al-Hajj', 'الحج', 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ', NULL, NULL, 'الذين ان مكنهم في الارض اقاموا الصلاه واتوا الزكاه وامروا بالمعروف ونهوا عن المنكر ولله عقبه الامور', 'ذين ان مكن في ارض اقم صل ات زك امر معروف نه عن منكر لل عقب امور', 'quran', NULL, NULL, 'https://quran.com/22/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1452, 'الذ لذي ذين ان مكن كنه نهم في الر لرض اقم قمو الص لصل صله وتو الز لزك زكه ومر مرو بلم لمع معر عرو روف ونه نهو عن الم لمن منك نكر ولل لله عقب قبه الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1453, 'quran:22:42', 'quran', 'quran', '22:42', 42, 1452, 'Al-Hajj', 'الحج', 'وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ', NULL, NULL, 'وان يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود', 'ون يكذبوك فقد كذبت قبل قوم نوح عد ثمود', 'quran', NULL, NULL, 'https://quran.com/22/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1453, 'ون يكذ كذب ذبو بوك فقد كذب ذبت قبل بله لهم قوم نوح وعد وثم ثمو مود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1454, 'quran:22:43', 'quran', 'quran', '22:43', 43, 1453, 'Al-Hajj', 'الحج', 'وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ', NULL, NULL, 'وقوم ابرهيم وقوم لوط', 'قوم ابرهيم قوم لوط', 'quran', NULL, NULL, 'https://quran.com/22/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1454, 'وقو قوم ابر بره رهي هيم وقو قوم لوط');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1455, 'quran:22:44', 'quran', 'quran', '22:44', 44, 1454, 'Al-Hajj', 'الحج', 'وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ', NULL, NULL, 'واصحب مدين وكذب موسي فامليت للكفرين ثم اخذتهم فكيف كان نكير', 'اصحب مد كذب موس امليت كفر ثم اخذت كيف كن نكير', 'quran', NULL, NULL, 'https://quran.com/22/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1455, 'وصح صحب مدي دين وكذ كذب موس وسي فمل ملي ليت للك لكف كفر فري رين ثم اخذ خذت ذته تهم فكي كيف كن نكي كير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1456, 'quran:22:45', 'quran', 'quran', '22:45', 45, 1455, 'Al-Hajj', 'الحج', 'فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ', NULL, NULL, 'فكاين من قريه اهلكنها وهي ظالمه فهي خاويه علي عروشها وبير معطله وقصر مشيد', 'ك من قر اهلكن وه ظلم فه خو عل عروش بير معطل قصر مشيد', 'quran', NULL, NULL, 'https://quran.com/22/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1456, 'فكي كين من قري ريه اهل هلك لكن كنه وهي ظلم لمه فهي خوي ويه علي عرو روش وشه وبي بير معط عطل طله وقص قصر مشي شيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1457, 'quran:22:46', 'quran', 'quran', '22:46', 46, 1456, 'Al-Hajj', 'الحج', 'أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ', NULL, NULL, 'افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمي الابصر ولكن تعمي القلوب التي في الصدور', 'افلم يسير في ارض تك لهم قلوب يعقل به او اذ يسمع به ان ل تعم ابصر لكن تعم قلوب تي في صدور', 'quran', NULL, NULL, 'https://quran.com/22/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1457, 'افل فلم يسي سير يرو في الر لرض فتك تكو كون لهم قلو لوب يعق عقل قلو لون به او اذن يسم سمع معو عون به فنه ل تعم عمي الب لبص بصر ولك لكن تعم عمي الق لقل قلو لوب الت لتي في الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1458, 'quran:22:47', 'quran', 'quran', '22:47', 47, 1457, 'Al-Hajj', 'الحج', 'وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ', NULL, NULL, 'ويستعجلونك بالعذاب ولن يخلف الله وعده وان يوما عند ربك كالف سنه مما تعدون', 'يستعجلونك عذب ولن يخلف له عد ون يوم عند ربك كلف سن مم تعد', 'quran', NULL, NULL, 'https://quran.com/22/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1458, 'ويس يست ستع تعج عجل جلو لون ونك بلع لعذ عذب ولن يخل خلف الل لله وعد عده ون يوم عند ربك كلف سنه مم تعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1459, 'quran:22:48', 'quran', 'quran', '22:48', 48, 1458, 'Al-Hajj', 'الحج', 'وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ', NULL, NULL, 'وكاين من قريه امليت لها وهي ظالمه ثم اخذتها والي المصير', 'ك من قر امليت له وه ظلم ثم اخذت ول مصير', 'quran', NULL, NULL, 'https://quran.com/22/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1459, 'وكي كين من قري ريه امل ملي ليت له وهي ظلم لمه ثم اخذ خذت ذته ولي الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1460, 'quran:22:49', 'quran', 'quran', '22:49', 49, 1459, 'Al-Hajj', 'الحج', 'قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ', NULL, NULL, 'قل يا ايها الناس انما انا لكم نذير مبين', 'قل ي اي نس انم ان لكم نذير مب', 'quran', NULL, NULL, 'https://quran.com/22/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1460, 'قل ي ايه الن لنس انم ان لكم نذي ذير مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1461, 'quran:22:50', 'quran', 'quran', '22:50', 50, 1460, 'Al-Hajj', 'الحج', 'فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ', NULL, NULL, 'فالذين امنوا وعملوا الصلحت لهم مغفره ورزق كريم', 'ذين امن عمل صلحت لهم مغفر رزق كريم', 'quran', NULL, NULL, 'https://quran.com/22/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1461, 'فلذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لهم مغف غفر فره ورز رزق كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1462, 'quran:22:51', 'quran', 'quran', '22:51', 51, 1461, 'Al-Hajj', 'الحج', 'وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', NULL, NULL, 'والذين سعوا في ايتنا معجزين اوليك اصحب الجحيم', 'ذين سع في ايت معجز اوليك اصحب جحيم', 'quran', NULL, NULL, 'https://quran.com/22/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1462, 'ولذ لذي ذين سعو في ايت يتن معج عجز جزي زين اول ولي ليك اصح صحب الج لجح جحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1463, 'quran:22:52', 'quran', 'quran', '22:52', 52, 1462, 'Al-Hajj', 'الحج', 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', NULL, NULL, 'وما ارسلنا من قبلك من رسول ولا نبي الا اذا تمني القي الشيطن في امنيته فينسخ الله ما يلقي الشيطن ثم يحكم الله ايته والله عليم حكيم', 'وم ارسل من قبلك من رسول ول نب ال اذ تمن قي شيطن في امنيت ينسخ له م يلق شيطن ثم يح له ايت له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/22/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1463, 'وم ارس رسل سلن من قبل بلك من رسو سول ول نبي ال اذ تمن مني الق لقي الش لشي شيط يطن في امن مني نيت يته فين ينس نسخ الل لله م يلق لقي الش لشي شيط يطن ثم يحك حكم الل لله ايت يته ولل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1464, 'quran:22:53', 'quran', 'quran', '22:53', 53, 1463, 'Al-Hajj', 'الحج', 'لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ', NULL, NULL, 'ليجعل ما يلقي الشيطن فتنه للذين في قلوبهم مرض والقاسيه قلوبهم وان الظلمين لفي شقاق بعيد', 'ليجعل م يلق شيطن تن ذين في قلوب مرض قس قلوب ون ظلم لف شقق بعيد', 'quran', NULL, NULL, 'https://quran.com/22/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1464, 'ليج يجع جعل م يلق لقي الش لشي شيط يطن فتن تنه للذ لذي ذين في قلو لوب وبه بهم مرض ولق لقس قسي سيه قلو لوب وبه بهم ون الظ لظل ظلم لمي مين لفي شقق بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1465, 'quran:22:54', 'quran', 'quran', '22:54', 54, 1464, 'Al-Hajj', 'الحج', 'وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'وليعلم الذين اوتوا العلم انه الحق من ربك فيومنوا به فتخبت له قلوبهم وان الله لهاد الذين امنوا الي صرط مستقيم', 'ليعلم ذين اوت علم ان حق من ربك يومن به تخبت له قلوب ون له لهد ذين امن ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/22/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1465, 'ولي ليع يعل علم الذ لذي ذين اوت وتو الع لعل علم انه الح لحق من ربك فيو يوم ومن منو به فتخ تخب خبت له قلو لوب وبه بهم ون الل لله لهد الذ لذي ذين امن منو الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1466, 'quran:22:55', 'quran', 'quran', '22:55', 55, 1465, 'Al-Hajj', 'الحج', 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ', NULL, NULL, 'ولا يزال الذين كفروا في مريه منه حتي تاتيهم الساعه بغته او ياتيهم عذاب يوم عقيم', 'ول يزل ذين كفر في مر من حت تتي سع بغت او يتي عذب يوم عقيم', 'quran', NULL, NULL, 'https://quran.com/22/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1466, 'ول يزل الذ لذي ذين كفر فرو في مري ريه منه حتي تتي تيه يهم الس لسع سعه بغت غته او يتي تيه يهم عذب يوم عقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1467, 'quran:22:56', 'quran', 'quran', '22:56', 56, 1466, 'Al-Hajj', 'الحج', 'ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي جَنَّٰتِ ٱلنَّعِيمِ', NULL, NULL, 'الملك يوميذ لله يحكم بينهم فالذين امنوا وعملوا الصلحت في جنت النعيم', 'ملك يوميذ لل يح بين ذين امن عمل صلحت في جنت نعيم', 'quran', NULL, NULL, 'https://quran.com/22/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1467, 'الم لمل ملك يوم ومي ميذ لله يحك حكم بين ينه نهم فلذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت في جنت الن لنع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1468, 'quran:22:57', 'quran', 'quran', '22:57', 57, 1467, 'Al-Hajj', 'الحج', 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ', NULL, NULL, 'والذين كفروا وكذبوا بايتنا فاوليك لهم عذاب مهين', 'ذين كفر كذب بيت اوليك لهم عذب مه', 'quran', NULL, NULL, 'https://quran.com/22/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1468, 'ولذ لذي ذين كفر فرو وكذ كذب ذبو بيت يتن فول ولي ليك لهم عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1469, 'quran:22:58', 'quran', 'quran', '22:58', 58, 1468, 'Al-Hajj', 'الحج', 'وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ', NULL, NULL, 'والذين هاجروا في سبيل الله ثم قتلوا او ماتوا ليرزقنهم الله رزقا حسنا وان الله لهو خير الرزقين', 'ذين هجر في سبيل له ثم قتل او مت ليرزقن له رزق حس ون له لهو خير رزق', 'quran', NULL, NULL, 'https://quran.com/22/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1469, 'ولذ لذي ذين هجر جرو في سبي بيل الل لله ثم قتل تلو او متو لير يرز رزق زقن قنه نهم الل لله رزق حسن ون الل لله لهو خير الر لرز رزق زقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1470, 'quran:22:59', 'quran', 'quran', '22:59', 59, 1469, 'Al-Hajj', 'الحج', 'لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٞ', NULL, NULL, 'ليدخلنهم مدخلا يرضونه وان الله لعليم حليم', 'ليدخلن مدخل يرضون ون له لعليم حليم', 'quran', NULL, NULL, 'https://quran.com/22/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1470, 'ليد يدخ دخل خلن لنه نهم مدخ دخل يرض رضو ضون ونه ون الل لله لعل علي ليم حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1471, 'quran:22:60', 'quran', 'quran', '22:60', 60, 1470, 'Al-Hajj', 'الحج', 'ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ', NULL, NULL, 'ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله ان الله لعفو غفور', 'ذلك ومن عقب بمثل م عوقب به ثم بغ عل لينصرن له ان له لعفو غفور', 'quran', NULL, NULL, 'https://quran.com/22/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1471, 'ذلك ومن عقب بمث مثل م عوق وقب به ثم بغي علي ليه لين ينص نصر صرن رنه الل لله ان الل لله لعف عفو غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1472, 'quran:22:61', 'quran', 'quran', '22:61', 61, 1471, 'Al-Hajj', 'الحج', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ', NULL, NULL, 'ذلك بان الله يولج اليل في النهار ويولج النهار في اليل وان الله سميع بصير', 'ذلك بن له يولج يل في نهر يولج نهر في يل ون له سميع بصير', 'quran', NULL, NULL, 'https://quran.com/22/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1472, 'ذلك بن الل لله يول ولج الي ليل في الن لنه نهر ويو يول ولج الن لنه نهر في الي ليل ون الل لله سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1473, 'quran:22:62', 'quran', 'quran', '22:62', 62, 1472, 'Al-Hajj', 'الحج', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ', NULL, NULL, 'ذلك بان الله هو الحق وان ما يدعون من دونه هو البطل وان الله هو العلي الكبير', 'ذلك بن له هو حق ون م يدع من دون هو بطل ون له هو عل كبير', 'quran', NULL, NULL, 'https://quran.com/22/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1473, 'ذلك بن الل لله هو الح لحق ون م يدع دعو عون من دون ونه هو الب لبط بطل ون الل لله هو الع لعل علي الك لكب كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1474, 'quran:22:63', 'quran', 'quran', '22:63', 63, 1473, 'Al-Hajj', 'الحج', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ', NULL, NULL, 'الم تر ان الله انزل من السماء ماء فتصبح الارض مخضره ان الله لطيف خبير', 'الم تر ان له انزل من سمء مء تصبح ارض مخضر ان له لطيف خبير', 'quran', NULL, NULL, 'https://quran.com/22/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1474, 'الم تر ان الل لله انز نزل من الس لسم سمء مء فتص تصب صبح الر لرض مخض خضر ضره ان الل لله لطي طيف خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1475, 'quran:22:64', 'quran', 'quran', '22:64', 64, 1474, 'Al-Hajj', 'الحج', 'لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ', NULL, NULL, 'له ما في السموت وما في الارض وان الله لهو الغني الحميد', 'له م في سموت وم في ارض ون له لهو غن حميد', 'quran', NULL, NULL, 'https://quran.com/22/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1475, 'له م في الس لسم سمو موت وم في الر لرض ون الل لله لهو الغ لغن غني الح لحم حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1476, 'quran:22:65', 'quran', 'quran', '22:65', 65, 1475, 'Al-Hajj', 'الحج', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ', NULL, NULL, 'الم تر ان الله سخر لكم ما في الارض والفلك تجري في البحر بامره ويمسك السماء ان تقع علي الارض الا باذنه ان الله بالناس لرءوف رحيم', 'الم تر ان له سخر لكم م في ارض فلك تجر في بحر بمر يمسك سمء ان تقع عل ارض ال بذن ان له نس لرءوف رحيم', 'quran', NULL, NULL, 'https://quran.com/22/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1476, 'الم تر ان الل لله سخر لكم م في الر لرض ولف لفل فلك تجر جري في الب لبح بحر بمر مره ويم يمس مسك الس لسم سمء ان تقع علي الر لرض ال بذن ذنه ان الل لله بلن لنس لرء رءو ءوف رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1477, 'quran:22:66', 'quran', 'quran', '22:66', 66, 1476, 'Al-Hajj', 'الحج', 'وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ', NULL, NULL, 'وهو الذي احياكم ثم يميتكم ثم يحييكم ان الانسن لكفور', 'وهو ذي احي ثم يميت ثم يحيي ان انسن لكفور', 'quran', NULL, NULL, 'https://quran.com/22/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1477, 'وهو الذ لذي احي حيك يكم ثم يمي ميت يتك تكم ثم يحي حيي ييك يكم ان الن لنس نسن لكف كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1478, 'quran:22:67', 'quran', 'quran', '22:67', 67, 1477, 'Al-Hajj', 'الحج', 'لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ', NULL, NULL, 'لكل امه جعلنا منسكا هم ناسكوه فلا ينزعنك في الامر وادع الي ربك انك لعلي هدي مستقيم', 'لكل ام جعل منسك هم نسكو فل ينزعنك في امر ادع ال ربك انك لعل هد مستقيم', 'quran', NULL, NULL, 'https://quran.com/22/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1478, 'لكل امه جعل علن منس نسك هم نسك سكو كوه فل ينز نزع زعن عنك في الم لمر ودع الي ربك انك لعل علي هدي مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1479, 'quran:22:68', 'quran', 'quran', '22:68', 68, 1478, 'Al-Hajj', 'الحج', 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ', NULL, NULL, 'وان جدلوك فقل الله اعلم بما تعملون', 'ون جدلوك فقل له اعلم بم تعمل', 'quran', NULL, NULL, 'https://quran.com/22/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1479, 'ون جدل دلو لوك فقل الل لله اعل علم بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1480, 'quran:22:69', 'quran', 'quran', '22:69', 69, 1479, 'Al-Hajj', 'الحج', 'ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', NULL, NULL, 'الله يحكم بينكم يوم القيمه فيما كنتم فيه تختلفون', 'له يح بين يوم قيم يم كنتم في تختلف', 'quran', NULL, NULL, 'https://quran.com/22/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1480, 'الل لله يحك حكم بين ينك نكم يوم الق لقي قيم يمه فيم كنت نتم فيه تخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1481, 'quran:22:70', 'quran', 'quran', '22:70', 70, 1480, 'Al-Hajj', 'الحج', 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ', NULL, NULL, 'الم تعلم ان الله يعلم ما في السماء والارض ان ذلك في كتب ان ذلك علي الله يسير', 'الم تعلم ان له يعلم م في سمء ارض ان ذلك في كتب ان ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/22/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1481, 'الم تعل علم ان الل لله يعل علم م في الس لسم سمء ولر لرض ان ذلك في كتب ان ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1482, 'quran:22:71', 'quran', 'quran', '22:71', 71, 1481, 'Al-Hajj', 'الحج', 'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٖ', NULL, NULL, 'ويعبدون من دون الله ما لم ينزل به سلطنا وما ليس لهم به علم وما للظلمين من نصير', 'يعبد من دون له م لم ينزل به سلط وم ليس لهم به علم وم ظلم من نصير', 'quran', NULL, NULL, 'https://quran.com/22/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1482, 'ويع يعب عبد بدو دون من دون الل لله م لم ينز نزل به سلط لطن وم ليس لهم به علم وم للظ لظل ظلم لمي مين من نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1483, 'quran:22:72', 'quran', 'quran', '22:72', 72, 1482, 'Al-Hajj', 'الحج', 'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ', NULL, NULL, 'واذا تتلي عليهم ايتنا بينت تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم ايتنا قل افانبيكم بشر من ذلكم النار وعدها الله الذين كفروا وبيس المصير', 'اذ تتل علي ايت بينت تعرف في جو ذين كفر منكر يكد يسط ذين يتل علي ايت قل افنبي بشر من ذل نر عد له ذين كفر بيس مصير', 'quran', NULL, NULL, 'https://quran.com/22/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1483, 'وذ تتل تلي علي ليه يهم ايت يتن بين ينت تعر عرف في وجو جوه الذ لذي ذين كفر فرو الم لمن منك نكر يكد كدو دون يسط سطو طون بلذ لذي ذين يتل تلو لون علي ليه يهم ايت يتن قل افن فنب نبي بيك يكم بشر من ذلك لكم الن لنر وعد عده الل لله الذ لذي ذين كفر فرو وبي بيس الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1484, 'quran:22:73', 'quran', 'quran', '22:73', 73, 1483, 'Al-Hajj', 'الحج', 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ', NULL, NULL, 'يا ايها الناس ضرب مثل فاستمعوا له ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وان يسلبهم الذباب شيا لا يستنقذوه منه ضعف الطالب والمطلوب', 'ي اي نس ضرب مثل استمع له ان ذين تدع من دون له لن يخلق ذبب ولو اجتمع له ون يسلب ذبب شي ل يستنقذو من ضعف طلب مطلوب', 'quran', NULL, NULL, 'https://quran.com/22/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1484, 'ي ايه الن لنس ضرب مثل فست ستم تمع معو له ان الذ لذي ذين تدع دعو عون من دون الل لله لن يخل خلق لقو ذبب ولو اجت جتم تمع معو له ون يسل سلب لبه بهم الذ لذب ذبب شي ل يست ستن تنق نقذ قذو ذوه منه ضعف الط لطل طلب ولم لمط مطل طلو لوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1485, 'quran:22:74', 'quran', 'quran', '22:74', 74, 1484, 'Al-Hajj', 'الحج', 'مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ', NULL, NULL, 'ما قدروا الله حق قدره ان الله لقوي عزيز', 'م قدر له حق قدر ان له لقو عزيز', 'quran', NULL, NULL, 'https://quran.com/22/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1485, 'م قدر درو الل لله حق قدر دره ان الل لله لقو قوي عزي زيز');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1486, 'quran:22:75', 'quran', 'quran', '22:75', 75, 1485, 'Al-Hajj', 'الحج', 'ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ', NULL, NULL, 'الله يصطفي من المليكه رسلا ومن الناس ان الله سميع بصير', 'له يصطف من مليك رسل ومن نس ان له سميع بصير', 'quran', NULL, NULL, 'https://quran.com/22/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1486, 'الل لله يصط صطف طفي من الم لمل ملي ليك يكه رسل ومن الن لنس ان الل لله سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1487, 'quran:22:76', 'quran', 'quran', '22:76', 76, 1486, 'Al-Hajj', 'الحج', 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', NULL, NULL, 'يعلم ما بين ايديهم وما خلفهم والي الله ترجع الامور', 'يعلم م بين ايدي وم خلف ول له ترجع امور', 'quran', NULL, NULL, 'https://quran.com/22/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1487, 'يعل علم م بين ايد يدي ديه يهم وم خلف لفه فهم ولي الل لله ترج رجع الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1488, 'quran:22:77', 'quran', 'quran', '22:77', 77, 1487, 'Al-Hajj', 'الحج', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ', NULL, NULL, 'يا ايها الذين امنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون', 'ي اي ذين امن اركع اسجد اعبد رب افعل خير لعل تفلح', 'quran', NULL, NULL, 'https://quran.com/22/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1488, 'ي ايه الذ لذي ذين امن منو ارك ركع كعو وسج سجد جدو وعب عبد بدو ربك بكم وفع فعل علو الخ لخي خير لعل علك لكم تفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1489, 'quran:22:78', 'quran', 'quran', '22:78', 78, 1488, 'Al-Hajj', 'الحج', 'وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ', NULL, NULL, 'وجهدوا في الله حق جهاده هو اجتباكم وما جعل عليكم في الدين من حرج مله ابيكم ابرهيم هو سماكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء علي الناس فاقيموا الصلاه واتوا الزكاه واعتصموا بالله هو مولاكم فنعم المولي ونعم النصير', 'جهد في له حق جهد هو اجتب وم جعل علي في دين من حرج مل ابي ابرهيم هو سم مسلم من قبل وف هذ ليك رسول شهيد علي تكون شهدء عل نس اقيم صل ات زك اعتصم له هو مول نعم مول نعم نصير', 'quran', NULL, NULL, 'https://quran.com/22/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1489, 'وجه جهد هدو في الل لله حق جهد هده هو اجت جتب تبك بكم وم جعل علي ليك يكم في الد لدي دين من حرج مله ابي بيك يكم ابر بره رهي هيم هو سمك مكم الم لمس مسل سلم لمي مين من قبل وفي هذ ليك يكو كون الر لرس رسو سول شهي هيد علي ليك يكم وتك تكو كون ونو شهد هدء علي الن لنس فقي قيم يمو الص لصل صله وتو الز لزك زكه وعت عتص تصم صمو بلل لله هو مول ولك لكم فنع نعم الم لمو مول ولي ونع نعم الن لنص نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1490, 'quran:23:1', 'quran', 'quran', '23:1', 1, 1489, 'Al-Mu''minun', 'المؤمنون', 'قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ', NULL, NULL, 'قد افلح المومنون', 'قد افلح مومن', 'quran', NULL, NULL, 'https://quran.com/23/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1490, 'قد افل فلح الم لمو موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1491, 'quran:23:2', 'quran', 'quran', '23:2', 2, 1490, 'Al-Mu''minun', 'المؤمنون', 'ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ', NULL, NULL, 'الذين هم في صلاتهم خشعون', 'ذين هم في صلت خشع', 'quran', NULL, NULL, 'https://quran.com/23/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1491, 'الذ لذي ذين هم في صلت لته تهم خشع شعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1492, 'quran:23:3', 'quran', 'quran', '23:3', 3, 1491, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ', NULL, NULL, 'والذين هم عن اللغو معرضون', 'ذين هم عن لغو معرض', 'quran', NULL, NULL, 'https://quran.com/23/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1492, 'ولذ لذي ذين هم عن الل للغ لغو معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1493, 'quran:23:4', 'quran', 'quran', '23:4', 4, 1492, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ', NULL, NULL, 'والذين هم للزكاه فعلون', 'ذين هم زك عل', 'quran', NULL, NULL, 'https://quran.com/23/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1493, 'ولذ لذي ذين هم للز لزك زكه فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1494, 'quran:23:5', 'quran', 'quran', '23:5', 5, 1493, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ', NULL, NULL, 'والذين هم لفروجهم حفظون', 'ذين هم لفروج حفظ', 'quran', NULL, NULL, 'https://quran.com/23/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1494, 'ولذ لذي ذين هم لفر فرو روج وجه جهم حفظ فظو ظون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1495, 'quran:23:6', 'quran', 'quran', '23:6', 6, 1494, 'Al-Mu''minun', 'المؤمنون', 'إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ', NULL, NULL, 'الا علي ازوجهم او ما ملكت ايمنهم فانهم غير ملومين', 'ال عل ازوج او م ملكت ايمن ان غير ملوم', 'quran', NULL, NULL, 'https://quran.com/23/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1495, 'ال علي ازو زوج وجه جهم او م ملك لكت ايم يمن منه نهم فنه نهم غير ملو لوم ومي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1496, 'quran:23:7', 'quran', 'quran', '23:7', 7, 1495, 'Al-Mu''minun', 'المؤمنون', 'فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ', NULL, NULL, 'فمن ابتغي وراء ذلك فاوليك هم العادون', 'فمن ابتغ رء ذلك اوليك هم عد', 'quran', NULL, NULL, 'https://quran.com/23/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1496, 'فمن ابت بتغ تغي ورء ذلك فول ولي ليك هم الع لعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1497, 'quran:23:8', 'quran', 'quran', '23:8', 8, 1496, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ', NULL, NULL, 'والذين هم لامنتهم وعهدهم رعون', 'ذين هم لمنت عهد رع', 'quran', NULL, NULL, 'https://quran.com/23/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1497, 'ولذ لذي ذين هم لمن منت نته تهم وعه عهد هده دهم رعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1498, 'quran:23:9', 'quran', 'quran', '23:9', 9, 1497, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ', NULL, NULL, 'والذين هم علي صلوتهم يحافظون', 'ذين هم عل صلوت يحفظ', 'quran', NULL, NULL, 'https://quran.com/23/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1498, 'ولذ لذي ذين هم علي صلو لوت وته تهم يحف حفظ فظو ظون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1499, 'quran:23:10', 'quran', 'quran', '23:10', 10, 1498, 'Al-Mu''minun', 'المؤمنون', 'أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ', NULL, NULL, 'اوليك هم الورثون', 'اوليك هم ورث', 'quran', NULL, NULL, 'https://quran.com/23/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1499, 'اول ولي ليك هم الو لور ورث رثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1500, 'quran:23:11', 'quran', 'quran', '23:11', 11, 1499, 'Al-Mu''minun', 'المؤمنون', 'ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'الذين يرثون الفردوس هم فيها خلدون', 'ذين يرث فردوس هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/23/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1500, 'الذ لذي ذين يرث رثو ثون الف لفر فرد ردو دوس هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1501, 'quran:23:12', 'quran', 'quran', '23:12', 12, 1500, 'Al-Mu''minun', 'المؤمنون', 'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ', NULL, NULL, 'ولقد خلقنا الانسن من سلله من طين', 'لقد خلق انسن من سلل من طين', 'quran', NULL, NULL, 'https://quran.com/23/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1501, 'ولق لقد خلق لقن الن لنس نسن من سلل لله من طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1502, 'quran:23:13', 'quran', 'quran', '23:13', 13, 1501, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ', NULL, NULL, 'ثم جعلنه نطفه في قرار مكين', 'ثم جعلن نطف في قرر مك', 'quran', NULL, NULL, 'https://quran.com/23/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1502, 'ثم جعل علن لنه نطف طفه في قرر مكي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1503, 'quran:23:14', 'quran', 'quran', '23:14', 14, 1502, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ', NULL, NULL, 'ثم خلقنا النطفه علقه فخلقنا العلقه مضغه فخلقنا المضغه عظما فكسونا العظم لحما ثم انشانه خلقا اخر فتبارك الله احسن الخلقين', 'ثم خلق نطف علق خلق علق مضغ خلق مضغ عظم كسو عظم لحم ثم انشن خلق اخر تبرك له احسن خلق', 'quran', NULL, NULL, 'https://quran.com/23/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1503, 'ثم خلق لقن الن لنط نطف طفه علق لقه فخل خلق لقن الع لعل علق لقه مضغ ضغه فخل خلق لقن الم لمض مضغ ضغه عظم فكس كسو سون الع لعظ عظم لحم ثم انش نشن شنه خلق اخر فتب تبر برك الل لله احس حسن الخ لخل خلق لقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1504, 'quran:23:15', 'quran', 'quran', '23:15', 15, 1503, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ', NULL, NULL, 'ثم انكم بعد ذلك لميتون', 'ثم ان بعد ذلك لميت', 'quran', NULL, NULL, 'https://quran.com/23/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1504, 'ثم انك نكم بعد ذلك لمي ميت يتو تون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1505, 'quran:23:16', 'quran', 'quran', '23:16', 16, 1504, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ', NULL, NULL, 'ثم انكم يوم القيمه تبعثون', 'ثم ان يوم قيم تبعث', 'quran', NULL, NULL, 'https://quran.com/23/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1505, 'ثم انك نكم يوم الق لقي قيم يمه تبع بعث عثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1506, 'quran:23:17', 'quran', 'quran', '23:17', 17, 1505, 'Al-Mu''minun', 'المؤمنون', 'وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ', NULL, NULL, 'ولقد خلقنا فوقكم سبع طرايق وما كنا عن الخلق غفلين', 'لقد خلق وق سبع طريق وم كن عن خلق غفل', 'quran', NULL, NULL, 'https://quran.com/23/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1506, 'ولق لقد خلق لقن فوق وقك قكم سبع طري ريق وم كن عن الخ لخل خلق غفل فلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1507, 'quran:23:18', 'quran', 'quran', '23:18', 18, 1506, 'Al-Mu''minun', 'المؤمنون', 'وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ', NULL, NULL, 'وانزلنا من السماء ماء بقدر فاسكنه في الارض وانا علي ذهاب به لقدرون', 'انزل من سمء مء بقدر اسكن في ارض ان عل ذهب به لقدر', 'quran', NULL, NULL, 'https://quran.com/23/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1507, 'ونز نزل زلن من الس لسم سمء مء بقد قدر فسك سكن كنه في الر لرض ون علي ذهب به لقد قدر درو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1508, 'quran:23:19', 'quran', 'quran', '23:19', 19, 1507, 'Al-Mu''minun', 'المؤمنون', 'فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ', NULL, NULL, 'فانشانا لكم به جنت من نخيل واعنب لكم فيها فوكه كثيره ومنها تاكلون', 'انش لكم به جنت من نخيل اعنب لكم يه وك كثير من تكل', 'quran', NULL, NULL, 'https://quran.com/23/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1508, 'فنش نشن لكم به جنت من نخي خيل وعن عنب لكم فيه فوك وكه كثي ثير يره ومن منه تكل كلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1509, 'quran:23:20', 'quran', 'quran', '23:20', 20, 1508, 'Al-Mu''minun', 'المؤمنون', 'وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ', NULL, NULL, 'وشجره تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين', 'شجر تخرج من طور سينء تنبت دهن صبغ اكل', 'quran', NULL, NULL, 'https://quran.com/23/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1509, 'وشج شجر جره تخر خرج من طور سين ينء تنب نبت بلد لده دهن وصب صبغ للك لكل كلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1510, 'quran:23:21', 'quran', 'quran', '23:21', 21, 1509, 'Al-Mu''minun', 'المؤمنون', 'وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ', NULL, NULL, 'وان لكم في الانعم لعبره نسقيكم مما في بطونها ولكم فيها منفع كثيره ومنها تاكلون', 'ون لكم في انعم لعبر نسقي مم في بطون لكم يه منفع كثير من تكل', 'quran', NULL, NULL, 'https://quran.com/23/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1510, 'ون لكم في الن لنع نعم لعب عبر بره نسق سقي قيك يكم مم في بطو طون ونه ولك لكم فيه منف نفع كثي ثير يره ومن منه تكل كلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1511, 'quran:23:22', 'quran', 'quran', '23:22', 22, 1510, 'Al-Mu''minun', 'المؤمنون', 'وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ', NULL, NULL, 'وعليها وعلي الفلك تحملون', 'علي عل فلك تحمل', 'quran', NULL, NULL, 'https://quran.com/23/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1511, 'وعل علي ليه وعل علي الف لفل فلك تحم حمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1512, 'quran:23:23', 'quran', 'quran', '23:23', 23, 1511, 'Al-Mu''minun', 'المؤمنون', 'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ', NULL, NULL, 'ولقد ارسلنا نوحا الي قومه فقال يا قوم اعبدوا الله ما لكم من اله غيره افلا تتقون', 'لقد ارسل نوح ال قوم قل ي قوم اعبد له م لكم من ال غير افل تتق', 'quran', NULL, NULL, 'https://quran.com/23/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1512, 'ولق لقد ارس رسل سلن نوح الي قوم ومه فقل ي قوم اعب عبد بدو الل لله م لكم من اله غير يره افل تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1513, 'quran:23:24', 'quran', 'quran', '23:24', 24, 1512, 'Al-Mu''minun', 'المؤمنون', 'فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ', NULL, NULL, 'فقال الملوا الذين كفروا من قومه ما هذا الا بشر مثلكم يريد ان يتفضل عليكم ولو شاء الله لانزل مليكه ما سمعنا بهذا في اباينا الاولين', 'قل مل ذين كفر من قوم م هذ ال بشر مثل يريد ان يتفضل علي ولو شء له لنزل مليك م سمع بهذ في ابي اول', 'quran', NULL, NULL, 'https://quran.com/23/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1513, 'فقل الم لمل ملو الذ لذي ذين كفر فرو من قوم ومه م هذ ال بشر مثل ثلك لكم يري ريد ان يتف تفض فضل علي ليك يكم ولو شء الل لله لنز نزل ملي ليك يكه م سمع معن بهذ في ابي بين الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1514, 'quran:23:25', 'quran', 'quran', '23:25', 25, 1513, 'Al-Mu''minun', 'المؤمنون', 'إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ', NULL, NULL, 'ان هو الا رجل به جنه فتربصوا به حتي حين', 'ان هو ال رجل به جن تربص به حت حين', 'quran', NULL, NULL, 'https://quran.com/23/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1514, 'ان هو ال رجل به جنه فتر ترب ربص بصو به حتي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1515, 'quran:23:26', 'quran', 'quran', '23:26', 26, 1514, 'Al-Mu''minun', 'المؤمنون', 'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ', NULL, NULL, 'قال رب انصرني بما كذبون', 'قل رب انصرن بم كذب', 'quran', NULL, NULL, 'https://quran.com/23/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1515, 'قل رب انص نصر صرن رني بم كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1516, 'quran:23:27', 'quran', 'quran', '23:27', 27, 1515, 'Al-Mu''minun', 'المؤمنون', 'فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ', NULL, NULL, 'فاوحينا اليه ان اصنع الفلك باعيننا ووحينا فاذا جاء امرنا وفار التنور فاسلك فيها من كل زوجين اثنين واهلك الا من سبق عليه القول منهم ولا تخطبني في الذين ظلموا انهم مغرقون', 'اوحي يه ان اصنع فلك بعين وحي اذ جء امر فر تنور اسلك يه من كل زوج اثن اهلك ال من سبق عل قول من ول تخطبن في ذين ظلم ان مغرق', 'quran', NULL, NULL, 'https://quran.com/23/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1516, 'فوح وحي حين الي ليه ان اصن صنع الف لفل فلك بعي عين ينن ووح وحي حين فذ جء امر مرن وفر الت لتن تنو نور فسل سلك فيه من كل زوج وجي جين اثن ثني نين وهل هلك ال من سبق علي ليه الق لقو قول منه نهم ول تخط خطب طبن بني في الذ لذي ذين ظلم لمو انه نهم مغر غرق رقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1517, 'quran:23:28', 'quran', 'quran', '23:28', 28, 1516, 'Al-Mu''minun', 'المؤمنون', 'فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ', NULL, NULL, 'فاذا استويت انت ومن معك علي الفلك فقل الحمد لله الذي نجانا من القوم الظلمين', 'اذ استويت انت ومن معك عل فلك فقل حمد لل ذي نج من قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/23/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1517, 'فذ است ستو توي ويت انت ومن معك علي الف لفل فلك فقل الح لحم حمد لله الذ لذي نجن من الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1518, 'quran:23:29', 'quran', 'quran', '23:29', 29, 1517, 'Al-Mu''minun', 'المؤمنون', 'وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ', NULL, NULL, 'وقل رب انزلني منزلا مباركا وانت خير المنزلين', 'وقل رب انزلن منزل مبرك انت خير منزل', 'quran', NULL, NULL, 'https://quran.com/23/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1518, 'وقل رب انز نزل زلن لني منز نزل مبر برك ونت خير الم لمن منز نزل زلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1519, 'quran:23:30', 'quran', 'quran', '23:30', 30, 1518, 'Al-Mu''minun', 'المؤمنون', 'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ', NULL, NULL, 'ان في ذلك لايت وان كنا لمبتلين', 'ان في ذلك ليت ون كن لمبتل', 'quran', NULL, NULL, 'https://quran.com/23/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1519, 'ان في ذلك ليت ون كن لمب مبت بتل تلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1520, 'quran:23:31', 'quran', 'quran', '23:31', 31, 1519, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ', NULL, NULL, 'ثم انشانا من بعدهم قرنا اخرين', 'ثم انش من بعد قر اخر', 'quran', NULL, NULL, 'https://quran.com/23/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1520, 'ثم انش نشن من بعد عده دهم قرن اخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1521, 'quran:23:32', 'quran', 'quran', '23:32', 32, 1520, 'Al-Mu''minun', 'المؤمنون', 'فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ', NULL, NULL, 'فارسلنا فيهم رسولا منهم ان اعبدوا الله ما لكم من اله غيره افلا تتقون', 'ارسل يهم رسول من ان اعبد له م لكم من ال غير افل تتق', 'quran', NULL, NULL, 'https://quran.com/23/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1521, 'فرس رسل سلن فيه يهم رسو سول منه نهم ان اعب عبد بدو الل لله م لكم من اله غير يره افل تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1522, 'quran:23:33', 'quran', 'quran', '23:33', 33, 1521, 'Al-Mu''minun', 'المؤمنون', 'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ', NULL, NULL, 'وقال الملا من قومه الذين كفروا وكذبوا بلقاء الاخره واترفنهم في الحياه الدنيا ما هذا الا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون', 'قل مل من قوم ذين كفر كذب بلقء اخر اترفن في حي دني م هذ ال بشر مثل يكل مم تكل من يشرب مم تشرب', 'quran', NULL, NULL, 'https://quran.com/23/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1522, 'وقل الم لمل من قوم ومه الذ لذي ذين كفر فرو وكذ كذب ذبو بلق لقء الخ لخر خره وتر ترف رفن فنه نهم في الح لحي حيه الد لدن دني م هذ ال بشر مثل ثلك لكم يكل مم تكل كلو لون منه ويش يشر شرب مم تشر شرب ربو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1523, 'quran:23:34', 'quran', 'quran', '23:34', 34, 1522, 'Al-Mu''minun', 'المؤمنون', 'وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ', NULL, NULL, 'ولين اطعتم بشرا مثلكم انكم اذا لخسرون', 'لين اطعتم بشر مثل ان اذ لخسر', 'quran', NULL, NULL, 'https://quran.com/23/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1523, 'ولي لين اطع طعت عتم بشر مثل ثلك لكم انك نكم اذ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1524, 'quran:23:35', 'quran', 'quran', '23:35', 35, 1523, 'Al-Mu''minun', 'المؤمنون', 'أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ', NULL, NULL, 'ايعدكم انكم اذا متم وكنتم ترابا وعظما انكم مخرجون', 'ايعد ان اذ متم كنتم ترب عظم ان مخرج', 'quran', NULL, NULL, 'https://quran.com/23/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1524, 'ايع يعد عدك دكم انك نكم اذ متم وكن كنت نتم ترب وعظ عظم انك نكم مخر خرج رجو جون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1525, 'quran:23:36', 'quran', 'quran', '23:36', 36, 1524, 'Al-Mu''minun', 'المؤمنون', 'هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ', NULL, NULL, 'هيهات هيهات لما توعدون', 'هيه هيه لم توعد', 'quran', NULL, NULL, 'https://quran.com/23/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1525, 'هيه يهت هيه يهت لم توع وعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1526, 'quran:23:37', 'quran', 'quran', '23:37', 37, 1525, 'Al-Mu''minun', 'المؤمنون', 'إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ', NULL, NULL, 'ان هي الا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين', 'ان هي ال حيت دني نموت نحي وم نحن بمبعوث', 'quran', NULL, NULL, 'https://quran.com/23/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1526, 'ان هي ال حيت يتن الد لدن دني نمو موت ونح نحي وم نحن بمب مبع بعو عوث وثي ثين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1527, 'quran:23:38', 'quran', 'quran', '23:38', 38, 1526, 'Al-Mu''minun', 'المؤمنون', 'إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ', NULL, NULL, 'ان هو الا رجل افتري علي الله كذبا وما نحن له بمومنين', 'ان هو ال رجل افتر عل له كذب وم نحن له بمومن', 'quran', NULL, NULL, 'https://quran.com/23/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1527, 'ان هو ال رجل افت فتر تري علي الل لله كذب وم نحن له بمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1528, 'quran:23:39', 'quran', 'quran', '23:39', 39, 1527, 'Al-Mu''minun', 'المؤمنون', 'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ', NULL, NULL, 'قال رب انصرني بما كذبون', 'قل رب انصرن بم كذب', 'quran', NULL, NULL, 'https://quran.com/23/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1528, 'قل رب انص نصر صرن رني بم كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1529, 'quran:23:40', 'quran', 'quran', '23:40', 40, 1528, 'Al-Mu''minun', 'المؤمنون', 'قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ', NULL, NULL, 'قال عما قليل ليصبحن ندمين', 'قل عم قليل ليصبحن ندم', 'quran', NULL, NULL, 'https://quran.com/23/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1529, 'قل عم قلي ليل ليص يصب صبح بحن ندم دمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1530, 'quran:23:41', 'quran', 'quran', '23:41', 41, 1529, 'Al-Mu''minun', 'المؤمنون', 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ', NULL, NULL, 'فاخذتهم الصيحه بالحق فجعلنهم غثاء فبعدا للقوم الظلمين', 'اخذت صيح حق جعلن غثء بعد قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/23/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1530, 'فخذ خذت ذته تهم الص لصي صيح يحه بلح لحق فجع جعل علن لنه نهم غثء فبع بعد للق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1531, 'quran:23:42', 'quran', 'quran', '23:42', 42, 1530, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ', NULL, NULL, 'ثم انشانا من بعدهم قرونا اخرين', 'ثم انش من بعد قرو اخر', 'quran', NULL, NULL, 'https://quran.com/23/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1531, 'ثم انش نشن من بعد عده دهم قرو رون اخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1532, 'quran:23:43', 'quran', 'quran', '23:43', 43, 1531, 'Al-Mu''minun', 'المؤمنون', 'مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ', NULL, NULL, 'ما تسبق من امه اجلها وما يستخرون', 'م تسبق من ام اجل وم يستخر', 'quran', NULL, NULL, 'https://quran.com/23/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1532, 'م تسب سبق من امه اجل جله وم يست ستخ تخر خرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1533, 'quran:23:44', 'quran', 'quran', '23:44', 44, 1532, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ', NULL, NULL, 'ثم ارسلنا رسلنا تترا كل ما جاء امه رسولها كذبوه فاتبعنا بعضهم بعضا وجعلنهم احاديث فبعدا لقوم لا يومنون', 'ثم ارسل رسل تتر كل م جء ام رسول كذبو اتبع بعض بعض جعلن احديث بعد لقوم ل يومن', 'quran', NULL, NULL, 'https://quran.com/23/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1533, 'ثم ارس رسل سلن رسل سلن تتر كل م جء امه رسو سول وله كذب ذبو بوه فتب تبع بعن بعض عضه ضهم بعض وجع جعل علن لنه نهم احد حدي ديث فبع بعد لقو قوم ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1534, 'quran:23:45', 'quran', 'quran', '23:45', 45, 1533, 'Al-Mu''minun', 'المؤمنون', 'ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ', NULL, NULL, 'ثم ارسلنا موسي واخاه هرون بايتنا وسلطن مبين', 'ثم ارسل موس اخ هر بيت سلطن مب', 'quran', NULL, NULL, 'https://quran.com/23/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1534, 'ثم ارس رسل سلن موس وسي وخه هرو رون بيت يتن وسل سلط لطن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1535, 'quran:23:46', 'quran', 'quran', '23:46', 46, 1534, 'Al-Mu''minun', 'المؤمنون', 'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ', NULL, NULL, 'الي فرعون وملايه فاستكبروا وكانوا قوما عالين', 'ال رع مل استكبر كن قوم عل', 'quran', NULL, NULL, 'https://quran.com/23/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1535, 'الي فرع رعو عون ومل ملي ليه فست ستك تكب كبر برو وكن كنو قوم علي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1536, 'quran:23:47', 'quran', 'quran', '23:47', 47, 1535, 'Al-Mu''minun', 'المؤمنون', 'فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ', NULL, NULL, 'فقالوا انومن لبشرين مثلنا وقومهما لنا عبدون', 'قل انومن لبشر مثل قومهم لن عبد', 'quran', NULL, NULL, 'https://quran.com/23/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1536, 'فقل قلو انو نوم ومن لبش بشر شري رين مثل ثلن وقو قوم ومه مهم لن عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1537, 'quran:23:48', 'quran', 'quran', '23:48', 48, 1536, 'Al-Mu''minun', 'المؤمنون', 'فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ', NULL, NULL, 'فكذبوهما فكانوا من المهلكين', 'كذبوهم كن من مهلك', 'quran', NULL, NULL, 'https://quran.com/23/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1537, 'فكذ كذب ذبو بوه وهم فكن كنو من الم لمه مهل هلك لكي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1538, 'quran:23:49', 'quran', 'quran', '23:49', 49, 1537, 'Al-Mu''minun', 'المؤمنون', 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ', NULL, NULL, 'ولقد اتينا موسي الكتب لعلهم يهتدون', 'لقد اتي موس كتب لعل يهتد', 'quran', NULL, NULL, 'https://quran.com/23/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1538, 'ولق لقد اتي تين موس وسي الك لكت كتب لعل عله لهم يهت هتد تدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1539, 'quran:23:50', 'quran', 'quran', '23:50', 50, 1538, 'Al-Mu''minun', 'المؤمنون', 'وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ', NULL, NULL, 'وجعلنا ابن مريم وامه ايه واوينهما الي ربوه ذات قرار ومعين', 'جعل ابن مريم ام اي اوينهم ال ربو ذت قرر مع', 'quran', NULL, NULL, 'https://quran.com/23/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1539, 'وجع جعل علن ابن مري ريم ومه ايه ووي وين ينه نهم الي ربو بوه ذت قرر ومع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1540, 'quran:23:51', 'quran', 'quran', '23:51', 51, 1539, 'Al-Mu''minun', 'المؤمنون', 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ', NULL, NULL, 'يا ايها الرسل كلوا من الطيبت واعملوا صلحا اني بما تعملون عليم', 'ي اي رسل كل من طيبت اعمل صلح ان بم تعمل عليم', 'quran', NULL, NULL, 'https://quran.com/23/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1540, 'ي ايه الر لرس رسل كلو من الط لطي طيب يبت وعم عمل ملو صلح اني بم تعم عمل ملو لون علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1541, 'quran:23:52', 'quran', 'quran', '23:52', 52, 1540, 'Al-Mu''minun', 'المؤمنون', 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ', NULL, NULL, 'وان هذه امتكم امه وحده وانا ربكم فاتقون', 'ون هذ امت ام حد ان رب اتق', 'quran', NULL, NULL, 'https://quran.com/23/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1541, 'ون هذه امت متك تكم امه وحد حده ون ربك بكم فتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1542, 'quran:23:53', 'quran', 'quran', '23:53', 53, 1541, 'Al-Mu''minun', 'المؤمنون', 'فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ', NULL, NULL, 'فتقطعوا امرهم بينهم زبرا كل حزب بما لديهم فرحون', 'تقطع امر بين زبر كل حزب بم لدي رح', 'quran', NULL, NULL, 'https://quran.com/23/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1542, 'فتق تقط قطع طعو امر مره رهم بين ينه نهم زبر كل حزب بم لدي ديه يهم فرح رحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1543, 'quran:23:54', 'quran', 'quran', '23:54', 54, 1542, 'Al-Mu''minun', 'المؤمنون', 'فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ', NULL, NULL, 'فذرهم في غمرتهم حتي حين', 'ذر في غمرت حت حين', 'quran', NULL, NULL, 'https://quran.com/23/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1543, 'فذر ذره رهم في غمر مرت رته تهم حتي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1544, 'quran:23:55', 'quran', 'quran', '23:55', 55, 1543, 'Al-Mu''minun', 'المؤمنون', 'أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ', NULL, NULL, 'ايحسبون انما نمدهم به من مال وبنين', 'ايحسب انم نمد به من مل بن', 'quran', NULL, NULL, 'https://quran.com/23/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1544, 'ايح يحس حسب سبو بون انم نمد مده دهم به من مل وبن بني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1545, 'quran:23:56', 'quran', 'quran', '23:56', 56, 1544, 'Al-Mu''minun', 'المؤمنون', 'نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ', NULL, NULL, 'نسارع لهم في الخيرت بل لا يشعرون', 'نسرع لهم في خيرت بل ل يشعر', 'quran', NULL, NULL, 'https://quran.com/23/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1545, 'نسر سرع لهم في الخ لخي خير يرت بل ل يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1546, 'quran:23:57', 'quran', 'quran', '23:57', 57, 1545, 'Al-Mu''minun', 'المؤمنون', 'إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ', NULL, NULL, 'ان الذين هم من خشيه ربهم مشفقون', 'ان ذين هم من خش رب مشفق', 'quran', NULL, NULL, 'https://quran.com/23/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1546, 'ان الذ لذي ذين هم من خشي شيه ربه بهم مشف شفق فقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1547, 'quran:23:58', 'quran', 'quran', '23:58', 58, 1546, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ', NULL, NULL, 'والذين هم بايت ربهم يومنون', 'ذين هم بيت رب يومن', 'quran', NULL, NULL, 'https://quran.com/23/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1547, 'ولذ لذي ذين هم بيت ربه بهم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1548, 'quran:23:59', 'quran', 'quran', '23:59', 59, 1547, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ', NULL, NULL, 'والذين هم بربهم لا يشركون', 'ذين هم برب ل يشرك', 'quran', NULL, NULL, 'https://quran.com/23/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1548, 'ولذ لذي ذين هم برب ربه بهم ل يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1549, 'quran:23:60', 'quran', 'quran', '23:60', 60, 1548, 'Al-Mu''minun', 'المؤمنون', 'وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ', NULL, NULL, 'والذين يوتون ما اتوا وقلوبهم وجله انهم الي ربهم رجعون', 'ذين يوت م ات قلوب جل ان ال رب رجع', 'quran', NULL, NULL, 'https://quran.com/23/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1549, 'ولذ لذي ذين يوت وتو تون م اتو وقل قلو لوب وبه بهم وجل جله انه نهم الي ربه بهم رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1550, 'quran:23:61', 'quran', 'quran', '23:61', 61, 1549, 'Al-Mu''minun', 'المؤمنون', 'أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ', NULL, NULL, 'اوليك يسرعون في الخيرت وهم لها سبقون', 'اوليك يسرع في خيرت وهم له سبق', 'quran', NULL, NULL, 'https://quran.com/23/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1550, 'اول ولي ليك يسر سرع رعو عون في الخ لخي خير يرت وهم له سبق بقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1551, 'quran:23:62', 'quran', 'quran', '23:62', 62, 1550, 'Al-Mu''minun', 'المؤمنون', 'وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'ولا نكلف نفسا الا وسعها ولدينا كتب ينطق بالحق وهم لا يظلمون', 'ول نكلف نفس ال سع لدي كتب ينطق حق وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/23/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1551, 'ول نكل كلف نفس ال وسع سعه ولد لدي دين كتب ينط نطق بلح لحق وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1552, 'quran:23:63', 'quran', 'quran', '23:63', 63, 1551, 'Al-Mu''minun', 'المؤمنون', 'بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ', NULL, NULL, 'بل قلوبهم في غمره من هذا ولهم اعمل من دون ذلك هم لها عملون', 'بل قلوب في غمر من هذ لهم اعمل من دون ذلك هم له عمل', 'quran', NULL, NULL, 'https://quran.com/23/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1552, 'بل قلو لوب وبه بهم في غمر مره من هذ وله لهم اعم عمل من دون ذلك هم له عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1553, 'quran:23:64', 'quran', 'quran', '23:64', 64, 1552, 'Al-Mu''minun', 'المؤمنون', 'حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ', NULL, NULL, 'حتي اذا اخذنا مترفيهم بالعذاب اذا هم يجرون', 'حت اذ اخذ مترفي عذب اذ هم يجر', 'quran', NULL, NULL, 'https://quran.com/23/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1553, 'حتي اذ اخذ خذن متر ترف رفي فيه يهم بلع لعذ عذب اذ هم يجر جرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1554, 'quran:23:65', 'quran', 'quran', '23:65', 65, 1553, 'Al-Mu''minun', 'المؤمنون', 'لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', NULL, NULL, 'لا تجروا اليوم انكم منا لا تنصرون', 'ل تجر يوم ان من ل تنصر', 'quran', NULL, NULL, 'https://quran.com/23/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1554, 'ل تجر جرو الي ليو يوم انك نكم من ل تنص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1555, 'quran:23:66', 'quran', 'quran', '23:66', 66, 1554, 'Al-Mu''minun', 'المؤمنون', 'قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ', NULL, NULL, 'قد كانت ايتي تتلي عليكم فكنتم علي اعقبكم تنكصون', 'قد كنت ايت تتل علي كنتم عل اعقب تنكص', 'quran', NULL, NULL, 'https://quran.com/23/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1555, 'قد كنت ايت يتي تتل تلي علي ليك يكم فكن كنت نتم علي اعق عقب قبك بكم تنك نكص كصو صون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1556, 'quran:23:67', 'quran', 'quran', '23:67', 67, 1555, 'Al-Mu''minun', 'المؤمنون', 'مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ', NULL, NULL, 'مستكبرين به سمرا تهجرون', 'مستكبر به سمر تهجر', 'quran', NULL, NULL, 'https://quran.com/23/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1556, 'مست ستك تكب كبر بري رين به سمر تهج هجر جرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1557, 'quran:23:68', 'quran', 'quran', '23:68', 68, 1556, 'Al-Mu''minun', 'المؤمنون', 'أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ', NULL, NULL, 'افلم يدبروا القول ام جاءهم ما لم يات اباءهم الاولين', 'افلم يدبر قول ام جء م لم يت ابء اول', 'quran', NULL, NULL, 'https://quran.com/23/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1557, 'افل فلم يدب دبر برو الق لقو قول ام جءه ءهم م لم يت ابء بءه ءهم الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1558, 'quran:23:69', 'quran', 'quran', '23:69', 69, 1557, 'Al-Mu''minun', 'المؤمنون', 'أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ', NULL, NULL, 'ام لم يعرفوا رسولهم فهم له منكرون', 'ام لم يعرف رسول فهم له منكر', 'quran', NULL, NULL, 'https://quran.com/23/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1558, 'ام لم يعر عرف رفو رسو سول وله لهم فهم له منك نكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1559, 'quran:23:70', 'quran', 'quran', '23:70', 70, 1558, 'Al-Mu''minun', 'المؤمنون', 'أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ', NULL, NULL, 'ام يقولون به جنه بل جاءهم بالحق واكثرهم للحق كرهون', 'ام يقول به جن بل جء حق اكثر حق كره', 'quran', NULL, NULL, 'https://quran.com/23/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1559, 'ام يقو قول ولو لون به جنه بل جءه ءهم بلح لحق وكث كثر ثره رهم للح لحق كره رهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1560, 'quran:23:71', 'quran', 'quran', '23:71', 71, 1559, 'Al-Mu''minun', 'المؤمنون', 'وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ', NULL, NULL, 'ولو اتبع الحق اهواءهم لفسدت السموت والارض ومن فيهن بل اتينهم بذكرهم فهم عن ذكرهم معرضون', 'ولو اتبع حق اهوء لفسدت سموت ارض ومن يهن بل اتين بذكر فهم عن ذكر معرض', 'quran', NULL, NULL, 'https://quran.com/23/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1560, 'ولو اتب تبع الح لحق اهو هوء وءه ءهم لفس فسد سدت الس لسم سمو موت ولر لرض ومن فيه يهن بل اتي تين ينه نهم بذك ذكر كره رهم فهم عن ذكر كره رهم معر عرض رضو ضون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1561, 'quran:23:72', 'quran', 'quran', '23:72', 72, 1560, 'Al-Mu''minun', 'المؤمنون', 'أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ', NULL, NULL, 'ام تسلهم خرجا فخراج ربك خير وهو خير الرزقين', 'ام تسل خرج خرج ربك خير وهو خير رزق', 'quran', NULL, NULL, 'https://quran.com/23/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1561, 'ام تسل سله لهم خرج فخر خرج ربك خير وهو خير الر لرز رزق زقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1562, 'quran:23:73', 'quran', 'quran', '23:73', 73, 1561, 'Al-Mu''minun', 'المؤمنون', 'وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', NULL, NULL, 'وانك لتدعوهم الي صرط مستقيم', 'انك لتدعو ال صرط مستقيم', 'quran', NULL, NULL, 'https://quran.com/23/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1562, 'ونك لتد تدع دعو عوه وهم الي صرط مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1563, 'quran:23:74', 'quran', 'quran', '23:74', 74, 1562, 'Al-Mu''minun', 'المؤمنون', 'وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', NULL, NULL, 'وان الذين لا يومنون بالاخره عن الصرط لنكبون', 'ون ذين ل يومن اخر عن صرط لنكب', 'quran', NULL, NULL, 'https://quran.com/23/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1563, 'ون الذ لذي ذين ل يوم ومن منو نون بلخ لخر خره عن الص لصر صرط لنك نكب كبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1564, 'quran:23:75', 'quran', 'quran', '23:75', 75, 1563, 'Al-Mu''minun', 'المؤمنون', 'وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', NULL, NULL, 'ولو رحمنهم وكشفنا ما بهم من ضر للجوا في طغينهم يعمهون', 'ولو رحمن كشف م بهم من ضر جو في طغين يعمه', 'quran', NULL, NULL, 'https://quran.com/23/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1564, 'ولو رحم حمن منه نهم وكش كشف شفن م بهم من ضر للج لجو في طغي غين ينه نهم يعم عمه مهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1565, 'quran:23:76', 'quran', 'quran', '23:76', 76, 1564, 'Al-Mu''minun', 'المؤمنون', 'وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ', NULL, NULL, 'ولقد اخذنهم بالعذاب فما استكانوا لربهم وما يتضرعون', 'لقد اخذن عذب فم استكن لرب وم يتضرع', 'quran', NULL, NULL, 'https://quran.com/23/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1565, 'ولق لقد اخذ خذن ذنه نهم بلع لعذ عذب فم است ستك تكن كنو لرب ربه بهم وم يتض تضر ضرع رعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1566, 'quran:23:77', 'quran', 'quran', '23:77', 77, 1565, 'Al-Mu''minun', 'المؤمنون', 'حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ', NULL, NULL, 'حتي اذا فتحنا عليهم بابا ذا عذاب شديد اذا هم فيه مبلسون', 'حت اذ تح علي بب ذ عذب شديد اذ هم في مبلس', 'quran', NULL, NULL, 'https://quran.com/23/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1566, 'حتي اذ فتح تحن علي ليه يهم بب ذ عذب شدي ديد اذ هم فيه مبل بلس لسو سون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1567, 'quran:23:78', 'quran', 'quran', '23:78', 78, 1566, 'Al-Mu''minun', 'المؤمنون', 'وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ', NULL, NULL, 'وهو الذي انشا لكم السمع والابصر والافده قليلا ما تشكرون', 'وهو ذي انش لكم سمع ابصر افد قليل م تشكر', 'quran', NULL, NULL, 'https://quran.com/23/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1567, 'وهو الذ لذي انش لكم الس لسم سمع ولب لبص بصر ولف لفد فده قلي ليل م تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1568, 'quran:23:79', 'quran', 'quran', '23:79', 79, 1567, 'Al-Mu''minun', 'المؤمنون', 'وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ', NULL, NULL, 'وهو الذي ذراكم في الارض واليه تحشرون', 'وهو ذي ذر في ارض يه تحشر', 'quran', NULL, NULL, 'https://quran.com/23/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1568, 'وهو الذ لذي ذرك ركم في الر لرض ولي ليه تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1569, 'quran:23:80', 'quran', 'quran', '23:80', 80, 1568, 'Al-Mu''minun', 'المؤمنون', 'وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ', NULL, NULL, 'وهو الذي يحي ويميت وله اختلف اليل والنهار افلا تعقلون', 'وهو ذي يح يميت ول اختلف يل نهر افل تعقل', 'quran', NULL, NULL, 'https://quran.com/23/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1569, 'وهو الذ لذي يحي ويم يمي ميت وله اخت ختل تلف الي ليل ولن لنه نهر افل تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1570, 'quran:23:81', 'quran', 'quran', '23:81', 81, 1569, 'Al-Mu''minun', 'المؤمنون', 'بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ', NULL, NULL, 'بل قالوا مثل ما قال الاولون', 'بل قل مثل م قل اول', 'quran', NULL, NULL, 'https://quran.com/23/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1570, 'بل قلو مثل م قل الو لول ولو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1571, 'quran:23:82', 'quran', 'quran', '23:82', 82, 1570, 'Al-Mu''minun', 'المؤمنون', 'قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ', NULL, NULL, 'قالوا اءذا متنا وكنا ترابا وعظما اءنا لمبعوثون', 'قل اءذ مت كن ترب عظم اء لمبعوث', 'quran', NULL, NULL, 'https://quran.com/23/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1571, 'قلو اءذ متن وكن ترب وعظ عظم اءن لمب مبع بعو عوث وثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1572, 'quran:23:83', 'quran', 'quran', '23:83', 83, 1571, 'Al-Mu''minun', 'المؤمنون', 'لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', NULL, NULL, 'لقد وعدنا نحن واباونا هذا من قبل ان هذا الا اسطير الاولين', 'لقد عد نحن ابو هذ من قبل ان هذ ال اسطير اول', 'quran', NULL, NULL, 'https://quran.com/23/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1572, 'لقد وعد عدن نحن وبو بون هذ من قبل ان هذ ال اسط سطي طير الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1573, 'quran:23:84', 'quran', 'quran', '23:84', 84, 1572, 'Al-Mu''minun', 'المؤمنون', 'قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'قل لمن الارض ومن فيها ان كنتم تعلمون', 'قل لمن ارض ومن يه ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/23/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1573, 'قل لمن الر لرض ومن فيه ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1574, 'quran:23:85', 'quran', 'quran', '23:85', 85, 1573, 'Al-Mu''minun', 'المؤمنون', 'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ', NULL, NULL, 'سيقولون لله قل افلا تذكرون', 'سيقول لل قل افل تذكر', 'quran', NULL, NULL, 'https://quran.com/23/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1574, 'سيق يقو قول ولو لون لله قل افل تذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1575, 'quran:23:86', 'quran', 'quran', '23:86', 86, 1574, 'Al-Mu''minun', 'المؤمنون', 'قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ', NULL, NULL, 'قل من رب السموت السبع ورب العرش العظيم', 'قل من رب سموت سبع ورب عرش عظيم', 'quran', NULL, NULL, 'https://quran.com/23/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1575, 'قل من رب الس لسم سمو موت الس لسب سبع ورب الع لعر عرش الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1576, 'quran:23:87', 'quran', 'quran', '23:87', 87, 1575, 'Al-Mu''minun', 'المؤمنون', 'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ', NULL, NULL, 'سيقولون لله قل افلا تتقون', 'سيقول لل قل افل تتق', 'quran', NULL, NULL, 'https://quran.com/23/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1576, 'سيق يقو قول ولو لون لله قل افل تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1577, 'quran:23:88', 'quran', 'quran', '23:88', 88, 1576, 'Al-Mu''minun', 'المؤمنون', 'قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'قل من بيده ملكوت كل شيء وهو يجير ولا يجار عليه ان كنتم تعلمون', 'قل من بيد ملكوت كل شيء وهو يجير ول يجر عل ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/23/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1577, 'قل من بيد يده ملك لكو كوت كل شيء وهو يجي جير ول يجر علي ليه ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1578, 'quran:23:89', 'quran', 'quran', '23:89', 89, 1577, 'Al-Mu''minun', 'المؤمنون', 'سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ', NULL, NULL, 'سيقولون لله قل فاني تسحرون', 'سيقول لل قل ان تسحر', 'quran', NULL, NULL, 'https://quran.com/23/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1578, 'سيق يقو قول ولو لون لله قل فني تسح سحر حرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1579, 'quran:23:90', 'quran', 'quran', '23:90', 90, 1578, 'Al-Mu''minun', 'المؤمنون', 'بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ', NULL, NULL, 'بل اتينهم بالحق وانهم لكذبون', 'بل اتين حق ان لكذب', 'quran', NULL, NULL, 'https://quran.com/23/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1579, 'بل اتي تين ينه نهم بلح لحق ونه نهم لكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1580, 'quran:23:91', 'quran', 'quran', '23:91', 91, 1579, 'Al-Mu''minun', 'المؤمنون', 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', NULL, NULL, 'ما اتخذ الله من ولد وما كان معه من اله اذا لذهب كل اله بما خلق ولعلا بعضهم علي بعض سبحن الله عما يصفون', 'م اتخذ له من ولد وم كن مع من ال اذ لذهب كل ال بم خلق لعل بعض عل بعض سبحن له عم يصف', 'quran', NULL, NULL, 'https://quran.com/23/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1580, 'م اتخ تخذ الل لله من ولد وم كن معه من اله اذ لذه ذهب كل اله بم خلق ولع لعل بعض عضه ضهم علي بعض سبح بحن الل لله عم يصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1581, 'quran:23:92', 'quran', 'quran', '23:92', 92, 1580, 'Al-Mu''minun', 'المؤمنون', 'عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', NULL, NULL, 'علم الغيب والشهده فتعلي عما يشركون', 'علم غيب شهد تعل عم يشرك', 'quran', NULL, NULL, 'https://quran.com/23/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1581, 'علم الغ لغي غيب ولش لشه شهد هده فتع تعل علي عم يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1582, 'quran:23:93', 'quran', 'quran', '23:93', 93, 1581, 'Al-Mu''minun', 'المؤمنون', 'قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ', NULL, NULL, 'قل رب اما تريني ما يوعدون', 'قل رب ام ترين م يوعد', 'quran', NULL, NULL, 'https://quran.com/23/93');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1582, 'قل رب ام تري رين يني م يوع وعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1583, 'quran:23:94', 'quran', 'quran', '23:94', 94, 1582, 'Al-Mu''minun', 'المؤمنون', 'رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ', NULL, NULL, 'رب فلا تجعلني في القوم الظلمين', 'رب فل تجعلن في قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/23/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1583, 'رب فل تجع جعل علن لني في الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1584, 'quran:23:95', 'quran', 'quran', '23:95', 95, 1583, 'Al-Mu''minun', 'المؤمنون', 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ', NULL, NULL, 'وانا علي ان نريك ما نعدهم لقدرون', 'ان عل ان نريك م نعد لقدر', 'quran', NULL, NULL, 'https://quran.com/23/95');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1584, 'ون علي ان نري ريك م نعد عده دهم لقد قدر درو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1585, 'quran:23:96', 'quran', 'quran', '23:96', 96, 1584, 'Al-Mu''minun', 'المؤمنون', 'ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ', NULL, NULL, 'ادفع بالتي هي احسن السييه نحن اعلم بما يصفون', 'ادفع تي هي احسن سي نحن اعلم بم يصف', 'quran', NULL, NULL, 'https://quran.com/23/96');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1585, 'ادف دفع بلت لتي هي احس حسن الس لسي سيي ييه نحن اعل علم بم يصف صفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1586, 'quran:23:97', 'quran', 'quran', '23:97', 97, 1585, 'Al-Mu''minun', 'المؤمنون', 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ', NULL, NULL, 'وقل رب اعوذ بك من همزت الشيطين', 'وقل رب اعوذ بك من همزت شيط', 'quran', NULL, NULL, 'https://quran.com/23/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1586, 'وقل رب اعو عوذ بك من همز مزت الش لشي شيط يطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1587, 'quran:23:98', 'quran', 'quran', '23:98', 98, 1586, 'Al-Mu''minun', 'المؤمنون', 'وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ', NULL, NULL, 'واعوذ بك رب ان يحضرون', 'اعوذ بك رب ان يحضر', 'quran', NULL, NULL, 'https://quran.com/23/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1587, 'وعو عوذ بك رب ان يحض حضر ضرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1588, 'quran:23:99', 'quran', 'quran', '23:99', 99, 1587, 'Al-Mu''minun', 'المؤمنون', 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ', NULL, NULL, 'حتي اذا جاء احدهم الموت قال رب ارجعون', 'حت اذ جء احد موت قل رب ارجع', 'quran', NULL, NULL, 'https://quran.com/23/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1588, 'حتي اذ جء احد حده دهم الم لمو موت قل رب ارج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1589, 'quran:23:100', 'quran', 'quran', '23:100', 100, 1588, 'Al-Mu''minun', 'المؤمنون', 'لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كـَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ', NULL, NULL, 'لعلي اعمل صلحا فيما تركت كلا انها كلمه هو قايلها ومن ورايهم برزخ الي يوم يبعثون', 'لعل اعمل صلح يم تركت كل ان كلم هو قيل ومن ري برزخ ال يوم يبعث', 'quran', NULL, NULL, 'https://quran.com/23/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1589, 'لعل علي اعم عمل صلح فيم ترك ركت كل انه كلم لمه هو قيل يله ومن وري ريه يهم برز رزخ الي يوم يبع بعث عثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1590, 'quran:23:101', 'quran', 'quran', '23:101', 101, 1589, 'Al-Mu''minun', 'المؤمنون', 'فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ', NULL, NULL, 'فاذا نفخ في الصور فلا انساب بينهم يوميذ ولا يتساءلون', 'اذ نفخ في صور فل انسب بين يوميذ ول يتسءل', 'quran', NULL, NULL, 'https://quran.com/23/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1590, 'فذ نفخ في الص لصو صور فل انس نسب بين ينه نهم يوم ومي ميذ ول يتس تسء سءل ءلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1591, 'quran:23:102', 'quran', 'quran', '23:102', 102, 1590, 'Al-Mu''minun', 'المؤمنون', 'فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'فمن ثقلت موزينه فاوليك هم المفلحون', 'فمن ثقلت موزين اوليك هم مفلح', 'quran', NULL, NULL, 'https://quran.com/23/102');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1591, 'فمن ثقل قلت موز وزي زين ينه فول ولي ليك هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1592, 'quran:23:103', 'quran', 'quran', '23:103', 103, 1591, 'Al-Mu''minun', 'المؤمنون', 'وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ', NULL, NULL, 'ومن خفت موزينه فاوليك الذين خسروا انفسهم في جهنم خلدون', 'ومن خفت موزين اوليك ذين خسر انفس في جهنم خلد', 'quran', NULL, NULL, 'https://quran.com/23/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1592, 'ومن خفت موز وزي زين ينه فول ولي ليك الذ لذي ذين خسر سرو انف نفس فسه سهم في جهن هنم خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1593, 'quran:23:104', 'quran', 'quran', '23:104', 104, 1592, 'Al-Mu''minun', 'المؤمنون', 'تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ', NULL, NULL, 'تلفح وجوههم النار وهم فيها كلحون', 'تلفح جوه نر وهم يه كلح', 'quran', NULL, NULL, 'https://quran.com/23/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1593, 'تلف لفح وجو جوه وهه ههم الن لنر وهم فيه كلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1594, 'quran:23:105', 'quran', 'quran', '23:105', 105, 1593, 'Al-Mu''minun', 'المؤمنون', 'أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ', NULL, NULL, 'الم تكن ايتي تتلي عليكم فكنتم بها تكذبون', 'الم تكن ايت تتل علي كنتم به تكذب', 'quran', NULL, NULL, 'https://quran.com/23/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1594, 'الم تكن ايت يتي تتل تلي علي ليك يكم فكن كنت نتم به تكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1595, 'quran:23:106', 'quran', 'quran', '23:106', 106, 1594, 'Al-Mu''minun', 'المؤمنون', 'قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ', NULL, NULL, 'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين', 'قل رب غلبت علي شقوت كن قوم ضل', 'quran', NULL, NULL, 'https://quran.com/23/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1595, 'قلو ربن غلب لبت علي لين شقو قوت وتن وكن قوم ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1596, 'quran:23:107', 'quran', 'quran', '23:107', 107, 1595, 'Al-Mu''minun', 'المؤمنون', 'رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ', NULL, NULL, 'ربنا اخرجنا منها فان عدنا فانا ظلمون', 'رب اخرج من فن عد ان ظلم', 'quran', NULL, NULL, 'https://quran.com/23/107');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1596, 'ربن اخر خرج رجن منه فن عدن فن ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1597, 'quran:23:108', 'quran', 'quran', '23:108', 108, 1596, 'Al-Mu''minun', 'المؤمنون', 'قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ', NULL, NULL, 'قال اخسوا فيها ولا تكلمون', 'قل اخس يه ول تكلم', 'quran', NULL, NULL, 'https://quran.com/23/108');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1597, 'قل اخس خسو فيه ول تكل كلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1598, 'quran:23:109', 'quran', 'quran', '23:109', 109, 1597, 'Al-Mu''minun', 'المؤمنون', 'إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ', NULL, NULL, 'انه كان فريق من عبادي يقولون ربنا امنا فاغفر لنا وارحمنا وانت خير الرحمين', 'ان كن ريق من عبد يقول رب ام اغفر لن ارحم انت خير رحم', 'quran', NULL, NULL, 'https://quran.com/23/109');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1598, 'انه كن فري ريق من عبد بدي يقو قول ولو لون ربن امن فغف غفر لن ورح رحم حمن ونت خير الر لرح رحم حمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1599, 'quran:23:110', 'quran', 'quran', '23:110', 110, 1598, 'Al-Mu''minun', 'المؤمنون', 'فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ', NULL, NULL, 'فاتخذتموهم سخريا حتي انسوكم ذكري وكنتم منهم تضحكون', 'اتخذتمو سخري حت انسو ذكر كنتم من تضحك', 'quran', NULL, NULL, 'https://quran.com/23/110');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1599, 'فتخ تخذ خذت ذتم تمو موه وهم سخر خري حتي انس نسو سوك وكم ذكر كري وكن كنت نتم منه نهم تضح ضحك حكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1600, 'quran:23:111', 'quran', 'quran', '23:111', 111, 1599, 'Al-Mu''minun', 'المؤمنون', 'إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ', NULL, NULL, 'اني جزيتهم اليوم بما صبروا انهم هم الفايزون', 'ان جزيت يوم بم صبر ان هم فيز', 'quran', NULL, NULL, 'https://quran.com/23/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1600, 'اني جزي زيت يته تهم الي ليو يوم بم صبر برو انه نهم هم الف لفي فيز يزو زون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1601, 'quran:23:112', 'quran', 'quran', '23:112', 112, 1600, 'Al-Mu''minun', 'المؤمنون', 'قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ', NULL, NULL, 'قل كم لبثتم في الارض عدد سنين', 'قل كم لبثتم في ارض عدد سن', 'quran', NULL, NULL, 'https://quran.com/23/112');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1601, 'قل كم لبث بثت ثتم في الر لرض عدد سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1602, 'quran:23:113', 'quran', 'quran', '23:113', 113, 1601, 'Al-Mu''minun', 'المؤمنون', 'قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ', NULL, NULL, 'قالوا لبثنا يوما او بعض يوم فسل العادين', 'قل لبث يوم او بعض يوم فسل عد', 'quran', NULL, NULL, 'https://quran.com/23/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1602, 'قلو لبث بثن يوم او بعض يوم فسل الع لعد عدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1603, 'quran:23:114', 'quran', 'quran', '23:114', 114, 1602, 'Al-Mu''minun', 'المؤمنون', 'قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'قل ان لبثتم الا قليلا لو انكم كنتم تعلمون', 'قل ان لبثتم ال قليل لو ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/23/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1603, 'قل ان لبث بثت ثتم ال قلي ليل لو انك نكم كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1604, 'quran:23:115', 'quran', 'quran', '23:115', 115, 1603, 'Al-Mu''minun', 'المؤمنون', 'أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ', NULL, NULL, 'افحسبتم انما خلقنكم عبثا وانكم الينا لا ترجعون', 'افحسبتم انم خلقن عبث ان ين ل ترجع', 'quran', NULL, NULL, 'https://quran.com/23/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1604, 'افح فحس حسب سبت بتم انم خلق لقن قنك نكم عبث ونك نكم الي لين ل ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1605, 'quran:23:116', 'quran', 'quran', '23:116', 116, 1604, 'Al-Mu''minun', 'المؤمنون', 'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ', NULL, NULL, 'فتعلي الله الملك الحق لا اله الا هو رب العرش الكريم', 'تعل له ملك حق ل ال ال هو رب عرش كريم', 'quran', NULL, NULL, 'https://quran.com/23/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1605, 'فتع تعل علي الل لله الم لمل ملك الح لحق ل اله ال هو رب الع لعر عرش الك لكر كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1606, 'quran:23:117', 'quran', 'quran', '23:117', 117, 1605, 'Al-Mu''minun', 'المؤمنون', 'وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ', NULL, NULL, 'ومن يدع مع الله الها اخر لا برهن له به فانما حسابه عند ربه انه لا يفلح الكفرون', 'ومن يدع مع له ه اخر ل بر له به انم حسب عند رب ان ل يفلح كفر', 'quran', NULL, NULL, 'https://quran.com/23/117');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1606, 'ومن يدع مع الل لله اله اخر ل بره رهن له به فنم حسب سبه عند ربه انه ل يفل فلح الك لكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1607, 'quran:23:118', 'quran', 'quran', '23:118', 118, 1606, 'Al-Mu''minun', 'المؤمنون', 'وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ', NULL, NULL, 'وقل رب اغفر وارحم وانت خير الرحمين', 'وقل رب اغفر ارحم انت خير رحم', 'quran', NULL, NULL, 'https://quran.com/23/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1607, 'وقل رب اغف غفر ورح رحم ونت خير الر لرح رحم حمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1608, 'quran:26:1', 'quran', 'quran', '26:1', 1, 1607, 'Ash-Shu''ara', 'الشعراء', 'طسٓمٓ', NULL, NULL, 'طسم', 'طسم', 'quran', NULL, NULL, 'https://quran.com/26/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1608, 'طسم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1609, 'quran:26:2', 'quran', 'quran', '26:2', 2, 1608, 'Ash-Shu''ara', 'الشعراء', 'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ', NULL, NULL, 'تلك ايت الكتب المبين', 'تلك ايت كتب مب', 'quran', NULL, NULL, 'https://quran.com/26/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1609, 'تلك ايت الك لكت كتب الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1610, 'quran:26:3', 'quran', 'quran', '26:3', 3, 1609, 'Ash-Shu''ara', 'الشعراء', 'لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ', NULL, NULL, 'لعلك بخع نفسك الا يكونوا مومنين', 'لعلك بخع نفسك ال يكون مومن', 'quran', NULL, NULL, 'https://quran.com/26/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1610, 'لعل علك بخع نفس فسك ال يكو كون ونو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1611, 'quran:26:4', 'quran', 'quran', '26:4', 4, 1610, 'Ash-Shu''ara', 'الشعراء', 'إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ', NULL, NULL, 'ان نشا ننزل عليهم من السماء ايه فظلت اعنقهم لها خضعين', 'ان نش ننزل علي من سمء اي ظلت اعنق له خضع', 'quran', NULL, NULL, 'https://quran.com/26/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1611, 'ان نش ننز نزل علي ليه يهم من الس لسم سمء ايه فظل ظلت اعن عنق نقه قهم له خضع ضعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1612, 'quran:26:5', 'quran', 'quran', '26:5', 5, 1611, 'Ash-Shu''ara', 'الشعراء', 'وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ', NULL, NULL, 'وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين', 'وم يتي من ذكر من رحمن محدث ال كن عن معرض', 'quran', NULL, NULL, 'https://quran.com/26/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1612, 'وم يتي تيه يهم من ذكر من الر لرح رحم حمن محد حدث ال كنو عنه معر عرض رضي ضين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1613, 'quran:26:6', 'quran', 'quran', '26:6', 6, 1612, 'Ash-Shu''ara', 'الشعراء', 'فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'فقد كذبوا فسياتيهم انبوا ما كانوا به يستهزءون', 'فقد كذب سيتي انب م كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/26/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1613, 'فقد كذب ذبو فسي سيت يتي تيه يهم انب نبو م كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1614, 'quran:26:7', 'quran', 'quran', '26:7', 7, 1613, 'Ash-Shu''ara', 'الشعراء', 'أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ', NULL, NULL, 'اولم يروا الي الارض كم انبتنا فيها من كل زوج كريم', 'اولم ير ال ارض كم انبت يه من كل زوج كريم', 'quran', NULL, NULL, 'https://quran.com/26/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1614, 'اول ولم يرو الي الر لرض كم انب نبت بتن فيه من كل زوج كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1615, 'quran:26:8', 'quran', 'quran', '26:8', 8, 1614, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه وما كان اكثرهم مومنين', 'ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1615, 'ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1616, 'quran:26:9', 'quran', 'quran', '26:9', 9, 1615, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1616, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1617, 'quran:26:10', 'quran', 'quran', '26:10', 10, 1616, 'Ash-Shu''ara', 'الشعراء', 'وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ', NULL, NULL, 'واذ نادي ربك موسي ان ايت القوم الظلمين', 'وذ ند ربك موس ان ايت قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/26/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1617, 'وذ ندي ربك موس وسي ان ايت الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1618, 'quran:26:11', 'quran', 'quran', '26:11', 11, 1617, 'Ash-Shu''ara', 'الشعراء', 'قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ', NULL, NULL, 'قوم فرعون الا يتقون', 'قوم رع ال يتق', 'quran', NULL, NULL, 'https://quran.com/26/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1618, 'قوم فرع رعو عون ال يتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1619, 'quran:26:12', 'quran', 'quran', '26:12', 12, 1618, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ', NULL, NULL, 'قال رب اني اخاف ان يكذبون', 'قل رب ان اخف ان يكذب', 'quran', NULL, NULL, 'https://quran.com/26/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1619, 'قل رب اني اخف ان يكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1620, 'quran:26:13', 'quran', 'quran', '26:13', 13, 1619, 'Ash-Shu''ara', 'الشعراء', 'وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ', NULL, NULL, 'ويضيق صدري ولا ينطلق لساني فارسل الي هرون', 'يضيق صدر ول ينطلق لسن ارسل ال هر', 'quran', NULL, NULL, 'https://quran.com/26/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1620, 'ويض يضي ضيق صدر دري ول ينط نطل طلق لسن سني فرس رسل الي هرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1621, 'quran:26:14', 'quran', 'quran', '26:14', 14, 1620, 'Ash-Shu''ara', 'الشعراء', 'وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ', NULL, NULL, 'ولهم علي ذنب فاخاف ان يقتلون', 'لهم عل ذنب اخف ان يقتل', 'quran', NULL, NULL, 'https://quran.com/26/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1621, 'وله لهم علي ذنب فخف ان يقت قتل تلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1622, 'quran:26:15', 'quran', 'quran', '26:15', 15, 1621, 'Ash-Shu''ara', 'الشعراء', 'قَالَ كـَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ', NULL, NULL, 'قال كلا فاذهبا بايتنا انا معكم مستمعون', 'قل كل اذهب بيت ان مع مستمع', 'quran', NULL, NULL, 'https://quran.com/26/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1622, 'قل كل فذه ذهب بيت يتن ان معك عكم مست ستم تمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1623, 'quran:26:16', 'quran', 'quran', '26:16', 16, 1622, 'Ash-Shu''ara', 'الشعراء', 'فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'فاتيا فرعون فقولا انا رسول رب العلمين', 'اتي رع قول ان رسول رب علم', 'quran', NULL, NULL, 'https://quran.com/26/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1623, 'فتي فرع رعو عون فقو قول ان رسو سول رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1624, 'quran:26:17', 'quran', 'quran', '26:17', 17, 1623, 'Ash-Shu''ara', 'الشعراء', 'أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ', NULL, NULL, 'ان ارسل معنا بني اسرءيل', 'ان ارسل مع بن اسرءيل', 'quran', NULL, NULL, 'https://quran.com/26/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1624, 'ان ارس رسل معن بني اسر سرء رءي ءيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1625, 'quran:26:18', 'quran', 'quran', '26:18', 18, 1624, 'Ash-Shu''ara', 'الشعراء', 'قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ', NULL, NULL, 'قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين', 'قل الم نربك ين ليد لبثت ين من عمرك سن', 'quran', NULL, NULL, 'https://quran.com/26/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1625, 'قل الم نرب ربك فين ولي ليد ولب لبث بثت فين من عمر مرك سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1626, 'quran:26:19', 'quran', 'quran', '26:19', 19, 1625, 'Ash-Shu''ara', 'الشعراء', 'وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'وفعلت فعلتك التي فعلت وانت من الكفرين', 'فعلت علتك تي علت انت من كفر', 'quran', NULL, NULL, 'https://quran.com/26/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1626, 'وفع فعل علت فعل علت لتك الت لتي فعل علت ونت من الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1627, 'quran:26:20', 'quran', 'quran', '26:20', 20, 1626, 'Ash-Shu''ara', 'الشعراء', 'قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', NULL, NULL, 'قال فعلتها اذا وانا من الضالين', 'قل علت اذ ان من ضل', 'quran', NULL, NULL, 'https://quran.com/26/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1627, 'قل فعل علت لته اذ ون من الض لضل ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1628, 'quran:26:21', 'quran', 'quran', '26:21', 21, 1627, 'Ash-Shu''ara', 'الشعراء', 'فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين', 'فررت من لم خفت وهب لي رب حكم جعلن من مرسل', 'quran', NULL, NULL, 'https://quran.com/26/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1628, 'ففر فرر ررت منك نكم لم خفت فتك تكم فوه وهب لي ربي حكم وجع جعل علن لني من الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1629, 'quran:26:22', 'quran', 'quran', '26:22', 22, 1628, 'Ash-Shu''ara', 'الشعراء', 'وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ', NULL, NULL, 'وتلك نعمه تمنها علي ان عبدت بني اسرءيل', 'تلك نعم تمن عل ان عبدت بن اسرءيل', 'quran', NULL, NULL, 'https://quran.com/26/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1629, 'وتل تلك نعم عمه تمن منه علي ان عبد بدت بني اسر سرء رءي ءيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1630, 'quran:26:23', 'quran', 'quran', '26:23', 23, 1629, 'Ash-Shu''ara', 'الشعراء', 'قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قال فرعون وما رب العلمين', 'قل رع وم رب علم', 'quran', NULL, NULL, 'https://quran.com/26/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1630, 'قل فرع رعو عون وم رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1631, 'quran:26:24', 'quran', 'quran', '26:24', 24, 1630, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ', NULL, NULL, 'قال رب السموت والارض وما بينهما ان كنتم موقنين', 'قل رب سموت ارض وم بينهم ان كنتم موقن', 'quran', NULL, NULL, 'https://quran.com/26/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1631, 'قل رب الس لسم سمو موت ولر لرض وم بين ينه نهم ان كنت نتم موق وقن قني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1632, 'quran:26:25', 'quran', 'quran', '26:25', 25, 1631, 'Ash-Shu''ara', 'الشعراء', 'قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ', NULL, NULL, 'قال لمن حوله الا تستمعون', 'قل لمن حول ال تستمع', 'quran', NULL, NULL, 'https://quran.com/26/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1632, 'قل لمن حول وله ال تست ستم تمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1633, 'quran:26:26', 'quran', 'quran', '26:26', 26, 1632, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ', NULL, NULL, 'قال ربكم ورب ابايكم الاولين', 'قل رب ورب ابي اول', 'quran', NULL, NULL, 'https://quran.com/26/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1633, 'قل ربك بكم ورب ابي بيك يكم الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1634, 'quran:26:27', 'quran', 'quran', '26:27', 27, 1633, 'Ash-Shu''ara', 'الشعراء', 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ', NULL, NULL, 'قال ان رسولكم الذي ارسل اليكم لمجنون', 'قل ان رسول ذي ارسل يكم لمجن', 'quran', NULL, NULL, 'https://quran.com/26/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1634, 'قل ان رسو سول ولك لكم الذ لذي ارس رسل الي ليك يكم لمج مجن جنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1635, 'quran:26:28', 'quran', 'quran', '26:28', 28, 1634, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ', NULL, NULL, 'قال رب المشرق والمغرب وما بينهما ان كنتم تعقلون', 'قل رب مشرق مغرب وم بينهم ان كنتم تعقل', 'quran', NULL, NULL, 'https://quran.com/26/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1635, 'قل رب الم لمش مشر شرق ولم لمغ مغر غرب وم بين ينه نهم ان كنت نتم تعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1636, 'quran:26:29', 'quran', 'quran', '26:29', 29, 1635, 'Ash-Shu''ara', 'الشعراء', 'قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ', NULL, NULL, 'قال لين اتخذت الها غيري لاجعلنك من المسجونين', 'قل لين اتخذت ه غير لجعلنك من مسجون', 'quran', NULL, NULL, 'https://quran.com/26/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1636, 'قل لين اتخ تخذ خذت اله غير يري لجع جعل علن لنك من الم لمس مسج سجو جون وني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1637, 'quran:26:30', 'quran', 'quran', '26:30', 30, 1636, 'Ash-Shu''ara', 'الشعراء', 'قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ', NULL, NULL, 'قال اولو جيتك بشيء مبين', 'قل اولو جيتك بشيء مب', 'quran', NULL, NULL, 'https://quran.com/26/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1637, 'قل اول ولو جيت يتك بشي شيء مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1638, 'quran:26:31', 'quran', 'quran', '26:31', 31, 1637, 'Ash-Shu''ara', 'الشعراء', 'قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', NULL, NULL, 'قال فات به ان كنت من الصدقين', 'قل فت به ان كنت من صدق', 'quran', NULL, NULL, 'https://quran.com/26/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1638, 'قل فت به ان كنت من الص لصد صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1639, 'quran:26:32', 'quran', 'quran', '26:32', 32, 1638, 'Ash-Shu''ara', 'الشعراء', 'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ', NULL, NULL, 'فالقي عصاه فاذا هي ثعبان مبين', 'قي عص اذ هي ثعب مب', 'quran', NULL, NULL, 'https://quran.com/26/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1639, 'فلق لقي عصه فذ هي ثعب عبن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1640, 'quran:26:33', 'quran', 'quran', '26:33', 33, 1639, 'Ash-Shu''ara', 'الشعراء', 'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ', NULL, NULL, 'ونزع يده فاذا هي بيضاء للنظرين', 'نزع يد اذ هي بيضء نظر', 'quran', NULL, NULL, 'https://quran.com/26/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1640, 'ونز نزع يده فذ هي بيض يضء للن لنظ نظر ظري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1641, 'quran:26:34', 'quran', 'quran', '26:34', 34, 1640, 'Ash-Shu''ara', 'الشعراء', 'قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ', NULL, NULL, 'قال للملا حوله ان هذا لسحر عليم', 'قل مل حول ان هذ لسحر عليم', 'quran', NULL, NULL, 'https://quran.com/26/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1641, 'قل للم لمل حول وله ان هذ لسح سحر علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1642, 'quran:26:35', 'quran', 'quran', '26:35', 35, 1641, 'Ash-Shu''ara', 'الشعراء', 'يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ', NULL, NULL, 'يريد ان يخرجكم من ارضكم بسحره فماذا تامرون', 'يريد ان يخرج من ارض بسحر مذ تمر', 'quran', NULL, NULL, 'https://quran.com/26/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1642, 'يري ريد ان يخر خرج رجك جكم من ارض رضك ضكم بسح سحر حره فمذ تمر مرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1643, 'quran:26:36', 'quran', 'quran', '26:36', 36, 1642, 'Ash-Shu''ara', 'الشعراء', 'قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ', NULL, NULL, 'قالوا ارجه واخاه وابعث في المداين حشرين', 'قل ارج اخ ابعث في مد حشر', 'quran', NULL, NULL, 'https://quran.com/26/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1643, 'قلو ارج رجه وخه وبع بعث في الم لمد مدي دين حشر شري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1644, 'quran:26:37', 'quran', 'quran', '26:37', 37, 1643, 'Ash-Shu''ara', 'الشعراء', 'يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ', NULL, NULL, 'ياتوك بكل سحار عليم', 'يتوك بكل سحر عليم', 'quran', NULL, NULL, 'https://quran.com/26/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1644, 'يتو توك بكل سحر علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1645, 'quran:26:38', 'quran', 'quran', '26:38', 38, 1644, 'Ash-Shu''ara', 'الشعراء', 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ', NULL, NULL, 'فجمع السحره لميقت يوم معلوم', 'جمع سحر لميقت يوم معلوم', 'quran', NULL, NULL, 'https://quran.com/26/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1645, 'فجم جمع الس لسح سحر حره لمي ميق يقت يوم معل علو لوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1646, 'quran:26:39', 'quran', 'quran', '26:39', 39, 1645, 'Ash-Shu''ara', 'الشعراء', 'وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ', NULL, NULL, 'وقيل للناس هل انتم مجتمعون', 'قيل نس هل انتم مجتمع', 'quran', NULL, NULL, 'https://quran.com/26/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1646, 'وقي قيل للن لنس هل انت نتم مجت جتم تمع معو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1647, 'quran:26:40', 'quran', 'quran', '26:40', 40, 1646, 'Ash-Shu''ara', 'الشعراء', 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ', NULL, NULL, 'لعلنا نتبع السحره ان كانوا هم الغلبين', 'لعل نتبع سحر ان كن هم غلب', 'quran', NULL, NULL, 'https://quran.com/26/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1647, 'لعل علن نتب تبع الس لسح سحر حره ان كنو هم الغ لغل غلب لبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1648, 'quran:26:41', 'quran', 'quran', '26:41', 41, 1647, 'Ash-Shu''ara', 'الشعراء', 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ', NULL, NULL, 'فلما جاء السحره قالوا لفرعون اين لنا لاجرا ان كنا نحن الغلبين', 'لم جء سحر قل لفرع اين لن لجر ان كن نحن غلب', 'quran', NULL, NULL, 'https://quran.com/26/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1648, 'فلم جء الس لسح سحر حره قلو لفر فرع رعو عون اين لن لجر ان كن نحن الغ لغل غلب لبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1649, 'quran:26:42', 'quran', 'quran', '26:42', 42, 1648, 'Ash-Shu''ara', 'الشعراء', 'قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ', NULL, NULL, 'قال نعم وانكم اذا لمن المقربين', 'قل نعم ان اذ لمن مقرب', 'quran', NULL, NULL, 'https://quran.com/26/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1649, 'قل نعم ونك نكم اذ لمن الم لمق مقر قرب ربي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1650, 'quran:26:43', 'quran', 'quran', '26:43', 43, 1649, 'Ash-Shu''ara', 'الشعراء', 'قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ', NULL, NULL, 'قال لهم موسي القوا ما انتم ملقون', 'قل لهم موس قو م انتم ملق', 'quran', NULL, NULL, 'https://quran.com/26/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1650, 'قل لهم موس وسي الق لقو م انت نتم ملق لقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1651, 'quran:26:44', 'quran', 'quran', '26:44', 44, 1650, 'Ash-Shu''ara', 'الشعراء', 'فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ', NULL, NULL, 'فالقوا حبالهم وعصيهم وقالوا بعزه فرعون انا لنحن الغلبون', 'قو حبل عصي قل بعز رع ان لنحن غلب', 'quran', NULL, NULL, 'https://quran.com/26/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1651, 'فلق لقو حبل بله لهم وعص عصي صيه يهم وقل قلو بعز عزه فرع رعو عون ان لنح نحن الغ لغل غلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1652, 'quran:26:45', 'quran', 'quran', '26:45', 45, 1651, 'Ash-Shu''ara', 'الشعراء', 'فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ', NULL, NULL, 'فالقي موسي عصاه فاذا هي تلقف ما يافكون', 'قي موس عص اذ هي تلقف م يفك', 'quran', NULL, NULL, 'https://quran.com/26/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1652, 'فلق لقي موس وسي عصه فذ هي تلق لقف م يفك فكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1653, 'quran:26:46', 'quran', 'quran', '26:46', 46, 1652, 'Ash-Shu''ara', 'الشعراء', 'فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ', NULL, NULL, 'فالقي السحره سجدين', 'قي سحر سجد', 'quran', NULL, NULL, 'https://quran.com/26/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1653, 'فلق لقي الس لسح سحر حره سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1654, 'quran:26:47', 'quran', 'quran', '26:47', 47, 1653, 'Ash-Shu''ara', 'الشعراء', 'قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'قالوا امنا برب العلمين', 'قل ام برب علم', 'quran', NULL, NULL, 'https://quran.com/26/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1654, 'قلو امن برب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1655, 'quran:26:48', 'quran', 'quran', '26:48', 48, 1654, 'Ash-Shu''ara', 'الشعراء', 'رَبِّ مُوسَىٰ وَهَٰرُونَ', NULL, NULL, 'رب موسي وهرون', 'رب موس هر', 'quran', NULL, NULL, 'https://quran.com/26/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1655, 'رب موس وسي وهر هرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1656, 'quran:26:49', 'quran', 'quran', '26:49', 49, 1655, 'Ash-Shu''ara', 'الشعراء', 'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ', NULL, NULL, 'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلسوف تعلمون لاقطعن ايديكم وارجلكم من خلف ولاصلبنكم اجمعين', 'قل امنتم له قبل ان اذن لكم ان لكبير ذي علم سحر لسوف تعلم لقطعن ايدي ارجل من خلف لصلبن اجمع', 'quran', NULL, NULL, 'https://quran.com/26/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1656, 'قل امن منت نتم له قبل ان اذن لكم انه لكب كبي بير يرك ركم الذ لذي علم لمك مكم الس لسح سحر فلس لسو سوف تعل علم لمو مون لقط قطع طعن ايد يدي ديك يكم ورج رجل جلك لكم من خلف ولص لصل صلب لبن بنك نكم اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1657, 'quran:26:50', 'quran', 'quran', '26:50', 50, 1656, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', NULL, NULL, 'قالوا لا ضير انا الي ربنا منقلبون', 'قل ل ضير ان ال رب منقلب', 'quran', NULL, NULL, 'https://quran.com/26/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1657, 'قلو ل ضير ان الي ربن منق نقل قلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1658, 'quran:26:51', 'quran', 'quran', '26:51', 51, 1657, 'Ash-Shu''ara', 'الشعراء', 'إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'انا نطمع ان يغفر لنا ربنا خطينا ان كنا اول المومنين', 'ان نطمع ان يغفر لن رب خطي ان كن اول مومن', 'quran', NULL, NULL, 'https://quran.com/26/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1658, 'ان نطم طمع ان يغف غفر لن ربن خطي طين ان كن اول الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1659, 'quran:26:52', 'quran', 'quran', '26:52', 52, 1658, 'Ash-Shu''ara', 'الشعراء', 'وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ', NULL, NULL, 'واوحينا الي موسي ان اسر بعبادي انكم متبعون', 'اوحي ال موس ان اسر بعبد ان متبع', 'quran', NULL, NULL, 'https://quran.com/26/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1659, 'ووح وحي حين الي موس وسي ان اسر بعب عبد بدي انك نكم متب تبع بعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1660, 'quran:26:53', 'quran', 'quran', '26:53', 53, 1659, 'Ash-Shu''ara', 'الشعراء', 'فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ', NULL, NULL, 'فارسل فرعون في المداين حشرين', 'ارسل رع في مد حشر', 'quran', NULL, NULL, 'https://quran.com/26/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1660, 'فرس رسل فرع رعو عون في الم لمد مدي دين حشر شري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1661, 'quran:26:54', 'quran', 'quran', '26:54', 54, 1660, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ هَٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ', NULL, NULL, 'ان هولاء لشرذمه قليلون', 'ان هولء لشرذم قليل', 'quran', NULL, NULL, 'https://quran.com/26/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1661, 'ان هول ولء لشر شرذ رذم ذمه قلي ليل يلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1662, 'quran:26:55', 'quran', 'quran', '26:55', 55, 1661, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ', NULL, NULL, 'وانهم لنا لغايظون', 'ان لن لغيظ', 'quran', NULL, NULL, 'https://quran.com/26/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1662, 'ونه نهم لن لغي غيظ يظو ظون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1663, 'quran:26:56', 'quran', 'quran', '26:56', 56, 1662, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', NULL, NULL, 'وانا لجميع حذرون', 'ان لجميع حذر', 'quran', NULL, NULL, 'https://quran.com/26/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1663, 'ون لجم جمي ميع حذر ذرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1664, 'quran:26:57', 'quran', 'quran', '26:57', 57, 1663, 'Ash-Shu''ara', 'الشعراء', 'فَأَخۡرَجۡنَٰهُم مِّن جَنَّٰتٖ وَعُيُونٖ', NULL, NULL, 'فاخرجنهم من جنت وعيون', 'اخرجن من جنت عي', 'quran', NULL, NULL, 'https://quran.com/26/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1664, 'فخر خرج رجن جنه نهم من جنت وعي عيو يون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1665, 'quran:26:58', 'quran', 'quran', '26:58', 58, 1664, 'Ash-Shu''ara', 'الشعراء', 'وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ', NULL, NULL, 'وكنوز ومقام كريم', 'كنوز مقم كريم', 'quran', NULL, NULL, 'https://quran.com/26/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1665, 'وكن كنو نوز ومق مقم كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1666, 'quran:26:59', 'quran', 'quran', '26:59', 59, 1665, 'Ash-Shu''ara', 'الشعراء', 'كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَٰٓءِيلَ', NULL, NULL, 'كذلك واورثنها بني اسرءيل', 'كذلك اورثن بن اسرءيل', 'quran', NULL, NULL, 'https://quran.com/26/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1666, 'كذل ذلك وور ورث رثن ثنه بني اسر سرء رءي ءيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1667, 'quran:26:60', 'quran', 'quran', '26:60', 60, 1666, 'Ash-Shu''ara', 'الشعراء', 'فَأَتۡبَعُوهُم مُّشۡرِقِينَ', NULL, NULL, 'فاتبعوهم مشرقين', 'اتبعو مشرق', 'quran', NULL, NULL, 'https://quran.com/26/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1667, 'فتب تبع بعو عوه وهم مشر شرق رقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1668, 'quran:26:61', 'quran', 'quran', '26:61', 61, 1667, 'Ash-Shu''ara', 'الشعراء', 'فَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ', NULL, NULL, 'فلما ترا الجمعان قال اصحب موسي انا لمدركون', 'لم تر جمع قل اصحب موس ان لمدرك', 'quran', NULL, NULL, 'https://quran.com/26/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1668, 'فلم تر الج لجم جمع معن قل اصح صحب موس وسي ان لمد مدر درك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1669, 'quran:26:62', 'quran', 'quran', '26:62', 62, 1668, 'Ash-Shu''ara', 'الشعراء', 'قَالَ كـَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ', NULL, NULL, 'قال كلا ان معي ربي سيهدين', 'قل كل ان مع رب سيهد', 'quran', NULL, NULL, 'https://quran.com/26/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1669, 'قل كل ان معي ربي سيه يهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1670, 'quran:26:63', 'quran', 'quran', '26:63', 63, 1669, 'Ash-Shu''ara', 'الشعراء', 'فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ', NULL, NULL, 'فاوحينا الي موسي ان اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم', 'اوحي ال موس ان اضرب بعصك بحر انفلق كن كل فرق طود عظيم', 'quran', NULL, NULL, 'https://quran.com/26/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1670, 'فوح وحي حين الي موس وسي ان اضر ضرب بعص عصك الب لبح بحر فنف نفل فلق فكن كل فرق كلط لطو طود الع لعظ عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1671, 'quran:26:64', 'quran', 'quran', '26:64', 64, 1670, 'Ash-Shu''ara', 'الشعراء', 'وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ', NULL, NULL, 'وازلفنا ثم الاخرين', 'ازلف ثم اخر', 'quran', NULL, NULL, 'https://quran.com/26/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1671, 'وزل زلف لفن ثم الخ لخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1672, 'quran:26:65', 'quran', 'quran', '26:65', 65, 1671, 'Ash-Shu''ara', 'الشعراء', 'وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ', NULL, NULL, 'وانجينا موسي ومن معه اجمعين', 'انجي موس ومن مع اجمع', 'quran', NULL, NULL, 'https://quran.com/26/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1672, 'ونج نجي جين موس وسي ومن معه اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1673, 'quran:26:66', 'quran', 'quran', '26:66', 66, 1672, 'Ash-Shu''ara', 'الشعراء', 'ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ', NULL, NULL, 'ثم اغرقنا الاخرين', 'ثم اغرق اخر', 'quran', NULL, NULL, 'https://quran.com/26/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1673, 'ثم اغر غرق رقن الخ لخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1674, 'quran:26:67', 'quran', 'quran', '26:67', 67, 1673, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه وما كان اكثرهم مومنين', 'ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1674, 'ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1675, 'quran:26:68', 'quran', 'quran', '26:68', 68, 1674, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1675, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1676, 'quran:26:69', 'quran', 'quran', '26:69', 69, 1675, 'Ash-Shu''ara', 'الشعراء', 'وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ', NULL, NULL, 'واتل عليهم نبا ابرهيم', 'اتل علي نب ابرهيم', 'quran', NULL, NULL, 'https://quran.com/26/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1676, 'وتل علي ليه يهم نب ابر بره رهي هيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1677, 'quran:26:70', 'quran', 'quran', '26:70', 70, 1676, 'Ash-Shu''ara', 'الشعراء', 'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ', NULL, NULL, 'اذ قال لابيه وقومه ما تعبدون', 'اذ قل لب قوم م تعبد', 'quran', NULL, NULL, 'https://quran.com/26/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1677, 'اذ قل لبي بيه وقو قوم ومه م تعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1678, 'quran:26:71', 'quran', 'quran', '26:71', 71, 1677, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ', NULL, NULL, 'قالوا نعبد اصناما فنظل لها عكفين', 'قل نعبد اصنم نظل له عكف', 'quran', NULL, NULL, 'https://quran.com/26/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1678, 'قلو نعب عبد اصن صنم فنظ نظل له عكف كفي فين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1679, 'quran:26:72', 'quran', 'quran', '26:72', 72, 1678, 'Ash-Shu''ara', 'الشعراء', 'قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ', NULL, NULL, 'قال هل يسمعونكم اذ تدعون', 'قل هل يسمعون اذ تدع', 'quran', NULL, NULL, 'https://quran.com/26/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1679, 'قل هل يسم سمع معو عون ونك نكم اذ تدع دعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1680, 'quran:26:73', 'quran', 'quran', '26:73', 73, 1679, 'Ash-Shu''ara', 'الشعراء', 'أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ', NULL, NULL, 'او ينفعونكم او يضرون', 'او ينفعون او يضر', 'quran', NULL, NULL, 'https://quran.com/26/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1680, 'او ينف نفع فعو عون ونك نكم او يضر ضرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1681, 'quran:26:74', 'quran', 'quran', '26:74', 74, 1680, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ', NULL, NULL, 'قالوا بل وجدنا اباءنا كذلك يفعلون', 'قل بل جد ابء كذلك يفعل', 'quran', NULL, NULL, 'https://quran.com/26/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1681, 'قلو بل وجد جدن ابء بءن كذل ذلك يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1682, 'quran:26:75', 'quran', 'quran', '26:75', 75, 1681, 'Ash-Shu''ara', 'الشعراء', 'قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ', NULL, NULL, 'قال افرءيتم ما كنتم تعبدون', 'قل افرءيتم م كنتم تعبد', 'quran', NULL, NULL, 'https://quran.com/26/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1682, 'قل افر فرء رءي ءيت يتم م كنت نتم تعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1683, 'quran:26:76', 'quran', 'quran', '26:76', 76, 1682, 'Ash-Shu''ara', 'الشعراء', 'أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ', NULL, NULL, 'انتم واباوكم الاقدمون', 'انتم ابو اقدم', 'quran', NULL, NULL, 'https://quran.com/26/76');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1683, 'انت نتم وبو بوك وكم الق لقد قدم دمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1684, 'quran:26:77', 'quran', 'quran', '26:77', 77, 1683, 'Ash-Shu''ara', 'الشعراء', 'فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'فانهم عدو لي الا رب العلمين', 'ان عدو لي ال رب علم', 'quran', NULL, NULL, 'https://quran.com/26/77');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1684, 'فنه نهم عدو لي ال رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1685, 'quran:26:78', 'quran', 'quran', '26:78', 78, 1684, 'Ash-Shu''ara', 'الشعراء', 'ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ', NULL, NULL, 'الذي خلقني فهو يهدين', 'ذي خلقن فهو يهد', 'quran', NULL, NULL, 'https://quran.com/26/78');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1685, 'الذ لذي خلق لقن قني فهو يهد هدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1686, 'quran:26:79', 'quran', 'quran', '26:79', 79, 1685, 'Ash-Shu''ara', 'الشعراء', 'وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ', NULL, NULL, 'والذي هو يطعمني ويسقين', 'ذي هو يطعمن يسق', 'quran', NULL, NULL, 'https://quran.com/26/79');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1686, 'ولذ لذي هو يطع طعم عمن مني ويس يسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1687, 'quran:26:80', 'quran', 'quran', '26:80', 80, 1686, 'Ash-Shu''ara', 'الشعراء', 'وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ', NULL, NULL, 'واذا مرضت فهو يشفين', 'اذ مرضت فهو يشف', 'quran', NULL, NULL, 'https://quran.com/26/80');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1687, 'وذ مرض رضت فهو يشف شفي فين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1688, 'quran:26:81', 'quran', 'quran', '26:81', 81, 1687, 'Ash-Shu''ara', 'الشعراء', 'وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ', NULL, NULL, 'والذي يميتني ثم يحيين', 'ذي يميتن ثم يحي', 'quran', NULL, NULL, 'https://quran.com/26/81');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1688, 'ولذ لذي يمي ميت يتن تني ثم يحي حيي يين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1689, 'quran:26:82', 'quran', 'quran', '26:82', 82, 1688, 'Ash-Shu''ara', 'الشعراء', 'وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ', NULL, NULL, 'والذي اطمع ان يغفر لي خطيتي يوم الدين', 'ذي اطمع ان يغفر لي خطيت يوم دين', 'quran', NULL, NULL, 'https://quran.com/26/82');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1689, 'ولذ لذي اطم طمع ان يغف غفر لي خطي طيت يتي يوم الد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1690, 'quran:26:83', 'quran', 'quran', '26:83', 83, 1689, 'Ash-Shu''ara', 'الشعراء', 'رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ', NULL, NULL, 'رب هب لي حكما والحقني بالصلحين', 'رب هب لي حكم حقن صلح', 'quran', NULL, NULL, 'https://quran.com/26/83');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1690, 'رب هب لي حكم ولح لحق حقن قني بلص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1691, 'quran:26:84', 'quran', 'quran', '26:84', 84, 1690, 'Ash-Shu''ara', 'الشعراء', 'وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ', NULL, NULL, 'واجعل لي لسان صدق في الاخرين', 'اجعل لي لس صدق في اخر', 'quran', NULL, NULL, 'https://quran.com/26/84');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1691, 'وجع جعل لي لسن صدق في الخ لخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1692, 'quran:26:85', 'quran', 'quran', '26:85', 85, 1691, 'Ash-Shu''ara', 'الشعراء', 'وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', NULL, NULL, 'واجعلني من ورثه جنه النعيم', 'اجعلن من رث جن نعيم', 'quran', NULL, NULL, 'https://quran.com/26/85');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1692, 'وجع جعل علن لني من ورث رثه جنه الن لنع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1693, 'quran:26:86', 'quran', 'quran', '26:86', 86, 1692, 'Ash-Shu''ara', 'الشعراء', 'وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', NULL, NULL, 'واغفر لابي انه كان من الضالين', 'اغفر لب ان كن من ضل', 'quran', NULL, NULL, 'https://quran.com/26/86');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1693, 'وغف غفر لبي انه كن من الض لضل ضلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1694, 'quran:26:87', 'quran', 'quran', '26:87', 87, 1693, 'Ash-Shu''ara', 'الشعراء', 'وَلَا تُخۡزِنِي يَوۡمَ يُبۡعَثُونَ', NULL, NULL, 'ولا تخزني يوم يبعثون', 'ول تخزن يوم يبعث', 'quran', NULL, NULL, 'https://quran.com/26/87');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1694, 'ول تخز خزن زني يوم يبع بعث عثو ثون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1695, 'quran:26:88', 'quran', 'quran', '26:88', 88, 1694, 'Ash-Shu''ara', 'الشعراء', 'يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ', NULL, NULL, 'يوم لا ينفع مال ولا بنون', 'يوم ل ينفع مل ول بن', 'quran', NULL, NULL, 'https://quran.com/26/88');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1695, 'يوم ل ينف نفع مل ول بنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1696, 'quran:26:89', 'quran', 'quran', '26:89', 89, 1695, 'Ash-Shu''ara', 'الشعراء', 'إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ', NULL, NULL, 'الا من اتي الله بقلب سليم', 'ال من ات له بقلب سليم', 'quran', NULL, NULL, 'https://quran.com/26/89');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1696, 'ال من اتي الل لله بقل قلب سلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1697, 'quran:26:90', 'quran', 'quran', '26:90', 90, 1696, 'Ash-Shu''ara', 'الشعراء', 'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ', NULL, NULL, 'وازلفت الجنه للمتقين', 'ازلفت جن متق', 'quran', NULL, NULL, 'https://quran.com/26/90');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1697, 'وزل زلف لفت الج لجن جنه للم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1698, 'quran:26:91', 'quran', 'quran', '26:91', 91, 1697, 'Ash-Shu''ara', 'الشعراء', 'وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ', NULL, NULL, 'وبرزت الجحيم للغاوين', 'برزت جحيم غو', 'quran', NULL, NULL, 'https://quran.com/26/91');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1698, 'وبر برز رزت الج لجح جحي حيم للغ لغو غوي وين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1699, 'quran:26:92', 'quran', 'quran', '26:92', 92, 1698, 'Ash-Shu''ara', 'الشعراء', 'وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ', NULL, NULL, 'وقيل لهم اين ما كنتم تعبدون', 'قيل لهم اين م كنتم تعبد', 'quran', NULL, NULL, 'https://quran.com/26/92');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1699, 'وقي قيل لهم اين م كنت نتم تعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1700, 'quran:26:93', 'quran', 'quran', '26:93', 93, 1699, 'Ash-Shu''ara', 'الشعراء', 'مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ', NULL, NULL, 'من دون الله هل ينصرونكم او ينتصرون', 'من دون له هل ينصرون او ينتصر', 'quran', NULL, NULL, 'https://quran.com/26/93');
