INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1701, 'quran:26:94', 'quran', 'quran', '26:94', 94, 1700, 'Ash-Shu''ara', 'الشعراء', 'فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ', NULL, NULL, 'فكبكبوا فيها هم والغاون', 'كبكب يه هم غ', 'quran', NULL, NULL, 'https://quran.com/26/94');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1701, 'فكب كبك بكب كبو فيه هم ولغ لغو غون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1702, 'quran:26:95', 'quran', 'quran', '26:95', 95, 1701, 'Ash-Shu''ara', 'الشعراء', 'وَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ', NULL, NULL, 'وجنود ابليس اجمعون', 'جنود ابليس اجمع', 'quran', NULL, NULL, 'https://quran.com/26/95');
