INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1703, 'quran:26:96', 'quran', 'quran', '26:96', 96, 1702, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ', NULL, NULL, 'قالوا وهم فيها يختصمون', 'قل وهم يه يختصم', 'quran', NULL, NULL, 'https://quran.com/26/96');
