INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1704, 'quran:26:97', 'quran', 'quran', '26:97', 97, 1703, 'Ash-Shu''ara', 'الشعراء', 'تَٱللَّهِ إِن كُنَّا لَفِي ضَلَٰلٖ مُّبِينٍ', NULL, NULL, 'تالله ان كنا لفي ضلل مبين', 'تلل ان كن لف ضلل مب', 'quran', NULL, NULL, 'https://quran.com/26/97');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1704, 'تلل لله ان كن لفي ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1705, 'quran:26:98', 'quran', 'quran', '26:98', 98, 1704, 'Ash-Shu''ara', 'الشعراء', 'إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'اذ نسويكم برب العلمين', 'اذ نسوي برب علم', 'quran', NULL, NULL, 'https://quran.com/26/98');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1705, 'اذ نسو سوي ويك يكم برب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1706, 'quran:26:99', 'quran', 'quran', '26:99', 99, 1705, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَضَلَّنَآ إِلَّا ٱلۡمُجۡرِمُونَ', NULL, NULL, 'وما اضلنا الا المجرمون', 'وم اضل ال مجرم', 'quran', NULL, NULL, 'https://quran.com/26/99');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1706, 'وم اضل ضلن ال الم لمج مجر جرم رمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1707, 'quran:26:100', 'quran', 'quran', '26:100', 100, 1706, 'Ash-Shu''ara', 'الشعراء', 'فَمَا لَنَا مِن شَٰفِعِينَ', NULL, NULL, 'فما لنا من شفعين', 'فم لن من شفع', 'quran', NULL, NULL, 'https://quran.com/26/100');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1707, 'فم لن من شفع فعي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1708, 'quran:26:101', 'quran', 'quran', '26:101', 101, 1707, 'Ash-Shu''ara', 'الشعراء', 'وَلَا صَدِيقٍ حَمِيمٖ', NULL, NULL, 'ولا صديق حميم', 'ول صديق حميم', 'quran', NULL, NULL, 'https://quran.com/26/101');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1708, 'ول صدي ديق حمي ميم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1709, 'quran:26:102', 'quran', 'quran', '26:102', 102, 1708, 'Ash-Shu''ara', 'الشعراء', 'فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'فلو ان لنا كره فنكون من المومنين', 'فلو ان لن كر نك من مومن', 'quran', NULL, NULL, 'https://quran.com/26/102');
