INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1710, 'quran:26:103', 'quran', 'quran', '26:103', 103, 1709, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه وما كان اكثرهم مومنين', 'ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/103');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1710, 'ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1711, 'quran:26:104', 'quran', 'quran', '26:104', 104, 1710, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/104');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1711, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1712, 'quran:26:105', 'quran', 'quran', '26:105', 105, 1711, 'Ash-Shu''ara', 'الشعراء', 'كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'كذبت قوم نوح المرسلين', 'كذبت قوم نوح مرسل', 'quran', NULL, NULL, 'https://quran.com/26/105');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1712, 'كذب ذبت قوم نوح الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1713, 'quran:26:106', 'quran', 'quran', '26:106', 106, 1712, 'Ash-Shu''ara', 'الشعراء', 'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ', NULL, NULL, 'اذ قال لهم اخوهم نوح الا تتقون', 'اذ قل لهم اخو نوح ال تتق', 'quran', NULL, NULL, 'https://quran.com/26/106');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1713, 'اذ قل لهم اخو خوه وهم نوح ال تتق تقو قون');
