INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1718, 'quran:26:111', 'quran', 'quran', '26:111', 111, 1717, 'Ash-Shu''ara', 'الشعراء', 'قَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ', NULL, NULL, 'قالوا انومن لك واتبعك الارذلون', 'قل انومن لك اتبعك ارذل', 'quran', NULL, NULL, 'https://quran.com/26/111');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1718, 'قلو انو نوم ومن لك وتب تبع بعك الر لرذ رذل ذلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1719, 'quran:26:112', 'quran', 'quran', '26:112', 112, 1718, 'Ash-Shu''ara', 'الشعراء', 'قَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'قال وما علمي بما كانوا يعملون', 'قل وم علم بم كن يعمل', 'quran', NULL, NULL, 'https://quran.com/26/112');
