INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1720, 'quran:26:113', 'quran', 'quran', '26:113', 113, 1719, 'Ash-Shu''ara', 'الشعراء', 'إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّيۖ لَوۡ تَشۡعُرُونَ', NULL, NULL, 'ان حسابهم الا علي ربي لو تشعرون', 'ان حسب ال عل رب لو تشعر', 'quran', NULL, NULL, 'https://quran.com/26/113');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1720, 'ان حسب سبه بهم ال علي ربي لو تشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1721, 'quran:26:114', 'quran', 'quran', '26:114', 114, 1720, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'وما انا بطارد المومنين', 'وم ان بطرد مومن', 'quran', NULL, NULL, 'https://quran.com/26/114');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1721, 'وم ان بطر طرد الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1722, 'quran:26:115', 'quran', 'quran', '26:115', 115, 1721, 'Ash-Shu''ara', 'الشعراء', 'إِنۡ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ', NULL, NULL, 'ان انا الا نذير مبين', 'ان ان ال نذير مب', 'quran', NULL, NULL, 'https://quran.com/26/115');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1722, 'ان ان ال نذي ذير مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1723, 'quran:26:116', 'quran', 'quran', '26:116', 116, 1722, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلۡمَرۡجُومِينَ', NULL, NULL, 'قالوا لين لم تنته يا نوح لتكونن من المرجومين', 'قل لين لم تنت ي نوح لتكونن من مرجوم', 'quran', NULL, NULL, 'https://quran.com/26/116');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1723, 'قلو لين لم تنت نته ي نوح لتك تكو كون ونن من الم لمر مرج رجو جوم ومي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1724, 'quran:26:117', 'quran', 'quran', '26:117', 117, 1723, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبِّ إِنَّ قَوۡمِي كَذَّبُونِ', NULL, NULL, 'قال رب ان قومي كذبون', 'قل رب ان قوم كذب', 'quran', NULL, NULL, 'https://quran.com/26/117');
