INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1725, 'quran:26:118', 'quran', 'quran', '26:118', 118, 1724, 'Ash-Shu''ara', 'الشعراء', 'فَٱفۡتَحۡ بَيۡنِي وَبَيۡنَهُمۡ فَتۡحٗا وَنَجِّنِي وَمَن مَّعِيَ مِنَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'فافتح بيني وبينهم فتحا ونجني ومن معي من المومنين', 'افتح بين بين تح نجن ومن مع من مومن', 'quran', NULL, NULL, 'https://quran.com/26/118');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1725, 'ففت فتح بين يني وبي بين ينه نهم فتح ونج نجن جني ومن معي من الم لمو موم ومن مني نين');
