INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1742, 'quran:26:135', 'quran', 'quran', '26:135', 135, 1741, 'Ash-Shu''ara', 'الشعراء', 'إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ', NULL, NULL, 'اني اخاف عليكم عذاب يوم عظيم', 'ان اخف علي عذب يوم عظيم', 'quran', NULL, NULL, 'https://quran.com/26/135');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1742, 'اني اخف علي ليك يكم عذب يوم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1743, 'quran:26:136', 'quran', 'quran', '26:136', 136, 1742, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ', NULL, NULL, 'قالوا سواء علينا اوعظت ام لم تكن من الوعظين', 'قل سوء علي اوعظت ام لم تكن من وعظ', 'quran', NULL, NULL, 'https://quran.com/26/136');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1743, 'قلو سوء علي لين اوع وعظ عظت ام لم تكن من الو لوع وعظ عظي ظين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1744, 'quran:26:137', 'quran', 'quran', '26:137', 137, 1743, 'Ash-Shu''ara', 'الشعراء', 'إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ', NULL, NULL, 'ان هذا الا خلق الاولين', 'ان هذ ال خلق اول', 'quran', NULL, NULL, 'https://quran.com/26/137');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1744, 'ان هذ ال خلق الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1745, 'quran:26:138', 'quran', 'quran', '26:138', 138, 1744, 'Ash-Shu''ara', 'الشعراء', 'وَمَا نَحۡنُ بِمُعَذَّبِينَ', NULL, NULL, 'وما نحن بمعذبين', 'وم نحن بمعذب', 'quran', NULL, NULL, 'https://quran.com/26/138');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1745, 'وم نحن بمع معذ عذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1746, 'quran:26:139', 'quran', 'quran', '26:139', 139, 1745, 'Ash-Shu''ara', 'الشعراء', 'فَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'فكذبوه فاهلكنهم ان في ذلك لايه وما كان اكثرهم مومنين', 'كذبو اهلكن ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/139');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1746, 'فكذ كذب ذبو بوه فهل هلك لكن كنه نهم ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1747, 'quran:26:140', 'quran', 'quran', '26:140', 140, 1746, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/140');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1747, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1748, 'quran:26:141', 'quran', 'quran', '26:141', 141, 1747, 'Ash-Shu''ara', 'الشعراء', 'كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'كذبت ثمود المرسلين', 'كذبت ثمود مرسل', 'quran', NULL, NULL, 'https://quran.com/26/141');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1748, 'كذب ذبت ثمو مود الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1749, 'quran:26:142', 'quran', 'quran', '26:142', 142, 1748, 'Ash-Shu''ara', 'الشعراء', 'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ صَٰلِحٌ أَلَا تَتَّقُونَ', NULL, NULL, 'اذ قال لهم اخوهم صلح الا تتقون', 'اذ قل لهم اخو صلح ال تتق', 'quran', NULL, NULL, 'https://quran.com/26/142');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1749, 'اذ قل لهم اخو خوه وهم صلح ال تتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1750, 'quran:26:143', 'quran', 'quran', '26:143', 143, 1749, 'Ash-Shu''ara', 'الشعراء', 'إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ', NULL, NULL, 'اني لكم رسول امين', 'ان لكم رسول ام', 'quran', NULL, NULL, 'https://quran.com/26/143');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1750, 'اني لكم رسو سول امي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1751, 'quran:26:144', 'quran', 'quran', '26:144', 144, 1750, 'Ash-Shu''ara', 'الشعراء', 'فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', NULL, NULL, 'فاتقوا الله واطيعون', 'اتق له اطيع', 'quran', NULL, NULL, 'https://quran.com/26/144');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1751, 'فتق تقو الل لله وطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1752, 'quran:26:145', 'quran', 'quran', '26:145', 145, 1751, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين', 'وم اسل عل من اجر ان اجر ال عل رب علم', 'quran', NULL, NULL, 'https://quran.com/26/145');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1752, 'وم اسل سلك لكم علي ليه من اجر ان اجر جري ال علي رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1753, 'quran:26:146', 'quran', 'quran', '26:146', 146, 1752, 'Ash-Shu''ara', 'الشعراء', 'أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ', NULL, NULL, 'اتتركون في ما ههنا امنين', 'اتترك في م هه امن', 'quran', NULL, NULL, 'https://quran.com/26/146');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1753, 'اتت تتر ترك ركو كون في م ههن امن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1754, 'quran:26:147', 'quran', 'quran', '26:147', 147, 1753, 'Ash-Shu''ara', 'الشعراء', 'فِي جَنَّٰتٖ وَعُيُونٖ', NULL, NULL, 'في جنت وعيون', 'في جنت عي', 'quran', NULL, NULL, 'https://quran.com/26/147');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1754, 'في جنت وعي عيو يون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1755, 'quran:26:148', 'quran', 'quran', '26:148', 148, 1754, 'Ash-Shu''ara', 'الشعراء', 'وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ', NULL, NULL, 'وزروع ونخل طلعها هضيم', 'زروع نخل طلع هضيم', 'quran', NULL, NULL, 'https://quran.com/26/148');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1755, 'وزر زرو روع ونخ نخل طلع لعه هضي ضيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1756, 'quran:26:149', 'quran', 'quran', '26:149', 149, 1755, 'Ash-Shu''ara', 'الشعراء', 'وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ', NULL, NULL, 'وتنحتون من الجبال بيوتا فرهين', 'تنحت من جبل بيوت ره', 'quran', NULL, NULL, 'https://quran.com/26/149');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1756, 'وتن تنح نحت حتو تون من الج لجب جبل بيو يوت فره رهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1757, 'quran:26:150', 'quran', 'quran', '26:150', 150, 1756, 'Ash-Shu''ara', 'الشعراء', 'فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', NULL, NULL, 'فاتقوا الله واطيعون', 'اتق له اطيع', 'quran', NULL, NULL, 'https://quran.com/26/150');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1757, 'فتق تقو الل لله وطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1758, 'quran:26:151', 'quran', 'quran', '26:151', 151, 1757, 'Ash-Shu''ara', 'الشعراء', 'وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ', NULL, NULL, 'ولا تطيعوا امر المسرفين', 'ول تطيع امر مسرف', 'quran', NULL, NULL, 'https://quran.com/26/151');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1758, 'ول تطي طيع يعو امر الم لمس مسر سرف رفي فين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1759, 'quran:26:152', 'quran', 'quran', '26:152', 152, 1758, 'Ash-Shu''ara', 'الشعراء', 'ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ', NULL, NULL, 'الذين يفسدون في الارض ولا يصلحون', 'ذين يفسد في ارض ول يصلح', 'quran', NULL, NULL, 'https://quran.com/26/152');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1759, 'الذ لذي ذين يفس فسد سدو دون في الر لرض ول يصل صلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1760, 'quran:26:153', 'quran', 'quran', '26:153', 153, 1759, 'Ash-Shu''ara', 'الشعراء', 'قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ', NULL, NULL, 'قالوا انما انت من المسحرين', 'قل انم انت من مسحر', 'quran', NULL, NULL, 'https://quran.com/26/153');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1760, 'قلو انم انت من الم لمس مسح سحر حري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1761, 'quran:26:154', 'quran', 'quran', '26:154', 154, 1760, 'Ash-Shu''ara', 'الشعراء', 'مَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا فَأۡتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', NULL, NULL, 'ما انت الا بشر مثلنا فات بايه ان كنت من الصدقين', 'م انت ال بشر مثل فت ب ان كنت من صدق', 'quran', NULL, NULL, 'https://quran.com/26/154');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1761, 'م انت ال بشر مثل ثلن فت بيه ان كنت من الص لصد صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1762, 'quran:26:155', 'quran', 'quran', '26:155', 155, 1761, 'Ash-Shu''ara', 'الشعراء', 'قَالَ هَٰذِهِۦ نَاقَةٞ لَّهَا شِرۡبٞ وَلَكُمۡ شِرۡبُ يَوۡمٖ مَّعۡلُومٖ', NULL, NULL, 'قال هذه ناقه لها شرب ولكم شرب يوم معلوم', 'قل هذ نق له شرب لكم شرب يوم معلوم', 'quran', NULL, NULL, 'https://quran.com/26/155');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1762, 'قل هذه نقه له شرب ولك لكم شرب يوم معل علو لوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1763, 'quran:26:156', 'quran', 'quran', '26:156', 156, 1762, 'Ash-Shu''ara', 'الشعراء', 'وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ عَظِيمٖ', NULL, NULL, 'ولا تمسوها بسوء فياخذكم عذاب يوم عظيم', 'ول تمسو بسوء يخذ عذب يوم عظيم', 'quran', NULL, NULL, 'https://quran.com/26/156');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1763, 'ول تمس مسو سوه بسو سوء فيخ يخذ خذك ذكم عذب يوم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1764, 'quran:26:157', 'quran', 'quran', '26:157', 157, 1763, 'Ash-Shu''ara', 'الشعراء', 'فَعَقَرُوهَا فَأَصۡبَحُواْ نَٰدِمِينَ', NULL, NULL, 'فعقروها فاصبحوا ندمين', 'عقرو اصبح ندم', 'quran', NULL, NULL, 'https://quran.com/26/157');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1764, 'فعق عقر قرو روه فصب صبح بحو ندم دمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1765, 'quran:26:158', 'quran', 'quran', '26:158', 158, 1764, 'Ash-Shu''ara', 'الشعراء', 'فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'فاخذهم العذاب ان في ذلك لايه وما كان اكثرهم مومنين', 'اخذ عذب ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/158');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1765, 'فخذ خذه ذهم الع لعذ عذب ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1766, 'quran:26:159', 'quran', 'quran', '26:159', 159, 1765, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/159');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1766, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1767, 'quran:26:160', 'quran', 'quran', '26:160', 160, 1766, 'Ash-Shu''ara', 'الشعراء', 'كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'كذبت قوم لوط المرسلين', 'كذبت قوم لوط مرسل', 'quran', NULL, NULL, 'https://quran.com/26/160');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1767, 'كذب ذبت قوم لوط الم لمر مرس رسل سلي لين');
