INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1770, 'quran:26:163', 'quran', 'quran', '26:163', 163, 1769, 'Ash-Shu''ara', 'الشعراء', 'فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', NULL, NULL, 'فاتقوا الله واطيعون', 'اتق له اطيع', 'quran', NULL, NULL, 'https://quran.com/26/163');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1770, 'فتق تقو الل لله وطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1771, 'quran:26:164', 'quran', 'quran', '26:164', 164, 1770, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين', 'وم اسل عل من اجر ان اجر ال عل رب علم', 'quran', NULL, NULL, 'https://quran.com/26/164');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1771, 'وم اسل سلك لكم علي ليه من اجر ان اجر جري ال علي رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1772, 'quran:26:165', 'quran', 'quran', '26:165', 165, 1771, 'Ash-Shu''ara', 'الشعراء', 'أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ', NULL, NULL, 'اتاتون الذكران من العلمين', 'اتت ذكر من علم', 'quran', NULL, NULL, 'https://quran.com/26/165');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1772, 'اتت تتو تون الذ لذك ذكر كرن من الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1773, 'quran:26:166', 'quran', 'quran', '26:166', 166, 1772, 'Ash-Shu''ara', 'الشعراء', 'وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ', NULL, NULL, 'وتذرون ما خلق لكم ربكم من ازوجكم بل انتم قوم عادون', 'تذر م خلق لكم رب من ازوج بل انتم قوم عد', 'quran', NULL, NULL, 'https://quran.com/26/166');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1773, 'وتذ تذر ذرو رون م خلق لكم ربك بكم من ازو زوج وجك جكم بل انت نتم قوم عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1774, 'quran:26:167', 'quran', 'quran', '26:167', 167, 1773, 'Ash-Shu''ara', 'الشعراء', 'قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ', NULL, NULL, 'قالوا لين لم تنته يا لوط لتكونن من المخرجين', 'قل لين لم تنت ي لوط لتكونن من مخرج', 'quran', NULL, NULL, 'https://quran.com/26/167');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1774, 'قلو لين لم تنت نته ي لوط لتك تكو كون ونن من الم لمخ مخر خرج رجي جين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1775, 'quran:26:168', 'quran', 'quran', '26:168', 168, 1774, 'Ash-Shu''ara', 'الشعراء', 'قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ', NULL, NULL, 'قال اني لعملكم من القالين', 'قل ان لعمل من قل', 'quran', NULL, NULL, 'https://quran.com/26/168');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1775, 'قل اني لعم عمل ملك لكم من الق لقل قلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1776, 'quran:26:169', 'quran', 'quran', '26:169', 169, 1775, 'Ash-Shu''ara', 'الشعراء', 'رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ', NULL, NULL, 'رب نجني واهلي مما يعملون', 'رب نجن اهل مم يعمل', 'quran', NULL, NULL, 'https://quran.com/26/169');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1776, 'رب نجن جني وهل هلي مم يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1777, 'quran:26:170', 'quran', 'quran', '26:170', 170, 1776, 'Ash-Shu''ara', 'الشعراء', 'فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ', NULL, NULL, 'فنجينه واهله اجمعين', 'نجين اهل اجمع', 'quran', NULL, NULL, 'https://quran.com/26/170');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1777, 'فنج نجي جين ينه وهل هله اجم جمع معي عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1778, 'quran:26:171', 'quran', 'quran', '26:171', 171, 1777, 'Ash-Shu''ara', 'الشعراء', 'إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ', NULL, NULL, 'الا عجوزا في الغبرين', 'ال عجوز في غبر', 'quran', NULL, NULL, 'https://quran.com/26/171');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1778, 'ال عجو جوز في الغ لغب غبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1779, 'quran:26:172', 'quran', 'quran', '26:172', 172, 1778, 'Ash-Shu''ara', 'الشعراء', 'ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ', NULL, NULL, 'ثم دمرنا الاخرين', 'ثم دمر اخر', 'quran', NULL, NULL, 'https://quran.com/26/172');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1779, 'ثم دمر مرن الخ لخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1780, 'quran:26:173', 'quran', 'quran', '26:173', 173, 1779, 'Ash-Shu''ara', 'الشعراء', 'وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ', NULL, NULL, 'وامطرنا عليهم مطرا فساء مطر المنذرين', 'امطر علي مطر سء مطر منذر', 'quran', NULL, NULL, 'https://quran.com/26/173');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1780, 'ومط مطر طرن علي ليه يهم مطر فسء مطر الم لمن منذ نذر ذري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1781, 'quran:26:174', 'quran', 'quran', '26:174', 174, 1780, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه وما كان اكثرهم مومنين', 'ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/174');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1781, 'ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1782, 'quran:26:175', 'quran', 'quran', '26:175', 175, 1781, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/175');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1782, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1783, 'quran:26:176', 'quran', 'quran', '26:176', 176, 1782, 'Ash-Shu''ara', 'الشعراء', 'كَذَّبَ أَصۡحَٰبُ لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ', NULL, NULL, 'كذب اصحب ليكه المرسلين', 'كذب اصحب ليك مرسل', 'quran', NULL, NULL, 'https://quran.com/26/176');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1783, 'كذب اصح صحب ليك يكه الم لمر مرس رسل سلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1784, 'quran:26:177', 'quran', 'quran', '26:177', 177, 1783, 'Ash-Shu''ara', 'الشعراء', 'إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ', NULL, NULL, 'اذ قال لهم شعيب الا تتقون', 'اذ قل لهم شعيب ال تتق', 'quran', NULL, NULL, 'https://quran.com/26/177');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1784, 'اذ قل لهم شعي عيب ال تتق تقو قون');
