INSERT INTO units_tri_src (id, ar_tri) VALUES (1786, 'فتق تقو الل لله وطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1787, 'quran:26:180', 'quran', 'quran', '26:180', 180, 1786, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'وما اسلكم عليه من اجر ان اجري الا علي رب العلمين', 'وم اسل عل من اجر ان اجر ال عل رب علم', 'quran', NULL, NULL, 'https://quran.com/26/180');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1787, 'وم اسل سلك لكم علي ليه من اجر ان اجر جري ال علي رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1788, 'quran:26:181', 'quran', 'quran', '26:181', 181, 1787, 'Ash-Shu''ara', 'الشعراء', 'أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ', NULL, NULL, 'اوفوا الكيل ولا تكونوا من المخسرين', 'اوف كيل ول تكون من مخسر', 'quran', NULL, NULL, 'https://quran.com/26/181');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1788, 'اوف وفو الك لكي كيل ول تكو كون ونو من الم لمخ مخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1789, 'quran:26:182', 'quran', 'quran', '26:182', 182, 1788, 'Ash-Shu''ara', 'الشعراء', 'وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ', NULL, NULL, 'وزنوا بالقسطاس المستقيم', 'زن قسطس مستقيم', 'quran', NULL, NULL, 'https://quran.com/26/182');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1789, 'وزن زنو بلق لقس قسط سطس الم لمس مست ستق تقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1790, 'quran:26:183', 'quran', 'quran', '26:183', 183, 1789, 'Ash-Shu''ara', 'الشعراء', 'وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', NULL, NULL, 'ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين', 'ول تبخس نس اشيء ول تعث في ارض مفسد', 'quran', NULL, NULL, 'https://quran.com/26/183');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1790, 'ول تبخ بخس خسو الن لنس اشي شيء يءه ءهم ول تعث عثو في الر لرض مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1791, 'quran:26:184', 'quran', 'quran', '26:184', 184, 1790, 'Ash-Shu''ara', 'الشعراء', 'وَٱتَّقُواْ ٱلَّذِي خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ', NULL, NULL, 'واتقوا الذي خلقكم والجبله الاولين', 'اتق ذي خلق جبل اول', 'quran', NULL, NULL, 'https://quran.com/26/184');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1791, 'وتق تقو الذ لذي خلق لقك قكم ولج لجب جبل بله الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1792, 'quran:26:185', 'quran', 'quran', '26:185', 185, 1791, 'Ash-Shu''ara', 'الشعراء', 'قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ', NULL, NULL, 'قالوا انما انت من المسحرين', 'قل انم انت من مسحر', 'quran', NULL, NULL, 'https://quran.com/26/185');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1792, 'قلو انم انت من الم لمس مسح سحر حري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1793, 'quran:26:186', 'quran', 'quran', '26:186', 186, 1792, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَٰذِبِينَ', NULL, NULL, 'وما انت الا بشر مثلنا وان نظنك لمن الكذبين', 'وم انت ال بشر مثل ون نظنك لمن كذب', 'quran', NULL, NULL, 'https://quran.com/26/186');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1793, 'وم انت ال بشر مثل ثلن ون نظن ظنك لمن الك لكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1794, 'quran:26:187', 'quran', 'quran', '26:187', 187, 1793, 'Ash-Shu''ara', 'الشعراء', 'فَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', NULL, NULL, 'فاسقط علينا كسفا من السماء ان كنت من الصدقين', 'اسقط علي كسف من سمء ان كنت من صدق', 'quran', NULL, NULL, 'https://quran.com/26/187');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1794, 'فسق سقط علي لين كسف من الس لسم سمء ان كنت من الص لصد صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1795, 'quran:26:188', 'quran', 'quran', '26:188', 188, 1794, 'Ash-Shu''ara', 'الشعراء', 'قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ', NULL, NULL, 'قال ربي اعلم بما تعملون', 'قل رب اعلم بم تعمل', 'quran', NULL, NULL, 'https://quran.com/26/188');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1795, 'قل ربي اعل علم بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1796, 'quran:26:189', 'quran', 'quran', '26:189', 189, 1795, 'Ash-Shu''ara', 'الشعراء', 'فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ', NULL, NULL, 'فكذبوه فاخذهم عذاب يوم الظله انه كان عذاب يوم عظيم', 'كذبو اخذ عذب يوم ظل ان كن عذب يوم عظيم', 'quran', NULL, NULL, 'https://quran.com/26/189');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1796, 'فكذ كذب ذبو بوه فخذ خذه ذهم عذب يوم الظ لظل ظله انه كن عذب يوم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1797, 'quran:26:190', 'quran', 'quran', '26:190', 190, 1796, 'Ash-Shu''ara', 'الشعراء', 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', NULL, NULL, 'ان في ذلك لايه وما كان اكثرهم مومنين', 'ان في ذلك ل وم كن اكثر مومن', 'quran', NULL, NULL, 'https://quran.com/26/190');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1797, 'ان في ذلك ليه وم كن اكث كثر ثره رهم موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1798, 'quran:26:191', 'quran', 'quran', '26:191', 191, 1797, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', NULL, NULL, 'وان ربك لهو العزيز الرحيم', 'ون ربك لهو عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/191');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1798, 'ون ربك لهو الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1799, 'quran:26:192', 'quran', 'quran', '26:192', 192, 1798, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'وانه لتنزيل رب العلمين', 'ان لتنزيل رب علم', 'quran', NULL, NULL, 'https://quran.com/26/192');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1799, 'ونه لتن تنز نزي زيل رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1800, 'quran:26:193', 'quran', 'quran', '26:193', 193, 1799, 'Ash-Shu''ara', 'الشعراء', 'نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ', NULL, NULL, 'نزل به الروح الامين', 'نزل به روح ام', 'quran', NULL, NULL, 'https://quran.com/26/193');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1800, 'نزل به الر لرو روح الم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1801, 'quran:26:194', 'quran', 'quran', '26:194', 194, 1800, 'Ash-Shu''ara', 'الشعراء', 'عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ', NULL, NULL, 'علي قلبك لتكون من المنذرين', 'عل قلبك لتك من منذر', 'quran', NULL, NULL, 'https://quran.com/26/194');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1801, 'علي قلب لبك لتك تكو كون من الم لمن منذ نذر ذري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1802, 'quran:26:195', 'quran', 'quran', '26:195', 195, 1801, 'Ash-Shu''ara', 'الشعراء', 'بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ', NULL, NULL, 'بلسان عربي مبين', 'بلس عرب مب', 'quran', NULL, NULL, 'https://quran.com/26/195');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1802, 'بلس لسن عرب ربي مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1803, 'quran:26:196', 'quran', 'quran', '26:196', 196, 1802, 'Ash-Shu''ara', 'الشعراء', 'وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ', NULL, NULL, 'وانه لفي زبر الاولين', 'ان لف زبر اول', 'quran', NULL, NULL, 'https://quran.com/26/196');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1803, 'ونه لفي زبر الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1804, 'quran:26:197', 'quran', 'quran', '26:197', 197, 1803, 'Ash-Shu''ara', 'الشعراء', 'أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ', NULL, NULL, 'اولم يكن لهم ايه ان يعلمه علموا بني اسرءيل', 'اولم يكن لهم اي ان يعلم علم بن اسرءيل', 'quran', NULL, NULL, 'https://quran.com/26/197');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1804, 'اول ولم يكن لهم ايه ان يعل علم لمه علم لمو بني اسر سرء رءي ءيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1805, 'quran:26:198', 'quran', 'quran', '26:198', 198, 1804, 'Ash-Shu''ara', 'الشعراء', 'وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِينَ', NULL, NULL, 'ولو نزلنه علي بعض الاعجمين', 'ولو نزلن عل بعض اعجم', 'quran', NULL, NULL, 'https://quran.com/26/198');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1805, 'ولو نزل زلن لنه علي بعض الع لعج عجم جمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1806, 'quran:26:199', 'quran', 'quran', '26:199', 199, 1805, 'Ash-Shu''ara', 'الشعراء', 'فَقَرَأَهُۥ عَلَيۡهِم مَّا كَانُواْ بِهِۦ مُؤۡمِنِينَ', NULL, NULL, 'فقراه عليهم ما كانوا به مومنين', 'قر علي م كن به مومن', 'quran', NULL, NULL, 'https://quran.com/26/199');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1806, 'فقر قره علي ليه يهم م كنو به موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1807, 'quran:26:200', 'quran', 'quran', '26:200', 200, 1806, 'Ash-Shu''ara', 'الشعراء', 'كَذَٰلِكَ سَلَكۡنَٰهُ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ', NULL, NULL, 'كذلك سلكنه في قلوب المجرمين', 'كذلك سلكن في قلوب مجرم', 'quran', NULL, NULL, 'https://quran.com/26/200');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1807, 'كذل ذلك سلك لكن كنه في قلو لوب الم لمج مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1808, 'quran:26:201', 'quran', 'quran', '26:201', 201, 1807, 'Ash-Shu''ara', 'الشعراء', 'لَا يُؤۡمِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ', NULL, NULL, 'لا يومنون به حتي يروا العذاب الاليم', 'ل يومن به حت ير عذب اليم', 'quran', NULL, NULL, 'https://quran.com/26/201');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1808, 'ل يوم ومن منو نون به حتي يرو الع لعذ عذب الل للي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1809, 'quran:26:202', 'quran', 'quran', '26:202', 202, 1808, 'Ash-Shu''ara', 'الشعراء', 'فَيَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ', NULL, NULL, 'فياتيهم بغته وهم لا يشعرون', 'يتي بغت وهم ل يشعر', 'quran', NULL, NULL, 'https://quran.com/26/202');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1809, 'فيت يتي تيه يهم بغت غته وهم ل يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1810, 'quran:26:203', 'quran', 'quran', '26:203', 203, 1809, 'Ash-Shu''ara', 'الشعراء', 'فَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ', NULL, NULL, 'فيقولوا هل نحن منظرون', 'يقول هل نحن منظر', 'quran', NULL, NULL, 'https://quran.com/26/203');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1810, 'فيق يقو قول ولو هل نحن منظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1811, 'quran:26:204', 'quran', 'quran', '26:204', 204, 1810, 'Ash-Shu''ara', 'الشعراء', 'أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ', NULL, NULL, 'افبعذابنا يستعجلون', 'افبعذب يستعجل', 'quran', NULL, NULL, 'https://quran.com/26/204');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1811, 'افب فبع بعذ عذب ذبن يست ستع تعج عجل جلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1812, 'quran:26:205', 'quran', 'quran', '26:205', 205, 1811, 'Ash-Shu''ara', 'الشعراء', 'أَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ', NULL, NULL, 'افرءيت ان متعنهم سنين', 'افرءيت ان متعن سن', 'quran', NULL, NULL, 'https://quran.com/26/205');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1812, 'افر فرء رءي ءيت ان متع تعن عنه نهم سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1813, 'quran:26:206', 'quran', 'quran', '26:206', 206, 1812, 'Ash-Shu''ara', 'الشعراء', 'ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ', NULL, NULL, 'ثم جاءهم ما كانوا يوعدون', 'ثم جء م كن يوعد', 'quran', NULL, NULL, 'https://quran.com/26/206');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1813, 'ثم جءه ءهم م كنو يوع وعد عدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1814, 'quran:26:207', 'quran', 'quran', '26:207', 207, 1813, 'Ash-Shu''ara', 'الشعراء', 'مَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ', NULL, NULL, 'ما اغني عنهم ما كانوا يمتعون', 'م اغن عن م كن يمتع', 'quran', NULL, NULL, 'https://quran.com/26/207');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1814, 'م اغن غني عنه نهم م كنو يمت متع تعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1815, 'quran:26:208', 'quran', 'quran', '26:208', 208, 1814, 'Ash-Shu''ara', 'الشعراء', 'وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا لَهَا مُنذِرُونَ', NULL, NULL, 'وما اهلكنا من قريه الا لها منذرون', 'وم اهلك من قر ال له منذر', 'quran', NULL, NULL, 'https://quran.com/26/208');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1815, 'وم اهل هلك لكن من قري ريه ال له منذ نذر ذرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1816, 'quran:26:209', 'quran', 'quran', '26:209', 209, 1815, 'Ash-Shu''ara', 'الشعراء', 'ذِكۡرَىٰ وَمَا كُنَّا ظَٰلِمِينَ', NULL, NULL, 'ذكري وما كنا ظلمين', 'ذكر وم كن ظلم', 'quran', NULL, NULL, 'https://quran.com/26/209');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1816, 'ذكر كري وم كن ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1817, 'quran:26:210', 'quran', 'quran', '26:210', 210, 1816, 'Ash-Shu''ara', 'الشعراء', 'وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ', NULL, NULL, 'وما تنزلت به الشيطين', 'وم تنزلت به شيط', 'quran', NULL, NULL, 'https://quran.com/26/210');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1817, 'وم تنز نزل زلت به الش لشي شيط يطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1818, 'quran:26:211', 'quran', 'quran', '26:211', 211, 1817, 'Ash-Shu''ara', 'الشعراء', 'وَمَا يَنۢبَغِي لَهُمۡ وَمَا يَسۡتَطِيعُونَ', NULL, NULL, 'وما ينبغي لهم وما يستطيعون', 'وم ينبغ لهم وم يستطيع', 'quran', NULL, NULL, 'https://quran.com/26/211');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1818, 'وم ينب نبغ بغي لهم وم يست ستط تطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1819, 'quran:26:212', 'quran', 'quran', '26:212', 212, 1818, 'Ash-Shu''ara', 'الشعراء', 'إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ', NULL, NULL, 'انهم عن السمع لمعزولون', 'ان عن سمع لمعزول', 'quran', NULL, NULL, 'https://quran.com/26/212');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1819, 'انه نهم عن الس لسم سمع لمع معز عزو زول ولو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1820, 'quran:26:213', 'quran', 'quran', '26:213', 213, 1819, 'Ash-Shu''ara', 'الشعراء', 'فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ', NULL, NULL, 'فلا تدع مع الله الها اخر فتكون من المعذبين', 'فل تدع مع له ه اخر تك من معذب', 'quran', NULL, NULL, 'https://quran.com/26/213');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1820, 'فل تدع مع الل لله اله اخر فتك تكو كون من الم لمع معذ عذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1821, 'quran:26:214', 'quran', 'quran', '26:214', 214, 1820, 'Ash-Shu''ara', 'الشعراء', 'وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ', NULL, NULL, 'وانذر عشيرتك الاقربين', 'انذر عشيرتك اقرب', 'quran', NULL, NULL, 'https://quran.com/26/214');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1821, 'ونذ نذر عشي شير يرت رتك الق لقر قرب ربي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1822, 'quran:26:215', 'quran', 'quran', '26:215', 215, 1821, 'Ash-Shu''ara', 'الشعراء', 'وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ', NULL, NULL, 'واخفض جناحك لمن اتبعك من المومنين', 'اخفض جنحك لمن اتبعك من مومن', 'quran', NULL, NULL, 'https://quran.com/26/215');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1822, 'وخف خفض جنح نحك لمن اتب تبع بعك من الم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1823, 'quran:26:216', 'quran', 'quran', '26:216', 216, 1822, 'Ash-Shu''ara', 'الشعراء', 'فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ', NULL, NULL, 'فان عصوك فقل اني بريء مما تعملون', 'فن عصوك فقل ان بريء مم تعمل', 'quran', NULL, NULL, 'https://quran.com/26/216');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1823, 'فن عصو صوك فقل اني بري ريء مم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1824, 'quran:26:217', 'quran', 'quran', '26:217', 217, 1823, 'Ash-Shu''ara', 'الشعراء', 'وَتَوَكَّلۡ عَلَى ٱلۡعَزِيزِ ٱلرَّحِيمِ', NULL, NULL, 'وتوكل علي العزيز الرحيم', 'توكل عل عزيز رحيم', 'quran', NULL, NULL, 'https://quran.com/26/217');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1824, 'وتو توك وكل علي الع لعز عزي زيز الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1825, 'quran:26:218', 'quran', 'quran', '26:218', 218, 1824, 'Ash-Shu''ara', 'الشعراء', 'ٱلَّذِي يَرَىٰكَ حِينَ تَقُومُ', NULL, NULL, 'الذي يراك حين تقوم', 'ذي يرك حين تقوم', 'quran', NULL, NULL, 'https://quran.com/26/218');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1825, 'الذ لذي يرك حين تقو قوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1826, 'quran:26:219', 'quran', 'quran', '26:219', 219, 1825, 'Ash-Shu''ara', 'الشعراء', 'وَتَقَلُّبَكَ فِي ٱلسَّٰجِدِينَ', NULL, NULL, 'وتقلبك في السجدين', 'تقلبك في سجد', 'quran', NULL, NULL, 'https://quran.com/26/219');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1826, 'وتق تقل قلب لبك في الس لسج سجد جدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1827, 'quran:26:220', 'quran', 'quran', '26:220', 220, 1826, 'Ash-Shu''ara', 'الشعراء', 'إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'انه هو السميع العليم', 'ان هو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/26/220');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1827, 'انه هو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1828, 'quran:26:221', 'quran', 'quran', '26:221', 221, 1827, 'Ash-Shu''ara', 'الشعراء', 'هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ', NULL, NULL, 'هل انبيكم علي من تنزل الشيطين', 'هل انبي عل من تنزل شيط', 'quran', NULL, NULL, 'https://quran.com/26/221');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1828, 'هل انب نبي بيك يكم علي من تنز نزل الش لشي شيط يطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1829, 'quran:26:222', 'quran', 'quran', '26:222', 222, 1828, 'Ash-Shu''ara', 'الشعراء', 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ', NULL, NULL, 'تنزل علي كل افاك اثيم', 'تنزل عل كل افك اثيم', 'quran', NULL, NULL, 'https://quran.com/26/222');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1829, 'تنز نزل علي كل افك اثي ثيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1830, 'quran:26:223', 'quran', 'quran', '26:223', 223, 1829, 'Ash-Shu''ara', 'الشعراء', 'يُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ', NULL, NULL, 'يلقون السمع واكثرهم كذبون', 'يلق سمع اكثر كذب', 'quran', NULL, NULL, 'https://quran.com/26/223');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1830, 'يلق لقو قون الس لسم سمع وكث كثر ثره رهم كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1831, 'quran:26:224', 'quran', 'quran', '26:224', 224, 1830, 'Ash-Shu''ara', 'الشعراء', 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلۡغَاوُۥنَ', NULL, NULL, 'والشعراء يتبعهم الغاون', 'شعرء يتبع غ', 'quran', NULL, NULL, 'https://quran.com/26/224');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1831, 'ولش لشع شعر عرء يتب تبع بعه عهم الغ لغو غون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1832, 'quran:26:225', 'quran', 'quran', '26:225', 225, 1831, 'Ash-Shu''ara', 'الشعراء', 'أَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٖ يَهِيمُونَ', NULL, NULL, 'الم تر انهم في كل واد يهيمون', 'الم تر ان في كل ود يهيم', 'quran', NULL, NULL, 'https://quran.com/26/225');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1832, 'الم تر انه نهم في كل ود يهي هيم يمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1833, 'quran:26:226', 'quran', 'quran', '26:226', 226, 1832, 'Ash-Shu''ara', 'الشعراء', 'وَأَنَّهُمۡ يَقُولُونَ مَا لَا يَفۡعَلُونَ', NULL, NULL, 'وانهم يقولون ما لا يفعلون', 'ان يقول م ل يفعل', 'quran', NULL, NULL, 'https://quran.com/26/226');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1833, 'ونه نهم يقو قول ولو لون م ل يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1834, 'quran:26:227', 'quran', 'quran', '26:227', 227, 1833, 'Ash-Shu''ara', 'الشعراء', 'إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَذَكَرُواْ ٱللَّهَ كَثِيرٗا وَٱنتَصَرُواْ مِنۢ بَعۡدِ مَا ظُلِمُواْۗ وَسَيَعۡلَمُ ٱلَّذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبٖ يَنقَلِبُونَ', NULL, NULL, 'الا الذين امنوا وعملوا الصلحت وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا اي منقلب ينقلبون', 'ال ذين امن عمل صلحت ذكر له كثير انتصر من بعد م ظلم سيعلم ذين ظلم اي منقلب ينقلب', 'quran', NULL, NULL, 'https://quran.com/26/227');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1834, 'ال الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت وذك ذكر كرو الل لله كثي ثير ونت نتص تصر صرو من بعد م ظلم لمو وسي سيع يعل علم الذ لذي ذين ظلم لمو اي منق نقل قلب ينق نقل قلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1835, 'quran:29:1', 'quran', 'quran', '29:1', 1, 1834, 'Al-''Ankabut', 'العنكبوت', 'الٓمٓ', NULL, NULL, 'الم', 'الم', 'quran', NULL, NULL, 'https://quran.com/29/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1835, 'الم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1836, 'quran:29:2', 'quran', 'quran', '29:2', 2, 1835, 'Al-''Ankabut', 'العنكبوت', 'أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ', NULL, NULL, 'احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون', 'احسب نس ان يترك ان يقول ام وهم ل يفتن', 'quran', NULL, NULL, 'https://quran.com/29/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1836, 'احس حسب الن لنس ان يتر ترك ركو ان يقو قول ولو امن وهم ل يفت فتن تنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1837, 'quran:29:3', 'quran', 'quran', '29:3', 3, 1836, 'Al-''Ankabut', 'العنكبوت', 'وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ', NULL, NULL, 'ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكذبين', 'لقد تن ذين من قبل ليعلمن له ذين صدق ليعلمن كذب', 'quran', NULL, NULL, 'https://quran.com/29/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1837, 'ولق لقد فتن الذ لذي ذين من قبل بله لهم فلي ليع يعل علم لمن الل لله الذ لذي ذين صدق دقو ولي ليع يعل علم لمن الك لكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1838, 'quran:29:4', 'quran', 'quran', '29:4', 4, 1837, 'Al-''Ankabut', 'العنكبوت', 'أَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ سَآءَ مَا يَحۡكُمُونَ', NULL, NULL, 'ام حسب الذين يعملون السيات ان يسبقونا ساء ما يحكمون', 'ام حسب ذين يعمل سي ان يسبقو سء م يحكم', 'quran', NULL, NULL, 'https://quran.com/29/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1838, 'ام حسب الذ لذي ذين يعم عمل ملو لون الس لسي سيت ان يسب سبق بقو قون سء م يحك حكم كمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1839, 'quran:29:5', 'quran', 'quran', '29:5', 5, 1838, 'Al-''Ankabut', 'العنكبوت', 'مَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'من كان يرجوا لقاء الله فان اجل الله لات وهو السميع العليم', 'من كن يرج لقء له فن اجل له لت وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/29/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1839, 'من كن يرج رجو لقء الل لله فن اجل الل لله لت وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1840, 'quran:29:6', 'quran', 'quran', '29:6', 6, 1839, 'Al-''Ankabut', 'العنكبوت', 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفۡسِهِۦٓۚ إِنَّ ٱللَّهَ لَغَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ', NULL, NULL, 'ومن جهد فانما يجهد لنفسه ان الله لغني عن العلمين', 'ومن جهد انم يجهد لنفس ان له لغن عن علم', 'quran', NULL, NULL, 'https://quran.com/29/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1840, 'ومن جهد فنم يجه جهد لنف نفس فسه ان الل لله لغن غني عن الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1841, 'quran:29:7', 'quran', 'quran', '29:7', 7, 1840, 'Al-''Ankabut', 'العنكبوت', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'والذين امنوا وعملوا الصلحت لنكفرن عنهم سياتهم ولنجزينهم احسن الذي كانوا يعملون', 'ذين امن عمل صلحت لنكفرن عن سيت لنجزين احسن ذي كن يعمل', 'quran', NULL, NULL, 'https://quran.com/29/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1841, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لنك نكف كفر فرن عنه نهم سيت يته تهم ولن لنج نجز جزي زين ينه نهم احس حسن الذ لذي كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1842, 'quran:29:8', 'quran', 'quran', '29:8', 8, 1841, 'Al-''Ankabut', 'العنكبوت', 'وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حُسۡنٗاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'ووصينا الانسن بولديه حسنا وان جهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبيكم بما كنتم تعملون', 'وصي انسن بولد حس ون جهدك لتشرك بي م ليس لك به علم فل تطعهم ال مرجع انبي بم كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/29/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1842, 'ووص وصي صين الن لنس نسن بول ولد لدي ديه حسن ون جهد هدك لتش تشر شرك بي م ليس لك به علم فل تطع طعه عهم الي مرج رجع جعك عكم فنب نبي بيك يكم بم كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1843, 'quran:29:9', 'quran', 'quran', '29:9', 9, 1842, 'Al-''Ankabut', 'العنكبوت', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّٰلِحِينَ', NULL, NULL, 'والذين امنوا وعملوا الصلحت لندخلنهم في الصلحين', 'ذين امن عمل صلحت لندخلن في صلح', 'quran', NULL, NULL, 'https://quran.com/29/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1843, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لند ندخ دخل خلن لنه نهم في الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1844, 'quran:29:10', 'quran', 'quran', '29:10', 10, 1843, 'Al-''Ankabut', 'العنكبوت', 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَئِن جَآءَ نَصۡرٞ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِي صُدُورِ ٱلۡعَٰلَمِينَ', NULL, NULL, 'ومن الناس من يقول امنا بالله فاذا اوذي في الله جعل فتنه الناس كعذاب الله ولين جاء نصر من ربك ليقولن انا كنا معكم اوليس الله باعلم بما في صدور العلمين', 'ومن نس من يقول ام له اذ اوذ في له جعل تن نس كعذب له لين جء نصر من ربك ليقولن ان كن مع اوليس له بعلم بم في صدور علم', 'quran', NULL, NULL, 'https://quran.com/29/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1844, 'ومن الن لنس من يقو قول امن بلل لله فذ اوذ وذي في الل لله جعل فتن تنه الن لنس كعذ عذب الل لله ولي لين جء نصر من ربك ليق يقو قول ولن ان كن معك عكم اول ولي ليس الل لله بعل علم بم في صدو دور الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1845, 'quran:29:11', 'quran', 'quran', '29:11', 11, 1844, 'Al-''Ankabut', 'العنكبوت', 'وَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَلَيَعۡلَمَنَّ ٱلۡمُنَٰفِقِينَ', NULL, NULL, 'وليعلمن الله الذين امنوا وليعلمن المنفقين', 'ليعلمن له ذين امن ليعلمن منفق', 'quran', NULL, NULL, 'https://quran.com/29/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1845, 'ولي ليع يعل علم لمن الل لله الذ لذي ذين امن منو ولي ليع يعل علم لمن الم لمن منف نفق فقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1846, 'quran:29:12', 'quran', 'quran', '29:12', 12, 1845, 'Al-''Ankabut', 'العنكبوت', 'وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ ٱتَّبِعُواْ سَبِيلَنَا وَلۡنَحۡمِلۡ خَطَٰيَٰكُمۡ وَمَا هُم بِحَٰمِلِينَ مِنۡ خَطَٰيَٰهُم مِّن شَيۡءٍۖ إِنَّهُمۡ لَكَٰذِبُونَ', NULL, NULL, 'وقال الذين كفروا للذين امنوا اتبعوا سبيلنا ولنحمل خطيكم وما هم بحملين من خطيهم من شيء انهم لكذبون', 'قل ذين كفر ذين امن اتبع سبيل لنحمل خطي وم هم بحمل من خطي من شيء ان لكذب', 'quran', NULL, NULL, 'https://quran.com/29/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1846, 'وقل الذ لذي ذين كفر فرو للذ لذي ذين امن منو اتب تبع بعو سبي بيل يلن ولن لنح نحم حمل خطي طيك يكم وم هم بحم حمل ملي لين من خطي طيه يهم من شيء انه نهم لكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1847, 'quran:29:13', 'quran', 'quran', '29:13', 13, 1846, 'Al-''Ankabut', 'العنكبوت', 'وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ', NULL, NULL, 'وليحملن اثقالهم واثقالا مع اثقالهم وليسلن يوم القيمه عما كانوا يفترون', 'ليحملن اثقل اثقل مع اثقل ليسلن يوم قيم عم كن يفتر', 'quran', NULL, NULL, 'https://quran.com/29/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1847, 'ولي ليح يحم حمل ملن اثق ثقل قله لهم وثق ثقل مع اثق ثقل قله لهم ولي ليس يسل سلن يوم الق لقي قيم يمه عم كنو يفت فتر ترو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1848, 'quran:29:14', 'quran', 'quran', '29:14', 14, 1847, 'Al-''Ankabut', 'العنكبوت', 'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ', NULL, NULL, 'ولقد ارسلنا نوحا الي قومه فلبث فيهم الف سنه الا خمسين عاما فاخذهم الطوفان وهم ظلمون', 'لقد ارسل نوح ال قوم لبث يهم الف سن ال خمس عم اخذ طوف وهم ظلم', 'quran', NULL, NULL, 'https://quran.com/29/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1848, 'ولق لقد ارس رسل سلن نوح الي قوم ومه فلب لبث فيه يهم الف سنه ال خمس مسي سين عم فخذ خذه ذهم الط لطو طوف وفن وهم ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1849, 'quran:29:15', 'quran', 'quran', '29:15', 15, 1848, 'Al-''Ankabut', 'العنكبوت', 'فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ', NULL, NULL, 'فانجينه واصحب السفينه وجعلنها ايه للعلمين', 'انجين اصحب سفين جعلن اي علم', 'quran', NULL, NULL, 'https://quran.com/29/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1849, 'فنج نجي جين ينه وصح صحب الس لسف سفي فين ينه وجع جعل علن لنه ايه للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1850, 'quran:29:16', 'quran', 'quran', '29:16', 16, 1849, 'Al-''Ankabut', 'العنكبوت', 'وَإِبۡرَٰهِيمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُۖ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', NULL, NULL, 'وابرهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون', 'ابرهيم اذ قل لقوم اعبد له اتقو ذل خير لكم ان كنتم تعلم', 'quran', NULL, NULL, 'https://quran.com/29/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1850, 'وبر بره رهي هيم اذ قل لقو قوم ومه اعب عبد بدو الل لله وتق تقو قوه ذلك لكم خير لكم ان كنت نتم تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1851, 'quran:29:17', 'quran', 'quran', '29:17', 17, 1850, 'Al-''Ankabut', 'العنكبوت', 'إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡقٗا فَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ', NULL, NULL, 'انما تعبدون من دون الله اوثنا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون', 'انم تعبد من دون له اوث تخلق افك ان ذين تعبد من دون له ل يملك لكم رزق ابتغ عند له رزق اعبدو اشكر له يه ترجع', 'quran', NULL, NULL, 'https://quran.com/29/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1851, 'انم تعب عبد بدو دون من دون الل لله اوث وثن وتخ تخل خلق لقو قون افك ان الذ لذي ذين تعب عبد بدو دون من دون الل لله ل يمل ملك لكو كون لكم رزق فبت بتغ تغو عند الل لله الر لرز رزق وعب عبد بدو دوه وشك شكر كرو له الي ليه ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1852, 'quran:29:18', 'quran', 'quran', '29:18', 18, 1851, 'Al-''Ankabut', 'العنكبوت', 'وَإِن تُكَذِّبُواْ فَقَدۡ كَذَّبَ أُمَمٞ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ', NULL, NULL, 'وان تكذبوا فقد كذب امم من قبلكم وما علي الرسول الا البلغ المبين', 'ون تكذب فقد كذب امم من قبل وم عل رسول ال بلغ مب', 'quran', NULL, NULL, 'https://quran.com/29/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1852, 'ون تكذ كذب ذبو فقد كذب امم من قبل بلك لكم وم علي الر لرس رسو سول ال الب لبل بلغ الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1853, 'quran:29:19', 'quran', 'quran', '29:19', 19, 1852, 'Al-''Ankabut', 'العنكبوت', 'أَوَلَمۡ يَرَوۡاْ كَيۡفَ يُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥٓۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ', NULL, NULL, 'اولم يروا كيف يبدي الله الخلق ثم يعيده ان ذلك علي الله يسير', 'اولم ير كيف يبد له خلق ثم يعيد ان ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/29/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1853, 'اول ولم يرو كيف يبد بدي الل لله الخ لخل خلق ثم يعي عيد يده ان ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1854, 'quran:29:20', 'quran', 'quran', '29:20', 20, 1853, 'Al-''Ankabut', 'العنكبوت', 'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشي النشاه الاخره ان الله علي كل شيء قدير', 'قل سير في ارض انظر كيف بد خلق ثم له ينش نش اخر ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/29/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1854, 'قل سير يرو في الر لرض فنظ نظر ظرو كيف بد الخ لخل خلق ثم الل لله ينش نشي الن لنش نشه الخ لخر خره ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1855, 'quran:29:21', 'quran', 'quran', '29:21', 21, 1854, 'Al-''Ankabut', 'العنكبوت', 'يُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ', NULL, NULL, 'يعذب من يشاء ويرحم من يشاء واليه تقلبون', 'يعذب من يشء يرحم من يشء يه تقلب', 'quran', NULL, NULL, 'https://quran.com/29/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1855, 'يعذ عذب من يشء وير يرح رحم من يشء ولي ليه تقل قلب لبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1856, 'quran:29:22', 'quran', 'quran', '29:22', 22, 1855, 'Al-''Ankabut', 'العنكبوت', 'وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ', NULL, NULL, 'وما انتم بمعجزين في الارض ولا في السماء وما لكم من دون الله من ولي ولا نصير', 'وم انتم بمعجز في ارض ول في سمء وم لكم من دون له من ول ول نصير', 'quran', NULL, NULL, 'https://quran.com/29/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1856, 'وم انت نتم بمع معج عجز جزي زين في الر لرض ول في الس لسم سمء وم لكم من دون الل لله من ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1857, 'quran:29:23', 'quran', 'quran', '29:23', 23, 1856, 'Al-''Ankabut', 'العنكبوت', 'وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'والذين كفروا بايت الله ولقايه اوليك ييسوا من رحمتي واوليك لهم عذاب اليم', 'ذين كفر بيت له لق اوليك ييس من رحمت اوليك لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/29/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1857, 'ولذ لذي ذين كفر فرو بيت الل لله ولق لقي قيه اول ولي ليك ييس يسو من رحم حمت متي وول ولي ليك لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1858, 'quran:29:24', 'quran', 'quran', '29:24', 24, 1857, 'Al-''Ankabut', 'العنكبوت', 'فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ', NULL, NULL, 'فما كان جواب قومه الا ان قالوا اقتلوه او حرقوه فانجاه الله من النار ان في ذلك لايت لقوم يومنون', 'فم كن جوب قوم ال ان قل اقتلو او حرقو انج له من نر ان في ذلك ليت لقوم يومن', 'quran', NULL, NULL, 'https://quran.com/29/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1858, 'فم كن جوب قوم ومه ال ان قلو اقت قتل تلو لوه او حرق رقو قوه فنج نجه الل لله من الن لنر ان في ذلك ليت لقو قوم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1859, 'quran:29:25', 'quran', 'quran', '29:25', 25, 1858, 'Al-''Ankabut', 'العنكبوت', 'وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', NULL, NULL, 'وقال انما اتخذتم من دون الله اوثنا موده بينكم في الحياه الدنيا ثم يوم القيمه يكفر بعضكم ببعض ويلعن بعضكم بعضا وماواكم النار وما لكم من نصرين', 'قل انم اتخذتم من دون له اوث مود بين في حي دني ثم يوم قيم يكفر بعض ببعض يلعن بعض بعض مو نر وم لكم من نصر', 'quran', NULL, NULL, 'https://quran.com/29/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1859, 'وقل انم اتخ تخذ خذت ذتم من دون الل لله اوث وثن مود وده بين ينك نكم في الح لحي حيه الد لدن دني ثم يوم الق لقي قيم يمه يكف كفر بعض عضك ضكم ببع بعض ويل يلع لعن بعض عضك ضكم بعض ومو موك وكم الن لنر وم لكم من نصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1860, 'quran:29:26', 'quran', 'quran', '29:26', 26, 1859, 'Al-''Ankabut', 'العنكبوت', 'فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'فامن له لوط وقال اني مهاجر الي ربي انه هو العزيز الحكيم', 'امن له لوط قل ان مهجر ال رب ان هو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/29/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1860, 'فمن له لوط وقل اني مهج هجر الي ربي انه هو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1861, 'quran:29:27', 'quran', 'quran', '29:27', 27, 1860, 'Al-''Ankabut', 'العنكبوت', 'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'ووهبنا له اسحق ويعقوب وجعلنا في ذريته النبوه والكتب واتينه اجره في الدنيا وانه في الاخره لمن الصلحين', 'وهب له اسحق يعقوب جعل في ذريت نبو كتب اتين اجر في دني ان في اخر لمن صلح', 'quran', NULL, NULL, 'https://quran.com/29/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1861, 'ووه وهب هبن له اسح سحق ويع يعق عقو قوب وجع جعل علن في ذري ريت يته الن لنب نبو بوه ولك لكت كتب وتي تين ينه اجر جره في الد لدن دني ونه في الخ لخر خره لمن الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1862, 'quran:29:28', 'quran', 'quran', '29:28', 28, 1861, 'Al-''Ankabut', 'العنكبوت', 'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ', NULL, NULL, 'ولوطا اذ قال لقومه انكم لتاتون الفحشه ما سبقكم بها من احد من العلمين', 'لوط اذ قل لقوم ان لتت فحش م سبق به من احد من علم', 'quran', NULL, NULL, 'https://quran.com/29/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1862, 'ولو لوط اذ قل لقو قوم ومه انك نكم لتت تتو تون الف لفح فحش حشه م سبق بقك قكم به من احد من الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1863, 'quran:29:29', 'quran', 'quran', '29:29', 29, 1862, 'Al-''Ankabut', 'العنكبوت', 'أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِيلَ وَتَأۡتُونَ فِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', NULL, NULL, 'اينكم لتاتون الرجال وتقطعون السبيل وتاتون في ناديكم المنكر فما كان جواب قومه الا ان قالوا ايتنا بعذاب الله ان كنت من الصدقين', 'اين لتت رجل تقطع سبيل تت في ندي منكر فم كن جوب قوم ال ان قل ايت بعذب له ان كنت من صدق', 'quran', NULL, NULL, 'https://quran.com/29/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1863, 'اين ينك نكم لتت تتو تون الر لرج رجل وتق تقط قطع طعو عون الس لسب سبي بيل وتت تتو تون في ندي ديك يكم الم لمن منك نكر فم كن جوب قوم ومه ال ان قلو ايت يتن بعذ عذب الل لله ان كنت من الص لصد صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1864, 'quran:29:30', 'quran', 'quran', '29:30', 30, 1863, 'Al-''Ankabut', 'العنكبوت', 'قَالَ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ', NULL, NULL, 'قال رب انصرني علي القوم المفسدين', 'قل رب انصرن عل قوم مفسد', 'quran', NULL, NULL, 'https://quran.com/29/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1864, 'قل رب انص نصر صرن رني علي الق لقو قوم الم لمف مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1865, 'quran:29:31', 'quran', 'quran', '29:31', 31, 1864, 'Al-''Ankabut', 'العنكبوت', 'وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ', NULL, NULL, 'ولما جاءت رسلنا ابرهيم بالبشري قالوا انا مهلكوا اهل هذه القريه ان اهلها كانوا ظلمين', 'لم جءت رسل ابرهيم بشر قل ان مهلك اهل هذ قر ان اهل كن ظلم', 'quran', NULL, NULL, 'https://quran.com/29/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1865, 'ولم جءت رسل سلن ابر بره رهي هيم بلب لبش بشر شري قلو ان مهل هلك لكو اهل هذه الق لقر قري ريه ان اهل هله كنو ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1866, 'quran:29:32', 'quran', 'quran', '29:32', 32, 1865, 'Al-''Ankabut', 'العنكبوت', 'قَالَ إِنَّ فِيهَا لُوطٗاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ', NULL, NULL, 'قال ان فيها لوطا قالوا نحن اعلم بمن فيها لننجينه واهله الا امراته كانت من الغبرين', 'قل ان يه لوط قل نحن اعلم بمن يه لننجين اهل ال امرت كنت من غبر', 'quran', NULL, NULL, 'https://quran.com/29/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1866, 'قل ان فيه لوط قلو نحن اعل علم بمن فيه لنن ننج نجي جين ينه وهل هله ال امر مرت رته كنت من الغ لغب غبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1867, 'quran:29:33', 'quran', 'quran', '29:33', 33, 1866, 'Al-''Ankabut', 'العنكبوت', 'وَلَمَّآ أَن جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗاۖ وَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ', NULL, NULL, 'ولما ان جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن انا منجوك واهلك الا امراتك كانت من الغبرين', 'لم ان جءت رسل لوط سيء بهم ضق بهم ذرع قل ل تخف ول تحزن ان منجوك اهلك ال امرتك كنت من غبر', 'quran', NULL, NULL, 'https://quran.com/29/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1867, 'ولم ان جءت رسل سلن لوط سيء بهم وضق بهم ذرع وقل قلو ل تخف ول تحز حزن ان منج نجو جوك وهل هلك ال امر مرت رتك كنت من الغ لغب غبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1868, 'quran:29:34', 'quran', 'quran', '29:34', 34, 1867, 'Al-''Ankabut', 'العنكبوت', 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ', NULL, NULL, 'انا منزلون علي اهل هذه القريه رجزا من السماء بما كانوا يفسقون', 'ان منزل عل اهل هذ قر رجز من سمء بم كن يفسق', 'quran', NULL, NULL, 'https://quran.com/29/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1868, 'ان منز نزل زلو لون علي اهل هذه الق لقر قري ريه رجز من الس لسم سمء بم كنو يفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1869, 'quran:29:35', 'quran', 'quran', '29:35', 35, 1868, 'Al-''Ankabut', 'العنكبوت', 'وَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ', NULL, NULL, 'ولقد تركنا منها ايه بينه لقوم يعقلون', 'لقد ترك من اي بين لقوم يعقل', 'quran', NULL, NULL, 'https://quran.com/29/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1869, 'ولق لقد ترك ركن منه ايه بين ينه لقو قوم يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1870, 'quran:29:36', 'quran', 'quran', '29:36', 36, 1869, 'Al-''Ankabut', 'العنكبوت', 'وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', NULL, NULL, 'والي مدين اخاهم شعيبا فقال يا قوم اعبدوا الله وارجوا اليوم الاخر ولا تعثوا في الارض مفسدين', 'ول مد اخ شعيب قل ي قوم اعبد له ارج يوم اخر ول تعث في ارض مفسد', 'quran', NULL, NULL, 'https://quran.com/29/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1870, 'ولي مدي دين اخه خهم شعي عيب فقل ي قوم اعب عبد بدو الل لله ورج رجو الي ليو يوم الخ لخر ول تعث عثو في الر لرض مفس فسد سدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1871, 'quran:29:37', 'quran', 'quran', '29:37', 37, 1870, 'Al-''Ankabut', 'العنكبوت', 'فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ', NULL, NULL, 'فكذبوه فاخذتهم الرجفه فاصبحوا في دارهم جثمين', 'كذبو اخذت رجف اصبح في در جثم', 'quran', NULL, NULL, 'https://quran.com/29/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1871, 'فكذ كذب ذبو بوه فخذ خذت ذته تهم الر لرج رجف جفه فصب صبح بحو في دره رهم جثم ثمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1872, 'quran:29:38', 'quran', 'quran', '29:38', 38, 1871, 'Al-''Ankabut', 'العنكبوت', 'وَعَادٗا وَثَمُودَاْ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ', NULL, NULL, 'وعادا وثمودا وقد تبين لكم من مسكنهم وزين لهم الشيطن اعملهم فصدهم عن السبيل وكانوا مستبصرين', 'عد ثمود وقد تب لكم من مسكن زين لهم شيطن اعمل صد عن سبيل كن مستبصر', 'quran', NULL, NULL, 'https://quran.com/29/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1872, 'وعد وثم ثمو مود وقد تبي بين لكم من مسك سكن كنه نهم وزي زين لهم الش لشي شيط يطن اعم عمل مله لهم فصد صده دهم عن الس لسب سبي بيل وكن كنو مست ستب تبص بصر صري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1873, 'quran:29:39', 'quran', 'quran', '29:39', 39, 1872, 'Al-''Ankabut', 'العنكبوت', 'وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ', NULL, NULL, 'وقرون وفرعون وهمن ولقد جاءهم موسي بالبينت فاستكبروا في الارض وما كانوا سبقين', 'قر فرع همن لقد جء موس بينت استكبر في ارض وم كن سبق', 'quran', NULL, NULL, 'https://quran.com/29/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1873, 'وقر قرو رون وفر فرع رعو عون وهم همن ولق لقد جءه ءهم موس وسي بلب لبي بين ينت فست ستك تكب كبر برو في الر لرض وم كنو سبق بقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1874, 'quran:29:40', 'quran', 'quran', '29:40', 40, 1873, 'Al-''Ankabut', 'العنكبوت', 'فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبٗا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', NULL, NULL, 'فكلا اخذنا بذنبه فمنهم من ارسلنا عليه حاصبا ومنهم من اخذته الصيحه ومنهم من خسفنا به الارض ومنهم من اغرقنا وما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون', 'كل اخذ بذنب من من ارسل عل حصب من من اخذت صيح من من خسف به ارض من من اغرق وم كن له ليظلم لكن كن انفس يظلم', 'quran', NULL, NULL, 'https://quran.com/29/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1874, 'فكل اخذ خذن بذن ذنب نبه فمن منه نهم من ارس رسل سلن علي ليه حصب ومن منه نهم من اخذ خذت ذته الص لصي صيح يحه ومن منه نهم من خسف سفن به الر لرض ومن منه نهم من اغر غرق رقن وم كن الل لله ليظ يظل ظلم لمه مهم ولك لكن كنو انف نفس فسه سهم يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1875, 'quran:29:41', 'quran', 'quran', '29:41', 41, 1874, 'Al-''Ankabut', 'العنكبوت', 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'مثل الذين اتخذوا من دون الله اولياء كمثل العنكبوت اتخذت بيتا وان اوهن البيوت لبيت العنكبوت لو كانوا يعلمون', 'مثل ذين اتخذ من دون له اوليء كمثل عنكبوت اتخذت بيت ون او بيوت لبيت عنكبوت لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/29/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1875, 'مثل الذ لذي ذين اتخ تخذ خذو من دون الل لله اول ولي ليء كمث مثل الع لعن عنك نكب كبو بوت اتخ تخذ خذت بيت ون اوه وهن الب لبي بيو يوت لبي بيت الع لعن عنك نكب كبو بوت لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1876, 'quran:29:42', 'quran', 'quran', '29:42', 42, 1875, 'Al-''Ankabut', 'العنكبوت', 'إِنَّ ٱللَّهَ يَعۡلَمُ مَا يَدۡعُونَ مِن دُونِهِۦ مِن شَيۡءٖۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'ان الله يعلم ما يدعون من دونه من شيء وهو العزيز الحكيم', 'ان له يعلم م يدع من دون من شيء وهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/29/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1876, 'ان الل لله يعل علم م يدع دعو عون من دون ونه من شيء وهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1877, 'quran:29:43', 'quran', 'quran', '29:43', 43, 1876, 'Al-''Ankabut', 'العنكبوت', 'وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ', NULL, NULL, 'وتلك الامثل نضربها للناس وما يعقلها الا العلمون', 'تلك امثل نضرب نس وم يعقل ال علم', 'quran', NULL, NULL, 'https://quran.com/29/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1877, 'وتل تلك الم لمث مثل نضر ضرب ربه للن لنس وم يعق عقل قله ال الع لعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1878, 'quran:29:44', 'quran', 'quran', '29:44', 44, 1877, 'Al-''Ankabut', 'العنكبوت', 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ', NULL, NULL, 'خلق الله السموت والارض بالحق ان في ذلك لايه للمومنين', 'خلق له سموت ارض حق ان في ذلك ل مومن', 'quran', NULL, NULL, 'https://quran.com/29/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1878, 'خلق الل لله الس لسم سمو موت ولر لرض بلح لحق ان في ذلك ليه للم لمو موم ومن مني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1879, 'quran:29:45', 'quran', 'quran', '29:45', 45, 1878, 'Al-''Ankabut', 'العنكبوت', 'ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ', NULL, NULL, 'اتل ما اوحي اليك من الكتب واقم الصلاه ان الصلاه تنهي عن الفحشاء والمنكر ولذكر الله اكبر والله يعلم ما تصنعون', 'اتل م اوح يك من كتب اقم صل ان صل تنه عن فحشء منكر لذكر له اكبر له يعلم م تصنع', 'quran', NULL, NULL, 'https://quran.com/29/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1879, 'اتل م اوح وحي الي ليك من الك لكت كتب وقم الص لصل صله ان الص لصل صله تنه نهي عن الف لفح فحش حشء ولم لمن منك نكر ولذ لذك ذكر الل لله اكب كبر ولل لله يعل علم م تصن صنع نعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1880, 'quran:29:46', 'quran', 'quran', '29:46', 46, 1879, 'Al-''Ankabut', 'العنكبوت', 'وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', NULL, NULL, 'ولا تجدلوا اهل الكتب الا بالتي هي احسن الا الذين ظلموا منهم وقولوا امنا بالذي انزل الينا وانزل اليكم والهنا والهكم وحد ونحن له مسلمون', 'ول تجدل اهل كتب ال تي هي احسن ال ذين ظلم من قول ام ذي انزل ين انزل يكم هن هكم وحد نحن له مسلم', 'quran', NULL, NULL, 'https://quran.com/29/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1880, 'ول تجد جدل دلو اهل الك لكت كتب ال بلت لتي هي احس حسن ال الذ لذي ذين ظلم لمو منه نهم وقو قول ولو امن بلذ لذي انز نزل الي لين ونز نزل الي ليك يكم وله لهن وله لهك هكم وحد ونح نحن له مسل سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1881, 'quran:29:47', 'quran', 'quran', '29:47', 47, 1880, 'Al-''Ankabut', 'العنكبوت', 'وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ', NULL, NULL, 'وكذلك انزلنا اليك الكتب فالذين اتينهم الكتب يومنون به ومن هولاء من يومن به وما يجحد بايتنا الا الكفرون', 'كذلك انزل يك كتب ذين اتين كتب يومن به ومن هولء من يومن به وم يجحد بيت ال كفر', 'quran', NULL, NULL, 'https://quran.com/29/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1881, 'وكذ كذل ذلك انز نزل زلن الي ليك الك لكت كتب فلذ لذي ذين اتي تين ينه نهم الك لكت كتب يوم ومن منو نون به ومن هول ولء من يوم ومن به وم يجح جحد بيت يتن ال الك لكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1882, 'quran:29:48', 'quran', 'quran', '29:48', 48, 1881, 'Al-''Ankabut', 'العنكبوت', 'وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٖ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذٗا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ', NULL, NULL, 'وما كنت تتلوا من قبله من كتب ولا تخطه بيمينك اذا لارتاب المبطلون', 'وم كنت تتل من قبل من كتب ول تخط بيمينك اذ لرتب مبطل', 'quran', NULL, NULL, 'https://quran.com/29/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1882, 'وم كنت تتل تلو من قبل بله من كتب ول تخط خطه بيم يمي مين ينك اذ لرت رتب الم لمب مبط بطل طلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1883, 'quran:29:49', 'quran', 'quran', '29:49', 49, 1882, 'Al-''Ankabut', 'العنكبوت', 'بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', NULL, NULL, 'بل هو ايت بينت في صدور الذين اوتوا العلم وما يجحد بايتنا الا الظلمون', 'بل هو ايت بينت في صدور ذين اوت علم وم يجحد بيت ال ظلم', 'quran', NULL, NULL, 'https://quran.com/29/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1883, 'بل هو ايت بين ينت في صدو دور الذ لذي ذين اوت وتو الع لعل علم وم يجح جحد بيت يتن ال الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1884, 'quran:29:50', 'quran', 'quran', '29:50', 50, 1883, 'Al-''Ankabut', 'العنكبوت', 'وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ', NULL, NULL, 'وقالوا لولا انزل عليه ايت من ربه قل انما الايت عند الله وانما انا نذير مبين', 'قل لول انزل عل ايت من رب قل انم ايت عند له انم ان نذير مب', 'quran', NULL, NULL, 'https://quran.com/29/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1884, 'وقل قلو لول انز نزل علي ليه ايت من ربه قل انم الي ليت عند الل لله ونم ان نذي ذير مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1885, 'quran:29:51', 'quran', 'quran', '29:51', 51, 1884, 'Al-''Ankabut', 'العنكبوت', 'أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ', NULL, NULL, 'اولم يكفهم انا انزلنا عليك الكتب يتلي عليهم ان في ذلك لرحمه وذكري لقوم يومنون', 'اولم يكف ان انزل عليك كتب يتل علي ان في ذلك لرحم ذكر لقوم يومن', 'quran', NULL, NULL, 'https://quran.com/29/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1885, 'اول ولم يكف كفه فهم ان انز نزل زلن علي ليك الك لكت كتب يتل تلي علي ليه يهم ان في ذلك لرح رحم حمه وذك ذكر كري لقو قوم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1886, 'quran:29:52', 'quran', 'quran', '29:52', 52, 1885, 'Al-''Ankabut', 'العنكبوت', 'قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ بِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', NULL, NULL, 'قل كفي بالله بيني وبينكم شهيدا يعلم ما في السموت والارض والذين امنوا بالبطل وكفروا بالله اوليك هم الخسرون', 'قل كف له بين بين شهيد يعلم م في سموت ارض ذين امن بطل كفر له اوليك هم خسر', 'quran', NULL, NULL, 'https://quran.com/29/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1886, 'قل كفي بلل لله بين يني وبي بين ينك نكم شهي هيد يعل علم م في الس لسم سمو موت ولر لرض ولذ لذي ذين امن منو بلب لبط بطل وكف كفر فرو بلل لله اول ولي ليك هم الخ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1887, 'quran:29:53', 'quran', 'quran', '29:53', 53, 1886, 'Al-''Ankabut', 'العنكبوت', 'وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَآ أَجَلٞ مُّسَمّٗى لَّجَآءَهُمُ ٱلۡعَذَابُۚ وَلَيَأۡتِيَنَّهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ', NULL, NULL, 'ويستعجلونك بالعذاب ولولا اجل مسمي لجاءهم العذاب ولياتينهم بغته وهم لا يشعرون', 'يستعجلونك عذب لول اجل مسم لجء عذب ليتين بغت وهم ل يشعر', 'quran', NULL, NULL, 'https://quran.com/29/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1887, 'ويس يست ستع تعج عجل جلو لون ونك بلع لعذ عذب ولو لول اجل مسم سمي لجء جءه ءهم الع لعذ عذب ولي ليت يتي تين ينه نهم بغت غته وهم ل يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1888, 'quran:29:54', 'quran', 'quran', '29:54', 54, 1887, 'Al-''Ankabut', 'العنكبوت', 'يَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ', NULL, NULL, 'يستعجلونك بالعذاب وان جهنم لمحيطه بالكفرين', 'يستعجلونك عذب ون جهنم لمحيط كفر', 'quran', NULL, NULL, 'https://quran.com/29/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1888, 'يست ستع تعج عجل جلو لون ونك بلع لعذ عذب ون جهن هنم لمح محي حيط يطه بلك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1889, 'quran:29:55', 'quran', 'quran', '29:55', 55, 1888, 'Al-''Ankabut', 'العنكبوت', 'يَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'يوم يغشاهم العذاب من فوقهم ومن تحت ارجلهم ويقول ذوقوا ما كنتم تعملون', 'يوم يغش عذب من وق ومن تحت ارجل يقول ذوق م كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/29/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1889, 'يوم يغش غشه شهم الع لعذ عذب من فوق وقه قهم ومن تحت ارج رجل جله لهم ويق يقو قول ذوق وقو م كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1890, 'quran:29:56', 'quran', 'quran', '29:56', 56, 1889, 'Al-''Ankabut', 'العنكبوت', 'يَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ', NULL, NULL, 'يا عبادي الذين امنوا ان ارضي وسعه فايي فاعبدون', 'ي عبد ذين امن ان ارض سع اي اعبد', 'quran', NULL, NULL, 'https://quran.com/29/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1890, 'ي عبد بدي الذ لذي ذين امن منو ان ارض رضي وسع سعه فيي فعب عبد بدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1891, 'quran:29:57', 'quran', 'quran', '29:57', 57, 1890, 'Al-''Ankabut', 'العنكبوت', 'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ', NULL, NULL, 'كل نفس ذايقه الموت ثم الينا ترجعون', 'كل نفس ذيق موت ثم ين ترجع', 'quran', NULL, NULL, 'https://quran.com/29/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1891, 'كل نفس ذيق يقه الم لمو موت ثم الي لين ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1892, 'quran:29:58', 'quran', 'quran', '29:58', 58, 1891, 'Al-''Ankabut', 'العنكبوت', 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ', NULL, NULL, 'والذين امنوا وعملوا الصلحت لنبوينهم من الجنه غرفا تجري من تحتها الانهر خلدين فيها نعم اجر العملين', 'ذين امن عمل صلحت لنبوين من جن غرف تجر من تحت انهر خلد يه نعم اجر عمل', 'quran', NULL, NULL, 'https://quran.com/29/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1892, 'ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لنب نبو بوي وين ينه نهم من الج لجن جنه غرف تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه نعم اجر الع لعم عمل ملي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1893, 'quran:29:59', 'quran', 'quran', '29:59', 59, 1892, 'Al-''Ankabut', 'العنكبوت', 'ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ', NULL, NULL, 'الذين صبروا وعلي ربهم يتوكلون', 'ذين صبر عل رب يتوكل', 'quran', NULL, NULL, 'https://quran.com/29/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1893, 'الذ لذي ذين صبر برو وعل علي ربه بهم يتو توك وكل كلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1894, 'quran:29:60', 'quran', 'quran', '29:60', 60, 1893, 'Al-''Ankabut', 'العنكبوت', 'وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', NULL, NULL, 'وكاين من دابه لا تحمل رزقها الله يرزقها واياكم وهو السميع العليم', 'ك من دب ل تحمل رزق له يرزق اي وهو سميع عليم', 'quran', NULL, NULL, 'https://quran.com/29/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1894, 'وكي كين من دبه ل تحم حمل رزق زقه الل لله يرز رزق زقه ويك يكم وهو الس لسم سمي ميع الع لعل علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1895, 'quran:29:61', 'quran', 'quran', '29:61', 61, 1894, 'Al-''Ankabut', 'العنكبوت', 'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ', NULL, NULL, 'ولين سالتهم من خلق السموت والارض وسخر الشمس والقمر ليقولن الله فاني يوفكون', 'لين سلت من خلق سموت ارض سخر شمس قمر ليقولن له ان يوفك', 'quran', NULL, NULL, 'https://quran.com/29/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1895, 'ولي لين سلت لته تهم من خلق الس لسم سمو موت ولر لرض وسخ سخر الش لشم شمس ولق لقم قمر ليق يقو قول ولن الل لله فني يوف وفك فكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1896, 'quran:29:62', 'quran', 'quran', '29:62', 62, 1895, 'Al-''Ankabut', 'العنكبوت', 'ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥٓۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'الله يبسط الرزق لمن يشاء من عباده ويقدر له ان الله بكل شيء عليم', 'له يبسط رزق لمن يشء من عبد يقدر له ان له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/29/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1896, 'الل لله يبس بسط الر لرز رزق لمن يشء من عبد بده ويق يقد قدر له ان الل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1897, 'quran:29:63', 'quran', 'quran', '29:63', 63, 1896, 'Al-''Ankabut', 'العنكبوت', 'وَلَئِن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ', NULL, NULL, 'ولين سالتهم من نزل من السماء ماء فاحيا به الارض من بعد موتها ليقولن الله قل الحمد لله بل اكثرهم لا يعقلون', 'لين سلت من نزل من سمء مء احي به ارض من بعد موت ليقولن له قل حمد لل بل اكثر ل يعقل', 'quran', NULL, NULL, 'https://quran.com/29/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1897, 'ولي لين سلت لته تهم من نزل من الس لسم سمء مء فحي به الر لرض من بعد موت وته ليق يقو قول ولن الل لله قل الح لحم حمد لله بل اكث كثر ثره رهم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1898, 'quran:29:64', 'quran', 'quran', '29:64', 64, 1897, 'Al-''Ankabut', 'العنكبوت', 'وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'وما هذه الحياه الدنيا الا لهو ولعب وان الدار الاخره لهي الحيوان لو كانوا يعلمون', 'وم هذ حي دني ال لهو لعب ون در اخر له حيو لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/29/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1898, 'وم هذه الح لحي حيه الد لدن دني ال لهو ولع لعب ون الد لدر الخ لخر خره لهي الح لحي حيو يون لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1899, 'quran:29:65', 'quran', 'quran', '29:65', 65, 1898, 'Al-''Ankabut', 'العنكبوت', 'فَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ', NULL, NULL, 'فاذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجاهم الي البر اذا هم يشركون', 'اذ ركب في فلك دع له مخلص له دين لم نج ال بر اذ هم يشرك', 'quran', NULL, NULL, 'https://quran.com/29/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1899, 'فذ ركب كبو في الف لفل فلك دعو الل لله مخل خلص لصي صين له الد لدي دين فلم نجه جهم الي الب لبر اذ هم يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1900, 'quran:29:66', 'quran', 'quran', '29:66', 66, 1899, 'Al-''Ankabut', 'العنكبوت', 'لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ يَعۡلَمُونَ', NULL, NULL, 'ليكفروا بما اتينهم وليتمتعوا فسوف يعلمون', 'ليكفر بم اتين ليتمتع سوف يعلم', 'quran', NULL, NULL, 'https://quran.com/29/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1900, 'ليك يكف كفر فرو بم اتي تين ينه نهم ولي ليت يتم تمت متع تعو فسو سوف يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1901, 'quran:29:67', 'quran', 'quran', '29:67', 67, 1900, 'Al-''Ankabut', 'العنكبوت', 'أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ', NULL, NULL, 'اولم يروا انا جعلنا حرما امنا ويتخطف الناس من حولهم افبالبطل يومنون وبنعمه الله يكفرون', 'اولم ير ان جعل حرم ام يتخطف نس من حول افبلبطل يومن بنعم له يكفر', 'quran', NULL, NULL, 'https://quran.com/29/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1901, 'اول ولم يرو ان جعل علن حرم امن ويت يتخ تخط خطف الن لنس من حول وله لهم افب فبل بلب لبط بطل يوم ومن منو نون وبن بنع نعم عمه الل لله يكف كفر فرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1902, 'quran:29:68', 'quran', 'quran', '29:68', 68, 1901, 'Al-''Ankabut', 'العنكبوت', 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ', NULL, NULL, 'ومن اظلم ممن افتري علي الله كذبا او كذب بالحق لما جاءه اليس في جهنم مثوي للكفرين', 'ومن اظلم ممن افتر عل له كذب او كذب حق لم جء يس في جهنم مثو كفر', 'quran', NULL, NULL, 'https://quran.com/29/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1902, 'ومن اظل ظلم ممن افت فتر تري علي الل لله كذب او كذب بلح لحق لم جءه الي ليس في جهن هنم مثو ثوي للك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1903, 'quran:29:69', 'quran', 'quran', '29:69', 69, 1902, 'Al-''Ankabut', 'العنكبوت', 'وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'والذين جهدوا فينا لنهدينهم سبلنا وان الله لمع المحسنين', 'ذين جهد ين لنهدين سبل ون له لمع محسن', 'quran', NULL, NULL, 'https://quran.com/29/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1903, 'ولذ لذي ذين جهد هدو فين لنه نهد هدي دين ينه نهم سبل بلن ون الل لله لمع الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1904, 'quran:31:1', 'quran', 'quran', '31:1', 1, 1903, 'Luqman', 'لقمان', 'الٓمٓ', NULL, NULL, 'الم', 'الم', 'quran', NULL, NULL, 'https://quran.com/31/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1904, 'الم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1905, 'quran:31:2', 'quran', 'quran', '31:2', 2, 1904, 'Luqman', 'لقمان', 'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ', NULL, NULL, 'تلك ايت الكتب الحكيم', 'تلك ايت كتب حكيم', 'quran', NULL, NULL, 'https://quran.com/31/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1905, 'تلك ايت الك لكت كتب الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1906, 'quran:31:3', 'quran', 'quran', '31:3', 3, 1905, 'Luqman', 'لقمان', 'هُدٗى وَرَحۡمَةٗ لِّلۡمُحۡسِنِينَ', NULL, NULL, 'هدي ورحمه للمحسنين', 'هد رحم محسن', 'quran', NULL, NULL, 'https://quran.com/31/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1906, 'هدي ورح رحم حمه للم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1907, 'quran:31:4', 'quran', 'quran', '31:4', 4, 1906, 'Luqman', 'لقمان', 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ', NULL, NULL, 'الذين يقيمون الصلاه ويوتون الزكاه وهم بالاخره هم يوقنون', 'ذين يقيم صل يوت زك وهم اخر هم يوقن', 'quran', NULL, NULL, 'https://quran.com/31/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1907, 'الذ لذي ذين يقي قيم يمو مون الص لصل صله ويو يوت وتو تون الز لزك زكه وهم بلخ لخر خره هم يوق وقن قنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1908, 'quran:31:5', 'quran', 'quran', '31:5', 5, 1907, 'Luqman', 'لقمان', 'أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'اوليك علي هدي من ربهم واوليك هم المفلحون', 'اوليك عل هد من رب اوليك هم مفلح', 'quran', NULL, NULL, 'https://quran.com/31/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1908, 'اول ولي ليك علي هدي من ربه بهم وول ولي ليك هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1909, 'quran:31:6', 'quran', 'quran', '31:6', 6, 1908, 'Luqman', 'لقمان', 'وَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ', NULL, NULL, 'ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اوليك لهم عذاب مهين', 'ومن نس من يشتر لهو حديث ليضل عن سبيل له بغير علم يتخذ هز اوليك لهم عذب مه', 'quran', NULL, NULL, 'https://quran.com/31/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1909, 'ومن الن لنس من يشت شتر تري لهو الح لحد حدي ديث ليض يضل عن سبي بيل الل لله بغي غير علم ويت يتخ تخذ خذه هزو اول ولي ليك لهم عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1910, 'quran:31:7', 'quran', 'quran', '31:7', 7, 1909, 'Luqman', 'لقمان', 'وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا وَلَّىٰ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَا كَأَنَّ فِيٓ أُذُنَيۡهِ وَقۡرٗاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٍ', NULL, NULL, 'واذا تتلي عليه ايتنا ولي مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم', 'اذ تتل عل ايت ول مستكبر كن لم يسمع كن في اذن قر بشر بعذب يم', 'quran', NULL, NULL, 'https://quran.com/31/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1910, 'وذ تتل تلي علي ليه ايت يتن ولي مست ستك تكب كبر كن لم يسم سمع معه كن في اذن ذني نيه وقر فبش بشر شره بعذ عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1911, 'quran:31:8', 'quran', 'quran', '31:8', 8, 1910, 'Luqman', 'لقمان', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتُ ٱلنَّعِيمِ', NULL, NULL, 'ان الذين امنوا وعملوا الصلحت لهم جنت النعيم', 'ان ذين امن عمل صلحت لهم جنت نعيم', 'quran', NULL, NULL, 'https://quran.com/31/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1911, 'ان الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لهم جنت الن لنع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1912, 'quran:31:9', 'quran', 'quran', '31:9', 9, 1911, 'Luqman', 'لقمان', 'خَٰلِدِينَ فِيهَاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'خلدين فيها وعد الله حقا وهو العزيز الحكيم', 'خلد يه وعد له حق وهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/31/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1912, 'خلد لدي دين فيه وعد الل لله حق وهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1913, 'quran:31:10', 'quran', 'quran', '31:10', 10, 1912, 'Luqman', 'لقمان', 'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ', NULL, NULL, 'خلق السموت بغير عمد ترونها والقي في الارض روسي ان تميد بكم وبث فيها من كل دابه وانزلنا من السماء ماء فانبتنا فيها من كل زوج كريم', 'خلق سموت بغير عمد ترون قي في ارض روس ان تميد بكم وبث يه من كل دب انزل من سمء مء انبت يه من كل زوج كريم', 'quran', NULL, NULL, 'https://quran.com/31/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1913, 'خلق الس لسم سمو موت بغي غير عمد ترو رون ونه ولق لقي في الر لرض روس وسي ان تمي ميد بكم وبث فيه من كل دبه ونز نزل زلن من الس لسم سمء مء فنب نبت بتن فيه من كل زوج كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1914, 'quran:31:11', 'quran', 'quran', '31:11', 11, 1913, 'Luqman', 'لقمان', 'هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّٰلِمُونَ فِي ضَلَٰلٖ مُّبِينٖ', NULL, NULL, 'هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظلمون في ضلل مبين', 'هذ خلق له ارون مذ خلق ذين من دون بل ظلم في ضلل مب', 'quran', NULL, NULL, 'https://quran.com/31/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1914, 'هذ خلق الل لله فرو رون وني مذ خلق الذ لذي ذين من دون ونه بل الظ لظل ظلم لمو مون في ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1915, 'quran:31:12', 'quran', 'quran', '31:12', 12, 1914, 'Luqman', 'لقمان', 'وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ', NULL, NULL, 'ولقد اتينا لقمن الحكمه ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد', 'لقد اتي لقمن حكم ان اشكر لل ومن يشكر انم يشكر لنفس ومن كفر فن له غن حميد', 'quran', NULL, NULL, 'https://quran.com/31/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1915, 'ولق لقد اتي تين لقم قمن الح لحك حكم كمه ان اشك شكر لله ومن يشك شكر فنم يشك شكر لنف نفس فسه ومن كفر فن الل لله غني حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1916, 'quran:31:13', 'quran', 'quran', '31:13', 13, 1915, 'Luqman', 'لقمان', 'وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ', NULL, NULL, 'واذ قال لقمن لابنه وهو يعظه يا بني لا تشرك بالله ان الشرك لظلم عظيم', 'وذ قل لقمن لبن وهو يعظ ي بن ل تشرك له ان شرك لظلم عظيم', 'quran', NULL, NULL, 'https://quran.com/31/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1916, 'وذ قل لقم قمن لبن بنه وهو يعظ عظه ي بني ل تشر شرك بلل لله ان الش لشر شرك لظل ظلم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1917, 'quran:31:14', 'quran', 'quran', '31:14', 14, 1916, 'Luqman', 'لقمان', 'وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ', NULL, NULL, 'ووصينا الانسن بولديه حملته امه وهنا علي وهن وفصله في عامين ان اشكر لي ولولديك الي المصير', 'وصي انسن بولد حملت ام هن عل وهن فصل في عم ان اشكر لي لولديك ال مصير', 'quran', NULL, NULL, 'https://quran.com/31/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1917, 'ووص وصي صين الن لنس نسن بول ولد لدي ديه حمل ملت لته امه وهن علي وهن وفص فصل صله في عمي مين ان اشك شكر لي ولو لول ولد لدي ديك الي الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1918, 'quran:31:15', 'quran', 'quran', '31:15', 15, 1917, 'Luqman', 'لقمان', 'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'وان جهداك علي ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبيكم بما كنتم تعملون', 'ون جهدك عل ان تشرك بي م ليس لك به علم فل تطعهم صحبهم في دني معروف اتبع سبيل من انب ال ثم ال مرجع انبي بم كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/31/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1918, 'ون جهد هدك علي ان تشر شرك بي م ليس لك به علم فل تطع طعه عهم وصح صحب حبه بهم في الد لدن دني معر عرو روف وتب تبع سبي بيل من انب الي ثم الي مرج رجع جعك عكم فنب نبي بيك يكم بم كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1919, 'quran:31:16', 'quran', 'quran', '31:16', 16, 1918, 'Luqman', 'لقمان', 'يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ', NULL, NULL, 'يا بني انها ان تك مثقال حبه من خردل فتكن في صخره او في السموت او في الارض يات بها الله ان الله لطيف خبير', 'ي بن ان ان تك مثقل حب من خردل تكن في صخر او في سموت او في ارض يت به له ان له لطيف خبير', 'quran', NULL, NULL, 'https://quran.com/31/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1919, 'ي بني انه ان تك مثق ثقل حبه من خرد ردل فتك تكن في صخر خره او في الس لسم سمو موت او في الر لرض يت به الل لله ان الل لله لطي طيف خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1920, 'quran:31:17', 'quran', 'quran', '31:17', 17, 1919, 'Luqman', 'لقمان', 'يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ', NULL, NULL, 'يا بني اقم الصلاه وامر بالمعروف وانه عن المنكر واصبر علي ما اصابك ان ذلك من عزم الامور', 'ي بن اقم صل امر معروف ان عن منكر اصبر عل م اصبك ان ذلك من عزم امور', 'quran', NULL, NULL, 'https://quran.com/31/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1920, 'ي بني اقم الص لصل صله ومر بلم لمع معر عرو روف ونه عن الم لمن منك نكر وصب صبر علي م اصب صبك ان ذلك من عزم الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1921, 'quran:31:18', 'quran', 'quran', '31:18', 18, 1920, 'Luqman', 'لقمان', 'وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ', NULL, NULL, 'ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور', 'ول تصعر خدك نس ول تمش في ارض مرح ان له ل يحب كل مختل خور', 'quran', NULL, NULL, 'https://quran.com/31/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1921, 'ول تصع صعر خدك للن لنس ول تمش في الر لرض مرح ان الل لله ل يحب كل مخت ختل فخو خور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1922, 'quran:31:19', 'quran', 'quran', '31:19', 19, 1921, 'Luqman', 'لقمان', 'وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ', NULL, NULL, 'واقصد في مشيك واغضض من صوتك ان انكر الاصوت لصوت الحمير', 'اقصد في مشيك اغضض من صوتك ان انكر اصوت لصوت حمير', 'quran', NULL, NULL, 'https://quran.com/31/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1922, 'وقص قصد في مشي شيك وغض غضض من صوت وتك ان انك نكر الص لصو صوت لصو صوت الح لحم حمي مير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1923, 'quran:31:20', 'quran', 'quran', '31:20', 20, 1922, 'Luqman', 'لقمان', 'أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ', NULL, NULL, 'الم تروا ان الله سخر لكم ما في السموت وما في الارض واسبغ عليكم نعمه ظهره وباطنه ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير', 'الم تر ان له سخر لكم م في سموت وم في ارض اسبغ علي نعم ظهر بطن ومن نس من يجدل في له بغير علم ول هد ول كتب منير', 'quran', NULL, NULL, 'https://quran.com/31/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1923, 'الم ترو ان الل لله سخر لكم م في الس لسم سمو موت وم في الر لرض وسب سبغ علي ليك يكم نعم عمه ظهر هره وبط بطن طنه ومن الن لنس من يجد جدل في الل لله بغي غير علم ول هدي ول كتب مني نير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1924, 'quran:31:21', 'quran', 'quran', '31:21', 21, 1923, 'Luqman', 'لقمان', 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', NULL, NULL, 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما وجدنا عليه اباءنا اولو كان الشيطن يدعوهم الي عذاب السعير', 'اذ قيل لهم اتبع م انزل له قل بل نتبع م جد عل ابء اولو كن شيطن يدعو ال عذب سعير', 'quran', NULL, NULL, 'https://quran.com/31/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1924, 'وذ قيل لهم اتب تبع بعو م انز نزل الل لله قلو بل نتب تبع م وجد جدن علي ليه ابء بءن اول ولو كن الش لشي شيط يطن يدع دعو عوه وهم الي عذب الس لسع سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1925, 'quran:31:22', 'quran', 'quran', '31:22', 22, 1924, 'Luqman', 'لقمان', 'وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ', NULL, NULL, 'ومن يسلم وجهه الي الله وهو محسن فقد استمسك بالعروه الوثقي والي الله عقبه الامور', 'ومن يسلم جه ال له وهو محسن فقد استمسك عرو وثق ول له عقب امور', 'quran', NULL, NULL, 'https://quran.com/31/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1925, 'ومن يسل سلم وجه جهه الي الل لله وهو محس حسن فقد است ستم تمس مسك بلع لعر عرو روه الو لوث وثق ثقي ولي الل لله عقب قبه الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1926, 'quran:31:23', 'quran', 'quran', '31:23', 23, 1925, 'Luqman', 'لقمان', 'وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'ومن كفر فلا يحزنك كفره الينا مرجعهم فننبيهم بما عملوا ان الله عليم بذات الصدور', 'ومن كفر فل يحزنك كفر ين مرجع ننبي بم عمل ان له عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/31/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1926, 'ومن كفر فل يحز حزن زنك كفر فره الي لين مرج رجع جعه عهم فنن ننب نبي بيه يهم بم عمل ملو ان الل لله علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1927, 'quran:31:24', 'quran', 'quran', '31:24', 24, 1926, 'Luqman', 'لقمان', 'نُمَتِّعُهُمۡ قَلِيلٗا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظٖ', NULL, NULL, 'نمتعهم قليلا ثم نضطرهم الي عذاب غليظ', 'نمتع قليل ثم نضطر ال عذب غليظ', 'quran', NULL, NULL, 'https://quran.com/31/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1927, 'نمت متع تعه عهم قلي ليل ثم نضط ضطر طره رهم الي عذب غلي ليظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1928, 'quran:31:25', 'quran', 'quran', '31:25', 25, 1927, 'Luqman', 'لقمان', 'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'ولين سالتهم من خلق السموت والارض ليقولن الله قل الحمد لله بل اكثرهم لا يعلمون', 'لين سلت من خلق سموت ارض ليقولن له قل حمد لل بل اكثر ل يعلم', 'quran', NULL, NULL, 'https://quran.com/31/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1928, 'ولي لين سلت لته تهم من خلق الس لسم سمو موت ولر لرض ليق يقو قول ولن الل لله قل الح لحم حمد لله بل اكث كثر ثره رهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1929, 'quran:31:26', 'quran', 'quran', '31:26', 26, 1928, 'Luqman', 'لقمان', 'لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ', NULL, NULL, 'لله ما في السموت والارض ان الله هو الغني الحميد', 'لل م في سموت ارض ان له هو غن حميد', 'quran', NULL, NULL, 'https://quran.com/31/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1929, 'لله م في الس لسم سمو موت ولر لرض ان الل لله هو الغ لغن غني الح لحم حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1930, 'quran:31:27', 'quran', 'quran', '31:27', 27, 1929, 'Luqman', 'لقمان', 'وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', NULL, NULL, 'ولو انما في الارض من شجره اقلم والبحر يمده من بعده سبعه ابحر ما نفدت كلمت الله ان الله عزيز حكيم', 'ولو انم في ارض من شجر اقلم بحر يمد من بعد سبع ابحر م نفدت كلمت له ان له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/31/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1930, 'ولو انم في الر لرض من شجر جره اقل قلم ولب لبح بحر يمد مده من بعد عده سبع بعه ابح بحر م نفد فدت كلم لمت الل لله ان الل لله عزي زيز حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1931, 'quran:31:28', 'quran', 'quran', '31:28', 28, 1930, 'Luqman', 'لقمان', 'مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسٖ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ', NULL, NULL, 'ما خلقكم ولا بعثكم الا كنفس وحده ان الله سميع بصير', 'م خلق ول بعث ال كنفس حد ان له سميع بصير', 'quran', NULL, NULL, 'https://quran.com/31/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1931, 'م خلق لقك قكم ول بعث عثك ثكم ال كنف نفس وحد حده ان الل لله سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1932, 'quran:31:29', 'quran', 'quran', '31:29', 29, 1931, 'Luqman', 'لقمان', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'الم تر ان الله يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري الي اجل مسمي وان الله بما تعملون خبير', 'الم تر ان له يولج يل في نهر يولج نهر في يل سخر شمس قمر كل يجر ال اجل مسم ون له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/31/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1932, 'الم تر ان الل لله يول ولج الي ليل في الن لنه نهر ويو يول ولج الن لنه نهر في الي ليل وسخ سخر الش لشم شمس ولق لقم قمر كل يجر جري الي اجل مسم سمي ون الل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1933, 'quran:31:30', 'quran', 'quran', '31:30', 30, 1932, 'Luqman', 'لقمان', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ', NULL, NULL, 'ذلك بان الله هو الحق وان ما يدعون من دونه البطل وان الله هو العلي الكبير', 'ذلك بن له هو حق ون م يدع من دون بطل ون له هو عل كبير', 'quran', NULL, NULL, 'https://quran.com/31/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1933, 'ذلك بن الل لله هو الح لحق ون م يدع دعو عون من دون ونه الب لبط بطل ون الل لله هو الع لعل علي الك لكب كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1934, 'quran:31:31', 'quran', 'quran', '31:31', 31, 1933, 'Luqman', 'لقمان', 'أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ', NULL, NULL, 'الم تر ان الفلك تجري في البحر بنعمت الله ليريكم من ايته ان في ذلك لايت لكل صبار شكور', 'الم تر ان فلك تجر في بحر بنعمت له ليري من ايت ان في ذلك ليت لكل صبر شكور', 'quran', NULL, NULL, 'https://quran.com/31/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1934, 'الم تر ان الف لفل فلك تجر جري في الب لبح بحر بنع نعم عمت الل لله لير يري ريك يكم من ايت يته ان في ذلك ليت لكل صبر شكو كور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1935, 'quran:31:32', 'quran', 'quran', '31:32', 32, 1934, 'Luqman', 'لقمان', 'وَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ', NULL, NULL, 'واذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجاهم الي البر فمنهم مقتصد وما يجحد بايتنا الا كل ختار كفور', 'اذ غشي موج ظلل دع له مخلص له دين لم نج ال بر من مقتصد وم يجحد بيت ال كل ختر كفور', 'quran', NULL, NULL, 'https://quran.com/31/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1935, 'وذ غشي شيه يهم موج كلظ لظل ظلل دعو الل لله مخل خلص لصي صين له الد لدي دين فلم نجه جهم الي الب لبر فمن منه نهم مقت قتص تصد وم يجح جحد بيت يتن ال كل ختر كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1936, 'quran:31:33', 'quran', 'quran', '31:33', 33, 1935, 'Luqman', 'لقمان', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ', NULL, NULL, 'يا ايها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيا ان وعد الله حق فلا تغرنكم الحياه الدنيا ولا يغرنكم بالله الغرور', 'ي اي نس اتق رب اخش يوم ل يجز ولد عن لد ول مولود هو جز عن ده شي ان وعد له حق فل تغرن حي دني ول يغرن له غرور', 'quran', NULL, NULL, 'https://quran.com/31/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1936, 'ي ايه الن لنس اتق تقو ربك بكم وخش خشو يوم ل يجز جزي ولد عن ولد لده ول مول ولو لود هو جز عن ولد لده شي ان وعد الل لله حق فل تغر غرن رنك نكم الح لحي حيه الد لدن دني ول يغر غرن رنك نكم بلل لله الغ لغر غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1937, 'quran:31:34', 'quran', 'quran', '31:34', 34, 1936, 'Luqman', 'لقمان', 'إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ', NULL, NULL, 'ان الله عنده علم الساعه وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير', 'ان له عند علم سع ينزل غيث يعلم م في ارحم وم تدر نفس مذ تكسب غد وم تدر نفس ب ارض تموت ان له عليم خبير', 'quran', NULL, NULL, 'https://quran.com/31/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1937, 'ان الل لله عند نده علم الس لسع سعه وين ينز نزل الغ لغي غيث ويع يعل علم م في الر لرح رحم وم تدر دري نفس مذ تكس كسب غد وم تدر دري نفس بي ارض تمو موت ان الل لله علي ليم خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1938, 'quran:33:1', 'quran', 'quran', '33:1', 1, 1937, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا', NULL, NULL, 'يا ايها النبي اتق الله ولا تطع الكفرين والمنفقين ان الله كان عليما حكيما', 'ي اي نب اتق له ول تطع كفر منفق ان له كن عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/33/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1938, 'ي ايه الن لنب نبي اتق الل لله ول تطع الك لكف كفر فري رين ولم لمن منف نفق فقي قين ان الل لله كن علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1939, 'quran:33:2', 'quran', 'quran', '33:2', 2, 1938, 'Al-Ahzab', 'الأحزاب', 'وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', NULL, NULL, 'واتبع ما يوحي اليك من ربك ان الله كان بما تعملون خبيرا', 'اتبع م يوح يك من ربك ان له كن بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/33/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1939, 'وتب تبع م يوح وحي الي ليك من ربك ان الل لله كن بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1940, 'quran:33:3', 'quran', 'quran', '33:3', 3, 1939, 'Al-Ahzab', 'الأحزاب', 'وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا', NULL, NULL, 'وتوكل علي الله وكفي بالله وكيلا', 'توكل عل له كف له كيل', 'quran', NULL, NULL, 'https://quran.com/33/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1940, 'وتو توك وكل علي الل لله وكف كفي بلل لله وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1941, 'quran:33:4', 'quran', 'quran', '33:4', 4, 1940, 'Al-Ahzab', 'الأحزاب', 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ', NULL, NULL, 'ما جعل الله لرجل من قلبين في جوفه وما جعل ازوجكم الي تظهرون منهن امهتكم وما جعل ادعياءكم ابناءكم ذلكم قولكم بافوهكم والله يقول الحق وهو يهدي السبيل', 'م جعل له لرجل من قلب في جوف وم جعل ازوج ال تظهر من امهت وم جعل ادعيء ابنء ذل قول بفوه له يقول حق وهو يهد سبيل', 'quran', NULL, NULL, 'https://quran.com/33/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1941, 'م جعل الل لله لرج رجل من قلب لبي بين في جوف وفه وم جعل ازو زوج وجك جكم الي تظه ظهر هرو رون منه نهن امه مهت هتك تكم وم جعل ادع دعي عيء يءك ءكم ابن بنء نءك ءكم ذلك لكم قول ولك لكم بفو فوه وهك هكم ولل لله يقو قول الح لحق وهو يهد هدي الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1942, 'quran:33:5', 'quran', 'quran', '33:5', 5, 1941, 'Al-Ahzab', 'الأحزاب', 'ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا', NULL, NULL, 'ادعوهم لابايهم هو اقسط عند الله فان لم تعلموا اباءهم فاخونكم في الدين وموليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما', 'ادعو لبي هو اقسط عند له فن لم تعلم ابء اخون في دين مولي ليس علي جنح يم اخطتم به لكن م تعمدت قلوب كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/33/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1942, 'ادع دعو عوه وهم لبي بيه يهم هو اقس قسط عند الل لله فن لم تعل علم لمو ابء بءه ءهم فخو خون ونك نكم في الد لدي دين ومو مول ولي ليك يكم ولي ليس علي ليك يكم جنح فيم اخط خطت طتم به ولك لكن م تعم عمد مدت قلو لوب وبك بكم وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1943, 'quran:33:6', 'quran', 'quran', '33:6', 6, 1942, 'Al-Ahzab', 'الأحزاب', 'ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا', NULL, NULL, 'النبي اولي بالمومنين من انفسهم وازوجه امهتهم واولوا الارحام بعضهم اولي ببعض في كتب الله من المومنين والمهجرين الا ان تفعلوا الي اوليايكم معروفا كان ذلك في الكتب مسطورا', 'نب اول مومن من انفس ازوج امهت اول ارحم بعض اول ببعض في كتب له من مومن مهجر ال ان تفعل ال اوليي معروف كن ذلك في كتب مسطور', 'quran', NULL, NULL, 'https://quran.com/33/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1943, 'الن لنب نبي اول ولي بلم لمو موم ومن مني نين من انف نفس فسه سهم وزو زوج وجه امه مهت هته تهم وول ولو الر لرح رحم بعض عضه ضهم اول ولي ببع بعض في كتب الل لله من الم لمو موم ومن مني نين ولم لمه مهج هجر جري رين ال ان تفع فعل علو الي اول ولي ليي ييك يكم معر عرو روف كن ذلك في الك لكت كتب مسط سطو طور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1944, 'quran:33:7', 'quran', 'quran', '33:7', 7, 1943, 'Al-Ahzab', 'الأحزاب', 'وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا', NULL, NULL, 'واذ اخذنا من النبين ميثقهم ومنك ومن نوح وابرهيم وموسي وعيسي ابن مريم واخذنا منهم ميثقا غليظا', 'وذ اخذ من نب ميثق منك ومن نوح ابرهيم موس عيس ابن مريم اخذ من ميثق غليظ', 'quran', NULL, NULL, 'https://quran.com/33/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1944, 'وذ اخذ خذن من الن لنب نبي بين ميث يثق ثقه قهم ومن منك ومن نوح وبر بره رهي هيم ومو موس وسي وعي عيس يسي ابن مري ريم وخذ خذن منه نهم ميث يثق غلي ليظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1945, 'quran:33:8', 'quran', 'quran', '33:8', 8, 1944, 'Al-Ahzab', 'الأحزاب', 'لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا', NULL, NULL, 'ليسل الصدقين عن صدقهم واعد للكفرين عذابا اليما', 'ليسل صدق عن صدق اعد كفر عذب يم', 'quran', NULL, NULL, 'https://quran.com/33/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1945, 'ليس يسل الص لصد صدق دقي قين عن صدق دقه قهم وعد للك لكف كفر فري رين عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1946, 'quran:33:9', 'quran', 'quran', '33:9', 9, 1945, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا', NULL, NULL, 'يا ايها الذين امنوا اذكروا نعمه الله عليكم اذ جاءتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا', 'ي اي ذين امن اذكر نعم له علي اذ جءت جنود ارسل علي ريح جنود لم ترو كن له بم تعمل بصير', 'quran', NULL, NULL, 'https://quran.com/33/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1946, 'ي ايه الذ لذي ذين امن منو اذك ذكر كرو نعم عمه الل لله علي ليك يكم اذ جءت ءتك تكم جنو نود فرس رسل سلن علي ليه يهم ريح وجن جنو نود لم ترو روه وكن الل لله بم تعم عمل ملو لون بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1947, 'quran:33:10', 'quran', 'quran', '33:10', 10, 1946, 'Al-Ahzab', 'الأحزاب', 'إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', NULL, NULL, 'اذ جاءوكم من فوقكم ومن اسفل منكم واذ زاغت الابصر وبلغت القلوب الحناجر وتظنون بالله الظنونا', 'اذ جءو من وق ومن اسفل من وذ زغت ابصر بلغت قلوب حنجر تظن له ظنو', 'quran', NULL, NULL, 'https://quran.com/33/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1947, 'اذ جءو ءوك وكم من فوق وقك قكم ومن اسف سفل منك نكم وذ زغت الب لبص بصر وبل بلغ لغت الق لقل قلو لوب الح لحن حنج نجر وتظ تظن ظنو نون بلل لله الظ لظن ظنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1948, 'quran:33:11', 'quran', 'quran', '33:11', 11, 1947, 'Al-Ahzab', 'الأحزاب', 'هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا', NULL, NULL, 'هنالك ابتلي المومنون وزلزلوا زلزالا شديدا', 'هنلك ابتل مومن زلزل زلزل شديد', 'quran', NULL, NULL, 'https://quran.com/33/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1948, 'هنل نلك ابت بتل تلي الم لمو موم ومن منو نون وزل زلز لزل زلو زلز لزل شدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1949, 'quran:33:12', 'quran', 'quran', '33:12', 12, 1948, 'Al-Ahzab', 'الأحزاب', 'وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا', NULL, NULL, 'واذ يقول المنفقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا', 'وذ يقول منفق ذين في قلوب مرض م عد له رسول ال غرور', 'quran', NULL, NULL, 'https://quran.com/33/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1949, 'وذ يقو قول الم لمن منف نفق فقو قون ولذ لذي ذين في قلو لوب وبه بهم مرض م وعد عدن الل لله ورس رسو سول وله ال غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1950, 'quran:33:13', 'quran', 'quran', '33:13', 13, 1949, 'Al-Ahzab', 'الأحزاب', 'وَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا', NULL, NULL, 'واذ قالت طايفه منهم يا اهل يثرب لا مقام لكم فارجعوا ويستذن فريق منهم النبي يقولون ان بيوتنا عوره وما هي بعوره ان يريدون الا فرارا', 'وذ قلت طيف من ي اهل يثرب ل مقم لكم ارجع يستذن ريق من نب يقول ان بيوت عور وم هي بعور ان يريد ال رر', 'quran', NULL, NULL, 'https://quran.com/33/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1950, 'وذ قلت طيف يفه منه نهم ي اهل يثر ثرب ل مقم لكم فرج رجع جعو ويس يست ستذ تذن فري ريق منه نهم الن لنب نبي يقو قول ولو لون ان بيو يوت وتن عور وره وم هي بعو عور وره ان يري ريد يدو دون ال فرر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1951, 'quran:33:14', 'quran', 'quran', '33:14', 14, 1950, 'Al-Ahzab', 'الأحزاب', 'وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرٗا', NULL, NULL, 'ولو دخلت عليهم من اقطارها ثم سيلوا الفتنه لاتوها وما تلبثوا بها الا يسيرا', 'ولو دخلت علي من اقطر ثم سيل فتن لتو وم تلبث به ال يسير', 'quran', NULL, NULL, 'https://quran.com/33/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1951, 'ولو دخل خلت علي ليه يهم من اقط قطر طره ثم سيل يلو الف لفت فتن تنه لتو توه وم تلب لبث بثو به ال يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1952, 'quran:33:15', 'quran', 'quran', '33:15', 15, 1951, 'Al-Ahzab', 'الأحزاب', 'وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولٗا', NULL, NULL, 'ولقد كانوا عهدوا الله من قبل لا يولون الادبر وكان عهد الله مسولا', 'لقد كن عهد له من قبل ل يول ادبر كن عهد له مسول', 'quran', NULL, NULL, 'https://quran.com/33/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1952, 'ولق لقد كنو عهد هدو الل لله من قبل ل يول ولو لون الد لدب دبر وكن عهد الل لله مسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1953, 'quran:33:16', 'quran', 'quran', '33:16', 16, 1952, 'Al-Ahzab', 'الأحزاب', 'قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا', NULL, NULL, 'قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا', 'قل لن ينفع فرر ان ررتم من موت او قتل اذ ل تمتع ال قليل', 'quran', NULL, NULL, 'https://quran.com/33/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1953, 'قل لن ينف نفع فعك عكم الف لفر فرر ان فرر ررت رتم من الم لمو موت او الق لقت قتل وذ ل تمت متع تعو عون ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1954, 'quran:33:17', 'quran', 'quran', '33:17', 17, 1953, 'Al-Ahzab', 'الأحزاب', 'قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا', NULL, NULL, 'قل من ذا الذي يعصمكم من الله ان اراد بكم سوا او اراد بكم رحمه ولا يجدون لهم من دون الله وليا ولا نصيرا', 'قل من ذ ذي يعصم من له ان ارد بكم سو او ارد بكم رحم ول يجد لهم من دون له لي ول نصير', 'quran', NULL, NULL, 'https://quran.com/33/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1954, 'قل من ذ الذ لذي يعص عصم صمك مكم من الل لله ان ارد بكم سو او ارد بكم رحم حمه ول يجد جدو دون لهم من دون الل لله ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1955, 'quran:33:18', 'quran', 'quran', '33:18', 18, 1954, 'Al-Ahzab', 'الأحزاب', 'قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا', NULL, NULL, 'قد يعلم الله المعوقين منكم والقايلين لاخونهم هلم الينا ولا ياتون الباس الا قليلا', 'قد يعلم له معوق من قيل لخون هلم ين ول يت بس ال قليل', 'quran', NULL, NULL, 'https://quran.com/33/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1955, 'قد يعل علم الل لله الم لمع معو عوق وقي قين منك نكم ولق لقي قيل يلي لين لخو خون ونه نهم هلم الي لين ول يتو تون الب لبس ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1956, 'quran:33:19', 'quran', 'quran', '33:19', 19, 1955, 'Al-Ahzab', 'الأحزاب', 'أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا', NULL, NULL, 'اشحه عليكم فاذا جاء الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشي عليه من الموت فاذا ذهب الخوف سلقوكم بالسنه حداد اشحه علي الخير اوليك لم يومنوا فاحبط الله اعملهم وكان ذلك علي الله يسيرا', 'اشح علي اذ جء خوف ريت ينظر يك تدور اعين ذي يغش عل من موت اذ ذهب خوف سلقو سن حدد اشح عل خير اوليك لم يومن احبط له اعمل كن ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/33/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1956, 'اشح شحه علي ليك يكم فذ جء الخ لخو خوف ريت يته تهم ينظ نظر ظرو رون الي ليك تدو دور اعي عين ينه نهم كلذ لذي يغش غشي علي ليه من الم لمو موت فذ ذهب الخ لخو خوف سلق لقو قوك وكم بلس لسن سنه حدد اشح شحه علي الخ لخي خير اول ولي ليك لم يوم ومن منو فحب حبط الل لله اعم عمل مله لهم وكن ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1957, 'quran:33:20', 'quran', 'quran', '33:20', 20, 1956, 'Al-Ahzab', 'الأحزاب', 'يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا', NULL, NULL, 'يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسلون عن انبايكم ولو كانوا فيكم ما قتلوا الا قليلا', 'يحسب احزب لم يذهب ون يت احزب يود لو ان بد في اعرب يسل عن انبي ولو كن يكم م قتل ال قليل', 'quran', NULL, NULL, 'https://quran.com/33/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1957, 'يحس حسب سبو بون الح لحز حزب لم يذه ذهب هبو ون يت الح لحز حزب يود ودو لو انه نهم بدو دون في الع لعر عرب يسل سلو لون عن انب نبي بيك يكم ولو كنو فيك يكم م قتل تلو ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1958, 'quran:33:21', 'quran', 'quran', '33:21', 21, 1957, 'Al-Ahzab', 'الأحزاب', 'لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا', NULL, NULL, 'لقد كان لكم في رسول الله اسوه حسنه لمن كان يرجوا الله واليوم الاخر وذكر الله كثيرا', 'لقد كن لكم في رسول له اسو حسن لمن كن يرج له يوم اخر ذكر له كثير', 'quran', NULL, NULL, 'https://quran.com/33/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1958, 'لقد كن لكم في رسو سول الل لله اسو سوه حسن سنه لمن كن يرج رجو الل لله ولي ليو يوم الخ لخر وذك ذكر الل لله كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1959, 'quran:33:22', 'quran', 'quran', '33:22', 22, 1958, 'Al-Ahzab', 'الأحزاب', 'وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا', NULL, NULL, 'ولما را المومنون الاحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم الا ايمنا وتسليما', 'لم ر مومن احزب قل هذ م عد له رسول صدق له رسول وم زد ال ايم تسليم', 'quran', NULL, NULL, 'https://quran.com/33/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1959, 'ولم ر الم لمو موم ومن منو نون الح لحز حزب قلو هذ م وعد عدن الل لله ورس رسو سول وله وصد صدق الل لله ورس رسو سول وله وم زده دهم ال ايم يمن وتس تسل سلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1960, 'quran:33:23', 'quran', 'quran', '33:23', 23, 1959, 'Al-Ahzab', 'الأحزاب', 'مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا', NULL, NULL, 'من المومنين رجال صدقوا ما عهدوا الله عليه فمنهم من قضي نحبه ومنهم من ينتظر وما بدلوا تبديلا', 'من مومن رجل صدق م عهد له عل من من قض نحب من من ينتظر وم بدل تبديل', 'quran', NULL, NULL, 'https://quran.com/33/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1960, 'من الم لمو موم ومن مني نين رجل صدق دقو م عهد هدو الل لله علي ليه فمن منه نهم من قضي نحب حبه ومن منه نهم من ينت نتظ تظر وم بدل دلو تبد بدي ديل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1961, 'quran:33:24', 'quran', 'quran', '33:24', 24, 1960, 'Al-Ahzab', 'الأحزاب', 'لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'ليجزي الله الصدقين بصدقهم ويعذب المنفقين ان شاء او يتوب عليهم ان الله كان غفورا رحيما', 'ليجز له صدق بصدق يعذب منفق ان شء او يتوب علي ان له كن غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/33/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1961, 'ليج يجز جزي الل لله الص لصد صدق دقي قين بصد صدق دقه قهم ويع يعذ عذب الم لمن منف نفق فقي قين ان شء او يتو توب علي ليه يهم ان الل لله كن غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1962, 'quran:33:25', 'quran', 'quran', '33:25', 25, 1961, 'Al-Ahzab', 'الأحزاب', 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا', NULL, NULL, 'ورد الله الذين كفروا بغيظهم لم ينالوا خيرا وكفي الله المومنين القتال وكان الله قويا عزيزا', 'ورد له ذين كفر بغيظ لم ينل خير كف له مومن قتل كن له قوي عزيز', 'quran', NULL, NULL, 'https://quran.com/33/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1962, 'ورد الل لله الذ لذي ذين كفر فرو بغي غيظ يظه ظهم لم ينل نلو خير وكف كفي الل لله الم لمو موم ومن مني نين الق لقت قتل وكن الل لله قوي عزي زيز');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1963, 'quran:33:26', 'quran', 'quran', '33:26', 26, 1962, 'Al-Ahzab', 'الأحزاب', 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا', NULL, NULL, 'وانزل الذين ظهروهم من اهل الكتب من صياصيهم وقذف في قلوبهم الرعب فريقا تقتلون وتاسرون فريقا', 'انزل ذين ظهرو من اهل كتب من صيصي قذف في قلوب رعب ريق تقتل تسر ريق', 'quran', NULL, NULL, 'https://quran.com/33/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1963, 'ونز نزل الذ لذي ذين ظهر هرو روه وهم من اهل الك لكت كتب من صيص يصي صيه يهم وقذ قذف في قلو لوب وبه بهم الر لرع رعب فري ريق تقت قتل تلو لون وتس تسر سرو رون فري ريق');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1964, 'quran:33:27', 'quran', 'quran', '33:27', 27, 1963, 'Al-Ahzab', 'الأحزاب', 'وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا', NULL, NULL, 'واورثكم ارضهم وديرهم وامولهم وارضا لم تطوها وكان الله علي كل شيء قديرا', 'اورث ارض دير امول ارض لم تطو كن له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/33/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1964, 'وور ورث رثك ثكم ارض رضه ضهم ودي دير يره رهم ومو مول وله لهم ورض لم تطو طوه وكن الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1965, 'quran:33:28', 'quran', 'quran', '33:28', 28, 1964, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا', NULL, NULL, 'يا ايها النبي قل لازوجك ان كنتن تردن الحياه الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا', 'ي اي نب قل لزوجك ان كنتن تردن حي دني زينت تعل امتعكن اسرحكن سرح جميل', 'quran', NULL, NULL, 'https://quran.com/33/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1965, 'ي ايه الن لنب نبي قل لزو زوج وجك ان كنت نتن ترد ردن الح لحي حيه الد لدن دني وزي زين ينت نته فتع تعل علي لين امت متع تعك عكن وسر سرح رحك حكن سرح جمي ميل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1966, 'quran:33:29', 'quran', 'quran', '33:29', 29, 1965, 'Al-Ahzab', 'الأحزاب', 'وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا', NULL, NULL, 'وان كنتن تردن الله ورسوله والدار الاخره فان الله اعد للمحسنت منكن اجرا عظيما', 'ون كنتن تردن له رسول در اخر فن له اعد محسنت منكن اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/33/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1966, 'ون كنت نتن ترد ردن الل لله ورس رسو سول وله ولد لدر الخ لخر خره فن الل لله اعد للم لمح محس حسن سنت منك نكن اجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1967, 'quran:33:30', 'quran', 'quran', '33:30', 30, 1966, 'Al-Ahzab', 'الأحزاب', 'يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا', NULL, NULL, 'يا نساء النبي من يات منكن بفحشه مبينه يضعف لها العذاب ضعفين وكان ذلك علي الله يسيرا', 'ي نسء نب من يت منكن بفحش مبين يضعف له عذب ضعف كن ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/33/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1967, 'ي نسء الن لنب نبي من يت منك نكن بفح فحش حشه مبي بين ينه يضع ضعف له الع لعذ عذب ضعف عفي فين وكن ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1968, 'quran:33:31', 'quran', 'quran', '33:31', 31, 1967, 'Al-Ahzab', 'الأحزاب', 'وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا', NULL, NULL, 'ومن يقنت منكن لله ورسوله وتعمل صلحا نوتها اجرها مرتين واعتدنا لها رزقا كريما', 'ومن يقنت منكن لل رسول تعمل صلح نوت اجر مرت اعتد له رزق كريم', 'quran', NULL, NULL, 'https://quran.com/33/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1968, 'ومن يقن قنت منك نكن لله ورس رسو سول وله وتع تعم عمل صلح نوت وته اجر جره مرت رتي تين وعت عتد تدن له رزق كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1969, 'quran:33:32', 'quran', 'quran', '33:32', 32, 1968, 'Al-Ahzab', 'الأحزاب', 'يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا', NULL, NULL, 'يا نساء النبي لستن كاحد من النساء ان اتقيتن فلا تخضعن بالقول فيطمع الذي في قلبه مرض وقلن قولا معروفا', 'ي نسء نب لستن كحد من نسء ان اتقيتن فل تخضعن قول يطمع ذي في قلب مرض قلن قول معروف', 'quran', NULL, NULL, 'https://quran.com/33/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1969, 'ي نسء الن لنب نبي لست ستن كحد من الن لنس نسء ان اتق تقي قيت يتن فل تخض خضع ضعن بلق لقو قول فيط يطم طمع الذ لذي في قلب لبه مرض وقل قلن قول معر عرو روف');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1970, 'quran:33:33', 'quran', 'quran', '33:33', 33, 1969, 'Al-Ahzab', 'الأحزاب', 'وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا', NULL, NULL, 'وقرن في بيوتكن ولا تبرجن تبرج الجهليه الاولي واقمن الصلاه واتين الزكاه واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا', 'قرن في بيوتكن ول تبرجن تبرج جهل اول اقمن صل ات زك اطعن له رسول انم يريد له ليذهب عن رجس اهل بيت يطهر تطهير', 'quran', NULL, NULL, 'https://quran.com/33/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1970, 'وقر قرن في بيو يوت وتك تكن ول تبر برج رجن تبر برج الج لجه جهل هلي ليه الو لول ولي وقم قمن الص لصل صله وتي تين الز لزك زكه وطع طعن الل لله ورس رسو سول وله انم يري ريد الل لله ليذ يذه ذهب عنك نكم الر لرج رجس اهل الب لبي بيت ويط يطه طهر هرك ركم تطه طهي هير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1971, 'quran:33:34', 'quran', 'quran', '33:34', 34, 1970, 'Al-Ahzab', 'الأحزاب', 'وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', NULL, NULL, 'واذكرن ما يتلي في بيوتكن من ايت الله والحكمه ان الله كان لطيفا خبيرا', 'اذكرن م يتل في بيوتكن من ايت له حكم ان له كن لطيف خبير', 'quran', NULL, NULL, 'https://quran.com/33/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1971, 'وذك ذكر كرن م يتل تلي في بيو يوت وتك تكن من ايت الل لله ولح لحك حكم كمه ان الل لله كن لطي طيف خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1972, 'quran:33:35', 'quran', 'quran', '33:35', 35, 1971, 'Al-Ahzab', 'الأحزاب', 'إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا', NULL, NULL, 'ان المسلمين والمسلمت والمومنين والمومنت والقنتين والقنتت والصدقين والصدقت والصبرين والصبرت والخشعين والخشعت والمتصدقين والمتصدقت والصيمين والصيمت والحفظين فروجهم والحفظت والذكرين الله كثيرا والذكرت اعد الله لهم مغفره واجرا عظيما', 'ان مسلم مسلمت مومن مومنت قنت قنتت صدق صدقت صبر صبرت خشع خشعت متصدق متصدقت صيم صيمت حفظ روج حفظت ذكر له كثير ذكرت اعد له لهم مغفر اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/33/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1972, 'ان الم لمس مسل سلم لمي مين ولم لمس مسل سلم لمت ولم لمو موم ومن مني نين ولم لمو موم ومن منت ولق لقن قنت نتي تين ولق لقن قنت نتت ولص لصد صدق دقي قين ولص لصد صدق دقت ولص لصب صبر بري رين ولص لصب صبر برت ولخ لخش خشع شعي عين ولخ لخش خشع شعت ولم لمت متص تصد صدق دقي قين ولم لمت متص تصد صدق دقت ولص لصي صيم يمي مين ولص لصي صيم يمت ولح لحف حفظ فظي ظين فرو روج وجه جهم ولح لحف حفظ فظت ولذ لذك ذكر كري رين الل لله كثي ثير ولذ لذك ذكر كرت اعد الل لله لهم مغف غفر فره وجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1973, 'quran:33:36', 'quran', 'quran', '33:36', 36, 1972, 'Al-Ahzab', 'الأحزاب', 'وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا', NULL, NULL, 'وما كان لمومن ولا مومنه اذا قضي الله ورسوله امرا ان يكون لهم الخيره من امرهم ومن يعص الله ورسوله فقد ضل ضللا مبينا', 'وم كن لمومن ول مومن اذ قض له رسول امر ان يك لهم خير من امر ومن يعص له رسول فقد ضل ضلل مبي', 'quran', NULL, NULL, 'https://quran.com/33/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1973, 'وم كن لمو موم ومن ول موم ومن منه اذ قضي الل لله ورس رسو سول وله امر ان يكو كون لهم الخ لخي خير يره من امر مره رهم ومن يعص الل لله ورس رسو سول وله فقد ضل ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1974, 'quran:33:37', 'quran', 'quran', '33:37', 37, 1973, 'Al-Ahzab', 'الأحزاب', 'وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولٗا', NULL, NULL, 'واذ تقول للذي انعم الله عليه وانعمت عليه امسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشي الناس والله احق ان تخشاه فلما قضي زيد منها وطرا زوجنكها لكي لا يكون علي المومنين حرج في ازوج ادعيايهم اذا قضوا منهن وطرا وكان امر الله مفعولا', 'وذ تقول ذي انعم له عل انعمت عل امسك عليك زوجك اتق له تخف في نفسك م له مبد تخش نس له احق ان تخش لم قض زيد من طر زوجنك لك ل يك عل مومن حرج في ازوج ادعيي اذ قض من طر كن امر له مفعول', 'quran', NULL, NULL, 'https://quran.com/33/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1974, 'وذ تقو قول للذ لذي انع نعم الل لله علي ليه ونع نعم عمت علي ليه امس مسك علي ليك زوج وجك وتق الل لله وتخ تخف خفي في نفس فسك م الل لله مبد بدي ديه وتخ تخش خشي الن لنس ولل لله احق ان تخش خشه فلم قضي زيد منه وطر زوج وجن جنك نكه لكي ل يكو كون علي الم لمو موم ومن مني نين حرج في ازو زوج ادع دعي عيي ييه يهم اذ قضو منه نهن وطر وكن امر الل لله مفع فعو عول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1975, 'quran:33:38', 'quran', 'quran', '33:38', 38, 1974, 'Al-Ahzab', 'الأحزاب', 'مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجٖ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرٗا مَّقۡدُورًا', NULL, NULL, 'ما كان علي النبي من حرج فيما فرض الله له سنه الله في الذين خلوا من قبل وكان امر الله قدرا مقدورا', 'م كن عل نب من حرج يم فرض له له سن له في ذين خل من قبل كن امر له قدر مقدور', 'quran', NULL, NULL, 'https://quran.com/33/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1975, 'م كن علي الن لنب نبي من حرج فيم فرض الل لله له سنه الل لله في الذ لذي ذين خلو من قبل وكن امر الل لله قدر مقد قدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1976, 'quran:33:39', 'quran', 'quran', '33:39', 39, 1975, 'Al-Ahzab', 'الأحزاب', 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا', NULL, NULL, 'الذين يبلغون رسلت الله ويخشونه ولا يخشون احدا الا الله وكفي بالله حسيبا', 'ذين يبلغ رسلت له يخشون ول يخش احد ال له كف له حسيب', 'quran', NULL, NULL, 'https://quran.com/33/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1976, 'الذ لذي ذين يبل بلغ لغو غون رسل سلت الل لله ويخ يخش خشو شون ونه ول يخش خشو شون احد ال الل لله وكف كفي بلل لله حسي سيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1977, 'quran:33:40', 'quran', 'quran', '33:40', 40, 1976, 'Al-Ahzab', 'الأحزاب', 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا', NULL, NULL, 'ما كان محمد ابا احد من رجالكم ولكن رسول الله وخاتم النبين وكان الله بكل شيء عليما', 'م كن محمد اب احد من رجل لكن رسول له ختم نب كن له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/33/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1977, 'م كن محم حمد اب احد من رجل جلك لكم ولك لكن رسو سول الل لله وخت ختم الن لنب نبي بين وكن الل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1978, 'quran:33:41', 'quran', 'quran', '33:41', 41, 1977, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا', NULL, NULL, 'يا ايها الذين امنوا اذكروا الله ذكرا كثيرا', 'ي اي ذين امن اذكر له ذكر كثير', 'quran', NULL, NULL, 'https://quran.com/33/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1978, 'ي ايه الذ لذي ذين امن منو اذك ذكر كرو الل لله ذكر كثي ثير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1979, 'quran:33:42', 'quran', 'quran', '33:42', 42, 1978, 'Al-Ahzab', 'الأحزاب', 'وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا', NULL, NULL, 'وسبحوه بكره واصيلا', 'سبحو بكر اصيل', 'quran', NULL, NULL, 'https://quran.com/33/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1979, 'وسب سبح بحو حوه بكر كره وصي صيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1980, 'quran:33:43', 'quran', 'quran', '33:43', 43, 1979, 'Al-Ahzab', 'الأحزاب', 'هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا', NULL, NULL, 'هو الذي يصلي عليكم ومليكته ليخرجكم من الظلمت الي النور وكان بالمومنين رحيما', 'هو ذي يصل علي مليكت ليخرج من ظلمت ال نور كن مومن رحيم', 'quran', NULL, NULL, 'https://quran.com/33/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1980, 'هو الذ لذي يصل صلي علي ليك يكم ومل ملي ليك يكت كته ليخ يخر خرج رجك جكم من الظ لظل ظلم لمت الي الن لنو نور وكن بلم لمو موم ومن مني نين رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1981, 'quran:33:44', 'quran', 'quran', '33:44', 44, 1980, 'Al-Ahzab', 'الأحزاب', 'تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمٞۚ وَأَعَدَّ لَهُمۡ أَجۡرٗا كَرِيمٗا', NULL, NULL, 'تحيتهم يوم يلقونه سلم واعد لهم اجرا كريما', 'تحيت يوم يلقون سلم اعد لهم اجر كريم', 'quran', NULL, NULL, 'https://quran.com/33/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1981, 'تحي حيت يته تهم يوم يلق لقو قون ونه سلم وعد لهم اجر كري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1982, 'quran:33:45', 'quran', 'quran', '33:45', 45, 1981, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا', NULL, NULL, 'يا ايها النبي انا ارسلنك شهدا ومبشرا ونذيرا', 'ي اي نب ان ارسلنك شهد مبشر نذير', 'quran', NULL, NULL, 'https://quran.com/33/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1982, 'ي ايه الن لنب نبي ان ارس رسل سلن لنك شهد ومب مبش بشر ونذ نذي ذير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1983, 'quran:33:46', 'quran', 'quran', '33:46', 46, 1982, 'Al-Ahzab', 'الأحزاب', 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا', NULL, NULL, 'وداعيا الي الله باذنه وسراجا منيرا', 'دعي ال له بذن سرج منير', 'quran', NULL, NULL, 'https://quran.com/33/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1983, 'ودع دعي الي الل لله بذن ذنه وسر سرج مني نير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1984, 'quran:33:47', 'quran', 'quran', '33:47', 47, 1983, 'Al-Ahzab', 'الأحزاب', 'وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا', NULL, NULL, 'وبشر المومنين بان لهم من الله فضلا كبيرا', 'بشر مومن بن لهم من له ضل كبير', 'quran', NULL, NULL, 'https://quran.com/33/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1984, 'وبش بشر الم لمو موم ومن مني نين بن لهم من الل لله فضل كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1985, 'quran:33:48', 'quran', 'quran', '33:48', 48, 1984, 'Al-Ahzab', 'الأحزاب', 'وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا', NULL, NULL, 'ولا تطع الكفرين والمنفقين ودع اذاهم وتوكل علي الله وكفي بالله وكيلا', 'ول تطع كفر منفق ودع اذ توكل عل له كف له كيل', 'quran', NULL, NULL, 'https://quran.com/33/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1985, 'ول تطع الك لكف كفر فري رين ولم لمن منف نفق فقي قين ودع اذه ذهم وتو توك وكل علي الل لله وكف كفي بلل لله وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1986, 'quran:33:49', 'quran', 'quran', '33:49', 49, 1985, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا', NULL, NULL, 'يا ايها الذين امنوا اذا نكحتم المومنت ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عده تعتدونها فمتعوهن وسرحوهن سراحا جميلا', 'ي اي ذين امن اذ نكحتم مومنت ثم طلقتمو من قبل ان تمسو فم لكم علي من عد تعتدون متعو سرحو سرح جميل', 'quran', NULL, NULL, 'https://quran.com/33/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1986, 'ي ايه الذ لذي ذين امن منو اذ نكح كحت حتم الم لمو موم ومن منت ثم طلق لقت قتم تمو موه وهن من قبل ان تمس مسو سوه وهن فم لكم علي ليه يهن من عده تعت عتد تدو دون ونه فمت متع تعو عوه وهن وسر سرح رحو حوه وهن سرح جمي ميل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1987, 'quran:33:50', 'quran', 'quran', '33:50', 50, 1986, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةٗ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا خَالِصَةٗ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا يَكُونَ عَلَيۡكَ حَرَجٞۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'يا ايها النبي انا احللنا لك ازوجك التي اتيت اجورهن وما ملكت يمينك مما افاء الله عليك وبنات عمك وبنات عمتك وبنات خالك وبنات خلتك التي هاجرن معك وامراه مومنه ان وهبت نفسها للنبي ان اراد النبي ان يستنكحها خالصه لك من دون المومنين قد علمنا ما فرضنا عليهم في ازوجهم وما ملكت ايمنهم لكيلا يكون عليك حرج وكان الله غفورا رحيما', 'ي اي نب ان احلل لك ازوجك تي اتيت اجور وم ملكت يمينك مم افء له عليك بن عمك بن عمتك بن خلك بن خلتك تي هجرن معك امر مومن ان هبت نفس نب ان ارد نب ان يستنكح خلص لك من دون مومن قد علم م رض علي في ازوج وم ملكت ايمن لكيل يك عليك حرج كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/33/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1987, 'ي ايه الن لنب نبي ان احل حلل للن لك ازو زوج وجك الت لتي اتي تيت اجو جور وره رهن وم ملك لكت يمي مين ينك مم افء الل لله علي ليك وبن بنت عمك وبن بنت عمت متك وبن بنت خلك وبن بنت خلت لتك الت لتي هجر جرن معك ومر مره موم ومن منه ان وهب هبت نفس فسه للن لنب نبي ان ارد الن لنب نبي ان يست ستن تنك نكح كحه خلص لصه لك من دون الم لمو موم ومن مني نين قد علم لمن م فرض رضن علي ليه يهم في ازو زوج وجه جهم وم ملك لكت ايم يمن منه نهم لكي كيل يكو كون علي ليك حرج وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1988, 'quran:33:51', 'quran', 'quran', '33:51', 51, 1987, 'Al-Ahzab', 'الأحزاب', 'تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ وَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ مَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا', NULL, NULL, 'ترجي من تشاء منهن وتوي اليك من تشاء ومن ابتغيت ممن عزلت فلا جناح عليك ذلك ادني ان تقر اعينهن ولا يحزن ويرضين بما اتيتهن كلهن والله يعلم ما في قلوبكم وكان الله عليما حليما', 'ترج من تشء من تو يك من تشء ومن ابتغيت ممن عزلت فل جنح عليك ذلك ادن ان تقر اعين ول يحزن يرض بم اتيت كل له يعلم م في قلوب كن له عليم حليم', 'quran', NULL, NULL, 'https://quran.com/33/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1988, 'ترج رجي من تشء منه نهن وتو توي الي ليك من تشء ومن ابت بتغ تغي غيت ممن عزل زلت فل جنح علي ليك ذلك ادن دني ان تقر اعي عين ينه نهن ول يحز حزن وير يرض رضي ضين بم اتي تيت يته تهن كله لهن ولل لله يعل علم م في قلو لوب وبك بكم وكن الل لله علي ليم حلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1989, 'quran:33:52', 'quran', 'quran', '33:52', 52, 1988, 'Al-Ahzab', 'الأحزاب', 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ رَّقِيبٗا', NULL, NULL, 'لا يحل لك النساء من بعد ولا ان تبدل بهن من ازوج ولو اعجبك حسنهن الا ما ملكت يمينك وكان الله علي كل شيء رقيبا', 'ل يحل لك نسء من بعد ول ان تبدل بهن من ازوج ولو اعجبك حسن ال م ملكت يمينك كن له عل كل شيء رقيب', 'quran', NULL, NULL, 'https://quran.com/33/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1989, 'ل يحل لك الن لنس نسء من بعد ول ان تبد بدل بهن من ازو زوج ولو اعج عجب جبك حسن سنه نهن ال م ملك لكت يمي مين ينك وكن الل لله علي كل شيء رقي قيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1990, 'quran:33:53', 'quran', 'quran', '33:53', 53, 1989, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا', NULL, NULL, 'يا ايها الذين امنوا لا تدخلوا بيوت النبي الا ان يوذن لكم الي طعام غير نظرين اناه ولكن اذا دعيتم فادخلوا فاذا طعمتم فانتشروا ولا مستنسين لحديث ان ذلكم كان يوذي النبي فيستحي منكم والله لا يستحي من الحق واذا سالتموهن متعا فسلوهن من وراء حجاب ذلكم اطهر لقلوبكم وقلوبهن وما كان لكم ان توذوا رسول الله ولا ان تنكحوا ازوجه من بعده ابدا ان ذلكم كان عند الله عظيما', 'ي اي ذين امن ل تدخل بيوت نب ال ان يوذن لكم ال طعم غير نظر ان لكن اذ دعيتم ادخل اذ طعمتم انتشر ول مستنس لحديث ان ذل كن يوذ نب يستح من له ل يستح من حق اذ سلتمو متع سلو من رء حجب ذل اطهر لقلوب قلوب وم كن لكم ان توذ رسول له ول ان تنكح ازوج من بعد ابد ان ذل كن عند له عظيم', 'quran', NULL, NULL, 'https://quran.com/33/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1990, 'ي ايه الذ لذي ذين امن منو ل تدخ دخل خلو بيو يوت الن لنب نبي ال ان يوذ وذن لكم الي طعم غير نظر ظري رين انه ولك لكن اذ دعي عيت يتم فدخ دخل خلو فذ طعم عمت متم فنت نتش تشر شرو ول مست ستن تنس نسي سين لحد حدي ديث ان ذلك لكم كن يوذ وذي الن لنب نبي فيس يست ستح تحي منك نكم ولل لله ل يست ستح تحي من الح لحق وذ سلت لتم تمو موه وهن متع فسل سلو لوه وهن من ورء حجب ذلك لكم اطه طهر لقل قلو لوب وبك بكم وقل قلو لوب وبه بهن وم كن لكم ان توذ وذو رسو سول الل لله ول ان تنك نكح كحو ازو زوج وجه من بعد عده ابد ان ذلك لكم كن عند الل لله عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1991, 'quran:33:54', 'quran', 'quran', '33:54', 54, 1990, 'Al-Ahzab', 'الأحزاب', 'إِن تُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا', NULL, NULL, 'ان تبدوا شيا او تخفوه فان الله كان بكل شيء عليما', 'ان تبد شي او تخفو فن له كن بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/33/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1991, 'ان تبد بدو شي او تخف خفو فوه فن الل لله كن بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1992, 'quran:33:55', 'quran', 'quran', '33:55', 55, 1991, 'Al-Ahzab', 'الأحزاب', 'لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا', NULL, NULL, 'لا جناح عليهن في ابايهن ولا ابنايهن ولا اخونهن ولا ابناء اخونهن ولا ابناء اخوتهن ولا نسايهن ولا ما ملكت ايمنهن واتقين الله ان الله كان علي كل شيء شهيدا', 'ل جنح علي في ابي ول ابني ول اخون ول ابنء اخون ول ابنء اخوت ول نسي ول م ملكت ايمن اتق له ان له كن عل كل شيء شهيد', 'quran', NULL, NULL, 'https://quran.com/33/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1992, 'ل جنح علي ليه يهن في ابي بيه يهن ول ابن بني نيه يهن ول اخو خون ونه نهن ول ابن بنء اخو خون ونه نهن ول ابن بنء اخو خوت وته تهن ول نسي سيه يهن ول م ملك لكت ايم يمن منه نهن وتق تقي قين الل لله ان الل لله كن علي كل شيء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1993, 'quran:33:56', 'quran', 'quran', '33:56', 56, 1992, 'Al-Ahzab', 'الأحزاب', 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا', NULL, NULL, 'ان الله ومليكته يصلون علي النبي يا ايها الذين امنوا صلوا عليه وسلموا تسليما', 'ان له مليكت يصل عل نب ي اي ذين امن صل عل سلم تسليم', 'quran', NULL, NULL, 'https://quran.com/33/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1993, 'ان الل لله ومل ملي ليك يكت كته يصل صلو لون علي الن لنب نبي ي ايه الذ لذي ذين امن منو صلو علي ليه وسل سلم لمو تسل سلي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1994, 'quran:33:57', 'quran', 'quran', '33:57', 57, 1993, 'Al-Ahzab', 'الأحزاب', 'إِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا', NULL, NULL, 'ان الذين يوذون الله ورسوله لعنهم الله في الدنيا والاخره واعد لهم عذابا مهينا', 'ان ذين يوذ له رسول لعن له في دني اخر اعد لهم عذب مهي', 'quran', NULL, NULL, 'https://quran.com/33/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1994, 'ان الذ لذي ذين يوذ وذو ذون الل لله ورس رسو سول وله لعن عنه نهم الل لله في الد لدن دني ولخ لخر خره وعد لهم عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1995, 'quran:33:58', 'quran', 'quran', '33:58', 58, 1994, 'Al-Ahzab', 'الأحزاب', 'وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا', NULL, NULL, 'والذين يوذون المومنين والمومنت بغير ما اكتسبوا فقد احتملوا بهتنا واثما مبينا', 'ذين يوذ مومن مومنت بغير م اكتسب فقد احتمل بهت اثم مبي', 'quran', NULL, NULL, 'https://quran.com/33/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1995, 'ولذ لذي ذين يوذ وذو ذون الم لمو موم ومن مني نين ولم لمو موم ومن منت بغي غير م اكت كتس تسب سبو فقد احت حتم تمل ملو بهت هتن وثم مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1996, 'quran:33:59', 'quran', 'quran', '33:59', 59, 1995, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', NULL, NULL, 'يا ايها النبي قل لازوجك وبناتك ونساء المومنين يدنين عليهن من جلبيبهن ذلك ادني ان يعرفن فلا يوذين وكان الله غفورا رحيما', 'ي اي نب قل لزوجك بنتك نسء مومن يدن علي من جلبيب ذلك ادن ان يعرفن فل يوذ كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/33/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1996, 'ي ايه الن لنب نبي قل لزو زوج وجك وبن بنت نتك ونس نسء الم لمو موم ومن مني نين يدن دني نين علي ليه يهن من جلب لبي بيب يبه بهن ذلك ادن دني ان يعر عرف رفن فل يوذ وذي ذين وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1997, 'quran:33:60', 'quran', 'quran', '33:60', 60, 1996, 'Al-Ahzab', 'الأحزاب', 'لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا', NULL, NULL, 'لين لم ينته المنفقون والذين في قلوبهم مرض والمرجفون في المدينه لنغرينك بهم ثم لا يجاورونك فيها الا قليلا', 'لين لم ينت منفق ذين في قلوب مرض مرجف في مدين لنغرينك بهم ثم ل يجورونك يه ال قليل', 'quran', NULL, NULL, 'https://quran.com/33/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1997, 'لين لم ينت نته الم لمن منف نفق فقو قون ولذ لذي ذين في قلو لوب وبه بهم مرض ولم لمر مرج رجف جفو فون في الم لمد مدي دين ينه لنغ نغر غري رين ينك بهم ثم ل يجو جور ورو رون ونك فيه ال قلي ليل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1998, 'quran:33:61', 'quran', 'quran', '33:61', 61, 1997, 'Al-Ahzab', 'الأحزاب', 'مَّلۡعُونِينَۖ أَيۡنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقۡتِيلٗا', NULL, NULL, 'ملعونين اينما ثقفوا اخذوا وقتلوا تقتيلا', 'ملعون اينم ثقف اخذ قتل تقتيل', 'quran', NULL, NULL, 'https://quran.com/33/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1998, 'ملع لعو عون وني نين اين ينم ثقف قفو اخذ خذو وقت قتل تلو تقت قتي تيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (1999, 'quran:33:62', 'quran', 'quran', '33:62', 62, 1998, 'Al-Ahzab', 'الأحزاب', 'سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا', NULL, NULL, 'سنه الله في الذين خلوا من قبل ولن تجد لسنه الله تبديلا', 'سن له في ذين خل من قبل ولن تجد لسن له تبديل', 'quran', NULL, NULL, 'https://quran.com/33/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (1999, 'سنه الل لله في الذ لذي ذين خلو من قبل ولن تجد لسن سنه الل لله تبد بدي ديل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2000, 'quran:33:63', 'quran', 'quran', '33:63', 63, 1999, 'Al-Ahzab', 'الأحزاب', 'يَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', NULL, NULL, 'يسلك الناس عن الساعه قل انما علمها عند الله وما يدريك لعل الساعه تكون قريبا', 'يسلك نس عن سع قل انم علم عند له وم يدريك لعل سع تك قريب', 'quran', NULL, NULL, 'https://quran.com/33/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2000, 'يسل سلك الن لنس عن الس لسع سعه قل انم علم لمه عند الل لله وم يدر دري ريك لعل الس لسع سعه تكو كون قري ريب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2001, 'quran:33:64', 'quran', 'quran', '33:64', 64, 2000, 'Al-Ahzab', 'الأحزاب', 'إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا', NULL, NULL, 'ان الله لعن الكفرين واعد لهم سعيرا', 'ان له لعن كفر اعد لهم سعير', 'quran', NULL, NULL, 'https://quran.com/33/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2001, 'ان الل لله لعن الك لكف كفر فري رين وعد لهم سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2002, 'quran:33:65', 'quran', 'quran', '33:65', 65, 2001, 'Al-Ahzab', 'الأحزاب', 'خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا', NULL, NULL, 'خلدين فيها ابدا لا يجدون وليا ولا نصيرا', 'خلد يه ابد ل يجد لي ول نصير', 'quran', NULL, NULL, 'https://quran.com/33/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2002, 'خلد لدي دين فيه ابد ل يجد جدو دون ولي ول نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2003, 'quran:33:66', 'quran', 'quran', '33:66', 66, 2002, 'Al-Ahzab', 'الأحزاب', 'يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠', NULL, NULL, 'يوم تقلب وجوههم في النار يقولون يا ليتنا اطعنا الله واطعنا الرسولا', 'يوم تقلب جوه في نر يقول ي ليت اطع له اطع رسول', 'quran', NULL, NULL, 'https://quran.com/33/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2003, 'يوم تقل قلب وجو جوه وهه ههم في الن لنر يقو قول ولو لون ي ليت يتن اطع طعن الل لله وطع طعن الر لرس رسو سول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2004, 'quran:33:67', 'quran', 'quran', '33:67', 67, 2003, 'Al-Ahzab', 'الأحزاب', 'وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعۡنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', NULL, NULL, 'وقالوا ربنا انا اطعنا سادتنا وكبراءنا فاضلونا السبيلا', 'قل رب ان اطع سدت كبرء اضلو سبيل', 'quran', NULL, NULL, 'https://quran.com/33/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2004, 'وقل قلو ربن ان اطع طعن سدت دتن وكب كبر برء رءن فضل ضلو لون الس لسب سبي بيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2005, 'quran:33:68', 'quran', 'quran', '33:68', 68, 2004, 'Al-Ahzab', 'الأحزاب', 'رَبَّنَآ ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنٗا كَبِيرٗا', NULL, NULL, 'ربنا اتهم ضعفين من العذاب والعنهم لعنا كبيرا', 'رب ات ضعف من عذب عن لع كبير', 'quran', NULL, NULL, 'https://quran.com/33/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2005, 'ربن اته تهم ضعف عفي فين من الع لعذ عذب ولع لعن عنه نهم لعن كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2006, 'quran:33:69', 'quran', 'quran', '33:69', 69, 2005, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ ءَاذَوۡاْ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا', NULL, NULL, 'يا ايها الذين امنوا لا تكونوا كالذين اذوا موسي فبراه الله مما قالوا وكان عند الله وجيها', 'ي اي ذين امن ل تكون ذين اذ موس بر له مم قل كن عند له جي', 'quran', NULL, NULL, 'https://quran.com/33/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2006, 'ي ايه الذ لذي ذين امن منو ل تكو كون ونو كلذ لذي ذين اذو موس وسي فبر بره الل لله مم قلو وكن عند الل لله وجي جيه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2007, 'quran:33:70', 'quran', 'quran', '33:70', 70, 2006, 'Al-Ahzab', 'الأحزاب', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا', NULL, NULL, 'يا ايها الذين امنوا اتقوا الله وقولوا قولا سديدا', 'ي اي ذين امن اتق له قول قول سديد', 'quran', NULL, NULL, 'https://quran.com/33/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2007, 'ي ايه الذ لذي ذين امن منو اتق تقو الل لله وقو قول ولو قول سدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2008, 'quran:33:71', 'quran', 'quran', '33:71', 71, 2007, 'Al-Ahzab', 'الأحزاب', 'يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا', NULL, NULL, 'يصلح لكم اعملكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما', 'يصلح لكم اعمل يغفر لكم ذنوب ومن يطع له رسول فقد فز وز عظيم', 'quran', NULL, NULL, 'https://quran.com/33/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2008, 'يصل صلح لكم اعم عمل ملك لكم ويغ يغف غفر لكم ذنو نوب وبك بكم ومن يطع الل لله ورس رسو سول وله فقد فز فوز عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2009, 'quran:33:72', 'quran', 'quran', '33:72', 72, 2008, 'Al-Ahzab', 'الأحزاب', 'إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا', NULL, NULL, 'انا عرضنا الامانه علي السموت والارض والجبال فابين ان يحملنها واشفقن منها وحملها الانسن انه كان ظلوما جهولا', 'ان عرض امن عل سموت ارض جبل اب ان يحملن اشفقن من حمل انسن ان كن ظلوم جهول', 'quran', NULL, NULL, 'https://quran.com/33/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2009, 'ان عرض رضن الم لمن منه علي الس لسم سمو موت ولر لرض ولج لجب جبل فبي بين ان يحم حمل ملن لنه وشف شفق فقن منه وحم حمل مله الن لنس نسن انه كن ظلو لوم جهو هول');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2010, 'quran:33:73', 'quran', 'quran', '33:73', 73, 2009, 'Al-Ahzab', 'الأحزاب', 'لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا', NULL, NULL, 'ليعذب الله المنفقين والمنفقت والمشركين والمشركت ويتوب الله علي المومنين والمومنت وكان الله غفورا رحيما', 'ليعذب له منفق منفقت مشرك مشركت يتوب له عل مومن مومنت كن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/33/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2010, 'ليع يعذ عذب الل لله الم لمن منف نفق فقي قين ولم لمن منف نفق فقت ولم لمش مشر شرك ركي كين ولم لمش مشر شرك ركت ويت يتو توب الل لله علي الم لمو موم ومن مني نين ولم لمو موم ومن منت وكن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2011, 'quran:35:1', 'quran', 'quran', '35:1', 1, 2010, 'Fatir', 'فاطر', 'ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'الحمد لله فاطر السموت والارض جاعل المليكه رسلا اولي اجنحه مثني وثلث وربع يزيد في الخلق ما يشاء ان الله علي كل شيء قدير', 'حمد لل اطر سموت ارض جعل مليك رسل اول اجنح مثن ثلث ربع يزيد في خلق م يشء ان له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/35/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2011, 'الح لحم حمد لله فطر الس لسم سمو موت ولر لرض جعل الم لمل ملي ليك يكه رسل اول ولي اجن جنح نحه مثن ثني وثل ثلث ورب ربع يزي زيد في الخ لخل خلق م يشء ان الل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2012, 'quran:35:2', 'quran', 'quran', '35:2', 2, 2011, 'Fatir', 'فاطر', 'مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'ما يفتح الله للناس من رحمه فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم', 'م يفتح له نس من رحم فل ممسك له وم يمسك فل مرسل له من بعد وهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/35/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2012, 'م يفت فتح الل لله للن لنس من رحم حمه فل ممس مسك له وم يمس مسك فل مرس رسل له من بعد عده وهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2013, 'quran:35:3', 'quran', 'quran', '35:3', 3, 2012, 'Fatir', 'فاطر', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ', NULL, NULL, 'يا ايها الناس اذكروا نعمت الله عليكم هل من خلق غير الله يرزقكم من السماء والارض لا اله الا هو فاني توفكون', 'ي اي نس اذكر نعمت له علي هل من خلق غير له يرزق من سمء ارض ل ال ال هو ان توفك', 'quran', NULL, NULL, 'https://quran.com/35/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2013, 'ي ايه الن لنس اذك ذكر كرو نعم عمت الل لله علي ليك يكم هل من خلق غير الل لله يرز رزق زقك قكم من الس لسم سمء ولر لرض ل اله ال هو فني توف وفك فكو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2014, 'quran:35:4', 'quran', 'quran', '35:4', 4, 2013, 'Fatir', 'فاطر', 'وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', NULL, NULL, 'وان يكذبوك فقد كذبت رسل من قبلك والي الله ترجع الامور', 'ون يكذبوك فقد كذبت رسل من قبلك ول له ترجع امور', 'quran', NULL, NULL, 'https://quran.com/35/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2014, 'ون يكذ كذب ذبو بوك فقد كذب ذبت رسل من قبل بلك ولي الل لله ترج رجع الم لمو مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2015, 'quran:35:5', 'quran', 'quran', '35:5', 5, 2014, 'Fatir', 'فاطر', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ', NULL, NULL, 'يا ايها الناس ان وعد الله حق فلا تغرنكم الحياه الدنيا ولا يغرنكم بالله الغرور', 'ي اي نس ان وعد له حق فل تغرن حي دني ول يغرن له غرور', 'quran', NULL, NULL, 'https://quran.com/35/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2015, 'ي ايه الن لنس ان وعد الل لله حق فل تغر غرن رنك نكم الح لحي حيه الد لدن دني ول يغر غرن رنك نكم بلل لله الغ لغر غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2016, 'quran:35:6', 'quran', 'quran', '35:6', 6, 2015, 'Fatir', 'فاطر', 'إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ', NULL, NULL, 'ان الشيطن لكم عدو فاتخذوه عدوا انما يدعوا حزبه ليكونوا من اصحب السعير', 'ان شيطن لكم عدو اتخذو عد انم يدع حزب ليكون من اصحب سعير', 'quran', NULL, NULL, 'https://quran.com/35/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2016, 'ان الش لشي شيط يطن لكم عدو فتخ تخذ خذو ذوه عدو انم يدع دعو حزب زبه ليك يكو كون ونو من اصح صحب الس لسع سعي عير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2017, 'quran:35:7', 'quran', 'quran', '35:7', 7, 2016, 'Fatir', 'فاطر', 'ٱلَّذِينَ كَفَرُواْ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٌ', NULL, NULL, 'الذين كفروا لهم عذاب شديد والذين امنوا وعملوا الصلحت لهم مغفره واجر كبير', 'ذين كفر لهم عذب شديد ذين امن عمل صلحت لهم مغفر اجر كبير', 'quran', NULL, NULL, 'https://quran.com/35/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2017, 'الذ لذي ذين كفر فرو لهم عذب شدي ديد ولذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت لهم مغف غفر فره وجر كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2018, 'quran:35:8', 'quran', 'quran', '35:8', 8, 2017, 'Fatir', 'فاطر', 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ', NULL, NULL, 'افمن زين له سوء عمله فراه حسنا فان الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرت ان الله عليم بما يصنعون', 'افمن زين له سوء عمل ر حس فن له يضل من يشء يهد من يشء فل تذهب نفسك علي حسرت ان له عليم بم يصنع', 'quran', NULL, NULL, 'https://quran.com/35/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2018, 'افم فمن زين له سوء عمل مله فره حسن فن الل لله يضل من يشء ويه يهد هدي من يشء فل تذه ذهب نفس فسك علي ليه يهم حسر سرت ان الل لله علي ليم بم يصن صنع نعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2019, 'quran:35:9', 'quran', 'quran', '35:9', 9, 2018, 'Fatir', 'فاطر', 'وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَسُقۡنَٰهُ إِلَىٰ بَلَدٖ مَّيِّتٖ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ', NULL, NULL, 'والله الذي ارسل الريح فتثير سحابا فسقنه الي بلد ميت فاحيينا به الارض بعد موتها كذلك النشور', 'له ذي ارسل ريح تثير سحب سقن ال بلد ميت احيي به ارض بعد موت كذلك نشور', 'quran', NULL, NULL, 'https://quran.com/35/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2019, 'ولل لله الذ لذي ارس رسل الر لري ريح فتث تثي ثير سحب فسق سقن قنه الي بلد ميت فحي حيي يين به الر لرض بعد موت وته كذل ذلك الن لنش نشو شور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2020, 'quran:35:10', 'quran', 'quran', '35:10', 10, 2019, 'Fatir', 'فاطر', 'مَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ إِلَيۡهِ يَصۡعَدُ ٱلۡكَلِمُ ٱلطَّيِّبُ وَٱلۡعَمَلُ ٱلصَّٰلِحُ يَرۡفَعُهُۥۚ وَٱلَّذِينَ يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَمَكۡرُ أُوْلَٰٓئِكَ هُوَ يَبُورُ', NULL, NULL, 'من كان يريد العزه فلله العزه جميعا اليه يصعد الكلم الطيب والعمل الصلح يرفعه والذين يمكرون السيات لهم عذاب شديد ومكر اوليك هو يبور', 'من كن يريد عز لل عز جميع يه يصعد كلم طيب عمل صلح يرفع ذين يمكر سي لهم عذب شديد مكر اوليك هو يبور', 'quran', NULL, NULL, 'https://quran.com/35/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2020, 'من كن يري ريد الع لعز عزه فلل لله الع لعز عزه جمي ميع الي ليه يصع صعد الك لكل كلم الط لطي طيب ولع لعم عمل الص لصل صلح يرف رفع فعه ولذ لذي ذين يمك مكر كرو رون الس لسي سيت لهم عذب شدي ديد ومك مكر اول ولي ليك هو يبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2021, 'quran:35:11', 'quran', 'quran', '35:11', 11, 2020, 'Fatir', 'فاطر', 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجٗاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٖ وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ', NULL, NULL, 'والله خلقكم من تراب ثم من نطفه ثم جعلكم ازوجا وما تحمل من انثي ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتب ان ذلك علي الله يسير', 'له خلق من ترب ثم من نطف ثم جعل ازوج وم تحمل من انث ول تضع ال بعلم وم يعمر من معمر ول ينقص من عمر ال في كتب ان ذلك عل له يسير', 'quran', NULL, NULL, 'https://quran.com/35/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2021, 'ولل لله خلق لقك قكم من ترب ثم من نطف طفه ثم جعل علك لكم ازو زوج وم تحم حمل من انث نثي ول تضع ال بعل علم لمه وم يعم عمر من معم عمر ول ينق نقص من عمر مره ال في كتب ان ذلك علي الل لله يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2022, 'quran:35:12', 'quran', 'quran', '35:12', 12, 2021, 'Fatir', 'فاطر', 'وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبٞ فُرَاتٞ سَآئِغٞ شَرَابُهُۥ وَهَٰذَا مِلۡحٌ أُجَاجٞۖ وَمِن كُلّٖ تَأۡكُلُونَ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُونَ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ', NULL, NULL, 'وما يستوي البحران هذا عذب فرات سايغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حليه تلبسونها وتري الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون', 'وم يستو بحر هذ عذب رت سيغ شرب هذ ملح اجج ومن كل تكل لحم طري تستخرج حل تلبسون تر فلك في موخر لتبتغ من ضل لعل تشكر', 'quran', NULL, NULL, 'https://quran.com/35/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2022, 'وم يست ستو توي الب لبح بحر حرن هذ عذب فرت سيغ شرب ربه وهذ ملح اجج ومن كل تكل كلو لون لحم طري وتس تست ستخ تخر خرج رجو جون حلي ليه تلب لبس بسو سون ونه وتر تري الف لفل فلك فيه موخ وخر لتب تبت بتغ تغو من فضل ضله ولع لعل علك لكم تشك شكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2023, 'quran:35:13', 'quran', 'quran', '35:13', 13, 2022, 'Fatir', 'فاطر', 'يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ', NULL, NULL, 'يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري لاجل مسمي ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير', 'يولج يل في نهر يولج نهر في يل سخر شمس قمر كل يجر لجل مسم ذل له رب له ملك ذين تدع من دون م يملك من قطمير', 'quran', NULL, NULL, 'https://quran.com/35/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2023, 'يول ولج الي ليل في الن لنه نهر ويو يول ولج الن لنه نهر في الي ليل وسخ سخر الش لشم شمس ولق لقم قمر كل يجر جري لجل مسم سمي ذلك لكم الل لله ربك بكم له الم لمل ملك ولذ لذي ذين تدع دعو عون من دون ونه م يمل ملك لكو كون من قطم طمي مير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2024, 'quran:35:14', 'quran', 'quran', '35:14', 14, 2023, 'Fatir', 'فاطر', 'إِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ', NULL, NULL, 'ان تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيمه يكفرون بشرككم ولا ينبيك مثل خبير', 'ان تدعو ل يسمع دعء ولو سمع م استجب لكم يوم قيم يكفر بشرك ول ينبيك مثل خبير', 'quran', NULL, NULL, 'https://quran.com/35/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2024, 'ان تدع دعو عوه وهم ل يسم سمع معو دعء عءك ءكم ولو سمع معو م است ستج تجب جبو لكم ويو يوم الق لقي قيم يمه يكف كفر فرو رون بشر شرك ركك ككم ول ينب نبي بيك مثل خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2025, 'quran:35:15', 'quran', 'quran', '35:15', 15, 2024, 'Fatir', 'فاطر', 'يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ', NULL, NULL, 'يا ايها الناس انتم الفقراء الي الله والله هو الغني الحميد', 'ي اي نس انتم فقرء ال له له هو غن حميد', 'quran', NULL, NULL, 'https://quran.com/35/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2025, 'ي ايه الن لنس انت نتم الف لفق فقر قرء الي الل لله ولل لله هو الغ لغن غني الح لحم حمي ميد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2026, 'quran:35:16', 'quran', 'quran', '35:16', 16, 2025, 'Fatir', 'فاطر', 'إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ', NULL, NULL, 'ان يشا يذهبكم ويات بخلق جديد', 'ان يش يذهب يت بخلق جديد', 'quran', NULL, NULL, 'https://quran.com/35/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2026, 'ان يش يذه ذهب هبك بكم ويت بخل خلق جدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2027, 'quran:35:17', 'quran', 'quran', '35:17', 17, 2026, 'Fatir', 'فاطر', 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ', NULL, NULL, 'وما ذلك علي الله بعزيز', 'وم ذلك عل له بعزيز', 'quran', NULL, NULL, 'https://quran.com/35/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2027, 'وم ذلك علي الل لله بعز عزي زيز');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2028, 'quran:35:18', 'quran', 'quran', '35:18', 18, 2027, 'Fatir', 'فاطر', 'وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ', NULL, NULL, 'ولا تزر وازره وزر اخري وان تدع مثقله الي حملها لا يحمل منه شيء ولو كان ذا قربي انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلاه ومن تزكي فانما يتزكي لنفسه والي الله المصير', 'ول تزر ازر وزر اخر ون تدع مثقل ال حمل ل يحمل من شيء ولو كن ذ قرب انم تنذر ذين يخش رب غيب اقم صل ومن تزك انم يتزك لنفس ول له مصير', 'quran', NULL, NULL, 'https://quran.com/35/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2028, 'ول تزر وزر زره وزر اخر خري ون تدع مثق ثقل قله الي حمل مله ل يحم حمل منه شيء ولو كن ذ قرب ربي انم تنذ نذر الذ لذي ذين يخش خشو شون ربه بهم بلغ لغي غيب وقم قمو الص لصل صله ومن تزك زكي فنم يتز تزك زكي لنف نفس فسه ولي الل لله الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2029, 'quran:35:19', 'quran', 'quran', '35:19', 19, 2028, 'Fatir', 'فاطر', 'وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ', NULL, NULL, 'وما يستوي الاعمي والبصير', 'وم يستو اعم بصير', 'quran', NULL, NULL, 'https://quran.com/35/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2029, 'وم يست ستو توي الع لعم عمي ولب لبص بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2030, 'quran:35:20', 'quran', 'quran', '35:20', 20, 2029, 'Fatir', 'فاطر', 'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ', NULL, NULL, 'ولا الظلمت ولا النور', 'ول ظلمت ول نور', 'quran', NULL, NULL, 'https://quran.com/35/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2030, 'ول الظ لظل ظلم لمت ول الن لنو نور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2031, 'quran:35:21', 'quran', 'quran', '35:21', 21, 2030, 'Fatir', 'فاطر', 'وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ', NULL, NULL, 'ولا الظل ولا الحرور', 'ول ظل ول حرور', 'quran', NULL, NULL, 'https://quran.com/35/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2031, 'ول الظ لظل ول الح لحر حرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2032, 'quran:35:22', 'quran', 'quran', '35:22', 22, 2031, 'Fatir', 'فاطر', 'وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ', NULL, NULL, 'وما يستوي الاحياء ولا الاموت ان الله يسمع من يشاء وما انت بمسمع من في القبور', 'وم يستو احيء ول اموت ان له يسمع من يشء وم انت بمسمع من في قبور', 'quran', NULL, NULL, 'https://quran.com/35/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2032, 'وم يست ستو توي الح لحي حيء ول الم لمو موت ان الل لله يسم سمع من يشء وم انت بمس مسم سمع من في الق لقب قبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2033, 'quran:35:23', 'quran', 'quran', '35:23', 23, 2032, 'Fatir', 'فاطر', 'إِنۡ أَنتَ إِلَّا نَذِيرٌ', NULL, NULL, 'ان انت الا نذير', 'ان انت ال نذير', 'quran', NULL, NULL, 'https://quran.com/35/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2033, 'ان انت ال نذي ذير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2034, 'quran:35:24', 'quran', 'quran', '35:24', 24, 2033, 'Fatir', 'فاطر', 'إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ', NULL, NULL, 'انا ارسلنك بالحق بشيرا ونذيرا وان من امه الا خلا فيها نذير', 'ان ارسلنك حق بشير نذير ون من ام ال خل يه نذير', 'quran', NULL, NULL, 'https://quran.com/35/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2034, 'ان ارس رسل سلن لنك بلح لحق بشي شير ونذ نذي ذير ون من امه ال خل فيه نذي ذير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2035, 'quran:35:25', 'quran', 'quran', '35:25', 25, 2034, 'Fatir', 'فاطر', 'وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ ٱلۡمُنِيرِ', NULL, NULL, 'وان يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينت وبالزبر وبالكتب المنير', 'ون يكذبوك فقد كذب ذين من قبل جءت رسل بينت زبر كتب منير', 'quran', NULL, NULL, 'https://quran.com/35/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2035, 'ون يكذ كذب ذبو بوك فقد كذب الذ لذي ذين من قبل بله لهم جءت ءته تهم رسل سله لهم بلب لبي بين ينت وبل بلز لزب زبر وبل بلك لكت كتب الم لمن مني نير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2036, 'quran:35:26', 'quran', 'quran', '35:26', 26, 2035, 'Fatir', 'فاطر', 'ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ فَكَيۡفَ كَانَ نَكِيرِ', NULL, NULL, 'ثم اخذت الذين كفروا فكيف كان نكير', 'ثم اخذت ذين كفر كيف كن نكير', 'quran', NULL, NULL, 'https://quran.com/35/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2036, 'ثم اخذ خذت الذ لذي ذين كفر فرو فكي كيف كن نكي كير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2037, 'quran:35:27', 'quran', 'quran', '35:27', 27, 2036, 'Fatir', 'فاطر', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ', NULL, NULL, 'الم تر ان الله انزل من السماء ماء فاخرجنا به ثمرت مختلفا الونها ومن الجبال جدد بيض وحمر مختلف الونها وغرابيب سود', 'الم تر ان له انزل من سمء مء اخرج به ثمرت مختلف ون ومن جبل جدد بيض حمر مختلف ون غربيب سود', 'quran', NULL, NULL, 'https://quran.com/35/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2037, 'الم تر ان الل لله انز نزل من الس لسم سمء مء فخر خرج رجن به ثمر مرت مخت ختل تلف الو لون ونه ومن الج لجب جبل جدد بيض وحم حمر مخت ختل تلف الو لون ونه وغر غرب ربي بيب سود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2038, 'quran:35:28', 'quran', 'quran', '35:28', 28, 2037, 'Fatir', 'فاطر', 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', NULL, NULL, 'ومن الناس والدواب والانعم مختلف الونه كذلك انما يخشي الله من عباده العلموا ان الله عزيز غفور', 'ومن نس دوب انعم مختلف ون كذلك انم يخش له من عبد علم ان له عزيز غفور', 'quran', NULL, NULL, 'https://quran.com/35/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2038, 'ومن الن لنس ولد لدو دوب ولن لنع نعم مخت ختل تلف الو لون ونه كذل ذلك انم يخش خشي الل لله من عبد بده الع لعل علم لمو ان الل لله عزي زيز غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2039, 'quran:35:29', 'quran', 'quran', '35:29', 29, 2038, 'Fatir', 'فاطر', 'إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ', NULL, NULL, 'ان الذين يتلون كتب الله واقاموا الصلاه وانفقوا مما رزقنهم سرا وعلانيه يرجون تجره لن تبور', 'ان ذين يتل كتب له اقم صل انفق مم رزقن سر علن يرج تجر لن تبور', 'quran', NULL, NULL, 'https://quran.com/35/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2039, 'ان الذ لذي ذين يتل تلو لون كتب الل لله وقم قمو الص لصل صله ونف نفق فقو مم رزق زقن قنه نهم سر وعل علن لني نيه يرج رجو جون تجر جره لن تبو بور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2040, 'quran:35:30', 'quran', 'quran', '35:30', 30, 2039, 'Fatir', 'فاطر', 'لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ', NULL, NULL, 'ليوفيهم اجورهم ويزيدهم من فضله انه غفور شكور', 'ليوفي اجور يزيد من ضل ان غفور شكور', 'quran', NULL, NULL, 'https://quran.com/35/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2040, 'ليو يوف وفي فيه يهم اجو جور وره رهم ويز يزي زيد يده دهم من فضل ضله انه غفو فور شكو كور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2041, 'quran:35:31', 'quran', 'quran', '35:31', 31, 2040, 'Fatir', 'فاطر', 'وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرٞ', NULL, NULL, 'والذي اوحينا اليك من الكتب هو الحق مصدقا لما بين يديه ان الله بعباده لخبير بصير', 'ذي اوحي يك من كتب هو حق مصدق لم بين يد ان له بعبد لخبير بصير', 'quran', NULL, NULL, 'https://quran.com/35/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2041, 'ولذ لذي اوح وحي حين الي ليك من الك لكت كتب هو الح لحق مصد صدق لم بين يدي ديه ان الل لله بعب عبد بده لخب خبي بير بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2042, 'quran:35:32', 'quran', 'quran', '35:32', 32, 2041, 'Fatir', 'فاطر', 'ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ', NULL, NULL, 'ثم اورثنا الكتب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرت باذن الله ذلك هو الفضل الكبير', 'ثم اورث كتب ذين اصطفي من عبد من ظلم لنفس من مقتصد من سبق خيرت بذن له ذلك هو فضل كبير', 'quran', NULL, NULL, 'https://quran.com/35/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2042, 'ثم اور ورث رثن الك لكت كتب الذ لذي ذين اصط صطف طفي فين من عبد بدن فمن منه نهم ظلم لنف نفس فسه ومن منه نهم مقت قتص تصد ومن منه نهم سبق بلخ لخي خير يرت بذن الل لله ذلك هو الف لفض فضل الك لكب كبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2043, 'quran:35:33', 'quran', 'quran', '35:33', 33, 2042, 'Fatir', 'فاطر', 'جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ', NULL, NULL, 'جنت عدن يدخلونها يحلون فيها من اساور من ذهب ولولوا ولباسهم فيها حرير', 'جنت عدن يدخلون يحل يه من اسور من ذهب لول لبس يه حرير', 'quran', NULL, NULL, 'https://quran.com/35/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2043, 'جنت عدن يدخ دخل خلو لون ونه يحل حلو لون فيه من اسو سور من ذهب ولو لول ولو ولب لبس بسه سهم فيه حري رير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2044, 'quran:35:34', 'quran', 'quran', '35:34', 34, 2043, 'Fatir', 'فاطر', 'وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ', NULL, NULL, 'وقالوا الحمد لله الذي اذهب عنا الحزن ان ربنا لغفور شكور', 'قل حمد لل ذي اذهب عن حزن ان رب لغفور شكور', 'quran', NULL, NULL, 'https://quran.com/35/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2044, 'وقل قلو الح لحم حمد لله الذ لذي اذه ذهب عن الح لحز حزن ان ربن لغف غفو فور شكو كور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2045, 'quran:35:35', 'quran', 'quran', '35:35', 35, 2044, 'Fatir', 'فاطر', 'ٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ', NULL, NULL, 'الذي احلنا دار المقامه من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب', 'ذي احل در مقم من ضل ل يمس يه نصب ول يمس يه لغوب', 'quran', NULL, NULL, 'https://quran.com/35/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2045, 'الذ لذي احل حلن در الم لمق مقم قمه من فضل ضله ل يمس مسن فيه نصب ول يمس مسن فيه لغو غوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2046, 'quran:35:36', 'quran', 'quran', '35:36', 36, 2045, 'Fatir', 'فاطر', 'وَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ', NULL, NULL, 'والذين كفروا لهم نار جهنم لا يقضي عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور', 'ذين كفر لهم نر جهنم ل يقض علي يموت ول يخفف عن من عذب كذلك نجز كل كفور', 'quran', NULL, NULL, 'https://quran.com/35/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2046, 'ولذ لذي ذين كفر فرو لهم نر جهن هنم ل يقض قضي علي ليه يهم فيم يمو موت وتو ول يخف خفف عنه نهم من عذب ذبه كذل ذلك نجز جزي كل كفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2047, 'quran:35:37', 'quran', 'quran', '35:37', 37, 2046, 'Fatir', 'فاطر', 'وَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ فَذُوقُواْ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', NULL, NULL, 'وهم يصطرخون فيها ربنا اخرجنا نعمل صلحا غير الذي كنا نعمل اولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير فذوقوا فما للظلمين من نصير', 'وهم يصطرخ يه رب اخرج نعمل صلح غير ذي كن نعمل اولم نعمر م يتذكر في من تذكر جء نذير ذوق فم ظلم من نصير', 'quran', NULL, NULL, 'https://quran.com/35/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2047, 'وهم يصط صطر طرخ رخو خون فيه ربن اخر خرج رجن نعم عمل صلح غير الذ لذي كن نعم عمل اول ولم نعم عمر مرك ركم م يتذ تذك ذكر فيه من تذك ذكر وجء جءك ءكم الن لنذ نذي ذير فذو ذوق وقو فم للظ لظل ظلم لمي مين من نصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2048, 'quran:35:38', 'quran', 'quran', '35:38', 38, 2047, 'Fatir', 'فاطر', 'إِنَّ ٱللَّهَ عَٰلِمُ غَيۡبِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'ان الله علم غيب السموت والارض انه عليم بذات الصدور', 'ان له علم غيب سموت ارض ان عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/35/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2048, 'ان الل لله علم غيب الس لسم سمو موت ولر لرض انه علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2049, 'quran:35:39', 'quran', 'quran', '35:39', 39, 2048, 'Fatir', 'فاطر', 'هُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ إِلَّا خَسَارٗا', NULL, NULL, 'هو الذي جعلكم خليف في الارض فمن كفر فعليه كفره ولا يزيد الكفرين كفرهم عند ربهم الا مقتا ولا يزيد الكفرين كفرهم الا خسارا', 'هو ذي جعل خليف في ارض فمن كفر عل كفر ول يزيد كفر كفر عند رب ال مقت ول يزيد كفر كفر ال خسر', 'quran', NULL, NULL, 'https://quran.com/35/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2049, 'هو الذ لذي جعل علك لكم خلي ليف في الر لرض فمن كفر فعل علي ليه كفر فره ول يزي زيد الك لكف كفر فري رين كفر فره رهم عند ربه بهم ال مقت ول يزي زيد الك لكف كفر فري رين كفر فره رهم ال خسر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2050, 'quran:35:40', 'quran', 'quran', '35:40', 40, 2049, 'Fatir', 'فاطر', 'قُلۡ أَرَءَيۡتُمۡ شُرَكَآءَكُمُ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا فَهُمۡ عَلَىٰ بَيِّنَتٖ مِّنۡهُۚ بَلۡ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا', NULL, NULL, 'قل ارءيتم شركاءكم الذين تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموت ام اتينهم كتبا فهم علي بينت منه بل ان يعد الظلمون بعضهم بعضا الا غرورا', 'قل ارءيتم شركء ذين تدع من دون له ارون مذ خلق من ارض ام لهم شرك في سموت ام اتين كتب فهم عل بينت من بل ان يعد ظلم بعض بعض ال غرور', 'quran', NULL, NULL, 'https://quran.com/35/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2050, 'قل ارء رءي ءيت يتم شرك ركء كءك ءكم الذ لذي ذين تدع دعو عون من دون الل لله ارو رون وني مذ خلق لقو من الر لرض ام لهم شرك في الس لسم سمو موت ام اتي تين ينه نهم كتب فهم علي بين ينت منه بل ان يعد الظ لظل ظلم لمو مون بعض عضه ضهم بعض ال غرو رور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2051, 'quran:35:41', 'quran', 'quran', '35:41', 41, 2050, 'Fatir', 'فاطر', 'إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدٖ مِّنۢ بَعۡدِهِۦٓۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا', NULL, NULL, 'ان الله يمسك السموت والارض ان تزولا ولين زالتا ان امسكهما من احد من بعده انه كان حليما غفورا', 'ان له يمسك سموت ارض ان تزول لين زلت ان امسكهم من احد من بعد ان كن حليم غفور', 'quran', NULL, NULL, 'https://quran.com/35/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2051, 'ان الل لله يمس مسك الس لسم سمو موت ولر لرض ان تزو زول ولي لين زلت ان امس مسك سكه كهم من احد من بعد عده انه كن حلي ليم غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2052, 'quran:35:42', 'quran', 'quran', '35:42', 42, 2051, 'Fatir', 'فاطر', 'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا', NULL, NULL, 'واقسموا بالله جهد ايمنهم لين جاءهم نذير ليكونن اهدي من احدي الامم فلما جاءهم نذير ما زادهم الا نفورا', 'اقسم له جهد ايمن لين جء نذير ليكونن اهد من احد امم لم جء نذير م زد ال نفور', 'quran', NULL, NULL, 'https://quran.com/35/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2052, 'وقس قسم سمو بلل لله جهد ايم يمن منه نهم لين جءه ءهم نذي ذير ليك يكو كون ونن اهد هدي من احد حدي الم لمم فلم جءه ءهم نذي ذير م زده دهم ال نفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2053, 'quran:35:43', 'quran', 'quran', '35:43', 43, 2052, 'Fatir', 'فاطر', 'ٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا', NULL, NULL, 'استكبارا في الارض ومكر السيي ولا يحيق المكر السيي الا باهله فهل ينظرون الا سنت الاولين فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا', 'استكبر في ارض مكر سي ول يحيق مكر سي ال بهل فهل ينظر ال سنت اول فلن تجد لسنت له تبديل ولن تجد لسنت له تحويل', 'quran', NULL, NULL, 'https://quran.com/35/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2053, 'است ستك تكب كبر في الر لرض ومك مكر الس لسي سيي ول يحي حيق الم لمك مكر الس لسي سيي ال بهل هله فهل ينظ نظر ظرو رون ال سنت الو لول ولي لين فلن تجد لسن سنت الل لله تبد بدي ديل ولن تجد لسن سنت الل لله تحو حوي ويل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2054, 'quran:35:44', 'quran', 'quran', '35:44', 44, 2053, 'Fatir', 'فاطر', 'أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَكَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗۚ وَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمٗا قَدِيرٗا', NULL, NULL, 'اولم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم وكانوا اشد منهم قوه وما كان الله ليعجزه من شيء في السموت ولا في الارض انه كان عليما قديرا', 'اولم يسير في ارض ينظر كيف كن عقب ذين من قبل كن اشد من قو وم كن له ليعجز من شيء في سموت ول في ارض ان كن عليم قدير', 'quran', NULL, NULL, 'https://quran.com/35/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2054, 'اول ولم يسي سير يرو في الر لرض فين ينظ نظر ظرو كيف كن عقب قبه الذ لذي ذين من قبل بله لهم وكن كنو اشد منه نهم قوه وم كن الل لله ليع يعج عجز جزه من شيء في الس لسم سمو موت ول في الر لرض انه كن علي ليم قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2055, 'quran:35:45', 'quran', 'quran', '35:45', 45, 2054, 'Fatir', 'فاطر', 'وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا', NULL, NULL, 'ولو يواخذ الله الناس بما كسبوا ما ترك علي ظهرها من دابه ولكن يوخرهم الي اجل مسمي فاذا جاء اجلهم فان الله كان بعباده بصيرا', 'ولو يوخذ له نس بم كسب م ترك عل ظهر من دب لكن يوخر ال اجل مسم اذ جء اجل فن له كن بعبد بصير', 'quran', NULL, NULL, 'https://quran.com/35/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2055, 'ولو يوخ وخذ الل لله الن لنس بم كسب سبو م ترك علي ظهر هره من دبه ولك لكن يوخ وخر خره رهم الي اجل مسم سمي فذ جء اجل جله لهم فن الل لله كن بعب عبد بده بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2056, 'quran:39:1', 'quran', 'quran', '39:1', 1, 2055, 'Az-Zumar', 'الزمر', 'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ', NULL, NULL, 'تنزيل الكتب من الله العزيز الحكيم', 'تنزيل كتب من له عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/39/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2056, 'تنز نزي زيل الك لكت كتب من الل لله الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2057, 'quran:39:2', 'quran', 'quran', '39:2', 2, 2056, 'Az-Zumar', 'الزمر', 'إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ', NULL, NULL, 'انا انزلنا اليك الكتب بالحق فاعبد الله مخلصا له الدين', 'ان انزل يك كتب حق اعبد له مخلص له دين', 'quran', NULL, NULL, 'https://quran.com/39/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2057, 'ان انز نزل زلن الي ليك الك لكت كتب بلح لحق فعب عبد الل لله مخل خلص له الد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2058, 'quran:39:3', 'quran', 'quran', '39:3', 3, 2057, 'Az-Zumar', 'الزمر', 'أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ', NULL, NULL, 'الا لله الدين الخالص والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الي الله زلفي ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كذب كفار', 'ال لل دين خلص ذين اتخذ من دون اوليء م نعبد ال ليقربو ال له زلف ان له يح بين في م هم في يختلف ان له ل يهد من هو كذب كفر', 'quran', NULL, NULL, 'https://quran.com/39/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2058, 'ال لله الد لدي دين الخ لخل خلص ولذ لذي ذين اتخ تخذ خذو من دون ونه اول ولي ليء م نعب عبد بده دهم ال ليق يقر قرب ربو بون الي الل لله زلف لفي ان الل لله يحك حكم بين ينه نهم في م هم فيه يخت ختل تلف لفو فون ان الل لله ل يهد هدي من هو كذب كفر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2059, 'quran:39:4', 'quran', 'quran', '39:4', 4, 2058, 'Az-Zumar', 'الزمر', 'لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ', NULL, NULL, 'لو اراد الله ان يتخذ ولدا لاصطفي مما يخلق ما يشاء سبحنه هو الله الوحد القهار', 'لو ارد له ان يتخذ لد لصطف مم يخلق م يشء سبحن هو له وحد قهر', 'quran', NULL, NULL, 'https://quran.com/39/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2059, 'لو ارد الل لله ان يتخ تخذ ولد لصط صطف طفي مم يخل خلق م يشء سبح بحن حنه هو الل لله الو لوح وحد الق لقه قهر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2060, 'quran:39:5', 'quran', 'quran', '39:5', 5, 2059, 'Az-Zumar', 'الزمر', 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ', NULL, NULL, 'خلق السموت والارض بالحق يكور اليل علي النهار ويكور النهار علي اليل وسخر الشمس والقمر كل يجري لاجل مسمي الا هو العزيز الغفر', 'خلق سموت ارض حق يكور يل عل نهر يكور نهر عل يل سخر شمس قمر كل يجر لجل مسم ال هو عزيز غفر', 'quran', NULL, NULL, 'https://quran.com/39/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2060, 'خلق الس لسم سمو موت ولر لرض بلح لحق يكو كور الي ليل علي الن لنه نهر ويك يكو كور الن لنه نهر علي الي ليل وسخ سخر الش لشم شمس ولق لقم قمر كل يجر جري لجل مسم سمي ال هو الع لعز عزي زيز الغ لغف غفر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2061, 'quran:39:6', 'quran', 'quran', '39:6', 6, 2060, 'Az-Zumar', 'الزمر', 'خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ', NULL, NULL, 'خلقكم من نفس وحده ثم جعل منها زوجها وانزل لكم من الانعم ثمنيه ازوج يخلقكم في بطون امهتكم خلقا من بعد خلق في ظلمت ثلث ذلكم الله ربكم له الملك لا اله الا هو فاني تصرفون', 'خلق من نفس حد ثم جعل من زوج انزل لكم من انعم ثمن ازوج يخلق في بط امهت خلق من بعد خلق في ظلمت ثلث ذل له رب له ملك ل ال ال هو ان تصرف', 'quran', NULL, NULL, 'https://quran.com/39/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2061, 'خلق لقك قكم من نفس وحد حده ثم جعل منه زوج وجه ونز نزل لكم من الن لنع نعم ثمن مني نيه ازو زوج يخل خلق لقك قكم في بطو طون امه مهت هتك تكم خلق من بعد خلق في ظلم لمت ثلث ذلك لكم الل لله ربك بكم له الم لمل ملك ل اله ال هو فني تصر صرف رفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2062, 'quran:39:7', 'quran', 'quran', '39:7', 7, 2061, 'Az-Zumar', 'الزمر', 'إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', NULL, NULL, 'ان تكفروا فان الله غني عنكم ولا يرضي لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازره وزر اخري ثم الي ربكم مرجعكم فينبيكم بما كنتم تعملون انه عليم بذات الصدور', 'ان تكفر فن له غن عن ول يرض لعبد كفر ون تشكر يرض لكم ول تزر ازر وزر اخر ثم ال رب مرجع ينبي بم كنتم تعمل ان عليم بذ صدور', 'quran', NULL, NULL, 'https://quran.com/39/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2062, 'ان تكف كفر فرو فن الل لله غني عنك نكم ول يرض رضي لعب عبد بده الك لكف كفر ون تشك شكر كرو يرض رضه لكم ول تزر وزر زره وزر اخر خري ثم الي ربك بكم مرج رجع جعك عكم فين ينب نبي بيك يكم بم كنت نتم تعم عمل ملو لون انه علي ليم بذت الص لصد صدو دور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2063, 'quran:39:8', 'quran', 'quran', '39:8', 8, 2062, 'Az-Zumar', 'الزمر', 'وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ', NULL, NULL, 'واذا مس الانسن ضر دعا ربه منيبا اليه ثم اذا خوله نعمه منه نسي ما كان يدعوا اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحب النار', 'اذ مس انسن ضر دع رب منيب يه ثم اذ خول نعم من نس م كن يدع يه من قبل جعل لل اندد ليضل عن سبيل قل تمتع بكفرك قليل انك من اصحب نر', 'quran', NULL, NULL, 'https://quran.com/39/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2063, 'وذ مس الن لنس نسن ضر دع ربه مني نيب الي ليه ثم اذ خول وله نعم عمه منه نسي م كن يدع دعو الي ليه من قبل وجع جعل لله اند ندد ليض يضل عن سبي بيل يله قل تمت متع بكف كفر فرك قلي ليل انك من اصح صحب الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2064, 'quran:39:9', 'quran', 'quran', '39:9', 9, 2063, 'Az-Zumar', 'الزمر', 'أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ', NULL, NULL, 'امن هو قنت اناء اليل ساجدا وقايما يحذر الاخره ويرجوا رحمه ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولوا الالبب', 'امن هو قنت انء يل سجد قيم يحذر اخر يرج رحم رب قل هل يستو ذين يعلم ذين ل يعلم انم يتذكر اول البب', 'quran', NULL, NULL, 'https://quran.com/39/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2064, 'امن هو قنت انء الي ليل سجد وقي قيم يحذ حذر الخ لخر خره وير يرج رجو رحم حمه ربه قل هل يست ستو توي الذ لذي ذين يعل علم لمو مون ولذ لذي ذين ل يعل علم لمو مون انم يتذ تذك ذكر اول ولو الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2065, 'quran:39:10', 'quran', 'quran', '39:10', 10, 2064, 'Az-Zumar', 'الزمر', 'قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ', NULL, NULL, 'قل يا عباد الذين امنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنه وارض الله وسعه انما يوفي الصبرون اجرهم بغير حساب', 'قل ي عبد ذين امن اتق رب ذين احسن في هذ دني حسن ارض له سع انم يوف صبر اجر بغير حسب', 'quran', NULL, NULL, 'https://quran.com/39/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2065, 'قل ي عبد الذ لذي ذين امن منو اتق تقو ربك بكم للذ لذي ذين احس حسن سنو في هذه الد لدن دني حسن سنه ورض الل لله وسع سعه انم يوف وفي الص لصب صبر برو رون اجر جره رهم بغي غير حسب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2066, 'quran:39:11', 'quran', 'quran', '39:11', 11, 2065, 'Az-Zumar', 'الزمر', 'قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ', NULL, NULL, 'قل اني امرت ان اعبد الله مخلصا له الدين', 'قل ان امرت ان اعبد له مخلص له دين', 'quran', NULL, NULL, 'https://quran.com/39/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2066, 'قل اني امر مرت ان اعب عبد الل لله مخل خلص له الد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2067, 'quran:39:12', 'quran', 'quran', '39:12', 12, 2066, 'Az-Zumar', 'الزمر', 'وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ', NULL, NULL, 'وامرت لان اكون اول المسلمين', 'امرت لن اك اول مسلم', 'quran', NULL, NULL, 'https://quran.com/39/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2067, 'ومر مرت لن اكو كون اول الم لمس مسل سلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2068, 'quran:39:13', 'quran', 'quran', '39:13', 13, 2067, 'Az-Zumar', 'الزمر', 'قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ', NULL, NULL, 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', 'قل ان اخف ان عصيت رب عذب يوم عظيم', 'quran', NULL, NULL, 'https://quran.com/39/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2068, 'قل اني اخف ان عصي صيت ربي عذب يوم عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2069, 'quran:39:14', 'quran', 'quran', '39:14', 14, 2068, 'Az-Zumar', 'الزمر', 'قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي', NULL, NULL, 'قل الله اعبد مخلصا له ديني', 'قل له اعبد مخلص له دين', 'quran', NULL, NULL, 'https://quran.com/39/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2069, 'قل الل لله اعب عبد مخل خلص له دين يني');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2070, 'quran:39:15', 'quran', 'quran', '39:15', 15, 2069, 'Az-Zumar', 'الزمر', 'فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ', NULL, NULL, 'فاعبدوا ما شيتم من دونه قل ان الخسرين الذين خسروا انفسهم واهليهم يوم القيمه الا ذلك هو الخسران المبين', 'اعبد م شيتم من دون قل ان خسر ذين خسر انفس اهلي يوم قيم ال ذلك هو خسر مب', 'quran', NULL, NULL, 'https://quran.com/39/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2070, 'فعب عبد بدو م شيت يتم من دون ونه قل ان الخ لخس خسر سري رين الذ لذي ذين خسر سرو انف نفس فسه سهم وهل هلي ليه يهم يوم الق لقي قيم يمه ال ذلك هو الخ لخس خسر سرن الم لمب مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2071, 'quran:39:16', 'quran', 'quran', '39:16', 16, 2070, 'Az-Zumar', 'الزمر', 'لَهُم مِّن فَوۡقِهِمۡ ظُلَلٞ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلٞۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ', NULL, NULL, 'لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يا عباد فاتقون', 'لهم من وق ظلل من نر ومن تحت ظلل ذلك يخوف له به عبد ي عبد اتق', 'quran', NULL, NULL, 'https://quran.com/39/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2071, 'لهم من فوق وقه قهم ظلل من الن لنر ومن تحت حته تهم ظلل ذلك يخو خوف الل لله به عبد بده ي عبد فتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2072, 'quran:39:17', 'quran', 'quran', '39:17', 17, 2071, 'Az-Zumar', 'الزمر', 'وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ', NULL, NULL, 'والذين اجتنبوا الطغوت ان يعبدوها وانابوا الي الله لهم البشري فبشر عباد', 'ذين اجتنب طغوت ان يعبدو انب ال له لهم بشر بشر عبد', 'quran', NULL, NULL, 'https://quran.com/39/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2072, 'ولذ لذي ذين اجت جتن تنب نبو الط لطغ طغو غوت ان يعب عبد بدو دوه ونب نبو الي الل لله لهم الب لبش بشر شري فبش بشر عبد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2073, 'quran:39:18', 'quran', 'quran', '39:18', 18, 2072, 'Az-Zumar', 'الزمر', 'ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ', NULL, NULL, 'الذين يستمعون القول فيتبعون احسنه اوليك الذين هداهم الله واوليك هم اولوا الالبب', 'ذين يستمع قول يتبع احسن اوليك ذين هد له اوليك هم اول البب', 'quran', NULL, NULL, 'https://quran.com/39/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2073, 'الذ لذي ذين يست ستم تمع معو عون الق لقو قول فيت يتب تبع بعو عون احس حسن سنه اول ولي ليك الذ لذي ذين هده دهم الل لله وول ولي ليك هم اول ولو الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2074, 'quran:39:19', 'quran', 'quran', '39:19', 19, 2073, 'Az-Zumar', 'الزمر', 'أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ', NULL, NULL, 'افمن حق عليه كلمه العذاب افانت تنقذ من في النار', 'افمن حق عل كلم عذب افنت تنقذ من في نر', 'quran', NULL, NULL, 'https://quran.com/39/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2074, 'افم فمن حق علي ليه كلم لمه الع لعذ عذب افن فنت تنق نقذ من في الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2075, 'quran:39:20', 'quran', 'quran', '39:20', 20, 2074, 'Az-Zumar', 'الزمر', 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفٞ مِّن فَوۡقِهَا غُرَفٞ مَّبۡنِيَّةٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ', NULL, NULL, 'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنيه تجري من تحتها الانهر وعد الله لا يخلف الله الميعاد', 'لكن ذين اتق رب لهم غرف من وق غرف مبن تجر من تحت انهر وعد له ل يخلف له ميعد', 'quran', NULL, NULL, 'https://quran.com/39/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2075, 'لكن الذ لذي ذين اتق تقو ربه بهم لهم غرف من فوق وقه غرف مبن بني نيه تجر جري من تحت حته الن لنه نهر وعد الل لله ل يخل خلف الل لله الم لمي ميع يعد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2076, 'quran:39:21', 'quran', 'quran', '39:21', 21, 2075, 'Az-Zumar', 'الزمر', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ', NULL, NULL, 'الم تر ان الله انزل من السماء ماء فسلكه ينبيع في الارض ثم يخرج به زرعا مختلفا الونه ثم يهيج فتراه مصفرا ثم يجعله حطما ان في ذلك لذكري لاولي الالبب', 'الم تر ان له انزل من سمء مء سلك ينبيع في ارض ثم يخرج به زرع مختلف ون ثم يهيج تر مصفر ثم يجعل حطم ان في ذلك لذكر لول البب', 'quran', NULL, NULL, 'https://quran.com/39/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2076, 'الم تر ان الل لله انز نزل من الس لسم سمء مء فسل سلك لكه ينب نبي بيع في الر لرض ثم يخر خرج به زرع مخت ختل تلف الو لون ونه ثم يهي هيج فتر تره مصف صفر ثم يجع جعل عله حطم ان في ذلك لذك ذكر كري لول ولي الل للب لبب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2077, 'quran:39:22', 'quran', 'quran', '39:22', 22, 2076, 'Az-Zumar', 'الزمر', 'أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ فَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ', NULL, NULL, 'افمن شرح الله صدره للاسلم فهو علي نور من ربه فويل للقسيه قلوبهم من ذكر الله اوليك في ضلل مبين', 'افمن شرح له صدر اسلم فهو عل نور من رب ويل قس قلوب من ذكر له اوليك في ضلل مب', 'quran', NULL, NULL, 'https://quran.com/39/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2077, 'افم فمن شرح الل لله صدر دره للس لسل سلم فهو علي نور من ربه فوي ويل للق لقس قسي سيه قلو لوب وبه بهم من ذكر الل لله اول ولي ليك في ضلل مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2078, 'quran:39:23', 'quran', 'quran', '39:23', 23, 2077, 'Az-Zumar', 'الزمر', 'ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ', NULL, NULL, 'الله نزل احسن الحديث كتبا متشبها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم الي ذكر الله ذلك هدي الله يهدي به من يشاء ومن يضلل الله فما له من هاد', 'له نزل احسن حديث كتب متشب مثن تقشعر من جلود ذين يخش رب ثم تل جلود قلوب ال ذكر له ذلك هد له يهد به من يشء ومن يضلل له فم له من هد', 'quran', NULL, NULL, 'https://quran.com/39/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2078, 'الل لله نزل احس حسن الح لحد حدي ديث كتب متش تشب شبه مثن ثني تقش قشع شعر منه جلو لود الذ لذي ذين يخش خشو شون ربه بهم ثم تلي لين جلو لود وده دهم وقل قلو لوب وبه بهم الي ذكر الل لله ذلك هدي الل لله يهد هدي به من يشء ومن يضل ضلل الل لله فم له من هد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2079, 'quran:39:24', 'quran', 'quran', '39:24', 24, 2078, 'Az-Zumar', 'الزمر', 'أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ', NULL, NULL, 'افمن يتقي بوجهه سوء العذاب يوم القيمه وقيل للظلمين ذوقوا ما كنتم تكسبون', 'افمن يتق بوجه سوء عذب يوم قيم قيل ظلم ذوق م كنتم تكسب', 'quran', NULL, NULL, 'https://quran.com/39/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2079, 'افم فمن يتق تقي بوج وجه جهه سوء الع لعذ عذب يوم الق لقي قيم يمه وقي قيل للظ لظل ظلم لمي مين ذوق وقو م كنت نتم تكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2080, 'quran:39:25', 'quran', 'quran', '39:25', 25, 2079, 'Az-Zumar', 'الزمر', 'كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ', NULL, NULL, 'كذب الذين من قبلهم فاتاهم العذاب من حيث لا يشعرون', 'كذب ذين من قبل ات عذب من حيث ل يشعر', 'quran', NULL, NULL, 'https://quran.com/39/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2080, 'كذب الذ لذي ذين من قبل بله لهم فته تهم الع لعذ عذب من حيث ل يشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2081, 'quran:39:26', 'quran', 'quran', '39:26', 26, 2080, 'Az-Zumar', 'الزمر', 'فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'فاذاقهم الله الخزي في الحياه الدنيا ولعذاب الاخره اكبر لو كانوا يعلمون', 'اذق له خز في حي دني لعذب اخر اكبر لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/39/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2081, 'فذق ذقه قهم الل لله الخ لخز خزي في الح لحي حيه الد لدن دني ولع لعذ عذب الخ لخر خره اكب كبر لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2082, 'quran:39:27', 'quran', 'quran', '39:27', 27, 2081, 'Az-Zumar', 'الزمر', 'وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ', NULL, NULL, 'ولقد ضربنا للناس في هذا القران من كل مثل لعلهم يتذكرون', 'لقد ضرب نس في هذ قر من كل مثل لعل يتذكر', 'quran', NULL, NULL, 'https://quran.com/39/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2082, 'ولق لقد ضرب ربن للن لنس في هذ الق لقر قرن من كل مثل لعل عله لهم يتذ تذك ذكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2083, 'quran:39:28', 'quran', 'quran', '39:28', 28, 2082, 'Az-Zumar', 'الزمر', 'قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ', NULL, NULL, 'قرانا عربيا غير ذي عوج لعلهم يتقون', 'قر عربي غير ذي عوج لعل يتق', 'quran', NULL, NULL, 'https://quran.com/39/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2083, 'قرن عرب ربي غير ذي عوج لعل عله لهم يتق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2084, 'quran:39:29', 'quran', 'quran', '39:29', 29, 2083, 'Az-Zumar', 'الزمر', 'ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'ضرب الله مثلا رجلا فيه شركاء متشكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل اكثرهم لا يعلمون', 'ضرب له مثل رجل في شركء متشكس رجل سلم لرجل هل يستوي مثل حمد لل بل اكثر ل يعلم', 'quran', NULL, NULL, 'https://quran.com/39/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2084, 'ضرب الل لله مثل رجل فيه شرك ركء متش تشك شكس كسو سون ورج رجل سلم لرج رجل هل يست ستو توي وين مثل الح لحم حمد لله بل اكث كثر ثره رهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2085, 'quran:39:30', 'quran', 'quran', '39:30', 30, 2084, 'Az-Zumar', 'الزمر', 'إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ', NULL, NULL, 'انك ميت وانهم ميتون', 'انك ميت ان ميت', 'quran', NULL, NULL, 'https://quran.com/39/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2085, 'انك ميت ونه نهم ميت يتو تون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2086, 'quran:39:31', 'quran', 'quran', '39:31', 31, 2085, 'Az-Zumar', 'الزمر', 'ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ', NULL, NULL, 'ثم انكم يوم القيمه عند ربكم تختصمون', 'ثم ان يوم قيم عند رب تختصم', 'quran', NULL, NULL, 'https://quran.com/39/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2086, 'ثم انك نكم يوم الق لقي قيم يمه عند ربك بكم تخت ختص تصم صمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2087, 'quran:39:32', 'quran', 'quran', '39:32', 32, 2086, 'Az-Zumar', 'الزمر', 'فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ', NULL, NULL, 'فمن اظلم ممن كذب علي الله وكذب بالصدق اذ جاءه اليس في جهنم مثوي للكفرين', 'فمن اظلم ممن كذب عل له كذب صدق اذ جء يس في جهنم مثو كفر', 'quran', NULL, NULL, 'https://quran.com/39/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2087, 'فمن اظل ظلم ممن كذب علي الل لله وكذ كذب بلص لصد صدق اذ جءه الي ليس في جهن هنم مثو ثوي للك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2088, 'quran:39:33', 'quran', 'quran', '39:33', 33, 2087, 'Az-Zumar', 'الزمر', 'وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ', NULL, NULL, 'والذي جاء بالصدق وصدق به اوليك هم المتقون', 'ذي جء صدق صدق به اوليك هم متق', 'quran', NULL, NULL, 'https://quran.com/39/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2088, 'ولذ لذي جء بلص لصد صدق وصد صدق به اول ولي ليك هم الم لمت متق تقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2089, 'quran:39:34', 'quran', 'quran', '39:34', 34, 2088, 'Az-Zumar', 'الزمر', 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'لهم ما يشاءون عند ربهم ذلك جزاء المحسنين', 'لهم م يشء عند رب ذلك جزء محسن', 'quran', NULL, NULL, 'https://quran.com/39/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2089, 'لهم م يشء شءو ءون عند ربه بهم ذلك جزء الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2090, 'quran:39:35', 'quran', 'quran', '39:35', 35, 2089, 'Az-Zumar', 'الزمر', 'لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'ليكفر الله عنهم اسوا الذي عملوا ويجزيهم اجرهم باحسن الذي كانوا يعملون', 'ليكفر له عن اس ذي عمل يجزي اجر بحسن ذي كن يعمل', 'quran', NULL, NULL, 'https://quran.com/39/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2090, 'ليك يكف كفر الل لله عنه نهم اسو الذ لذي عمل ملو ويج يجز جزي زيه يهم اجر جره رهم بحس حسن الذ لذي كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2091, 'quran:39:36', 'quran', 'quran', '39:36', 36, 2090, 'Az-Zumar', 'الزمر', 'أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ', NULL, NULL, 'اليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد', 'يس له بكف عبد يخوفونك ذين من دون ومن يضلل له فم له من هد', 'quran', NULL, NULL, 'https://quran.com/39/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2091, 'الي ليس الل لله بكف عبد بده ويخ يخو خوف وفو فون ونك بلذ لذي ذين من دون ونه ومن يضل ضلل الل لله فم له من هد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2092, 'quran:39:37', 'quran', 'quran', '39:37', 37, 2091, 'Az-Zumar', 'الزمر', 'وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ', NULL, NULL, 'ومن يهد الله فما له من مضل اليس الله بعزيز ذي انتقام', 'ومن يهد له فم له من مضل يس له بعزيز ذي انتقم', 'quran', NULL, NULL, 'https://quran.com/39/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2092, 'ومن يهد الل لله فم له من مضل الي ليس الل لله بعز عزي زيز ذي انت نتق تقم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2093, 'quran:39:38', 'quran', 'quran', '39:38', 38, 2092, 'Az-Zumar', 'الزمر', 'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ', NULL, NULL, 'ولين سالتهم من خلق السموت والارض ليقولن الله قل افرءيتم ما تدعون من دون الله ان ارادني الله بضر هل هن كشفت ضره او ارادني برحمه هل هن ممسكت رحمته قل حسبي الله عليه يتوكل المتوكلون', 'لين سلت من خلق سموت ارض ليقولن له قل افرءيتم م تدع من دون له ان اردن له بضر هل هن كشفت ضر او اردن برحم هل هن ممسكت رحمت قل حسب له عل يتوكل متوكل', 'quran', NULL, NULL, 'https://quran.com/39/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2093, 'ولي لين سلت لته تهم من خلق الس لسم سمو موت ولر لرض ليق يقو قول ولن الل لله قل افر فرء رءي ءيت يتم م تدع دعو عون من دون الل لله ان ارد ردن دني الل لله بضر هل هن كشف شفت ضره او ارد ردن دني برح رحم حمه هل هن ممس مسك سكت رحم حمت مته قل حسب سبي الل لله علي ليه يتو توك وكل الم لمت متو توك وكل كلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2094, 'quran:39:39', 'quran', 'quran', '39:39', 39, 2093, 'Az-Zumar', 'الزمر', 'قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ', NULL, NULL, 'قل يا قوم اعملوا علي مكانتكم اني عمل فسوف تعلمون', 'قل ي قوم اعمل عل مكنت ان عمل سوف تعلم', 'quran', NULL, NULL, 'https://quran.com/39/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2094, 'قل ي قوم اعم عمل ملو علي مكن كنت نتك تكم اني عمل فسو سوف تعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2095, 'quran:39:40', 'quran', 'quran', '39:40', 40, 2094, 'Az-Zumar', 'الزمر', 'مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ', NULL, NULL, 'من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم', 'من يت عذب يخز يحل عل عذب مقيم', 'quran', NULL, NULL, 'https://quran.com/39/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2095, 'من يتي تيه عذب يخز خزي زيه ويح يحل علي ليه عذب مقي قيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2096, 'quran:39:41', 'quran', 'quran', '39:41', 41, 2095, 'Az-Zumar', 'الزمر', 'إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ', NULL, NULL, 'انا انزلنا عليك الكتب للناس بالحق فمن اهتدي فلنفسه ومن ضل فانما يضل عليها وما انت عليهم بوكيل', 'ان انزل عليك كتب نس حق فمن اهتد لنفس ومن ضل انم يضل علي وم انت علي بوكيل', 'quran', NULL, NULL, 'https://quran.com/39/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2096, 'ان انز نزل زلن علي ليك الك لكت كتب للن لنس بلح لحق فمن اهت هتد تدي فلن لنف نفس فسه ومن ضل فنم يضل علي ليه وم انت علي ليه يهم بوك وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2097, 'quran:39:42', 'quran', 'quran', '39:42', 42, 2096, 'Az-Zumar', 'الزمر', 'ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ', NULL, NULL, 'الله يتوفي الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضي عليها الموت ويرسل الاخري الي اجل مسمي ان في ذلك لايت لقوم يتفكرون', 'له يتوف انفس حين موت تي لم تمت في منم يمسك تي قض علي موت يرسل اخر ال اجل مسم ان في ذلك ليت لقوم يتفكر', 'quran', NULL, NULL, 'https://quran.com/39/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2097, 'الل لله يتو توف وفي الن لنف نفس حين موت وته ولت لتي لم تمت في منم نمه فيم يمس مسك الت لتي قضي علي ليه الم لمو موت وير يرس رسل الخ لخر خري الي اجل مسم سمي ان في ذلك ليت لقو قوم يتف تفك فكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2098, 'quran:39:43', 'quran', 'quran', '39:43', 43, 2097, 'Az-Zumar', 'الزمر', 'أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ', NULL, NULL, 'ام اتخذوا من دون الله شفعاء قل اولو كانوا لا يملكون شيا ولا يعقلون', 'ام اتخذ من دون له شفعء قل اولو كن ل يملك شي ول يعقل', 'quran', NULL, NULL, 'https://quran.com/39/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2098, 'ام اتخ تخذ خذو من دون الل لله شفع فعء قل اول ولو كنو ل يمل ملك لكو كون شي ول يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2099, 'quran:39:44', 'quran', 'quran', '39:44', 44, 2098, 'Az-Zumar', 'الزمر', 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ', NULL, NULL, 'قل لله الشفعه جميعا له ملك السموت والارض ثم اليه ترجعون', 'قل لل شفع جميع له ملك سموت ارض ثم يه ترجع', 'quran', NULL, NULL, 'https://quran.com/39/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2099, 'قل لله الش لشف شفع فعه جمي ميع له ملك الس لسم سمو موت ولر لرض ثم الي ليه ترج رجع جعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2100, 'quran:39:45', 'quran', 'quran', '39:45', 45, 2099, 'Az-Zumar', 'الزمر', 'وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ', NULL, NULL, 'واذا ذكر الله وحده اشمازت قلوب الذين لا يومنون بالاخره واذا ذكر الذين من دونه اذا هم يستبشرون', 'اذ ذكر له حد اشمزت قلوب ذين ل يومن اخر اذ ذكر ذين من دون اذ هم يستبشر', 'quran', NULL, NULL, 'https://quran.com/39/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2100, 'وذ ذكر الل لله وحد حده اشم شمز مزت قلو لوب الذ لذي ذين ل يوم ومن منو نون بلخ لخر خره وذ ذكر الذ لذي ذين من دون ونه اذ هم يست ستب تبش بشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2101, 'quran:39:46', 'quran', 'quran', '39:46', 46, 2100, 'Az-Zumar', 'الزمر', 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ', NULL, NULL, 'قل اللهم فاطر السموت والارض علم الغيب والشهده انت تحكم بين عبادك في ما كانوا فيه يختلفون', 'قل لهم اطر سموت ارض علم غيب شهد انت تح بين عبدك في م كن في يختلف', 'quran', NULL, NULL, 'https://quran.com/39/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2101, 'قل الل لله لهم فطر الس لسم سمو موت ولر لرض علم الغ لغي غيب ولش لشه شهد هده انت تحك حكم بين عبد بدك في م كنو فيه يخت ختل تلف لفو فون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2102, 'quran:39:47', 'quran', 'quran', '39:47', 47, 2101, 'Az-Zumar', 'الزمر', 'وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ', NULL, NULL, 'ولو ان للذين ظلموا ما في الارض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيمه وبدا لهم من الله ما لم يكونوا يحتسبون', 'ولو ان ذين ظلم م في ارض جميع مثل مع لفتد به من سوء عذب يوم قيم بد لهم من له م لم يكون يحتسب', 'quran', NULL, NULL, 'https://quran.com/39/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2102, 'ولو ان للذ لذي ذين ظلم لمو م في الر لرض جمي ميع ومث مثل ثله معه لفت فتد تدو به من سوء الع لعذ عذب يوم الق لقي قيم يمه وبد لهم من الل لله م لم يكو كون ونو يحت حتس تسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2103, 'quran:39:48', 'quran', 'quran', '39:48', 48, 2102, 'Az-Zumar', 'الزمر', 'وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', NULL, NULL, 'وبدا لهم سيات ما كسبوا وحاق بهم ما كانوا به يستهزءون', 'بد لهم سي م كسب حق بهم م كن به يستهزء', 'quran', NULL, NULL, 'https://quran.com/39/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2103, 'وبد لهم سيت م كسب سبو وحق بهم م كنو به يست سته تهز هزء زءو ءون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2104, 'quran:39:49', 'quran', 'quran', '39:49', 49, 2103, 'Az-Zumar', 'الزمر', 'فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'فاذا مس الانسن ضر دعانا ثم اذا خولنه نعمه منا قال انما اوتيته علي علم بل هي فتنه ولكن اكثرهم لا يعلمون', 'اذ مس انسن ضر دع ثم اذ خولن نعم من قل انم اوتيت عل علم بل هي تن لكن اكثر ل يعلم', 'quran', NULL, NULL, 'https://quran.com/39/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2104, 'فذ مس الن لنس نسن ضر دعن ثم اذ خول ولن لنه نعم عمه من قل انم اوت وتي تيت يته علي علم بل هي فتن تنه ولك لكن اكث كثر ثره رهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2105, 'quran:39:50', 'quran', 'quran', '39:50', 50, 2104, 'Az-Zumar', 'الزمر', 'قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ', NULL, NULL, 'قد قالها الذين من قبلهم فما اغني عنهم ما كانوا يكسبون', 'قد قل ذين من قبل فم اغن عن م كن يكسب', 'quran', NULL, NULL, 'https://quran.com/39/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2105, 'قد قله الذ لذي ذين من قبل بله لهم فم اغن غني عنه نهم م كنو يكس كسب سبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2106, 'quran:39:51', 'quran', 'quran', '39:51', 51, 2105, 'Az-Zumar', 'الزمر', 'فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ', NULL, NULL, 'فاصابهم سيات ما كسبوا والذين ظلموا من هولاء سيصيبهم سيات ما كسبوا وما هم بمعجزين', 'اصب سي م كسب ذين ظلم من هولء سيصيب سي م كسب وم هم بمعجز', 'quran', NULL, NULL, 'https://quran.com/39/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2106, 'فصب صبه بهم سيت م كسب سبو ولذ لذي ذين ظلم لمو من هول ولء سيص يصي صيب يبه بهم سيت م كسب سبو وم هم بمع معج عجز جزي زين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2107, 'quran:39:52', 'quran', 'quran', '39:52', 52, 2106, 'Az-Zumar', 'الزمر', 'أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ', NULL, NULL, 'اولم يعلموا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايت لقوم يومنون', 'اولم يعلم ان له يبسط رزق لمن يشء يقدر ان في ذلك ليت لقوم يومن', 'quran', NULL, NULL, 'https://quran.com/39/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2107, 'اول ولم يعل علم لمو ان الل لله يبس بسط الر لرز رزق لمن يشء ويق يقد قدر ان في ذلك ليت لقو قوم يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2108, 'quran:39:53', 'quran', 'quran', '39:53', 53, 2107, 'Az-Zumar', 'الزمر', 'قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ', NULL, NULL, 'قل يا عبادي الذين اسرفوا علي انفسهم لا تقنطوا من رحمه الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيم', 'قل ي عبد ذين اسرف عل انفس ل تقنط من رحم له ان له يغفر ذنوب جميع ان هو غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/39/53');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2108, 'قل ي عبد بدي الذ لذي ذين اسر سرف رفو علي انف نفس فسه سهم ل تقن قنط نطو من رحم حمه الل لله ان الل لله يغف غفر الذ لذن ذنو نوب جمي ميع انه هو الغ لغف غفو فور الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2109, 'quran:39:54', 'quran', 'quran', '39:54', 54, 2108, 'Az-Zumar', 'الزمر', 'وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ', NULL, NULL, 'وانيبوا الي ربكم واسلموا له من قبل ان ياتيكم العذاب ثم لا تنصرون', 'انيب ال رب اسلم له من قبل ان يتي عذب ثم ل تنصر', 'quran', NULL, NULL, 'https://quran.com/39/54');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2109, 'وني نيب يبو الي ربك بكم وسل سلم لمو له من قبل ان يتي تيك يكم الع لعذ عذب ثم ل تنص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2110, 'quran:39:55', 'quran', 'quran', '39:55', 55, 2109, 'Az-Zumar', 'الزمر', 'وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ بَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ', NULL, NULL, 'واتبعوا احسن ما انزل اليكم من ربكم من قبل ان ياتيكم العذاب بغته وانتم لا تشعرون', 'اتبع احسن م انزل يكم من رب من قبل ان يتي عذب بغت انتم ل تشعر', 'quran', NULL, NULL, 'https://quran.com/39/55');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2110, 'وتب تبع بعو احس حسن م انز نزل الي ليك يكم من ربك بكم من قبل ان يتي تيك يكم الع لعذ عذب بغت غته ونت نتم ل تشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2111, 'quran:39:56', 'quran', 'quran', '39:56', 56, 2110, 'Az-Zumar', 'الزمر', 'أَن تَقُولَ نَفۡسٞ يَٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', NULL, NULL, 'ان تقول نفس يا حسرتي علي ما فرطت في جنب الله وان كنت لمن السخرين', 'ان تقول نفس ي حسرت عل م رطت في جنب له ون كنت لمن سخر', 'quran', NULL, NULL, 'https://quran.com/39/56');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2111, 'ان تقو قول نفس ي حسر سرت رتي علي م فرط رطت في جنب الل لله ون كنت لمن الس لسخ سخر خري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2112, 'quran:39:57', 'quran', 'quran', '39:57', 57, 2111, 'Az-Zumar', 'الزمر', 'أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ', NULL, NULL, 'او تقول لو ان الله هداني لكنت من المتقين', 'او تقول لو ان له هدن لكنت من متق', 'quran', NULL, NULL, 'https://quran.com/39/57');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2112, 'او تقو قول لو ان الل لله هدن دني لكن كنت من الم لمت متق تقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2113, 'quran:39:58', 'quran', 'quran', '39:58', 58, 2112, 'Az-Zumar', 'الزمر', 'أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ', NULL, NULL, 'او تقول حين تري العذاب لو ان لي كره فاكون من المحسنين', 'او تقول حين تر عذب لو ان لي كر اك من محسن', 'quran', NULL, NULL, 'https://quran.com/39/58');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2113, 'او تقو قول حين تري الع لعذ عذب لو ان لي كره فكو كون من الم لمح محس حسن سني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2114, 'quran:39:59', 'quran', 'quran', '39:59', 59, 2113, 'Az-Zumar', 'الزمر', 'بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ', NULL, NULL, 'بلي قد جاءتك ايتي فكذبت بها واستكبرت وكنت من الكفرين', 'بل قد جءتك ايت كذبت به استكبرت كنت من كفر', 'quran', NULL, NULL, 'https://quran.com/39/59');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2114, 'بلي قد جءت ءتك ايت يتي فكذ كذب ذبت به وست ستك تكب كبر برت وكن كنت من الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2115, 'quran:39:60', 'quran', 'quran', '39:60', 60, 2114, 'Az-Zumar', 'الزمر', 'وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ', NULL, NULL, 'ويوم القيمه تري الذين كذبوا علي الله وجوههم مسوده اليس في جهنم مثوي للمتكبرين', 'يوم قيم تر ذين كذب عل له جوه مسود يس في جهنم مثو متكبر', 'quran', NULL, NULL, 'https://quran.com/39/60');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2115, 'ويو يوم الق لقي قيم يمه تري الذ لذي ذين كذب ذبو علي الل لله وجو جوه وهه ههم مسو سود وده الي ليس في جهن هنم مثو ثوي للم لمت متك تكب كبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2116, 'quran:39:61', 'quran', 'quran', '39:61', 61, 2115, 'Az-Zumar', 'الزمر', 'وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ', NULL, NULL, 'وينجي الله الذين اتقوا بمفازتهم لا يمسهم السوء ولا هم يحزنون', 'ينج له ذين اتق بمفزت ل يمس سوء ول هم يحزن', 'quran', NULL, NULL, 'https://quran.com/39/61');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2116, 'وين ينج نجي الل لله الذ لذي ذين اتق تقو بمف مفز فزت زته تهم ل يمس مسه سهم الس لسو سوء ول هم يحز حزن زنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2117, 'quran:39:62', 'quran', 'quran', '39:62', 62, 2116, 'Az-Zumar', 'الزمر', 'ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ', NULL, NULL, 'الله خلق كل شيء وهو علي كل شيء وكيل', 'له خلق كل شيء وهو عل كل شيء كيل', 'quran', NULL, NULL, 'https://quran.com/39/62');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2117, 'الل لله خلق كل شيء وهو علي كل شيء وكي كيل');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2118, 'quran:39:63', 'quran', 'quran', '39:63', 63, 2117, 'Az-Zumar', 'الزمر', 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', NULL, NULL, 'له مقاليد السموت والارض والذين كفروا بايت الله اوليك هم الخسرون', 'له مقليد سموت ارض ذين كفر بيت له اوليك هم خسر', 'quran', NULL, NULL, 'https://quran.com/39/63');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2118, 'له مقل قلي ليد الس لسم سمو موت ولر لرض ولذ لذي ذين كفر فرو بيت الل لله اول ولي ليك هم الخ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2119, 'quran:39:64', 'quran', 'quran', '39:64', 64, 2118, 'Az-Zumar', 'الزمر', 'قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ', NULL, NULL, 'قل افغير الله تامروني اعبد ايها الجهلون', 'قل افغير له تمرون اعبد اي جهل', 'quran', NULL, NULL, 'https://quran.com/39/64');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2119, 'قل افغ فغي غير الل لله تمر مرو رون وني اعب عبد ايه الج لجه جهل هلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2120, 'quran:39:65', 'quran', 'quran', '39:65', 65, 2119, 'Az-Zumar', 'الزمر', 'وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ', NULL, NULL, 'ولقد اوحي اليك والي الذين من قبلك لين اشركت ليحبطن عملك ولتكونن من الخسرين', 'لقد اوح يك ول ذين من قبلك لين اشركت ليحبطن عملك لتكونن من خسر', 'quran', NULL, NULL, 'https://quran.com/39/65');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2120, 'ولق لقد اوح وحي الي ليك ولي الذ لذي ذين من قبل بلك لين اشر شرك ركت ليح يحب حبط بطن عمل ملك ولت لتك تكو كون ونن من الخ لخس خسر سري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2121, 'quran:39:66', 'quran', 'quran', '39:66', 66, 2120, 'Az-Zumar', 'الزمر', 'بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ', NULL, NULL, 'بل الله فاعبد وكن من الشكرين', 'بل له اعبد وكن من شكر', 'quran', NULL, NULL, 'https://quran.com/39/66');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2121, 'بل الل لله فعب عبد وكن من الش لشك شكر كري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2122, 'quran:39:67', 'quran', 'quran', '39:67', 67, 2121, 'Az-Zumar', 'الزمر', 'وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطۡوِيَّٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', NULL, NULL, 'وما قدروا الله حق قدره والارض جميعا قبضته يوم القيمه والسموت مطويت بيمينه سبحنه وتعلي عما يشركون', 'وم قدر له حق قدر ارض جميع قبضت يوم قيم سموت مطويت بيمين سبحن تعل عم يشرك', 'quran', NULL, NULL, 'https://quran.com/39/67');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2122, 'وم قدر درو الل لله حق قدر دره ولر لرض جمي ميع قبض بضت ضته يوم الق لقي قيم يمه ولس لسم سمو موت مطو طوي ويت بيم يمي مين ينه سبح بحن حنه وتع تعل علي عم يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2123, 'quran:39:68', 'quran', 'quran', '39:68', 68, 2122, 'Az-Zumar', 'الزمر', 'وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامٞ يَنظُرُونَ', NULL, NULL, 'ونفخ في الصور فصعق من في السموت ومن في الارض الا من شاء الله ثم نفخ فيه اخري فاذا هم قيام ينظرون', 'نفخ في صور صعق من في سموت ومن في ارض ال من شء له ثم نفخ في اخر اذ هم قيم ينظر', 'quran', NULL, NULL, 'https://quran.com/39/68');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2123, 'ونف نفخ في الص لصو صور فصع صعق من في الس لسم سمو موت ومن في الر لرض ال من شء الل لله ثم نفخ فيه اخر خري فذ هم قيم ينظ نظر ظرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2124, 'quran:39:69', 'quran', 'quran', '39:69', 69, 2123, 'Az-Zumar', 'الزمر', 'وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ', NULL, NULL, 'واشرقت الارض بنور ربها ووضع الكتب وجايء بالنبين والشهداء وقضي بينهم بالحق وهم لا يظلمون', 'اشرقت ارض بنور رب وضع كتب جيء نب شهدء قض بين حق وهم ل يظلم', 'quran', NULL, NULL, 'https://quran.com/39/69');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2124, 'وشر شرق رقت الر لرض بنو نور ربه ووض وضع الك لكت كتب وجي جيء بلن لنب نبي بين ولش لشه شهد هدء وقض قضي بين ينه نهم بلح لحق وهم ل يظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2125, 'quran:39:70', 'quran', 'quran', '39:70', 70, 2124, 'Az-Zumar', 'الزمر', 'وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ', NULL, NULL, 'ووفيت كل نفس ما عملت وهو اعلم بما يفعلون', 'وفيت كل نفس م عملت وهو اعلم بم يفعل', 'quran', NULL, NULL, 'https://quran.com/39/70');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2125, 'ووف وفي فيت كل نفس م عمل ملت وهو اعل علم بم يفع فعل علو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2126, 'quran:39:71', 'quran', 'quran', '39:71', 71, 2125, 'Az-Zumar', 'الزمر', 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ', NULL, NULL, 'وسيق الذين كفروا الي جهنم زمرا حتي اذا جاءوها فتحت ابوبها وقال لهم خزنتها الم ياتكم رسل منكم يتلون عليكم ايت ربكم وينذرونكم لقاء يومكم هذا قالوا بلي ولكن حقت كلمه العذاب علي الكفرين', 'سيق ذين كفر ال جهنم زمر حت اذ جءو تحت ابوب قل لهم خزنت الم يت رسل من يتل علي ايت رب ينذرون لقء يوم هذ قل بل لكن حقت كلم عذب عل كفر', 'quran', NULL, NULL, 'https://quran.com/39/71');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2126, 'وسي سيق الذ لذي ذين كفر فرو الي جهن هنم زمر حتي اذ جءو ءوه فتح تحت ابو بوب وبه وقل لهم خزن زنت نته الم يتك تكم رسل منك نكم يتل تلو لون علي ليك يكم ايت ربك بكم وين ينذ نذر ذرو رون ونك نكم لقء يوم ومك مكم هذ قلو بلي ولك لكن حقت كلم لمه الع لعذ عذب علي الك لكف كفر فري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2127, 'quran:39:72', 'quran', 'quran', '39:72', 72, 2126, 'Az-Zumar', 'الزمر', 'قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ', NULL, NULL, 'قيل ادخلوا ابوب جهنم خلدين فيها فبيس مثوي المتكبرين', 'قيل ادخل ابوب جهنم خلد يه بيس مثو متكبر', 'quran', NULL, NULL, 'https://quran.com/39/72');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2127, 'قيل ادخ دخل خلو ابو بوب جهن هنم خلد لدي دين فيه فبي بيس مثو ثوي الم لمت متك تكب كبر بري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2128, 'quran:39:73', 'quran', 'quran', '39:73', 73, 2127, 'Az-Zumar', 'الزمر', 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ', NULL, NULL, 'وسيق الذين اتقوا ربهم الي الجنه زمرا حتي اذا جاءوها وفتحت ابوبها وقال لهم خزنتها سلم عليكم طبتم فادخلوها خلدين', 'سيق ذين اتق رب ال جن زمر حت اذ جءو فتحت ابوب قل لهم خزنت سلم علي طبتم ادخلو خلد', 'quran', NULL, NULL, 'https://quran.com/39/73');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2128, 'وسي سيق الذ لذي ذين اتق تقو ربه بهم الي الج لجن جنه زمر حتي اذ جءو ءوه وفت فتح تحت ابو بوب وبه وقل لهم خزن زنت نته سلم علي ليك يكم طبت بتم فدخ دخل خلو لوه خلد لدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2129, 'quran:39:74', 'quran', 'quran', '39:74', 74, 2128, 'Az-Zumar', 'الزمر', 'وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ', NULL, NULL, 'وقالوا الحمد لله الذي صدقنا وعده واورثنا الارض نتبوا من الجنه حيث نشاء فنعم اجر العملين', 'قل حمد لل ذي صدق عد اورث ارض نتب من جن حيث نشء نعم اجر عمل', 'quran', NULL, NULL, 'https://quran.com/39/74');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2129, 'وقل قلو الح لحم حمد لله الذ لذي صدق دقن وعد عده وور ورث رثن الر لرض نتب تبو من الج لجن جنه حيث نشء فنع نعم اجر الع لعم عمل ملي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2130, 'quran:39:75', 'quran', 'quran', '39:75', 75, 2129, 'Az-Zumar', 'الزمر', 'وَتَرَى ٱلۡمَلَٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'وتري المليكه حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العلمين', 'تر مليك حف من حول عرش يسبح بحمد رب قض بين حق قيل حمد لل رب علم', 'quran', NULL, NULL, 'https://quran.com/39/75');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2130, 'وتر تري الم لمل ملي ليك يكه حفي فين من حول الع لعر عرش يسب سبح بحو حون بحم حمد ربه بهم وقض قضي بين ينه نهم بلح لحق وقي قيل الح لحم حمد لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2131, 'quran:49:1', 'quran', 'quran', '49:1', 1, 2130, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', NULL, NULL, 'يا ايها الذين امنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم', 'ي اي ذين امن ل تقدم بين يد له رسول اتق له ان له سميع عليم', 'quran', NULL, NULL, 'https://quran.com/49/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2131, 'ي ايه الذ لذي ذين امن منو ل تقد قدم دمو بين يدي الل لله ورس رسو سول وله وتق تقو الل لله ان الل لله سمي ميع علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2132, 'quran:49:2', 'quran', 'quran', '49:2', 2, 2131, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ', NULL, NULL, 'يا ايها الذين امنوا لا ترفعوا اصوتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعملكم وانتم لا تشعرون', 'ي اي ذين امن ل ترفع اصوت فوق صوت نب ول تجهر له قول كجهر بعض لبعض ان تحبط اعمل انتم ل تشعر', 'quran', NULL, NULL, 'https://quran.com/49/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2132, 'ي ايه الذ لذي ذين امن منو ل ترف رفع فعو اصو صوت وتك تكم فوق صوت الن لنب نبي ول تجه جهر هرو له بلق لقو قول كجه جهر بعض عضك ضكم لبع بعض ان تحب حبط اعم عمل ملك لكم ونت نتم ل تشع شعر عرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2133, 'quran:49:3', 'quran', 'quran', '49:3', 3, 2132, 'Al-Hujurat', 'الحجرات', 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ', NULL, NULL, 'ان الذين يغضون اصوتهم عند رسول الله اوليك الذين امتحن الله قلوبهم للتقوي لهم مغفره واجر عظيم', 'ان ذين يغض اصوت عند رسول له اوليك ذين امتحن له قلوب تقو لهم مغفر اجر عظيم', 'quran', NULL, NULL, 'https://quran.com/49/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2133, 'ان الذ لذي ذين يغض غضو ضون اصو صوت وته تهم عند رسو سول الل لله اول ولي ليك الذ لذي ذين امت متح تحن الل لله قلو لوب وبه بهم للت لتق تقو قوي لهم مغف غفر فره وجر عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2134, 'quran:49:4', 'quran', 'quran', '49:4', 4, 2133, 'Al-Hujurat', 'الحجرات', 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ', NULL, NULL, 'ان الذين ينادونك من وراء الحجرت اكثرهم لا يعقلون', 'ان ذين يندونك من رء حجرت اكثر ل يعقل', 'quran', NULL, NULL, 'https://quran.com/49/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2134, 'ان الذ لذي ذين يند ندو دون ونك من ورء الح لحج حجر جرت اكث كثر ثره رهم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2135, 'quran:49:5', 'quran', 'quran', '49:5', 5, 2134, 'Al-Hujurat', 'الحجرات', 'وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرٗا لَّهُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'ولو انهم صبروا حتي تخرج اليهم لكان خيرا لهم والله غفور رحيم', 'ولو ان صبر حت تخرج يهم لك خير لهم له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/49/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2135, 'ولو انه نهم صبر برو حتي تخر خرج الي ليه يهم لكن خير لهم ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2136, 'quran:49:6', 'quran', 'quran', '49:6', 6, 2135, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ', NULL, NULL, 'يا ايها الذين امنوا ان جاءكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهله فتصبحوا علي ما فعلتم ندمين', 'ي اي ذين امن ان جء اسق بنب تبين ان تصيب قوم بجهل تصبح عل م علتم ندم', 'quran', NULL, NULL, 'https://quran.com/49/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2136, 'ي ايه الذ لذي ذين امن منو ان جءك ءكم فسق بنب فتب تبي بين ينو ان تصي صيب يبو قوم بجه جهل هله فتص تصب صبح بحو علي م فعل علت لتم ندم دمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2137, 'quran:49:7', 'quran', 'quran', '49:7', 7, 2136, 'Al-Hujurat', 'الحجرات', 'وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', NULL, NULL, 'واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمن وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اوليك هم الرشدون', 'اعلم ان يكم رسول له لو يطيع في كثير من امر لعنتم لكن له حبب يكم ايمن زين في قلوب كر يكم كفر فسوق عصي اوليك هم رشد', 'quran', NULL, NULL, 'https://quran.com/49/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2137, 'وعل علم لمو ان فيك يكم رسو سول الل لله لو يطي طيع يعك عكم في كثي ثير من الم لمر لعن عنت نتم ولك لكن الل لله حبب الي ليك يكم الي ليم يمن وزي زين ينه في قلو لوب وبك بكم وكر كره الي ليك يكم الك لكف كفر ولف لفس فسو سوق ولع لعص عصي صين اول ولي ليك هم الر لرش رشد شدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2138, 'quran:49:8', 'quran', 'quran', '49:8', 8, 2137, 'Al-Hujurat', 'الحجرات', 'فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', NULL, NULL, 'فضلا من الله ونعمه والله عليم حكيم', 'ضل من له نعم له عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/49/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2138, 'فضل من الل لله ونع نعم عمه ولل لله علي ليم حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2139, 'quran:49:9', 'quran', 'quran', '49:9', 9, 2138, 'Al-Hujurat', 'الحجرات', 'وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ', NULL, NULL, 'وان طايفتان من المومنين اقتتلوا فاصلحوا بينهما فان بغت احداهما علي الاخري فقتلوا التي تبغي حتي تفيء الي امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين', 'ون طيفت من مومن اقتتل اصلح بينهم فن بغت احدهم عل اخر قتل تي تبغ حت تفيء ال امر له فن اءت اصلح بينهم عدل اقسط ان له يحب مقسط', 'quran', NULL, NULL, 'https://quran.com/49/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2139, 'ون طيف يفت فتن من الم لمو موم ومن مني نين اقت قتت تتل تلو فصل صلح لحو بين ينه نهم فن بغت احد حده دهم علي الخ لخر خري فقت قتل تلو الت لتي تبغ بغي حتي تفي فيء الي امر الل لله فن فءت فصل صلح لحو بين ينه نهم بلع لعد عدل وقس قسط سطو ان الل لله يحب الم لمق مقس قسط سطي طين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2140, 'quran:49:10', 'quran', 'quran', '49:10', 10, 2139, 'Al-Hujurat', 'الحجرات', 'إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ', NULL, NULL, 'انما المومنون اخوه فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون', 'انم مومن اخو اصلح بين اخوي اتق له لعل ترحم', 'quran', NULL, NULL, 'https://quran.com/49/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2140, 'انم الم لمو موم ومن منو نون اخو خوه فصل صلح لحو بين اخو خوي ويك يكم وتق تقو الل لله لعل علك لكم ترح رحم حمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2141, 'quran:49:11', 'quran', 'quran', '49:11', 11, 2140, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', NULL, NULL, 'يا ايها الذين امنوا لا يسخر قوم من قوم عسي ان يكونوا خيرا منهم ولا نساء من نساء عسي ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقب بيس الاسم الفسوق بعد الايمن ومن لم يتب فاوليك هم الظلمون', 'ي اي ذين امن ل يسخر قوم من قوم عس ان يكون خير من ول نسء من نسء عس ان يكن خير من ول تلمز انفس ول تنبز القب بيس اسم فسوق بعد ايمن ومن لم يتب اوليك هم ظلم', 'quran', NULL, NULL, 'https://quran.com/49/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2141, 'ي ايه الذ لذي ذين امن منو ل يسخ سخر قوم من قوم عسي ان يكو كون ونو خير منه نهم ول نسء من نسء عسي ان يكن خير منه نهن ول تلم لمز مزو انف نفس فسك سكم ول تنب نبز بزو بلل للق لقب بيس الس لسم الف لفس فسو سوق بعد الي ليم يمن ومن لم يتب فول ولي ليك هم الظ لظل ظلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2142, 'quran:49:12', 'quran', 'quran', '49:12', 12, 2141, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ', NULL, NULL, 'يا ايها الذين امنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم', 'ي اي ذين امن اجتنب كثير من ظن ان بعض ظن اثم ول تجسس ول يغتب بعض بعض ايحب احد ان يكل لحم اخ ميت كرهتمو اتق له ان له توب رحيم', 'quran', NULL, NULL, 'https://quran.com/49/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2142, 'ي ايه الذ لذي ذين امن منو اجت جتن تنب نبو كثي ثير من الظ لظن ان بعض الظ لظن اثم ول تجس جسس سسو ول يغت غتب بعض عضك ضكم بعض ايح يحب احد حدك دكم ان يكل لحم اخي خيه ميت فكر كره رهت هتم تمو موه وتق تقو الل لله ان الل لله توب رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2143, 'quran:49:13', 'quran', 'quran', '49:13', 13, 2142, 'Al-Hujurat', 'الحجرات', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ', NULL, NULL, 'يا ايها الناس انا خلقنكم من ذكر وانثي وجعلنكم شعوبا وقبايل لتعارفوا ان اكرمكم عند الله اتقاكم ان الله عليم خبير', 'ي اي نس ان خلقن من ذكر انث جعلن شعوب قبيل لتعرف ان اكرم عند له اتق ان له عليم خبير', 'quran', NULL, NULL, 'https://quran.com/49/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2143, 'ي ايه الن لنس ان خلق لقن قنك نكم من ذكر ونث نثي وجع جعل علن لنك نكم شعو عوب وقب قبي بيل لتع تعر عرف رفو ان اكر كرم رمك مكم عند الل لله اتق تقك قكم ان الل لله علي ليم خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2144, 'quran:49:14', 'quran', 'quran', '49:14', 14, 2143, 'Al-Hujurat', 'الحجرات', 'قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', NULL, NULL, 'قالت الاعراب امنا قل لم تومنوا ولكن قولوا اسلمنا ولما يدخل الايمن في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعملكم شيا ان الله غفور رحيم', 'قلت اعرب ام قل لم تومن لكن قول اسلم لم يدخل ايمن في قلوب ون تطيع له رسول ل يلت من اعمل شي ان له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/49/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2144, 'قلت الع لعر عرب امن قل لم توم ومن منو ولك لكن قول ولو اسل سلم لمن ولم يدخ دخل الي ليم يمن في قلو لوب وبك بكم ون تطي طيع يعو الل لله ورس رسو سول وله ل يلت لتك تكم من اعم عمل ملك لكم شي ان الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2145, 'quran:49:15', 'quran', 'quran', '49:15', 15, 2144, 'Al-Hujurat', 'الحجرات', 'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', NULL, NULL, 'انما المومنون الذين امنوا بالله ورسوله ثم لم يرتابوا وجهدوا بامولهم وانفسهم في سبيل الله اوليك هم الصدقون', 'انم مومن ذين امن له رسول ثم لم يرتب جهد بمول انفس في سبيل له اوليك هم صدق', 'quran', NULL, NULL, 'https://quran.com/49/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2145, 'انم الم لمو موم ومن منو نون الذ لذي ذين امن منو بلل لله ورس رسو سول وله ثم لم يرت رتب تبو وجه جهد هدو بمو مول وله لهم ونف نفس فسه سهم في سبي بيل الل لله اول ولي ليك هم الص لصد صدق دقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2146, 'quran:49:16', 'quran', 'quran', '49:16', 16, 2145, 'Al-Hujurat', 'الحجرات', 'قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ', NULL, NULL, 'قل اتعلمون الله بدينكم والله يعلم ما في السموت وما في الارض والله بكل شيء عليم', 'قل اتعلم له بدين له يعلم م في سموت وم في ارض له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/49/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2146, 'قل اتع تعل علم لمو مون الل لله بدي دين ينك نكم ولل لله يعل علم م في الس لسم سمو موت وم في الر لرض ولل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2147, 'quran:49:17', 'quran', 'quran', '49:17', 17, 2146, 'Al-Hujurat', 'الحجرات', 'يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ', NULL, NULL, 'يمنون عليك ان اسلموا قل لا تمنوا علي اسلمكم بل الله يمن عليكم ان هداكم للايمن ان كنتم صدقين', 'يمن عليك ان اسلم قل ل تمن عل اسلم بل له يمن علي ان هد ايمن ان كنتم صدق', 'quran', NULL, NULL, 'https://quran.com/49/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2147, 'يمن منو نون علي ليك ان اسل سلم لمو قل ل تمن منو علي اسل سلم لمك مكم بل الل لله يمن علي ليك يكم ان هدك دكم للي ليم يمن ان كنت نتم صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2148, 'quran:49:18', 'quran', 'quran', '49:18', 18, 2147, 'Al-Hujurat', 'الحجرات', 'إِنَّ ٱللَّهَ يَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ', NULL, NULL, 'ان الله يعلم غيب السموت والارض والله بصير بما تعملون', 'ان له يعلم غيب سموت ارض له بصير بم تعمل', 'quran', NULL, NULL, 'https://quran.com/49/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2148, 'ان الل لله يعل علم غيب الس لسم سمو موت ولر لرض ولل لله بصي صير بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2149, 'quran:50:1', 'quran', 'quran', '50:1', 1, 2148, 'Qaf', 'ق', 'قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ', NULL, NULL, 'ق والقران المجيد', 'ق قر مجيد', 'quran', NULL, NULL, 'https://quran.com/50/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2149, 'ق ولق لقر قرن الم لمج مجي جيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2150, 'quran:50:2', 'quran', 'quran', '50:2', 2, 2149, 'Qaf', 'ق', 'بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡ فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ', NULL, NULL, 'بل عجبوا ان جاءهم منذر منهم فقال الكفرون هذا شيء عجيب', 'بل عجب ان جء منذر من قل كفر هذ شيء عجيب', 'quran', NULL, NULL, 'https://quran.com/50/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2150, 'بل عجب جبو ان جءه ءهم منذ نذر منه نهم فقل الك لكف كفر فرو رون هذ شيء عجي جيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2151, 'quran:50:3', 'quran', 'quran', '50:3', 3, 2150, 'Qaf', 'ق', 'أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗاۖ ذَٰلِكَ رَجۡعُۢ بَعِيدٞ', NULL, NULL, 'اءذا متنا وكنا ترابا ذلك رجع بعيد', 'اءذ مت كن ترب ذلك رجع بعيد', 'quran', NULL, NULL, 'https://quran.com/50/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2151, 'اءذ متن وكن ترب ذلك رجع بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2152, 'quran:50:4', 'quran', 'quran', '50:4', 4, 2151, 'Qaf', 'ق', 'قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ', NULL, NULL, 'قد علمنا ما تنقص الارض منهم وعندنا كتب حفيظ', 'قد علم م تنقص ارض من عند كتب حفيظ', 'quran', NULL, NULL, 'https://quran.com/50/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2152, 'قد علم لمن م تنق نقص الر لرض منه نهم وعن عند ندن كتب حفي فيظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2153, 'quran:50:5', 'quran', 'quran', '50:5', 5, 2152, 'Qaf', 'ق', 'بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ', NULL, NULL, 'بل كذبوا بالحق لما جاءهم فهم في امر مريج', 'بل كذب حق لم جء فهم في امر مريج', 'quran', NULL, NULL, 'https://quran.com/50/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2153, 'بل كذب ذبو بلح لحق لم جءه ءهم فهم في امر مري ريج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2154, 'quran:50:6', 'quran', 'quran', '50:6', 6, 2153, 'Qaf', 'ق', 'أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٖ', NULL, NULL, 'افلم ينظروا الي السماء فوقهم كيف بنينها وزينها وما لها من فروج', 'افلم ينظر ال سمء وق كيف بنين زين وم له من روج', 'quran', NULL, NULL, 'https://quran.com/50/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2154, 'افل فلم ينظ نظر ظرو الي الس لسم سمء فوق وقه قهم كيف بني نين ينه وزي زين ينه وم له من فرو روج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2155, 'quran:50:7', 'quran', 'quran', '50:7', 7, 2154, 'Qaf', 'ق', 'وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ', NULL, NULL, 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل زوج بهيج', 'ارض مددن قي يه روس انبت يه من كل زوج بهيج', 'quran', NULL, NULL, 'https://quran.com/50/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2155, 'ولر لرض مدد ددن دنه ولق لقي قين فيه روس وسي ونب نبت بتن فيه من كل زوج بهي هيج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2156, 'quran:50:8', 'quran', 'quran', '50:8', 8, 2155, 'Qaf', 'ق', 'تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ', NULL, NULL, 'تبصره وذكري لكل عبد منيب', 'تبصر ذكر لكل عبد منيب', 'quran', NULL, NULL, 'https://quran.com/50/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2156, 'تبص بصر صره وذك ذكر كري لكل عبد مني نيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2157, 'quran:50:9', 'quran', 'quran', '50:9', 9, 2156, 'Qaf', 'ق', 'وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتٖ وَحَبَّ ٱلۡحَصِيدِ', NULL, NULL, 'ونزلنا من السماء ماء مبركا فانبتنا به جنت وحب الحصيد', 'نزل من سمء مء مبرك انبت به جنت وحب حصيد', 'quran', NULL, NULL, 'https://quran.com/50/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2157, 'ونز نزل زلن من الس لسم سمء مء مبر برك فنب نبت بتن به جنت وحب الح لحص حصي صيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2158, 'quran:50:10', 'quran', 'quran', '50:10', 10, 2157, 'Qaf', 'ق', 'وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ', NULL, NULL, 'والنخل باسقت لها طلع نضيد', 'نخل بسقت له طلع نضيد', 'quran', NULL, NULL, 'https://quran.com/50/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2158, 'ولن لنخ نخل بسق سقت له طلع نضي ضيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2159, 'quran:50:11', 'quran', 'quran', '50:11', 11, 2158, 'Qaf', 'ق', 'رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ', NULL, NULL, 'رزقا للعباد واحيينا به بلده ميتا كذلك الخروج', 'رزق عبد احيي به بلد ميت كذلك خروج', 'quran', NULL, NULL, 'https://quran.com/50/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2159, 'رزق للع لعب عبد وحي حيي يين به بلد لده ميت كذل ذلك الخ لخر خرو روج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2160, 'quran:50:12', 'quran', 'quran', '50:12', 12, 2159, 'Qaf', 'ق', 'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ', NULL, NULL, 'كذبت قبلهم قوم نوح واصحب الرس وثمود', 'كذبت قبل قوم نوح اصحب رس ثمود', 'quran', NULL, NULL, 'https://quran.com/50/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2160, 'كذب ذبت قبل بله لهم قوم نوح وصح صحب الر لرس وثم ثمو مود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2161, 'quran:50:13', 'quran', 'quran', '50:13', 13, 2160, 'Qaf', 'ق', 'وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ', NULL, NULL, 'وعاد وفرعون واخون لوط', 'عد فرع اخ لوط', 'quran', NULL, NULL, 'https://quran.com/50/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2161, 'وعد وفر فرع رعو عون وخو خون لوط');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2162, 'quran:50:14', 'quran', 'quran', '50:14', 14, 2161, 'Qaf', 'ق', 'وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', NULL, NULL, 'واصحب الايكه وقوم تبع كل كذب الرسل فحق وعيد', 'اصحب ايك قوم تبع كل كذب رسل فحق عيد', 'quran', NULL, NULL, 'https://quran.com/50/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2162, 'وصح صحب الي ليك يكه وقو قوم تبع كل كذب الر لرس رسل فحق وعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2163, 'quran:50:15', 'quran', 'quran', '50:15', 15, 2162, 'Qaf', 'ق', 'أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسٖ مِّنۡ خَلۡقٖ جَدِيدٖ', NULL, NULL, 'افعيينا بالخلق الاول بل هم في لبس من خلق جديد', 'افعيي خلق اول بل هم في لبس من خلق جديد', 'quran', NULL, NULL, 'https://quran.com/50/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2163, 'افع فعي عيي يين بلخ لخل خلق الو لول بل هم في لبس من خلق جدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2164, 'quran:50:16', 'quran', 'quran', '50:16', 16, 2163, 'Qaf', 'ق', 'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ', NULL, NULL, 'ولقد خلقنا الانسن ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد', 'لقد خلق انسن نعلم م توسوس به نفس نحن اقرب يه من حبل وريد', 'quran', NULL, NULL, 'https://quran.com/50/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2164, 'ولق لقد خلق لقن الن لنس نسن ونع نعل علم م توس وسو سوس به نفس فسه ونح نحن اقر قرب الي ليه من حبل الو لور وري ريد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2165, 'quran:50:17', 'quran', 'quran', '50:17', 17, 2164, 'Qaf', 'ق', 'إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ', NULL, NULL, 'اذ يتلقي المتلقيان عن اليمين وعن الشمال قعيد', 'اذ يتلق متلقي عن يم وعن شمل قعيد', 'quran', NULL, NULL, 'https://quran.com/50/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2165, 'اذ يتل تلق لقي الم لمت متل تلق لقي قين عن الي ليم يمي مين وعن الش لشم شمل قعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2166, 'quran:50:18', 'quran', 'quran', '50:18', 18, 2165, 'Qaf', 'ق', 'مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ', NULL, NULL, 'ما يلفظ من قول الا لديه رقيب عتيد', 'م يلفظ من قول ال لد رقيب عتيد', 'quran', NULL, NULL, 'https://quran.com/50/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2166, 'م يلف لفظ من قول ال لدي ديه رقي قيب عتي تيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2167, 'quran:50:19', 'quran', 'quran', '50:19', 19, 2166, 'Qaf', 'ق', 'وَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ', NULL, NULL, 'وجاءت سكره الموت بالحق ذلك ما كنت منه تحيد', 'جءت سكر موت حق ذلك م كنت من تحيد', 'quran', NULL, NULL, 'https://quran.com/50/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2167, 'وجء جءت سكر كره الم لمو موت بلح لحق ذلك م كنت منه تحي حيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2168, 'quran:50:20', 'quran', 'quran', '50:20', 20, 2167, 'Qaf', 'ق', 'وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ', NULL, NULL, 'ونفخ في الصور ذلك يوم الوعيد', 'نفخ في صور ذلك يوم وعيد', 'quran', NULL, NULL, 'https://quran.com/50/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2168, 'ونف نفخ في الص لصو صور ذلك يوم الو لوع وعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2169, 'quran:50:21', 'quran', 'quran', '50:21', 21, 2168, 'Qaf', 'ق', 'وَجَآءَتۡ كُلُّ نَفۡسٖ مَّعَهَا سَآئِقٞ وَشَهِيدٞ', NULL, NULL, 'وجاءت كل نفس معها سايق وشهيد', 'جءت كل نفس مع سيق شهيد', 'quran', NULL, NULL, 'https://quran.com/50/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2169, 'وجء جءت كل نفس معه سيق وشه شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2170, 'quran:50:22', 'quran', 'quran', '50:22', 22, 2169, 'Qaf', 'ق', 'لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ', NULL, NULL, 'لقد كنت في غفله من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد', 'لقد كنت في غفل من هذ كشف عنك غطءك بصرك يوم حديد', 'quran', NULL, NULL, 'https://quran.com/50/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2170, 'لقد كنت في غفل فله من هذ فكش كشف شفن عنك غطء طءك فبص بصر صرك الي ليو يوم حدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2171, 'quran:50:23', 'quran', 'quran', '50:23', 23, 2170, 'Qaf', 'ق', 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ', NULL, NULL, 'وقال قرينه هذا ما لدي عتيد', 'قل قرين هذ م لد عتيد', 'quran', NULL, NULL, 'https://quran.com/50/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2171, 'وقل قري رين ينه هذ م لدي عتي تيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2172, 'quran:50:24', 'quran', 'quran', '50:24', 24, 2171, 'Qaf', 'ق', 'أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٖ', NULL, NULL, 'القيا في جهنم كل كفار عنيد', 'قي في جهنم كل كفر عنيد', 'quran', NULL, NULL, 'https://quran.com/50/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2172, 'الق لقي في جهن هنم كل كفر عني نيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2173, 'quran:50:25', 'quran', 'quran', '50:25', 25, 2172, 'Qaf', 'ق', 'مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٖ مُّرِيبٍ', NULL, NULL, 'مناع للخير معتد مريب', 'منع خير معتد مريب', 'quran', NULL, NULL, 'https://quran.com/50/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2173, 'منع للخ لخي خير معت عتد مري ريب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2174, 'quran:50:26', 'quran', 'quran', '50:26', 26, 2173, 'Qaf', 'ق', 'ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ', NULL, NULL, 'الذي جعل مع الله الها اخر فالقياه في العذاب الشديد', 'ذي جعل مع له ه اخر قي في عذب شديد', 'quran', NULL, NULL, 'https://quran.com/50/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2174, 'الذ لذي جعل مع الل لله اله اخر فلق لقي قيه في الع لعذ عذب الش لشد شدي ديد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2175, 'quran:50:27', 'quran', 'quran', '50:27', 27, 2174, 'Qaf', 'ق', 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ', NULL, NULL, 'قال قرينه ربنا ما اطغيته ولكن كان في ضلل بعيد', 'قل قرين رب م اطغيت لكن كن في ضلل بعيد', 'quran', NULL, NULL, 'https://quran.com/50/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2175, 'قل قري رين ينه ربن م اطغ طغي غيت يته ولك لكن كن في ضلل بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2176, 'quran:50:28', 'quran', 'quran', '50:28', 28, 2175, 'Qaf', 'ق', 'قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ', NULL, NULL, 'قال لا تختصموا لدي وقد قدمت اليكم بالوعيد', 'قل ل تختصم لد وقد قدمت يكم وعيد', 'quran', NULL, NULL, 'https://quran.com/50/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2176, 'قل ل تخت ختص تصم صمو لدي وقد قدم دمت الي ليك يكم بلو لوع وعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2177, 'quran:50:29', 'quran', 'quran', '50:29', 29, 2176, 'Qaf', 'ق', 'مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّٰمٖ لِّلۡعَبِيدِ', NULL, NULL, 'ما يبدل القول لدي وما انا بظلم للعبيد', 'م يبدل قول لد وم ان بظلم عبيد', 'quran', NULL, NULL, 'https://quran.com/50/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2177, 'م يبد بدل الق لقو قول لدي وم ان بظل ظلم للع لعب عبي بيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2178, 'quran:50:30', 'quran', 'quran', '50:30', 30, 2177, 'Qaf', 'ق', 'يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ', NULL, NULL, 'يوم نقول لجهنم هل امتلات وتقول هل من مزيد', 'يوم نقول لجهنم هل امتل تقول هل من مزيد', 'quran', NULL, NULL, 'https://quran.com/50/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2178, 'يوم نقو قول لجه جهن هنم هل امت متل تلت وتق تقو قول هل من مزي زيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2179, 'quran:50:31', 'quran', 'quran', '50:31', 31, 2178, 'Qaf', 'ق', 'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ', NULL, NULL, 'وازلفت الجنه للمتقين غير بعيد', 'ازلفت جن متق غير بعيد', 'quran', NULL, NULL, 'https://quran.com/50/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2179, 'وزل زلف لفت الج لجن جنه للم لمت متق تقي قين غير بعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2180, 'quran:50:32', 'quran', 'quran', '50:32', 32, 2179, 'Qaf', 'ق', 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ', NULL, NULL, 'هذا ما توعدون لكل اواب حفيظ', 'هذ م توعد لكل اوب حفيظ', 'quran', NULL, NULL, 'https://quran.com/50/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2180, 'هذ م توع وعد عدو دون لكل اوب حفي فيظ');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2181, 'quran:50:33', 'quran', 'quran', '50:33', 33, 2180, 'Qaf', 'ق', 'مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ', NULL, NULL, 'من خشي الرحمن بالغيب وجاء بقلب منيب', 'من خش رحمن غيب جء بقلب منيب', 'quran', NULL, NULL, 'https://quran.com/50/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2181, 'من خشي الر لرح رحم حمن بلغ لغي غيب وجء بقل قلب مني نيب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2182, 'quran:50:34', 'quran', 'quran', '50:34', 34, 2181, 'Qaf', 'ق', 'ٱدۡخُلُوهَا بِسَلَٰمٖۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ', NULL, NULL, 'ادخلوها بسلم ذلك يوم الخلود', 'ادخلو بسلم ذلك يوم خلود', 'quran', NULL, NULL, 'https://quran.com/50/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2182, 'ادخ دخل خلو لوه بسل سلم ذلك يوم الخ لخل خلو لود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2183, 'quran:50:35', 'quran', 'quran', '50:35', 35, 2182, 'Qaf', 'ق', 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدٞ', NULL, NULL, 'لهم ما يشاءون فيها ولدينا مزيد', 'لهم م يشء يه لدي مزيد', 'quran', NULL, NULL, 'https://quran.com/50/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2183, 'لهم م يشء شءو ءون فيه ولد لدي دين مزي زيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2184, 'quran:50:36', 'quran', 'quran', '50:36', 36, 2183, 'Qaf', 'ق', 'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ', NULL, NULL, 'وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلد هل من محيص', 'وكم اهلك قبل من قرن هم اشد من بطش نقب في بلد هل من محيص', 'quran', NULL, NULL, 'https://quran.com/50/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2184, 'وكم اهل هلك لكن قبل بله لهم من قرن هم اشد منه نهم بطش فنق نقب قبو في الب لبل بلد هل من محي حيص');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2185, 'quran:50:37', 'quran', 'quran', '50:37', 37, 2184, 'Qaf', 'ق', 'إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ', NULL, NULL, 'ان في ذلك لذكري لمن كان له قلب او القي السمع وهو شهيد', 'ان في ذلك لذكر لمن كن له قلب او قي سمع وهو شهيد', 'quran', NULL, NULL, 'https://quran.com/50/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2185, 'ان في ذلك لذك ذكر كري لمن كن له قلب او الق لقي الس لسم سمع وهو شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2186, 'quran:50:38', 'quran', 'quran', '50:38', 38, 2185, 'Qaf', 'ق', 'وَلَقَدۡ خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ وَمَا مَسَّنَا مِن لُّغُوبٖ', NULL, NULL, 'ولقد خلقنا السموت والارض وما بينهما في سته ايام وما مسنا من لغوب', 'لقد خلق سموت ارض وم بينهم في ست ايم وم مس من لغوب', 'quran', NULL, NULL, 'https://quran.com/50/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2186, 'ولق لقد خلق لقن الس لسم سمو موت ولر لرض وم بين ينه نهم في سته ايم وم مسن من لغو غوب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2187, 'quran:50:39', 'quran', 'quran', '50:39', 39, 2186, 'Qaf', 'ق', 'فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ', NULL, NULL, 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب', 'اصبر عل م يقول سبح بحمد ربك قبل طلوع شمس قبل غروب', 'quran', NULL, NULL, 'https://quran.com/50/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2187, 'فصب صبر علي م يقو قول ولو لون وسب سبح بحم حمد ربك قبل طلو لوع الش لشم شمس وقب قبل الغ لغر غرو روب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2188, 'quran:50:40', 'quran', 'quran', '50:40', 40, 2187, 'Qaf', 'ق', 'وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ', NULL, NULL, 'ومن اليل فسبحه وادبر السجود', 'ومن يل سبح ادبر سجود', 'quran', NULL, NULL, 'https://quran.com/50/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2188, 'ومن الي ليل فسب سبح بحه ودب دبر الس لسج سجو جود');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2189, 'quran:50:41', 'quran', 'quran', '50:41', 41, 2188, 'Qaf', 'ق', 'وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانٖ قَرِيبٖ', NULL, NULL, 'واستمع يوم يناد المناد من مكان قريب', 'استمع يوم يند مند من مك قريب', 'quran', NULL, NULL, 'https://quran.com/50/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2189, 'وست ستم تمع يوم يند الم لمن مند من مكن قري ريب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2190, 'quran:50:42', 'quran', 'quran', '50:42', 42, 2189, 'Qaf', 'ق', 'يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ', NULL, NULL, 'يوم يسمعون الصيحه بالحق ذلك يوم الخروج', 'يوم يسمع صيح حق ذلك يوم خروج', 'quran', NULL, NULL, 'https://quran.com/50/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2190, 'يوم يسم سمع معو عون الص لصي صيح يحه بلح لحق ذلك يوم الخ لخر خرو روج');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2191, 'quran:50:43', 'quran', 'quran', '50:43', 43, 2190, 'Qaf', 'ق', 'إِنَّا نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ', NULL, NULL, 'انا نحن نحي ونميت والينا المصير', 'ان نحن نح نميت ين مصير', 'quran', NULL, NULL, 'https://quran.com/50/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2191, 'ان نحن نحي ونم نمي ميت ولي لين الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2192, 'quran:50:44', 'quran', 'quran', '50:44', 44, 2191, 'Qaf', 'ق', 'يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعٗاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرٞ', NULL, NULL, 'يوم تشقق الارض عنهم سراعا ذلك حشر علينا يسير', 'يوم تشقق ارض عن سرع ذلك حشر علي يسير', 'quran', NULL, NULL, 'https://quran.com/50/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2192, 'يوم تشق شقق الر لرض عنه نهم سرع ذلك حشر علي لين يسي سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2193, 'quran:50:45', 'quran', 'quran', '50:45', 45, 2192, 'Qaf', 'ق', 'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ', NULL, NULL, 'نحن اعلم بما يقولون وما انت عليهم بجبار فذكر بالقران من يخاف وعيد', 'نحن اعلم بم يقول وم انت علي بجبر ذكر قر من يخف عيد', 'quran', NULL, NULL, 'https://quran.com/50/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2193, 'نحن اعل علم بم يقو قول ولو لون وم انت علي ليه يهم بجب جبر فذك ذكر بلق لقر قرن من يخف وعي عيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2194, 'quran:52:1', 'quran', 'quran', '52:1', 1, 2193, 'At-Tur', 'الطور', 'وَٱلطُّورِ', NULL, NULL, 'والطور', 'طور', 'quran', NULL, NULL, 'https://quran.com/52/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2194, 'ولط لطو طور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2195, 'quran:52:2', 'quran', 'quran', '52:2', 2, 2194, 'At-Tur', 'الطور', 'وَكِتَٰبٖ مَّسۡطُورٖ', NULL, NULL, 'وكتب مسطور', 'كتب مسطور', 'quran', NULL, NULL, 'https://quran.com/52/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2195, 'وكت كتب مسط سطو طور');
