INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2198, 'quran:52:5', 'quran', 'quran', '52:5', 5, 2197, 'At-Tur', 'الطور', 'وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ', NULL, NULL, 'والسقف المرفوع', 'سقف مرفوع', 'quran', NULL, NULL, 'https://quran.com/52/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2198, 'ولس لسق سقف الم لمر مرف رفو فوع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2199, 'quran:52:6', 'quran', 'quran', '52:6', 6, 2198, 'At-Tur', 'الطور', 'وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ', NULL, NULL, 'والبحر المسجور', 'بحر مسجور', 'quran', NULL, NULL, 'https://quran.com/52/6');
