INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2200, 'quran:52:7', 'quran', 'quran', '52:7', 7, 2199, 'At-Tur', 'الطور', 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ', NULL, NULL, 'ان عذاب ربك لوقع', 'ان عذب ربك لوقع', 'quran', NULL, NULL, 'https://quran.com/52/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2200, 'ان عذب ربك لوق وقع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2201, 'quran:52:8', 'quran', 'quran', '52:8', 8, 2200, 'At-Tur', 'الطور', 'مَّا لَهُۥ مِن دَافِعٖ', NULL, NULL, 'ما له من دافع', 'م له من دفع', 'quran', NULL, NULL, 'https://quran.com/52/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2201, 'م له من دفع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2202, 'quran:52:9', 'quran', 'quran', '52:9', 9, 2201, 'At-Tur', 'الطور', 'يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرٗا', NULL, NULL, 'يوم تمور السماء مورا', 'يوم تمور سمء مور', 'quran', NULL, NULL, 'https://quran.com/52/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2202, 'يوم تمو مور الس لسم سمء مور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2203, 'quran:52:10', 'quran', 'quran', '52:10', 10, 2202, 'At-Tur', 'الطور', 'وَتَسِيرُ ٱلۡجِبَالُ سَيۡرٗا', NULL, NULL, 'وتسير الجبال سيرا', 'تسير جبل سير', 'quran', NULL, NULL, 'https://quran.com/52/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2203, 'وتس تسي سير الج لجب جبل سير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2204, 'quran:52:11', 'quran', 'quran', '52:11', 11, 2203, 'At-Tur', 'الطور', 'فَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ', NULL, NULL, 'فويل يوميذ للمكذبين', 'ويل يوميذ مكذب', 'quran', NULL, NULL, 'https://quran.com/52/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2204, 'فوي ويل يوم ومي ميذ للم لمك مكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2205, 'quran:52:12', 'quran', 'quran', '52:12', 12, 2204, 'At-Tur', 'الطور', 'ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ', NULL, NULL, 'الذين هم في خوض يلعبون', 'ذين هم في خوض يلعب', 'quran', NULL, NULL, 'https://quran.com/52/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2205, 'الذ لذي ذين هم في خوض يلع لعب عبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2206, 'quran:52:13', 'quran', 'quran', '52:13', 13, 2205, 'At-Tur', 'الطور', 'يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', NULL, NULL, 'يوم يدعون الي نار جهنم دعا', 'يوم يدع ال نر جهنم دع', 'quran', NULL, NULL, 'https://quran.com/52/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2206, 'يوم يدع دعو عون الي نر جهن هنم دع');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2207, 'quran:52:14', 'quran', 'quran', '52:14', 14, 2206, 'At-Tur', 'الطور', 'هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ', NULL, NULL, 'هذه النار التي كنتم بها تكذبون', 'هذ نر تي كنتم به تكذب', 'quran', NULL, NULL, 'https://quran.com/52/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2207, 'هذه الن لنر الت لتي كنت نتم به تكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2208, 'quran:52:15', 'quran', 'quran', '52:15', 15, 2207, 'At-Tur', 'الطور', 'أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ', NULL, NULL, 'افسحر هذا ام انتم لا تبصرون', 'افسحر هذ ام انتم ل تبصر', 'quran', NULL, NULL, 'https://quran.com/52/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2208, 'افس فسح سحر هذ ام انت نتم ل تبص بصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2209, 'quran:52:16', 'quran', 'quran', '52:16', 16, 2208, 'At-Tur', 'الطور', 'ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'اصلوها فاصبروا او لا تصبروا سواء عليكم انما تجزون ما كنتم تعملون', 'اصلو اصبر او ل تصبر سوء علي انم تجز م كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/52/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2209, 'اصل صلو لوه فصب صبر برو او ل تصب صبر برو سوء علي ليك يكم انم تجز جزو زون م كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2210, 'quran:52:17', 'quran', 'quran', '52:17', 17, 2209, 'At-Tur', 'الطور', 'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَنَعِيمٖ', NULL, NULL, 'ان المتقين في جنت ونعيم', 'ان متق في جنت نعيم', 'quran', NULL, NULL, 'https://quran.com/52/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2210, 'ان الم لمت متق تقي قين في جنت ونع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2211, 'quran:52:18', 'quran', 'quran', '52:18', 18, 2210, 'At-Tur', 'الطور', 'فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ', NULL, NULL, 'فكهين بما اتاهم ربهم ووقاهم ربهم عذاب الجحيم', 'كه بم ات رب وق رب عذب جحيم', 'quran', NULL, NULL, 'https://quran.com/52/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2211, 'فكه كهي هين بم اته تهم ربه بهم ووق وقه قهم ربه بهم عذب الج لجح جحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2212, 'quran:52:19', 'quran', 'quran', '52:19', 19, 2211, 'At-Tur', 'الطور', 'كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'كلوا واشربوا هنيا بما كنتم تعملون', 'كل اشرب هني بم كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/52/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2212, 'كلو وشر شرب ربو هني بم كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2213, 'quran:52:20', 'quran', 'quran', '52:20', 20, 2212, 'At-Tur', 'الطور', 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ', NULL, NULL, 'متكين علي سرر مصفوفه وزوجنهم بحور عين', 'متك عل سرر مصفوف زوجن بحور عين', 'quran', NULL, NULL, 'https://quran.com/52/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2213, 'متك تكي كين علي سرر مصف صفو فوف وفه وزو زوج وجن جنه نهم بحو حور عين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2214, 'quran:52:21', 'quran', 'quran', '52:21', 21, 2213, 'At-Tur', 'الطور', 'وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينٞ', NULL, NULL, 'والذين امنوا واتبعتهم ذريتهم بايمن الحقنا بهم ذريتهم وما التنهم من عملهم من شيء كل امري بما كسب رهين', 'ذين امن اتبعت ذريت بيمن حق بهم ذريت وم تن من عمل من شيء كل امر بم كسب ره', 'quran', NULL, NULL, 'https://quran.com/52/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2214, 'ولذ لذي ذين امن منو وتب تبع بعت عته تهم ذري ريت يته تهم بيم يمن الح لحق حقن بهم ذري ريت يته تهم وم الت لتن تنه نهم من عمل مله لهم من شيء كل امر مري بم كسب رهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2215, 'quran:52:22', 'quran', 'quran', '52:22', 22, 2214, 'At-Tur', 'الطور', 'وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ', NULL, NULL, 'وامددنهم بفكهه ولحم مما يشتهون', 'امددن بفكه لحم مم يشته', 'quran', NULL, NULL, 'https://quran.com/52/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2215, 'ومد مدد ددن دنه نهم بفك فكه كهه ولح لحم مم يشت شته تهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2216, 'quran:52:23', 'quran', 'quran', '52:23', 23, 2215, 'At-Tur', 'الطور', 'يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ', NULL, NULL, 'يتنزعون فيها كاسا لا لغو فيها ولا تاثيم', 'يتنزع يه كس ل لغو يه ول تثيم', 'quran', NULL, NULL, 'https://quran.com/52/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2216, 'يتن تنز نزع زعو عون فيه كس ل لغو فيه ول تثي ثيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2217, 'quran:52:24', 'quran', 'quran', '52:24', 24, 2216, 'At-Tur', 'الطور', 'وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ', NULL, NULL, 'ويطوف عليهم غلمان لهم كانهم لولو مكنون', 'يطوف علي غلم لهم كن لولو مكن', 'quran', NULL, NULL, 'https://quran.com/52/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2217, 'ويط يطو طوف علي ليه يهم غلم لمن لهم كنه نهم لول ولو مكن كنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2218, 'quran:52:25', 'quran', 'quran', '52:25', 25, 2217, 'At-Tur', 'الطور', 'وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ', NULL, NULL, 'واقبل بعضهم علي بعض يتساءلون', 'اقبل بعض عل بعض يتسءل', 'quran', NULL, NULL, 'https://quran.com/52/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2218, 'وقب قبل بعض عضه ضهم علي بعض يتس تسء سءل ءلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2219, 'quran:52:26', 'quran', 'quran', '52:26', 26, 2218, 'At-Tur', 'الطور', 'قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ', NULL, NULL, 'قالوا انا كنا قبل في اهلنا مشفقين', 'قل ان كن قبل في اهل مشفق', 'quran', NULL, NULL, 'https://quran.com/52/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2219, 'قلو ان كن قبل في اهل هلن مشف شفق فقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2220, 'quran:52:27', 'quran', 'quran', '52:27', 27, 2219, 'At-Tur', 'الطور', 'فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', NULL, NULL, 'فمن الله علينا ووقانا عذاب السموم', 'فمن له علي وق عذب سموم', 'quran', NULL, NULL, 'https://quran.com/52/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2220, 'فمن الل لله علي لين ووق وقن عذب الس لسم سمو موم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2221, 'quran:52:28', 'quran', 'quran', '52:28', 28, 2220, 'At-Tur', 'الطور', 'إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ', NULL, NULL, 'انا كنا من قبل ندعوه انه هو البر الرحيم', 'ان كن من قبل ندعو ان هو بر رحيم', 'quran', NULL, NULL, 'https://quran.com/52/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2221, 'ان كن من قبل ندع دعو عوه انه هو الب لبر الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2222, 'quran:52:29', 'quran', 'quran', '52:29', 29, 2221, 'At-Tur', 'الطور', 'فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنٖ وَلَا مَجۡنُونٍ', NULL, NULL, 'فذكر فما انت بنعمت ربك بكاهن ولا مجنون', 'ذكر فم انت بنعمت ربك بك ول مجن', 'quran', NULL, NULL, 'https://quran.com/52/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2222, 'فذك ذكر فم انت بنع نعم عمت ربك بكه كهن ول مجن جنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2223, 'quran:52:30', 'quran', 'quran', '52:30', 30, 2222, 'At-Tur', 'الطور', 'أَمۡ يَقُولُونَ شَاعِرٞ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ', NULL, NULL, 'ام يقولون شاعر نتربص به ريب المنون', 'ام يقول شعر نتربص به ريب من', 'quran', NULL, NULL, 'https://quran.com/52/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2223, 'ام يقو قول ولو لون شعر نتر ترب ربص به ريب الم لمن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2224, 'quran:52:31', 'quran', 'quran', '52:31', 31, 2223, 'At-Tur', 'الطور', 'قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ', NULL, NULL, 'قل تربصوا فاني معكم من المتربصين', 'قل تربص ان مع من متربص', 'quran', NULL, NULL, 'https://quran.com/52/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2224, 'قل ترب ربص بصو فني معك عكم من الم لمت متر ترب ربص بصي صين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2225, 'quran:52:32', 'quran', 'quran', '52:32', 32, 2224, 'At-Tur', 'الطور', 'أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ', NULL, NULL, 'ام تامرهم احلمهم بهذا ام هم قوم طاغون', 'ام تمر احلم بهذ ام هم قوم طغ', 'quran', NULL, NULL, 'https://quran.com/52/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2225, 'ام تمر مره رهم احل حلم لمه مهم بهذ ام هم قوم طغو غون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2226, 'quran:52:33', 'quran', 'quran', '52:33', 33, 2225, 'At-Tur', 'الطور', 'أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ', NULL, NULL, 'ام يقولون تقوله بل لا يومنون', 'ام يقول تقول بل ل يومن', 'quran', NULL, NULL, 'https://quran.com/52/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2226, 'ام يقو قول ولو لون تقو قول وله بل ل يوم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2227, 'quran:52:34', 'quran', 'quran', '52:34', 34, 2226, 'At-Tur', 'الطور', 'فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ', NULL, NULL, 'فلياتوا بحديث مثله ان كانوا صدقين', 'ليت بحديث مثل ان كن صدق', 'quran', NULL, NULL, 'https://quran.com/52/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2227, 'فلي ليت يتو بحد حدي ديث مثل ثله ان كنو صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2228, 'quran:52:35', 'quran', 'quran', '52:35', 35, 2227, 'At-Tur', 'الطور', 'أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ', NULL, NULL, 'ام خلقوا من غير شيء ام هم الخلقون', 'ام خلق من غير شيء ام هم خلق', 'quran', NULL, NULL, 'https://quran.com/52/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2228, 'ام خلق لقو من غير شيء ام هم الخ لخل خلق لقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2229, 'quran:52:36', 'quran', 'quran', '52:36', 36, 2228, 'At-Tur', 'الطور', 'أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ', NULL, NULL, 'ام خلقوا السموت والارض بل لا يوقنون', 'ام خلق سموت ارض بل ل يوقن', 'quran', NULL, NULL, 'https://quran.com/52/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2229, 'ام خلق لقو الس لسم سمو موت ولر لرض بل ل يوق وقن قنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2230, 'quran:52:37', 'quran', 'quran', '52:37', 37, 2229, 'At-Tur', 'الطور', 'أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ', NULL, NULL, 'ام عندهم خزاين ربك ام هم المصيطرون', 'ام عند خز ربك ام هم مصيطر', 'quran', NULL, NULL, 'https://quran.com/52/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2230, 'ام عند نده دهم خزي زين ربك ام هم الم لمص مصي صيط يطر طرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2231, 'quran:52:38', 'quran', 'quran', '52:38', 38, 2230, 'At-Tur', 'الطور', 'أَمۡ لَهُمۡ سُلَّمٞ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنٖ مُّبِينٍ', NULL, NULL, 'ام لهم سلم يستمعون فيه فليات مستمعهم بسلطن مبين', 'ام لهم سلم يستمع في لي مستمع بسلطن مب', 'quran', NULL, NULL, 'https://quran.com/52/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2231, 'ام لهم سلم يست ستم تمع معو عون فيه فلي ليت مست ستم تمع معه عهم بسل سلط لطن مبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2232, 'quran:52:39', 'quran', 'quran', '52:39', 39, 2231, 'At-Tur', 'الطور', 'أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ', NULL, NULL, 'ام له البنت ولكم البنون', 'ام له بنت لكم بن', 'quran', NULL, NULL, 'https://quran.com/52/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2232, 'ام له الب لبن بنت ولك لكم الب لبن بنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2233, 'quran:52:40', 'quran', 'quran', '52:40', 40, 2232, 'At-Tur', 'الطور', 'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ', NULL, NULL, 'ام تسلهم اجرا فهم من مغرم مثقلون', 'ام تسل اجر فهم من مغرم مثقل', 'quran', NULL, NULL, 'https://quran.com/52/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2233, 'ام تسل سله لهم اجر فهم من مغر غرم مثق ثقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2234, 'quran:52:41', 'quran', 'quran', '52:41', 41, 2233, 'At-Tur', 'الطور', 'أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ', NULL, NULL, 'ام عندهم الغيب فهم يكتبون', 'ام عند غيب فهم يكتب', 'quran', NULL, NULL, 'https://quran.com/52/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2234, 'ام عند نده دهم الغ لغي غيب فهم يكت كتب تبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2235, 'quran:52:42', 'quran', 'quran', '52:42', 42, 2234, 'At-Tur', 'الطور', 'أَمۡ يُرِيدُونَ كَيۡدٗاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ', NULL, NULL, 'ام يريدون كيدا فالذين كفروا هم المكيدون', 'ام يريد كيد ذين كفر هم مكيد', 'quran', NULL, NULL, 'https://quran.com/52/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2235, 'ام يري ريد يدو دون كيد فلذ لذي ذين كفر فرو هم الم لمك مكي كيد يدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2236, 'quran:52:43', 'quran', 'quran', '52:43', 43, 2235, 'At-Tur', 'الطور', 'أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ', NULL, NULL, 'ام لهم اله غير الله سبحن الله عما يشركون', 'ام لهم ال غير له سبحن له عم يشرك', 'quran', NULL, NULL, 'https://quran.com/52/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2236, 'ام لهم اله غير الل لله سبح بحن الل لله عم يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2237, 'quran:52:44', 'quran', 'quran', '52:44', 44, 2236, 'At-Tur', 'الطور', 'وَإِن يَرَوۡاْ كِسۡفٗا مِّنَ ٱلسَّمَآءِ سَاقِطٗا يَقُولُواْ سَحَابٞ مَّرۡكُومٞ', NULL, NULL, 'وان يروا كسفا من السماء ساقطا يقولوا سحاب مركوم', 'ون ير كسف من سمء سقط يقول سحب مركوم', 'quran', NULL, NULL, 'https://quran.com/52/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2237, 'ون يرو كسف من الس لسم سمء سقط يقو قول ولو سحب مرك ركو كوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2238, 'quran:52:45', 'quran', 'quran', '52:45', 45, 2237, 'At-Tur', 'الطور', 'فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ', NULL, NULL, 'فذرهم حتي يلقوا يومهم الذي فيه يصعقون', 'ذر حت يلق يوم ذي في يصعق', 'quran', NULL, NULL, 'https://quran.com/52/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2238, 'فذر ذره رهم حتي يلق لقو يوم ومه مهم الذ لذي فيه يصع صعق عقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2239, 'quran:52:46', 'quran', 'quran', '52:46', 46, 2238, 'At-Tur', 'الطور', 'يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ', NULL, NULL, 'يوم لا يغني عنهم كيدهم شيا ولا هم ينصرون', 'يوم ل يغن عن كيد شي ول هم ينصر', 'quran', NULL, NULL, 'https://quran.com/52/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2239, 'يوم ل يغن غني عنه نهم كيد يده دهم شي ول هم ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2240, 'quran:52:47', 'quran', 'quran', '52:47', 47, 2239, 'At-Tur', 'الطور', 'وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', NULL, NULL, 'وان للذين ظلموا عذابا دون ذلك ولكن اكثرهم لا يعلمون', 'ون ذين ظلم عذب دون ذلك لكن اكثر ل يعلم', 'quran', NULL, NULL, 'https://quran.com/52/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2240, 'ون للذ لذي ذين ظلم لمو عذب دون ذلك ولك لكن اكث كثر ثره رهم ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2241, 'quran:52:48', 'quran', 'quran', '52:48', 48, 2240, 'At-Tur', 'الطور', 'وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ', NULL, NULL, 'واصبر لحكم ربك فانك باعيننا وسبح بحمد ربك حين تقوم', 'اصبر لح ربك انك بعين سبح بحمد ربك حين تقوم', 'quran', NULL, NULL, 'https://quran.com/52/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2241, 'وصب صبر لحك حكم ربك فنك بعي عين ينن وسب سبح بحم حمد ربك حين تقو قوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2242, 'quran:52:49', 'quran', 'quran', '52:49', 49, 2241, 'At-Tur', 'الطور', 'وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ', NULL, NULL, 'ومن اليل فسبحه وادبر النجوم', 'ومن يل سبح ادبر نجوم', 'quran', NULL, NULL, 'https://quran.com/52/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2242, 'ومن الي ليل فسب سبح بحه ودب دبر الن لنج نجو جوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2243, 'quran:58:1', 'quran', 'quran', '58:1', 1, 2242, 'Al-Mujadila', 'المجادلة', 'قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ', NULL, NULL, 'قد سمع الله قول التي تجدلك في زوجها وتشتكي الي الله والله يسمع تحاوركما ان الله سميع بصير', 'قد سمع له قول تي تجدلك في زوج تشتك ال له له يسمع تحوركم ان له سميع بصير', 'quran', NULL, NULL, 'https://quran.com/58/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2243, 'قد سمع الل لله قول الت لتي تجد جدل دلك في زوج وجه وتش تشت شتك تكي الي الل لله ولل لله يسم سمع تحو حور ورك ركم ان الل لله سمي ميع بصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2244, 'quran:58:2', 'quran', 'quran', '58:2', 2, 2243, 'Al-Mujadila', 'المجادلة', 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ', NULL, NULL, 'الذين يظهرون منكم من نسايهم ما هن امهتهم ان امهتهم الا الي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور', 'ذين يظهر من من نسي م هن امهت ان امهت ال ال لدن ان ليقول منكر من قول زور ون له لعفو غفور', 'quran', NULL, NULL, 'https://quran.com/58/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2244, 'الذ لذي ذين يظه ظهر هرو رون منك نكم من نسي سيه يهم م هن امه مهت هته تهم ان امه مهت هته تهم ال الي ولد لدن دنه نهم ونه نهم ليق يقو قول ولو لون منك نكر من الق لقو قول وزو زور ون الل لله لعف عفو غفو فور');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2245, 'quran:58:3', 'quran', 'quran', '58:3', 3, 2244, 'Al-Mujadila', 'المجادلة', 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'والذين يظهرون من نسايهم ثم يعودون لما قالوا فتحرير رقبه من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير', 'ذين يظهر من نسي ثم يعود لم قل تحرير رقب من قبل ان يتمس ذل توعظ به له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/58/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2245, 'ولذ لذي ذين يظه ظهر هرو رون من نسي سيه يهم ثم يعو عود ودو دون لم قلو فتح تحر حري رير رقب قبه من قبل ان يتم تمس ذلك لكم توع وعظ عظو ظون به ولل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2246, 'quran:58:4', 'quran', 'quran', '58:4', 4, 2245, 'Al-Mujadila', 'المجادلة', 'فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ', NULL, NULL, 'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتومنوا بالله ورسوله وتلك حدود الله وللكفرين عذاب اليم', 'فمن لم يجد صيم شهر متتبع من قبل ان يتمس فمن لم يستطع اطعم ست مسكي ذلك لتومن له رسول تلك حدود له كفر عذب يم', 'quran', NULL, NULL, 'https://quran.com/58/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2246, 'فمن لم يجد فصي صيم شهر هري رين متت تتب تبع بعي عين من قبل ان يتم تمس فمن لم يست ستط تطع فطع طعم ستي تين مسك سكي كين ذلك لتو توم ومن منو بلل لله ورس رسو سول وله وتل تلك حدو دود الل لله ولل للك لكف كفر فري رين عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2247, 'quran:58:5', 'quran', 'quran', '58:5', 5, 2246, 'Al-Mujadila', 'المجادلة', 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ', NULL, NULL, 'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايت بينت وللكفرين عذاب مهين', 'ان ذين يحد له رسول كبت كم كبت ذين من قبل وقد انزل ايت بينت كفر عذب مه', 'quran', NULL, NULL, 'https://quran.com/58/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2247, 'ان الذ لذي ذين يحد حدو دون الل لله ورس رسو سول وله كبت بتو كم كبت الذ لذي ذين من قبل بله لهم وقد انز نزل زلن ايت بين ينت ولل للك لكف كفر فري رين عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2248, 'quran:58:6', 'quran', 'quran', '58:6', 6, 2247, 'Al-Mujadila', 'المجادلة', 'يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ', NULL, NULL, 'يوم يبعثهم الله جميعا فينبيهم بما عملوا احصاه الله ونسوه والله علي كل شيء شهيد', 'يوم يبعث له جميع ينبي بم عمل احص له نسو له عل كل شيء شهيد', 'quran', NULL, NULL, 'https://quran.com/58/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2248, 'يوم يبع بعث عثه ثهم الل لله جمي ميع فين ينب نبي بيه يهم بم عمل ملو احص حصه الل لله ونس نسو سوه ولل لله علي كل شيء شهي هيد');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2249, 'quran:58:7', 'quran', 'quran', '58:7', 7, 2248, 'Al-Mujadila', 'المجادلة', 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ', NULL, NULL, 'الم تر ان الله يعلم ما في السموت وما في الارض ما يكون من نجوي ثلثه الا هو رابعهم ولا خمسه الا هو سادسهم ولا ادني من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبيهم بما عملوا يوم القيمه ان الله بكل شيء عليم', 'الم تر ان له يعلم م في سموت وم في ارض م يك من نجو ثلث ال هو ربع ول خمس ال هو سدس ول ادن من ذلك ول اكثر ال هو مع اين م كن ثم ينبي بم عمل يوم قيم ان له بكل شيء عليم', 'quran', NULL, NULL, 'https://quran.com/58/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2249, 'الم تر ان الل لله يعل علم م في الس لسم سمو موت وم في الر لرض م يكو كون من نجو جوي ثلث لثه ال هو ربع بعه عهم ول خمس مسه ال هو سدس دسه سهم ول ادن دني من ذلك ول اكث كثر ال هو معه عهم اين م كنو ثم ينب نبي بيه يهم بم عمل ملو يوم الق لقي قيم يمه ان الل لله بكل شيء علي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2250, 'quran:58:8', 'quran', 'quran', '58:8', 8, 2249, 'Al-Mujadila', 'المجادلة', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ', NULL, NULL, 'الم تر الي الذين نهوا عن النجوي ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبيس المصير', 'الم تر ال ذين نه عن نجو ثم يعود لم نه عن يتنج اثم عد معصيت رسول اذ جءوك حيوك بم لم يحيك به له يقول في انفس لول يعذب له بم نقول حسب جهنم يصلون بيس مصير', 'quran', NULL, NULL, 'https://quran.com/58/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2250, 'الم تر الي الذ لذي ذين نهو عن الن لنج نجو جوي ثم يعو عود ودو دون لم نهو عنه ويت يتن تنج نجو جون بلث لثم ولع لعد عدو دون ومع معص عصي صيت الر لرس رسو سول وذ جءو ءوك حيو يوك بم لم يحي حيك به الل لله ويق يقو قول ولو لون في انف نفس فسه سهم لول يعذ عذب ذبن الل لله بم نقو قول حسب سبه بهم جهن هنم يصل صلو لون ونه فبي بيس الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2251, 'quran:58:9', 'quran', 'quran', '58:9', 9, 2250, 'Al-Mujadila', 'المجادلة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ', NULL, NULL, 'يا ايها الذين امنوا اذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت الرسول وتنجوا بالبر والتقوي واتقوا الله الذي اليه تحشرون', 'ي اي ذين امن اذ تنجيتم فل تتنج اثم عد معصيت رسول تنج بر تقو اتق له ذي يه تحشر', 'quran', NULL, NULL, 'https://quran.com/58/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2251, 'ي ايه الذ لذي ذين امن منو اذ تنج نجي جيت يتم فل تتن تنج نجو بلث لثم ولع لعد عدو دون ومع معص عصي صيت الر لرس رسو سول وتن تنج نجو بلب لبر ولت لتق تقو قوي وتق تقو الل لله الذ لذي الي ليه تحش حشر شرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2252, 'quran:58:10', 'quran', 'quran', '58:10', 10, 2251, 'Al-Mujadila', 'المجادلة', 'إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', NULL, NULL, 'انما النجوي من الشيطن ليحزن الذين امنوا وليس بضارهم شيا الا باذن الله وعلي الله فليتوكل المومنون', 'انم نجو من شيطن ليحزن ذين امن ليس بضر شي ال بذن له عل له ليتوكل مومن', 'quran', NULL, NULL, 'https://quran.com/58/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2252, 'انم الن لنج نجو جوي من الش لشي شيط يطن ليح يحز حزن الذ لذي ذين امن منو ولي ليس بضر ضره رهم شي ال بذن الل لله وعل علي الل لله فلي ليت يتو توك وكل الم لمو موم ومن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2253, 'quran:58:11', 'quran', 'quran', '58:11', 11, 2252, 'Al-Mujadila', 'المجادلة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', NULL, NULL, 'يا ايها الذين امنوا اذا قيل لكم تفسحوا في المجلس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجت والله بما تعملون خبير', 'ي اي ذين امن اذ قيل لكم تفسح في مجلس افسح يفسح له لكم اذ قيل انشز انشز يرفع له ذين امن من ذين اوت علم درجت له بم تعمل خبير', 'quran', NULL, NULL, 'https://quran.com/58/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2253, 'ي ايه الذ لذي ذين امن منو اذ قيل لكم تفس فسح سحو في الم لمج مجل جلس ففس فسح سحو يفس فسح الل لله لكم وذ قيل انش نشز شزو فنش نشز شزو يرف رفع الل لله الذ لذي ذين امن منو منك نكم ولذ لذي ذين اوت وتو الع لعل علم درج رجت ولل لله بم تعم عمل ملو لون خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2254, 'quran:58:12', 'quran', 'quran', '58:12', 12, 2253, 'Al-Mujadila', 'المجادلة', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَةٗۚ ذَٰلِكَ خَيۡرٞ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', NULL, NULL, 'يا ايها الذين امنوا اذا نجيتم الرسول فقدموا بين يدي نجواكم صدقه ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم', 'ي اي ذين امن اذ نجيتم رسول قدم بين يد نجو صدق ذلك خير لكم اطهر فن لم تجد فن له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/58/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2254, 'ي ايه الذ لذي ذين امن منو اذ نجي جيت يتم الر لرس رسو سول فقد قدم دمو بين يدي نجو جوك وكم صدق دقه ذلك خير لكم وطه طهر فن لم تجد جدو فن الل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2255, 'quran:58:13', 'quran', 'quran', '58:13', 13, 2254, 'Al-Mujadila', 'المجادلة', 'ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتٖۚ فَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ', NULL, NULL, 'اشفقتم ان تقدموا بين يدي نجواكم صدقت فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاه واتوا الزكاه واطيعوا الله ورسوله والله خبير بما تعملون', 'اشفقتم ان تقدم بين يد نجو صدقت فذ لم تفعل تب له علي اقيم صل ات زك اطيع له رسول له خبير بم تعمل', 'quran', NULL, NULL, 'https://quran.com/58/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2255, 'اشف شفق فقت قتم ان تقد قدم دمو بين يدي نجو جوك وكم صدق دقت فذ لم تفع فعل علو وتب الل لله علي ليك يكم فقي قيم يمو الص لصل صله وتو الز لزك زكه وطي طيع يعو الل لله ورس رسو سول وله ولل لله خبي بير بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2256, 'quran:58:14', 'quran', 'quran', '58:14', 14, 2255, 'Al-Mujadila', 'المجادلة', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ يَعۡلَمُونَ', NULL, NULL, 'الم تر الي الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون علي الكذب وهم يعلمون', 'الم تر ال ذين تول قوم غضب له علي م هم من ول من يحلف عل كذب وهم يعلم', 'quran', NULL, NULL, 'https://quran.com/58/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2256, 'الم تر الي الذ لذي ذين تول ولو قوم غضب الل لله علي ليه يهم م هم منك نكم ول منه نهم ويح يحل حلف لفو فون علي الك لكذ كذب وهم يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2257, 'quran:58:15', 'quran', 'quran', '58:15', 15, 2256, 'Al-Mujadila', 'المجادلة', 'أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ', NULL, NULL, 'اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون', 'اعد له لهم عذب شديد ان سء م كن يعمل', 'quran', NULL, NULL, 'https://quran.com/58/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2257, 'اعد الل لله لهم عذب شدي ديد انه نهم سء م كنو يعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2258, 'quran:58:16', 'quran', 'quran', '58:16', 16, 2257, 'Al-Mujadila', 'المجادلة', 'ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ عَذَابٞ مُّهِينٞ', NULL, NULL, 'اتخذوا ايمنهم جنه فصدوا عن سبيل الله فلهم عذاب مهين', 'اتخذ ايمن جن صد عن سبيل له لهم عذب مه', 'quran', NULL, NULL, 'https://quran.com/58/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2258, 'اتخ تخذ خذو ايم يمن منه نهم جنه فصد صدو عن سبي بيل الل لله فله لهم عذب مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2259, 'quran:58:17', 'quran', 'quran', '58:17', 17, 2258, 'Al-Mujadila', 'المجادلة', 'لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', NULL, NULL, 'لن تغني عنهم امولهم ولا اولدهم من الله شيا اوليك اصحب النار هم فيها خلدون', 'لن تغن عن امول ول اولد من له شي اوليك اصحب نر هم يه خلد', 'quran', NULL, NULL, 'https://quran.com/58/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2259, 'لن تغن غني عنه نهم امو مول وله لهم ول اول ولد لده دهم من الل لله شي اول ولي ليك اصح صحب الن لنر هم فيه خلد لدو دون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2260, 'quran:58:18', 'quran', 'quran', '58:18', 18, 2259, 'Al-Mujadila', 'المجادلة', 'يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ', NULL, NULL, 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم علي شيء الا انهم هم الكذبون', 'يوم يبعث له جميع يحلف له كم يحلف لكم يحسب ان عل شيء ال ان هم كذب', 'quran', NULL, NULL, 'https://quran.com/58/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2260, 'يوم يبع بعث عثه ثهم الل لله جمي ميع فيح يحل حلف لفو فون له كم يحل حلف لفو فون لكم ويح يحس حسب سبو بون انه نهم علي شيء ال انه نهم هم الك لكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2261, 'quran:58:19', 'quran', 'quran', '58:19', 19, 2260, 'Al-Mujadila', 'المجادلة', 'ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ', NULL, NULL, 'استحوذ عليهم الشيطن فانساهم ذكر الله اوليك حزب الشيطن الا ان حزب الشيطن هم الخسرون', 'استحوذ علي شيطن انس ذكر له اوليك حزب شيطن ال ان حزب شيطن هم خسر', 'quran', NULL, NULL, 'https://quran.com/58/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2261, 'است ستح تحو حوذ علي ليه يهم الش لشي شيط يطن فنس نسه سهم ذكر الل لله اول ولي ليك حزب الش لشي شيط يطن ال ان حزب الش لشي شيط يطن هم الخ لخس خسر سرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2262, 'quran:58:20', 'quran', 'quran', '58:20', 20, 2261, 'Al-Mujadila', 'المجادلة', 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ', NULL, NULL, 'ان الذين يحادون الله ورسوله اوليك في الاذلين', 'ان ذين يحد له رسول اوليك في اذل', 'quran', NULL, NULL, 'https://quran.com/58/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2262, 'ان الذ لذي ذين يحد حدو دون الل لله ورس رسو سول وله اول ولي ليك في الذ لذل ذلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2263, 'quran:58:21', 'quran', 'quran', '58:21', 21, 2262, 'Al-Mujadila', 'المجادلة', 'كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ', NULL, NULL, 'كتب الله لاغلبن انا ورسلي ان الله قوي عزيز', 'كتب له لغلبن ان رسل ان له قو عزيز', 'quran', NULL, NULL, 'https://quran.com/58/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2263, 'كتب الل لله لغل غلب لبن ان ورس رسل سلي ان الل لله قوي عزي زيز');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2264, 'quran:58:22', 'quran', 'quran', '58:22', 22, 2263, 'Al-Mujadila', 'المجادلة', 'لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحٖ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'لا تجد قوما يومنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباءهم او ابناءهم او اخونهم او عشيرتهم اوليك كتب في قلوبهم الايمن وايدهم بروح منه ويدخلهم جنت تجري من تحتها الانهر خلدين فيها ورضوا عنه اوليك حزب الله الا ان حزب الله هم المفلحون', 'ل تجد قوم يومن له يوم اخر يود من حد له رسول ولو كن ابء او ابنء او اخون او عشيرت اوليك كتب في قلوب ايمن ايد بروح من يدخل جنت تجر من تحت انهر خلد يه رض عن اوليك حزب له ال ان حزب له هم مفلح', 'quran', NULL, NULL, 'https://quran.com/58/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2264, 'ل تجد قوم يوم ومن منو نون بلل لله ولي ليو يوم الخ لخر يود ودو دون من حد الل لله ورس رسو سول وله ولو كنو ابء بءه ءهم او ابن بنء نءه ءهم او اخو خون ونه نهم او عشي شير يرت رته تهم اول ولي ليك كتب في قلو لوب وبه بهم الي ليم يمن ويد يده دهم برو روح منه ويد يدخ دخل خله لهم جنت تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ورض رضو عنه اول ولي ليك حزب الل لله ال ان حزب الل لله هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2265, 'quran:59:1', 'quran', 'quran', '59:1', 1, 2264, 'Al-Hashr', 'الحشر', 'سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'سبح لله ما في السموت وما في الارض وهو العزيز الحكيم', 'سبح لل م في سموت وم في ارض وهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/59/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2265, 'سبح لله م في الس لسم سمو موت وم في الر لرض وهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2266, 'quran:59:2', 'quran', 'quran', '59:2', 2, 2265, 'Al-Hashr', 'الحشر', 'هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ', NULL, NULL, 'هو الذي اخرج الذين كفروا من اهل الكتب من ديرهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتاهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المومنين فاعتبروا يا اولي الابصر', 'هو ذي اخرج ذين كفر من اهل كتب من دير لول حشر م ظننتم ان يخرج ظن ان منعت حصون من له ات له من حيث لم يحتسب قذف في قلوب رعب يخرب بيوت بيدي ايد مومن اعتبر ي اول ابصر', 'quran', NULL, NULL, 'https://quran.com/59/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2266, 'هو الذ لذي اخر خرج الذ لذي ذين كفر فرو من اهل الك لكت كتب من دير يره رهم لول الح لحش حشر م ظنن ننت نتم ان يخر خرج رجو وظن ظنو انه نهم منع نعت عته تهم حصو صون ونه نهم من الل لله فته تهم الل لله من حيث لم يحت حتس تسب سبو وقذ قذف في قلو لوب وبه بهم الر لرع رعب يخر خرب ربو بون بيو يوت وته تهم بيد يدي ديه يهم ويد يدي الم لمو موم ومن مني نين فعت عتب تبر برو ي اول ولي الب لبص بصر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2267, 'quran:59:3', 'quran', 'quran', '59:3', 3, 2266, 'Al-Hashr', 'الحشر', 'وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ', NULL, NULL, 'ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخره عذاب النار', 'لول ان كتب له علي جلء لعذب في دني لهم في اخر عذب نر', 'quran', NULL, NULL, 'https://quran.com/59/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2267, 'ولو لول ان كتب الل لله علي ليه يهم الج لجل جلء لعذ عذب ذبه بهم في الد لدن دني وله لهم في الخ لخر خره عذب الن لنر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2268, 'quran:59:4', 'quran', 'quran', '59:4', 4, 2267, 'Al-Hashr', 'الحشر', 'ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب', 'ذلك بن شق له رسول ومن يشق له فن له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/59/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2268, 'ذلك بنه نهم شقو الل لله ورس رسو سول وله ومن يشق الل لله فن الل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2269, 'quran:59:5', 'quran', 'quran', '59:5', 5, 2268, 'Al-Hashr', 'الحشر', 'مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ', NULL, NULL, 'ما قطعتم من لينه او تركتموها قايمه علي اصولها فباذن الله وليخزي الفسقين', 'م قطعتم من لين او تركتمو قيم عل اصول بذن له ليخز فسق', 'quran', NULL, NULL, 'https://quran.com/59/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2269, 'م قطع طعت عتم من لين ينه او ترك ركت كتم تمو موه قيم يمه علي اصو صول وله فبذ بذن الل لله ولي ليخ يخز خزي الف لفس فسق سقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2270, 'quran:59:6', 'quran', 'quran', '59:6', 6, 2269, 'Al-Hashr', 'الحشر', 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلٖ وَلَا رِكَابٖ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'وما افاء الله علي رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله علي من يشاء والله علي كل شيء قدير', 'وم افء له عل رسول من فم اوجفتم عل من خيل ول ركب لكن له يسلط رسل عل من يشء له عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/59/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2270, 'وم افء الل لله علي رسو سول وله منه نهم فم اوج وجف جفت فتم علي ليه من خيل ول ركب ولك لكن الل لله يسل سلط رسل سله علي من يشء ولل لله علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2271, 'quran:59:7', 'quran', 'quran', '59:7', 7, 2270, 'Al-Hashr', 'الحشر', 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', NULL, NULL, 'ما افاء الله علي رسوله من اهل القري فلله وللرسول ولذي القربي واليتمي والمسكين وابن السبيل كي لا يكون دوله بين الاغنياء منكم وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا واتقوا الله ان الله شديد العقاب', 'م افء له عل رسول من اهل قر لل رسول لذ قرب يتم مسك ابن سبيل كي ل يك دول بين اغنيء من وم ات رسول خذو وم نه عن انته اتق له ان له شديد عقب', 'quran', NULL, NULL, 'https://quran.com/59/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2271, 'م افء الل لله علي رسو سول وله من اهل الق لقر قري فلل لله ولل للر لرس رسو سول ولذ لذي الق لقر قرب ربي ولي ليت يتم تمي ولم لمس مسك سكي كين وبن الس لسب سبي بيل كي ل يكو كون دول وله بين الغ لغن غني نيء منك نكم وم اتك تكم الر لرس رسو سول فخذ خذو ذوه وم نهك هكم عنه فنت نته تهو وتق تقو الل لله ان الل لله شدي ديد الع لعق عقب');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2272, 'quran:59:8', 'quran', 'quran', '59:8', 8, 2271, 'Al-Hashr', 'الحشر', 'لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', NULL, NULL, 'للفقراء المهجرين الذين اخرجوا من ديرهم وامولهم يبتغون فضلا من الله ورضونا وينصرون الله ورسوله اوليك هم الصدقون', 'فقرء مهجر ذين اخرج من دير امول يبتغ ضل من له رضو ينصر له رسول اوليك هم صدق', 'quran', NULL, NULL, 'https://quran.com/59/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2272, 'للف لفق فقر قرء الم لمه مهج هجر جري رين الذ لذي ذين اخر خرج رجو من دير يره رهم ومو مول وله لهم يبت بتغ تغو غون فضل من الل لله ورض رضو ضون وين ينص نصر صرو رون الل لله ورس رسو سول وله اول ولي ليك هم الص لصد صدق دقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2273, 'quran:59:9', 'quran', 'quran', '59:9', 9, 2272, 'Al-Hashr', 'الحشر', 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', NULL, NULL, 'والذين تبوءو الدار والايمن من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجه مما اوتوا ويوثرون علي انفسهم ولو كان بهم خصاصه ومن يوق شح نفسه فاوليك هم المفلحون', 'ذين تبوءو در ايمن من قبل يحب من هجر يهم ول يجد في صدور حج مم اوت يوثر عل انفس ولو كن بهم خصص ومن يوق شح نفس اوليك هم مفلح', 'quran', NULL, NULL, 'https://quran.com/59/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2273, 'ولذ لذي ذين تبو بوء وءو الد لدر ولي ليم يمن من قبل بله لهم يحب حبو بون من هجر الي ليه يهم ول يجد جدو دون في صدو دور وره رهم حجه مم اوت وتو ويو يوث وثر ثرو رون علي انف نفس فسه سهم ولو كن بهم خصص صصه ومن يوق شح نفس فسه فول ولي ليك هم الم لمف مفل فلح لحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2274, 'quran:59:10', 'quran', 'quran', '59:10', 10, 2273, 'Al-Hashr', 'الحشر', 'وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ', NULL, NULL, 'والذين جاءو من بعدهم يقولون ربنا اغفر لنا ولاخوننا الذين سبقونا بالايمن ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك رءوف رحيم', 'ذين جءو من بعد يقول رب اغفر لن لخون ذين سبقو ايمن ول تجعل في قلوب غل ذين امن رب انك رءوف رحيم', 'quran', NULL, NULL, 'https://quran.com/59/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2274, 'ولذ لذي ذين جءو من بعد عده دهم يقو قول ولو لون ربن اغف غفر لن ولخ لخو خون ونن الذ لذي ذين سبق بقو قون بلي ليم يمن ول تجع جعل في قلو لوب وبن غل للذ لذي ذين امن منو ربن انك رءو ءوف رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2275, 'quran:59:11', 'quran', 'quran', '59:11', 11, 2274, 'Al-Hashr', 'الحشر', 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَدٗا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ', NULL, NULL, 'الم تر الي الذين نافقوا يقولون لاخونهم الذين كفروا من اهل الكتب لين اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكذبون', 'الم تر ال ذين نفق يقول لخون ذين كفر من اهل كتب لين اخرجتم لنخرجن مع ول نطيع يكم احد ابد ون قوتلتم لننصرن له يشهد ان لكذب', 'quran', NULL, NULL, 'https://quran.com/59/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2275, 'الم تر الي الذ لذي ذين نفق فقو يقو قول ولو لون لخو خون ونه نهم الذ لذي ذين كفر فرو من اهل الك لكت كتب لين اخر خرج رجت جتم لنخ نخر خرج رجن معك عكم ول نطي طيع فيك يكم احد ابد ون قوت وتل تلت لتم لنن ننص نصر صرن رنك نكم ولل لله يشه شهد انه نهم لكذ كذب ذبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2276, 'quran:59:12', 'quran', 'quran', '59:12', 12, 2275, 'Al-Hashr', 'الحشر', 'لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ وَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ', NULL, NULL, 'لين اخرجوا لا يخرجون معهم ولين قوتلوا لا ينصرونهم ولين نصروهم ليولن الادبر ثم لا ينصرون', 'لين اخرج ل يخرج مع لين قوتل ل ينصرون لين نصرو ليولن ادبر ثم ل ينصر', 'quran', NULL, NULL, 'https://quran.com/59/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2276, 'لين اخر خرج رجو ل يخر خرج رجو جون معه عهم ولي لين قوت وتل تلو ل ينص نصر صرو رون ونه نهم ولي لين نصر صرو روه وهم ليو يول ولن الد لدب دبر ثم ل ينص نصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2277, 'quran:59:13', 'quran', 'quran', '59:13', 13, 2276, 'Al-Hashr', 'الحشر', 'لَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ', NULL, NULL, 'لانتم اشد رهبه في صدورهم من الله ذلك بانهم قوم لا يفقهون', 'لنتم اشد رهب في صدور من له ذلك بن قوم ل يفقه', 'quran', NULL, NULL, 'https://quran.com/59/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2277, 'لنت نتم اشد رهب هبه في صدو دور وره رهم من الل لله ذلك بنه نهم قوم ل يفق فقه قهو هون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2278, 'quran:59:14', 'quran', 'quran', '59:14', 14, 2277, 'Al-Hashr', 'الحشر', 'لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرٗى مُّحَصَّنَةٍ أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ', NULL, NULL, 'لا يقتلونكم جميعا الا في قري محصنه او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتي ذلك بانهم قوم لا يعقلون', 'ل يقتلون جميع ال في قر محصن او من رء جدر بس بين شديد تحسب جميع قلوب شت ذلك بن قوم ل يعقل', 'quran', NULL, NULL, 'https://quran.com/59/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2278, 'ل يقت قتل تلو لون ونك نكم جمي ميع ال في قري محص حصن صنه او من ورء جدر بسه سهم بين ينه نهم شدي ديد تحس حسب سبه بهم جمي ميع وقل قلو لوب وبه بهم شتي ذلك بنه نهم قوم ل يعق عقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2279, 'quran:59:15', 'quran', 'quran', '59:15', 15, 2278, 'Al-Hashr', 'الحشر', 'كَمَثَلِ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبٗاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ', NULL, NULL, 'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم', 'كمثل ذين من قبل قريب ذق بل امر لهم عذب يم', 'quran', NULL, NULL, 'https://quran.com/59/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2279, 'كمث مثل الذ لذي ذين من قبل بله لهم قري ريب ذقو وبل امر مره رهم وله لهم عذب الي ليم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2280, 'quran:59:16', 'quran', 'quran', '59:16', 16, 2279, 'Al-Hashr', 'الحشر', 'كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيٓءٞ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ', NULL, NULL, 'كمثل الشيطن اذ قال للانسن اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العلمين', 'كمثل شيطن اذ قل انسن اكفر لم كفر قل ان بريء منك ان اخف له رب علم', 'quran', NULL, NULL, 'https://quran.com/59/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2280, 'كمث مثل الش لشي شيط يطن اذ قل للن لنس نسن اكف كفر فلم كفر قل اني بري ريء منك اني اخف الل لله رب الع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2281, 'quran:59:17', 'quran', 'quran', '59:17', 17, 2280, 'Al-Hashr', 'الحشر', 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ', NULL, NULL, 'فكان عقبتهما انهما في النار خلدين فيها وذلك جزوا الظلمين', 'كن عقبتهم انهم في نر خلد يه ذلك جز ظلم', 'quran', NULL, NULL, 'https://quran.com/59/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2281, 'فكن عقب قبت بته تهم انه نهم في الن لنر خلد لدي دين فيه وذل ذلك جزو الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2282, 'quran:59:18', 'quran', 'quran', '59:18', 18, 2281, 'Al-Hashr', 'الحشر', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ', NULL, NULL, 'يا ايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون', 'ي اي ذين امن اتق له لتنظر نفس م قدمت لغد اتق له ان له خبير بم تعمل', 'quran', NULL, NULL, 'https://quran.com/59/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2282, 'ي ايه الذ لذي ذين امن منو اتق تقو الل لله ولت لتن تنظ نظر نفس م قدم دمت لغد وتق تقو الل لله ان الل لله خبي بير بم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2283, 'quran:59:19', 'quran', 'quran', '59:19', 19, 2282, 'Al-Hashr', 'الحشر', 'وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', NULL, NULL, 'ولا تكونوا كالذين نسوا الله فانساهم انفسهم اوليك هم الفسقون', 'ول تكون ذين نس له انس انفس اوليك هم فسق', 'quran', NULL, NULL, 'https://quran.com/59/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2283, 'ول تكو كون ونو كلذ لذي ذين نسو الل لله فنس نسه سهم انف نفس فسه سهم اول ولي ليك هم الف لفس فسق سقو قون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2284, 'quran:59:20', 'quran', 'quran', '59:20', 20, 2283, 'Al-Hashr', 'الحشر', 'لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ أَصۡحَٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ', NULL, NULL, 'لا يستوي اصحب النار واصحب الجنه اصحب الجنه هم الفايزون', 'ل يستو اصحب نر اصحب جن اصحب جن هم فيز', 'quran', NULL, NULL, 'https://quran.com/59/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2284, 'ل يست ستو توي اصح صحب الن لنر وصح صحب الج لجن جنه اصح صحب الج لجن جنه هم الف لفي فيز يزو زون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2285, 'quran:59:21', 'quran', 'quran', '59:21', 21, 2284, 'Al-Hashr', 'الحشر', 'لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ', NULL, NULL, 'لو انزلنا هذا القران علي جبل لرايته خشعا متصدعا من خشيه الله وتلك الامثل نضربها للناس لعلهم يتفكرون', 'لو انزل هذ قر عل جبل لريت خشع متصدع من خش له تلك امثل نضرب نس لعل يتفكر', 'quran', NULL, NULL, 'https://quran.com/59/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2285, 'لو انز نزل زلن هذ الق لقر قرن علي جبل لري ريت يته خشع متص تصد صدع من خشي شيه الل لله وتل تلك الم لمث مثل نضر ضرب ربه للن لنس لعل عله لهم يتف تفك فكر كرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2286, 'quran:59:22', 'quran', 'quran', '59:22', 22, 2285, 'Al-Hashr', 'الحشر', 'هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ', NULL, NULL, 'هو الله الذي لا اله الا هو علم الغيب والشهده هو الرحمن الرحيم', 'هو له ذي ل ال ال هو علم غيب شهد هو رحمن رحيم', 'quran', NULL, NULL, 'https://quran.com/59/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2286, 'هو الل لله الذ لذي ل اله ال هو علم الغ لغي غيب ولش لشه شهد هده هو الر لرح رحم حمن الر لرح رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2287, 'quran:59:23', 'quran', 'quran', '59:23', 23, 2286, 'Al-Hashr', 'الحشر', 'هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ', NULL, NULL, 'هو الله الذي لا اله الا هو الملك القدوس السلم المومن المهيمن العزيز الجبار المتكبر سبحن الله عما يشركون', 'هو له ذي ل ال ال هو ملك قدوس سلم مومن مهيمن عزيز جبر متكبر سبحن له عم يشرك', 'quran', NULL, NULL, 'https://quran.com/59/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2287, 'هو الل لله الذ لذي ل اله ال هو الم لمل ملك الق لقد قدو دوس الس لسل سلم الم لمو موم ومن الم لمه مهي هيم يمن الع لعز عزي زيز الج لجب جبر الم لمت متك تكب كبر سبح بحن الل لله عم يشر شرك ركو كون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2288, 'quran:59:24', 'quran', 'quran', '59:24', 24, 2287, 'Al-Hashr', 'الحشر', 'هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', NULL, NULL, 'هو الله الخلق الباري المصور له الاسماء الحسني يسبح له ما في السموت والارض وهو العزيز الحكيم', 'هو له خلق بر مصور له اسمء حسن يسبح له م في سموت ارض وهو عزيز حكيم', 'quran', NULL, NULL, 'https://quran.com/59/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2288, 'هو الل لله الخ لخل خلق الب لبر بري الم لمص مصو صور له الس لسم سمء الح لحس حسن سني يسب سبح له م في الس لسم سمو موت ولر لرض وهو الع لعز عزي زيز الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2289, 'quran:66:1', 'quran', 'quran', '66:1', 1, 2288, 'At-Tahrim', 'التحريم', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', NULL, NULL, 'يا ايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازوجك والله غفور رحيم', 'ي اي نب لم تحرم م احل له لك تبتغ مرض ازوجك له غفور رحيم', 'quran', NULL, NULL, 'https://quran.com/66/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2289, 'ي ايه الن لنب نبي لم تحر حرم م احل الل لله لك تبت بتغ تغي مرض رضت ازو زوج وجك ولل لله غفو فور رحي حيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2290, 'quran:66:2', 'quran', 'quran', '66:2', 2, 2289, 'At-Tahrim', 'التحريم', 'قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', NULL, NULL, 'قد فرض الله لكم تحله ايمنكم والله مولاكم وهو العليم الحكيم', 'قد فرض له لكم تحل ايمن له مول وهو عليم حكيم', 'quran', NULL, NULL, 'https://quran.com/66/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2290, 'قد فرض الل لله لكم تحل حله ايم يمن منك نكم ولل لله مول ولك لكم وهو الع لعل علي ليم الح لحك حكي كيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2291, 'quran:66:3', 'quran', 'quran', '66:3', 3, 2290, 'At-Tahrim', 'التحريم', 'وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ', NULL, NULL, 'واذ اسر النبي الي بعض ازوجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير', 'وذ اسر نب ال بعض ازوج حديث لم نب به اظهر له عل عرف بعض اعرض عن بعض لم نب به قلت من انبك هذ قل نبن عليم خبير', 'quran', NULL, NULL, 'https://quran.com/66/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2291, 'وذ اسر الن لنب نبي الي بعض ازو زوج وجه حدي ديث فلم نبت به وظه ظهر هره الل لله علي ليه عرف بعض عضه وعر عرض عن بعض فلم نبه به قلت من انب نبك هذ قل نبن بني الع لعل علي ليم الخ لخب خبي بير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2292, 'quran:66:4', 'quran', 'quran', '66:4', 4, 2291, 'At-Tahrim', 'التحريم', 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ', NULL, NULL, 'ان تتوبا الي الله فقد صغت قلوبكما وان تظهرا عليه فان الله هو مولاه وجبريل وصلح المومنين والمليكه بعد ذلك ظهير', 'ان تتوب ال له فقد صغت قلوبكم ون تظهر عل فن له هو مول جبريل صلح مومن مليك بعد ذلك ظهير', 'quran', NULL, NULL, 'https://quran.com/66/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2292, 'ان تتو توب الي الل لله فقد صغت قلو لوب وبك بكم ون تظه ظهر علي ليه فن الل لله هو مول وله وجب جبر بري ريل وصل صلح الم لمو موم ومن مني نين ولم لمل ملي ليك يكه بعد ذلك ظهي هير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2293, 'quran:66:5', 'quran', 'quran', '66:5', 5, 2292, 'At-Tahrim', 'التحريم', 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا', NULL, NULL, 'عسي ربه ان طلقكن ان يبدله ازوجا خيرا منكن مسلمت مومنت قنتت تيبت عبدت سيحت ثيبت وابكارا', 'عس رب ان طلقكن ان يبدل ازوج خير منكن مسلمت مومنت قنتت تيبت عبدت سيحت ثيبت ابكر', 'quran', NULL, NULL, 'https://quran.com/66/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2293, 'عسي ربه ان طلق لقك قكن ان يبد بدل دله ازو زوج خير منك نكن مسل سلم لمت موم ومن منت قنت نتت تيب يبت عبد بدت سيح يحت ثيب يبت وبك بكر');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2294, 'quran:66:6', 'quran', 'quran', '66:6', 6, 2293, 'At-Tahrim', 'التحريم', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ', NULL, NULL, 'يا ايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجاره عليها مليكه غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يومرون', 'ي اي ذين امن قو انفس اهلي نر قود نس حجر علي مليك غلظ شدد ل يعص له م امر يفعل م يومر', 'quran', NULL, NULL, 'https://quran.com/66/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2294, 'ي ايه الذ لذي ذين امن منو قو انف نفس فسك سكم وهل هلي ليك يكم نر وقو قود وده الن لنس ولح لحج حجر جره علي ليه ملي ليك يكه غلظ شدد ل يعص عصو صون الل لله م امر مره رهم ويف يفع فعل علو لون م يوم ومر مرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2295, 'quran:66:7', 'quran', 'quran', '66:7', 7, 2294, 'At-Tahrim', 'التحريم', 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ', NULL, NULL, 'يا ايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون', 'ي اي ذين كفر ل تعتذر يوم انم تجز م كنتم تعمل', 'quran', NULL, NULL, 'https://quran.com/66/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2295, 'ي ايه الذ لذي ذين كفر فرو ل تعت عتذ تذر ذرو الي ليو يوم انم تجز جزو زون م كنت نتم تعم عمل ملو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2296, 'quran:66:8', 'quran', 'quran', '66:8', 8, 2295, 'At-Tahrim', 'التحريم', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', NULL, NULL, 'يا ايها الذين امنوا توبوا الي الله توبه نصوحا عسي ربكم ان يكفر عنكم سياتكم ويدخلكم جنت تجري من تحتها الانهر يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعي بين ايديهم وبايمنهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك علي كل شيء قدير', 'ي اي ذين امن توب ال له توب نصوح عس رب ان يكفر عن سيت يدخل جنت تجر من تحت انهر يوم ل يخز له نب ذين امن مع نور يسع بين ايدي بيمن يقول رب اتمم لن نور اغفر لن انك عل كل شيء قدير', 'quran', NULL, NULL, 'https://quran.com/66/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2296, 'ي ايه الذ لذي ذين امن منو توب وبو الي الل لله توب وبه نصو صوح عسي ربك بكم ان يكف كفر عنك نكم سيت يتك تكم ويد يدخ دخل خلك لكم جنت تجر جري من تحت حته الن لنه نهر يوم ل يخز خزي الل لله الن لنب نبي ولذ لذي ذين امن منو معه نور وره رهم يسع سعي بين ايد يدي ديه يهم وبي بيم يمن منه نهم يقو قول ولو لون ربن اتم تمم لن نور ورن وغف غفر لن انك علي كل شيء قدي دير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2297, 'quran:66:9', 'quran', 'quran', '66:9', 9, 2296, 'At-Tahrim', 'التحريم', 'يَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ', NULL, NULL, 'يا ايها النبي جهد الكفار والمنفقين واغلظ عليهم وماواهم جهنم وبيس المصير', 'ي اي نب جهد كفر منفق اغلظ علي مو جهنم بيس مصير', 'quran', NULL, NULL, 'https://quran.com/66/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2297, 'ي ايه الن لنب نبي جهد الك لكف كفر ولم لمن منف نفق فقي قين وغل غلظ علي ليه يهم ومو موه وهم جهن هنم وبي بيس الم لمص مصي صير');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2298, 'quran:66:10', 'quran', 'quran', '66:10', 10, 2297, 'At-Tahrim', 'التحريم', 'ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', NULL, NULL, 'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من الله شيا وقيل ادخلا النار مع الدخلين', 'ضرب له مثل ذين كفر امر نوح امر لوط كنت تحت عبد من عبد صلح خنتهم فلم يغني عنهم من له شي قيل ادخل نر مع دخل', 'quran', NULL, NULL, 'https://quran.com/66/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2298, 'ضرب الل لله مثل للذ لذي ذين كفر فرو امر مرت نوح ومر مرت لوط كنت تحت عبد بدي دين من عبد بدن صلح لحي حين فخن خنت نته تهم فلم يغن غني عنه نهم من الل لله شي وقي قيل ادخ دخل الن لنر مع الد لدخ دخل خلي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2299, 'quran:66:11', 'quran', 'quran', '66:11', 11, 2298, 'At-Tahrim', 'التحريم', 'وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ', NULL, NULL, 'وضرب الله مثلا للذين امنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنه ونجني من فرعون وعمله ونجني من القوم الظلمين', 'ضرب له مثل ذين امن امر رع اذ قلت رب ابن لي عندك بيت في جن نجن من رع عمل نجن من قوم ظلم', 'quran', NULL, NULL, 'https://quran.com/66/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2299, 'وضر ضرب الل لله مثل للذ لذي ذين امن منو امر مرت فرع رعو عون اذ قلت رب ابن لي عند ندك بيت في الج لجن جنه ونج نجن جني من فرع رعو عون وعم عمل مله ونج نجن جني من الق لقو قوم الظ لظل ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2300, 'quran:66:12', 'quran', 'quran', '66:12', 12, 2299, 'At-Tahrim', 'التحريم', 'وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ', NULL, NULL, 'ومريم ابنت عمرن التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من القنتين', 'مريم ابنت عمرن تي احصنت رج نفخ في من روح صدقت بكلمت رب كتب كنت من قنت', 'quran', NULL, NULL, 'https://quran.com/66/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2300, 'ومر مري ريم ابن بنت عمر مرن الت لتي احص حصن صنت فرج رجه فنف نفخ فخن فيه من روح وحن وصد صدق دقت بكل كلم لمت ربه وكت كتب تبه وكن كنت من الق لقن قنت نتي تين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2301, 'quran:68:1', 'quran', 'quran', '68:1', 1, 2300, 'Al-Qalam', 'القلم', 'نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ', NULL, NULL, 'ن والقلم وما يسطرون', 'ن قلم وم يسطر', 'quran', NULL, NULL, 'https://quran.com/68/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2301, 'ن ولق لقل قلم وم يسط سطر طرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2302, 'quran:68:2', 'quran', 'quran', '68:2', 2, 2301, 'Al-Qalam', 'القلم', 'مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونٖ', NULL, NULL, 'ما انت بنعمه ربك بمجنون', 'م انت بنعم ربك بمجن', 'quran', NULL, NULL, 'https://quran.com/68/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2302, 'م انت بنع نعم عمه ربك بمج مجن جنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2303, 'quran:68:3', 'quran', 'quran', '68:3', 3, 2302, 'Al-Qalam', 'القلم', 'وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونٖ', NULL, NULL, 'وان لك لاجرا غير ممنون', 'ون لك لجر غير ممن', 'quran', NULL, NULL, 'https://quran.com/68/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2303, 'ون لك لجر غير ممن منو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2304, 'quran:68:4', 'quran', 'quran', '68:4', 4, 2303, 'Al-Qalam', 'القلم', 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ', NULL, NULL, 'وانك لعلي خلق عظيم', 'انك لعل خلق عظيم', 'quran', NULL, NULL, 'https://quran.com/68/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2304, 'ونك لعل علي خلق عظي ظيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2305, 'quran:68:5', 'quran', 'quran', '68:5', 5, 2304, 'Al-Qalam', 'القلم', 'فَسَتُبۡصِرُ وَيُبۡصِرُونَ', NULL, NULL, 'فستبصر ويبصرون', 'ستبصر يبصر', 'quran', NULL, NULL, 'https://quran.com/68/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2305, 'فست ستب تبص بصر ويب يبص بصر صرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2306, 'quran:68:6', 'quran', 'quran', '68:6', 6, 2305, 'Al-Qalam', 'القلم', 'بِأَييِّكُمُ ٱلۡمَفۡتُونُ', NULL, NULL, 'باييكم المفتون', 'بيي مفت', 'quran', NULL, NULL, 'https://quran.com/68/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2306, 'بيي ييك يكم الم لمف مفت فتو تون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2307, 'quran:68:7', 'quran', 'quran', '68:7', 7, 2306, 'Al-Qalam', 'القلم', 'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ', NULL, NULL, 'ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين', 'ان ربك هو اعلم بمن ضل عن سبيل وهو اعلم مهتد', 'quran', NULL, NULL, 'https://quran.com/68/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2307, 'ان ربك هو اعل علم بمن ضل عن سبي بيل يله وهو اعل علم بلم لمه مهت هتد تدي دين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2308, 'quran:68:8', 'quran', 'quran', '68:8', 8, 2307, 'Al-Qalam', 'القلم', 'فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ', NULL, NULL, 'فلا تطع المكذبين', 'فل تطع مكذب', 'quran', NULL, NULL, 'https://quran.com/68/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2308, 'فل تطع الم لمك مكذ كذب ذبي بين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2309, 'quran:68:9', 'quran', 'quran', '68:9', 9, 2308, 'Al-Qalam', 'القلم', 'وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ', NULL, NULL, 'ودوا لو تدهن فيدهنون', 'دو لو تد يدهن', 'quran', NULL, NULL, 'https://quran.com/68/9');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2309, 'ودو لو تده دهن فيد يده دهن هنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2310, 'quran:68:10', 'quran', 'quran', '68:10', 10, 2309, 'Al-Qalam', 'القلم', 'وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ', NULL, NULL, 'ولا تطع كل حلاف مهين', 'ول تطع كل حلف مه', 'quran', NULL, NULL, 'https://quran.com/68/10');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2310, 'ول تطع كل حلف مهي هين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2311, 'quran:68:11', 'quran', 'quran', '68:11', 11, 2310, 'Al-Qalam', 'القلم', 'هَمَّازٖ مَّشَّآءِۭ بِنَمِيمٖ', NULL, NULL, 'هماز مشاء بنميم', 'همز مشء بنميم', 'quran', NULL, NULL, 'https://quran.com/68/11');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2311, 'همز مشء بنم نمي ميم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2312, 'quran:68:12', 'quran', 'quran', '68:12', 12, 2311, 'Al-Qalam', 'القلم', 'مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ', NULL, NULL, 'مناع للخير معتد اثيم', 'منع خير معتد اثيم', 'quran', NULL, NULL, 'https://quran.com/68/12');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2312, 'منع للخ لخي خير معت عتد اثي ثيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2313, 'quran:68:13', 'quran', 'quran', '68:13', 13, 2312, 'Al-Qalam', 'القلم', 'عُتُلِّۭ بَعۡدَ ذَٰلِكَ زَنِيمٍ', NULL, NULL, 'عتل بعد ذلك زنيم', 'عتل بعد ذلك زنيم', 'quran', NULL, NULL, 'https://quran.com/68/13');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2313, 'عتل بعد ذلك زني نيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2314, 'quran:68:14', 'quran', 'quran', '68:14', 14, 2313, 'Al-Qalam', 'القلم', 'أَن كَانَ ذَا مَالٖ وَبَنِينَ', NULL, NULL, 'ان كان ذا مال وبنين', 'ان كن ذ مل بن', 'quran', NULL, NULL, 'https://quran.com/68/14');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2314, 'ان كن ذ مل وبن بني نين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2315, 'quran:68:15', 'quran', 'quran', '68:15', 15, 2314, 'Al-Qalam', 'القلم', 'إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', NULL, NULL, 'اذا تتلي عليه ايتنا قال اسطير الاولين', 'اذ تتل عل ايت قل اسطير اول', 'quran', NULL, NULL, 'https://quran.com/68/15');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2315, 'اذ تتل تلي علي ليه ايت يتن قل اسط سطي طير الو لول ولي لين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2316, 'quran:68:16', 'quran', 'quran', '68:16', 16, 2315, 'Al-Qalam', 'القلم', 'سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ', NULL, NULL, 'سنسمه علي الخرطوم', 'سنسم عل خرطوم', 'quran', NULL, NULL, 'https://quran.com/68/16');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2316, 'سنس نسم سمه علي الخ لخر خرط رطو طوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2317, 'quran:68:17', 'quran', 'quran', '68:17', 17, 2316, 'Al-Qalam', 'القلم', 'إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ', NULL, NULL, 'انا بلونهم كما بلونا اصحب الجنه اذ اقسموا ليصرمنها مصبحين', 'ان بلون كم بلو اصحب جن اذ اقسم ليصرمن مصبح', 'quran', NULL, NULL, 'https://quran.com/68/17');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2317, 'ان بلو لون ونه نهم كم بلو لون اصح صحب الج لجن جنه اذ اقس قسم سمو ليص يصر صرم رمن منه مصب صبح بحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2318, 'quran:68:18', 'quran', 'quran', '68:18', 18, 2317, 'Al-Qalam', 'القلم', 'وَلَا يَسۡتَثۡنُونَ', NULL, NULL, 'ولا يستثنون', 'ول يستثن', 'quran', NULL, NULL, 'https://quran.com/68/18');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2318, 'ول يست ستث تثن ثنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2319, 'quran:68:19', 'quran', 'quran', '68:19', 19, 2318, 'Al-Qalam', 'القلم', 'فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ', NULL, NULL, 'فطاف عليها طايف من ربك وهم نايمون', 'طف علي طيف من ربك وهم نيم', 'quran', NULL, NULL, 'https://quran.com/68/19');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2319, 'فطف علي ليه طيف من ربك وهم نيم يمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2320, 'quran:68:20', 'quran', 'quran', '68:20', 20, 2319, 'Al-Qalam', 'القلم', 'فَأَصۡبَحَتۡ كَٱلصَّرِيمِ', NULL, NULL, 'فاصبحت كالصريم', 'اصبحت صريم', 'quran', NULL, NULL, 'https://quran.com/68/20');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2320, 'فصب صبح بحت كلص لصر صري ريم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2321, 'quran:68:21', 'quran', 'quran', '68:21', 21, 2320, 'Al-Qalam', 'القلم', 'فَتَنَادَوۡاْ مُصۡبِحِينَ', NULL, NULL, 'فتنادوا مصبحين', 'تند مصبح', 'quran', NULL, NULL, 'https://quran.com/68/21');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2321, 'فتن تند ندو مصب صبح بحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2322, 'quran:68:22', 'quran', 'quran', '68:22', 22, 2321, 'Al-Qalam', 'القلم', 'أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ', NULL, NULL, 'ان اغدوا علي حرثكم ان كنتم صرمين', 'ان اغد عل حرث ان كنتم صرم', 'quran', NULL, NULL, 'https://quran.com/68/22');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2322, 'ان اغد غدو علي حرث رثك ثكم ان كنت نتم صرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2323, 'quran:68:23', 'quran', 'quran', '68:23', 23, 2322, 'Al-Qalam', 'القلم', 'فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ', NULL, NULL, 'فانطلقوا وهم يتخفتون', 'انطلق وهم يتخفت', 'quran', NULL, NULL, 'https://quran.com/68/23');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2323, 'فنط نطل طلق لقو وهم يتخ تخف خفت فتو تون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2324, 'quran:68:24', 'quran', 'quran', '68:24', 24, 2323, 'Al-Qalam', 'القلم', 'أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ', NULL, NULL, 'ان لا يدخلنها اليوم عليكم مسكين', 'ان ل يدخلن يوم علي مسك', 'quran', NULL, NULL, 'https://quran.com/68/24');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2324, 'ان ل يدخ دخل خلن لنه الي ليو يوم علي ليك يكم مسك سكي كين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2325, 'quran:68:25', 'quran', 'quran', '68:25', 25, 2324, 'Al-Qalam', 'القلم', 'وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ', NULL, NULL, 'وغدوا علي حرد قدرين', 'غد عل حرد قدر', 'quran', NULL, NULL, 'https://quran.com/68/25');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2325, 'وغد غدو علي حرد قدر دري رين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2326, 'quran:68:26', 'quran', 'quran', '68:26', 26, 2325, 'Al-Qalam', 'القلم', 'فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ', NULL, NULL, 'فلما راوها قالوا انا لضالون', 'لم رو قل ان لضل', 'quran', NULL, NULL, 'https://quran.com/68/26');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2326, 'فلم روه قلو ان لضل ضلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2327, 'quran:68:27', 'quran', 'quran', '68:27', 27, 2326, 'Al-Qalam', 'القلم', 'بَلۡ نَحۡنُ مَحۡرُومُونَ', NULL, NULL, 'بل نحن محرومون', 'بل نحن محروم', 'quran', NULL, NULL, 'https://quran.com/68/27');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2327, 'بل نحن محر حرو روم ومو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2328, 'quran:68:28', 'quran', 'quran', '68:28', 28, 2327, 'Al-Qalam', 'القلم', 'قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ', NULL, NULL, 'قال اوسطهم الم اقل لكم لولا تسبحون', 'قل اوسط الم اقل لكم لول تسبح', 'quran', NULL, NULL, 'https://quran.com/68/28');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2328, 'قل اوس وسط سطه طهم الم اقل لكم لول تسب سبح بحو حون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2329, 'quran:68:29', 'quran', 'quran', '68:29', 29, 2328, 'Al-Qalam', 'القلم', 'قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', NULL, NULL, 'قالوا سبحن ربنا انا كنا ظلمين', 'قل سبحن رب ان كن ظلم', 'quran', NULL, NULL, 'https://quran.com/68/29');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2329, 'قلو سبح بحن ربن ان كن ظلم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2330, 'quran:68:30', 'quran', 'quran', '68:30', 30, 2329, 'Al-Qalam', 'القلم', 'فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ', NULL, NULL, 'فاقبل بعضهم علي بعض يتلومون', 'اقبل بعض عل بعض يتلوم', 'quran', NULL, NULL, 'https://quran.com/68/30');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2330, 'فقب قبل بعض عضه ضهم علي بعض يتل تلو لوم ومو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2331, 'quran:68:31', 'quran', 'quran', '68:31', 31, 2330, 'Al-Qalam', 'القلم', 'قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ', NULL, NULL, 'قالوا يا ويلنا انا كنا طغين', 'قل ي يل ان كن طغ', 'quran', NULL, NULL, 'https://quran.com/68/31');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2331, 'قلو ي ويل يلن ان كن طغي غين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2332, 'quran:68:32', 'quran', 'quran', '68:32', 32, 2331, 'Al-Qalam', 'القلم', 'عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', NULL, NULL, 'عسي ربنا ان يبدلنا خيرا منها انا الي ربنا رغبون', 'عس رب ان يبدل خير من ان ال رب رغب', 'quran', NULL, NULL, 'https://quran.com/68/32');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2332, 'عسي ربن ان يبد بدل دلن خير منه ان الي ربن رغب غبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2333, 'quran:68:33', 'quran', 'quran', '68:33', 33, 2332, 'Al-Qalam', 'القلم', 'كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ', NULL, NULL, 'كذلك العذاب ولعذاب الاخره اكبر لو كانوا يعلمون', 'كذلك عذب لعذب اخر اكبر لو كن يعلم', 'quran', NULL, NULL, 'https://quran.com/68/33');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2333, 'كذل ذلك الع لعذ عذب ولع لعذ عذب الخ لخر خره اكب كبر لو كنو يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2334, 'quran:68:34', 'quran', 'quran', '68:34', 34, 2333, 'Al-Qalam', 'القلم', 'إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّٰتِ ٱلنَّعِيمِ', NULL, NULL, 'ان للمتقين عند ربهم جنت النعيم', 'ان متق عند رب جنت نعيم', 'quran', NULL, NULL, 'https://quran.com/68/34');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2334, 'ان للم لمت متق تقي قين عند ربه بهم جنت الن لنع نعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2335, 'quran:68:35', 'quran', 'quran', '68:35', 35, 2334, 'Al-Qalam', 'القلم', 'أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ', NULL, NULL, 'افنجعل المسلمين كالمجرمين', 'افنجعل مسلم مجرم', 'quran', NULL, NULL, 'https://quran.com/68/35');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2335, 'افن فنج نجع جعل الم لمس مسل سلم لمي مين كلم لمج مجر جرم رمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2336, 'quran:68:36', 'quran', 'quran', '68:36', 36, 2335, 'Al-Qalam', 'القلم', 'مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ', NULL, NULL, 'ما لكم كيف تحكمون', 'م لكم كيف تحكم', 'quran', NULL, NULL, 'https://quran.com/68/36');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2336, 'م لكم كيف تحك حكم كمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2337, 'quran:68:37', 'quran', 'quran', '68:37', 37, 2336, 'Al-Qalam', 'القلم', 'أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ', NULL, NULL, 'ام لكم كتب فيه تدرسون', 'ام لكم كتب في تدرس', 'quran', NULL, NULL, 'https://quran.com/68/37');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2337, 'ام لكم كتب فيه تدر درس رسو سون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2338, 'quran:68:38', 'quran', 'quran', '68:38', 38, 2337, 'Al-Qalam', 'القلم', 'إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ', NULL, NULL, 'ان لكم فيه لما تخيرون', 'ان لكم في لم تخير', 'quran', NULL, NULL, 'https://quran.com/68/38');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2338, 'ان لكم فيه لم تخي خير يرو رون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2339, 'quran:68:39', 'quran', 'quran', '68:39', 39, 2338, 'Al-Qalam', 'القلم', 'أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ', NULL, NULL, 'ام لكم ايمن علينا بلغه الي يوم القيمه ان لكم لما تحكمون', 'ام لكم ايمن علي بلغ ال يوم قيم ان لكم لم تحكم', 'quran', NULL, NULL, 'https://quran.com/68/39');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2339, 'ام لكم ايم يمن علي لين بلغ لغه الي يوم الق لقي قيم يمه ان لكم لم تحك حكم كمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2340, 'quran:68:40', 'quran', 'quran', '68:40', 40, 2339, 'Al-Qalam', 'القلم', 'سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', NULL, NULL, 'سلهم ايهم بذلك زعيم', 'سل اي بذلك زعيم', 'quran', NULL, NULL, 'https://quran.com/68/40');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2340, 'سله لهم ايه يهم بذل ذلك زعي عيم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2341, 'quran:68:41', 'quran', 'quran', '68:41', 41, 2340, 'Al-Qalam', 'القلم', 'أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ', NULL, NULL, 'ام لهم شركاء فلياتوا بشركايهم ان كانوا صدقين', 'ام لهم شركء ليت بشركي ان كن صدق', 'quran', NULL, NULL, 'https://quran.com/68/41');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2341, 'ام لهم شرك ركء فلي ليت يتو بشر شرك ركي كيه يهم ان كنو صدق دقي قين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2342, 'quran:68:42', 'quran', 'quran', '68:42', 42, 2341, 'Al-Qalam', 'القلم', 'يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ', NULL, NULL, 'يوم يكشف عن ساق ويدعون الي السجود فلا يستطيعون', 'يوم يكشف عن سق يدع ال سجود فل يستطيع', 'quran', NULL, NULL, 'https://quran.com/68/42');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2342, 'يوم يكش كشف عن سق ويد يدع دعو عون الي الس لسج سجو جود فل يست ستط تطي طيع يعو عون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2343, 'quran:68:43', 'quran', 'quran', '68:43', 43, 2342, 'Al-Qalam', 'القلم', 'خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ', NULL, NULL, 'خشعه ابصرهم ترهقهم ذله وقد كانوا يدعون الي السجود وهم سلمون', 'خشع ابصر ترهق ذل وقد كن يدع ال سجود وهم سلم', 'quran', NULL, NULL, 'https://quran.com/68/43');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2343, 'خشع شعه ابص بصر صره رهم تره رهق هقه قهم ذله وقد كنو يدع دعو عون الي الس لسج سجو جود وهم سلم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2344, 'quran:68:44', 'quran', 'quran', '68:44', 44, 2343, 'Al-Qalam', 'القلم', 'فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ', NULL, NULL, 'فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون', 'ذرن ومن يكذب بهذ حديث سنستدرج من حيث ل يعلم', 'quran', NULL, NULL, 'https://quran.com/68/44');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2344, 'فذر ذرن رني ومن يكذ كذب بهذ الح لحد حدي ديث سنس نست ستد تدر درج رجه جهم من حيث ل يعل علم لمو مون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2345, 'quran:68:45', 'quran', 'quran', '68:45', 45, 2344, 'Al-Qalam', 'القلم', 'وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ', NULL, NULL, 'واملي لهم ان كيدي متين', 'امل لهم ان كيد مت', 'quran', NULL, NULL, 'https://quran.com/68/45');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2345, 'ومل ملي لهم ان كيد يدي متي تين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2346, 'quran:68:46', 'quran', 'quran', '68:46', 46, 2345, 'Al-Qalam', 'القلم', 'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ', NULL, NULL, 'ام تسلهم اجرا فهم من مغرم مثقلون', 'ام تسل اجر فهم من مغرم مثقل', 'quran', NULL, NULL, 'https://quran.com/68/46');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2346, 'ام تسل سله لهم اجر فهم من مغر غرم مثق ثقل قلو لون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2347, 'quran:68:47', 'quran', 'quran', '68:47', 47, 2346, 'Al-Qalam', 'القلم', 'أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ', NULL, NULL, 'ام عندهم الغيب فهم يكتبون', 'ام عند غيب فهم يكتب', 'quran', NULL, NULL, 'https://quran.com/68/47');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2347, 'ام عند نده دهم الغ لغي غيب فهم يكت كتب تبو بون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2348, 'quran:68:48', 'quran', 'quran', '68:48', 48, 2347, 'Al-Qalam', 'القلم', 'فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ', NULL, NULL, 'فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادي وهو مكظوم', 'اصبر لح ربك ول تكن كصحب حوت اذ ند وهو مكظوم', 'quran', NULL, NULL, 'https://quran.com/68/48');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2348, 'فصب صبر لحك حكم ربك ول تكن كصح صحب الح لحو حوت اذ ندي وهو مكظ كظو ظوم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2349, 'quran:68:49', 'quran', 'quran', '68:49', 49, 2348, 'Al-Qalam', 'القلم', 'لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ', NULL, NULL, 'لولا ان تدركه نعمه من ربه لنبذ بالعراء وهو مذموم', 'لول ان تدرك نعم من رب لنبذ عرء وهو مذموم', 'quran', NULL, NULL, 'https://quran.com/68/49');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2349, 'لول ان تدر درك ركه نعم عمه من ربه لنب نبذ بلع لعر عرء وهو مذم ذمو موم');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2350, 'quran:68:50', 'quran', 'quran', '68:50', 50, 2349, 'Al-Qalam', 'القلم', 'فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', NULL, NULL, 'فاجتبه ربه فجعله من الصلحين', 'اجتب رب جعل من صلح', 'quran', NULL, NULL, 'https://quran.com/68/50');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2350, 'فجت جتب تبه ربه فجع جعل عله من الص لصل صلح لحي حين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2351, 'quran:68:51', 'quran', 'quran', '68:51', 51, 2350, 'Al-Qalam', 'القلم', 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ', NULL, NULL, 'وان يكاد الذين كفروا ليزلقونك بابصرهم لما سمعوا الذكر ويقولون انه لمجنون', 'ون يكد ذين كفر ليزلقونك ببصر لم سمع ذكر يقول ان لمجن', 'quran', NULL, NULL, 'https://quran.com/68/51');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2351, 'ون يكد الذ لذي ذين كفر فرو ليز يزل زلق لقو قون ونك ببص بصر صره رهم لم سمع معو الذ لذك ذكر ويق يقو قول ولو لون انه لمج مجن جنو نون');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2352, 'quran:68:52', 'quran', 'quran', '68:52', 52, 2351, 'Al-Qalam', 'القلم', 'وَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ', NULL, NULL, 'وما هو الا ذكر للعلمين', 'وم هو ال ذكر علم', 'quran', NULL, NULL, 'https://quran.com/68/52');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2352, 'وم هو ال ذكر للع لعل علم لمي مين');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2353, 'quran:98:1', 'quran', 'quran', '98:1', 1, 2352, 'Al-Bayyinah', 'البينة', 'لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ', NULL, NULL, 'لم يكن الذين كفروا من اهل الكتب والمشركين منفكين حتي تاتيهم البينه', 'لم يكن ذين كفر من اهل كتب مشرك منفك حت تتي بين', 'quran', NULL, NULL, 'https://quran.com/98/1');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2353, 'لم يكن الذ لذي ذين كفر فرو من اهل الك لكت كتب ولم لمش مشر شرك ركي كين منف نفك فكي كين حتي تتي تيه يهم الب لبي بين ينه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2354, 'quran:98:2', 'quran', 'quran', '98:2', 2, 2353, 'Al-Bayyinah', 'البينة', 'رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ', NULL, NULL, 'رسول من الله يتلوا صحفا مطهره', 'رسول من له يتل صحف مطهر', 'quran', NULL, NULL, 'https://quran.com/98/2');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2354, 'رسو سول من الل لله يتل تلو صحف مطه طهر هره');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2355, 'quran:98:3', 'quran', 'quran', '98:3', 3, 2354, 'Al-Bayyinah', 'البينة', 'فِيهَا كُتُبٞ قَيِّمَةٞ', NULL, NULL, 'فيها كتب قيمه', 'يه كتب قيم', 'quran', NULL, NULL, 'https://quran.com/98/3');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2355, 'فيه كتب قيم يمه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2356, 'quran:98:4', 'quran', 'quran', '98:4', 4, 2355, 'Al-Bayyinah', 'البينة', 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ', NULL, NULL, 'وما تفرق الذين اوتوا الكتب الا من بعد ما جاءتهم البينه', 'وم تفرق ذين اوت كتب ال من بعد م جءت بين', 'quran', NULL, NULL, 'https://quran.com/98/4');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2356, 'وم تفر فرق الذ لذي ذين اوت وتو الك لكت كتب ال من بعد م جءت ءته تهم الب لبي بين ينه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2357, 'quran:98:5', 'quran', 'quran', '98:5', 5, 2356, 'Al-Bayyinah', 'البينة', 'وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ', NULL, NULL, 'وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاه ويوتوا الزكاه وذلك دين القيمه', 'وم امر ال ليعبد له مخلص له دين حنفء يقيم صل يوت زك ذلك دين قيم', 'quran', NULL, NULL, 'https://quran.com/98/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2357, 'وم امر مرو ال ليع يعب عبد بدو الل لله مخل خلص لصي صين له الد لدي دين حنف نفء ويق يقي قيم يمو الص لصل صله ويو يوت وتو الز لزك زكه وذل ذلك دين الق لقي قيم يمه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2358, 'quran:98:6', 'quran', 'quran', '98:6', 6, 2357, 'Al-Bayyinah', 'البينة', 'إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ', NULL, NULL, 'ان الذين كفروا من اهل الكتب والمشركين في نار جهنم خلدين فيها اوليك هم شر البريه', 'ان ذين كفر من اهل كتب مشرك في نر جهنم خلد يه اوليك هم شر بر', 'quran', NULL, NULL, 'https://quran.com/98/6');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2358, 'ان الذ لذي ذين كفر فرو من اهل الك لكت كتب ولم لمش مشر شرك ركي كين في نر جهن هنم خلد لدي دين فيه اول ولي ليك هم شر الب لبر بري ريه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2359, 'quran:98:7', 'quran', 'quran', '98:7', 7, 2358, 'Al-Bayyinah', 'البينة', 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ', NULL, NULL, 'ان الذين امنوا وعملوا الصلحت اوليك هم خير البريه', 'ان ذين امن عمل صلحت اوليك هم خير بر', 'quran', NULL, NULL, 'https://quran.com/98/7');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2359, 'ان الذ لذي ذين امن منو وعم عمل ملو الص لصل صلح لحت اول ولي ليك هم خير الب لبر بري ريه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2360, 'quran:98:8', 'quran', 'quran', '98:8', 8, 2359, 'Al-Bayyinah', 'البينة', 'جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ', NULL, NULL, 'جزاوهم عند ربهم جنت عدن تجري من تحتها الانهر خلدين فيها ابدا ورضوا عنه ذلك لمن خشي ربه', 'جزو عند رب جنت عدن تجر من تحت انهر خلد يه ابد رض عن ذلك لمن خش رب', 'quran', NULL, NULL, 'https://quran.com/98/8');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2360, 'جزو زوه وهم عند ربه بهم جنت عدن تجر جري من تحت حته الن لنه نهر خلد لدي دين فيه ابد ورض رضو عنه ذلك لمن خشي ربه');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2361, 'quran:112:1', 'quran', 'quran', '112:1', 1, 2360, 'Al-Ikhlas', 'الإخلاص', 'قُلۡ هُوَ ٱللَّهُ أَحَدٌ', NULL, NULL, 'قل هو الله احد', 'قل هو له احد', 'quran', NULL, NULL, 'https://quran.com/112/1');
