INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2364, 'quran:112:4', 'quran', 'quran', '112:4', 4, 2363, 'Al-Ikhlas', 'الإخلاص', 'وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ', NULL, NULL, 'ولم يكن له كفوا احد', 'ولم يكن له كف احد', 'quran', NULL, NULL, 'https://quran.com/112/4');
