INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2373, 'quran:114:4', 'quran', 'quran', '114:4', 4, 2372, 'An-Nas', 'الناس', 'مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ', NULL, NULL, 'من شر الوسواس الخناس', 'من شر وسوس خنس', 'quran', NULL, NULL, 'https://quran.com/114/4');
