INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2374, 'quran:114:5', 'quran', 'quran', '114:5', 5, 2373, 'An-Nas', 'الناس', 'ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ', NULL, NULL, 'الذي يوسوس في صدور الناس', 'ذي يوسوس في صدور نس', 'quran', NULL, NULL, 'https://quran.com/114/5');
INSERT INTO units_tri_src (id, ar_tri) VALUES (2374, 'الذ لذي يوس وسو سوس في صدو دور الن لنس');
INSERT INTO units (id, key, kind, collection, number, number_base, ord, chapter_en, chapter_ar, ar_matn, en_text, id_text, ar_norm, ar_stem, grade_status, grades_json, parallel_of, url) VALUES (2375, 'quran:114:6', 'quran', 'quran', '114:6', 6, 2374, 'An-Nas', 'الناس', 'مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ', NULL, NULL, 'من الجنه والناس', 'من جن نس', 'quran', NULL, NULL, 'https://quran.com/114/6');
